// Hyperreal Stepped Lozenge Pyramid of Hand-Dyed Wool Skeins
// Kilim logic: hard stepped diagonals, saw-tooth edges, strict bilateral balance, warm dry light

const PALETTES = {
  MADDER: {
    name: "MADDER",
    wash: ["#a83523", "#bc422d", "#942a1b"],
    deep: "#3d0f0b",
    dark: "#661b14",
    midDark: "#8c271d",
    mid: "#b33927",
    midLight: "#cc4e38",
    light: "#de6b52",
    highlight: "#f0977d",
    abrashCool: "#962925",
    abrashWarm: "#d45937"
  },
  INDIGO: {
    name: "INDIGO",
    wash: ["#293b54", "#354b69", "#1f2e42"],
    deep: "#0f1621",
    dark: "#192436",
    midDark: "#25364f",
    mid: "#354c6b",
    midLight: "#496487",
    light: "#6480a3",
    highlight: "#94acc7",
    abrashCool: "#223859",
    abrashWarm: "#4f6d8a"
  },
  WELD: {
    name: "WELD",
    wash: ["#cfa02c", "#deb038", "#b8891f"],
    deep: "#4f360b",
    dark: "#785312",
    midDark: "#a1721b",
    mid: "#c99427",
    midLight: "#e0ae38",
    light: "#f0c959",
    highlight: "#fae391",
    abrashCool: "#b58621",
    abrashWarm: "#e8bb43"
  },
  WALNUT: {
    name: "WALNUT",
    wash: ["#5e3f27", "#704c30", "#4d321e"],
    deep: "#1f130b",
    dark: "#362214",
    midDark: "#4f331f",
    mid: "#6b472d",
    midLight: "#875d3d",
    light: "#a67956",
    highlight: "#c79e7b",
    abrashCool: "#543927",
    abrashWarm: "#825634"
  },
  CREAM: {
    name: "CREAM",
    wash: ["#dfd0b6", "#e8dac2", "#cfbda0"],
    deep: "#5e4c36",
    dark: "#806a4f",
    midDark: "#a38b6d",
    mid: "#c4ae8f",
    midLight: "#dcc9ad",
    light: "#eee0ca",
    highlight: "#fcf7ed",
    abrashCool: "#ccb89b",
    abrashWarm: "#e8d6b7"
  }
};

const CX = 600;
const NUM_TIERS = 21;     // r = 0 (bottom base) .. 20 (top apex)
const EQUATOR_R = 7;      // widest tier of the stepped lozenge
const MAX_H = 13;         // half-width at equator in modules (total width = 27 modules)
const MOD_W = 40;         // width of 1 step module in px (27 * 40 = 1080 px at equator)
const TIER_H = 44;        // height of 1 stacked skein tier in px (21 * 44 = 924 px tall)
const TOP_Y = 130;        // top of apex tier (r = 20)
const BASE_Y = TOP_Y + NUM_TIERS * TIER_H; // y = 1054 (plinth horizon line)

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // Base warm dry plaster & raw linen ground
  background("#ece0c8");

  // 1. Render dry warm background & stone weaver's plinth
  drawWarmDryGround();

  // 2. Build the complete bilaterally symmetric stepped lozenge pyramid data
  const tiers = buildPyramidStructure();

  // 3. Render symmetrical stepped cast shadows on background & plinth
  drawSteppedShadows(tiers);

  // 4. Batch watercolor / dry pigment base washes for all skeins by color family
  drawBatchedSkeinWashes(tiers);

  // 5. Render hyperreal twisted wool hanks: faceted lobes, dye mottling,
  //    dense directional crimped fibres, saw-tooth joins, binding ties & stray hairs
  drawAllWoolTiers(tiers);

  noLoop();
}

// ============================================================================
// DETERMINISTIC SYMMETRIC HELPERS
// ============================================================================

function hash01(a, b, c = 0) {
  let n = Math.sin(a * 127.1 + b * 311.7 + c * 74.7) * 43758.5453123;
  return n - Math.floor(n);
}

function lerpPt(p1, p2, t) {
  return [p1[0] + (p2[0] - p1[0]) * t, p1[1] + (p2[1] - p1[1]) * t];
}

function bilerpQuad(TL, TR, BR, BL, u, v) {
  const top = lerpPt(TL, TR, u);
  const bot = lerpPt(BL, BR, u);
  return lerpPt(top, bot, v);
}

function drawStraightPoly(pts) {
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function tierHalfModules(r) {
  return MAX_H - Math.abs(r - EQUATOR_R);
}

function tierTopY(r) {
  return TOP_Y + (NUM_TIERS - 1 - r) * TIER_H;
}

// ============================================================================
// KILIM COLOR LOGIC (STRICT BILATERAL SYMMETRY & STEPPED LOZENGES)
// ============================================================================

function getModuleColor(r, m) {
  const dm = Math.abs(m);
  const dr = Math.abs(r - EQUATOR_R);
  const D = dr + dm; // Manhattan distance from lozenge center (r = 7, m = 0)

  // Foundation base row (r = 0) woven border logic
  if (r === 0) {
    if (dm === 6) return "WALNUT";
    if (dm === 5) return "CREAM";
    if (dm === 4) return "MADDER";
    if (dm === 3) return "WELD";
    if (dm === 2) return "INDIGO";
    if (dm === 1) return "CREAM";
    return "WALNUT";
  }

  // Outer stepped perimeter (D === 13)
  if (D === 13) {
    if (r === 20 || r === 7 || r === 14) return "MADDER";
    if (r % 3 === 1) return "MADDER";
    return "WALNUT";
  }

  // High-contrast undyed cream stepped guard band (D === 12)
  if (D === 12) {
    if (dr === 0 || dm === 0) return "WELD";
    return "CREAM";
  }

  // Outer Indigo stepped field with Weld latch-hooks (D === 11, 10)
  if (D === 11) {
    if (r === 18 || r === 7) return "WELD";
    return "INDIGO";
  }
  if (D === 10) {
    if (dr === dm || r === 15 || r === 3) return "WELD";
    if (r === 7) return "CREAM";
    return "INDIGO";
  }

  // Glowing Weld Yellow stepped lozenge band (D === 9)
  if (D === 9) {
    if (dm === 0) return "MADDER";
    return "WELD";
  }

  // Saw-tooth Walnut & Cream stepped divider (D === 8)
  if (D === 8) {
    return (r + dm) % 2 === 0 ? "WALNUT" : "CREAM";
  }

  // Great Madder Red central kilim medallion (D === 7, 6, 5)
  if (D === 7) {
    if (dm === 0) return "CREAM";
    return "MADDER";
  }
  if (D === 6) {
    if (dr === dm) return "WELD";
    if (dr === 0 || dm === 0) return "CREAM";
    return "MADDER";
  }
  if (D === 5) {
    if (r === 7) return "WELD";
    return "MADDER";
  }

  // Inner Walnut outline diamond (D === 4)
  if (D === 4) {
    if (dm === 0 || dr === 0) return "CREAM";
    return "WALNUT";
  }

  // Inner Undyed Cream stepped diamond (D === 3)
  if (D === 3) {
    return "CREAM";
  }

  // Inner Indigo star ring (D === 2)
  if (D === 2) {
    if (dr === 1 && dm === 1) return "WELD";
    return "INDIGO";
  }

  // Inner Weld Yellow four-pointed star (D === 1)
  if (D === 1) {
    return "WELD";
  }

  // Heart of the lozenge pyramid (r = 7, m = 0)
  return "MADDER";
}

// ============================================================================
// STAGE 1: WARM DRY PLASTER GROUND & STONE WEAVER'S PLINTH
// ============================================================================

function drawWarmDryGround() {
  brush.noStroke();
  brush.noHatch();

  // Warm dry plaster atmospheric washes (straight-edged zones)
  brush.fill("#e3d3b7", 85);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.25);
  drawStraightPoly([[30, 30], [1170, 30], [1170, BASE_Y], [30, BASE_Y]]);

  // Upper warm dry sunlight glow around apex
  brush.fill("#f5ebd6", 95);
  brush.fillBleed(0.15, "in");
  drawStraightPoly([[220, 40], [980, 40], [1080, 680], [120, 680]]);

  // Lower plinth / bench surface (y = BASE_Y to 1200)
  brush.fill("#cfbda0", 130);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.6, 0.35);
  drawStraightPoly([[0, BASE_Y], [1200, BASE_Y], [1200, 1200], [0, 1200]]);

  brush.fill("#bda786", 110);
  drawStraightPoly([[0, BASE_Y + 55], [1200, BASE_Y + 55], [1200, 1200], [0, 1200]]);

  brush.noFill();

  // Subtle dry woven linen / plaster tooth in the background (strictly symmetrical)
  brush.set("2H", "#cbb999", 0.24);
  for (let y = 48; y < BASE_Y; y += 14) {
    const span = 560;
    const yjit = (hash01(y, 11) - 0.5) * 2;
    brush.line(CX - span, y + yjit, CX + span, y + yjit);
  }

  // Subtle vertical dry plaster texture near left and right margins
  brush.set("2H", "#c4b08f", 0.22);
  for (let d = 320; d <= 565; d += 16) {
    const yStart = 50 + (d % 40);
    const yEnd = BASE_Y - 20;
    brush.line(CX - d, yStart, CX - d, yEnd);
    brush.line(CX + d, yStart, CX + d, yEnd);
  }

  // Plinth horizontal dry stone grain & crisp horizon bevel
  brush.set("HB", "#8f785b", 0.42);
  brush.line(0, BASE_Y, 1200, BASE_Y);
  brush.set("2H", "#f7efe0", 0.35);
  brush.line(0, BASE_Y + 2, 1200, BASE_Y + 2);

  brush.set("2H", "#a89173", 0.26);
  for (let y = BASE_Y + 10; y < 1192; y += 9) {
    brush.line(20, y, 1180, y);
  }
}

// ============================================================================
// STAGE 2: BUILD PYRAMID SKEIN & SAW-TOOTH STRUCTURE
// ============================================================================

function buildPyramidStructure() {
  const tiers = [];

  for (let r = 0; r < NUM_TIERS; r++) {
    const h = tierHalfModules(r);
    const y0 = tierTopY(r);
    const y1 = y0 + TIER_H;

    // 1. Build symmetric skein intervals [mStart, mEnd] across [-h .. +h]
    const centerColor = getModuleColor(r, 0);
    let cSpan = 0;
    while (cSpan + 1 <= h && cSpan < 1 && getModuleColor(r, cSpan + 1) === centerColor) {
      cSpan++;
    }

    const rightIntervals = [];
    let m = cSpan + 1;
    while (m <= h) {
      const col = getModuleColor(r, m);
      let mEnd = m;
      while (
        mEnd + 1 <= h &&
        getModuleColor(r, mEnd + 1) === col &&
        mEnd - m + 1 < 3
      ) {
        mEnd++;
      }
      rightIntervals.push({ mStart: m, mEnd: mEnd, color: col });
      m = mEnd + 1;
    }

    const allIntervals = [];
    // Mirror right intervals to left in reverse order
    for (let i = rightIntervals.length - 1; i >= 0; i--) {
      const it = rightIntervals[i];
      allIntervals.push({
        mStart: -it.mEnd,
        mEnd: -it.mStart,
        color: it.color
      });
    }
    // Center interval
    allIntervals.push({
      mStart: -cSpan,
      mEnd: cSpan,
      color: centerColor
    });
    // Right intervals
    for (let i = 0; i < rightIntervals.length; i++) {
      allIntervals.push(rightIntervals[i]);
    }

    // 2. Build saw-tooth boundary profiles between adjacent skeins
    // Each boundary has 9 vertical vertices (k = 0..8, every 5.5 px)
    // Guaranteed bilaterally symmetric: x_left(k) = 2 * CX - x_right(k)
    const numBounds = allIntervals.length + 1;
    const boundaries = new Array(numBounds);

    for (let b = 0; b < numBounds; b++) {
      const mEdge =
        b === 0
          ? -h - 0.5
          : b === numBounds - 1
          ? h + 0.5
          : allIntervals[b - 1].mEnd + 0.5;

      const xBase = CX + mEdge * MOD_W;
      const isOuter = b === 0 || b === numBounds - 1;
      const absM = Math.round(Math.abs(mEdge) * 2);

      // Saw-tooth amplitude: bold 13px interlocking teeth where skeins meet,
      // crisp 2.2px ply-head notch at outer stepped edges
      const amp = isOuter ? 2.2 : 12.5;
      const parity = (r + absM) % 2 === 0 ? 1 : -1;

      const pts = [];
      for (let k = 0; k <= 8; k++) {
        const yk = y0 + (k / 8) * TIER_H;
        let toothDir = (k % 2 === 0 ? 1 : -1) * parity;
        // At top and bottom corners of outer edges, keep strict 0 offset for razor-sharp step corners
        let localAmp = amp;
        if (isOuter && (k === 0 || k === 8)) localAmp = 0;
        if (!isOuter && (k === 0 || k === 8)) localAmp = amp * 0.45;

        // Outward displacement relative to center CX (ensures exact mirror symmetry!)
        const signFromCenter = mEdge >= 0 ? 1 : -1;
        const dx = signFromCenter * toothDir * localAmp;
        pts.push([xBase + dx, yk]);
      }
      boundaries[b] = { mEdge, xBase, isOuter, pts };
    }

    // 3. Construct individual Skein objects with their left/right saw-tooth boundaries
    const skeins = [];
    for (let s = 0; s < allIntervals.length; s++) {
      const it = allIntervals[s];
      const leftB = boundaries[s];
      const rightB = boundaries[s + 1];
      const symIdx = Math.abs(it.mStart + it.mEnd);
      const abrash = hash01(r + 3, symIdx + 7, 19);

      // Build closed polygon for watercolor wash
      const poly = [];
      for (let k = 0; k <= 8; k++) poly.push(leftB.pts[k]);
      for (let k = 8; k >= 0; k--) poly.push(rightB.pts[k]);

      // Determine if this skein has a binding tie wrap near its outer end
      const spanMods = it.mEnd - it.mStart + 1;
      let tieX = null;
      let tieColor = it.color === "CREAM" ? "WALNUT" : "CREAM";
      if (s === 0 && spanMods >= 2) {
        tieX = leftB.xBase + 18;
      } else if (s === allIntervals.length - 1 && spanMods >= 2) {
        tieX = rightB.xBase - 18;
      }

      skeins.push({
        r,
        sIdx: s,
        mStart: it.mStart,
        mEnd: it.mEnd,
        color: it.color,
        abrash,
        leftB,
        rightB,
        y0,
        y1,
        poly,
        tieX,
        tieColor
      });
    }

    tiers.push({
      r,
      h,
      y0,
      y1,
      xLeft: CX - (h + 0.5) * MOD_W,
      xRight: CX + (h + 0.5) * MOD_W,
      skeins,
      boundaries
    });
  }

  return tiers;
}

// ============================================================================
// STAGE 3: SYMMETRICAL STEPPED CAST SHADOWS (NO CURVES)
// ============================================================================

function drawSteppedShadows(tiers) {
  brush.noStroke();
  brush.noHatch();

  // 1. Stepped shadows cast onto the wall under the overhanging lower lozenge steps (r = 1..7)
  brush.fill("#b8a180", 115);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.45, 0.3);

  for (let r = 1; r <= EQUATOR_R; r++) {
    const tCurr = tiers[r];
    const tBelow = tiers[r - 1];
    // Overhang on left: from tCurr.xLeft to tBelow.xLeft at y = tCurr.y1
    const overhangL1 = tCurr.xLeft;
    const overhangL2 = tBelow.xLeft;
    const yStep = tCurr.y1;
    const dropH = TIER_H * 0.68;

    // Left stepped shadow triangle/trapezoid
    drawStraightPoly([
      [overhangL1 + 4, yStep],
      [overhangL2, yStep],
      [overhangL2, yStep + dropH],
      [overhangL1 + 14, yStep + dropH * 0.45]
    ]);

    // Right mirrored stepped shadow triangle/trapezoid
    const overhangR1 = tBelow.xRight;
    const overhangR2 = tCurr.xRight;
    drawStraightPoly([
      [overhangR1, yStep],
      [overhangR2 - 4, yStep],
      [overhangR2 - 14, yStep + dropH * 0.45],
      [overhangR1, yStep + dropH]
    ]);
  }

  // 2. Plinth contact & cast shadow beneath base tier (r = 0)
  const baseT = tiers[0];
  brush.fill("#8c7353", 145);
  drawStraightPoly([
    [baseT.xLeft - 12, BASE_Y],
    [baseT.xRight + 12, BASE_Y],
    [baseT.xRight + 46, BASE_Y + 34],
    [baseT.xLeft - 46, BASE_Y + 34]
  ]);

  brush.fill("#4a3623", 180);
  drawStraightPoly([
    [baseT.xLeft + 2, BASE_Y],
    [baseT.xRight - 2, BASE_Y],
    [baseT.xRight + 14, BASE_Y + 11],
    [baseT.xLeft - 14, BASE_Y + 11]
  ]);

  brush.noFill();

  // Crisp graphite hatching inside the cast shadows
  for (let r = 1; r <= EQUATOR_R; r++) {
    const tCurr = tiers[r];
    const tBelow = tiers[r - 1];
    const yStep = tCurr.y1;

    brush.set("2B", "#6e583f", 0.32);
    for (let k = 0; k < 7; k++) {
      const yy = yStep + 2 + k * 3.5;
      const inset = k * 4.5;
      if (tCurr.xLeft + 6 + inset < tBelow.xLeft) {
        brush.line(tCurr.xLeft + 6 + inset, yy, tBelow.xLeft, yy);
        brush.line(tBelow.xRight, yy, tCurr.xRight - 6 - inset, yy);
      }
    }
  }

  // Dense dry occlusion hatching under base tier on the plinth
  brush.set("charcoal", "#2b1c10", 0.48);
  brush.line(baseT.xLeft, BASE_Y + 1, baseT.xRight, BASE_Y + 1);
  brush.line(baseT.xLeft - 4, BASE_Y + 3, baseT.xRight + 4, BASE_Y + 3);

  brush.set("2B", "#59432d", 0.32);
  for (let k = 1; k <= 9; k++) {
    const yy = BASE_Y + k * 3.4;
    const spread = k * 3.8;
    brush.line(baseT.xLeft - spread, yy, baseT.xRight + spread, yy);
  }
}

// ============================================================================
// STAGE 4: BATCHED WATERCOLOR & DRY PIGMENT UNDERPAINTING
// ============================================================================

function drawBatchedSkeinWashes(tiers) {
  const colorNames = ["MADDER", "INDIGO", "WELD", "WALNUT", "CREAM"];

  brush.noStroke();
  brush.noHatch();

  for (let c = 0; c < colorNames.length; c++) {
    const cName = colorNames[c];
    const pal = PALETTES[cName];

    // Group skeins of this color into 3 abrash dye-lot buckets for rich mottling
    for (let bucket = 0; bucket < 3; bucket++) {
      brush.fill(pal.wash[bucket], 175);
      brush.fillBleed(0.05, "in");
      brush.fillTexture(0.5, 0.32);

      for (let r = 0; r < tiers.length; r++) {
        const skeins = tiers[r].skeins;
        for (let s = 0; s < skeins.length; s++) {
          const sk = skeins[s];
          if (sk.color !== cName) continue;
          const skBucket = Math.floor(sk.abrash * 3) % 3;
          if (skBucket !== bucket) continue;
          drawStraightPoly(sk.poly);
        }
      }
    }

    // Second pass: lower-ply shadow wash on bottom half of each skein
    brush.fill(pal.dark, 110);
    brush.fillBleed(0.03, "in");
    for (let r = 0; r < tiers.length; r++) {
      const skeins = tiers[r].skeins;
      for (let s = 0; s < skeins.length; s++) {
        const sk = skeins[s];
        if (sk.color !== cName) continue;
        const pts = [
          sk.leftB.pts[4],
          sk.rightB.pts[4],
          sk.rightB.pts[6],
          sk.rightB.pts[8],
          sk.leftB.pts[8],
          sk.leftB.pts[6]
        ];
        drawStraightPoly(pts);
      }
    }
  }

  brush.noFill();
}

// ============================================================================
// STAGE 5: HYPERREAL WOOL HANKS, TWIST LOBES, CRIMPED FIBRES & STRAY HAIRS
// ============================================================================

function drawAllWoolTiers(tiers) {
  for (let r = 0; r < tiers.length; r++) {
    const tier = tiers[r];

    // 1. Render every skein in this tier
    for (let s = 0; s < tier.skeins.length; s++) {
      drawHyperrealSkein(tier.skeins[s], r, tiers);
    }

    // 2. Render crisp saw-tooth join crevices where skeins meet in this tier
    for (let b = 1; b < tier.boundaries.length - 1; b++) {
      const bound = tier.boundaries[b];
      const leftSk = tier.skeins[b - 1];
      const rightSk = tier.skeins[b];
      drawSawToothJoinDetail(bound, leftSk, rightSk, r);
    }

    // 3. Render outer stepped head details & stray wool halo hairs at tier ends
    drawOuterStepHeads(tier.boundaries[0], tier.skeins[0], -1, r);
    drawOuterStepHeads(
      tier.boundaries[tier.boundaries.length - 1],
      tier.skeins[tier.skeins.length - 1],
      1,
      r
    );

    // 4. Render deep horizontal crevice shadow between tiers & upper shelf shadow
    drawTierCrevicesAndShelfShadows(tier, r, tiers);
  }
}

function drawHyperrealSkein(sk, r, tiers) {
  const pal = PALETTES[sk.color];
  const y0 = sk.y0;
  const y1 = sk.y1;
  const yMid = (y0 + y1) * 0.5;

  // Each module (40px) is divided into 2 twist lobes (20px each) -> 100% symmetric grid!
  const spanMods = sk.mEnd - sk.mStart + 1;
  const numLobes = spanMods * 2;

  // Build lobe boundary x-coordinates along top (y0), middle seam (yMid), and bottom (y1)
  // Upper ply slants outward-up; Lower ply counter-twists outward-down (chevron hank twist)
  const topNodes = new Array(numLobes + 1);
  const midNodes = new Array(numLobes + 1);
  const botNodes = new Array(numLobes + 1);

  for (let i = 0; i <= numLobes; i++) {
    const mPos = sk.mStart - 0.5 + i * 0.5; // in module units from center
    const xNom = CX + mPos * MOD_W;

    if (i === 0) {
      topNodes[i] = [sk.leftB.pts[0][0], y0];
      midNodes[i] = [sk.leftB.pts[4][0], yMid];
      botNodes[i] = [sk.leftB.pts[8][0], y1];
    } else if (i === numLobes) {
      topNodes[i] = [sk.rightB.pts[0][0], y0];
      midNodes[i] = [sk.rightB.pts[4][0], yMid];
      botNodes[i] = [sk.rightB.pts[8][0], y1];
    } else {
      // Sign from center CX ensures exact left-right mirror reflection!
      const sign = mPos > 0 ? 1 : mPos < 0 ? -1 : 0;
      const twistShift = 6.5 * sign;
      const midZig = (i % 2 === 0 ? -2.4 : 2.4);

      topNodes[i] = [xNom + twistShift, y0];
      midNodes[i] = [xNom - twistShift * 0.45, yMid + midZig];
      botNodes[i] = [xNom + twistShift * 0.85, y1];
    }
  }

  // Render each twist lobe (Upper Ply + Lower Ply)
  for (let i = 0; i < numLobes; i++) {
    const mCenter = sk.mStart - 0.25 + i * 0.5;
    const symLobeSeed = Math.round(Math.abs(mCenter) * 4);
    const lobeAbrash = hash01(r * 13 + 5, symLobeSeed, 3);

    // Upper Ply Quad
    const uTL = topNodes[i];
    const uTR = topNodes[i + 1];
    const uBR = midNodes[i + 1];
    const uBL = midNodes[i];

    // Lower Ply Quad
    const lTL = midNodes[i];
    const lTR = midNodes[i + 1];
    const lBR = botNodes[i + 1];
    const lBL = botNodes[i];

    // Render Upper Ply twist lobe
    renderTwistLobe(uTL, uTR, uBR, uBL, pal, lobeAbrash, true, mCenter, r, i);

    // Render Lower Ply twist lobe
    renderTwistLobe(lTL, lTR, lBR, lBL, pal, lobeAbrash, false, mCenter, r, i);

    // Central herringbone seam crevice between upper and lower plies
    brush.set("2B", pal.deep, 0.36);
    brush.line(uBL[0], uBL[1], uBR[0], uBR[1]);

    // Diagonal twist valley crevice between adjacent lobes
    if (i > 0) {
      brush.set("2B", pal.dark, 0.38);
      brush.line(uTL[0], uTL[1] + 2, uBL[0], uBL[1]);
      brush.set("2B", pal.deep, 0.42);
      brush.line(lTL[0], lTL[1], lBL[0], lBL[1] - 2);
    }
  }

  // If this skein has a binding tie wrap near its outer end, render it
  if (sk.tieX !== null) {
    drawHankBindingTie(sk.tieX, y0, y1, PALETTES[sk.tieColor], pal, r);
  }
}

function renderTwistLobe(TL, TR, BR, BL, pal, lobeAbrash, isUpperPly, mCenter, r, lobeIdx) {
  const numStrands = 12;
  const sign = mCenter >= 0 ? 1 : -1;

  for (let s = 0; s < numStrands; s++) {
    const v = (s + 0.5) / numStrands; // 0 = top of ply, 1 = bottom of ply

    // Yarn fibres angle across the twist lobe to show the spiral tension of the hank
    const slantDV = (isUpperPly ? 0.22 : -0.22) * sign;
    const vStart = constrain(v - slantDV * 0.5, 0.04, 0.96);
    const vEnd = constrain(v + slantDV * 0.5, 0.04, 0.96);

    const p0 = bilerpQuad(TL, TR, BR, BL, 0.04, vStart);
    const p3 = bilerpQuad(TL, TR, BR, BL, 0.96, vEnd);

    // Compute 3-segment crimped wool path (straight segments with angular wool crimp)
    const symSeed = Math.round(Math.abs(mCenter) * 10) + s * 17 + (isUpperPly ? 0 : 100);
    const crimpAmp = 1.35 + hash01(r, symSeed, 1) * 1.1;
    const crimpSign = (s % 2 === 0 ? 1 : -1) * (isUpperPly ? 1 : -1);

    const mid1 = lerpPt(p0, p3, 0.33);
    const mid2 = lerpPt(p0, p3, 0.67);
    const p1 = [mid1[0], mid1[1] + crimpSign * crimpAmp];
    const p2 = [mid2[0], mid2[1] - crimpSign * crimpAmp];

    // Select colour & pencil brush for 3D cylindrical volume + hand-dyed abrash mottling
    let col = pal.mid;
    let bName = "cpencil";
    let weight = 0.36;

    if (isUpperPly) {
      if (v < 0.24) {
        col = lobeAbrash > 0.55 ? pal.highlight : pal.light;
        bName = "2H";
        weight = 0.30;
      } else if (v < 0.48) {
        col = lobeAbrash > 0.6 ? pal.light : lobeAbrash < 0.3 ? pal.abrashWarm : pal.midLight;
        bName = "cpencil";
        weight = 0.38;
      } else if (v < 0.78) {
        col = lobeAbrash > 0.65 ? pal.abrashWarm : lobeAbrash < 0.35 ? pal.abrashCool : pal.mid;
        bName = "HB";
        weight = 0.36;
      } else {
        col = pal.midDark;
        bName = "2B";
        weight = 0.38;
      }
    } else {
      // Lower ply has secondary light ridge at top, deeper core shadow below
      if (v < 0.22) {
        col = lobeAbrash > 0.5 ? pal.light : pal.midLight;
        bName = "cpencil";
        weight = 0.34;
      } else if (v < 0.55) {
        col = lobeAbrash > 0.6 ? pal.mid : lobeAbrash < 0.3 ? pal.abrashCool : pal.midDark;
        bName = "HB";
        weight = 0.38;
      } else if (v < 0.82) {
        col = pal.dark;
        bName = "2B";
        weight = 0.42;
      } else {
        col = pal.deep;
        bName = "2B";
        weight = 0.45;
      }
    }

    brush.set(bName, col, weight);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(p2[0], p2[1], p3[0], p3[1]);

    // Add fine sunlit crimp highlight filament near top ridge of upper ply
    if (isUpperPly && (s === 1 || s === 2)) {
      brush.set("2H", pal.highlight, 0.24);
      brush.line(p1[0], p1[1] - 0.8, p2[0], p2[1] - 0.8);
    }
  }

  // Short directional tuck-in hatches at the left and right crease edges of the lobe
  brush.set("2B", isUpperPly ? pal.dark : pal.deep, 0.28);
  for (let k = 1; k <= 3; k++) {
    const vv = k * 0.25;
    const leftEdge = lerpPt(TL, BL, vv);
    const rightEdge = lerpPt(TR, BR, vv);
    brush.line(leftEdge[0], leftEdge[1], leftEdge[0] + 4.5, leftEdge[1] + 1.2);
    brush.line(rightEdge[0], rightEdge[1], rightEdge[0] - 4.5, rightEdge[1] + 1.2);
  }
}

function drawHankBindingTie(tieX, y0, y1, tiePal, skeinPal, r) {
  // Pinch shadows on left and right of the vertical tie wrap
  brush.set("2B", skeinPal.deep, 0.42);
  brush.line(tieX - 4.5, y0 + 2, tieX - 3.5, y1 - 2);
  brush.line(tieX + 4.5, y0 + 2, tieX + 3.5, y1 - 2);

  // 4 tightly bundled vertical/angled cord strands
  const strands = [-2.4, -0.8, 0.8, 2.4];
  for (let i = 0; i < strands.length; i++) {
    const dx = strands[i];
    const col = i === 1 ? tiePal.highlight : i === 3 ? tiePal.dark : tiePal.midLight;
    brush.set("cpencil", col, 0.38);
    brush.line(tieX + dx, y0 + 1.5, tieX + dx * 0.7, (y0 + y1) * 0.5);
    brush.line(tieX + dx * 0.7, (y0 + y1) * 0.5, tieX + dx, y1 - 1.5);
  }

  // Horizontal knot bind at center of the tie
  brush.set("HB", tiePal.light, 0.36);
  const ym = (y0 + y1) * 0.5;
  brush.line(tieX - 4.2, ym - 2, tieX + 4.2, ym + 1);
  brush.line(tieX - 4.2, ym + 1, tieX + 4.2, ym - 2);
}

function drawSawToothJoinDetail(bound, leftSk, rightSk, r) {
  const leftPal = PALETTES[leftSk.color];
  const rightPal = PALETTES[rightSk.color];
  const pts = bound.pts;

  // 1. Interlocking crimped fibres reaching into the saw-tooth teeth from both skeins
  for (let k = 0; k < 8; k++) {
    const pA = pts[k];
    const pB = pts[k + 1];
    const midP = lerpPt(pA, pB, 0.5);

    // Crisp fibre strands looping into the tooth apex
    brush.set("cpencil", k < 4 ? leftPal.light : leftPal.midDark, 0.28);
    brush.line(pA[0] - 9, pA[1], pA[0] - 1, pA[1]);
    brush.line(midP[0] - 8, midP[1] + 0.8, midP[0] - 0.5, midP[1]);

    brush.set("cpencil", k < 4 ? rightPal.light : rightPal.midDark, 0.28);
    brush.line(pA[0] + 1, pA[1], pA[0] + 9, pA[1]);
    brush.line(midP[0] + 0.5, midP[1], midP[0] + 8, midP[1] + 0.8);
  }

  // 2. Sharp dark occlusion zigzag line right in the saw-tooth slit-weave crevice
  brush.set("2B", "#1f140d", 0.38);
  for (let k = 0; k < 8; k++) {
    brush.line(pts[k][0], pts[k][1], pts[k + 1][0], pts[k + 1][1]);
  }

  // 3. Fine stray wool hairs crossing the saw-tooth join (strictly symmetric)
  for (let k = 1; k <= 7; k += 2) {
    const pt = pts[k];
    brush.set("2H", leftPal.highlight, 0.20);
    brush.line(pt[0] - 5, pt[1] - 1.5, pt[0] + 3.5, pt[1] + 0.5);
    brush.set("2H", rightPal.highlight, 0.20);
    brush.line(pt[0] + 5, pt[1] + 1.5, pt[0] - 3.5, pt[1] - 0.5);
  }
}

function drawOuterStepHeads(bound, sk, sideSign, r) {
  const pal = PALETTES[sk.color];
  const pts = bound.pts;

  // Crisp vertical step-edge definition with ply-turn shading
  brush.set("2B", pal.deep, 0.42);
  for (let k = 0; k < 8; k++) {
    brush.line(pts[k][0], pts[k][1], pts[k + 1][0], pts[k + 1][1]);
  }

  // Turned loop ends of the wool hank at the outer step head
  for (let k = 1; k <= 7; k++) {
    const pt = pts[k];
    const col = k <= 3 ? pal.light : k <= 5 ? pal.mid : pal.dark;
    brush.set("cpencil", col, 0.32);
    brush.line(pt[0], pt[1], pt[0] - sideSign * 10, pt[1] + (k % 2 === 0 ? 1.5 : -1.5));
  }

  // Fine stray wool halo hairs projecting into the warm dry air (symmetric left/right)
  for (let k = 1; k <= 7; k++) {
    const pt = pts[k];
    const hLen = 5 + hash01(r, k, 99) * 7;
    const dy1 = (k % 2 === 0 ? -1 : 1) * 1.8;
    const dy2 = -dy1 * 0.9;
    const pMid = [pt[0] + sideSign * hLen * 0.55, pt[1] + dy1];
    const pTip = [pt[0] + sideSign * hLen, pt[1] + dy1 + dy2];

    const hairCol = k <= 3 ? pal.highlight : pal.midDark;
    brush.set("2H", hairCol, 0.20);
    brush.line(pt[0], pt[1], pMid[0], pMid[1]);
    brush.line(pMid[0], pMid[1], pTip[0], pTip[1]);
  }
}

function drawTierCrevicesAndShelfShadows(tier, r, tiers) {
  const y0 = tier.y0;
  const y1 = tier.y1;
  const xL = tier.xLeft;
  const xR = tier.xRight;

  // 1. Deep horizontal crevice line along the bottom of the tier (y1)
  brush.set("charcoal", "#21150c", 0.46);
  brush.line(xL + 2, y1, xR - 2, y1);

  // 2. If there is a tier above (r < NUM_TIERS - 1), cast a crisp horizontal shelf shadow
  //    along the top of this tier where the upper tier rests on it
  if (r < NUM_TIERS - 1) {
    const upperTier = tiers[r + 1];
    const shadowL = Math.max(xL, upperTier.xLeft);
    const shadowR = Math.min(xR, upperTier.xRight);

    brush.set("2B", "#2b1b10", 0.42);
    brush.line(shadowL, y0 + 1.2, shadowR, y0 + 1.2);
    brush.set("HB", "#4d3522", 0.32);
    brush.line(shadowL + 2, y0 + 3.0, shadowR - 2, y0 + 3.0);
  }

  // 3. Exposed horizontal step treads (for r >= EQUATOR_R where this tier is wider than r+1)
  //    Catch warm dry top light + fine stray sunlit wool hairs rising from the step ledge!
  if (r >= EQUATOR_R && r < NUM_TIERS - 1) {
    const upperTier = tiers[r + 1];
    const leftStepSk = tier.skeins[0];
    const rightStepSk = tier.skeins[tier.skeins.length - 1];
    const leftPal = PALETTES[leftStepSk.color];
    const rightPal = PALETTES[rightStepSk.color];

    // Sunlit top rim on left and right exposed step ledges
    brush.set("2H", leftPal.highlight, 0.34);
    brush.line(xL + 1, y0 + 0.8, upperTier.xLeft - 1, y0 + 0.8);
    brush.set("2H", rightPal.highlight, 0.34);
    brush.line(upperTier.xRight + 1, y0 + 0.8, xR - 1, y0 + 0.8);

    // Symmetrical stray wool hairs along the exposed horizontal step tread
    for (let s = 0; s < 6; s++) {
      const t = (s + 0.5) / 6;
      const hxL = xL + t * (upperTier.xLeft - xL);
      const hxR = upperTier.xRight + (1 - t) * (xR - upperTier.xRight);
      const hHeight = 4.5 + hash01(r, s, 41) * 5.5;
      const kink = (s % 2 === 0 ? 1 : -1) * 2.2;

      brush.set("2H", leftPal.highlight, 0.19);
      brush.line(hxL, y0, hxL + kink, y0 - hHeight * 0.55);
      brush.line(hxL + kink, y0 - hHeight * 0.55, hxL - kink * 0.5, y0 - hHeight);

      brush.set("2H", rightPal.highlight, 0.19);
      brush.line(hxR, y0, hxR - kink, y0 - hHeight * 0.55);
      brush.line(hxR - kink, y0 - hHeight * 0.55, hxR + kink * 0.5, y0 - hHeight);
    }
  }

  // 4. Apex capstone top ridge (r === NUM_TIERS - 1)
  if (r === NUM_TIERS - 1) {
    const apexPal = PALETTES[tier.skeins[0].color];
    brush.set("2H", apexPal.highlight, 0.36);
    brush.line(xL + 1, y0 + 0.8, xR - 1, y0 + 0.8);

    for (let s = -3; s <= 3; s++) {
      const hx = CX + s * 5.2;
      const hHeight = 5 + hash01(20, Math.abs(s), 77) * 5;
      const kink = s * 0.8;
      brush.set("2H", apexPal.highlight, 0.20);
      brush.line(hx, y0, hx + kink, y0 - hHeight);
    }
  }
}

// =============================================================================
// HYPERREAL PLEIN-AIR STUDY: COW'S NOSE THROUGH WEATHERED LICHEN GATE
// Medium: Broad Earthy Watercolour & Charcoal Mass -> Meticulous Coloured Pencil
// =============================================================================

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Register custom vector field for sweeping plein-air foliage & wind
  brush.addField("pleinAirWind", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let angle = -12 + 28 * sin(nx * 180 + ny * 90) + (noise(nx * 3, ny * 3) - 0.5) * 50;
        field[col][row] = angle;
      }
    }
    return field;
  });

  // Register custom vector field for organic wood-grain flow with knots
  brush.addField("oakGrain", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = (col / field.length) * 1200;
        let y = (row / field[0].length) * 1200;
        let baseAngle = -1.15;
        let n = (noise(x * 0.008, y * 0.04) - 0.5) * 8;
        field[col][row] = baseAngle + n;
      }
    }
    return field;
  });
}

// -----------------------------------------------------------------------------
// GEOMETRY & ANATOMICAL HELPERS
// -----------------------------------------------------------------------------

// Upper gate bar top & bottom Y coordinates across X
function getTopBarY(x) {
  let slope = -0.019 * (x - 60);
  let sag = 7 * sin(((x - 60) / 1100) * 180);
  let wobble = (noise(x * 0.01, 1.2) - 0.5) * 6;
  let top = 192 + slope + sag + wobble;
  let bottom = top + 122 + (noise(x * 0.008, 3.4) - 0.5) * 8;
  return { top, bottom };
}

// Lower gate bar top & bottom Y coordinates across X
function getBottomBarY(x) {
  let slope = -0.021 * (x - 60);
  let sag = 6 * sin(((x - 60) / 1100) * 180 + 15);
  let wobble = (noise(x * 0.01, 5.7) - 0.5) * 6;
  let top = 768 + slope + sag + wobble;
  let bottom = top + 126 + (noise(x * 0.008, 8.1) - 0.5) * 8;
  return { top, bottom };
}

// Helper to draw a closed field-aware shape from an array of [x, y] points
function drawShapePoly(pts, curvature = 0.25) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Generates an organic blob polygon for washes, lichen, and foliage
function makeOrganicBlob(cx, cy, rx, ry, numPts = 14, irr = 0.25, seedOffset = 0) {
  let pts = [];
  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    let n = noise(cos(ang) * 1.3 + seedOffset, sin(ang) * 1.3 + seedOffset);
    let rMod = 1 + (n - 0.5) * 2 * irr;
    pts.push([cx + cos(ang) * rx * rMod, cy + sin(ang) * ry * rMod]);
  }
  return pts;
}

// Wood grain deflection around knots
function getWoodGrainY(x, baseY, railIndex) {
  let knots = railIndex === 0
    ? [
        { kx: 285, ky: 252, kr: 34, strength: 18 },
        { kx: 540, ky: 225, kr: 22, strength: -11 },
        { kx: 935, ky: 228, kr: 38, strength: 22 }
      ]
    : [
        { kx: 335, ky: 825, kr: 40, strength: 24 },
        { kx: 660, ky: 838, kr: 28, strength: -15 },
        { kx: 965, ky: 802, kr: 32, strength: 19 }
      ];

  let bar = railIndex === 0 ? getTopBarY(x) : getBottomBarY(x);
  let t = (baseY - bar.top) / (bar.bottom - bar.top);
  let y = lerp(bar.top, bar.bottom, t);

  for (let k of knots) {
    let dx = x - k.kx;
    let dy = y - k.ky;
    let distSq = dx * dx + dy * dy * 2.2;
    let influence = exp(-distSq / (k.kr * k.kr * 2.8));
    let sign = dy >= 0 ? 1 : -1;
    y += sign * abs(k.strength) * influence * (1 - abs(dx) / (k.kr * 3.5));
  }
  y += (noise(x * 0.015, baseY * 0.08) - 0.5) * 4.5;
  return y;
}

// -----------------------------------------------------------------------------
// COW MUZZLE 3D ANATOMY, NOSTRILS & PIGMENTATION FUNCTIONS
// -----------------------------------------------------------------------------

// Signed distance / boundary check for the hairless wet muzzle (Planum Nasolabiale)
function isInsideMuzzle(x, y) {
  let cx = 640;
  let cy = 606;
  let dx = (x - cx) / 196;
  let dy = (y - cy) / 136;

  // Broad bovine muzzle silhouette: wider at nostril wings, arched top, curved upper lip
  let wingBulge = 0.16 * exp(-pow((y - 565) / 55, 2)) * (1 - exp(-pow((x - cx) / 90, 2)));
  let topArch = y < 520 ? 0.08 * cos(((x - cx) / 170) * 180) : 0;
  let lipTaper = y > 650 ? 0.12 * pow((y - 650) / 85, 1.6) : 0;
  let philtrumDip = y > 710 && abs(x - cx) < 35 ? 0.035 * cos(((x - cx) / 35) * 90) : 0;

  let effRx = 1 + wingBulge - lipTaper;
  let effRy = 1 + topArch - philtrumDip;

  let d = pow(dx / effRx, 2) + pow(dy / effRy, 2);
  let nEdge = (noise(x * 0.025, y * 0.025) - 0.5) * 0.06;
  return d + nEdge < 0.98;
}

// Returns > 0 if inside dark nostril cavity, with depth 0..1
function getNostrilDepth(x, y) {
  // Left nostril: comma-shaped cavity centered around (520, 580)
  let lx = x - 520;
  let ly = y - 580;
  let lRotX = lx * cos(-28) - ly * sin(-28);
  let lRotY = lx * sin(-28) + ly * cos(-28);
  // Curve the comma
  let lCurveX = lRotX - 0.0065 * lRotY * lRotY;
  let lDist = pow(lCurveX / 34, 2) + pow(lRotY / 54, 2);
  if (lDist < 1.0) {
    return constrain(1.0 - lDist, 0, 1);
  }

  // Right nostril: symmetric comma-shaped cavity centered around (760, 575)
  let rx = x - 760;
  let ry = y - 575;
  let rRotX = rx * cos(28) - ry * sin(28);
  let rRotY = rx * sin(28) + ry * cos(28);
  let rCurveX = rRotX + 0.0065 * rRotY * rRotY;
  let rDist = pow(rCurveX / 34, 2) + pow(rRotY / 54, 2);
  if (rDist < 1.0) {
    return constrain(1.0 - rDist, 0, 1);
  }

  return 0;
}

// 3D height field of the cow's nose for realistic lighting, normal mapping, and specular sheen
function getMuzzleHeight(x, y) {
  let cx = 640;
  let cy = 602;
  let nx = (x - cx) / 205;
  let ny = (y - cy) / 145;
  let r2 = nx * nx + ny * ny;
  let dome = sqrt(max(0.01, 1.15 - r2 * 0.85));

  // Central philtrum groove
  let philtrum = -0.075 * exp(-pow((x - cx) / 19, 2)) * constrain(map(y, 520, 735, 0.2, 1.0), 0, 1);

  // Muscular lateral alar wings wrapping outside the nostrils
  let leftWing = 0.16 * exp(-(pow((x - 482) / 38, 2) + pow((y - 565) / 52, 2)));
  let rightWing = 0.16 * exp(-(pow((x - 798) / 38, 2) + pow((y - 560) / 52, 2)));

  // Medial nostril rim cushions
  let leftMedial = 0.11 * exp(-(pow((x - 562) / 28, 2) + pow((y - 585) / 42, 2)));
  let rightMedial = 0.11 * exp(-(pow((x - 718) / 28, 2) + pow((y - 580) / 42, 2)));

  // Plump upper lip roll
  let lipRoll = 0.12 * exp(-pow((y - 702) / 26, 2)) * exp(-pow((x - cx) / 150, 2));

  // Nostril depression
  let nDepth = getNostrilDepth(x, y);
  let cavity = -0.55 * pow(nDepth, 0.7);

  return dome + philtrum + leftWing + rightWing + leftMedial + rightMedial + lipRoll + cavity;
}

// Surface normal [nx, ny, nz] at (x, y) on the muzzle
function getMuzzleNormal(x, y) {
  let eps = 2.5;
  let hL = getMuzzleHeight(x - eps, y);
  let hR = getMuzzleHeight(x + eps, y);
  let hU = getMuzzleHeight(x, y - eps);
  let hD = getMuzzleHeight(x, y + eps);

  let dx = -(hR - hL) * 42;
  let dy = -(hD - hU) * 42;
  let dz = 1.0;
  let len = sqrt(dx * dx + dy * dy + dz * dz);
  return [dx / len, dy / len, dz / len];
}

// Returns 0 (dark slate-obsidian pigment) to 1 (warm coral-terracotta/rose pigment)
function getMuzzlePigment(x, y) {
  let n1 = noise(x * 0.014, y * 0.014);
  let n2 = noise(x * 0.04 + 10, y * 0.04 + 10);
  // Warm pink/terracotta mottling concentrated at lower philtrum, upper lip, medial nostril rims, and top blaze bridge
  let philtrumWarmth = exp(-(pow((x - 640) / 58, 2) + pow((y - 680) / 62, 2))) * 0.85;
  let bridgeBlaze = exp(-(pow((x - 640) / 48, 2) + pow((y - 490) / 36, 2))) * 0.75;
  let leftRimWarmth = exp(-(pow((x - 548) / 30, 2) + pow((y - 595) / 38, 2))) * 0.8;
  let rightRimWarmth = exp(-(pow((x - 732) / 30, 2) + pow((y - 590) / 38, 2))) * 0.8;

  let val = n1 * 0.65 + n2 * 0.25 + philtrumWarmth + bridgeBlaze + leftRimWarmth + rightRimWarmth - 0.42;
  // Sharpen transition for authentic bovine spotted skin mottling
  return constrain( map(val, 0.12, 0.38, 0, 1), 0, 1 );
}

// =============================================================================
// MAIN DRAW FUNCTION
// =============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Heavy cold-press watercolour paper ground with subtle damp silvery-warm tone
  background("#e5e0d3");

  // 1. PLEIN-AIR BACKGROUND: OVERCAST SILVERY SKY, OAK EDGE & DAMP MEADOW
  drawPleinAirBackground();

  // 2. FAR GATE ELEMENTS & COW ANATOMY BEHIND THE TOP BAR (POLL, SHOULDERS, EARS)
  drawBackGateAndCowShoulders();

  // 3. WEATHERED LICHEN-CRUSTED GATE: UPPER BAR, LEFT STILE & LOWER BAR
  drawWeatheredGate();

  // 4. COW FOREHEAD, SOULFUL EYES, CHEEKS & FURRY BRIDGE OF NOSE
  drawCowHeadAndEyes();

  // 5. HYPERREAL DEW-WET COW'S NOSE PUSHING OVER THE LOWER BAR
  drawHyperrealWetNose();

  // 6. EXACT WHISKERS (VIBRISSAE), FOLLICLE PORES & HANGING DEW DROPS
  drawWhiskersAndDew();

  // 7. FINAL PLEIN-AIR ATMOSPHERIC UNIFICATION & SILVERY OVERCAST GLINTS
  drawAtmosphericFinishes();

  noLoop();
}

// =============================================================================
// PHASE 1: PLEIN-AIR SKY, OAK EDGE & DAMP MEADOW (WATERCOLOUR & CHARCOAL MASS)
// =============================================================================

function drawPleinAirBackground() {
  brush.noStroke();

  // --- A. Overcast Silvery Sky Washes (Batched by colour) ---
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.65, 0.35);

  // Silvery-blue storm sky upper washes
  let skyLayers = [
    { col: "#687f94", alpha: 95, blobs: [[280, 120, 320, 110], [880, 105, 360, 115], [580, 90, 340, 95]] },
    { col: "#465c70", alpha: 85, blobs: [[190, 85, 240, 85], [960, 80, 290, 90], [520, 65, 260, 70]] },
    { col: "#96aab8", alpha: 110, blobs: [[420, 165, 350, 95], [780, 155, 340, 90], [160, 175, 220, 80]] },
    { col: "#cddae0", alpha: 130, blobs: [[630, 150, 310, 75], [310, 190, 240, 65], [940, 170, 230, 65]] },
    { col: "#ebd8b2", alpha: 75, blobs: [[610, 210, 380, 65], [250, 225, 240, 55], [980, 205, 220, 55]] }
  ];

  for (let layer of skyLayers) {
    brush.fill(layer.col, layer.alpha);
    for (let i = 0; i < layer.blobs.length; i++) {
      let b = layer.blobs[i];
      drawShapePoly(makeOrganicBlob(b[0], b[1], b[2], b[3], 14, 0.28, i * 17 + b[0]), 0.35);
    }
  }

  // --- B. Loosely Suggested Oak Edge & Damp Meadow Washes ---
  // Vivid Terre Verte, Yellow Ochre, and Raw Umber grouped in batches
  let landscapeBatches = [
    // Deep Terre Verte oak canopy & hedgerow shadows
    {
      col: "#1e5942", alpha: 115, bleed: 0.35,
      blobs: [
        [180, 340, 190, 160], [340, 290, 210, 150], [920, 280, 230, 165],
        [1060, 360, 180, 175], [240, 540, 230, 130], [980, 520, 240, 140]
      ]
    },
    // Saturated Viridian / Mid Terre Verte meadow & foliage
    {
      col: "#32855c", alpha: 110, bleed: 0.32,
      blobs: [
        [270, 430, 250, 140], [880, 410, 260, 145], [190, 680, 260, 160],
        [1010, 660, 250, 170], [420, 960, 340, 150], [840, 950, 350, 155]
      ]
    },
    // Vivid Yellow Ochre & Golden Sienna damp meadow & autumn-touched oak edge
    {
      col: "#d99621", alpha: 115, bleed: 0.3,
      blobs: [
        [360, 490, 220, 115], [870, 480, 230, 120], [280, 730, 270, 125],
        [940, 720, 280, 130], [580, 990, 380, 135], [230, 980, 240, 120]
      ]
    },
    // Bright Luminous Gold Ochre highlights in the wet grass
    {
      col: "#f2b838", alpha: 95, bleed: 0.25,
      blobs: [
        [330, 590, 180, 85], [910, 575, 195, 90], [350, 920, 240, 95], [880, 910, 250, 95]
      ]
    },
    // Raw Umber deep earth, oak trunks, and wet gateway mud
    {
      col: "#472e19", alpha: 120, bleed: 0.32,
      blobs: [
        [150, 420, 150, 140], [1040, 400, 160, 150], [520, 1040, 360, 120],
        [780, 1050, 320, 115], [310, 640, 180, 95], [930, 625, 190, 95]
      ]
    },
    // Cool Silvery-Sage mist hovering at the oak edge
    {
      col: "#9ab3a8", alpha: 90, bleed: 0.4,
      blobs: [
        [390, 440, 210, 80], [850, 425, 220, 85], [640, 930, 350, 80]
      ]
    }
  ];

  for (let batch of landscapeBatches) {
    brush.fillBleed(batch.bleed, "out");
    brush.fill(batch.col, batch.alpha);
    for (let i = 0; i < batch.blobs.length; i++) {
      let b = batch.blobs[i];
      drawShapePoly(makeOrganicBlob(b[0], b[1], b[2], b[3], 12, 0.32, i * 31 + b[1]), 0.35);
    }
  }
  brush.noFill();

  // --- C. Plein-Air Charcoal Mass in the Oak Edge & Hedgerow ---
  let charcoalMasses = [
    { col: "#261b12", cx: 210, cy: 330, rx: 130, ry: 110, str: 0.65 },
    { col: "#1f382b", cx: 330, cy: 360, rx: 145, ry: 95, str: 0.55 },
    { col: "#261b12", cx: 970, cy: 310, rx: 150, ry: 115, str: 0.65 },
    { col: "#1f382b", cx: 880, cy: 365, rx: 135, ry: 95, str: 0.5 },
    { col: "#3b2818", cx: 250, cy: 640, rx: 160, ry: 90, str: 0.45 },
    { col: "#3b2818", cx: 970, cy: 620, rx: 165, ry: 95, str: 0.45 },
    { col: "#291c12", cx: 620, cy: 1030, rx: 320, ry: 95, str: 0.55 }
  ];

  for (let i = 0; i < charcoalMasses.length; i++) {
    let cm = charcoalMasses[i];
    brush.mass("charcoal", cm.col, {
      precision: 0.2,
      strength: cm.str,
      gradient: 0.45,
      outline: false
    });
    drawShapePoly(makeOrganicBlob(cm.cx, cm.cy, cm.rx, cm.ry, 11, 0.3, i * 43), 0.3);
  }
  brush.noMass();

  // --- D. Expressive Plein-Air Haste Gestures: Loose Oak Boughs & Meadow Sweeps ---
  brush.field("pleinAirWind");

  // Loose charcoal & terre-verte sweeping marks in the background
  let bgStrokes = [
    { br: "charcoal", col: "#2b1d12", w: 1.8, count: 45, yMin: 140, yMax: 520, len: 110 },
    { br: "charcoal", col: "#1b4d38", w: 1.6, count: 40, yMin: 260, yMax: 720, len: 120 },
    { br: "2B", col: "#c9881e", w: 1.5, count: 38, yMin: 480, yMax: 1080, len: 130 },
    { br: "charcoal", col: "#3b6e4c", w: 1.4, count: 35, yMin: 520, yMax: 1060, len: 115 },
    { br: "HB", col: "#7c8f9e", w: 1.1, count: 30, yMin: 60, yMax: 240, len: 140 }
  ];

  for (let s of bgStrokes) {
    brush.set(s.br, s.col, s.w);
    for (let i = 0; i < s.count; i++) {
      let sx = random(50, 1150);
      let sy = random(s.yMin, s.yMax);
      // Keep the central cow-nose zone cleaner for contrast
      if (dist(sx, sy, 640, 580) < 230) continue;
      brush.flowLine(sx, sy, random(s.len * 0.5, s.len * 1.3), random(-25, 25));
    }
  }
  brush.noField();

  // Gnarled plein-air oak branches at left and right edges
  brush.wiggle(3.5);
  let oakTrunks = [
    [[160, 490], [185, 380], [235, 270], [295, 165]],
    [[235, 270], [310, 210], [385, 160]],
    [[185, 380], [120, 310], [75, 240]],
    [[1015, 470], [985, 360], [945, 250], [885, 145]],
    [[945, 250], [860, 195], [790, 155]],
    [[985, 360], [1055, 285], [1115, 215]]
  ];
  for (let tr of oakTrunks) {
    brush.set("charcoal", "#24170e", random(1.8, 3.2));
    brush.spline(tr, 0.4);
    brush.set("cpencil", "#6e8275", 0.9);
    brush.spline(tr.map(p => [p[0] - 3, p[1] - 2]), 0.4);
  }
  brush.noField();

  // Damp meadow spatter & rain-threat atmosphere
  let sprays = [
    { col: "#2a6b49", w: 1.2, n: 28 },
    { col: "#d99621", w: 1.1, n: 24 },
    { col: "#4a321d", w: 1.1, n: 22 },
    { col: "#c5d4de", w: 1.0, n: 20 }
  ];
  for (let sp of sprays) {
    brush.set("spray", sp.col, sp.w);
    for (let i = 0; i < sp.n; i++) {
      let x = random(70, 1130);
      let y = random(180, 1100);
      if (dist(x, y, 640, 580) < 260) continue;
      brush.line(x, y, x + random(-45, 45), y + random(-25, 25));
    }
  }
}

// =============================================================================
// PHASE 2: FAR GATE BRACE & COW ANATOMY BEHIND THE TOP BAR
// =============================================================================

function drawBackGateAndCowShoulders() {
  // --- A. Diagonal Gate Cross-Brace (Behind horizontal bars & cow head) ---
  let bracePts = [
    [175, 760], [205, 865], [595, 305], [510, 295]
  ];
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.4);
  brush.fill("#7d8790", 165);
  drawShapePoly(bracePts, 0.08);
  brush.fill("#4f3824", 110);
  drawShapePoly([
    [185, 780], [205, 865], [595, 305], [560, 300]
  ], 0.08);
  brush.noFill();

  // Loose wood grain on diagonal brace
  brush.set("2B", "#362517", 0.85);
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let x1 = lerp(178, 204, t);
    let y1 = lerp(762, 860, t);
    let x2 = lerp(512, 592, t);
    let y2 = lerp(298, 305, t);
    brush.line(x1, y1, x2, y2);
  }

  // --- B. Cow's Neck, Shoulders & Poll (In looser charcoal & umber washes behind the gate) ---
  brush.noStroke();
  brush.fillBleed(0.28, "out");

  // Broad dark umber body mass behind the head
  brush.fill("#26170e", 175);
  drawShapePoly(makeOrganicBlob(640, 430, 255, 240, 16, 0.14, 88), 0.3);

  // Poll / Crown of head rising above the top gate bar (y = 115..205)
  brush.fill("#1f130b", 190);
  drawShapePoly([
    [485, 210], [515, 138], [585, 118], [640, 114],
    [695, 118], [765, 135], [795, 205]
  ], 0.35);

  // White/cream crown blaze tuft on poll
  brush.fill("#dce2e6", 180);
  drawShapePoly([
    [590, 200], [608, 130], [640, 122], [672, 132], [690, 200]
  ], 0.3);
  brush.noFill();

  // Charcoal mass on cow's shoulders, neck, and poll
  brush.mass("charcoal", "#1c110a", { precision: 0.35, strength: 0.8, gradient: 0.3, outline: false });
  drawShapePoly([
    [390, 490], [435, 310], [845, 305], [890, 480], [835, 690], [445, 695]
  ], 0.25);
  brush.noMass();

  // --- C. Cow's Expressive Furry Ears (Flanking wide behind the gate) ---
  // Left Ear (x = 195..415, y = 275..415)
  let leftEarOuter = [
    [420, 325], [335, 285], [235, 282], [192, 312],
    [208, 362], [275, 405], [365, 408], [425, 378]
  ];
  let leftEarInner = [
    [405, 342], [325, 312], [240, 314], [225, 345], [285, 385], [375, 385]
  ];

  // Right Ear (x = 865..1085, y = 260..400)
  let rightEarOuter = [
    [860, 315], [945, 272], [1045, 268], [1088, 298],
    [1072, 348], [1005, 392], [915, 395], [855, 368]
  ];
  let rightEarInner = [
    [875, 332], [955, 298], [1040, 300], [1055, 332], [995, 372], [905, 372]
  ];

  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill("#24160e", 210);
  drawShapePoly(leftEarOuter, 0.3);
  drawShapePoly(rightEarOuter, 0.3);

  // Warm rose-ochre & umber inner ear cavity
  brush.fill("#8c4f3a", 155);
  drawShapePoly(leftEarInner, 0.3);
  drawShapePoly(rightEarInner, 0.3);
  brush.noFill();

  // Long backlit yellow-ochre and silvery guard hairs fringing the ears
  for (let side = -1; side <= 1; side += 2) {
    let baseX = side === -1 ? 405 : 875;
    let baseY = side === -1 ? 348 : 338;
    for (let i = 0; i < 55; i++) {
      let t = i / 54;
      let sx = baseX + side * (t * 175 + random(-10, 10));
      let sy = baseY + sin(t * 180) * 28 + random(-22, 22);
      let len = random(28, 62);
      let ang = side === -1 ? random(145, 215) : random(-35, 35);
      let ex = sx + cos(ang) * len;
      let ey = sy + sin(ang) * len;

      let col = random() < 0.45 ? "#e6b85c" : (random() < 0.6 ? "#dce3e8" : "#4a2e1b");
      brush.set("cpencil", col, random(0.6, 1.2));
      brush.spline([[sx, sy], [(sx + ex) / 2, (sy + ey) / 2 - random(4, 12)], [ex, ey]], 0.4);
    }
  }

  // Loose hairs on poll above the top bar
  for (let i = 0; i < 65; i++) {
    let px = random(500, 780);
    let py = random(120, 195);
    let isBlaze = abs(px - 640) < 42 + random(-12, 12);
    let col = isBlaze ? (random() < 0.6 ? "#e8eef2" : "#c7bba3") : (random() < 0.4 ? "#8c5322" : "#21140c");
    brush.set("cpencil", col, random(0.6, 1.1));
    let ang = -90 + (px - 640) * 0.28 + random(-18, 18);
    brush.line(px, py, px + cos(ang) * random(18, 36), py + sin(ang) * random(18, 36));
  }
}

// =============================================================================
// PHASE 3: WEATHERED, LICHEN-CRUSTED WOODEN FIELD GATE
// =============================================================================

function drawWeatheredGate() {
  // --- A. Left Vertical Stile (Gate Hanging Post: x = 58..188, y = 75..1120) ---
  let stilePts = [
    [58, 95], [95, 72], [186, 82], [190, 1110], [55, 1115]
  ];
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.65, 0.45);
  brush.fill("#7b858f", 190);
  drawShapePoly(stilePts, 0.05);

  brush.fill("#45311f", 130);
  drawShapePoly([
    [135, 80], [186, 82], [190, 1110], [130, 1110]
  ], 0.05);

  // Mossy terre-verte stain at base of stile
  brush.fill("#2b6949", 135);
  drawShapePoly(makeOrganicBlob(122, 920, 68, 160, 12, 0.25, 19), 0.3);
  brush.noFill();

  // Vertical grain on left stile
  for (let i = 0; i < 42; i++) {
    let gx = random(62, 184);
    let gy1 = random(85, 350);
    let gy2 = gy1 + random(180, 680);
    let col = random() < 0.35 ? "#2e1f14" : (random() < 0.5 ? "#a9b5bf" : "#594330");
    brush.set("2B", col, random(0.5, 1.1));
    brush.line(gx, gy1, gx + random(-4, 4), min(1105, gy2));
  }

  // --- B. Build Polygon Contours for Upper & Lower Horizontal Gate Rails ---
  let topBarPts = [];
  let topBevelPts = [];
  let botBarPts = [];
  let botBevelPts = [];

  for (let x = 48; x <= 1152; x += 24) {
    let tb = getTopBarY(x);
    topBarPts.push([x, tb.top]);
    topBevelPts.push([x, tb.top]);

    let bb = getBottomBarY(x);
    botBarPts.push([x, bb.top]);
    botBevelPts.push([x, bb.top]);
  }
  for (let x = 1152; x >= 48; x -= 24) {
    let tb = getTopBarY(x);
    topBarPts.push([x, tb.bottom]);
    topBevelPts.push([x, tb.top + 18]);

    let bb = getBottomBarY(x);
    botBarPts.push([x, bb.bottom]);
    botBevelPts.push([x, bb.top + 20]);
  }

  // Watercolour base washes on both horizontal rails
  brush.noStroke();
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.7, 0.5);

  // Silvery-umber weathered oak body
  brush.fill("#87929c", 225);
  drawShapePoly(topBarPts, 0.05);
  drawShapePoly(botBarPts, 0.05);

  // Silvery sky-lit top bevels of the rails
  brush.fill("#d4dfe6", 210);
  drawShapePoly(topBevelPts, 0.05);
  drawShapePoly(botBevelPts, 0.05);

  // Warm yellow-ochre & raw-umber heartwood weather stains along the bars
  let woodStains = [
    { col: "#523822", alpha: 145, pts: [[180, 250, 160, 42], [640, 255, 220, 45], [960, 235, 170, 42], [330, 835, 190, 48], [860, 815, 210, 46]] },
    { col: "#b57b24", alpha: 115, pts: [[410, 240, 140, 32], [790, 230, 150, 34], [520, 815, 160, 35], [740, 810, 155, 35]] },
    { col: "#2c6b4b", alpha: 120, pts: [[210, 290, 130, 24], [990, 265, 140, 25], [240, 865, 160, 28], [940, 845, 165, 28]] }
  ];
  for (let st of woodStains) {
    brush.fill(st.col, st.alpha);
    for (let i = 0; i < st.pts.length; i++) {
      let b = st.pts[i];
      drawShapePoly(makeOrganicBlob(b[0], b[1], b[2], b[3], 12, 0.22, i * 29 + b[0]), 0.25);
    }
  }
  brush.noFill();

  // --- C. Rusted Iron Strap Hinge & Latch on Left Stile ---
  let hingeY = 248;
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fill("#3d2214", 230);
  drawShapePoly([
    [52, hingeY - 18], [315, hingeY - 11], [332, hingeY + 2],
    [315, hingeY + 15], [52, hingeY + 20]
  ], 0.05);
  // Second lower iron strap
  let hingeY2 = 825;
  drawShapePoly([
    [52, hingeY2 - 18], [285, hingeY2 - 12], [302, hingeY2 + 1],
    [285, hingeY2 + 14], [52, hingeY2 + 20]
  ], 0.05);
  brush.noFill();

  // Rust texture & square bolt heads on iron straps
  for (let hy of [hingeY, hingeY2]) {
    brush.set("cpencil", "#a84a1d", 1.1);
    for (let i = 0; i < 16; i++) {
      let rx = random(58, 280);
      let ry = hy + random(-12, 12);
      brush.line(rx, ry, rx + random(12, 32), ry + random(-2, 2));
    }
    brush.set("cpencil", "#c7d4de", 0.7);
    brush.line(55, hy - 15, 295, hy - 10);
    // Square iron bolts
    for (let bx of [95, 155, 235, 285]) {
      brush.set("rotring", "#1a0d06", 1.2);
      brush.rect(bx, hy, 11, 11, "center");
      brush.set("cpencil", "#dce6ed", 0.7);
      brush.line(bx - 5, hy - 5, bx + 4, hy - 5);
    }
  }

  // --- D. Meticulous Coloured Pencil Wood Grain, Weathering Cracks & Knots ---
  // Grain sharpens into hyperreal coloured pencil in the central zone (x = 240..1020)
  for (let rail = 0; rail < 2; rail++) {
    let sampleBar = rail === 0 ? getTopBarY(600) : getBottomBarY(600);
    let numLines = 78;

    for (let i = 0; i < numLines; i++) {
      let frac = i / (numLines - 1);
      let baseY = lerp(sampleBar.top + 3, sampleBar.bottom - 3, frac);

      // Break each grain line into segments with denser sharpness near the center
      let xStart = random(55, 140);
      let xEnd = random(1060, 1145);
      let step = 28;
      let pts = [];
      for (let x = xStart; x <= xEnd; x += step) {
        let gy = getWoodGrainY(x, baseY, rail);
        pts.push([x, gy]);
      }

      // Choose wood grain colour: silver-grey, deep raw umber, warm ochre, or bright sky highlight
      let col;
      let w;
      let brName;
      if (frac < 0.16) {
        // Silvery top bevel catching overcast sky light
        col = random() < 0.6 ? "#eef4f7" : "#a3b2bf";
        w = random(0.45, 0.85);
        brName = "cpencil";
      } else if (frac > 0.86) {
        // Dark damp underside of rail
        col = random() < 0.7 ? "#21150c" : "#3b2818";
        w = random(0.65, 1.15);
        brName = "cpencil";
      } else {
        let r = random();
        if (r < 0.32) {
          col = "#332214";
          w = random(0.4, 0.8);
          brName = "cpencil";
        } else if (r < 0.58) {
          col = "#63707a";
          w = random(0.45, 0.85);
          brName = "2H";
        } else if (r < 0.80) {
          col = "#c9d4dc";
          w = random(0.4, 0.75);
          brName = "cpencil";
        } else {
          col = "#9e6b24";
          w = random(0.45, 0.8);
          brName = "cpencil";
        }
      }

      brush.set(brName, col, w);
      brush.spline(pts, 0.3);
    }

    // Deep seasoned oak checks / longitudinal splits with crisp upper-edge silver highlights
    let splits = rail === 0
      ? [
          { x1: 210, x2: 495, frac: 0.38 },
          { x1: 460, x2: 790, frac: 0.62 },
          { x1: 720, x2: 1040, frac: 0.32 },
          { x1: 310, x2: 610, frac: 0.18 }
        ]
      : [
          { x1: 195, x2: 520, frac: 0.45 },
          { x1: 480, x2: 830, frac: 0.68 },
          { x1: 760, x2: 1080, frac: 0.36 },
          { x1: 350, x2: 690, frac: 0.24 }
        ];

    for (let sp of splits) {
      let sBar = rail === 0 ? getTopBarY(600) : getBottomBarY(600);
      let by = lerp(sBar.top, sBar.bottom, sp.frac);
      let darkPts = [];
      let lightPts = [];
      for (let x = sp.x1; x <= sp.x2; x += 20) {
        let gy = getWoodGrainY(x, by, rail) + (noise(x * 0.05, sp.frac * 10) - 0.5) * 4;
        darkPts.push([x, gy]);
        lightPts.push([x, gy + 2.2]);
      }
      brush.set("rotring", "#170e08", 1.15);
      brush.spline(darkPts, 0.35);
      brush.set("cpencil", "#3d2716", 0.9);
      brush.spline(darkPts, 0.35);
      brush.set("cpencil", "#e6eef2", 0.65);
      brush.spline(lightPts, 0.35);
    }
  }

  // Detailed concentric knot rings on the rails
  let allKnots = [
    { kx: 285, ky: 252, rx: 28, ry: 16 },
    { kx: 540, ky: 225, rx: 18, ry: 11 },
    { kx: 935, ky: 228, rx: 32, ry: 18 },
    { kx: 335, ky: 825, rx: 34, ry: 19 },
    { kx: 660, ky: 838, rx: 24, ry: 14 },
    { kx: 965, ky: 802, rx: 28, ry: 16 }
  ];

  for (let k of allKnots) {
    for (let ring = 1.0; ring >= 0.2; ring -= 0.22) {
      let pts = makeOrganicBlob(k.kx, k.ky, k.rx * ring, k.ry * ring, 14, 0.12, k.kx + ring * 10);
      brush.set("cpencil", ring < 0.45 ? "#1a1009" : "#422c1a", ring < 0.45 ? 1.1 : 0.65);
      drawShapePoly(pts, 0.35);
    }
    // Radial checks inside knot core
    brush.set("rotring", "#120a05", 0.8);
    for (let a = 0; a < 360; a += 60) {
      brush.line(k.kx, k.ky, k.kx + cos(a) * k.rx * 0.45, k.ky + sin(a) * k.ry * 0.45);
    }
  }

  // --- E. Vivid Crustose & Foliose Lichen Colonies on the Gate Bars ---
  drawGateLichens();
}

function drawGateLichens() {
  // Colonies of Xanthoria parietina (golden-orange sunburst) and Parmelia (sage-turquoise foliose)
  let colonies = [
    // Upper bar colonies
    { x: 245, rail: 0, yOff: 8, rx: 46, ry: 14, type: "gold" },
    { x: 355, rail: 0, yOff: 16, rx: 58, ry: 18, type: "sage" },
    { x: 445, rail: 0, yOff: 6, rx: 38, ry: 12, type: "gold" },
    { x: 785, rail: 0, yOff: 12, rx: 52, ry: 16, type: "sage" },
    { x: 875, rail: 0, yOff: 7, rx: 48, ry: 15, type: "gold" },
    { x: 1015, rail: 0, yOff: 18, rx: 55, ry: 17, type: "sage" },
    // Lower bar colonies (framing the cow's wet nose & chin!)
    { x: 265, rail: 1, yOff: 10, rx: 52, ry: 16, type: "sage" },
    { x: 385, rail: 1, yOff: 8, rx: 64, ry: 19, type: "gold" },
    { x: 465, rail: 1, yOff: 22, rx: 48, ry: 16, type: "sage" },
    { x: 795, rail: 1, yOff: 9, rx: 62, ry: 18, type: "gold" },
    { x: 885, rail: 1, yOff: 24, rx: 54, ry: 17, type: "sage" },
    { x: 1005, rail: 1, yOff: 11, rx: 48, ry: 15, type: "gold" },
    // Left stile colonies
    { x: 125, rail: -1, yAbs: 440, rx: 32, ry: 45, type: "sage" },
    { x: 110, rail: -1, yAbs: 620, rx: 28, ry: 38, type: "gold" }
  ];

  // 1. Watercolour & dry-mass base for lichen colonies
  for (let i = 0; i < colonies.length; i++) {
    let c = colonies[i];
    let cy = c.rail === -1
      ? c.yAbs
      : (c.rail === 0 ? getTopBarY(c.x).top : getBottomBarY(c.x).top) + c.yOff;
    c.cy = cy;

    let baseCol = c.type === "gold" ? "#e89218" : "#4ca382";
    let massCol = c.type === "gold" ? "#f7b934" : "#76cfb0";

    brush.noStroke();
    brush.fillBleed(0.12, "out");
    brush.fill(baseCol, 175);
    drawShapePoly(makeOrganicBlob(c.x, cy, c.rx, c.ry, 14, 0.32, i * 19), 0.35);
    brush.noFill();

    brush.mass("cpencil", massCol, { precision: 0.65, strength: 0.55, gradient: 0.25, outline: false });
    drawShapePoly(makeOrganicBlob(c.x, cy, c.rx * 0.82, c.ry * 0.82, 12, 0.28, i * 23 + 5), 0.35);
    brush.noMass();
  }

  // 2. Meticulous Coloured Pencil Scalloped Thalli & Apothecia Cups
  for (let i = 0; i < colonies.length; i++) {
    let c = colonies[i];
    let numLobes = floor(map(c.rx, 28, 64, 26, 52));

    for (let j = 0; j < numLobes; j++) {
      let ang = random(360);
      let distFrac = sqrt(random());
      let lx = c.x + cos(ang) * c.rx * distFrac;
      let ly = c.cy + sin(ang) * c.ry * distFrac;
      let lobeR = random(3.5, 7.5) * (1.15 - distFrac * 0.4);

      // Dark underside shadow of crustose/foliose lobe
      brush.set("cpencil", c.type === "gold" ? "#59330c" : "#1c4032", 0.55);
      brush.arc(lx, ly + 1.2, lobeR, 15, 165);

      // Vivid coloured pencil lobe body
      let lobeCol = c.type === "gold"
        ? (random() < 0.5 ? "#ffbe2e" : (random() < 0.5 ? "#f08316" : "#ffe270"))
        : (random() < 0.5 ? "#66c7a6" : (random() < 0.5 ? "#388c6f" : "#b2ebd7"));
      brush.set("cpencil", lobeCol, 0.7);
      brush.circle(lx, ly, lobeR * 0.75, 0.25);

      // Crisp pale thallus rim or dark apothecia fruiting center
      if (distFrac < 0.55 && random() < 0.45) {
        // Tiny saucer-shaped apothecium cup
        brush.set("rotring", c.type === "gold" ? "#b84a0e" : "#3d291a", 0.5);
        brush.circle(lx, ly, lobeR * 0.38, 0.15);
      } else {
        // Silvery-white pruinose rim highlight
        brush.set("cpencil", c.type === "gold" ? "#fff3b8" : "#e6f7f1", 0.45);
        brush.arc(lx, ly, lobeR * 0.85, 200, 340);
      }
    }
  }
}

// =============================================================================
// PHASE 4: COW FOREHEAD, SOULFUL EYES, CHEEKS & FURRY NASAL BRIDGE
// =============================================================================

function drawCowHeadAndEyes() {
  // --- A. Cast Shadow of Upper Gate Bar Across Cow's Forehead (y = 302..358) ---
  brush.noStroke();
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.5, 0.3);

  // Rich umber/slate head base emerging below top bar
  brush.fill("#21140c", 220);
  drawShapePoly([
    [415, 305], [865, 295], [855, 425], [815, 505],
    [465, 510], [425, 430]
  ], 0.25);

  // Warm rufous-ochre and raw umber cheek highlights
  brush.fill("#7a461d", 145);
  drawShapePoly(makeOrganicBlob(475, 445, 58, 65, 12, 0.2, 41), 0.3);
  drawShapePoly(makeOrganicBlob(805, 438, 58, 65, 12, 0.2, 53), 0.3);

  // White forehead blaze narrowing down the bridge of the nose
  let blazePts = [
    [575, 304], [705, 298], [692, 385], [682, 460],
    [705, 495], [575, 498], [598, 460], [588, 385]
  ];
  brush.fill("#ced8de", 195);
  drawShapePoly(blazePts, 0.28);

  // Brighter cream-white center of the blaze below the bar shadow
  brush.fill("#edf2f5", 205);
  drawShapePoly([
    [596, 352], [684, 348], [676, 445], [688, 488],
    [592, 490], [604, 445]
  ], 0.28);

  // Cool shadow cast by the upper wooden bar across the brow (y = 300..352)
  brush.fill("#1c242e", 135);
  drawShapePoly([
    [412, 304], [868, 294], [862, 348], [418, 356]
  ], 0.1);
  brush.noFill();

  // --- B. Directional Coloured Pencil Hair Coat with Central Forehead Whorl ---
  // Anatomical spiral cowlick centered at (640, 392)
  let whorlX = 640;
  let whorlY = 392;

  for (let i = 0; i < 620; i++) {
    let hx = random(420, 860);
    let hy = random(306, 515);

    // Exclude the hairless wet muzzle below y = 485
    if (hy > 480 && isInsideMuzzle(hx, hy)) continue;

    // Exclude eye sockets so eyes stay crisp
    if (dist(hx, hy, 452, 382) < 34 || dist(hx, hy, 828, 372) < 34) continue;

    // Compute radial + spiral hair direction from the central whorl
    let dx = hx - whorlX;
    let dy = hy - whorlY;
    let d = sqrt(dx * dx + dy * dy);
    let radialAng = atan2(dy, dx);
    let spiralTwist = 28 * exp(-d / 65);
    // Lower down on the bridge, hair flows downward toward the nostrils
    let bridgeFlow = hy > 420 ? map(hy, 420, 510, 0, 1) : 0;
    let targetDown = 90 + (hx - 640) * 0.18;
    let ang = lerp(radialAng + spiralTwist, targetDown, bridgeFlow) + random(-8, 8);

    let hairLen = map(constrain(d, 8, 180), 8, 180, 9, 24) * random(0.75, 1.25);
    let ex = hx + cos(ang) * hairLen;
    let ey = hy + sin(ang) * hairLen;

    // Determine hair colour from blaze vs dark umber vs golden-ochre cheek fringe
    let inBlaze = abs(hx - 640) < map(hy, 305, 495, 62, 46) + (noise(hx * 0.05, hy * 0.05) - 0.5) * 28;
    let inShadow = hy < 346;

    let col;
    if (inBlaze) {
      if (inShadow) {
        col = random() < 0.6 ? "#8b9cab" : "#b0bfc9";
      } else {
        col = random() < 0.55 ? "#f2f6f9" : (random() < 0.6 ? "#d5dfe6" : "#e8d6b3");
      }
    } else {
      let edgeDist = abs(hx - 640);
      if (edgeDist > 145 && random() < 0.42) {
        col = random() < 0.5 ? "#b87424" : "#d99b38";
      } else {
        col = random() < 0.5 ? "#170e09" : (random() < 0.6 ? "#331f13" : "#54341e");
      }
    }

    brush.set("cpencil", col, random(0.45, 0.85));
    brush.spline([
      [hx, hy],
      [(hx + ex) * 0.5 + random(-2, 2), (hy + ey) * 0.5 + random(-2, 2)],
      [ex, ey]
    ], 0.35);
  }

  // --- C. The Cow's Wide-Set, Glistening Soulful Eyes ---
  drawCowEye(452, 382, -1);
  drawCowEye(828, 372, 1);
}

function drawCowEye(ex, ey, side) {
  // Bony orbital arch & wrinkled eyelid folds
  brush.noStroke();
  brush.fillBleed(0.1, "in");
  brush.fill("#140c08", 235);
  drawShapePoly(makeOrganicBlob(ex, ey, 34, 24, 12, 0.12, ex), 0.3);

  // Glossy dark obsidian-amber eyeball
  brush.fill("#1f100a", 245);
  drawShapePoly(makeOrganicBlob(ex + side * 2, ey + 1, 21, 16, 12, 0.06, ex + 7), 0.35);
  brush.noFill();

  // Coloured pencil sculpting of upper and lower eyelids
  for (let fold = 0; fold < 3; fold++) {
    let r = 24 + fold * 5.5;
    brush.set("cpencil", fold === 0 ? "#0d0705" : "#4a3222", 0.75);
    brush.arc(ex, ey + 2, r, 195, 345);
    brush.set("cpencil", "#7d8f9e", 0.5);
    brush.arc(ex, ey + 0.5, r, 205, 335);
  }

  // Deep pupil (horizontal oval characteristic of cattle) and warm amber iris rim
  brush.set("cpencil", "#5e3319", 0.85);
  brush.circle(ex + side * 2, ey + 1, 15, 0.08);
  brush.set("rotring", "#090403", 1.3);
  brush.circle(ex + side * 2, ey + 1, 9, 0.08);

  // Wet pink-terracotta medial tear caruncle
  let tearX = ex - side * 19;
  let tearY = ey + 4;
  brush.set("cpencil", "#b54f45", 1.1);
  brush.circle(tearX, tearY, 3.5, 0.15);
  brush.set("cpencil", "#e8eff5", 0.55);
  brush.circle(tearX, tearY - 1, 1.5, 0.1);

  // Silvery overcast sky reflection arc across the wet cornea
  brush.set("cpencil", "#a8c7db", 1.15);
  brush.arc(ex + side * 3, ey - 2, 11, 215, 325);
  brush.set("cpencil", "#ffffff", 1.1);
  brush.arc(ex + side * 3, ey - 3, 9.5, 230, 310);
  brush.line(ex + side * 6, ey - 8, ex + side * 1, ey - 8);

  // Moist lower eyelid rim highlight
  brush.set("cpencil", "#cde0ec", 0.65);
  brush.arc(ex + side * 1, ey + 2, 18, 25, 155);

  // Straight, downward-curving pale golden-ochre and silver bovine eyelashes
  for (let i = 0; i < 16; i++) {
    let t = i / 15;
    let ang = lerp(205, 335, t);
    let lx = ex + cos(ang) * 21;
    let ly = ey + sin(ang) * 15;
    let lashAng = side === -1 ? lerp(135, 75, t) : lerp(105, 45, t);
    let lashLen = random(14, 24) * sin(t * 180 + 15);
    let tx = lx + cos(lashAng) * lashLen;
    let ty = ly + sin(lashAng) * lashLen + 4;

    brush.set("cpencil", "#1a1009", 0.5);
    brush.line(lx, ly + 1, tx, ty + 1);
    brush.set("cpencil", random() < 0.6 ? "#e8cfa0" : "#dde6ed", 0.65);
    brush.spline([[lx, ly], [(lx + tx) * 0.5, (ly + ty) * 0.5 + 2], [tx, ty]], 0.3);
  }
}

// =============================================================================
// PHASE 5: HYPERREAL DEW-WET COW'S NOSE & MUZZLE (COLOURED PENCIL MASTERWORK)
// =============================================================================

function drawHyperrealWetNose() {
  // --- A. Cast Shadow of the Muzzle & Chin Onto the Lower Gate Bar (y = 745..845) ---
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.35);

  brush.fill("#1d140e", 165);
  drawShapePoly([
    [465, 755], [815, 745], [835, 815], [720, 838],
    [560, 842], [445, 818]
  ], 0.3);

  brush.fill("#120b07", 190);
  drawShapePoly([
    [495, 752], [785, 744], [770, 798], [510, 802]
  ], 0.28);

  // --- B. Wet Lower Lip & Tufted Chin Pressing Over the Lower Gate Bar ---
  // Fleshy wet lower lip & chin pad (y = 720..785)
  brush.fill("#2b1e1b", 225);
  drawShapePoly([
    [485, 718], [795, 715], [775, 772], [640, 786], [505, 774]
  ], 0.32);

  // Warm coral-rose & terracotta mottled lower lip rim
  brush.fill("#b85248", 185);
  drawShapePoly([
    [515, 725], [765, 722], [748, 754], [640, 762], [532, 755]
  ], 0.3);

  // --- C. Underpainting of the Bulbous Dew-Wet Muzzle (Planum Nasolabiale) ---
  // Collect outer contour of the muzzle
  let muzzleContour = [];
  for (let a = 0; a < 360; a += 8) {
    let radX = 196;
    let radY = 136;
    let x = 640 + cos(a) * radX;
    let y = 606 + sin(a) * radY;
    // Refine to exact boundary
    for (let s = 1.15; s >= 0.7; s -= 0.02) {
      let tx = 640 + cos(a) * radX * s;
      let ty = 606 + sin(a) * radY * s;
      if (isInsideMuzzle(tx, ty)) {
        x = tx;
        y = ty;
        break;
      }
    }
    muzzleContour.push([x, y]);
  }

  // Deep slate-plum-umber base wash of the muzzle
  brush.fillBleed(0.1, "in");
  brush.fill("#23202b", 235);
  drawShapePoly(muzzleContour, 0.3);

  // Vivid warm terracotta-rose & coral-ochre mottled pigmentation zones
  let pinkZones = [
    // Lower central philtrum & upper lip
    [640, 682, 82, 52],
    // Bridge blaze transition at top center of nose
    [640, 496, 56, 26],
    // Left and right medial nostril folds
    [552, 592, 36, 42],
    [728, 588, 36, 42],
    // Spotted organic blotches
    [575, 650, 32, 26],
    [708, 645, 34, 28],
    [482, 635, 24, 22],
    [795, 630, 25, 22]
  ];
  brush.fillBleed(0.18, "in");
  brush.fill("#c75b4f", 185);
  for (let i = 0; i < pinkZones.length; i++) {
    let pz = pinkZones[i];
    drawShapePoly(makeOrganicBlob(pz[0], pz[1], pz[2], pz[3], 12, 0.22, i * 37), 0.35);
  }

  // Lighter fleshy rose-ochre inner glow on mottled skin
  brush.fill("#e68a7c", 145);
  drawShapePoly(makeOrganicBlob(640, 692, 62, 36, 12, 0.2, 91), 0.35);
  drawShapePoly(makeOrganicBlob(554, 592, 24, 30, 10, 0.2, 92), 0.35);
  drawShapePoly(makeOrganicBlob(726, 588, 24, 30, 10, 0.2, 93), 0.35);

  // Cool silvery-blue overcast sky sheen wash across the upper dome & alar wings
  brush.fill("#9bbbd1", 130);
  drawShapePoly(makeOrganicBlob(600, 548, 72, 46, 12, 0.18, 101), 0.35);
  drawShapePoly(makeOrganicBlob(680, 545, 72, 46, 12, 0.18, 102), 0.35);
  drawShapePoly(makeOrganicBlob(482, 558, 32, 42, 10, 0.18, 103), 0.35);
  drawShapePoly(makeOrganicBlob(798, 552, 32, 42, 10, 0.18, 104), 0.35);
  brush.noFill();

  // --- D. Meticulous Coloured Pencil Pebbled Skin Mosaic & Exact Gland Pores ---
  // Generate jittered hexagonal grid of glandular skin pads (dermatoglyphics) across the muzzle
  let rowSpacing = 9.2;
  let colSpacing = 10.4;

  for (let y = 474; y <= 736; y += rowSpacing) {
    let rowIdx = floor((y - 474) / rowSpacing);
    let xOffset = (rowIdx % 2) * (colSpacing * 0.5);

    for (let x = 442 + xOffset; x <= 838; x += colSpacing) {
      let px = x + (noise(x * 0.12, y * 0.12) - 0.5) * 4.2;
      let py = y + (noise(x * 0.12 + 50, y * 0.12 + 50) - 0.5) * 4.2;

      if (!isInsideMuzzle(px, py)) continue;
      let nDepth = getNostrilDepth(px, py);
      if (nDepth > 0.12) continue; // Nostril cavities rendered separately

      let norm = getMuzzleNormal(px, py);
      let nx = norm[0];
      let ny = norm[1];
      let nz = norm[2];

      let pigment = getMuzzlePigment(px, py); // 0 = dark slate-obsidian, 1 = warm coral-rose

      // Overhead silvery sky light vector: slightly from top-left [ -0.15, -0.62, 0.77 ]
      let lightDot = constrain(nx * -0.15 + ny * -0.62 + nz * 0.77, 0, 1);
      // Specular reflection for wet mucous sheen
      let specDot = pow(constrain(nx * -0.1 + ny * -0.52 + nz * 0.85, 0, 1), 6);

      // Pebble radius scales slightly (smaller near nostrils & lip margin, larger on central pad)
      let distToNostril = min(dist(px, py, 520, 580), dist(px, py, 760, 575));
      let cellR = constrain(map(distToNostril, 35, 110, 3.4, 5.2), 3.4, 5.2);
      if (py > 695) cellR *= 0.82;

      // Build 6-sided polygonal pebble vertices
      let polyPts = [];
      for (let k = 0; k < 6; k++) {
        let ang = k * 60 + 15 + (noise(px * 0.1 + k, py * 0.1) - 0.5) * 22;
        let r = cellR * (0.85 + noise(px * 0.2, py * 0.2, k) * 0.3);
        polyPts.push([px + cos(ang) * r, py + sin(ang) * r]);
      }

      // 1. Recessed micro-groove (sulcus) around the polygonal skin pad
      let grooveCol = pigment > 0.5
        ? (lightDot > 0.55 ? "#7a2e26" : "#4a1814")
        : (lightDot > 0.55 ? "#1c1a24" : "#0e0b10");
      brush.set("cpencil", grooveCol, 0.42);
      drawShapePoly(polyPts, 0.2);

      // 2. Coloured pencil shading on the convex crown of the pebble
      let crownCol;
      if (pigment > 0.5) {
        // Warm terracotta / coral-rose wet skin
        if (specDot > 0.48) {
          crownCol = "#f0c4c0";
        } else if (lightDot > 0.62) {
          crownCol = "#e38376";
        } else if (lightDot > 0.38) {
          crownCol = "#bf5649";
        } else {
          crownCol = "#803028";
        }
      } else {
        // Dark slate-obsidian / indigo-umber wet skin
        if (specDot > 0.48) {
          crownCol = "#9bb8cc";
        } else if (lightDot > 0.62) {
          crownCol = "#495869";
        } else if (lightDot > 0.38) {
          crownCol = "#282c38";
        } else {
          crownCol = "#16141c";
        }
      }

      brush.set("cpencil", crownCol, 0.65);
      brush.arc(px, py - 0.4, cellR * 0.62, 190, 355);
      brush.line(px - cellR * 0.45, py + 0.3, px + cellR * 0.45, py + 0.3);

      // 3. Exact central nasolabial gland pore inside each polygonal pad
      let poreX = px + (noise(px, py) - 0.5) * 1.4;
      let poreY = py + (noise(py, px) - 0.5) * 1.4;
      let poreCol = pigment > 0.5 ? "#3d120e" : "#09070a";
      brush.set("rotring", poreCol, 0.55);
      brush.circle(poreX, poreY, 0.95, 0.1);

      // 4. Individual wet silvery specular glint on upper pebble facet & lower pore rim
      if (specDot > 0.36 || (lightDot > 0.58 && random() < 0.65)) {
        let glintCol = specDot > 0.58 ? "#ffffff" : "#cde2f0";
        brush.set("cpencil", glintCol, specDot > 0.58 ? 0.6 : 0.45);
        brush.arc(px - 0.3, py - 0.8, cellR * 0.55, 210, 330);
      } else if (lightDot < 0.35 && py > 660) {
        // Warm reflected bounce light from the golden lichen gate bar below!
        brush.set("cpencil", "#b87b3b", 0.42);
        brush.arc(px, py + 0.8, cellR * 0.52, 25, 155);
      }
    }
  }

  // --- E. Deep Glistening Nostrils (Cavernous Core, Crimson Mucosa & Rolled Wet Rims) ---
  drawGlisteningNostril(520, 580, -1);
  drawGlisteningNostril(760, 575, 1);

  // --- F. Central Philtrum Crease & Moist Mouth Cleft Detail ---
  brush.set("cpencil", "#451815", 0.85);
  brush.spline([[640, 525], [639, 610], [640, 685], [640, 736]], 0.3);
  brush.set("cpencil", "#e6f2f7", 0.55);
  brush.spline([[642.5, 535], [642, 615], [642.5, 680]], 0.3);

  // Dark shadowed mouth cleft under the overhanging upper lip
  let mouthPts = [
    [482, 712], [555, 734], [640, 740], [725, 732], [798, 708]
  ];
  brush.set("charcoal", "#120807", 1.6);
  brush.spline(mouthPts, 0.35);
  brush.set("rotring", "#080303", 1.2);
  brush.spline(mouthPts, 0.35);

  // Wet saliva/moisture sheen along the lower lip margin
  brush.set("cpencil", "#f2aba0", 0.85);
  brush.spline([[520, 740], [580, 748], [640, 751], [700, 746], [760, 738]], 0.35);
  brush.set("cpencil", "#ffffff", 0.75);
  brush.spline([[545, 743], [605, 749], [665, 749], [730, 741]], 0.35);

  // Dense damp chin hairs pressing directly against the top edge of the lower gate bar
  for (let i = 0; i < 165; i++) {
    let cx = random(485, 795);
    let cy = random(744, 782);
    let distCenter = abs(cx - 640);
    if (cy > 786 - (distCenter * distCenter) * 0.0012) continue;

    let len = random(14, 32);
    let ang = 90 + (cx - 640) * 0.22 + random(-18, 18);
    let ex = cx + cos(ang) * len;
    let ey = cy + sin(ang) * len;

    let col = random() < 0.45 ? "#f0ead8" : (random() < 0.5 ? "#c99b49" : "#3b2618");
    brush.set("cpencil", col, random(0.45, 0.85));
    brush.spline([[cx, cy], [(cx + ex) * 0.5, (cy + ey) * 0.5 + 2], [ex, ey]], 0.3);
  }
}

function drawGlisteningNostril(nx, ny, side) {
  // Build comma-shaped nostril contour points
  let cavityPts = [];
  let innerMucosaPts = [];
  let outerRimPts = [];

  for (let a = 0; a < 360; a += 12) {
    let lx = cos(a) * 33;
    let ly = sin(a) * 53;
    let curveX = lx + side * 0.0065 * ly * ly;
    let rotAng = side * 28;
    let wx = nx + curveX * cos(rotAng) - ly * sin(rotAng);
    let wy = ny + curveX * sin(rotAng) + ly * cos(rotAng);
    cavityPts.push([wx, wy]);

    // Slightly wider rim for wet highlight sculpting
    let rwx = nx + curveX * 1.18 * cos(rotAng) - ly * 1.14 * sin(rotAng);
    let rwy = ny + curveX * 1.18 * sin(rotAng) + ly * 1.14 * cos(rotAng);
    outerRimPts.push([rwx, rwy]);
  }

  // Medial crimson-terracotta nasal fold inside the nostril opening
  for (let a = -75; a <= 85; a += 15) {
    let lx = -side * cos(a) * 22 + side * 4;
    let ly = sin(a) * 42 + 4;
    let rotAng = side * 28;
    let wx = nx + lx * cos(rotAng) - ly * sin(rotAng);
    let wy = ny + lx * sin(rotAng) + ly * cos(rotAng);
    innerMucosaPts.push([wx, wy]);
  }

  brush.noStroke();
  brush.fillBleed(0.08, "in");

  // Deepest obsidian-umber nasal passage
  brush.fill("#0d0707", 250);
  drawShapePoly(cavityPts, 0.35);

  // Translucent warm crimson-rose mucosal membrane on medial wall
  brush.fill("#a6332b", 210);
  drawShapePoly(innerMucosaPts, 0.35);
  brush.noFill();

  // Coloured pencil burnishing inside nostril & across the rolled alar cartilage rim
  for (let s = 0.95; s >= 0.35; s -= 0.15) {
    let ring = cavityPts.map(p => [lerp(nx - side * 6, p[0], s), lerp(ny - 6, p[1], s)]);
    brush.set("cpencil", s > 0.65 ? "#291210" : "#080404", 0.95);
    drawShapePoly(ring, 0.35);
  }

  // Glowing rose-coral highlight on the inner mucosal fold
  brush.set("cpencil", "#e66e60", 0.9);
  brush.spline(innerMucosaPts.slice(2, 9), 0.35);
  brush.set("cpencil", "#f7b6ad", 0.65);
  brush.spline(innerMucosaPts.slice(3, 8), 0.35);

  // Intense wet silvery-cyan sky reflection curving around the fleshy outer & lower nostril rim
  for (let i = 0; i < outerRimPts.length; i++) {
    let p1 = outerRimPts[i];
    let p2 = outerRimPts[(i + 1) % outerRimPts.length];
    let dy = p1[1] - ny;
    let dx = (p1[0] - nx) * side;

    // Upper-outer alar wing & lower-inner notch catch brilliant sky reflections
    if ((dx > 5 && dy < 15) || (dy > 24 && abs(dx) < 28)) {
      brush.set("cpencil", "#b8d6e8", 1.1);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.set("cpencil", "#ffffff", 0.75);
      brush.line(p1[0] - side * 1.2, p1[1] - 1, p2[0] - side * 1.2, p2[1] - 1);
    }
  }

  // Glistening pooling moisture bead at the bottom notch of the nostril
  let notchX = nx - side * 8;
  let notchY = ny + 46;
  drawDewDrop(notchX, notchY, 6.2, true);
  drawDewDrop(notchX + side * 11, notchY + 5, 4.2, true);
}

// =============================================================================
// PHASE 6: EXACT WHISKERS (VIBRISSAE), FOLLICLE PORES & DEW DROPS
// =============================================================================

function drawWhiskersAndDew() {
  // --- A. Dew & Sweat Beads Across the Wet Nose Dome, Lip & Gate Bar ---
  let dewLocations = [];

  // Scatter natural dew beads emerging from nasolabial pores across the nose
  for (let i = 0; i < 58; i++) {
    let dx = random(455, 825);
    let dy = random(490, 732);
    if (!isInsideMuzzle(dx, dy)) continue;
    if (getNostrilDepth(dx, dy) > 0.05) continue;
    let r = random(1.8, 4.8) * (dy > 660 ? 1.25 : 1.0);
    dewLocations.push({ x: dx, y: dy, r, onPink: getMuzzlePigment(dx, dy) > 0.5 });
  }

  // Hanging dew / saliva droplets along the chin hairs and on the top bevel of the lower gate bar
  let chinDrops = [
    { x: 545, y: 768, r: 5.2, onPink: true },
    { x: 595, y: 778, r: 6.4, onPink: true },
    { x: 640, y: 784, r: 7.0, onPink: true },
    { x: 682, y: 776, r: 5.8, onPink: true },
    { x: 735, y: 765, r: 4.8, onPink: true },
    // Dew beads sitting on the weathered oak & lichen of the gate bars
    { x: 365, y: getBottomBarY(365).top + 6, r: 4.2, onPink: false },
    { x: 425, y: getBottomBarY(425).top + 8, r: 5.0, onPink: false },
    { x: 825, y: getBottomBarY(825).top + 7, r: 5.2, onPink: false },
    { x: 890, y: getBottomBarY(890).top + 6, r: 4.0, onPink: false }
  ];
  for (let cd of chinDrops) dewLocations.push(cd);

  for (let d of dewLocations) {
    drawDewDrop(d.x, d.y, d.r, d.onPink);
  }

  // --- B. Exact Whisker Follicle Pores & Tactile Vibrissae ---
  let whiskerRoots = [];

  // Lateral muzzle wings (left: x = 432..495, right: x = 785..848, y = 515..710)
  for (let side = -1; side <= 1; side += 2) {
    for (let row = 0; row < 6; row++) {
      for (let col = 0; col < 4; col++) {
        let wy = 525 + row * 31 + random(-6, 6);
        let baseEdgeX = side === -1 ? 478 : 802;
        let wx = baseEdgeX + side * (col * 12 - row * 2.5 + random(-5, 5));
        let len = map(row, 0, 5, 42, 95) * map(col, 0, 3, 0.75, 1.2) * random(0.85, 1.15);
        let baseAng = side === -1 ? lerp(155, 115, row / 5) : lerp(25, 65, row / 5);
        whiskerRoots.push({ x: wx, y: wy, len, ang: baseAng + random(-12, 12), side, weight: random(0.65, 1.05) });
      }
    }
  }

  // Upper lip margin & chin vibrissae
  for (let i = 0; i < 34; i++) {
    let wx = random(480, 800);
    let isUpperLip = i < 18;
    let wy = isUpperLip ? random(692, 728) : random(742, 776);
    // Avoid central philtrum pad where cattle have fewer long vibrissae
    if (isUpperLip && abs(wx - 640) < 48) continue;
    let side = wx < 640 ? -1 : 1;
    let len = random(35, 78);
    let ang = 90 + side * map(abs(wx - 640), 20, 160, 12, 48) + random(-14, 14);
    whiskerRoots.push({ x: wx, y: wy, len, ang, side, weight: random(0.55, 0.9) });
  }

  // Supraorbital (eyebrow) tactile vibrissae above both eyes
  for (let side = -1; side <= 1; side += 2) {
    let bx = side === -1 ? 458 : 822;
    let by = side === -1 ? 352 : 342;
    for (let k = 0; k < 5; k++) {
      whiskerRoots.push({
        x: bx + (k - 2) * 8 + random(-2, 2),
        y: by + random(-4, 4),
        len: random(48, 82),
        ang: (side === -1 ? 215 : -35) + (k - 2) * 8,
        side,
        weight: 0.7
      });
    }
  }

  // Render every follicle pore and whisker shaft
  for (let i = 0; i < whiskerRoots.length; i++) {
    let w = whiskerRoots[i];

    // 1. Raised fleshy follicle collar & deep dark pore socket
    brush.set("cpencil", "#6e3b32", 0.75);
    brush.circle(w.x, w.y, 2.8, 0.15);
    brush.set("rotring", "#120908", 0.85);
    brush.circle(w.x, w.y, 1.5, 0.1);
    brush.set("cpencil", "#cde0eb", 0.45);
    brush.arc(w.x, w.y, 2.8, 200, 340);

    // Compute curved 4-point spline for the whisker with natural gravity droop
    let p0 = [w.x, w.y];
    let a1 = w.ang;
    let a2 = w.ang + w.side * 12 + (w.y > 500 ? 14 : -8);
    let a3 = w.ang + w.side * 22 + (w.y > 500 ? 28 : -15);

    let p1 = [w.x + cos(a1) * (w.len * 0.33), w.y + sin(a1) * (w.len * 0.33)];
    let p2 = [p1[0] + cos(a2) * (w.len * 0.33), p1[1] + sin(a2) * (w.len * 0.33)];
    let p3 = [p2[0] + cos(a3) * (w.len * 0.34), p2[1] + sin(a3) * (w.len * 0.34)];

    // 2. Subtle dark under-shadow so the whisker stands out in crisp relief
    brush.set("cpencil", "#1c130e", w.weight * 0.75);
    brush.spline([
      [p0[0] + 1, p0[1] + 1.5],
      [p1[0] + 1.2, p1[1] + 1.8],
      [p2[0] + 1.2, p2[1] + 1.8],
      [p3[0] + 1, p3[1] + 1.5]
    ], 0.4);

    // 3. Glistening translucent whisker shaft (warm golden-cream base tapering to silver-white tip)
    let shaftCol = i % 3 === 0 ? "#ffffff" : (i % 3 === 1 ? "#f5e6c4" : "#d8e6f0");
    brush.set("cpencil", shaftCol, w.weight);
    brush.spline([p0, p1, p2, p3], 0.4);

    // 4. Fine micro-highlight along the upper curve of thick whiskers
    if (w.weight > 0.78) {
      brush.set("2H", "#ffffff", 0.45);
      brush.spline([p0, p1, p2], 0.4);
    }

    // 5. Micro-beads of silver dew clinging directly to whiskers
    if (w.len > 52 && random() < 0.48) {
      let numBeads = floor(random(1, 3.2));
      for (let b = 1; b <= numBeads; b++) {
        let bt = b === 1 ? 0.42 : 0.74;
        let bx = bt < 0.5 ? lerp(p1[0], p2[0], (bt - 0.33) * 3) : lerp(p2[0], p3[0], (bt - 0.66) * 3);
        let by = bt < 0.5 ? lerp(p1[1], p2[1], (bt - 0.33) * 3) : lerp(p2[1], p3[1], (bt - 0.66) * 3);
        drawDewDrop(bx, by + 1.2, random(1.8, 3.1), false);
      }
    }
  }
}

// Renders a hyperreal optical dew droplet with cast shadow, dark upper refraction, warm bounce glow & crisp specular
function drawDewDrop(x, y, r, warmSubsurface) {
  // 1. Cast shadow beneath droplet
  brush.set("cpencil", "#0d0807", 0.65);
  brush.arc(x + 0.4, y + r * 0.45, r * 0.9, 15, 165);

  // 2. Dark refractive upper hemisphere
  brush.set("cpencil", warmSubsurface ? "#4a1714" : "#18242e", 0.7);
  brush.arc(x, y, r * 0.85, 195, 345);

  // 3. Internal refracted bounce light in lower belly of droplet
  let bellyCol = warmSubsurface ? "#f28d7e" : "#9bd4b8";
  brush.set("cpencil", bellyCol, 0.65);
  brush.arc(x, y + r * 0.12, r * 0.65, 25, 155);

  // 4. Primary razor-sharp silvery-white sky reflection at top-left
  brush.set("cpencil", "#ffffff", r > 3.5 ? 0.95 : 0.65);
  brush.circle(x - r * 0.25, y - r * 0.28, max(0.8, r * 0.26), 0.05);

  // 5. Secondary caustic rim glint at bottom
  if (r > 2.8) {
    brush.set("cpencil", "#e6f4fa", 0.5);
    brush.arc(x, y + r * 0.1, r * 0.78, 45, 135);
  }
}

