// =============================================================================
// GEOMETRY & WATERCOLOR HELPERS
// =============================================================================

function fillOrganicPolygon(pts, col, alpha, bleed = 0.22, tex = 0.45, border = 0.25, curvature = 0.55) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function makeRibbonPolygon(xStart, xEnd, steps, centerFn, halfThickFn, noiseAmp = 2.0, seedOffset = 0) {
  let upper = [];
  let lower = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(xStart, xEnd, t);
    let cy = centerFn(t, x);
    let ht = halfThickFn(t, x);
    let n1 = (noise(t * 5 + seedOffset, 1.3) - 0.5) * 2 * noiseAmp;
    let n2 = (noise(t * 5 + seedOffset, 7.9) - 0.5) * 2 * noiseAmp;
    upper.push([x, cy - ht + n1]);
    lower.push([x, cy + ht + n2]);
  }
  let poly = [];
  for (let i = 0; i < upper.length; i++) poly.push(upper[i]);
  for (let i = lower.length - 1; i >= 0; i--) poly.push(lower[i]);
  return poly;
}

function makeCloudDomePolygon(cx, cy, rx, ry, bumps = 14, flatBottom = 0.45, seed = 0) {
  let pts = [];
  let totalSteps = bumps * 3;
  for (let i = 0; i < totalSteps; i++) {
    let a = map(i, 0, totalSteps, 0, 360);
    let radMod = 1.0;
    let s = sin(a);
    let c = cos(a);

    // Upper hemisphere (a from 180 to 360) gets crisp cauliflower scallops
    if (s < 0) {
      let lobeWave = abs(sin(a * (bumps * 0.5) + seed * 37)) * 0.16;
      let microWave = abs(cos(a * bumps + seed * 19)) * 0.06;
      let n = noise(c * 1.5 + seed, s * 1.5 + seed) * 0.18;
      radMod = 0.92 + lobeWave + microWave + n;
    } else {
      // Lower hemisphere flattens softly into the cloud base
      let n = noise(c * 1.2 + seed + 10, s * 1.2 + seed) * 0.14;
      radMod = 0.88 + n;
    }

    let px = cx + c * rx * radMod;
    let py = cy + s * ry * radMod * (s > 0 ? flatBottom : 1.0);
    pts.push([px, py]);
  }
  return pts;
}

// =============================================================================
// 1. SKY WASHES
// =============================================================================

function drawSkyWashes(horizonY) {
  const skyBands = [
    { y0: -30, y1: 180, col: "#425260", alpha: 115, bleed: 0.38 },
    { y0: 90,  y1: 310, col: "#526370", alpha: 105, bleed: 0.36 },
    { y0: 220, y1: 460, col: "#667682", alpha: 95,  bleed: 0.35 },
    { y0: 360, y1: 620, col: "#7c8b92", alpha: 90,  bleed: 0.32 },
    { y0: 520, y1: 790, col: "#96a1a3", alpha: 85,  bleed: 0.30 },
    { y0: 690, y1: 930, col: "#b6b7ae", alpha: 88,  bleed: 0.28 },
    { y0: 840, y1: 1015, col: "#cfc5b2", alpha: 95, bleed: 0.25 },
    { y0: 945, y1: horizonY + 12, col: "#e2d4be", alpha: 110, bleed: 0.20 }
  ];

  for (let b = 0; b < skyBands.length; b++) {
    let band = skyBands[b];
    let pts = [];
    let steps = 16;
    for (let i = 0; i <= steps; i++) {
      let x = map(i, 0, steps, -40, 1240);
      let ny = band.y0 + (noise(i * 0.35, b * 1.7) - 0.5) * 48;
      pts.push([x, ny]);
    }
    for (let i = steps; i >= 0; i--) {
      let x = map(i, 0, steps, -40, 1240);
      let ny = band.y1 + (noise(i * 0.35 + 9, b * 1.7 + 4) - 0.5) * 55;
      pts.push([x, ny]);
    }
    fillOrganicPolygon(pts, band.col, band.alpha, band.bleed, 0.42, 0.18, 0.4);
  }

  // Deep atmospheric zenith corners to make the pileus cap glow by contrast
  let leftSkyCorner = [
    [-40, -40], [680, -40], [520, 210], [280, 320], [120, 440], [-40, 490]
  ];
  fillOrganicPolygon(leftSkyCorner, "#394856", 75, 0.42, 0.5, 0.2, 0.5);

  let rightSkyCorner = [
    [560, -40], [1240, -40], [1240, 520], [1040, 430], [870, 290], [660, 185]
  ];
  fillOrganicPolygon(rightSkyCorner, "#3d4d5b", 78, 0.42, 0.5, 0.2, 0.5);

  // Warm ochre-earth horizon glow slot beneath the cloud base
  let horizonGlow = makeRibbonPolygon(
    -30, 1230, 20,
    (t) => 985 + sin(t * 180) * 14,
    (t) => 48 + sin(t * 180) * 18,
    8, 11
  );
  fillOrganicPolygon(horizonGlow, "#e8d5b5", 95, 0.28, 0.3, 0.15, 0.5);
}

