// =============================================================================
// 3. PILEUS CAP CLOUD & PASTEL DIFFRACTION BANDS
// =============================================================================

function pileusSpineY(t) {
  // Smooth symmetric-yet-natural lenticular arch peaking around t = 0.49, y = 148
  let d = (t - 0.49) * 2.0;
  let arch = 144 + d * d * 155 + d * d * d * d * 32;
  let subtleWave = sin(t * 360) * 4.5;
  return arch + subtleWave;
}

function drawPileusCapUnderlayer() {
  // Luminous mother-of-pearl veil cushion behind the diffraction bands
  let outerCap = makeRibbonPolygon(
    235, 975, 32,
    (t) => pileusSpineY(t) + 8,
    (t) => sin(constrain(t, 0.02, 0.98) * 180) * 56,
    2.5, 21
  );
  fillOrganicPolygon(outerCap, "#f6efe2", 110, 0.22, 0.25, 0.12, 0.6);

  // Secondary high ghost pileus veil slightly above the crown
  let upperGhostCap = makeRibbonPolygon(
    330, 860, 26,
    (t) => pileusSpineY(t) - 36,
    (t) => sin(constrain(t, 0.03, 0.97) * 180) * 16,
    1.5, 33
  );
  fillOrganicPolygon(upperGhostCap, "#efe5d4", 75, 0.18, 0.22, 0.1, 0.6);
}

function drawPileusDiffractionBands() {
  // Narrow, carefully glazed concentric bands of pastel diffraction:
  // Pale Gold, Salmon, Lilac, Mint — repeating harmonically toward the bright pearl core
  const diffractionBands = [
    // Upperghost cap shimmer
    { x0: 345, x1: 845, offset: -41, thick: 6.5, col: "#f2dfaa", alpha: 88, bleed: 0.12 },
    { x0: 355, x1: 835, offset: -35, thick: 6.5, col: "#e6b09e", alpha: 82, bleed: 0.12 },
    { x0: 365, x1: 825, offset: -29, thick: 6.0, col: "#b4dece", alpha: 85, bleed: 0.12 },

    // Main pileus crown diffraction sequence (outer crest to inner core)
    { x0: 250, x1: 960, offset: -22, thick: 9.0,  col: "#f3e0a6", alpha: 105, bleed: 0.11 }, // Pale Gold
    { x0: 260, x1: 950, offset: -14, thick: 8.5,  col: "#e6ab98", alpha: 98,  bleed: 0.11 }, // Salmon
    { x0: 270, x1: 940, offset: -6,  thick: 8.5,  col: "#c7b1d4", alpha: 95,  bleed: 0.11 }, // Lilac
    { x0: 280, x1: 930, offset: 2,   thick: 9.5,  col: "#b2dece", alpha: 105, bleed: 0.11 }, // Mint
    { x0: 295, x1: 915, offset: 11,  thick: 9.0,  col: "#f5e5b5", alpha: 110, bleed: 0.10 }, // Second-order Pale Gold
    { x0: 310, x1: 900, offset: 19,  thick: 8.5,  col: "#ebb7a7", alpha: 96,  bleed: 0.10 }, // Second-order Salmon
    { x0: 325, x1: 885, offset: 27,  thick: 8.0,  col: "#d1bedb", alpha: 92,  bleed: 0.10 }, // Second-order Lilac
    { x0: 340, x1: 870, offset: 34,  thick: 8.5,  col: "#bfe5d7", alpha: 98,  bleed: 0.10 }, // Second-order Mint
    { x0: 355, x1: 855, offset: 42,  thick: 10.5, col: "#fbf6ec", alpha: 135, bleed: 0.14 }, // Luminous Pearl Core
    { x0: 375, x1: 835, offset: 52,  thick: 11.0, col: "#99919f", alpha: 82,  bleed: 0.16 }  // Cool Mauve-Slate Underside
  ];

  for (let i = 0; i < diffractionBands.length; i++) {
    let b = diffractionBands[i];
    let poly = makeRibbonPolygon(
      b.x0, b.x1, 30,
      (t, x) => {
        let globalT = map(x, 235, 975, 0, 1);
        let taper = sin(constrain(t, 0.01, 0.99) * 180);
        return pileusSpineY(globalT) + b.offset * pow(taper, 0.55);
      },
      (t) => {
        let env = sin(constrain(t, 0.02, 0.98) * 180);
        return b.thick * pow(env, 0.65);
      },
      1.1,
      100 + i * 7
    );
    fillOrganicPolygon(poly, b.col, b.alpha, b.bleed, 0.24, 0.10, 0.65);
  }

  // Secondary smaller pileus cap over the left shoulder turret (x = 185..465, y = 330..410)
  const leftCapBands = [
    { off: -10, th: 6.5, col: "#f2dfa8", alpha: 90 },
    { off: -4,  th: 6.0, col: "#e7b09f", alpha: 86 },
    { off: 2,   th: 6.0, col: "#c9b5d4", alpha: 84 },
    { off: 8,   th: 6.5, col: "#b5dfd0", alpha: 90 },
    { off: 15,  th: 7.5, col: "#faf4e8", alpha: 110 }
  ];
  for (let i = 0; i < leftCapBands.length; i++) {
    let lb = leftCapBands[i];
    let poly = makeRibbonPolygon(
      185, 470, 22,
      (t) => {
        let d = (t - 0.52) * 2;
        return 338 + d * d * 68 + lb.off * sin(t * 180);
      },
      (t) => sin(constrain(t, 0.03, 0.97) * 180) * lb.th,
      1.0,
      200 + i * 5
    );
    fillOrganicPolygon(poly, lb.col, lb.alpha, 0.11, 0.22, 0.1, 0.6);
  }

  // Optical silk blending across the diffraction bands using smooth spline strokes
  const silkColors = [
    { offset: -20, col: "#f6e7b8" },
    { offset: -12, col: "#ebb6a5" },
    { offset: -4,  col: "#cebad9" },
    { offset: 4,   col: "#bce4d5" },
    { offset: 12,  col: "#f7e9c0" },
    { offset: 21,  col: "#efc0b2" },
    { offset: 30,  col: "#c5e8da" },
    { offset: 39,  col: "#fffcf5" }
  ];

  for (let s = 0; s < silkColors.length; s++) {
    let sc = silkColors[s];
    for (let pass = 0; pass < 4; pass++) {
      let pts = [];
      let tStart = random(0.04, 0.18);
      let tEnd = random(0.82, 0.96);
      let steps = 14;
      for (let k = 0; k <= steps; k++) {
        let t = lerp(tStart, tEnd, k / steps);
        let x = lerp(250, 960, t);
        let env = pow(sin(t * 180), 0.6);
        let y = pileusSpineY(t) + (sc.offset + random(-2.5, 2.5)) * env;
        let p = sin((k / steps) * 180) * 1.1 + 0.2;
        pts.push([x, y, p]);
      }
      brush.set("silk_glaze", sc.col, random(0.65, 1.15));
      brush.spline(pts, 0.65);
    }
  }

  // Crisp luminous filaments along the lenticular leading edge
  for (let f = 0; f < 28; f++) {
    let t0 = random(0.06, 0.72);
    let t1 = constrain(t0 + random(0.12, 0.26), 0.15, 0.94);
    let pts = [];
    let bandChoice = f % 4;
    let col = bandChoice === 0 ? "#fcf6e3" : bandChoice === 1 ? "#f2c6b8" : bandChoice === 2 ? "#c7eadc" : "#dfd0e8";
    let off = map(f, 0, 28, -24, 42);
    for (let k = 0; k <= 8; k++) {
      let t = lerp(t0, t1, k / 8);
      let x = lerp(250, 960, t);
      let y = pileusSpineY(t) + off * pow(sin(t * 180), 0.55);
      pts.push([x, y, sin((k / 8) * 180) * 0.9 + 0.2]);
    }
    brush.set("cpencil", col, random(0.45, 0.85));
    brush.spline(pts, 0.6);
  }
}

