    { cx: 615, cy: 445, rx: 135, ry: 125, tier: "high",  seed: 22 },
    { cx: 745, cy: 440, rx: 105, ry: 100, tier: "high",  seed: 23 },
    { cx: 530, cy: 615, rx: 155, ry: 130, tier: "mid",   seed: 24 },
