function drawSculptedTurret(t) {
  let lightCol = "#fbf6ec";
  let midCol   = "#d8cbb8";
  let shCol    = "#8c827b";
  let deepCol  = "#635d5e";

  if (t.tier === "crown") {
    lightCol = "#fffcf5";
    midCol   = "#e8dcc8";
    shCol    = "#9e938b";
    deepCol  = "#756d6c";
  } else if (t.tier === "high") {
    lightCol = "#fbf5e8";
    midCol   = "#dfd2bf";
    shCol    = "#8f857f";
    deepCol  = "#686162";
  } else if (t.tier === "base") {
    lightCol = "#dfd3c0";
    midCol   = "#b5a89b";
    shCol    = "#706866";
    deepCol  = "#4f4b4f";
  }

  // 1. Mid-tone limestone volume wash
  let midPoly = makeCloudDomePolygon(t.cx, t.cy, t.rx, t.ry, 14, 0.45, t.seed);
  fillOrganicPolygon(midPoly, midCol, 118, 0.26, 0.42, 0.22, 0.55);

  // 2. Sunlit upper-left crown (shifted toward upper-left sun at -135 deg)
  let sunPoly = makeCloudDomePolygon(
    t.cx - t.rx * 0.14,
    t.cy - t.ry * 0.16,
    t.rx * 0.84,
    t.ry * 0.80,
    15, 0.38, t.seed + 30
  );
  fillOrganicPolygon(sunPoly, lightCol, 140, 0.18, 0.32, 0.18, 0.58);

  // 3. Wet-in-wet shadow belly (shifted lower-right)
  let shPoly = makeCloudDomePolygon(
    t.cx + t.rx * 0.15,
    t.cy + t.ry * 0.20,
    t.rx * 0.82,
    t.ry * 0.68,
    11, 0.42, t.seed + 60
  );
  fillOrganicPolygon(shPoly, shCol, 108, 0.35, 0.48, 0.24, 0.52);

  // 4. Deep core shadow at the underside
  let deepPoly = makeCloudDomePolygon(
    t.cx + t.rx * 0.22,
    t.cy + t.ry * 0.34,
    t.rx * 0.62,
    t.ry * 0.46,
    9, 0.35, t.seed + 90
  );
  fillOrganicPolygon(deepPoly, deepCol, 95, 0.38, 0.52, 0.24, 0.5);

  // 5. Crisp cauliflower knuckle rims along the sunlit arc (165 deg to 345 deg)
  drawTurretCauliflowerEdge(
    t.cx - t.rx * 0.08,
    t.cy - t.ry * 0.08,
    t.rx * 0.90,
    t.ry * 0.86,
    165, 345,
    11,
    lightCol,
    shCol,
    t.seed
  );
}

function drawTurretCauliflowerEdge(cx, cy, rx, ry, startAng, endAng, knuckleCount, rimCol, creviceCol, seed) {
  let span = endAng - startAng;
  let stepAng = span / knuckleCount;

  for (let k = 0; k < knuckleCount; k++) {
    let a0 = startAng + k * stepAng;
    let a1 = a0 + stepAng;
    let aMid = (a0 + a1) * 0.5;
    let bulge = 1.0 + 0.14 * noise(k * 0.7, seed * 0.3);

    // Scalloped sunlit knuckle arc
    let arcPts = [];
    for (let s = 0; s <= 6; s++) {
      let f = s / 6;
      let ang = lerp(a0, a1, f);
      let knucklePush = sin(f * 180) * 14 * bulge;
      let px = cx + cos(ang) * (rx + knucklePush);
      let py = cy + sin(ang) * (ry + knucklePush);
      let press = sin(f * 180) * 1.1 + 0.25;
      arcPts.push([px, py, press]);
    }

    // Soft glowing vapor cushion along knuckle rim
    brush.set("vapor_rim", rimCol, random(0.85, 1.35));
    brush.spline(arcPts, 0.6);

    // Crisp dry-pencil silver lining on the sunward side (angles 170..295)
    if (aMid < 305) {
      brush.set("cpencil", "#fffdf8", random(0.55, 0.95));
      brush.spline(arcPts, 0.6);
    }

    // Dark V-shaped sinus crevice tucked right between adjacent cloud knuckles
    let crevAng = a1;
    let cx0 = cx + cos(crevAng) * (rx + 2);
    let cy0 = cy + sin(crevAng) * (ry + 2);
    let cx1 = cx + cos(crevAng + 6) * (rx - 18 * bulge);
    let cy1 = cy + sin(crevAng + 6) * (ry - 18 * bulge);
    let cx2 = cx + cos(crevAng + 14) * (rx - 34 * bulge);
    let cy2 = cy + sin(crevAng + 14) * (ry - 34 * bulge);

    brush.set("cloud_scumble", creviceCol, random(0.55, 0.95));
    brush.spline([[cx0, cy0, 0.3], [cx1, cy1, 1.0], [cx2, cy2, 0.2]], 0.5);
  }
}

function drawCauliflowerMicroTurrets() {
  // High-detail boiling florets on the sunlit face of the central tower
  const florets = [
    { x: 545, y: 235, r: 46 },
    { x: 605, y: 215, r: 52 },
    { x: 665, y: 242, r: 44 },
    { x: 475, y: 310, r: 55 },
    { x: 555, y: 318, r: 62 },
    { x: 645, y: 325, r: 58 },
    { x: 725, y: 335, r: 48 },
    { x: 310, y: 415, r: 54 },
    { x: 395, y: 420, r: 64 },
    { x: 495, y: 435, r: 68 },
    { x: 590, y: 425, r: 72 },
    { x: 690, y: 445, r: 60 },
    { x: 795, y: 430, r: 52 },
    { x: 255, y: 585, r: 62 },
    { x: 375, y: 565, r: 74 },
    { x: 485, y: 575, r: 78 },
    { x: 615, y: 570, r: 82 },
    { x: 745, y: 585, r: 70 },
    { x: 885, y: 605, r: 64 }
  ];

  for (let i = 0; i < florets.length; i++) {
    let fl = florets[i];
    // Bright boiling puff highlight
    let puffPoly = makeCloudDomePolygon(fl.x - 6, fl.y - 6, fl.r, fl.r * 0.85, 9, 0.5, 300 + i);
    fillOrganicPolygon(puffPoly, "#fcf7ec", 115, 0.16, 0.28, 0.16, 0.6);

    // Shadowed underside pocket directly beneath the puff
    let pocketPoly = makeCloudDomePolygon(fl.x + 10, fl.y + fl.r * 0.48, fl.r * 0.78, fl.r * 0.42, 7, 0.4, 400 + i);
    fillOrganicPolygon(pocketPoly, "#7e7570", 85, 0.30, 0.45, 0.2, 0.5);

    // Micro-curls along the upper-left perimeter
    drawTurretCauliflowerEdge(
      fl.x, fl.y, fl.r * 0.92, fl.r * 0.80,
      175, 330, 7,
      "#fffdf9", "#857b75", 500 + i
    );
  }

  // Soft scumbled cloud belly texture & internal smoky shadows
  for (let i = 0; i < 140; i++) {
    let x = random(160, 1020);
    let y = random(260, 860);
    let dCenter = dist(x, y, 600, 580);
    if (dCenter > 430) continue;

    let isLower = y > 680;
    let col = isLower
      ? (random() < 0.5 ? "#575256" : "#6e6867")
      : (random() < 0.5 ? "#d8cbb8" : "#9c9189");

    brush.set("cloud_scumble", col, random(0.7, 1.5));
    let len = random(28, 75);
    let ang = random(-25, 25);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    brush.spline([[x, y, 0.3], [(x + x2) * 0.5, (y + y2) * 0.5 - random(4, 14), 1.0], [x2, y2, 0.2]], 0.5);
  }
}

