function drawPileusForegroundVeil() {
  // The lower translucent fringe of the pileus cap cloud drapes directly in front
  // of the highest ascending cumulus turret (around y = 185..265), locking them in 3D space.
  const veilRibbons = [
    { x0: 410, x1: 795, yOff: 32, th: 7.5, col: "#f4e3b0", alpha: 78 }, // Pale gold glaze
    { x0: 425, x1: 780, yOff: 39, th: 7.0, col: "#eab7a7", alpha: 75 }, // Salmon glaze
    { x0: 440, x1: 765, yOff: 46, th: 7.0, col: "#cbb6d6", alpha: 72 }, // Lilac glaze
    { x0: 455, x1: 750, yOff: 53, th: 7.5, col: "#b6e0d0", alpha: 78 }, // Mint glaze
    { x0: 470, x1: 735, yOff: 60, th: 8.0, col: "#faf5eb", alpha: 82 }  // Pearl mist edge
  ];

  for (let i = 0; i < veilRibbons.length; i++) {
    let vr = veilRibbons[i];
    let poly = makeRibbonPolygon(
      vr.x0, vr.x1, 24,
      (t, x) => {
        let globalT = map(x, 235, 975, 0, 1);
        return pileusSpineY(globalT) + vr.yOff;
      },
      (t) => sin(constrain(t, 0.03, 0.97) * 180) * vr.th,
      1.0,
      600 + i * 9
    );
    fillOrganicPolygon(poly, vr.col, vr.alpha, 0.14, 0.22, 0.08, 0.65);
  }

  // Delicate horizontal laminar silk threads across the crown veil
  for (let i = 0; i < 36; i++) {
    let t0 = random(0.28, 0.55);
    let t1 = t0 + random(0.12, 0.24);
    let off = random(28, 64);
    let cols = ["#f6e6b6", "#ecc0b1", "#d2c0de", "#bfe6d7", "#fffcf5"];
    let col = cols[i % cols.length];
    let pts = [];
    for (let k = 0; k <= 8; k++) {
      let t = lerp(t0, t1, k / 8);
      let x = lerp(250, 960, t);
      let y = pileusSpineY(t) + off;
      pts.push([x, y, sin((k / 8) * 180) * 0.9 + 0.15]);
    }
    brush.set("silk_glaze", col, random(0.45, 0.85));
    brush.spline(pts, 0.65);
  }
}

