function drawSubCloudAtmosphere(horizonY) {
  // Diagonal curtains of virga (evaporating rain streaks) hanging below the dark cumulus base
  for (let i = 0; i < 65; i++) {
    let x = random(180, 1020);
    let y0 = random(865, 915);
    let y1 = y0 + random(55, 125);
    let drift = random(-18, -6);
    let col = i % 3 === 0 ? "#8a827c" : i % 3 === 1 ? "#a89f94" : "#dfd2bc";
    brush.set("silk_glaze", col, random(0.4, 0.9));
    brush.spline([
      [x, y0, 0.9],
      [x + drift * 0.5, (y0 + y1) * 0.5, 0.6],
      [x + drift, y1, 0.15]
    ], 0.4);
  }

  // Low horizontal stratus ribbons glowing in pale ochre-gold near the horizon
  for (let i = 0; i < 5; i++) {
    let y = map(i, 0, 4, 955, 1032);
    let x0 = random(40, 280);
    let x1 = random(920, 1160);
    let poly = makeRibbonPolygon(
      x0, x1, 20,
      (t) => y + sin(t * 360 + i * 40) * 4,
      (t) => sin(constrain(t, 0.04, 0.96) * 180) * (7 - i * 0.8),
      1.2,
      700 + i
    );
    let col = i < 2 ? "#9e948c" : "#ebd8b9";
    fillOrganicPolygon(poly, col, 75, 0.16, 0.25, 0.1, 0.5);
  }
}

function drawDistantHorizonDetails(horizonY) {
  // Distant low industrial warehouse roofs on the right (x = 890..1200)
  let roofPoly = [
    [890, horizonY],
    [890, horizonY - 11],
    [965, horizonY - 13],
    [965, horizonY - 9],
    [1085, horizonY - 10],
    [1110, horizonY - 15],
    [1185, horizonY - 15],
    [1205, horizonY]
  ];
  fillOrganicPolygon(roofPoly, "#595450", 145, 0.04, 0.3, 0.2, 0.05);

  // Crisp architectural pen outlines on the distant roofs & vents
  brush.set("fine_liner", "#36322f", 0.85);
  brush.line(890, horizonY - 11, 965, horizonY - 13);
  brush.line(965, horizonY - 13, 965, horizonY);
  brush.line(965, horizonY - 9, 1085, horizonY - 10);
  brush.line(1110, horizonY - 15, 1185, horizonY - 15);

  // Tiny rooftop HVAC units and vents
  const vents = [915, 942, 1010, 1045, 1135, 1162];
  for (let v of vents) {
    brush.set("fine_liner", "#3b3734", 0.75);
    brush.rect(v, horizonY - 16, 9, 5, "corner");
  }

  // Distant winter scrub trees / hedgerow along the left and center horizon (x = 0..885)
  for (let x = 8; x < 885; x += random(5, 11)) {
    let h = noise(x * 0.03) * 14 + random(2, 7);
    if (x > 520 && x < 680) h *= 0.45; // Low gap near vanishing point
    let treeCol = random() < 0.5 ? "#4a4642" : "#615b54";
    brush.set("2B", treeCol, random(0.5, 0.95));
    brush.line(x, horizonY, x + random(-2, 2), horizonY - h);
    if (h > 9) {
      brush.set("fine_liner", "#383430", 0.6);
      brush.line(x, horizonY - h * 0.4, x - 3, horizonY - h * 0.85);
      brush.line(x, horizonY - h * 0.5, x + 3, horizonY - h * 0.9);
    }
  }

  // Distant chain-link perimeter fence posts along the back edge of the carpark
  brush.set("2H", "#6e6860", 0.65);
  brush.line(0, horizonY - 5, 1200, horizonY - 5);
  brush.line(0, horizonY - 2.5, 1200, horizonY - 2.5);
  for (let x = 15; x < 1190; x += 28) {
    brush.set("fine_liner", "#4a4540", 0.7);
    brush.line(x, horizonY, x, horizonY - 7);
  }
}

// =============================================================================
// 7. CARPARK TARMAC, PUDDLE REFLECTIONS & BAY MARKINGS (PRECISE PEN & PENCIL)
// =============================================================================

function drawCarparkTarmac(horizonY) {
  // 7A. Base weathered asphalt watercolor washes (muted earth umber & slate)
  let tarmacBase = [
    [-20, horizonY],
    [1220, horizonY],
    [1220, 1220],
    [-20, 1220]
  ];
  fillOrganicPolygon(tarmacBase, "#59534c", 165, 0.08, 0.55, 0.25, 0.05);

  // Darker foreground asphalt strips
  const asphaltBands = [
    { y0: horizonY, y1: 1092, col: "#665f57", alpha: 115 },
    { y0: 1085,     y1: 1138, col: "#4d4843", alpha: 120 },
    { y0: 1125,     y1: 1175, col: "#3e3a36", alpha: 135 },
    { y0: 1160,     y1: 1215, col: "#312e2b", alpha: 150 }
  ];

  for (let i = 0; i < asphaltBands.length; i++) {
    let ab = asphaltBands[i];
    let poly = makeRibbonPolygon(
      -20, 1220, 18,
      (t) => (ab.y0 + ab.y1) * 0.5 + (noise(t * 4, i * 3) - 0.5) * 10,
      (t) => (ab.y1 - ab.y0) * 0.55,
      3.0,
      800 + i
    );
    fillOrganicPolygon(poly, ab.col, ab.alpha, 0.16, 0.52, 0.25, 0.35);
  }

  // 7B. Wet rainwater puddle on the carpark tarmac reflecting the luminous pastel sky!
  let puddleSkyGlow = makeRibbonPolygon(
    185, 865, 28,
    (t) => 1118 + sin(t * 360) * 12,
    (t) => sin(constrain(t, 0.03, 0.97) * 180) * 28,
    3.5, 850
  );
  fillOrganicPolygon(puddleSkyGlow, "#e6d6be", 135, 0.12, 0.28, 0.22, 0.5);

  // Subtle reflections of the pastel diffraction colors in the puddle water
  let puddleSalmon = makeRibbonPolygon(
    260, 780, 22,
    (t) => 1112 + sin(t * 180) * 6,
    (t) => sin(constrain(t, 0.04, 0.96) * 180) * 11,
    1.8, 855
  );
  fillOrganicPolygon(puddleSalmon, "#e0b0a0", 85, 0.10, 0.22, 0.15, 0.5);

  let puddleMint = makeRibbonPolygon(
    310, 740, 22,
    (t) => 1124 + cos(t * 180) * 5,
    (t) => sin(constrain(t, 0.04, 0.96) * 180) * 10,
    1.8, 860
  );
  fillOrganicPolygon(puddleMint, "#b5d8ca", 82, 0.10, 0.22, 0.15, 0.5);

  let puddleGold = makeRibbonPolygon(
    220, 820, 22,
    (t) => 1132 + sin(t * 270) * 5,
    (t) => sin(constrain(t, 0.04, 0.96) * 180) * 9,
    1.8, 865
  );
  fillOrganicPolygon(puddleGold, "#ebd9aa", 90, 0.10, 0.22, 0.15, 0.5);

  // Secondary smaller puddle on the right
  let rightPuddle = makeRibbonPolygon(
    915, 1145, 18,
    (t) => 1142 + sin(t * 180) * 4,
    (t) => sin(constrain(t, 0.05, 0.95) * 180) * 14,
    2.0, 870
  );
  fillOrganicPolygon(rightPuddle, "#d8cab5", 110, 0.10, 0.25, 0.2, 0.5);

  // 7C. Distant concrete curb at the horizon seam
  brush.set("2H", "#cfc5b4", 0.9);
  brush.line(0, horizonY + 1, 1200, horizonY + 1);
  brush.set("fine_liner", "#2e2b28", 0.85);
  brush.line(0, horizonY, 1200, horizonY);
  brush.line(0, horizonY + 3.5, 1200, horizonY + 3.5);

  // 7D. Perspective Parking Bay Lines (converging toward vanishing point VP = (610, horizonY - 12))
  const vpX = 610;
  const vpY = horizonY - 12;

  // Transverse collector lane line at y = 1094
  const laneY = 1094;
  drawWeatheredPaintLine(40, laneY, 1160, laneY, "#ded4c1", 2.2);

  // Angled parking bay dividers radiating from the transverse line toward the foreground
  const bayTopX = [95, 205, 315, 425, 535, 645, 755, 865, 975, 1085];
  for (let i = 0; i < bayTopX.length; i++) {
    let tx = bayTopX[i];
    let ty = laneY;
    let dirX = tx - vpX;
    let dirY = ty - vpY;
    let scaleToBottom = (1188 - vpY) / dirY;
    let bx = vpX + dirX * scaleToBottom;
    let by = 1188;

    drawWeatheredPaintLine(tx, ty, bx, by, "#e0d6c3", 3.2);
  }

  // Back row of distant parking bay dividers between horizonY + 5 and laneY - 8
  for (let i = 0; i < 16; i++) {
    let tx = map(i, 0, 15, 80, 1120);
    let ty = horizonY + 5;
    let dirX = tx - vpX;
    let dirY = ty - vpY;
    let scaleMid = (laneY - 10 - vpY) / dirY;
    let mx = vpX + dirX * scaleMid;
    let my = laneY - 10;
    drawWeatheredPaintLine(tx, ty, mx, my, "#cfc5b4", 1.2);
  }

  // Double yellow no-parking curb lines in the lower-left foreground
  drawWeatheredPaintLine(-10, 1148, 395, 1198, "#d4aa5b", 2.6);
  drawWeatheredPaintLine(-10, 1155, 375, 1203, "#d4aa5b", 2.6);

  // 7E. Meticulous Pen & Pencil Tarmac Texture (Perspective Hatching, Aggregate & Cracks)
  // Horizontal perspective compression lines
  for (let i = 0; i < 260; i++) {
    let t = pow(random(), 1.55); // Denser near horizon, wider strokes in foreground
    let y = lerp(horizonY + 2, 1198, t);
    let x = random(-10, 1210);
    let len = lerp(18, 95, t) * random(0.6, 1.4);

    // Check if inside the main reflective puddle
    let inPuddle = (x > 200 && x < 850 && y > 1096 && y < 1144);
    if (inPuddle) {
      if (random() < 0.35) {
        // Delicate water ripple reflection line
        brush.set("2H", "#efe4cf", random(0.4, 0.75));
        brush.line(x, y, x + len * 0.5, y);
      }
      continue;
    }

    let pencilType = t < 0.35 ? "2H" : t < 0.7 ? "HB" : "2B";
    let strokeCol = random() < 0.45 ? "#2b2825" : random() < 0.75 ? "#3f3b37" : "#6e675e";
    brush.set(pencilType, strokeCol, lerp(0.35, 0.95, t));
    brush.line(x, y, x + len, y + random(-1.2, 1.2));
  }

  // Crisp water meniscus rim around the main puddle (drawn in fine technical pen & 2H)
  for (let i = 0; i < 48; i++) {
    let t = i / 48;
    let x = lerp(190, 860, t);
    let env = sin(constrain(t, 0.02, 0.98) * 180);
    let yTop = 1118 + sin(t * 360) * 12 - env * 27 + random(-2, 2);
    let yBot = 1118 + sin(t * 360) * 12 + env * 27 + random(-2, 2);
    brush.set("fine_liner", "#2b2825", 0.65);
    brush.line(x, yTop, x + 10, yTop + random(-1, 1));
    brush.line(x, yBot, x + 10, yBot + random(-1, 1));
  }

  // Coarse tarmac stone aggregate stippling in foreground
  for (let i = 0; i < 95; i++) {
    let x = random(20, 1180);
    let y = random(1110, 1196);
    brush.set("spray", i % 2 === 0 ? "#242220" : "#7a7268", random(0.35, 0.75));
    brush.line(x, y, x + random(8, 24), y + random(-1, 1));
  }

  // Wandering tar-sealed asphalt cracks in razor-sharp rotring/fine_liner
  const cracks = [
    [[140, 1195], [168, 1172], [162, 1152], [188, 1134], [215, 1122]],
    [[510, 1198], [525, 1178], [518, 1160], [542, 1146], [555, 1135]],
    [[790, 1192], [772, 1168], [785, 1148], [768, 1128], [780, 1110]],
    [[1020, 1185], [995, 1162], [1008, 1142], [985, 1120]]
  ];
  for (let c = 0; c < cracks.length; c++) {
    let pts = cracks[c];
    brush.set("fine_liner", "#1a1816", 0.95);
    for (let j = 0; j < pts.length - 1; j++) {
      brush.line(pts[j][0], pts[j][1], pts[j + 1][0], pts[j + 1][1]);
      // Secondary micro-branch crack
      if (j % 2 === 1) {
        brush.set("fine_liner", "#2e2b28", 0.6);
        brush.line(pts[j][0], pts[j][1], pts[j][0] + random(-18, 18), pts[j][1] + random(-8, 8));
      }
    }
  }

  // Precast concrete wheel-stop blocks in two bays & a storm-drain grate
  drawConcreteWheelStop(445, 1102, 58, 5.5);
  drawConcreteWheelStop(765, 1104, 58, 5.5);
  drawStormDrainGrate(695, 1162, 34, 14);
}

function drawWeatheredPaintLine(x1, y1, x2, y2, col, weight) {
  let steps = 18;
  for (let i = 0; i < steps; i++) {
    if (random() < 0.16) continue; // Chipped/worn gaps in paint
    let t0 = i / steps;
    let t1 = (i + 0.85) / steps;
    let sx0 = lerp(x1, x2, t0);
    let sy0 = lerp(y1, y2, t0);
    let sx1 = lerp(x1, x2, t1);
    let sy1 = lerp(y1, y2, t1);

    // Subdue paint line if passing through the wet puddle
    let inPuddle = (sx0 > 210 && sx0 < 840 && sy0 > 1100 && sy0 < 1142);
    let w = inPuddle ? weight * 0.45 : weight;

    brush.set("cpencil", col, w * 0.55);
    brush.line(sx0, sy0, sx1, sy1);

    // Crisp outer edge tick in fine pencil
    brush.set("2H", "#8c8478", 0.45);
    brush.line(sx0, sy0 + 1.2, sx1, sy1 + 1.2);
  }
}

function drawConcreteWheelStop(x, y, w, h) {
  let poly = [
    [x, y], [x + w, y], [x + w + 3, y + h], [x - 3, y + h]
  ];
  fillOrganicPolygon(poly, "#b8afa0", 160, 0.04, 0.35, 0.2, 0.05);

  // Shadow underneath wheel stop
  brush.set("rotring", "#1f1d1b", 0.9);
  brush.line(x - 3, y + h, x + w + 3, y + h);
  brush.line(x + w, y, x + w + 3, y + h);

  // Top sunlit edge
  brush.set("cpencil", "#e8dfd0", 0.7);
  brush.line(x, y, x + w, y);
  brush.set("fine_liner", "#4a4540", 0.65);
  brush.line(x, y, x - 3, y + h);
}

function drawStormDrainGrate(x, y, w, h) {
  let poly = [
    [x, y], [x + w, y], [x + w + 4, y + h], [x - 4, y + h]
  ];
  fillOrganicPolygon(poly, "#262422", 180, 0.03, 0.3, 0.2, 0.05);

  brush.set("fine_liner", "#141312", 0.85);
  brush.line(x, y, x + w, y);
  brush.line(x - 4, y + h, x + w + 4, y + h);
  for (let i = 0; i <= 6; i++) {
    let gx0 = lerp(x, x + w, i / 6);
    let gx1 = lerp(x - 4, x + w + 4, i / 6);
    brush.line(gx0, y, gx1, y + h);
  }
  brush.set("cpencil", "#8c857b", 0.55);
  brush.line(x, y, x + w, y);
}

