function drawDistantLampPosts(horizonY) {
  // Two distant slender lamp posts along the back edge of the carpark for deep scale
  const distantPosts = [
    { x: 118, yBase: horizonY + 2, yTop: 958, armDir: 1,  armLen: 18 },
    { x: 855, yBase: horizonY + 3, yTop: 942, armDir: -1, armLen: 20 },
    { x: 1095, yBase: horizonY + 1, yTop: 972, armDir: -1, armLen: 15 }
  ];

  for (let dp of distantPosts) {
    // Warm sodium glow halo around distant luminaire
    let lx = dp.x + dp.armDir * dp.armLen;
    let ly = dp.yTop - 5;
    let glowPoly = makeCloudDomePolygon(lx, ly, 14, 10, 8, 1.0, 910);
    fillOrganicPolygon(glowPoly, "#f2a444", 85, 0.35, 0.2, 0.05, 0.6);

    // Pole shaft in crisp fine_liner
    brush.set("fine_liner", "#3b3835", 0.8);
    brush.line(dp.x, dp.yBase, dp.x, dp.yTop);
    brush.set("cpencil", "#e8dfd0", 0.45);
    brush.line(dp.x - 0.8, dp.yBase, dp.x - 0.8, dp.yTop);

    // Bracket arm
    brush.set("fine_liner", "#33302d", 0.7);
    brush.spline([
      [dp.x, dp.yTop + 4, 0.8],
      [dp.x + dp.armDir * dp.armLen * 0.5, dp.yTop - 4, 0.7],
      [lx, ly, 0.9]
    ], 0.5);

    // Tiny luminaire head & bright sodium core
    brush.set("rotring", "#292725", 0.9);
    brush.line(lx - 3, ly, lx + 3, ly);
    brush.set("cpencil", "#fff2c2", 0.9);
    brush.line(lx - 1.5, ly + 1, lx + 1.5, ly + 1);
  }
}

function drawMainSodiumLampPost(baseX, baseY, topY, horizonY) {
  // The main foreground sodium lamp post at x = 318:
  // Anchored in the carpark at y = 1148, rising 554 pixels straight up into the sky (to y = 594),
  // slicing across the horizon, sub-cloud glow, and dark cloud base.

  const armEndX = baseX + 96;
  const armEndY = topY - 22;
  const lampCenterX = armEndX + 12;
  const lampCenterY = armEndY + 2;

  // 8A. Warm High-Pressure Sodium Vapor Glow around the luminaire head
  let outerHalo = makeCloudDomePolygon(lampCenterX, lampCenterY + 4, 52, 36, 12, 0.95, 920);
  fillOrganicPolygon(outerHalo, "#f29d38", 62, 0.42, 0.2, 0.05, 0.65);

  let midHalo = makeCloudDomePolygon(lampCenterX, lampCenterY + 3, 28, 20, 10, 0.95, 925);
  fillOrganicPolygon(midHalo, "#ffbe59", 105, 0.32, 0.18, 0.05, 0.65);

  let innerCore = makeCloudDomePolygon(lampCenterX, lampCenterY + 3, 13, 8, 8, 0.95, 930);
  fillOrganicPolygon(innerCore, "#fff6d6", 175, 0.18, 0.12, 0.05, 0.65);

  // 8B. Reflection & cast shadow of the lamp post on the wet tarmac below (y = 1148..1200)
  // Dark vertical reflection of the pole shaft
  brush.set("HB", "#211f1d", 1.3);
  brush.line(baseX, baseY, baseX - 2, 1200);
  brush.set("2B", "#2e2b28", 1.0);
  brush.line(baseX + 3, baseY, baseX + 2, 1200);

  // Shimmering vertical reflection of the amber sodium bulb in the wet puddle/tarmac
  for (let ry = 1112; ry < 1194; ry += 3.5) {
    let jit = sin(ry * 25) * 4;
    let col = ry % 7 < 3.5 ? "#f2a649" : "#ffe094";
    brush.set("cpencil", col, random(0.55, 0.95));
    brush.line(lampCenterX + jit - 5, ry, lampCenterX + jit + 5, ry);
  }

  // 8C. Concrete Footing Plinth & Base Flange (y = 1130..1148)
  let plinthPoly = [
    [baseX - 11, baseY - 16],
    [baseX + 11, baseY - 16],
    [baseX + 13, baseY],
    [baseX - 13, baseY]
  ];
  fillOrganicPolygon(plinthPoly, "#9c9386", 180, 0.03, 0.4, 0.25, 0.05);

  // Plinth shading & anchor bolts in technical pen
  brush.set("fine_liner", "#242220", 0.9);
  brush.line(baseX - 11, baseY - 16, baseX + 11, baseY - 16);
  brush.line(baseX - 13, baseY, baseX + 13, baseY);
  brush.line(baseX - 11, baseY - 16, baseX - 13, baseY);
  brush.line(baseX + 11, baseY - 16, baseX + 13, baseY);

  // Vertical hatching on shadow side of concrete plinth
  for (let hx = baseX + 1; hx <= baseX + 11; hx += 2) {
    brush.set("2H", "#45413c", 0.65);
    brush.line(hx, baseY - 15, hx + 1, baseY - 1);
  }

  // Steel base flange plate & four bolt heads
  brush.set("rotring", "#2b2927", 1.0);
  brush.line(baseX - 9, baseY - 17, baseX + 9, baseY - 17);
  brush.line(baseX - 7, baseY - 21, baseX - 7, baseY - 17);
  brush.line(baseX + 7, baseY - 21, baseX + 7, baseY - 17);

  // 8D. Lower Column Section with Electrical Inspection Door (y = 975..1132)
  const collarY = 975;
  let lowerColPoly = [
    [baseX - 6.0, baseY - 17],
    [baseX + 6.0, baseY - 17],
    [baseX + 4.8, collarY],
    [baseX - 4.8, collarY]
  ];
  fillOrganicPolygon(lowerColPoly, "#707274", 190, 0.02, 0.35, 0.2, 0.02);

  // 8E. Upper Tapered Galvanized Steel Shaft (y = 594..975)
  let upperColPoly = [
    [baseX - 3.8, collarY],
    [baseX + 3.8, collarY],
    [baseX + 2.1, topY],
    [baseX - 2.1, topY]
  ];
  fillOrganicPolygon(upperColPoly, "#7a7d80", 190, 0.02, 0.32, 0.2, 0.02);

  // Cylindrical 3D shading along the entire 554px shaft:
  // Sunlit left rim (warm silver-ivory), mid-grey core, and dark right shadow edge
  brush.set("cpencil", "#f5ebd8", 0.85);
  brush.line(baseX - 5.6, baseY - 17, baseX - 4.5, collarY);
  brush.line(baseX - 3.5, collarY, baseX - 1.9, topY);

  // Mid-core pencil grain
  brush.set("2H", "#545659", 0.75);
  brush.line(baseX + 0.5, baseY - 17, baseX + 0.4, collarY);
  brush.line(baseX + 0.4, collarY, baseX + 0.3, topY);

  // Shadowed right side of column
  brush.set("HB", "#35373a", 0.9);
  brush.line(baseX + 3.2, baseY - 17, baseX + 2.6, collarY);
  brush.line(baseX + 2.1, collarY, baseX + 1.2, topY);

  // Razor-sharp outer contour edges in fine_liner
  brush.set("fine_liner", "#1e1f21", 0.95);
  brush.line(baseX - 6.0, baseY - 17, baseX - 4.8, collarY);
  brush.line(baseX - 3.8, collarY, baseX - 2.1, topY);

  brush.set("fine_liner", "#141517", 1.1);
  brush.line(baseX + 6.0, baseY - 17, baseX + 4.8, collarY);
  brush.line(baseX + 3.8, collarY, baseX + 2.1, topY);

  // Transition collar ring at y = 975
  brush.set("rotring", "#1f2022", 0.95);
  brush.line(baseX - 5.2, collarY, baseX + 5.2, collarY);
  brush.line(baseX - 4.2, collarY - 3, baseX + 4.2, collarY - 3);

  // Inspection door panel seam & triangular utility lock (y = 1045..1105)
  brush.set("fine_liner", "#222326", 0.75);
  brush.rect(baseX - 3.2, 1045, 6.4, 58, "corner");
  brush.line(baseX + 1.5, 1062, baseX + 1.5, 1066);
  brush.line(baseX + 1.5, 1086, baseX + 1.5, 1090);

  // Cross-contour cylindrical hatch ticks along the lower pole for hyperreal metal texture
  for (let hy = collarY + 8; hy < baseY - 20; hy += 7) {
    let wAtY = map(hy, collarY, baseY - 17, 4.5, 5.8);
    brush.set("2H", "#2e3033", 0.55);
    brush.line(baseX, hy, baseX + wAtY, hy + 1.5);
  }
  for (let hy = topY + 10; hy < collarY; hy += 9) {
    let wAtY = map(hy, topY, collarY, 2.0, 3.7);
    brush.set("2H", "#2e3033", 0.45);
    brush.line(baseX + 0.2, hy, baseX + wAtY, hy + 1.2);
  }

  // 8F. Curved Outreach Bracket Arm & Support Strut
  let armPtsUpper = [
    [baseX, topY, 1.0],
    [baseX + 26, topY - 16, 0.9],
    [baseX + 62, topY - 22, 0.85],
    [armEndX, armEndY, 0.8]
  ];
  let armPtsLower = [
    [baseX + 1.8, topY + 3.2, 1.0],
    [baseX + 27, topY - 13, 0.9],
    [baseX + 62, topY - 19.2, 0.85],
    [armEndX, armEndY + 2.4, 0.8]
  ];

  // Sunlit top edge of bracket arm
  brush.set("cpencil", "#f2e7d3", 0.75);
  brush.spline(armPtsUpper, 0.55);

  // Metallic core & dark underside of bracket arm
  brush.set("fine_liner", "#4a4d50", 0.95);
  brush.spline(armPtsUpper, 0.55);
  brush.set("fine_liner", "#18191b", 1.15);
  brush.spline(armPtsLower, 0.55);

  // Secondary gusset / support strut at the pole-to-arm joint
  brush.set("fine_liner", "#222426", 0.85);
  brush.line(baseX + 1.9, topY + 24, baseX + 28, topY - 13);
  brush.set("cpencil", "#dcd2c0", 0.5);
  brush.line(baseX + 1.5, topY + 22, baseX + 26, topY - 14);

