// ============================================================================
// 1. FOXED, LAID-TEXTURE CREAM PAPER
// ============================================================================
function drawAntiqueLaidPaper() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Cool damp water-stain & age washes
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);

  brush.fill(PAL.paperCool, 65);
  drawWavyBlob(260, 240, 290, 220, 8);
  drawWavyBlob(940, 290, 260, 250, 8);
  drawWavyBlob(310, 920, 320, 230, 8);
  drawWavyBlob(900, 910, 280, 240, 8);
  drawWavyBlob(600, 600, 480, 460, 10);

  brush.fill(PAL.paperWarm, 55);
  drawWavyBlob(600, 130, 450, 110, 8);
  drawWavyBlob(600, 1070, 460, 110, 8);
  drawWavyBlob(130, 600, 110, 440, 8);
  drawWavyBlob(1070, 600, 110, 440, 8);

  // Edge darkening / tidelines
  brush.fill(PAL.paperStain, 75);
  drawWavyBlob(90, 90, 140, 120, 7);
  drawWavyBlob(1110, 95, 130, 130, 7);
  drawWavyBlob(95, 1105, 150, 125, 7);
  drawWavyBlob(1100, 1100, 145, 135, 7);

  // Foxing spots (organic fungal iron spots in aged rag paper)
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.4);
  brush.fill(PAL.foxingLight, 65);
  const foxClusters = [
    [110, 180], [1080, 220], [160, 1040], [1040, 980],
    [420, 95], [790, 1110], [85, 620], [1115, 530],
    [290, 390], [910, 790], [340, 830], [860, 350]
  ];
  for (let c of foxClusters) {
    let count = floor(random(3, 7));
    for (let i = 0; i < count; i++) {
      let fx = c[0] + randomGaussian(0, 36);
      let fy = c[1] + randomGaussian(0, 36);
      let fr = random(4, 16);
      brush.circle(fx, fy, fr, 0.4);
    }
  }

  brush.fill(PAL.foxingDark, 55);
  for (let c of foxClusters) {
    for (let i = 0; i < 3; i++) {
      let fx = c[0] + randomGaussian(0, 22);
      let fy = c[1] + randomGaussian(0, 22);
      brush.circle(fx, fy, random(2, 6), 0.35);
    }
  }
  brush.noFill();

  // Horizontal laid-paper wire screen lines (every ~6px)
  brush.noField();
  for (let y = 12; y < 1188; y += 6) {
    let col = (y % 12 === 0) ? PAL.laidLine : PAL.laidHighlight;
    let w = (y % 12 === 0) ? 0.22 : 0.16;
    brush.set("2H", col, w);
    let x = 14;
    while (x < 1186) {
      let seg = random(90, 240);
      let x2 = min(1186, x + seg);
      brush.line(x, y + random(-0.4, 0.4), x2, y + random(-0.4, 0.4));
      x = x2 + random(4, 16);
    }
  }

  // Vertical chain lines (every ~88px on antique laid mould)
  for (let x = 68; x < 1150; x += 88) {
    brush.set("2H", PAL.laidLine, 0.25);
    for (let y = 16; y < 1184; y += 160) {
      brush.line(x + random(-0.5, 0.5), y, x + random(-0.5, 0.5), min(1184, y + 148));
    }
  }

  // Fine foxing & fiber speckles across the sheet
  for (let i = 0; i < 450; i++) {
    let px = random(15, 1185);
    let py = random(15, 1185);
    let col = random() < 0.5 ? PAL.foxingDark : PAL.foxingLight;
    brush.set("cpencil", col, random(0.2, 0.55));
    brush.line(px, py, px + random(-1.5, 1.5), py + random(-1.5, 1.5));
  }

  // Deckled outer sheet border shadow & fold crease
  brush.set("2H", PAL.inkFaint, 0.22);
  // Subtle horizontal & vertical center fold creases typical of folded Fraktur sheets
  for (let x = 52; x < 1148; x += 45) {
    brush.set("2H", PAL.paperStain, 0.28);
    brush.line(x, 600 + random(-0.8, 0.8), x + 36, 600 + random(-0.8, 0.8));
    brush.set("2H", PAL.laidHighlight, 0.24);
    brush.line(x, 602 + random(-0.8, 0.8), x + 36, 602 + random(-0.8, 0.8));
  }
  for (let y = 52; y < 1148; y += 45) {
    brush.set("2H", PAL.paperStain, 0.25);
    brush.line(600 + random(-0.8, 0.8), y, 600 + random(-0.8, 0.8), y + 36);
  }
}

function drawWavyBlob(cx, cy, rx, ry, steps) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rMod = 0.82 + 0.35 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a));
    brush.vertex(cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod);
  }
  brush.endShape(CLOSE);
}

// ============================================================================
// 2. HAND-LETTERED GOTHIC BORDER & CORNER ROSETTES
// ============================================================================
function drawFrakturBorderFrame() {
  const outer = 52;
  const inner = 136;
  const farOuter = 1148;
  const farInner = 1064;
  const bw = inner - outer; // 84px band

  // Colored washes for border trim and corner blocks
  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.45, 0.35);

  // Corner block mustard & verdigris grounds
  const corners = [
    [outer, outer],
    [farInner, outer],
    [outer, farInner],
    [farInner, farInner]
  ];

  brush.fill(PAL.mustard, 130);
  for (let [cx, cy] of corners) {
    brush.rect(cx + 6, cy + 6, bw - 12, bw - 12, "corner");
  }

  // Thin verdigris guard bands along the inner and outer frames
  brush.fill(PAL.verdigris, 135);
  // Outer trim strips
  brush.rect(inner, outer, farInner - inner, 8, "corner");
  brush.rect(inner, farOuter - 8, farInner - inner, 8, "corner");
  brush.rect(outer, inner, 8, farInner - inner, "corner");
  brush.rect(farOuter - 8, inner, 8, farInner - inner, "corner");

  // Inner trim strips
  brush.fill(PAL.vermilion, 135);
  brush.rect(inner, inner - 7, farInner - inner, 7, "corner");
  brush.rect(inner, farInner, farInner - inner, 7, "corner");
  brush.rect(inner - 7, inner, 7, farInner - inner, "corner");
  brush.rect(farInner, inner, 7, farInner - inner, "corner");

  // Corner rosette petals in vermilion & verdigris
  for (let [cx, cy] of corners) {
    let midX = cx + bw / 2;
    let midY = cy + bw / 2;
    brush.fill(PAL.vermilion, 175);
    brush.circle(midX, midY, 22, 0.2);
    brush.fill(PAL.verdigris, 165);
    brush.circle(midX, midY, 10, 0.15);
  }
  brush.noFill();

  // Corner block folk geometry & iron-gall outlines
  for (let [cx, cy] of corners) {
    let midX = cx + bw / 2;
    let midY = cy + bw / 2;
    brush.set("pen", PAL.inkDark, 0.55);
    brush.rect(cx, cy, bw, bw, "corner");
    brush.rect(cx + 6, cy + 6, bw - 12, bw - 12, "corner");
    brush.circle(midX, midY, 22, 0.15);
    brush.circle(midX, midY, 10, 0.12);
    for (let a = 0; a < 360; a += 45) {
      brush.line(midX + cos(a) * 10, midY + sin(a) * 10, midX + cos(a) * 22, midY + sin(a) * 22);
      brush.arc(midX + cos(a) * 22, midY + sin(a) * 22, 5, a - 70, a + 70);
    }
    // Corner diagonal ticks
    for (let a = 45; a < 360; a += 90) {
      brush.line(midX + cos(a) * 24, midY + sin(a) * 24, midX + cos(a) * 38, midY + sin(a) * 38);
    }
  }

  // Iron-gall double ruling lines around the entire frame
  brush.wiggle(1.2);
  brush.set("pen", PAL.inkDark, 0.65);
  brush.rect(outer, outer, farOuter - outer, farOuter - outer, "corner");
  brush.rect(outer + 8, outer + 8, farOuter - outer - 16, farOuter - outer - 16, "corner");
  brush.rect(inner - 7, inner - 7, farInner - inner + 14, farInner - inner + 14, "corner");
  brush.rect(inner, inner, farInner - inner, farInner - inner, "corner");
  brush.noField();

  // Inner scalloped tooth border inside the main field
  brush.set("pen", PAL.inkMid, 0.38);
  const step = 18;
  for (let x = inner + 9; x <= farInner - 9; x += step) {
    brush.arc(x, inner, 6, 0, 180);
    brush.arc(x, farInner, 6, 180, 360);
    brush.set("rotring", PAL.vermilion, 0.45);
    brush.line(x, inner + 3, x, inner + 5);
    brush.line(x, farInner - 3, x, farInner - 5);
    brush.set("pen", PAL.inkMid, 0.38);
  }
  for (let y = inner + 9; y <= farInner - 9; y += step) {
    brush.arc(inner, y, 6, -90, 90);
    brush.arc(farInner, y, 6, 90, 270);
    brush.set("rotring", PAL.vermilion, 0.45);
    brush.line(inner + 3, y, inner + 5, y);
    brush.line(farInner - 3, y, farInner - 5, y);
    brush.set("pen", PAL.inkMid, 0.38);
  }

  // Hand-lettered Gothic (Fraktur) calligraphic bands along all 4 sides
  // Top Band
  drawGothicTextBand(inner + 14, outer + 14, farInner - inner - 28, bw - 28);
  // Bottom Band
  drawGothicTextBand(inner + 14, farInner + 14, farInner - inner - 28, bw - 28);
  // Left Band (rotated)
  push();
  translate(outer + bw / 2, 600);
  rotate(-90);
  drawGothicTextBand(-(farInner - inner - 28) / 2, -(bw - 28) / 2, farInner - inner - 28, bw - 28);
  pop();
  // Right Band (rotated)
  push();
  translate(farInner + bw / 2, 600);
  rotate(90);
  drawGothicTextBand(-(farInner - inner - 28) / 2, -(bw - 28) / 2, farInner - inner - 28, bw - 28);
  pop();
}

function drawGothicTextBand(x0, y0, w, h) {
  // Faint rubrication guidelines in vermilion/sepia
  const row1Y = y0 + 8;
  const row1H = 17;
  const row2Y = y0 + 34;
  const row2H = 15;

  brush.set("2H", PAL.vermilion, 0.18);
  brush.line(x0, row1Y, x0 + w, row1Y);
  brush.line(x0, row1Y + row1H, x0 + w, row1Y + row1H);
  brush.line(x0, row2Y, x0 + w, row2Y);
  brush.line(x0, row2Y + row2H, x0 + w, row2Y + row2H);

  // Render two lines of dense Fraktur blackletter script
  drawGothicLine(x0 + 4, row1Y, w - 8, row1H, true);
  drawGothicLine(x0 + 4, row2Y, w - 8, row2H, false);
}

function drawGothicLine(xStart, yTop, totalW, xHeight, isMajor) {
  let x = xStart;
  const xEnd = xStart + totalW;
  let wordIdx = 0;

  while (x < xEnd - 18) {
    let isCap = (wordIdx === 0 || random() < 0.24);
    let wordLen = floor(random(3, 8));

    // Rubricated initial capital in Vermilion or Verdigris + Iron-Gall
    if (isCap && x < xEnd - 26) {
      let capCol = (wordIdx % 2 === 0) ? PAL.vermilion : PAL.verdigrisDark;
      let cw = xHeight * 0.85;
      // Double vertical stem of Fraktur Lombardic/Broken capital
      brush.set("pen", capCol, isMajor ? 0.65 : 0.52);
      brush.line(x + 2, yTop - 4, x + 2, yTop + xHeight + 2);
      brush.line(x + 6, yTop - 3, x + 6, yTop + xHeight + 1);
      // Top & bottom calligraphic sweeps
      brush.spline([
        [x - 2, yTop - 2, 0.4],
        [x + cw * 0.5, yTop - 5, 0.9],
        [x + cw, yTop - 1, 0.4]
      ], 0.4);
      brush.spline([
        [x, yTop + xHeight + 1, 0.5],
        [x + cw * 0.55, yTop + xHeight + 3, 0.9],
        [x + cw, yTop + xHeight - 1, 0.3]
      ], 0.4);
      // Right bowl & hairline crossbar
      brush.line(x + cw - 2, yTop - 1, x + cw - 2, yTop + xHeight);
      brush.set("rotring", PAL.inkDark, 0.32);
      brush.line(x + 2, yTop + xHeight * 0.48, x + cw - 1, yTop + xHeight * 0.42);
      // Flourish loop
      brush.arc(x + cw * 0.5, yTop - 4, 4, 180, 360);
      x += cw + 4;
    }

    // Blackletter minims (broken Gothic vertical strokes with 45° diamond heads & feet)
    for (let m = 0; m < wordLen && x < xEnd - 10; m++) {
      let stemW = isMajor ? 0.58 : 0.46;
      let asc = (m === 1 && random() < 0.35) ? -6 : 0;
      let desc = (m === 2 && random() < 0.28) ? 6 : 0;

      // Diamond head serif (45 deg)
      brush.set("pen", PAL.inkDark, stemW);
      brush.line(x - 1.8, yTop + 2 + asc, x + 2.2, yTop - 1 + asc);
      // Vertical minim stem
      brush.line(x, yTop + asc, x - 0.3, yTop + xHeight + desc);
      // Diamond foot serif (45 deg)
      brush.line(x - 2, yTop + xHeight - 1.5, x + 2.5, yTop + xHeight + 1.5);

      // Connecting hairline or arch for n/m/u/o/e
      if (random() < 0.72) {
        brush.set("rotring", PAL.inkMid, 0.28);
        brush.line(x, yTop + 2, x + 5.5, yTop - 0.5);
        if (random() < 0.45) {
          brush.line(x, yTop + xHeight * 0.5, x + 5, yTop + xHeight * 0.38);
        }
      }

      // Calligraphic looped ascender (d / h / k / l)
      if (asc < 0) {
        brush.set("rotring", PAL.inkMid, 0.26);
        brush.arc(x + 3, yTop - 3, 4.5, -110, 90);
      }
      // Umlaut / tittle marks above vowels
      if (asc === 0 && random() < 0.2) {
        brush.set("rotring", PAL.inkDark, 0.3);
        brush.line(x - 1, yTop - 3.5, x + 1, yTop - 5.5);
        brush.line(x + 2, yTop - 3, x + 4, yTop - 5);
      }

      x += isMajor ? 6.2 : 5.4;
    }

    // Word space + occasional diamond punctuation spacer
    x += isMajor ? 8 : 6.5;
    if (random() < 0.35 && x < xEnd - 14) {
      brush.set("rotring", PAL.vermilion, 0.42);
      brush.line(x - 1, yTop + xHeight * 0.35, x + 1.5, yTop + xHeight * 0.35 - 2);
      brush.line(x - 1, yTop + xHeight * 0.7, x + 1.5, yTop + xHeight * 0.7 - 2);
      x += 5;
    }
    wordIdx++;
  }
}

