function drawFolkLeaf(x, y, len, ang, col) {
  push();
  translate(x, y);
  rotate(ang);

  const w = len * 0.38;
  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.45, 0.35);
  brush.fill(col, 165);

  brush.beginShape(0.4);
  brush.vertex(0, 0);
  brush.vertex(w, -len * 0.35);
  brush.vertex(w * 0.65, -len * 0.75);
  brush.vertex(0, -len);
  brush.vertex(-w * 0.65, -len * 0.75);
  brush.vertex(-w, -len * 0.35);
  brush.endShape(CLOSE);
  brush.noFill();

  // Naive half-side hatching inside leaf
  brush.set("rotring", PAL.inkMid, 0.28);
  for (let t = 0.2; t < 0.85; t += 0.14) {
    let ly = -len * t;
    let lw = w * sin(t * 180) * 0.85;
    brush.line(0, ly, lw, ly - 4);
  }

  // Iron-gall pen outline & center vein
  brush.set("pen", PAL.inkDark, 0.45);
  brush.beginShape(0.4);
  brush.vertex(0, 0);
  brush.vertex(w, -len * 0.35);
  brush.vertex(w * 0.65, -len * 0.75);
  brush.vertex(0, -len);
  brush.vertex(-w * 0.65, -len * 0.75);
  brush.vertex(-w, -len * 0.35);
  brush.endShape(CLOSE);
  brush.line(0, 0, 0, -len * 0.92);

  pop();
}

function drawFolkTulip(x, y, sz, ang, cOuter, cCenter, cBase) {
  push();
  translate(x, y);
  rotate(ang);

  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.5, 0.4);

  // Center upright petal
  brush.fill(cCenter, 180);
  brush.beginShape(0.35);
  brush.vertex(0, 0);
  brush.vertex(sz * 0.32, -sz * 0.45);
  brush.vertex(sz * 0.22, -sz * 0.95);
  brush.vertex(0, -sz * 1.18);
  brush.vertex(-sz * 0.22, -sz * 0.95);
  brush.vertex(-sz * 0.32, -sz * 0.45);
  brush.endShape(CLOSE);

  // Left & Right flaring petals
  brush.fill(cOuter, 185);
  for (let s of [-1, 1]) {
    brush.beginShape(0.38);
    brush.vertex(0, 0);
    brush.vertex(s * sz * 0.22, -sz * 0.55);
    brush.vertex(s * sz * 0.58, -sz * 0.98);
    brush.vertex(s * sz * 0.78, -sz * 0.82);
    brush.vertex(s * sz * 0.68, -sz * 0.38);
    brush.vertex(s * sz * 0.32, -sz * 0.05);
    brush.endShape(CLOSE);
  }

  // Calyx cup at base
  brush.fill(cBase, 190);
  brush.arc(0, 0, sz * 0.34, 180, 360);
  brush.circle(0, -sz * 0.12, sz * 0.24, 0.2);
  brush.noFill();

  // Folk decorative striping & polka dots on petals
  brush.set("rotring", PAL.inkDark, 0.32);
  for (let i = -3; i <= 3; i++) {
    brush.line(i * 2.5, -sz * 0.25, i * 4.2, -sz * 0.92);
  }
  // Checkered hatch on outer petal tips
  for (let s of [-1, 1]) {
    for (let t = 0.35; t <= 0.82; t += 0.12) {
      brush.line(s * sz * 0.2, -sz * t, s * sz * 0.64, -sz * (t - 0.06));
    }
  }

  // Crisp brown iron-gall pen outlines
  brush.set("pen", PAL.inkDark, 0.55);
  // Center petal outline
  brush.beginShape(0.35);
  brush.vertex(0, 0);
  brush.vertex(sz * 0.32, -sz * 0.45);
  brush.vertex(sz * 0.22, -sz * 0.95);
  brush.vertex(0, -sz * 1.18);
  brush.vertex(-sz * 0.22, -sz * 0.95);
  brush.vertex(-sz * 0.32, -sz * 0.45);
  brush.endShape(CLOSE);

  // Outer petals outlines
  for (let s of [-1, 1]) {
    brush.beginShape(0.38);
    brush.vertex(0, 0);
    brush.vertex(s * sz * 0.22, -sz * 0.55);
    brush.vertex(s * sz * 0.58, -sz * 0.98);
    brush.vertex(s * sz * 0.78, -sz * 0.82);
    brush.vertex(s * sz * 0.68, -sz * 0.38);
    brush.vertex(s * sz * 0.32, -sz * 0.05);
    brush.endShape(CLOSE);
  }

  // Scalloped crown stamens above center petal
  for (let i = -2; i <= 2; i++) {
    let sx = i * sz * 0.11;
    brush.line(sx * 0.5, -sz * 1.05, sx, -sz * 1.28);
    brush.circle(sx, -sz * 1.31, 2.5, 0.15);
  }

  // Base calyx outline
  brush.circle(0, -sz * 0.12, sz * 0.24, 0.15);

  pop();
}

function drawFolkBud(x, y, sz, ang, cMain, cTip) {
