function drawFolkHeart(x, y, sz, ang, cFill, cInner, scalloped) {
  push();
  translate(x, y);
  rotate(ang);

  const pts = [];
  const steps = 28;
  for (let i = 0; i < steps; i++) {
    let t = (i / steps) * 360;
    // Parametric folk heart
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    pts.push([hx * (sz / 17), hy * (sz / 17)]);
  }

  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.5, 0.38);

  brush.fill(cFill, 180);
  brush.beginShape(0.3);
  for (let p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(CLOSE);

  if (cInner) {
    brush.fill(cInner, 185);
    brush.beginShape(0.3);
    for (let p of pts) brush.vertex(p[0] * 0.56, p[1] * 0.56);
    brush.endShape(CLOSE);
  }
  brush.noFill();

  // Iron-gall outlines & inner folk cross-hatching
  brush.set("pen", PAL.inkDark, 0.52);
  brush.beginShape(0.3);
  for (let p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(CLOSE);

  if (cInner) {
    brush.set("pen", PAL.inkDark, 0.38);
    brush.beginShape(0.3);
    for (let p of pts) brush.vertex(p[0] * 0.56, p[1] * 0.56);
    brush.endShape(CLOSE);
  }

  // Scalloped lace border around heart
  if (scalloped) {
    brush.set("rotring", PAL.inkMid, 0.32);
    for (let i = 0; i < pts.length; i += 2) {
      let p1 = pts[i];
      let p2 = pts[(i + 2) % pts.length];
      let mx = (p1[0] + p2[0]) * 0.58;
      let my = (p1[1] + p2[1]) * 0.58;
      brush.circle(mx, my, 2.2, 0.15);
    }
  }

  pop();
}

function drawDistelfink(x, y, sc, faceDir, isElaborate) {
  push();
  translate(x, y);
  scale(faceDir * sc, sc);

  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.5, 0.38);

  // 1. Fan tail feathers (Verdigris & Vermilion alternating plumes)
  const tailAngles = [148, 162, 176, 190, 204];
  for (let i = 0; i < tailAngles.length; i++) {
    let ta = tailAngles[i];
    let col = (i % 2 === 0) ? PAL.verdigris : PAL.vermilion;
    brush.fill(col, 180);
    brush.beginShape(0.35);
    brush.vertex(-36, 8);
    brush.vertex(-36 + cos(ta - 6) * 68, 8 + sin(ta - 6) * 68);
    brush.vertex(-36 + cos(ta) * 78, 8 + sin(ta) * 78);
    brush.vertex(-36 + cos(ta + 6) * 68, 8 + sin(ta + 6) * 68);
    brush.endShape(CLOSE);
  }

  // 2. Plump folk bird body & breast (Mustard gold)
  brush.fill(PAL.mustard, 190);
  brush.beginShape(0.42);
  brush.vertex(-42, 6);    // Tail base
  brush.vertex(-15, -18);  // Back
  brush.vertex(22, -26);   // Neck/throat
  brush.vertex(36, -46);   // Head crown
  brush.vertex(50, -36);   // Forehead
  brush.vertex(44, -18);   // Chin
  brush.vertex(46, 10);    // Proud puffed chest
  brush.vertex(18, 32);    // Belly
  brush.vertex(-22, 26);   // Under-tail
  brush.endShape(CLOSE);

  // 3. Vermilion cheek & throat patch
  brush.fill(PAL.vermilion, 175);
  brush.circle(36, -28, 12, 0.25);

  // 4. Bold Folk Wing (Vermilion base + Verdigris secondary coverts)
  brush.fill(PAL.vermilion, 190);
  brush.beginShape(0.4);
  brush.vertex(14, -10);
  brush.vertex(-12, -24);
  brush.vertex(-54, -14);
  brush.vertex(-44, 8);
  brush.vertex(-8, 14);
  brush.endShape(CLOSE);

  brush.fill(PAL.verdigris, 185);
  brush.beginShape(0.38);
  brush.vertex(14, -10);
  brush.vertex(-4, -18);
  brush.vertex(-26, -10);
  brush.vertex(-16, 6);
  brush.endShape(CLOSE);
  brush.noFill();

  // ---- IRON-GALL PEN OUTLINES & NAIVE FOLK PATTERNING ----
  brush.set("pen", PAL.inkDark, 0.55);

  // Tail feather outlines & central quills
  for (let i = 0; i < tailAngles.length; i++) {
    let ta = tailAngles[i];
    brush.beginShape(0.35);
    brush.vertex(-36, 8);
    brush.vertex(-36 + cos(ta - 6) * 68, 8 + sin(ta - 6) * 68);
    brush.vertex(-36 + cos(ta) * 78, 8 + sin(ta) * 78);
    brush.vertex(-36 + cos(ta + 6) * 68, 8 + sin(ta + 6) * 68);
    brush.endShape(CLOSE);
    brush.set("rotring", PAL.inkMid, 0.3);
    brush.line(-36, 8, -36 + cos(ta) * 72, 8 + sin(ta) * 72);
    brush.set("pen", PAL.inkDark, 0.55);
  }

  // Body outline
  brush.beginShape(0.42);
  brush.vertex(-42, 6);
  brush.vertex(-15, -18);
  brush.vertex(22, -26);
  brush.vertex(36, -46);
  brush.vertex(50, -36);
  brush.vertex(44, -18);
  brush.vertex(46, 10);
  brush.vertex(18, 32);
  brush.vertex(-22, 26);
  brush.endShape(CLOSE);

  // Wing outline & feather bars
  brush.beginShape(0.4);
  brush.vertex(14, -10);
  brush.vertex(-12, -24);
  brush.vertex(-54, -14);
  brush.vertex(-44, 8);
  brush.vertex(-8, 14);
  brush.endShape(CLOSE);

  brush.set("rotring", PAL.inkDark, 0.36);
  brush.line(-16, -20, -14, 10);
  brush.line(-24, -18, -22, 10);
  for (let fy = -12; fy <= 6; fy += 5) {
    brush.line(-24, fy, -48, fy - 3);
  }

  // Scalloped folk breast & belly plumage scales
  if (isElaborate) {
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 3; col++) {
        let sx = 12 + col * 9 - row * 3;
        let sy = -2 + row * 7;
        brush.arc(sx, sy, 4.5, 0, 180);
      }
    }
  }

  // Wing coverts dots
  for (let dx = -10; dx <= 6; dx += 6) {
    for (let dy = -10; dy <= 0; dy += 5) {
      brush.circle(dx, dy, 1.5, 0.1);
    }
  }

  // Crested head plumes
  brush.set("pen", PAL.inkDark, 0.45);
  for (let i = 0; i < 3; i++) {
    let ca = -125 - i * 18;
    brush.line(34 - i * 3, -44, 34 + cos(ca) * 16, -44 + sin(ca) * 16);
    brush.circle(34 + cos(ca) * 18, -44 + sin(ca) * 18, 2.2, 0.15);
  }

  // Conical finch beak (open singing beak with tongue line)
  brush.beginShape(0.2);
  brush.vertex(49, -37);
  brush.vertex(66, -34);
  brush.vertex(48, -29);
  brush.endShape(CLOSE);
  brush.beginShape(0.2);
  brush.vertex(48, -29);
  brush.vertex(63, -26);
  brush.vertex(45, -23);
  brush.endShape(CLOSE);

  // Naive round folk eye
  brush.noStroke();
  brush.fill(PAL.paperBase, 230);
  brush.circle(39, -34, 4.8, 0.1);
  brush.noFill();
  brush.set("pen", PAL.inkDark, 0.48);
  brush.circle(39, -34, 4.8, 0.1);
  brush.circle(40, -34, 1.8, 0.1);

  // Sturdy folk legs & claws gripping the branch
  brush.set("pen", PAL.inkDark, 0.6);
  brush.line(2, 29, -4, 48);
  brush.line(14, 30, 10, 48);
  for (let lx of [-4, 10]) {
    brush.line(lx, 48, lx + 8, 50);
    brush.line(lx, 48, lx + 5, 54);
    brush.line(lx, 48, lx - 6, 51);
  }

  pop();
}

function drawTopCenterMotif(cx, cy) {
  // Large crowned folk heart with compass rosette at the top of the sheet
  drawFolkHeart(cx, cy, 52, 0, PAL.vermilion, PAL.mustard, true);

  // Small verdigris & slate compass star inside the heart
  push();
  translate(cx, cy - 4);
  brush.set("pen", PAL.inkDark, 0.42);
  for (let a = 0; a < 360; a += 60) {
    brush.line(0, 0, cos(a) * 18, sin(a) * 18);
  }
  brush.circle(0, 0, 18, 0.15);
  pop();

  // Three petite tulips sprouting from the top notch of the heart
  drawFolkTulip(cx, cy - 38, 34, 0, PAL.verdigris, PAL.vermilion, PAL.mustard);
  drawFolkTulip(cx - 28, cy - 32, 28, -32, PAL.mustard, PAL.verdigris, PAL.vermilion);
  drawFolkTulip(cx + 28, cy - 32, 28, 32, PAL.mustard, PAL.verdigris, PAL.vermilion);
}

function drawBottomCenterUrn(cx, cy) {
  // Symmetrical Fraktur Heart-Urn at bottom center
  drawFolkHeart(cx, cy, 54, 0, PAL.verdigris, PAL.mustard, true);

  // Pedestal foot below the heart-urn
  brush.noStroke();
  brush.fill(PAL.vermilion, 185);
  brush.beginShape(0.3);
  brush.vertex(cx - 12, cy + 38);
  brush.vertex(cx + 12, cy + 38);
  brush.vertex(cx + 34, cy + 62);
  brush.vertex(cx - 34, cy + 62);
  brush.endShape(CLOSE);
  brush.noFill();

  brush.set("pen", PAL.inkDark, 0.55);
  brush.beginShape(0.3);
  brush.vertex(cx - 12, cy + 38);
  brush.vertex(cx + 12, cy + 38);
  brush.vertex(cx + 34, cy + 62);
  brush.vertex(cx - 34, cy + 62);
  brush.endShape(CLOSE);

  // S-scroll handles on either side of the urn
  for (let s of [-1, 1]) {
    brush.spline([
      [cx + s * 38, cy - 22, 0.6],
      [cx + s * 68, cy - 32, 0.8],
      [cx + s * 64, cy + 4, 0.7],
      [cx + s * 26, cy + 18, 0.5]
    ], 0.5);
  }

  // Center upright tulip rising from the urn toward the bottom of the nest
  drawFolkTulip(cx, cy - 42, 46, 0, PAL.vermilion, PAL.mustard, PAL.verdigris);

  // Two small Gothic date cartouches ("ANNO" / "1817") flanking the urn
  for (let s of [-1, 1]) {
    let bx = cx + s * 130;
    let by = cy + 38;
    brush.noStroke();
    brush.fill(PAL.mustard, 115);
    brush.rect(bx, by, 86, 26, "center");
    brush.noFill();
    brush.set("pen", PAL.inkDark, 0.45);
    brush.rect(bx, by, 86, 26, "center");
    brush.rect(bx, by, 80, 20, "center");
    drawGothicLine(bx - 34, by - 6, 68, 12, false);
  }
}

function drawHexStar(cx, cy, r) {
  push();
  translate(cx, cy);
  brush.noStroke();
  brush.fillBleed(0.1, "out");
  for (let i = 0; i < 6; i++) {
    let a = i * 60;
    let col = (i % 2 === 0) ? PAL.vermilion : PAL.verdigris;
    brush.fill(col, 175);
    brush.beginShape(0.2);
    brush.vertex(0, 0);
    brush.vertex(cos(a - 18) * r * 0.55, sin(a - 18) * r * 0.55);
    brush.vertex(cos(a) * r, sin(a) * r);
    brush.vertex(cos(a + 18) * r * 0.55, sin(a + 18) * r * 0.55);
    brush.endShape(CLOSE);
  }
  brush.fill(PAL.mustard, 190);
  brush.circle(0, 0, r * 0.35, 0.15);
  brush.noFill();

  brush.set("pen", PAL.inkDark, 0.42);
  brush.circle(0, 0, r, 0.12);
  brush.circle(0, 0, r * 0.35, 0.12);
  for (let i = 0; i < 6; i++) {
    let a = i * 60;
    brush.line(0, 0, cos(a) * r, sin(a) * r);
  }
  pop();
}

// ============================================================================
// 4. TROMPE-L'OEIL CAST SHADOW OF THE NEST ON THE FRAKTUR SHEET
// ============================================================================
function drawNestDropShadow(cx, cy) {
  // Light comes from upper-left (~315 deg), so the nest casts a cool umber-slate
  // shadow shifted toward bottom-right over the paper and folk motifs
  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);

  // Soft outer penumbra
  brush.fill(PAL.slateBlue, 70);
  drawWavyBlob(cx + 28, cy + 32, 245, 235, 16);

  brush.fill(PAL.strawShadow, 95);
  drawWavyBlob(cx + 22, cy + 26, 225, 218, 16);

  // Deeper core shadow directly beneath the woven straw ring
  brush.fill(PAL.strawAbyss, 130);
  drawWavyBlob(cx + 12, cy + 16, 200, 195, 16);

  // Deep shadow inside the cup hollow
  brush.fill(PAL.strawAbyss, 190);
  drawWavyBlob(cx, cy, 155, 148, 14);
  brush.noFill();
}

// ============================================================================
// 5 & 7. OBSESSIVELY REALISTIC STRAW NEST
// ============================================================================
function drawStrawNestBackAndMid(cx, cy) {
  // Pass 1: Wild radiating outer dried stalks & their crisp cast shadows on the paper
  const outerCount = 85;
  for (let i = 0; i < outerCount; i++) {
    let baseAng = (i / outerCount) * 360 + random(-4, 4);
    let rStart = random(145, 205);
    let rEnd = random(225, 295);
    let tangShift = random(-55, 55) * (random() < 0.5 ? 1 : -1);

    let x1 = cx + cos(baseAng) * rStart;
    let y1 = cy + sin(baseAng) * rStart;
    let x3 = cx + cos(baseAng + tangShift) * rEnd;
    let y3 = cy + sin(baseAng + tangShift) * rEnd;
    let midR = (rStart + rEnd) * 0.52;
    let midA = baseAng + tangShift * 0.45 + random(-8, 8);
    let x2 = cx + cos(midA) * midR;
    let y2 = cy + sin(midA) * midR;

    let pts = [[x1, y1], [x2, y2], [x3, y3]];

    // Cast shadow of this individual protruding stalk onto the Fraktur sheet!
    let shOffset = map(rEnd, 220, 295, 7, 15);
    brush.set("2B", PAL.inkMid, random(0.45, 0.85));
    brush.spline([
      [x1 + shOffset * 0.6, y1 + shOffset * 0.7, 0.6],
      [x2 + shOffset * 0.85, y2 + shOffset * 0.95, 0.7],
      [x3 + shOffset, y3 + shOffset * 1.1, 0.3]
    ], 0.35);

    // Draw the 3D shaded straw stalk itself
    let w = random(2.2, 4.4);
    let lightDot = -cos(baseAng + 45); // +1 on upper-left, -1 on lower-right
    drawRealisticStrawStalk(pts, w, lightDot, random() < 0.35);
  }

  // Pass 2: Dark interstitial crevices & chaff inside the woven ring
  for (let i = 0; i < 320; i++) {
    let a = random(360);
    let r = random(110, 220);
    let span = random(18, 42);
    let x1 = cx + cos(a) * r;
    let y1 = cy + sin(a) * r;
    let x2 = cx + cos(a + span * 0.5) * (r + random(-12, 12));
    let y2 = cy + sin(a + span * 0.5) * (r + random(-12, 12));
    let x3 = cx + cos(a + span) * r;
    let y3 = cy + sin(a + span) * r;

    let col = random() < 0.6 ? PAL.strawAbyss : PAL.strawShadow;
    brush.set("charcoal", col, random(0.8, 1.8));
    brush.spline([[x1, y1, 0.5], [x2, y2, 0.9], [x3, y3, 0.5]], 0.4);
  }

  // Pass 3: Main structural woven straw ring (hundreds of interlocking stalks)
  const weaveCount = 260;
  for (let i = 0; i < weaveCount; i++) {
    let a1 = random(360);
    let dir = (i % 2 === 0) ? 1 : -1;
    let arcSpan = random(35, 82) * dir;
    let r1 = random(118, 228);
    let r2 = constrain(r1 + random(-24, 24), 112, 235);
    let r3 = constrain(r2 + random(-24, 24), 115, 242);

    let a2 = a1 + arcSpan * 0.5;
    let a3 = a1 + arcSpan;

    let pts = [
      [cx + cos(a1) * r1, cy + sin(a1) * r1],
      [cx + cos(a2) * r2, cy + sin(a2) * r2],
      [cx + cos(a3) * r3, cy + sin(a3) * r3]
    ];

    // Illumination depends on radial position and upper-left light direction
    let midX = pts[1][0] - cx;
    let midY = pts[1][1] - cy;
    let lightVal = (-midX - midY) / 240; // Positive toward upper-left, negative toward lower-right
    // Inner bowl slopes inward, so inner bottom-right catches some light while inner top-left is in bowl shadow
    if (r2 < 155) {
      lightVal = (midX + midY) / 220 - 0.15;
    }

    let w = random(2.0, 4.6);
    drawRealisticStrawStalk(pts, w, lightVal, random() < 0.28);
  }

  // Pass 4: Inner cup lining (fine curved hay, dried grass & rootlets cradling the hollow)
  for (let i = 0; i < 190; i++) {
    let a1 = random(360);
    let a2 = a1 + random(-55, 55);
    let a3 = a2 + random(-55, 55);
    let r1 = random(120, 165);
    let r2 = random(88, 138);
    let r3 = random(65, 125);

    let pts = [
      [cx + cos(a1) * r1, cy + sin(a1) * r1],
      [cx + cos(a2) * r2, cy + sin(a2) * r2],
      [cx + cos(a3) * r3, cy + sin(a3) * r3]
    ];

    // Deep hollow shading
    let col = random([PAL.strawShadow, PAL.strawUmber, PAL.strawMid, PAL.strawCool]);
    if (r2 < 110) col = random([PAL.strawAbyss, PAL.strawShadow, PAL.strawUmber]);

    brush.set("cpencil", col, random(0.45, 0.95));
    brush.spline([
      [pts[0][0], pts[0][1], 0.4],
      [pts[1][0], pts[1][1], 0.85],
      [pts[2][0], pts[2][1], 0.3]
    ], 0.45);

    // Fine silica highlight on upper rim grass threads
    if (r1 > 135 && random() < 0.45) {
      brush.set("2H", PAL.strawPale, 0.28);
      brush.spline([
        [pts[0][0] - 0.6, pts[0][1] - 0.6, 0.3],
        [pts[1][0] - 0.6, pts[1][1] - 0.6, 0.7],
        [pts[2][0] - 0.6, pts[2][1] - 0.6, 0.2]
      ], 0.45);
    }
  }
}

function drawStrawNestForeground(cx, cy) {
  // Foreground stalks and fine wisps along the rim that overlap the outer edge of the egg,
  // embedding the egg deep inside the straw cup!
  const fgCount = 46;
  for (let i = 0; i < fgCount; i++) {
    // Focus around the perimeter of the egg (r ~ 88 to 145)
    let a1 = random(360);
    // Avoid covering the central dome of the egg
    let span = random(38, 68) * (random() < 0.5 ? 1 : -1);
    let a2 = a1 + span * 0.5;
    let a3 = a1 + span;

    // Map radius to hug the egg silhouette closely
    let rEggAtA2 = getEggOuterRadiusAtAngle(a2);
    let r1 = rEggAtA2 + random(16, 48);
    let r2 = rEggAtA2 + random(-7, 14); // Overlaps the very edge of the egg by up to 7px!
    let r3 = rEggAtA2 + random(14, 46);

    let pts = [
      [EGG_CX + cos(a1) * r1, EGG_CY + sin(a1) * r1],
      [EGG_CX + cos(a2) * r2, EGG_CY + sin(a2) * r2],
      [EGG_CX + cos(a3) * r3, EGG_CY + sin(a3) * r3]
    ];

    // Tiny dark contact shadow cast by this foreground stalk onto the egg/nest
    brush.set("2B", PAL.eggAbyss, 0.55);
    brush.spline([
      [pts[0][0] + 2, pts[0][1] + 2.5, 0.3],
      [pts[1][0] + 2, pts[1][1] + 2.5, 0.8],
      [pts[2][0] + 2, pts[2][1] + 2.5, 0.3]
    ], 0.4);

    let lightVal = (-cos(a2) - sin(a2)) * 0.65;
    drawRealisticStrawStalk(pts, random(1.8, 3.6), lightVal, random() < 0.35);
  }

  // A few ultra-crisp dried seed husks / chaff and fine split fibers on the lit rim
  for (let i = 0; i < 28; i++) {
    let a = random(360);
    let r = random(115, 225);
    let sx = cx + cos(a) * r;
    let sy = cy + sin(a) * r;
    let sa = a + 90 + random(-35, 35);
    drawDriedOatHusk(sx, sy, sa, (-cos(a) - sin(a)) > -0.2);
  }
}

function getEggOuterRadiusAtAngle(worldAngle) {
  let localA = worldAngle - EGG_ANGLE;
  let ex = EGG_A * cos(localA);
  let ey = EGG_B * sin(localA) * (1 - EGG_K * cos(localA));
  return sqrt(ex * ex + ey * ey);
}

function drawRealisticStrawStalk(pts, w, lightVal, hasNode) {
  // Compute perpendicular normal to the stalk for 3D cylindrical shading across its width
  let dx = pts[2][0] - pts[0][0];
  let dy = pts[2][1] - pts[0][1];
  let len = max(1, sqrt(dx * dx + dy * dy));
  let nx = -dy / len;
  let ny = dx / len;
  // Orient normal so (nx, ny) points toward the upper-left light (-1, -1)
  if (nx * (-1) + ny * (-1) < 0) {
    nx = -nx;
    ny = -ny;
  }

  // Choose base palette based on illumination and natural straw variation
  let cShadow = PAL.strawShadow;
  let cMid = (lightVal > 0.1) ? PAL.strawGold : (lightVal > -0.2 ? PAL.strawMid : PAL.strawUmber);
  if (random() < 0.35) cMid = PAL.strawCool;
  let cLit = (lightVal > 0.15) ? PAL.strawPale : PAL.strawGold;
  let cSpec = (lightVal > 0.0) ? PAL.strawSpec : PAL.strawPale;

  // 1. Dark crevice shadow underneath the stalk (away from light)
  brush.set("2B", PAL.strawAbyss, w * 0.26);
  brush.spline([
    [pts[0][0] - nx * w * 0.55, pts[0][1] - ny * w * 0.55, 0.5],
    [pts[1][0] - nx * w * 0.55, pts[1][1] - ny * w * 0.55, 0.85],
    [pts[2][0] - nx * w * 0.55, pts[2][1] - ny * w * 0.55, 0.5]
  ], 0.38);

  // 2. Shadowed underside of the cylinder
  brush.set("cpencil", cShadow, w * 0.32);
  brush.spline([
    [pts[0][0] - nx * w * 0.28, pts[0][1] - ny * w * 0.28, 0.6],
    [pts[1][0] - nx * w * 0.28, pts[1][1] - ny * w * 0.28, 0.9],
    [pts[2][0] - nx * w * 0.28, pts[2][1] - ny * w * 0.28, 0.6]
  ], 0.38);

  // 3. Main mid-tone body of the dried stalk
  brush.set("cpencil", cMid, w * 0.42);
  brush.spline([
    [pts[0][0], pts[0][1], 0.7],
    [pts[1][0], pts[1][1], 0.95],
    [pts[2][0], pts[2][1], 0.7]
  ], 0.38);

  // 4. Lit upper plane of the stalk
  brush.set("cpencil", cLit, w * 0.3);
  brush.spline([
    [pts[0][0] + nx * w * 0.22, pts[0][1] + ny * w * 0.22, 0.6],
    [pts[1][0] + nx * w * 0.22, pts[1][1] + ny * w * 0.22, 0.9],
    [pts[2][0] + nx * w * 0.22, pts[2][1] + ny * w * 0.22, 0.6]
  ], 0.38);

  // 5. Longitudinal vascular striations & waxy silica specular highlight
  brush.set("2H", PAL.strawUmber, 0.22);
  brush.spline([
    [pts[0][0] - nx * w * 0.08, pts[0][1] - ny * w * 0.08, 0.5],
    [pts[1][0] - nx * w * 0.08, pts[1][1] - ny * w * 0.08, 0.8],
    [pts[2][0] - nx * w * 0.08, pts[2][1] - ny * w * 0.08, 0.5]
  ], 0.38);

  if (lightVal > -0.25) {
    brush.set("2H", cSpec, 0.28);
    brush.spline([
      [pts[0][0] + nx * w * 0.34, pts[0][1] + ny * w * 0.34, 0.4],
      [pts[1][0] + nx * w * 0.34, pts[1][1] + ny * w * 0.34, 0.95],
      [pts[2][0] + nx * w * 0.34, pts[2][1] + ny * w * 0.34, 0.4]
    ], 0.38);
  }

  // 6. Optional culm node (the swollen dark knuckle on cereal straw)
  if (hasNode) {
    let kx = pts[1][0];
    let ky = pts[1][1];
    brush.set("pen", PAL.strawAbyss, 0.55);
    brush.line(kx - nx * w * 0.55, ky - ny * w * 0.55, kx + nx * w * 0.55, ky + ny * w * 0.55);
    brush.set("2H", PAL.strawSpec, 0.32);
    brush.line(
      kx + (dx / len) * 2.2 - nx * w * 0.45,
      ky + (dy / len) * 2.2 - ny * w * 0.45,
      kx + (dx / len) * 2.2 + nx * w * 0.45,
      ky + (dy / len) * 2.2 + ny * w * 0.45
    );
  }
}

function drawDriedOatHusk(x, y, ang, isLit) {
  push();
  translate(x, y);
  rotate(ang);
  let col = isLit ? PAL.strawPale : PAL.strawGold;
  brush.set("cpencil", PAL.strawShadow, 0.45);
  brush.line(-6, 1, 8, 1);
  brush.set("cpencil", col, 0.55);
  brush.beginShape(0.35);
  brush.vertex(-7, 0);
  brush.vertex(0, -2.8);
  brush.vertex(8, 0);
  brush.vertex(0, 2.4);
  brush.endShape(CLOSE);
  if (isLit) {
    brush.set("2H", PAL.strawSpec, 0.26);
    brush.line(-5, -1.2, 6, -0.8);
    // Fine awn (bristle) extending from oat husk
    brush.line(8, 0, 18, -3);
  }
  pop();
}

// ============================================================================
// 6. HYPERREALISTIC SPECKLED BROWN HEN'S EGG
// ============================================================================
function getEggVertexWorld(theta, scaleX = 1, scaleY = 1, shiftX = 0, shiftY = 0) {
  let lx = EGG_A * scaleX * cos(theta) + shiftX;
  let ly = EGG_B * scaleY * sin(theta) * (1 - EGG_K * cos(theta)) + shiftY;
  let ca = cos(EGG_ANGLE);
  let sa = sin(EGG_ANGLE);
  return [
    EGG_CX + lx * ca - ly * sa,
    EGG_CY + lx * sa + ly * ca
  ];
}

function localToWorldEgg(lx, ly) {
  let ca = cos(EGG_ANGLE);
  let sa = sin(EGG_ANGLE);
  return [
    EGG_CX + lx * ca - ly * sa,
    EGG_CY + lx * sa + ly * ca
  ];
}

function evaluateEgg3D(lx, ly) {
  // Returns { inside, u, halfW, lz, nx, ny, nz, keyLight, bounceLight, bloomFactor, specFactor }
  let u = lx / EGG_A;
  if (abs(u) >= 0.998) return { inside: false };
  let halfW = EGG_B * sqrt(1 - u * u) * (1 - EGG_K * u);
  if (abs(ly) >= halfW) return { inside: false };

  let lz = sqrt(max(0.01, halfW * halfW - ly * ly));

  // Compute outward 3D surface normal in local egg coords, then rotate to world XY
  let nxLocal = lx / (EGG_A * EGG_A) + 0.12 * EGG_K / EGG_A;
  let nyLocal = ly / (EGG_B * EGG_B);
  let nzLocal = lz / (EGG_B * EGG_B);
  let ca = cos(EGG_ANGLE);
  let sa = sin(EGG_ANGLE);
  let nx = nxLocal * ca - nyLocal * sa;
  let ny = nxLocal * sa + nyLocal * ca;
  let nz = nzLocal;
  let nLen = sqrt(nx * nx + ny * ny + nz * nz);
  nx /= nLen;
  ny /= nLen;
  nz /= nLen;

  // Key studio north-light from upper-left: (-0.46, -0.54, 0.70)
  let keyDot = max(0, nx * (-0.46) + ny * (-0.54) + nz * 0.70);

  // Warm reflected bounce light from the golden straw nest along lower-right rim: (0.55, 0.62, -0.15)
  let bounceDot = max(0, nx * 0.55 + ny * 0.62 + nz * (-0.12)) * pow(1 - nz, 0.65);

  // Cool cuticular bloom (strongest in upper-left midtones & grazing sky reflection)
  let skyDot = max(0, nx * (-0.30) + ny * (-0.45) + nz * 0.84);
  let bloomFactor = pow(skyDot, 1.35) * (0.45 + 0.55 * sqrt(1 - nz * 0.6));

  // Satin-matte chalky specular sheen around upper-left dome
  let halfVecX = -0.26, halfVecY = -0.31, halfVecZ = 0.91;
  let specDot = max(0, nx * halfVecX + ny * halfVecY + nz * halfVecZ);
  let specFactor = pow(specDot, 14);

  return {
    inside: true,
    u,
    halfW,
    lz,
    nx,
    ny,
    nz,
    keyDot,
    bounceDot,
    bloomFactor,
    specFactor
  };
}

function drawHyperrealEgg() {
  // ---- A. DEEP CONTACT SHADOW / AMBIENT OCCLUSION IN THE NEST HOLLOW ----
  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.25);

  brush.fill(PAL.eggAbyss, 210);
  drawEggContourShape(1.06, 1.07, 7, 10);
  brush.fill(PAL.strawAbyss, 180);
  drawEggContourShape(1.03, 1.03, 3, 5);

  // ---- B. MULTI-LAYER WATERCOLOR UNDERPAINTING OF THE 3D EGG FORM ----
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.35, 0.2);

  // 1. Base terracotta-chestnut shell color
  brush.fill(PAL.eggBase, 225);
  drawEggContourShape(1.0, 1.0, 0, 0);

  // 2. Warm rich midtone body
  brush.fill(PAL.eggWarm, 150);
  drawEggContourShape(0.92, 0.90, -5, -4);

  // 3. Deep core shadow sweeping across lower-right belly
  brush.fill(PAL.eggShadow, 175);
  drawEggContourShape(0.86, 0.72, 10, 16);

  brush.fill(PAL.eggAbyss, 130);
  drawEggContourShape(0.75, 0.52, 12, 22);

  // 4. Warm golden straw bounce-light along the very bottom-right rim
  brush.fill(PAL.eggBounce, 125);
  drawEggCrescentRim(30, 155, 0.88, 1.0);

  // 5. Cool violet-slate bloom wash across the upper-left lit dome
  brush.fill(PAL.eggBloom, 115);
  drawEggContourShape(0.72, 0.65, -16, -15);

  // 6. Soft chalky satin highlight wash
  brush.fill(PAL.eggBloomLight, 130);
  drawEggContourShape(0.42, 0.38, -28, -22);

  brush.fill(PAL.eggHighlight, 120);
  drawEggContourShape(0.22, 0.20, -34, -24);
  brush.noFill();

  // ---- C. OBSESSIVE 3D SURFACE MODELING & CHALKY BLOOM SCUMBLING ----
  // Thousands of fine contoured dry-media strokes that follow the 3D surface curvature
  for (let lx = -EGG_A + 2; lx <= EGG_A - 2; lx += 2.3) {
    let u = lx / EGG_A;
    let halfW = EGG_B * sqrt(max(0, 1 - u * u)) * (1 - EGG_K * u);
    for (let ly = -halfW + 1.5; ly <= halfW - 1.5; ly += 2.3) {
      let jx = lx + random(-0.9, 0.9);
      let jy = ly + random(-0.9, 0.9);
      let info = evaluateEgg3D(jx, jy);
      if (!info.inside) continue;

      let [wx, wy] = localToWorldEgg(jx, jy);

      // Determine local micro-stroke color from 3D lighting model
      let col = PAL.eggBase;
      let weight = 0.34;
      let brushName = "cpencil";

      if (info.specFactor > 0.42) {
        col = random() < 0.65 ? PAL.eggHighlight : PAL.eggBloomLight;
        brushName = "2H";
        weight = 0.32;
      } else if (info.bloomFactor > 0.48 && random() < 0.62) {
        col = random() < 0.5 ? PAL.eggBloomLight : PAL.eggBloom;
        brushName = "cpencil";
        weight = 0.35;
      } else if (info.keyDot > 0.58) {
        col = random() < 0.55 ? PAL.eggWarm : PAL.eggBloom;
        weight = 0.34;
      } else if (info.keyDot > 0.32) {
        col = random() < 0.6 ? PAL.eggBase : PAL.eggWarm;
        weight = 0.36;
      } else if (info.bounceDot > 0.26 && info.nz < 0.55) {
        col = random() < 0.65 ? PAL.eggBounce : PAL.eggMid;
        weight = 0.36;
      } else if (info.keyDot < 0.14) {
        col = random() < 0.55 ? PAL.eggAbyss : PAL.eggShadow;
        weight = 0.42;
      } else {
        col = random() < 0.5 ? PAL.eggMid : PAL.eggShadow;
        weight = 0.38;
      }

      // Stroke direction follows the cross-contour tangent of the ovoid
      let tangAngle = atan2(info.nx, -info.ny) + random(-18, 18);
      let sLen = random(1.8, 3.8) * (0.4 + 0.6 * info.nz);
      brush.set(brushName, col, weight);
      brush.line(
        wx - cos(tangAngle) * sLen * 0.5,
        wy - sin(tangAngle) * sLen * 0.5,
        wx + cos(tangAngle) * sLen * 0.5,
        wy + sin(tangAngle) * sLen * 0.5
      );
    }
  }

  // ---- D. FAINT CHALKY BLOOM & NATURAL STRAW-SCRAPE MARKS ----
  // Delicate mottled cuticular bloom veil + 2 faint natural scuffs where straw rubbed the bloom
  for (let i = 0; i < 650; i++) {
    let lx = random(-EGG_A * 0.88, EGG_A * 0.85);
    let ly = random(-EGG_B * 0.88, EGG_B * 0.45);
    let info = evaluateEgg3D(lx, ly);
    if (!info.inside || info.keyDot < 0.22) continue;

    if (random() < info.bloomFactor * 1.1) {
      let [wx, wy] = localToWorldEgg(lx, ly);
      let col = info.specFactor > 0.25 ? PAL.eggHighlight : (random() < 0.5 ? PAL.eggBloomLight : PAL.eggBloom);
      brush.set("2H", col, random(0.22, 0.38));
      let a = random(360);
      brush.line(wx, wy, wx + cos(a) * random(1.2, 2.8), wy + sin(a) * random(1.2, 2.8));
    }
  }

  // Subtle organic bloom-scuff line (where a straw stalk scratched the chalky cuticle)
  brush.set("2H", PAL.eggWarm, 0.28);
  let scuff1 = localToWorldEgg(-18, -14);
  let scuff2 = localToWorldEgg(12, -22);
  let scuff3 = localToWorldEgg(38, -19);
  brush.spline([
    [scuff1[0], scuff1[1], 0.3],
    [scuff2[0], scuff2[1], 0.7],
    [scuff3[0], scuff3[1], 0.2]
  ], 0.35);
  brush.set("2H", PAL.eggBloomLight, 0.22);
  brush.spline([
    [scuff1[0], scuff1[1] - 0.9, 0.2],
    [scuff2[0], scuff2[1] - 0.9, 0.6],
    [scuff3[0], scuff3[1] - 0.9, 0.2]
  ], 0.35);

  // ---- E. MICROSCOPIC CHALKY SHELL PORES (Cratered dimples across the shell) ----
  for (let i = 0; i < 1900; i++) {
    let lx = random(-EGG_A * 0.96, EGG_A * 0.96);
    let ly = random(-EGG_B * 0.96, EGG_B * 0.96);
    let info = evaluateEgg3D(lx, ly);
    if (!info.inside || info.nz < 0.18) continue;

    let [wx, wy] = localToWorldEgg(lx, jy = ly);
    // Pore shadow pinprick
    let poreCol = info.keyDot > 0.5 ? PAL.eggMid : (info.keyDot > 0.2 ? PAL.eggShadow : PAL.eggAbyss);
    brush.set("rotring", poreCol, random(0.18, 0.32));
    brush.line(wx, wy, wx + 0.5, wy + 0.5);

    // In the raking mid-light zone (terminator to highlight), each pore catches a tiny bright rim!
    if (info.keyDot > 0.24 && info.keyDot < 0.78 && random() < 0.55) {
      let rimCol = info.bloomFactor > 0.4 ? PAL.eggHighlight : PAL.eggBloomLight;
      brush.set("2H", rimCol, 0.2);
      brush.line(wx + 0.6, wy + 0.6, wx + 1.3, wy + 1.1);
    }
  }

  // ---- F. ORGANIC PROTOPORPHYRIN SPECKLES, BLOTCHES & CALCIUM DEPOSITS ----
  // 1. Medium-to-large organic pigment blotches (foreshortened near the curved edge of the egg)
  const blotchCount = 165;
  for (let i = 0; i < blotchCount; i++) {
    // Slightly denser around the broad base (lx < 0) and crown band, natural to hen's eggs
    let lx = random(-EGG_A * 0.94, EGG_A * 0.94);
    if (random() < 0.35) lx = random(-EGG_A * 0.88, -EGG_A * 0.15);
    let u = lx / EGG_A;
    let halfW = EGG_B * sqrt(max(0, 1 - u * u)) * (1 - EGG_K * u);
    let ly = random(-halfW * 0.94, halfW * 0.94);

    let info = evaluateEgg3D(lx, ly);
    if (!info.inside || info.nz < 0.14) continue;

    let [wx, wy] = localToWorldEgg(lx, ly);
    let baseRadius = random(1.2, 4.6);
    if (random() < 0.12) baseRadius = random(4.6, 7.2); // Occasional larger pigment macule

    // Foreshorten the blotch along the radial normal direction as nz -> 0
    let radialAng = atan2(info.ny, info.nx);
    let foreshorten = constrain(info.nz, 0.22, 1.0);

    // Choose pigment color modulated by local lighting and cuticular bloom
    let spCol = PAL.speckleDark;
    if (info.specFactor > 0.35 || (info.bloomFactor > 0.55 && random() < 0.5)) {
      spCol = PAL.speckleBloom; // Veiled by milky cuticular bloom
    } else if (info.keyDot > 0.45) {
      spCol = random() < 0.55 ? PAL.speckleMid : PAL.speckleDark;
    } else if (info.keyDot < 0.18) {
      spCol = PAL.eggAbyss;
    }

    drawForeshortenedSpeckle(wx, wy, baseRadius, foreshorten, radialAng, spCol);
  }

  // 2. Thousands of fine peppering pinpoint speckles
  for (let i = 0; i < 2400; i++) {
    let lx = random(-EGG_A * 0.97, EGG_A * 0.97);
    let u = lx / EGG_A;
    let halfW = EGG_B * sqrt(max(0, 1 - u * u)) * (1 - EGG_K * u);
    let ly = random(-halfW * 0.97, halfW * 0.97);

    let info = evaluateEgg3D(lx, ly);
    if (!info.inside || info.nz < 0.12) continue;

    let [wx, wy] = localToWorldEgg(lx, ly);
    let spCol = PAL.speckleDark;
    if (info.specFactor > 0.3) {
      spCol = PAL.speckleBloom;
    } else if (info.keyDot > 0.4) {
      spCol = random() < 0.6 ? PAL.speckleMid : PAL.speckleBloom;
    } else if (info.keyDot < 0.15) {
      spCol = PAL.eggAbyss;
    }

    brush.set("rotring", spCol, random(0.22, 0.48));
    let tang = atan2(info.nx, -info.ny);
    let d = random(0.4, 1.4);
    brush.line(wx, wy, wx + cos(tang) * d, wy + sin(tang) * d);
  }

  // 3. Raised chalky calcium concretions (tiny pale mineral bumps with micro-shadows)
  for (let i = 0; i < 42; i++) {
    let lx = random(-EGG_A * 0.85, EGG_A * 0.85);
    let ly = random(-EGG_B * 0.85, EGG_B * 0.85);
    let info = evaluateEgg3D(lx, ly);
    if (!info.inside || info.nz < 0.35 || info.keyDot < 0.15) continue;

    let [wx, wy] = localToWorldEgg(lx, ly);
    let r = random(0.7, 1.8);
    // Tiny shadow on bottom-right side of bump
    brush.set("rotring", PAL.eggShadow, 0.35);
    brush.line(wx + 0.7, wy + 0.8, wx + 0.7 + r * 0.6, wy + 0.8);
    // Raised chalky white/pinkish calcium granule
    brush.set("rotring", PAL.eggHighlight, 0.48);
    brush.line(wx, wy, wx + r * 0.5, wy - r * 0.3);
  }

  // ---- G. CRISP SILHOUETTE EDGE REFINEMENT ----
  // Subtle rim definition so the egg edge reads with photographic sharpness against the straw
  brush.set("2H", PAL.eggBloomLight, 0.26);
  for (let t = 165; t <= 315; t += 4) {
    let p1 = getEggVertexWorld(t, 0.996, 0.996);
    let p2 = getEggVertexWorld(t + 4, 0.996, 0.996);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.set("2B", PAL.eggAbyss, 0.36);
  for (let t = -35; t <= 145; t += 4) {
    let p1 = getEggVertexWorld(t, 1.0, 1.0);
    let p2 = getEggVertexWorld(t + 4, 1.0, 1.0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawEggContourShape(scX, scY, offX, offY) {
  brush.beginShape(0.42);
  for (let t = 0; t < 360; t += 15) {
    let [wx, wy] = getEggVertexWorld(t, scX, scY, offX, offY);
    brush.vertex(wx, wy);
  }
  brush.endShape(CLOSE);
}

function drawEggCrescentRim(startA, endA, innerSc, outerSc) {
  brush.beginShape(0.38);
  for (let t = startA; t <= endA; t += 12) {
    let [wx, wy] = getEggVertexWorld(t, outerSc, outerSc, 0, 0);
    brush.vertex(wx, wy);
  }
  for (let t = endA; t >= startA; t -= 12) {
    let [wx, wy] = getEggVertexWorld(t, innerSc, innerSc, -3, -3);
    brush.vertex(wx, wy);
  }
  brush.endShape(CLOSE);
}

function drawForeshortenedSpeckle(wx, wy, rad, foreshorten, radialAng, col) {
  let tangAng = radialAng + 90;
  let rx = rad * foreshorten;
  let ry = rad;

  let c = cos(radialAng);
  let s = sin(radialAng);

  // Build organic protoporphyrin spot from clustered micro-marks
  let subDots = floor(constrain(rad * 4.5, 5, 24));
  brush.set("rotring", col, random(0.32, 0.55));
  for (let i = 0; i < subDots; i++) {
    let a = random(360);
    let d = sqrt(random()) * 0.95;
    let dxLocal = cos(a) * rx * d;
    let dyLocal = sin(a) * ry * d;
    let px = wx + dxLocal * c - dyLocal * s;
    let py = wy + dxLocal * s + dyLocal * c;
    brush.line(px, py, px + cos(tangAng) * 0.9, py + sin(tangAng) * 0.9);
  }

  // Darker pigment ring at the edge of larger blotches
  if (rad > 2.6 && random() < 0.65) {
    brush.set("rotring", PAL.speckleDark, 0.28);
    for (let a = 0; a < 360; a += 45) {
      let dxLocal = cos(a) * rx * 0.85;
      let dyLocal = sin(a) * ry * 0.85;
      let px = wx + dxLocal * c - dyLocal * s;
      let py = wy + dxLocal * s + dyLocal * c;
      brush.line(px, py, px + 0.6, py + 0.6);
    }
  }
}

