// ============================================================================
// GEOMETRY & ORGANIC PATH HELPERS
// ============================================================================

function trayRadiusAt(theta, baseR = 542) {
  // Classic Zhostovo scalloped cushion-oval tray contour (8 subtle lobes + 4 corner swells)
  let c4 = cos(4 * theta);
  let c8 = cos(8 * theta);
  let s2 = sin(2 * theta);
  return baseR + 18 * c4 - 7 * c8 + 4 * s2;
}

function trayPoint(theta, rScale = 1.0, cx = 600, cy = 600) {
  let r = trayRadiusAt(theta) * rScale;
  // Slight vertical elongation for classic bouquet presentation
  return [cx + r * 0.965 * cos(theta), cy + r * 1.015 * sin(theta)];
}

function evalBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

function evalBezierTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx =
    3 * u * u * (p1[0] - p0[0]) +
    6 * u * t * (p2[0] - p1[0]) +
    3 * t * t * (p3[0] - p2[0]);
  let dy =
    3 * u * u * (p1[1] - p0[1]) +
    6 * u * t * (p2[1] - p1[1]) +
    3 * t * t * (p3[1] - p2[1]);
  let len = sqrt(dx * dx + dy * dy) || 1;
  return [dx / len, dy / len];
}

function drawFilledPoly(pts, curvature = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ============================================================================
// STEP 1: BLACK LACQUER TRAY GROUND & RIM BEVELS
// ============================================================================

function drawLacquerTrayGround() {
  background("#050406");
  brush.noField();

  // Outer tray lip shadow and metallic rim bevel
  let outerRim = [];
  let bevelRim = [];
  let innerWell = [];
  for (let a = 0; a < 360; a += 3) {
    outerRim.push(trayPoint(a, 1.035));
    bevelRim.push(trayPoint(a, 0.995));
    innerWell.push(trayPoint(a, 0.855));
  }

  // Deep lacquer body wash
  brush.noStroke();
  brush.wash("#0b090d", 240);
  drawFilledPoly(outerRim, 0.25);

  brush.wash("#060508", 250);
  drawFilledPoly(bevelRim, 0.25);

  // Subtle warm oil-varnish depth in the central well where the bouquet sits
  brush.noWash();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.4, 0.15);
  brush.fill("#170b0f", 55);
  brush.circle(590, 585, 360, 0.25);
  brush.fill("#140d07", 45);
  brush.circle(615, 620, 290, 0.25);
  brush.noFill();

  // Glossy black lacquer diagonal sheen on the tray bevel (top-left & bottom-right)
  for (let i = 0; i < 28; i++) {
    let a1 = -165 + i * 3.2;
    let a2 = a1 + 4;
    let p1 = trayPoint(a1, 1.012);
    let p2 = trayPoint(a2, 1.012);
    let w = sin(map(i, 0, 27, 0, 180));
    brush.set("glazeSoft", "#2b2530", 1.1 * w + 0.2);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let i = 0; i < 24; i++) {
    let a1 = 15 + i * 3.0;
    let a2 = a1 + 3.5;
    let p1 = trayPoint(a1, 0.865);
    let p2 = trayPoint(a2, 0.865);
    let w = sin(map(i, 0, 23, 0, 180));
    brush.set("glazeSoft", "#1f1a22", 0.9 * w + 0.2);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Fine lacquer surface polish lines (extremely subtle)
  brush.set("2H", "#141118", 0.35);
  for (let i = 0; i < 36; i++) {
    let y = random(120, 1080);
    let x1 = random(140, 500);
    let x2 = x1 + random(80, 260);
    if (dist(600, 600, (x1 + x2) * 0.5, y) < 460) {
      brush.line(x1, y, x2, y - random(-8, 8));
    }
  }
}

// ============================================================================
// STEP 2: ORNATE ZHOSTOVO GOLD SCROLL BORDER (UBORKA)
// ============================================================================

function drawGoldScrollBorder() {
  brush.noField();
  brush.noFill();
  brush.noWash();

  // 1. Double gold framing fillets around the tray rim
  let rings = [
    { scale: 0.992, col: "#7a581b", w: 0.85 },
    { scale: 0.986, col: "#d4a843", w: 0.65 },
    { scale: 0.872, col: "#85601f", w: 0.55 },
    { scale: 0.866, col: "#cfa23c", w: 0.4 }
  ];

  for (let r of rings) {
    let pts = [];
    for (let a = 0; a <= 360; a += 4) {
      let pt = trayPoint(a, r.scale);
      pts.push([pt[0], pt[1], 0.8 + 0.3 * sin(a * 2)]);
    }
    brush.set("goldGild", r.col, r.w);
    brush.spline(pts, 0.3);
  }

  // Bright gold specular glint on upper-left rim fillet
  let glintPts = [];
  for (let a = 195; a <= 265; a += 3) {
    let pt = trayPoint(a, 0.986);
    glintPts.push([pt[0], pt[1], sin(map(a, 195, 265, 10, 170))]);
  }
  brush.set("wetSpec", "#fff2ba", 0.55);
  brush.spline(glintPts, 0.3);

  // 2. Repeating 16-section symmetrical acanthus & rococo gold scroll frieze
  let numSections = 16;
  let stepA = 360 / numSections;

  for (let s = 0; s < numSections; s++) {
    let a0 = s * stepA;
    let aMid = a0 + stepA * 0.5;
    let a1 = a0 + stepA;
    let flip = s % 2 === 0 ? 1 : -1;

    // Main S-scroll spine weaving between inner (0.885) and outer (0.970) border radii
    let sPtsShadow = [];
    let sPtsGold = [];
    let sPtsHigh = [];
    for (let i = 0; i <= 14; i++) {
      let t = i / 14;
      let ang = lerp(a0 + 0.8, a1 - 0.8, t);
      let wave = sin(t * 180 * flip - 90 * flip);
      let rad = 0.928 + 0.033 * wave;
      let pt = trayPoint(ang, rad);
      let p = 0.35 + 0.85 * sin(t * 180);
      sPtsShadow.push([pt[0] + 1.2, pt[1] + 1.2, p]);
      sPtsGold.push([pt[0], pt[1], p]);
      if (i >= 3 && i <= 11) {
        sPtsHigh.push([pt[0] - 0.6, pt[1] - 0.6, p * 0.7]);
      }
    }

    // Antique bronze base shadow
    brush.set("goldGild", "#6b4c14", 0.72);
    brush.spline(sPtsShadow, 0.45);
    // Rich ducat gold scroll
    brush.set("goldGild", "#d9ab42", 0.62);
    brush.spline(sPtsGold, 0.45);
    // Pale gold highlight ridge
    brush.set("fineRoot", "#ffefad", 0.42);
    brush.spline(sPtsHigh, 0.45);

    // Spiral volute curling inward at the center of each scroll
    let volutePts = [];
    let vCenter = trayPoint(aMid, 0.928 - 0.014 * flip);
    let baseTangent = aMid + 90;
    for (let k = 0; k <= 12; k++) {
      let kt = k / 12;
      let vAng = baseTangent + flip * kt * 290;
      let vR = (1 - kt * 0.78) * 16;
      let vx = vCenter[0] + vR * cos(vAng);
      let vy = vCenter[1] + vR * sin(vAng);
      volutePts.push([vx, vy, (1 - kt * 0.6) * 0.9]);
    }
    brush.set("goldGild", "#8c651c", 0.52);
    brush.spline(volutePts, 0.5);
    brush.set("goldGild", "#e6bc53", 0.42);
    brush.spline(volutePts, 0.5);

    // Secondary counter-scroll tendril
    let counterPts = [];
    for (let k = 0; k <= 8; k++) {
      let kt = k / 8;
      let cAng = lerp(aMid, a1 - 1.5, kt);
      let cRad = 0.928 - flip * (0.01 + 0.024 * sin(kt * 160));
      let cpt = trayPoint(cAng, cRad);
      counterPts.push([cpt[0], cpt[1], (1 - kt * 0.7) * 0.75]);
    }
    brush.set("goldGild", "#c99934", 0.42);
    brush.spline(counterPts, 0.45);

    // Delicate Zhostovo comma-stroke gold leaflets along the scroll
    for (let lf = -1; lf <= 1; lf += 2) {
      let lAng = aMid + lf * 4.2;
      let pBase = trayPoint(lAng, 0.928 + 0.012 * lf * flip);
      let pTip = trayPoint(lAng + lf * 3.2, 0.928 + 0.036 * lf * flip);
      let pMid = [
        (pBase[0] + pTip[0]) * 0.5 - 4 * sin(lAng),
        (pBase[1] + pTip[1]) * 0.5 + 4 * cos(lAng)
      ];
      brush.set("goldGild", "#e0b348", 0.55);
      brush.spline(
        [
          [pBase[0], pBase[1], 1.1],
          [pMid[0], pMid[1], 0.75],
          [pTip[0], pTip[1], 0.1]
        ],
        0.4
      );
    }

    // Floral rosette / berry cluster at each junction between scroll modules
    let jPt = trayPoint(a0, 0.928);
    brush.set("goldGild", "#996f20", 0.6);
    brush.circle(jPt[0], jPt[1], 5.5, 0.15);
    brush.set("wetSpec", "#ffe89e", 0.45);
    brush.circle(jPt[0] - 1.2, jPt[1] - 1.2, 2.2, 0.1);

    // Tiny satellite gold berries
    for (let b = -1; b <= 1; b += 2) {
      let bPt = trayPoint(a0 + b * 1.4, 0.928 + b * 0.022);
      brush.set("goldGild", "#d9ab42", 0.45);
      brush.circle(bPt[0], bPt[1], 2.5, 0.1);
      brush.set("wetSpec", "#fff5c8", 0.35);
      brush.line(bPt[0] - 0.8, bPt[1] - 0.8, bPt[0] + 0.4, bPt[1] - 0.2);
    }

    // Inner lacy gold scallop ticks pointing toward the tray well
    let tickBase = trayPoint(aMid, 0.866);
    let tickTip = trayPoint(aMid, 0.844);
    brush.set("fineRoot", "#b8892b", 0.4);
    brush.line(tickBase[0], tickBase[1], tickTip[0], tickTip[1]);
    brush.set("wetSpec", "#ffeba6", 0.35);
    brush.circle(tickTip[0], tickTip[1], 1.6, 0.1);
  }
}

