// ============================================================================
// SHAPE BUILDERS FOR LEAVES, CARROTS & BEETS
// ============================================================================

function getBeetLeafPolygon(leaf, scaleW = 1.0) {
  let leftPts = [];
  let rightPts = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalBezier(leaf.base, leaf.ctrl1, leaf.ctrl2, leaf.tip, t);
    let tan = evalBezierTangent(leaf.base, leaf.ctrl1, leaf.ctrl2, leaf.tip, t);
    let nx = -tan[1];
    let ny = tan[0];

    // Broad cordate-ovate beet leaf profile with undulating crinkled margins
    let env = pow(sin(t * 180), 0.65) * (1 - 0.18 * t);
    if (t < 0.12) env = map(t, 0, 0.12, 0.08, env);
    let crinkleL = sin(t * 180 * 5.5) * leaf.lobeAmp * sin(t * 180);
    let crinkleR = cos(t * 180 * 5.0) * leaf.lobeAmp * sin(t * 180);
    let wL = (leaf.width * env + crinkleL) * scaleW;
    let wR = (leaf.width * env + crinkleR) * scaleW;

    leftPts.push([pt[0] + nx * wL, pt[1] + ny * wL]);
    rightPts.push([pt[0] - nx * wR, pt[1] - ny * wR]);
  }
  return leftPts.concat(rightPts.reverse());
}

function getCarrotRadiusAt(carrot, t) {
  // Swells quickly from crown (t=0) to shoulder (t=0.10), then tapers smoothly to tip (t=1)
  if (t < 0.08) {
    return carrot.maxR * map(sqrt(t / 0.08), 0, 1, 0.28, 0.96);
  }
  let u = (t - 0.08) / 0.92;
  let baseTaper = carrot.maxR * pow(1 - u, 0.82) * (1 + 0.08 * sin(u * 180));
  // Subtle organic bumps from annular growth rings
  let ripple = 1 + 0.028 * sin(t * 180 * 7);
  return max(2.2, baseTaper * ripple);
}

function getCarrotPolygon(carrot, widthMult = 1.0, offsetSide = 0, tStart = 0, tEnd = 1) {
  let leftPts = [];
  let rightPts = [];
  let steps = 30;
  for (let i = 0; i <= steps; i++) {
    let t = lerp(tStart, tEnd, i / steps);
    let pt = evalBezier(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
    let tan = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
    let nx = -tan[1];
    let ny = tan[0];
    let r = getCarrotRadiusAt(carrot, t) * widthMult;
    let cx = pt[0] + nx * offsetSide * carrot.maxR;
    let cy = pt[1] + ny * offsetSide * carrot.maxR;
    leftPts.push([cx + nx * r, cy + ny * r]);
    rightPts.push([cx - nx * r, cy - ny * r]);
  }
  return leftPts.concat(rightPts.reverse());
}

function getBeetPointOnContour(beet, angleDeg, rScale = 1.0, shiftX = 0, shiftY = 0) {
  // Heart-shaped / oblate-bulbous beetroot profile that pinches into the taproot at angle=90 (bottom)
  let a = angleDeg;
  let radX = beet.rx * rScale;
  let radY = beet.ry * rScale;

  // Flatten slightly at top crown (angle ~ -90) and taper to a point at bottom (angle ~ +90)
  let s = sin(a);
  let c = cos(a);
  let shoulderSwell = s < 0 ? 1.08 + 0.08 * sin(-a * 2) : 1.0 - 0.26 * pow(s, 1.6);
  let bottomPinch = s > 0.25 ? 19 * pow((s - 0.25) / 0.75, 2.4) : 0;
  let organicBump = 1 + 0.025 * sin(a * 3 + beet.cx) + 0.018 * cos(a * 5);

  let lx = c * radX * shoulderSwell * organicBump;
  let ly = s * radY * organicBump + bottomPinch * rScale;

  // Rotate by beet.rot around (beet.cx, beet.cy)
  let ca = cos(beet.rot);
  let sa = sin(beet.rot);
  return [
    beet.cx + shiftX + lx * ca - ly * sa,
    beet.cy + shiftY + lx * sa + ly * ca
  ];
}

function getBeetPolygon(beet, rScale = 1.0, shiftX = 0, shiftY = 0) {
  let pts = [];
  for (let a = 0; a < 360; a += 8) {
    pts.push(getBeetPointOnContour(beet, a, rScale, shiftX, shiftY));
  }
  return pts;
}

// ============================================================================
// STEP 3: DIM UNDERPAINTING (ZAMALYOVOK) ON THE BLACK GROUND
// ============================================================================

function drawUnderpainting() {
  brush.noField();
  brush.noStroke();

  // 1. Leaf underpainting (muted grey-olive and dusky plum-umber)
  for (let leaf of BEET_LEAVES) {
    let poly = getBeetLeafPolygon(leaf, 0.96);
    brush.wash("#263022", 165);
    drawFilledPoly(poly, 0.35);

    let innerPoly = getBeetLeafPolygon(leaf, 0.65);
    brush.wash("#3d2932", 110);
    drawFilledPoly(innerPoly, 0.35);
  }
  brush.noWash();

  // 2. Feathery carrot frond underpainting clouds (dim sage & olive strokes)
  drawCarrotFrondsLayer(true);

  // 3. Carrot underpainting (opaque muted terracotta-ochre & warm umber cylinders)
  for (let c of CARROTS) {
    brush.noStroke();
    brush.wash("#592b18", 210);
    drawFilledPoly(getCarrotPolygon(c, 0.98, 0, 0, 1), 0.3);

    // Lit half underpainting in warm buff-ochre so orange glazes glow like fire
    brush.wash("#9e6238", 190);
    drawFilledPoly(getCarrotPolygon(c, 0.62, -0.22 * c.lightSide, 0.02, 0.95), 0.3);

    brush.wash("#c99364", 145);
    drawFilledPoly(getCarrotPolygon(c, 0.32, -0.35 * c.lightSide, 0.05, 0.88), 0.3);
  }

  // 4. Beetroot underpainting (dusky carmine-taupe and pale rose-mauve)
  for (let b of BEETROOTS) {
    brush.noStroke();
    brush.wash("#381523", 225);
    drawFilledPoly(getBeetPolygon(b, 0.99, 0, 0), 0.35);

    brush.wash("#6e3048", 195);
    drawFilledPoly(getBeetPolygon(b, 0.78, -10, -10), 0.35);

    // Pale mauve-pink underpainting on upper-left belly for luminous crimson lake glaze
    brush.wash("#a8647d", 165);
    drawFilledPoly(getBeetPolygon(b, 0.52, -20, -18), 0.35);
  }
  brush.noWash();
}

// ============================================================================
// STEP 4: WATERCOLOUR GLAZES & DETAILS — BEET LEAVES & CARROT FRONDS
// ============================================================================

function drawCarrotFrondsPlume(ox, oy, baseAngle, len, spread, isUnderpainting) {
  let spinePts = [];
  let steps = 10;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = baseAngle + sin(t * 180) * spread * 0.35;
    let r = t * len;
    let px = ox + r * cos(a);
    let py = oy + r * sin(a);
    spinePts.push([px, py, (1 - t * 0.7) * 0.9]);
  }

  if (isUnderpainting) {
    brush.set("2B", "#2b3824", 0.85);
    brush.spline(spinePts, 0.4);
  } else {
    brush.set("fineRoot", "#1f4d1e", 0.7);
    brush.spline(spinePts, 0.4);
  }

  // Pinnate lateral branches and feathery leaflets
  for (let i = 2; i <= steps; i++) {
    let t = i / steps;
    let pt = spinePts[i];
    let subLen = (1 - t * 0.62) * len * 0.32;

    for (let side = -1; side <= 1; side += 2) {
      let branchA = baseAngle + side * (36 + t * 14) + sin(t * 180) * 10;
      let bx = pt[0] + subLen * cos(branchA);
      let by = pt[1] + subLen * sin(branchA);

      if (isUnderpainting) {
        brush.set("cpencil", "#354729", 0.65);
        brush.line(pt[0], pt[1], bx, by);
      } else {
        // Rich leaf green & chartreuse feathery pinnules
        brush.set("fineRoot", "#246624", 0.52);
        brush.line(pt[0], pt[1], bx, by);

        let numPinnules = 4;
        for (let k = 1; k <= numPinnules; k++) {
          let kt = k / numPinnules;
          let px = lerp(pt[0], bx, kt);
          let py = lerp(pt[1], by, kt);
          let pLen = (1 - kt * 0.45) * 15;

          for (let ps = -1; ps <= 1; ps += 2) {
            let pA = branchA + ps * 38;
            let tx = px + pLen * cos(pA);
            let ty = py + pLen * sin(pA);

            let col =
              k === numPinnules
                ? "#8cd938"
                : ps < 0
                ? "#3ca132"
                : "#1a521b";
            brush.set("fineRoot", col, 0.42);
            brush.line(px, py, tx, ty);
          }
        }
      }
    }
  }
}

function drawCarrotFrondsLayer(isUnderpainting = false) {
  const plumes = [
    { ox: 510, oy: 455, a: -138, len: 265, sp: -28 },
    { ox: 485, oy: 485, a: -162, len: 245, sp: -22 },
    { ox: 555, oy: 430, a: -112, len: 280, sp: -18 },
