    { ox: 645, oy: 445, a: -42, len: 270, sp: 28 },
    { ox: 675, oy: 480, a: -16, len: 255, sp: 25 },
    { ox: 695, oy: 535, a: 12, len: 225, sp: 20 },
    { ox: 455, oy: 545, a: -178, len: 215, sp: -18 }
  ];

  for (let p of plumes) {
    drawCarrotFrondsPlume(p.ox, p.oy, p.a, p.len, p.sp, isUnderpainting);
