}

function drawBeetLeavesGlazesAndVeins() {
  brush.noField();

  // Batch 1: Deep leaf green & viridian watercolour glazes
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.55, 0.35);

  for (let leaf of BEET_LEAVES) {
    let poly = getBeetLeafPolygon(leaf, 1.0);
    brush.fill("#10451d", 115);
    drawFilledPoly(poly, 0.35);

    let litPoly = getBeetLeafPolygon(leaf, 0.82);
    brush.fill(leaf.tone === "emeraldCrimson" ? "#26782a" : "#1d5e22", 95);
    drawFilledPoly(litPoly, 0.35);
  }

  // Batch 2: Crimson Lake & Burgundy bleed along leaf centers and margins
  brush.fillBleed(0.32, "in");
  for (let leaf of BEET_LEAVES) {
    let centerPoly = getBeetLeafPolygon(leaf, 0.42);
    brush.fill("#78092b", 105);
    drawFilledPoly(centerPoly, 0.35);
  }
  brush.noFill();

  // Detailed crinkled leaf modeling, ruby midribs, lateral venation, and wet sheen
  for (let leaf of BEET_LEAVES) {
    let steps = 20;
    let midribShadow = [];
    let midribCore = [];
    let midribHigh = [];

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let pt = evalBezier(leaf.base, leaf.ctrl1, leaf.ctrl2, leaf.tip, t);
      let tan = evalBezierTangent(leaf.base, leaf.ctrl1, leaf.ctrl2, leaf.tip, t);
      let nx = -tan[1];
      let ny = tan[0];
      let w = (1 - t * 0.82) * 1.15;

      midribShadow.push([pt[0] - nx * 2.5, pt[1] - ny * 2.5, w]);
      midribCore.push([pt[0], pt[1], w]);
      if (t < 0.85) {
        midribHigh.push([pt[0] + nx * 1.5, pt[1] + ny * 1.5, w * 0.65]);
      }

      // Crinkled inter-vein cushions & ruby lateral veins
      if (i >= 3 && i <= 17 && i % 2 === 1) {
        let env = pow(sin(t * 180), 0.65) * (1 - 0.18 * t);
        let maxW = leaf.width * env;

        for (let side = -1; side <= 1; side += 2) {
          let vAng = atan2(tan[1], tan[0]) + side * 42;
          let vLen = maxW * 0.92;
          let vx1 = pt[0] + cos(vAng - side * 8) * vLen * 0.48;
          let vy1 = pt[1] + sin(vAng - side * 8) * vLen * 0.48;
          let vx2 = pt[0] + cos(vAng + side * 6) * vLen;
          let vy2 = pt[1] + sin(vAng + side * 6) * vLen;

          // Lush emerald/chartreuse pillow highlight between veins
          brush.set("glazeSoft", side < 0 ? "#48a832" : "#286e22", 0.55);
          brush.line(pt[0] + tan[0] * 10, pt[1] + tan[1] * 10, vx1, vy1);

          // Deep forest-burgundy crease shadow under vein
          brush.set("cpencil", "#0d2412", 0.55);
          brush.line(pt[0], pt[1], vx2, vy2);

          // Glowing Crimson Lake / Magenta lateral vein
          brush.set("fineRoot", "#b80d40", 0.55 * (1 - t * 0.4));
          brush.spline(
            [
              [pt[0], pt[1], 0.9],
              [vx1, vy1, 0.55],
              [vx2, vy2, 0.1]
            ],
            0.35
          );

          // Fine capillary vein forks near leaf margin
          let forkA = vAng + side * 24;
          brush.set("fineRoot", "#e01b56", 0.32);
          brush.line(vx1, vy1, vx1 + cos(forkA) * vLen * 0.35, vy1 + sin(forkA) * vLen * 0.35);
        }
      }
    }

    // Draw main ruby stalk & midrib
    brush.set("cpencil", "#380312", 1.1);
    brush.spline(midribShadow, 0.35);
    brush.set("fineRoot", "#c90e46", 0.95);
    brush.spline(midribCore, 0.35);
    brush.set("wetSpec", "#ff99b8", 0.45);
    brush.spline(midribHigh, 0.35);
  }

  // Paint the vibrant upper layer of feathery carrot fronds
  drawCarrotFrondsLayer(false);
}

