      brush.set("fineRoot", "#9be645", 0.48);
      brush.spline([[base[0] - 1.5, base[1] - 1.5, 0.8], [p1[0] - 1.5, p1[1] - 1.5, 0.6], [p2[0], p2[1], 0.3]], 0.35);
