}

function drawSingleCarrotDetailed(carrot) {
  brush.noField();

  // 1. Rich Transparent Watercolour Glazes (Carrot Orange, Cadmium, Burnt Sienna)
  brush.noStroke();
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.5, 0.3);

  // Full body orange glaze
  let mainCol = carrot.hueShift === "vermilionOrange" ? "#d9380b" : "#e64f0f";
  brush.fill(mainCol, 120);
  drawFilledPoly(getCarrotPolygon(carrot, 1.0, 0, 0, 1), 0.3);

  // Shadow side glaze (deep burnt sienna & crimson-umber)
  brush.fill("#5e1605", 125);
  drawFilledPoly(getCarrotPolygon(carrot, 0.48, 0.46, 0.02, 0.98), 0.3);

  // Luminous Cadmium Orange-Amber lit glaze
  brush.fill("#ff7b00", 110);
  drawFilledPoly(getCarrotPolygon(carrot, 0.58, -0.24, 0.02, 0.95), 0.3);

  // Fiery Golden-Orange core glow
  brush.fill("#ffa600", 90);
  drawFilledPoly(getCarrotPolygon(carrot, 0.32, -0.34, 0.05, 0.88), 0.3);
  brush.noFill();

  // 2. Longitudinal cylindrical shading & reflected light along shadow rim
  let steps = 34;
  for (let s = -0.88; s <= 0.88; s += 0.16) {
    let stripePts = [];
    for (let i = 1; i < steps; i++) {
      let t = i / steps;
      let pt = evalBezier(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
      let tan = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
      let nx = -tan[1];
      let ny = tan[0];
      let r = getCarrotRadiusAt(carrot, t);
      let px = pt[0] + nx * r * s;
      let py = pt[1] + ny * r * s;
      stripePts.push([px, py, (1 - t * 0.65) * 0.8]);
    }
    let col;
    let br = "glazeSoft";
    let w = 0.65;
    if (s < -0.55) {
      col = "#b83809"; // turning away on top-left edge
    } else if (s < -0.15) {
      col = "#ff9d1c"; // lit ridge
    } else if (s < 0.35) {
      col = "#d43d08"; // rich core orange
    } else if (s < 0.72) {
      col = "#4a0f03"; // deep core shadow
      br = "cpencil";
      w = 0.8;
    } else {
      col = "#9c3b16"; // warm reflected light on bottom-right edge
      br = "cpencil";
      w = 0.6;
    }
    brush.set(br, col, w);
    brush.spline(stripePts, 0.35);
  }

  // 3. Greenish-ochre recessed crown collar where stems attach
  let c0 = carrot.p0;
  let tan0 = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, 0.02);
  let nx0 = -tan0[1];
  let ny0 = tan0[0];
  let r0 = carrot.maxR * 0.55;
  brush.set("cpencil", "#485e1d", 0.9);
  brush.spline(
    [
      [c0[0] + nx0 * r0, c0[1] + ny0 * r0, 0.7],
      [c0[0] + tan0[0] * 10, c0[1] + tan0[1] * 10, 1.1],
      [c0[0] - nx0 * r0, c0[1] - ny0 * r0, 0.7]
    ],
    0.4
  );

  // 4. Hyperreal Transverse Lenticels (horizontal root scars & dimples)
  for (let i = 3; i < steps - 2; i++) {
    let t = i / steps;
    if (random() < 0.78) {
      let pt = evalBezier(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
      let tan = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
      let nx = -tan[1];
      let ny = tan[0];
      let r = getCarrotRadiusAt(carrot, t);

      let span1 = random(-0.75, 0.15);
      let span2 = span1 + random(0.28, 0.68);
      span2 = min(0.85, span2);

      let pStart = [
        pt[0] + nx * r * span1 - tan[0] * 2,
        pt[1] + ny * r * span1 - tan[1] * 2,
        0.3
      ];
      let pMid = [
        pt[0] + nx * r * ((span1 + span2) * 0.5) + tan[0] * 3.5,
        pt[1] + ny * r * ((span1 + span2) * 0.5) + tan[1] * 3.5,
        0.95
      ];
      let pEnd = [
        pt[0] + nx * r * span2 - tan[0] * 2,
        pt[1] + ny * r * span2 - tan[1] * 2,
        0.3
      ];

      // Dark burnt-umber/carmine indentation crease
      brush.set("fineRoot", "#521405", 0.42 * (1 - t * 0.45));
      brush.spline([pStart, pMid, pEnd], 0.35);

      // Luminous wet highlight on the lower rim of the scar if on the lit side
      if (span1 < 0.1) {
        let hStart = [pStart[0] + tan[0] * 2.2, pStart[1] + tan[1] * 2.2, 0.25];
        let hMid = [pMid[0] + tan[0] * 2.2, pMid[1] + tan[1] * 2.2, 0.85];
        let hEnd = [pEnd[0] + tan[0] * 2.2, pEnd[1] + tan[1] * 2.2, 0.25];
        brush.set("wetSpec", "#ffc482", 0.36 * (1 - t * 0.45));
        brush.spline([hStart, hMid, hEnd], 0.35);
      }
    }
  }
}

function drawSingleBeetrootDetailed(beet) {
  brush.noField();

  // 1. Rich Transparent Watercolour Glazes (Crimson Lake, Alizarin, Deep Burgundy)
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.35);

  // Full bulb Crimson Lake glaze
  brush.fill("#660422", 135);
  drawFilledPoly(getBeetPolygon(beet, 1.0, 0, 0), 0.35);

  // Deep Plum-Burgundy lower-right shadow glaze
  brush.fill("#26020e", 145);
  drawFilledPoly(getBeetPolygon(beet, 0.78, 16, 16), 0.35);

  // Glowing Alizarin / Ruby Magenta glaze on upper-left lit hemisphere
  brush.fill("#b3093f", 120);
  drawFilledPoly(getBeetPolygon(beet, 0.76, -12, -12), 0.35);

  // Saturated Magenta-Rose subsurface belly glow
  brush.fill("#eb175d", 95);
  drawFilledPoly(getBeetPolygon(beet, 0.48, -22, -20), 0.35);

  // Hot pink-crimson heart highlight zone
  brush.fill("#ff4785", 75);
  drawFilledPoly(getBeetPolygon(beet, 0.26, -30, -26), 0.35);
  brush.noFill();

  // 2. Spherical Cross-Contour Modeling & Cool Violet-Mauve Reflected Light
  for (let lat = -65; lat <= 75; lat += 14) {
    let arcPts = [];
    for (let lon = -80; lon <= 80; lon += 16) {
      let rScale = cos(lat * 0.75) * 0.94;
      let pt = getBeetPointOnContour(
        beet,
        lon + (lat > 0 ? 45 : -35),
        rScale,
        lat * 0.15,
        lat * 0.15
      );
      arcPts.push([pt[0], pt[1], sin(map(lon, -80, 80, 15, 165)) * 0.85]);
    }
    let col = lat < -15 ? "#f02468" : lat < 25 ? "#8a0630" : "#380215";
    brush.set("glazeSoft", col, 0.65);
    brush.spline(arcPts, 0.4);
  }

  // Cool violet-mauve reflected light along the lower-right turn of the wet beet skin
  let reflPts = [];
  for (let a = 15; a <= 82; a += 7) {
    let pt = getBeetPointOnContour(beet, a, 0.93, 0, 0);
    reflPts.push([pt[0], pt[1], sin(map(a, 15, 82, 15, 165)) * 0.9]);
  }
  brush.set("glazeSoft", "#8a497d", 0.75);
  brush.spline(reflPts, 0.4);
  brush.set("cpencil", "#ad689e", 0.55);
  brush.spline(reflPts, 0.4);

  // 3. Corky Concentric Collar Rings around the upper crown of the beetroot
  for (let ring = 0; ring < 7; ring++) {
    let rFrac = 0.28 + ring * 0.085;
    let ringPts = [];
    let aStart = -152 + random(-8, 8);
    let aEnd = -28 + random(-8, 8);
    for (let a = aStart; a <= aEnd; a += 10) {
      let pt = getBeetPointOnContour(beet, a, rFrac, 0, -beet.ry * 0.22);
      ringPts.push([
        pt[0] + random(-1.5, 1.5),
        pt[1] + random(-1.5, 1.5),
        sin(map(a, aStart, aEnd, 15, 165)) * 0.85
      ]);
    }
    // Corky umber-ochre and dark plum collar ridges
    brush.set("cpencil", ring % 2 === 0 ? "#421624" : "#6e4e3e", 0.62);
    brush.spline(ringPts, 0.35);
    if (ring % 2 === 1) {
      brush.set("fineRoot", "#a6856e", 0.38);
      brush.spline(ringPts, 0.35);
    }
  }
}

// ============================================================================
// STEP 7: HYPERREAL TAPROOTS, CAPILLARY ROOTLETS & CLINGING SOIL
// ============================================================================

function drawRootletBranch(x, y, angle, length, weight, depth, palette) {
  if (depth <= 0 || length < 5) return;

  let pts = [];
  let steps = 7;
  let curX = x;
  let curY = y;
  let curA = angle;
  let stepLen = length / steps;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = (1 - t * 0.88) * weight;
    pts.push([curX, curY, p]);
    // Organic rootlet kinks and gravity pull toward +90 deg
    let grav = sin(90 - curA) * 5.5;
    curA += random(-16, 16) + grav * 0.25;
    curX += stepLen * cos(curA);
    curY += stepLen * sin(curA);

    // Spawn secondary/tertiary capillary root hairs
    if (i >= 2 && i <= steps - 1 && random() < 0.55) {
      let side = random() < 0.5 ? -1 : 1;
      let subA = curA + side * random(24, 56);
      let subLen = length * (1 - t * 0.45) * random(0.42, 0.72);
      drawRootletBranch(curX, curY, subA, subLen, weight * 0.62, depth - 1, palette);
    }
  }

  // Shadow pass for rootlet depth
  brush.set("fineRoot", palette.dark, weight * 0.65);
  brush.spline(pts, 0.45);

  // Translucent core pass (crimson-ochre or amber-sienna)
  let colCore = depth === 3 ? palette.mid : depth === 2 ? palette.lit : palette.hair;
  brush.set("fineRoot", colCore, weight * 0.48);
  brush.spline(pts, 0.45);

  // Glistening wet highlight on primary rootlets against the black lacquer
  if (depth >= 2 && random() < 0.65) {
    let specSub = pts.slice(1, 5).map((pt) => [pt[0] - 0.8, pt[1] - 0.8, pt[2] * 0.55]);
    if (specSub.length >= 3) {
      brush.set("wetSpec", palette.spec, weight * 0.28);
      brush.spline(specSub, 0.4);
    }
  }
}

function drawCarrotTaprootAndRootlets(carrot) {
  let tip = carrot.p3;
  let end = carrot.tailEnd;
  let tan = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, 1.0);
  let mid1 = [
    lerp(tip[0], end[0], 0.35) + tan[0] * 18 + random(-12, 12),
    lerp(tip[1], end[1], 0.35) + tan[1] * 18 + random(-8, 12)
  ];
  let mid2 = [
    lerp(tip[0], end[0], 0.72) + random(-16, 16),
    lerp(tip[1], end[1], 0.72) + random(-10, 14)
  ];

  let tailShadow = [];
  let tailCore = [];
  let tailHigh = [];
  for (let i = 0; i <= 14; i++) {
    let t = i / 14;
    let p = evalBezier(tip, mid1, mid2, end, t);
    let w = (1 - t * 0.88) * 1.15;
    tailShadow.push([p[0] + 1.8, p[1] + 1.8, w]);
    tailCore.push([p[0], p[1], w * 0.85]);
    if (t < 0.75) tailHigh.push([p[0] - 1.2, p[1] - 1.2, w * 0.5]);
  }

  brush.set("cpencil", "#4a1506", 0.95);
  brush.spline(tailShadow, 0.45);
  brush.set("fineRoot", "#d45618", 0.78);
  brush.spline(tailCore, 0.45);
  brush.set("wetSpec", "#ffbe78", 0.42);
  brush.spline(tailHigh, 0.45);

  const carrotRootPalette = {
    dark: "#3b1709",
    mid: "#9e4618",
    lit: "#d67c3b",
    hair: "#e8a86b",
    spec: "#ffe8cc"
  };

  // Fine lateral rootlets sprouting from the carrot body lenticels
  for (let i = 0; i < 16; i++) {
    let t = random(0.18, 0.98);
    let pt = evalBezier(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
    let cTan = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
    let nx = -cTan[1];
    let ny = cTan[0];
    let r = getCarrotRadiusAt(carrot, t);
    let side = random() < 0.5 ? -1 : 1;
    let edgePlacement = side * random(0.55, 1.0);
    let rx = pt[0] + nx * r * edgePlacement;
    let ry = pt[1] + ny * r * edgePlacement;
    let outA = atan2(ny * side, nx * side) + random(-25, 35);
    let rLen = random(28, 72) * (0.6 + 0.5 * t);
    drawRootletBranch(rx, ry, outA, rLen, 0.85, 2, carrotRootPalette);
  }

  // Rootlets along the whip-like taproot
  for (let i = 2; i <= 12; i += 2) {
    let pt = tailCore[i];
    let side = i % 4 === 0 ? -1 : 1;
    let outA = atan2(end[1] - tip[1], end[0] - tip[0]) + side * random(28, 58);
    drawRootletBranch(pt[0], pt[1], outA, random(24, 58), 0.75, 2, carrotRootPalette);
  }
}

function drawBeetTaprootAndRootlets(beet) {
  let tPts = beet.tailPts;
  let shadowSpline = [];
  let darkRedSpline = [];
  let litRedSpline = [];
  let specSpline = [];

  for (let i = 0; i < tPts.length; i++) {
    let t = i / (tPts.length - 1);
    let w = pow(1 - t * 0.85, 1.15) * 2.2;
    shadowSpline.push([tPts[i][0] + 3.2 * (1 - t), tPts[i][1] + 2, w]);
    darkRedSpline.push([tPts[i][0], tPts[i][1], w * 0.9]);
    litRedSpline.push([tPts[i][0] - 2.0 * (1 - t), tPts[i][1], w * 0.65]);
    if (i < tPts.length - 1) {
      specSpline.push([tPts[i][0] - 2.8 * (1 - t), tPts[i][1] - 1, w * 0.38]);
    }
  }

  // Thick gnarled taproot base tapering into a fine whip
  brush.set("2B", "#260410", 1.55);
  brush.spline(shadowSpline, 0.45);
  brush.set("cpencil", "#700b2a", 1.3);
  brush.spline(darkRedSpline, 0.45);
  brush.set("fineRoot", "#ba1c4b", 0.9);
  brush.spline(litRedSpline, 0.45);
  brush.set("wetSpec", "#ff9ebb", 0.48);
  brush.spline(specSpline, 0.45);

  const beetRootPalette = {
    dark: "#2b0914",
    mid: "#781834",
    lit: "#b5435e",
    hair: "#d98b7c",
    spec: "#ffdbe3"
  };

  // Dense, tangled beard of hyperreal rootlets on the lower hemisphere of the beetroot
  for (let i = 0; i < 22; i++) {
    let a = random(28, 152);
    let rFrac = random(0.82, 1.0);
    let pt = getBeetPointOnContour(beet, a, rFrac, 0, 0);
    let outA = a + beet.rot + random(-25, 25);
    let len = random(38, 95);
    drawRootletBranch(pt[0], pt[1], outA, len, 0.95, 3, beetRootPalette);
  }

  // Branching rootlets all along the descending taproot
  for (let i = 0; i < tPts.length - 1; i++) {
    let pA = tPts[i];
    let pB = tPts[i + 1];
    for (let s = 0; s < 4; s++) {
      let st = s / 4;
      let rx = lerp(pA[0], pB[0], st);
      let ry = lerp(pA[1], pB[1], st);
      let side = random() < 0.5 ? -1 : 1;
      let outA = 90 + side * random(22, 68);
      let len = random(30, 82) * (1 - (i + st) / (tPts.length + 1));
      drawRootletBranch(rx, ry, outA, len, 0.85, 2, beetRootPalette);
    }
  }
}

function drawSoilClump(cx, cy, radius, density = 1.0) {
  // 1. Damp dark humus smudge base
  let pts = [];
  for (let a = 0; a < 360; a += 36) {
    let r = radius * random(0.55, 1.25);
    pts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  brush.noStroke();
  brush.wash("#140d09", 185);
  drawFilledPoly(pts, 0.35);
  brush.noWash();

  // 2. Granular soil crumbs, peat, clay ochre, and wet mineral glints
  let count = floor(radius * density * 2.2);
  const soilColors = [
    "#120b07",
    "#1f140d",
    "#2e1e13",
    "#422b1b",
    "#5c3d26",
    "#7d5638",
    "#a87e58"
  ];

  for (let i = 0; i < count; i++) {
    let ang = random(360);
    let distR = pow(random(), 0.65) * radius * 1.35;
    let sx = cx + distR * cos(ang);
    let sy = cy + distR * sin(ang);
    let col = soilColors[floor(pow(random(), 1.5) * soilColors.length)];
    let crSize = random(1.2, 4.2);

    brush.set(random() < 0.5 ? "charcoal" : "2B", col, random(0.45, 0.95));
    brush.line(sx, sy, sx + random(-crSize, crSize), sy + random(-crSize, crSize));

    // Tiny pale quartz/mica or wet mud pinpoint glint
    if (random() < 0.14) {
      brush.set("wetSpec", "#e8d5be", 0.32);
      brush.line(sx, sy, sx + 0.8, sy + 0.4);
    }
  }
}

