function drawWetCarrotHighlights(carrot) {
  let steps = 32;
  let haloPts = [];

  for (let i = 2; i < steps - 2; i++) {
    let t = i / steps;
    let pt = evalBezier(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
    let tan = evalBezierTangent(carrot.p0, carrot.p1, carrot.p2, carrot.p3, t);
    let nx = -tan[1];
    let ny = tan[0];
    let r = getCarrotRadiusAt(carrot, t);

    // Specular ridge sits along -0.36 * r on the upper-left lit cylinder turn
    let hx = pt[0] - nx * r * 0.36;
    let hy = pt[1] - ny * r * 0.36;
    haloPts.push([hx, hy, sin(t * 180) * (1 - t * 0.45)]);
  }

  // Warm golden-peach specular halo
  brush.set("glazeSoft", "#ffcf8c", 0.52);
  brush.spline(haloPts, 0.35);

  // Staccato razor-sharp white wet highlights broken by the carrot's annular rings
  for (let i = 1; i < haloPts.length - 2; i += 2) {
    if (random() < 0.82) {
      let pA = haloPts[i];
      let pB = haloPts[i + 1];
      let w = pA[2] * 0.62;
      brush.set("wetSpec", "#fff5de", w);
      brush.line(pA[0], pA[1], pB[0], pB[1]);

      // Pinpoint pure white wet glint at the crest of each ridge
      brush.set("wetSpec", "#ffffff", w * 0.78);
      brush.line(
        pA[0] - 0.5,
        pA[1] - 0.5,
        lerp(pA[0], pB[0], 0.55),
        lerp(pA[1], pB[1], 0.55)
      );
    }
  }
}

function drawWetBeetrootHighlights(beet) {
  // Primary curved wet specular window on upper-left swell of beetroot
  let specArc1 = [];
  let specArc2 = [];
  for (let a = -158; a <= -92; a += 6) {
    let p1 = getBeetPointOnContour(beet, a, 0.64, -8, -8);
    let p2 = getBeetPointOnContour(beet, a + 4, 0.50, -12, -10);
    let w = sin(map(a, -158, -92, 10, 170));
    specArc1.push([p1[0], p1[1], w]);
    specArc2.push([p2[0], p2[1], w * 0.85]);
  }

  // Soft rose-pink wet glow halo
  brush.set("glazeSoft", "#ff8cb3", 0.65);
  brush.spline(specArc1, 0.4);
  brush.set("glazeSoft", "#ffb8d0", 0.5);
  brush.spline(specArc2, 0.4);

  // Broken, dimpled razor-sharp pure white wet skin reflections
  for (let i = 1; i < specArc1.length - 2; i++) {
    if (i % 2 === 1) {
      let pA = specArc1[i];
      let pB = specArc1[i + 1];
      brush.set("wetSpec", "#fff0f6", 0.68 * pA[2]);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
      brush.set("wetSpec", "#ffffff", 0.52 * pA[2]);
      brush.line(pA[0] - 0.8, pA[1] - 0.8, (pA[0] + pB[0]) * 0.5, (pA[1] + pB[1]) * 0.5);
    }
  }

  for (let i = 2; i < specArc2.length - 2; i += 2) {
    let pA = specArc2[i];
    let pB = specArc2[i + 1];
    brush.set("wetSpec", "#ffffff", 0.6 * pA[2]);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Tiny wet skin pore sparkles around the highlight zone
  for (let k = 0; k < 14; k++) {
    let a = random(-165, -80);
    let r = random(0.38, 0.76);
    let pt = getBeetPointOnContour(beet, a, r, -10, -10);
    brush.set("wetSpec", "#ffffff", random(0.28, 0.48));
    brush.line(pt[0], pt[1], pt[0] + random(1.5, 3.5), pt[1] - random(1.0, 2.5));
  }
}

function drawWaterDroplet(x, y, r, surfaceHue) {
  // 1. Cast shadow below droplet
  brush.set("cpencil", "#120408", 0.45);
  brush.arc(x + r * 0.2, y + r * 0.25, r * 0.95, 15, 165);

  // 2. Dark upper interior refraction
  let darkCol =
    surfaceHue === "beet"
      ? "#4a0319"
      : surfaceHue === "carrot"
      ? "#6e1c05"
      : "#0c3012";
  brush.noStroke();
  brush.wash(darkCol, 175);
  brush.circle(x, y, r, 0.1);
  brush.noWash();

  // 3. Glowing lower crescent caustics (subsurface color focused through droplet)
  let glowCol =
    surfaceHue === "beet"
      ? "#ff2e74"
      : surfaceHue === "carrot"
      ? "#ff9900"
      : "#6ce638";
  brush.set("fineRoot", glowCol, 0.52);
  brush.arc(x + r * 0.1, y + r * 0.1, r * 0.72, 20, 155);

  // 4. Crisp pure white pinpoint specular highlight on upper-left of droplet
  brush.set("wetSpec", "#ffffff", 0.55);
  brush.circle(x - r * 0.32, y - r * 0.32, max(1.1, r * 0.28), 0.05);
}

