// ============================================================================
// MAIN RENDER SEQUENCE (THE TRAY-PAINTER'S SEQUENCE)
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep black lacquer tray ground & subtle rim bevels
  drawLacquerTrayGround();

  // 2. Thin, ornate gold scroll border around the tray's rim
  drawGoldScrollBorder();

  // 3. Dim underpainting (Zamalyovok) establishing volume on the black ground
  drawUnderpainting();

  // 4. Watercolour glazes & venation for beet greens, carrot fronds, and stems
  drawBeetLeavesGlazesAndVeins();
  drawCrownStemsAndGather();

  // 5. Layered Zhostovo sequence for Carrots & Beetroots (sorted by depth)
  // Upper-right carrot & mid-left carrot first
  drawSingleCarrotDetailed(CARROTS[0]);
