// ============================================================================
// GEOMETRY & SILKSCREEN RENDERING HELPERS
// ============================================================================

// Catmull-Rom spline subdivision with optional sharp corner flag [x, y, 1]
function buildPoly(ctrlPts, subdiv = 7, closed = true) {
  let n = ctrlPts.length;
  if (n < 3) return ctrlPts.map(p => [p[0], p[1]]);
  let out = [];
  let count = closed ? n : n - 1;

  for (let i = 0; i < count; i++) {
    let p0 = ctrlPts[(i - 1 + n) % n];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[(i + 1) % n];
    let p3 = ctrlPts[(i + 2) % n];

    if (!closed) {
      if (i === 0) p0 = p1;
      if (i === n - 2) p3 = p2;
    }
    if (p1[2] === 1) p0 = p1;
    if (p2[2] === 1) p3 = p2;

    for (let s = 0; s < subdiv; s++) {
      let t = s / subdiv;
      let t2 = t * t;
      let t3 = t2 * t;
      let x =
        0.5 *
        (2 * p1[0] +
          (-p0[0] + p2[0]) * t +
          (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
          (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y =
        0.5 *
        (2 * p1[1] +
          (-p0[1] + p2[1]) * t +
          (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
          (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  if (!closed) {
    let last = ctrlPts[n - 1];
    out.push([last[0], last[1]]);
  }
  return out;
}

function shiftPoly(pts, dx, dy) {
  if (!dx && !dy) return pts;
  return pts.map(p => [p[0] + dx, p[1] + dy]);
}

// Sutherland-Hodgman polygon clipper against a convex lens boundary
function clipPolyToConvex(subjectPoly, clipPoly) {
  if (!subjectPoly || subjectPoly.length < 3) return [];
  let cx = 0,
    cy = 0;
  for (let p of clipPoly) {
    cx += p[0];
    cy += p[1];
  }
  cx /= clipPoly.length;
  cy /= clipPoly.length;

  let output = subjectPoly.map(p => [p[0], p[1]]);
  let clen = clipPoly.length;

  for (let i = 0; i < clen; i++) {
    let A = clipPoly[i];
    let B = clipPoly[(i + 1) % clen];
    let ex = B[0] - A[0];
    let ey = B[1] - A[1];
    let cSide = ex * (cy - A[1]) - ey * (cx - A[0]);
    let sign = cSide >= 0 ? 1 : -1;

    let input = output;
    output = [];
    if (input.length === 0) break;

    let S = input[input.length - 1];
    for (let j = 0; j < input.length; j++) {
      let E = input[j];
      let sE = (ex * (E[1] - A[1]) - ey * (E[0] - A[0])) * sign;
      let sS = (ex * (S[1] - A[1]) - ey * (S[0] - A[0])) * sign;

      if (sE >= -0.001) {
        if (sS < -0.001) {
          let t = sS / (sS - sE);
          output.push([S[0] + t * (E[0] - S[0]), S[1] + t * (E[1] - S[1])]);
        }
        output.push(E);
      } else if (sS >= -0.001) {
        let t = sS / (sS - sE);
        output.push([S[0] + t * (E[0] - S[0]), S[1] + t * (E[1] - S[1])]);
      }
      S = E;
    }
  }
  return output;
}

// Core silkscreen flat spot-colour shape renderer
function drawScreenShape(pts, colorHex, alpha = 235, opts = {}) {
  if (!pts || pts.length < 3) return;
  let dx = opts.offset ? opts.offset[0] : 0;
  let dy = opts.offset ? opts.offset[1] : 0;
  let finalPts = dx !== 0 || dy !== 0 ? shiftPoly(pts, dx, dy) : pts;

  if (opts.clipPoly) {
    finalPts = clipPolyToConvex(finalPts, opts.clipPoly);
    if (finalPts.length < 3) return;
  }

  brush.noFill();
  brush.noHatch();

  if (alpha > 0) {
    brush.wash(colorHex, alpha);
  } else {
    brush.noWash();
  }

  if (opts.hatchDist) {
    brush.hatchStyle(
      opts.hatchBrush || "halftone_line",
      opts.hatchColor || colorHex,
      opts.hatchWeight || 0.75
    );
    brush.hatch(opts.hatchDist, opts.hatchAngle || 35, {
      rand: opts.hatchRand || 0.02,
      continuous: false
    });
  }

  let edgeW = opts.edgeWeight !== undefined ? opts.edgeWeight : 0.65;
  let edgeBrush = opts.edgeBrush || "stencil_edge";
  let edgeCol = opts.edgeColor || colorHex;

  if (edgeW > 0) {
    brush.set(edgeBrush, edgeCol, edgeW);
  } else {
    brush.noStroke();
  }

  brush.beginShape(0);
  for (let i = 0; i < finalPts.length; i++) {
    brush.vertex(finalPts[i][0], finalPts[i][1]);
  }
  brush.endShape(true);

  brush.noWash();
  brush.noHatch();
}

// Draw a silkscreen shape with an explicit misregistration halo plate behind it
function drawMisregShape(pts, mainCol, mainAlpha, haloCol, haloOffset, opts = {}) {
  if (haloCol && haloOffset) {
    drawScreenShape(pts, haloCol, opts.haloAlpha || 215, {
      offset: haloOffset,
      clipPoly: opts.clipPoly,
      edgeWeight: 0.45
    });
  }
  drawScreenShape(pts, mainCol, mainAlpha, opts);
}

// Clip and draw a line segment inside a convex polygon
function drawClippedLine(x1, y1, x2, y2, clipPoly, brushName, col, weight) {
  let strip = [
    [x1, y1],
    [x2, y2],
    [x2 + 0.5, y2 + 0.5],
    [x1 + 0.5, y1 + 0.5]
  ];
  let clipped = clipPoly ? clipPolyToConvex(strip, clipPoly) : strip;
  if (clipped.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.line(clipped[0][0], clipped[0][1], clipped[1][0], clipped[1][1]);
}

