// Helper to draw a detailed miniature Royal Palm clipped to the aviator lens
function drawMiniaturePalm(lensPoly, baseX, baseY, topX, topY, crownRadius, sc) {
  let midX = (baseX + topX) * 0.5 + (topX > baseX ? 8 : -8) * sc;
  let midY = (baseY + topY) * 0.5;
  let wBase = 5.5 * sc;
  let wTop = 2.2 * sc;

  // Trunk shadow core (Black) + Sunlit Cream/Ochre trunk edge
  let trunkBlack = buildPoly(
    [
      [baseX - wBase, baseY, 1],
      [midX - wBase * 0.7, midY],
      [topX - wTop, topY, 1],
      [topX + wTop, topY, 1],
      [midX + wBase * 0.7, midY],
      [baseX + wBase, baseY, 1]
    ],
    5,
    true
  );
  drawScreenShape(trunkBlack, PALETTE.black, 250, { clipPoly: lensPoly, edgeWeight: 0.5 });

  let trunkHighlight = buildPoly(
    [
      [baseX - wBase, baseY, 1],
      [midX - wBase * 0.7, midY],
      [topX - wTop, topY, 1],
      [topX, topY, 1],
      [midX - wBase * 0.1, midY],
      [baseX - wBase * 0.2, baseY, 1]
    ],
    5,
    true
  );
  drawScreenShape(trunkHighlight, PALETTE.ochreLight, 240, { clipPoly: lensPoly, edgeWeight: 0 });

  // Crown of arching palm fronds with serrated leaflet silhouettes
  let frondAngles = [-165, -135, -105, -70, -35, -10, 20, 145];
  for (let idx = 0; idx < frondAngles.length; idx++) {
    let ang = frondAngles[idx];
    let rad = crownRadius * (idx % 2 === 0 ? 1.0 : 0.85);
    let endX = topX + cos(ang) * rad;
    let endY = topY + sin(ang) * rad + rad * 0.28; // gravity droop
    let ctrlX = topX + cos(ang) * (rad * 0.55);
    let ctrlY = topY + sin(ang) * (rad * 0.55) - 6 * sc;

    // Serrated frond polygon
    let frondPoly = buildPoly(
      [
        [topX, topY, 1],
        [ctrlX - 4 * sc, ctrlY - 5 * sc],
        [endX, endY, 1],
        [ctrlX + 4 * sc, ctrlY + 6 * sc]
      ],
      5,
      true
    );
    drawScreenShape(frondPoly, PALETTE.black, 248, { clipPoly: lensPoly, edgeWeight: 0.55 });

    // Sunlit Ochre upper rib on top fronds
    if (ang < -20 && ang > -150) {
      drawClippedLine(topX, topY, ctrlX, ctrlY, lensPoly, "stencil_edge", PALETTE.ochreLight, 0.75 * sc);
    }
  }
}

