// 8. BOLD HAND-DRAWN CUBAN POSTER TITLE LETTERING (LOWER THIRD)
// ============================================================================
function drawCubanPosterTypography() {
  // Bold graphic ribbon / cut across the lower third (y: 940..1115)
  // Upper credit bar: Dark Turquoise + Cream rules
  let subBanner = [
    [88, 932],
    [1112, 916],
    [1112, 954],
    [88, 970]
  ];
  drawMisregShape(subBanner, PALETTE.black, 248, PALETTE.tomato, [-5, 4], {
    edgeWeight: 0.9,
    edgeBrush: "screen_marker"
  });

  // Crisp Ochre & Cream framing rules above and below title
  drawClippedLine(92, 925, 1108, 909, null, "screen_marker", PALETTE.cream, 1.4);
  drawClippedLine(92, 1112, 1108, 1096, null, "screen_marker", PALETTE.cream, 1.4);
  drawClippedLine(92, 1118, 1108, 1102, null, "screen_marker", PALETTE.tomato, 1.2);

  // Hand-cut graphic glyphs for "ICAIC · LA HABANA" in the sub-banner
  drawSubBannerText();

  // HERO HAND-DRAWN DISPLAY TITLE: "COSTA ROJA"
  // 9 bold, hand-cut mid-century Cuban poster block letters cutting across y = 968..1095
  const word = ["C", "O", "S", "T", "A", " ", "R", "O", "J", "A"];
  let startX = 94;
  let baseY = 978;
  let letterW = 92;
  let letterH = 112;
  let gap = 12;

  let curX = startX;
  for (let i = 0; i < word.length; i++) {
    let ch = word[i];
    if (ch === " ") {
      curX += 46;
      continue;
    }
    // Slight rising poster slant (-0.0155 slope)
    let ly = baseY - (curX - startX) * 0.0155;
    // Slight organic hand-cut jitter per letter
    let jx = (i % 2 === 0 ? 1 : -1) * 1.5;
    let jy = (i % 3 === 0 ? -1.5 : 1) * 1.2;

    drawHandCutLetter(ch, curX + jx, ly + jy, letterW, letterH, i >= 6);
    curX += letterW + gap;
  }
}

// Hand-drawn vector block letters with 3-plate silkscreen misregistration
function drawHandCutLetter(ch, x, y, w, h, isRedWord) {
  let polys = [];
  let cutouts = [];
  let t = 25; // thick chunky stem width

  if (ch === "C") {
    polys.push([
      [x + w, y + 2],
      [x + w - 4, y + t + 4],
      [x + t + 4, y + t],
      [x + t, y + h - t],
      [x + w - 2, y + h - t - 2],
      [x + w, y + h - 2],
      [x + 14, y + h],
      [x, y + h - 16],
      [x + 2, y + 16],
      [x + 16, y]
    ]);
  } else if (ch === "O") {
    polys.push([
      [x + 16, y],
      [x + w - 14, y + 2],
      [x + w, y + 18],
      [x + w - 2, y + h - 16],
      [x + w - 16, y + h],
      [x + 14, y + h - 2],
      [x, y + h - 18],
      [x + 2, y + 16]
    ]);
    cutouts.push([
      [x + t + 2, y + t],
      [x + w - t - 2, y + t + 2],
      [x + w - t - 4, y + h - t],
      [x + t, y + h - t - 2]
    ]);
  } else if (ch === "S") {
    polys.push([
      [x + w - 2, y + 4],
      [x + w - 6, y + t + 2],
      [x + t + 2, y + t - 2],
      [x + t, y + h * 0.42],
      [x + w - 8, y + h * 0.46],
      [x + w, y + h - 14],
      [x + w - 14, y + h],
      [x + 2, y + h - 2],
      [x + 6, y + h - t - 2],
      [x + w - t - 2, y + h - t + 2],
      [x + w - t, y + h * 0.62],
      [x + 8, y + h * 0.56],
      [x, y + 16],
      [x + 14, y]
    ]);
  } else if (ch === "T") {
    polys.push([
      [x, y + 2],
      [x + w, y],
      [x + w - 2, y + t + 2],
      [x + w * 0.5 + t * 0.52, y + t + 2],
      [x + w * 0.5 + t * 0.48, y + h],
      [x + w * 0.5 - t * 0.52, y + h - 2],
      [x + w * 0.5 - t * 0.48, y + t + 2],
      [x + 2, y + t + 4]
    ]);
  } else if (ch === "A") {
    polys.push([
      [x + w * 0.34, y],
      [x + w * 0.68, y + 2],
      [x + w, y + h],
      [x + w - t - 2, y + h],
      [x + w - t - 8, y + h * 0.74],
      [x + t + 8, y + h * 0.74],
      [x + t + 2, y + h],
      [x, y + h - 2]
    ]);
    cutouts.push([
      [x + w * 0.5, y + t + 4],
      [x + w - t - 12, y + h * 0.56],
      [x + t + 12, y + h * 0.56]
    ]);
  } else if (ch === "R") {
    polys.push([
      [x + 2, y],
      [x + w - 14, y + 2],
      [x + w, y + 16],
      [x + w - 2, y + h * 0.48],
      [x + w - 18, y + h * 0.58],
      [x + w + 2, y + h],
      [x + w - t - 2, y + h],
      [x + w * 0.44, y + h * 0.62],
      [x + t + 2, y + h * 0.62],
      [x + t, y + h],
      [x, y + h - 2]
    ]);
    cutouts.push([
      [x + t + 2, y + t - 2],
      [x + w - t - 2, y + t],
      [x + w - t - 4, y + h * 0.44],
      [x + t, y + h * 0.44]
    ]);
  } else if (ch === "J") {
    polys.push([
      [x + w - t - 2, y],
      [x + w, y + 2],
      [x + w - 2, y + h - 16],
      [x + w - 16, y + h],
      [x + 14, y + h - 2],
      [x, y + h - 18],
      [x + 2, y + h * 0.62],
      [x + t + 2, y + h * 0.64],
      [x + t, y + h - t],
      [x + w - t - 4, y + h - t]
    ]);
  }

  let faceCol = isRedWord ? PALETTE.tomato : PALETTE.cream;
  let haloCol = isRedWord ? PALETTE.cream : PALETTE.tomato;
  let shadowCutCol = PALETTE.black;

  for (let p of polys) {
    // 1. Heavy Black Extruded Drop Shadow Plate
    drawScreenShape(p, PALETTE.black, 250, {
      offset: [9, 9],
      edgeWeight: 0.9,
      edgeBrush: "screen_marker"
    });
    // 2. Misregistered Turquoise & Halo Plates
    drawScreenShape(p, PALETTE.turquoise, 230, {
      offset: [-5, 4],
      edgeWeight: 0.6
    });
    drawScreenShape(p, haloCol, 235, {
      offset: [4, -4],
      edgeWeight: 0.6
    });
    // 3. Main Hand-Cut Letter Face
    drawScreenShape(p, faceCol, 250, {
      edgeWeight: 1.1,
      edgeBrush: "screen_marker",
      edgeColor: PALETTE.black
    });
  }

  for (let c of cutouts) {
    drawScreenShape(shiftPoly(c, 5, 5), PALETTE.turquoiseDark, 240, { edgeWeight: 0.5 });
    drawScreenShape(c, shadowCutCol, 250, {
      edgeWeight: 0.9,
      edgeBrush: "screen_marker"
    });
  }
}

