function drawSilkscreenFinishing() {
  // Mask out the outer paper margin cleanly so misregistered background plates have a crisp screen edge
  let m = 68;
  let topM = [
    [0, 0],
    [1200, 0],
    [1200, m],
    [0, m]
  ];
  let botM = [
    [0, 1200 - m],
    [1200, 1200 - m],
    [1200, 1200],
    [0, 1200]
  ];
  let leftM = [
    [0, 0],
    [m, 0],
    [m, 1200],
    [0, 1200]
  ];
  let rightM = [
    [1200 - m, 0],
    [1200, 0],
    [1200, 1200],
    [1200 - m, 1200]
  ];

  drawScreenShape(topM, PALETTE.paper, 255, { edgeWeight: 0 });
  drawScreenShape(botM, PALETTE.paper, 255, { edgeWeight: 0 });
  drawScreenShape(leftM, PALETTE.paper, 255, { edgeWeight: 0 });
  drawScreenShape(rightM, PALETTE.paper, 255, { edgeWeight: 0 });

  // Misregistered border rules around the silkscreen image area
  brush.noFill();
  brush.noWash();
  brush.set("screen_marker", PALETTE.turquoise, 0.9);
  brush.rect(72, 66, 1060, 1064, "corner");

  brush.set("screen_marker", PALETTE.tomato, 0.9);
  brush.rect(65, 71, 1064, 1060, "corner");

  brush.set("screen_marker", PALETTE.black, 1.35);
  brush.rect(68, 68, 1064, 1064, "corner");

  // 4 Corner Silkscreen Registration Targets (+) printed in all 4 spot colours
  let regCorners = [
    [36, 36],
    [1164, 36],
    [36, 1164],
    [1164, 1164]
  ];
  let regPlates = [
    [PALETTE.ochre, PLATE_OFFSET.ochre],
    [PALETTE.turquoise, PLATE_OFFSET.turquoise],
    [PALETTE.tomato, PLATE_OFFSET.tomato],
    [PALETTE.black, [0, 0]]
  ];

  for (let rc of regCorners) {
    for (let rp of regPlates) {
      let col = rp[0];
      let ox = rp[1][0] * 0.65;
      let oy = rp[1][1] * 0.65;
      let rx = rc[0] + ox;
      let ry = rc[1] + oy;
      brush.set("stencil_edge", col, 0.7);
      brush.line(rx - 14, ry, rx + 14, ry);
      brush.line(rx, ry - 14, rx, ry + 14);
      brush.circle(rx, ry, 7, 0.05);
    }
  }

  // Color-bar swatches along bottom right margin (printer's colour blocks)
  let swatchColors = [PALETTE.cream, PALETTE.ochre, PALETTE.tomato, PALETTE.turquoise, PALETTE.black];
  for (let i = 0; i < swatchColors.length; i++) {
    let sx = 940 + i * 34;
    let sy = 1144;
    let sw = [
      [sx, sy],
      [sx + 26, sy],
      [sx + 26, sy + 16],
      [sx, sy + 16]
    ];
    drawScreenShape(sw, swatchColors[i], 245, {
      edgeWeight: 0.5,
      edgeColor: PALETTE.black
    });
  }

  // Subtle dry squeegee ink grain pass across the print for physical serigraph tooth
  brush.set("ink_grain", PALETTE.paper, 0.9);
  for (let i = 0; i < 28; i++) {
    let gx = random(90, 1110);
    let gy = random(90, 1110);
    brush.line(gx, gy, gx + random(-45, 45), gy + random(-12, 12));
  }
}

