// ============================================================================
// SCENE MODEL FOR ACCURATE REFLECTION SAMPLING
// ============================================================================

function getPatchIrregularRadius(patch, angleDeg, radiusScale) {
  let a = angleDeg * (PI / 180);
  let n1 = noise(cos(a) * 1.4 + patch.seed, sin(a) * 1.4 + patch.seed) - 0.5;
  let n2 = noise(cos(a * 2.5) * 1.8 + patch.seed * 2, sin(a * 2.5) * 1.8) - 0.5;
  let factor = 1 + n1 * 0.38 + n2 * 0.18;
  return {
    rx: patch.rx * radiusScale * factor,
    ry: patch.ry * radiusScale * factor
  };
}

function pointInPatch(x, y, patch, radiusScale) {
  let dx = x - patch.cx;
  let dy = y - patch.cy;
  let ang = atan2(dy, dx);
  let r = getPatchIrregularRadius(patch, ang, radiusScale);
  return (dx * dx) / (r.rx * r.rx) + (dy * dy) / (r.ry * r.ry) <= 1.0;
}

// Returns { color, type, brightness } for any point (x, y) in the upper band (y in -120..WATER_Y)
function sampleUpperScene(x, y) {
  // 1. Barber-pole mooring post at x = 206..284
  if (x >= 204 && x <= 286 && y >= 10) {
    let u = (x - 245) / 40; // -1 to +1 across cylinder
    let cylCurve = sqrt(max(0, 1 - u * u)) * 16;
    let stripeCoord = y + (x - 206) * 0.68 - cylCurve;
    let stripePhase = ((stripeCoord % 90) + 90) % 90;
    let isRed = stripePhase < 46;

    // Mossy wet base near waterline
    if (y > 402 + noise(x * 0.08) * 14) {
      return { color: u > 0.3 ? PAL.bottleDark : PAL.bottleGreen, type: "pole_moss", brightness: 0.2 };
    }
    // Iron collar at y ~ 278
    if (abs(y - cylCurve * 0.4 - 278) < 6) {
      return { color: PAL.inkDark, type: "pole_iron", brightness: 0.15 };
    }

    if (isRed) {
      if (u < -0.25) return { color: PAL.venetianBright, type: "pole_red_light", brightness: 0.62 };
      if (u < 0.38) return { color: PAL.venetianRed, type: "pole_red_mid", brightness: 0.45 };
      return { color: PAL.venetianDark, type: "pole_red_dark", brightness: 0.25 };
    } else {
      if (u < -0.15) return { color: PAL.poleWhite, type: "pole_white_light", brightness: 0.95 };
      if (u < 0.42) return { color: PAL.poleCream, type: "pole_white_mid", brightness: 0.78 };
      return { color: PAL.poleShadow, type: "pole_white_dark", brightness: 0.48 };
    }
  }

  // Mooring post cast shadow on wall
  if (x > 284 && x < 336 && y > 35 && y < 436) {
    return { color: PAL.ochreShadow, type: "wall_shadow", brightness: 0.32 };
  }

  // 2. Waterline stone foundation & algae band (y = 386..436)
  if (y >= 418) {
    return { color: PAL.bottleDark, type: "algae", brightness: 0.18 };
  }
  if (y >= 386) {
    if (y < 396) return { color: PAL.stoneLight, type: "stone_light", brightness: 0.88 };
    if (y < 403) return { color: PAL.ochreShadow, type: "stone_shadow", brightness: 0.35 };
    return { color: PAL.stoneMid, type: "stone_mid", brightness: 0.72 };
  }

  // 3. Main Window & Bottle-Green Shutters (x = 348..814, y = -60..328)
  if (y >= -60 && y <= 330) {
    // Stone windowsill
    if (x >= 438 && x <= 722 && y >= 304 && y <= 328) {
      return { color: y < 316 ? PAL.stoneLight : PAL.stoneShadow, type: "sill", brightness: y < 316 ? 0.9 : 0.45 };
    }
    // Left open bottle-green shutter
    if (x >= 348 && x <= 462 && y <= 306) {
      let louver = ((y % 11) + 11) % 11;
      if (louver < 3.5) return { color: PAL.bottleDark, type: "shutter_dark", brightness: 0.18 };
      if (louver < 7.5) return { color: PAL.bottleGreen, type: "shutter_mid", brightness: 0.32 };
      return { color: PAL.jadeMid, type: "shutter_light", brightness: 0.48 };
    }
    // Window dark interior aperture
    if (x > 462 && x < 698 && y <= 306) {
      // Interior wooden mullion cross
      if (abs(x - 580) < 7 || abs(y - 155) < 7 || x < 474 || x > 686) {
        return { color: PAL.stoneMid, type: "window_frame", brightness: 0.7 };
      }
      // Subtle warm/jade interior glass reflection
      if ((x + y * 0.6) % 95 < 26) {
        return { color: PAL.jadeDeep, type: "window_glass", brightness: 0.28 };
      }
      return { color: PAL.bottleDark, type: "window_dark", brightness: 0.12 };
    }
    // Right angled bottle-green shutter
    if (x >= 698 && x <= 814 && y <= 314) {
      let louver = (((y - (x - 698) * 0.08) % 11) + 11) % 11;
      if (louver < 3.5) return { color: PAL.bottleDark, type: "shutter_dark", brightness: 0.2 };
      if (louver < 7.5) return { color: PAL.bottleLight, type: "shutter_mid", brightness: 0.38 };
      return { color: PAL.jadeLight, type: "shutter_light", brightness: 0.56 };
    }
  }

  // Right shutter diagonal cast shadow on wall
  if (x > 706 && x < 862 && y > 35 && y < 342 && (x - 706) < (y - 10) * 0.52) {
    return { color: PAL.ochreShadow, type: "shutter_shadow", brightness: 0.32 };
  }

  // 4. Right-Side Window with Closed Bottle-Green Shutters (x = 955..1175, y = -60..328)
  if (y >= -60 && y <= 330) {
    if (x >= 948 && x <= 1182 && y >= 304 && y <= 328) {
      return { color: y < 316 ? PAL.stoneLight : PAL.stoneShadow, type: "sill", brightness: y < 316 ? 0.88 : 0.45 };
    }
    if (x >= 962 && x <= 1168 && y <= 306) {
      if (abs(x - 1065) < 4) return { color: PAL.bottleDark, type: "shutter_gap", brightness: 0.12 };
      let louver = ((y % 11) + 11) % 11;
      if (louver < 3.5) return { color: PAL.bottleDark, type: "shutter_dark", brightness: 0.18 };
      if (louver < 7.5) return { color: PAL.bottleGreen, type: "shutter_mid", brightness: 0.33 };
      return { color: PAL.jadeMid, type: "shutter_light", brightness: 0.48 };
    }
  }

  // 5. Peeling Plaster & Venetian Red Brick Patches
  for (let p of PEEL_PATCHES) {
    if (pointInPatch(x, y, p, 0.64)) {
      return { color: PAL.venetianRed, type: "brick", brightness: 0.44 };
    }
    if (pointInPatch(x, y, p, 1.0)) {
      return { color: PAL.roseMid, type: "rose_plaster", brightness: 0.58 };
    }
  }

  // 6. Base Peeling Ochre-and-Rose Wall Plaster
  let n = noise(x * 0.006, y * 0.008);
  if (n > 0.58) {
    return { color: PAL.roseLight, type: "wall_rose", brightness: 0.68 };
  } else if (n < 0.36) {
    return { color: PAL.ochreDeep, type: "wall_ochre_deep", brightness: 0.58 };
  } else {
    return { color: PAL.ochreLight, type: "wall_ochre", brightness: 0.76 };
  }
}

