  brush.noFill();
}

// ============================================================================
// 2. LOWER BAND: FRACTURED WATERCOLOUR REFLECTION IN CANAL
// ============================================================================

function drawCanalReflection() {
  // --- LAYER 2A: Deep Wet-in-Wet Watercolour Underwashes ---
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.68, 0.32);

  // Murky jade & bottle-green base canal body
  brush.fill(PAL.jadeMurky, 52);
  brush.rect(0, WATER_Y, 1200, 1200 - WATER_Y, "corner");

  // Warm ochre & rose reflection columns bleeding into the water
  const ochreZones = [
    [0, WATER_Y, 210, 764],
    [280, WATER_Y, 185, 764],
    [710, WATER_Y, 260, 764]
  ];
  brush.fill(PAL.ochreMid, 62);
  for (let z of ochreZones) {
    brush.rect(z[0], z[1], z[2], z[3], "corner");
  }

  // Rose & Venetian red under-glow beneath peeling plaster zones & barber pole
  const roseZones = [
    [50, WATER_Y + 40, 170, 520],
    [195, WATER_Y, 105, 750],
    [755, WATER_Y + 60, 210, 580]
  ];
  brush.fill(PAL.roseMid, 58);
  for (let z of roseZones) {
    brush.rect(z[0], z[1], z[2], z[3], "corner");
  }

  // Deep bottle-green & murky jade under-glow beneath the shutters & window apertures
  const greenZones = [
    [335, WATER_Y, 485, 764],
    [945, WATER_Y, 245, 764]
  ];
  brush.fill(PAL.bottleGreen, 65);
  for (let z of greenZones) {
    brush.rect(z[0], z[1], z[2], z[3], "corner");
  }

  brush.noFill();

  // --- LAYER 2B: Dragged Wet Streaks (Vertical Watery Curtains) ---
  // Simulates dragging a loaded wet brush vertically through the damp reflection wash
  for (let i = 0; i < 165; i++) {
    let sx = random(8, 1192);
    let sy1 = WATER_Y + random(0, 240);
    let len = random(160, 560);
    let sy2 = min(1195, sy1 + len);

    // Sample the upper scene right above this x to pick an authentic dragged pigment
    let sampleRefY = map(sy1, WATER_Y, 1200, WATER_Y - 10, 40);
    let samp = sampleUpperScene(sx, sampleRefY);

    let streakCol = samp.color;
    if (random() < 0.28) {
      streakCol = random() < 0.5 ? PAL.jadeMurky : PAL.bottleGreen;
    }

    let w = random(0.9, 2.4);
    brush.set("wet_streak", streakCol, w);

    let pts = [];
    let steps = 6;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let py = lerp(sy1, sy2, t);
      let px = sx + sin(py * 0.025 + i) * 7 + (noise(sx * 0.01, py * 0.008) - 0.5) * 14;
      pts.push([px, py, sin(t * 180) * 1.1 + 0.25]);
    }
    brush.spline(pts, 0.5);
  }

  // --- LAYER 2C: Wobbling Horizontal Ribbons (Stretched & Broken by Small Ripples) ---
  // Generate 72 wave rows from WATER_Y (436) down to 1196
  let waveRows = [];
  let curY = WATER_Y + 3;
  let rowIdx = 0;
  while (curY < 1194) {
    let progress = (curY - WATER_Y) / (1200 - WATER_Y); // 0 at waterline, 1 at bottom
    let dy = lerp(4.8, 18.5, pow(progress, 0.88));
    waveRows.push({
      idx: rowIdx,
      baseY: curY,
      dy: dy,
      progress: progress
    });
    curY += dy;
    rowIdx++;
  }

  // Helper to get wave vertical undulation at (x, row)
  function getWaveY(x, row) {
    let p = row.progress;
    let amp = lerp(1.6, 11.5, p);
    let w1 = sin(x * 0.85 + row.idx * 42) * amp * 0.55;
    let w2 = cos(x * 0.42 - row.idx * 27) * amp * 0.45;
    let n = (noise(x * 0.004, row.idx * 0.16) - 0.5) * amp * 1.4;
    return row.baseY + w1 + w2 + n;
  }

  // First pass on rows: Paint the Murky Jade & Bottle Green Ripple Troughs
  for (let row of waveRows) {
    let p = row.progress;
    let troughWeight = map(p, 0, 1, 0.45, 1.65);

    // Every wave has a trough/interstice where water surface reflects murky jade or bottle green
    let x = 10;
    while (x < 1190) {
      let segLen = random(70, 210);
      let xEnd = min(1192, x + segLen);

      // Determine trough darkness based on whether it's under shutters/post or open wall
      let midX = (x + xEnd) * 0.5;
      let troughCol = PAL.jadeMurky;
      if ((midX > 340 && midX < 820) || midX > 955) {
        troughCol = random() < 0.6 ? PAL.bottleGreen : PAL.jadeDeep;
      } else if (midX > 195 && midX < 295) {
        troughCol = random() < 0.5 ? PAL.jadeDeep : PAL.inkGreen;
      } else {
        troughCol = random() < 0.55 ? PAL.jadeMid : PAL.jadeMurky;
      }

      let pts = [];
      for (let sx = x; sx <= xEnd; sx += 18) {
        let wy = getWaveY(sx, row) - row.dy * 0.36;
        pts.push([sx, wy, random(0.6, 1.15)]);
      }
      if (pts.length >= 2) {
        brush.set("ribbon_wash", troughCol, troughWeight);
        brush.spline(pts, 0.45);
      }

      x = xEnd + random(12, 42);
    }
  }

  // Second pass on rows: Paint the Stretched & Broken Architectural Reflection Ribbons
  for (let row of waveRows) {
    let p = row.progress;

    // Reflection vertical mapping: stretches the 436px upper wall across the 764px canal
    // Plus vertical wave-tilt oscillation that stretches and breaks features across ripples
    let baseRefY = WATER_Y - (row.baseY - WATER_Y) * 0.57;

    // Horizontal wobble displacement for this ribbon
    let wobbleAmp = lerp(4, 38, pow(p, 0.75));

    let x = 8;
    while (x < 1192) {
      // Calculate local horizontal ripple shear
      let localShear =
        sin(row.idx * 53 + x * 0.45) * wobbleAmp * 0.65 +
        (noise(x * 0.007, row.idx * 0.25) - 0.5) * wobbleAmp * 1.3;

      // Vertical stretch offset from wave slope
      let localRefY =
        baseRefY +
        cos(row.idx * 47 + x * 0.35) * lerp(4, 24, p) +
        (noise(x * 0.009, row.idx * 0.3 + 50) - 0.5) * 18;

      let sampleX = constrain(x + localShear, 2, 1198);
      let sampleY = constrain(localRefY, -55, WATER_Y - 2);
      let firstSample = sampleUpperScene(sampleX, sampleY);

      // Walk horizontally while the reflected element stays in the same color family
      // or until a small capillary ripple breaks the ribbon
      let maxRibbonLen = (sampleX > 185 && sampleX < 310) ? random(22, 54) : random(45, 145);
      let stepX = 10;
      let curX = x;
      let ribbonPts = [];
      let upperEdgePts = [];
      let lowerEdgePts = [];

      let halfThick = row.dy * lerp(0.32, 0.44, noise(x * 0.01, row.idx * 0.2));

      while (curX <= min(1194, x + maxRibbonLen)) {
        let sShear =
          sin(row.idx * 53 + curX * 0.45) * wobbleAmp * 0.65 +
          (noise(curX * 0.007, row.idx * 0.25) - 0.5) * wobbleAmp * 1.3;
        let sSampleX = constrain(curX + sShear, 2, 1198);
        let sSample = sampleUpperScene(sSampleX, sampleY);

        if (curX > x && sSample.type !== firstSample.type) {
          break;
        }

        let wy = getWaveY(curX, row);
        // Taper thickness at both ends of the broken ribbon for a liquid lens shape
        let normT = (curX - x) / max(12, maxRibbonLen);
        let lensTaper = sin(constrain(normT, 0.08, 0.92) * 180);
        let h = halfThick * (0.35 + 0.65 * lensTaper);

        ribbonPts.push([curX, wy, 0.5 + 0.7 * lensTaper]);
        upperEdgePts.push([curX, wy - h]);
        lowerEdgePts.push([curX, wy + h]);

        curX += stepX;
      }

      if (ribbonPts.length >= 2) {
        let ribCol = firstSample.color;
        let ribWeight = map(p, 0, 1, 0.55, 1.95);

        // If this is a prominent foreground/midground ribbon or barber-pole stripe,
        // give it a luminous watercolor wash polygon + wet brush stroke
        if (upperEdgePts.length >= 3 && (p > 0.22 || firstSample.type.startsWith("pole_"))) {
          let polyPts = [];
          for (let pt of upperEdgePts) polyPts.push(pt);
          for (let k = lowerEdgePts.length - 1; k >= 0; k--) polyPts.push(lowerEdgePts[k]);

          let poly = new brush.Polygon(polyPts);
          let washAlpha = firstSample.type.startsWith("pole_") ? 155 : 115;
          poly.wash(ribCol, washAlpha);

          // Selective true watercolor bleed on larger ribbons for organic pigment blooms
          if (row.idx % 4 === 0 && polyPts.length >= 6 && random() < 0.35) {
            poly.fill(ribCol, 55, 0.22, 0.55);
          }
        }

        // Core watercolor ribbon stroke
        brush.set("ribbon_wash", ribCol, ribWeight);
        brush.spline(ribbonPts, 0.45);

        // Soft wet edge bleed along the ribbon
        if (random() < 0.65) {
          brush.set("wet_streak", ribCol, ribWeight * 0.55);
          brush.spline(ribbonPts, 0.5);
        }
      }

      // Small ripple gap before the next ribbon segment
      let gap = (sampleX > 180 && sampleX < 315) ? random(4, 14) : random(6, 22);
      x = max(x + stepX, curX + gap);
    }
  }

  // --- LAYER 2D: Lifted Lights in the Water ---
  // Soft pale cream & translucent jade highlights where pigment is lifted out on wave crests
  for (let row of waveRows) {
    let p = row.progress;
    let x = random(10, 45);
    while (x < 1185) {
      let shear = sin(row.idx * 53 + x * 0.45) * lerp(4, 38, pow(p, 0.75)) * 0.65;
      let refY = WATER_Y - (row.baseY - WATER_Y) * 0.57;
      let samp = sampleUpperScene(constrain(x + shear, 2, 1198), constrain(refY, 0, WATER_Y - 2));

      // Lift lights strongly on barber-pole white stripes, stone sills, sunlit ochre, and random wave glints
      let liftChance = samp.brightness > 0.72 ? 0.78 : 0.26;
      if (random() < liftChance) {
        let len = samp.type.startsWith("pole_") ? random(18, 42) : random(32, 95);
        let pts = [];
        for (let sx = x; sx <= min(1192, x + len); sx += 12) {
          let wy = getWaveY(sx, row) - row.dy * 0.22;
          pts.push([sx, wy, random(0.4, 1.1)]);
        }
        if (pts.length >= 2) {
          let liftCol = samp.brightness > 0.75 ? PAL.poleWhite : (random() < 0.5 ? PAL.paper : PAL.jadeLight);
          brush.set("lifted_light", liftCol, map(p, 0, 1, 0.45, 1.35));
          brush.spline(pts, 0.5);

          // Crisp bright glint inside the lifted light
          if (samp.brightness > 0.8 || random() < 0.35) {
            brush.set("cpencil", PAL.poleWhite, map(p, 0, 1, 0.35, 0.85));
            brush.spline(pts, 0.5);
          }
        }
        x += len + random(18, 55);
      } else {
        x += random(25, 65);
      }
    }
  }

  // Vertical lifted light streaks (where a damp clean brush was wiped vertically through the wet wash)
  for (let i = 0; i < 38; i++) {
    let lx = random(35, 1165);
    // Concentrate some lifted vertical streaks beneath the sunlit barber pole & stone sills
    if (i < 12) lx = random(205, 275);
    else if (i < 20) lx = random(450, 710);

    let ly1 = WATER_Y + random(15, 380);
    let ly2 = min(1185, ly1 + random(90, 290));
    let pts = [];
    for (let s = 0; s <= 5; s++) {
      let t = s / 5;
      let py = lerp(ly1, ly2, t);
      let px = lx + sin(py * 0.04 + i) * 4;
      pts.push([px, py, sin(t * 180) * 0.95 + 0.15]);
    }
    brush.set("lifted_light", PAL.paper, random(0.65, 1.35));
    brush.spline(pts, 0.4);
  }

  // --- LAYER 2E: Fine Pen Squiggles Marking the Ripple Edges ---
  for (let row of waveRows) {
    let p = row.progress;
    let x = random(6, 28);

    while (x < 1190) {
      let shear = sin(row.idx * 53 + x * 0.45) * lerp(4, 38, pow(p, 0.75)) * 0.65;
      let sampleX = constrain(x + shear, 2, 1198);
      let isPoleZone = sampleX >= 188 && sampleX <= 305;

      let segLen = isPoleZone ? random(24, 58) : random(36, 115);
      let xEnd = min(1192, x + segLen);

      // Choose ink shade to harmonize with local reflection
      let inkCol = PAL.inkDark;
      if ((sampleX > 345 && sampleX < 820) || sampleX > 955) {
        inkCol = random() < 0.6 ? PAL.inkGreen : PAL.inkDark;
      } else if (isPoleZone && random() < 0.45) {
        inkCol = PAL.inkRed;
      }

      let penWeight = map(p, 0, 1, 0.24, 0.48);
      brush.set(random() < 0.65 ? "rotring" : "pen", inkCol, penWeight);

      // Build a lively, squiggling ripple-edge contour with capillary wave oscillations
      let squigglePts = [];
      let step = isPoleZone ? 6 : 8;
      let squigFreq = random(18, 32);
      let squigAmp = lerp(1.1, 3.6, p) * (isPoleZone ? 1.25 : 1.0);
      let edgeSide = random() < 0.5 ? -1 : 1;

      for (let sx = x; sx <= xEnd; sx += step) {
        let wy = getWaveY(sx, row) + edgeSide * row.dy * 0.34;
        // High-frequency capillary squiggle + organic hand wobble
        let wigY =
          sin((sx - x) * squigFreq + row.idx * 35) * squigAmp +
          cos((sx - x) * squigFreq * 0.55) * squigAmp * 0.45;
        let wigX = cos((sx - x) * squigFreq * 0.8 + row.idx) * (squigAmp * 0.55);
        let press = 0.45 + 0.55 * sin(constrain((sx - x) / max(1, xEnd - x), 0, 1) * 180);
        squigglePts.push([sx + wigX, wy + wigY, press]);
      }

      if (squigglePts.length >= 3) {
        brush.spline(squigglePts, 0.55);
      }

      // Occasional closed ripple eye / figure-eight squiggle loop in the mid & foreground water
      if (p > 0.2 && random() < 0.22) {
        let cx = (x + xEnd) * 0.5;
        let cy = getWaveY(cx, row) + row.dy * 0.38;
        let rx = random(9, 24) * lerp(0.6, 1.3, p);
        let ry = random(1.8, 4.2) * lerp(0.6, 1.3, p);
        let loopPts = [];
        for (let a = 0; a <= 390; a += 45) {
          let lx = cx + cos(a) * rx + sin(a * 2) * 2.2;
          let ly = cy + sin(a) * ry;
          loopPts.push([lx, ly, 0.5]);
        }
        brush.set("rotring", inkCol, penWeight * 0.85);
        brush.spline(loopPts, 0.6);
      }

      x = xEnd + (isPoleZone ? random(6, 18) : random(12, 38));
    }
  }
}

// ============================================================================
// 3. UPPER BAND: CRISP PEELING OCHRE-AND-ROSE WALL & BOTTLE-GREEN SHUTTERS
// ============================================================================

function drawUpperWallAndShutters() {
  // --- 3A. Crisp Base Plaster Wall (Ochre & Rose) ---
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.48, 0.28);

  // Main warm ochre plaster coat
  brush.fill(PAL.ochreLight, 145);
  brush.rect(0, 0, 1200, 390, "corner");

  // Secondary tonal zoning of deeper golden ochre & dusty rose plaster patina
  const ochreClouds = [
    [0, 0, 360, 220],
    [290, 180, 420, 210],
    [720, 0, 260, 190],
    [830, 240, 370, 150]
  ];
  brush.fill(PAL.ochreMid, 85);
  for (let c of ochreClouds) {
    brush.rect(c[0], c[1], c[2], c[3], "corner");
  }

  const roseClouds = [
    [35, 130, 260, 255],
    [680, 110, 290, 275],
    [980, 280, 220, 110]
  ];
  brush.fill(PAL.roseLight, 80);
  for (let c of roseClouds) {
    brush.rect(c[0], c[1], c[2], c[3], "corner");
  }

  brush.noFill();

  // Crisp dry-brush stucco grain and subtle vertical damp streaks on the plaster wall
  brush.hatchStyle("2H", PAL.ochreDeep, 0.35);
  brush.hatch(9, 88, { rand: 0.12 });
  brush.noStroke();
  brush.rect(0, 0, 1200, 388, "corner");
  brush.noHatch();

  // --- 3B. Peeling Plaster Patches & Exposed Venetian Red Brickwork ---
  for (let p of PEEL_PATCHES) {
    drawPeelingPlasterPatch(p);
  }

  // --- 3C. Istrian Stone Base Cornice & Tidal Algae Band (y = 386..436) ---
  drawStoneWaterlineBase();

  // --- 3D. Cast Shadows on Wall (from Shutters, Sills, and Mooring Post) ---
  drawWallCastShadows();

  // --- 3E. Windows & Bottle-Green Shutters ---
  drawMainWindowAndShutters();
  drawRightWindowAndShutters();

  // --- 3F. Reflective Liquid Caustics Bouncing Up onto the Wall & Sills ---
  drawReflectedWallCaustics();
}

function drawPeelingPlasterPatch(p) {
  let outerPts = [];
  let shadowPts = [];
  let highlightPts = [];
  let innerPts = [];

  for (let a = 0; a < 360; a += 10) {
    let radOuter = getPatchIrregularRadius(p, a, 1.0);
    let ox = p.cx + cos(a) * radOuter.rx;
    let oy = constrain(p.cy + sin(a) * radOuter.ry, 6, 384);
    outerPts.push([ox, oy]);

    // Top-left rim casts a crisp drop-shadow onto the recessed rose under-plaster
    if (a >= 160 && a <= 350) {
      shadowPts.push([ox + 2.2, oy + 2.5, 0.85]);
    }
    // Bottom-right rim catches crisp sunlight on the broken lime plaster thickness
    if (a >= 0 && a <= 165) {
      highlightPts.push([ox, oy, 0.9]);
    }

    let radInner = getPatchIrregularRadius(p, a + 8, 0.64);
    let ix = p.cx + cos(a) * radInner.rx;
    let iy = constrain(p.cy + sin(a) * radInner.ry, 10, 380);
    innerPts.push([ix, iy]);
  }

  // 1. Recessed Rose Under-Plaster Layer
  let rosePoly = new brush.Polygon(outerPts);
  rosePoly.wash(PAL.roseMid, 175);
  rosePoly.fill(PAL.roseDeep, 65, 0.08, 0.45);

  // 2. Deeper Recessed Mortar Bed for Exposed Venetian Red Bricks
  let brickBedPoly = new brush.Polygon(innerPts);
  brickBedPoly.wash(PAL.brickMortar, 210);

  // 3. Crisp Individual Venetian Red Bricks inside the inner pocket
  let minX = p.cx - p.brickRx * 1.3;
  let maxX = p.cx + p.brickRx * 1.3;
  let minY = p.cy - p.brickRy * 1.3;
  let maxY = p.cy + p.brickRy * 1.3;

  let brickH = 12;
  let brickW = 36;
  let rowCount = 0;

  for (let by = minY; by <= maxY; by += brickH + 3.5) {
    let stagger = (rowCount % 2) * (brickW * 0.5);
    for (let bx = minX - stagger; bx <= maxX; bx += brickW + 4) {
      let bcx = bx + brickW * 0.5;
      let bcy = by + brickH * 0.5;

      if (pointInPatch(bcx, bcy, p, 0.58)) {
        let bCol = random([PAL.venetianRed, PAL.venetianBright, PAL.roseDeep, "#96291a"]);
        let bPoly = new brush.Polygon([
          [bx + 1, by + 1],
          [bx + brickW - 1, by + 0.5],
          [bx + brickW - 0.5, by + brickH - 1],
          [bx + 0.5, by + brickH - 0.5]
        ]);
        bPoly.wash(bCol, 215);

        // Crisp dark top-left brick recess & warm bottom highlight
        brush.set("rotring", PAL.venetianDark, 0.35);
        brush.line(bx + 1, by + 1, bx + brickW - 1, by + 1);
        brush.line(bx + 1, by + 1, bx + 1, by + brickH - 1);

        brush.set("2H", PAL.brickMortar, 0.35);
        brush.line(bx + 1, by + brickH, bx + brickW, by + brickH);
      }
    }
    rowCount++;
  }

  // 4. Crisp 3D Peeling Plaster Rim (drop-shadow, sunlit bevel, and hairline cracks)
  if (shadowPts.length >= 2) {
    brush.set("rotring", PAL.inkDark, 0.68);
    brush.spline(shadowPts, 0.35);
  }
  if (highlightPts.length >= 2) {
    brush.set("cpencil", PAL.stoneLight, 0.95);
    brush.spline(highlightPts, 0.35);
  }

  // Crisp contour around outer peeling edge & inner brick pocket
  let closedOuter = [...outerPts, outerPts[0]];
  brush.set("rotring", PAL.ochreShadow, 0.42);
  brush.spline(closedOuter, 0.3);

  let closedInner = [...innerPts, innerPts[0]];
  brush.set("rotring", PAL.venetianDark, 0.45);
  brush.spline(closedInner, 0.3);

  // Fine plaster fracture lines radiating from the patch
  for (let k = 0; k < 4; k++) {
    let ang = random(360);
    let r = getPatchIrregularRadius(p, ang, 1.0);
    let sx = p.cx + cos(ang) * r.rx;
    let sy = p.cy + sin(ang) * r.ry;
    let crackPts = [[sx, sy, 0.7]];
    for (let s = 1; s <= 4; s++) {
      sx += cos(ang + random(-25, 25)) * random(7, 15);
      sy += sin(ang + random(-25, 25)) * random(7, 15);
      crackPts.push([sx, constrain(sy, 5, 384), 0.7 - s * 0.14]);
    }
    brush.set("rotring", PAL.ochreShadow, 0.28);
    brush.spline(crackPts, 0.3);
  }
}

function drawStoneWaterlineBase() {
  // Upper stone cornice lip (y = 386..398)
  let lipPoly = new brush.Polygon([
    [0, 386], [1200, 386], [1200, 398], [0, 398]
  ]);
  lipPoly.wash(PAL.stoneLight, 235);

  // Crisp shadow under the stone lip (y = 398..404)
  let underLipPoly = new brush.Polygon([
    [0, 398], [1200, 398], [1200, 404], [0, 404]
  ]);
  underLipPoly.wash(PAL.ochreShadow, 195);

  // Ashlar stone blocks (y = 404..424)
  let blockPoly = new brush.Polygon([
    [0, 404], [1200, 404], [1200, 425], [0, 425]
  ]);
  blockPoly.wash(PAL.stoneMid, 220);

  // Dark bottle-green & murky jade wet tidal algae band at the waterline (y = 420..436)
  let algaePoly = new brush.Polygon([
    [0, 420], [1200, 420], [1200, WATER_Y + 2], [0, WATER_Y + 2]
  ]);
  algaePoly.wash(PAL.bottleDark, 210);

  // Textured bottle-green moss & barnacle edge along y = 418..436
  for (let x = 0; x < 1200; x += 28) {
    let mossH = 12 + noise(x * 0.03) * 10;
    brush.set("charcoal", x % 56 === 0 ? PAL.bottleGreen : PAL.jadeDeep, 0.85);
    brush.line(x, WATER_Y - mossH, x + 22, WATER_Y);
  }

  // Crisp stone block joints & horizontal architectural rules
  brush.set("rotring", PAL.inkDark, 0.45);
  brush.line(0, 386, 1200, 386);
  brush.line(0, 398, 1200, 398);
  brush.line(0, WATER_Y, 1200, WATER_Y);

  const joints = [135, 315, 495, 685, 875, 1060];
  for (let jx of joints) {
    brush.set("rotring", PAL.inkDark, 0.42);
    brush.line(jx, 386, jx, 426);
    brush.set("cpencil", PAL.stoneLight, 0.5);
    brush.line(jx + 2, 387, jx + 2, 424);
  }
}

function drawWallCastShadows() {
