function drawLouveredShutter(x1, y1, x2, y2, tiltY, isAngledLight) {
  // Outer wooden shutter frame
  let framePoly = new brush.Polygon([
    [x1, y1],
    [x2, y1 + tiltY * 0.3],
    [x2, y2 + tiltY],
    [x1, y2]
  ]);
  framePoly.wash(isAngledLight ? PAL.bottleLight : PAL.bottleGreen, 235);

  let frameW = 12;
  let midY = (y1 + y2) * 0.52;

  // Upper and lower recessed louver bays
  const bays = [
    [y1 + frameW, midY - frameW * 0.6],
    [midY + frameW * 0.6, y2 - frameW]
  ];

  for (let bay of bays) {
    let by1 = bay[0];
    let by2 = bay[1];
    let bx1 = x1 + frameW;
    let bx2 = x2 - frameW;

    // Dark recessed bay interior
    let bayPoly = new brush.Polygon([
      [bx1, by1 + tiltY * 0.15],
      [bx2, by1 + tiltY * 0.45],
      [bx2, by2 + tiltY * 0.85],
      [bx1, by2 + tiltY * 0.15]
    ]);
    bayPoly.wash(PAL.bottleDark, 230);

    // Crisp individual louver slats
    let slatStep = 10.5;
    for (let sy = by1 + 4; sy < by2 - 3; sy += slatStep) {
      let t = (sy - y1) / max(1, y2 - y1);
      let syLeft = sy + tiltY * t * 0.15;
      let syRight = sy + tiltY * (0.3 + t * 0.7);

      // Sunlit top bevel of louver slat (murky jade highlight)
      brush.set("crisp_chisel", isAngledLight ? PAL.jadeLight : PAL.jadeMid, 0.52);
      brush.line(bx1 + 1, syLeft, bx2 - 1, syRight);

      // Bottle-green slat face
      brush.set("crisp_chisel", isAngledLight ? PAL.bottleLight : PAL.bottleGreen, 0.68);
      brush.line(bx1 + 1, syLeft + 2.5, bx2 - 1, syRight + 2.5);

      // Crisp dark under-slat shadow line
      brush.set("rotring", PAL.inkGreen, 0.48);
      brush.line(bx1, syLeft + 5.2, bx2, syRight + 5.2);
    }

    // Crisp inner molding outline around louver bay
    brush.set("rotring", PAL.inkGreen, 0.45);
    brush.line(bx1, by1 + tiltY * 0.15, bx2, by1 + tiltY * 0.45);
    brush.line(bx2, by1 + tiltY * 0.45, bx2, by2 + tiltY * 0.85);
    brush.line(bx2, by2 + tiltY * 0.85, bx1, by2 + tiltY * 0.15);
    brush.line(bx1, by2 + tiltY * 0.15, bx1, by1 + tiltY * 0.15);
  }

  // Sunlit vertical stile highlight & crisp outer ink border
  brush.set("cpencil", PAL.jadeLight, 0.65);
  brush.line(x1 + 2, y1 + 2, x1 + 2, y2 - 2);
  brush.line(x2 - frameW + 2, y1 + tiltY * 0.3 + 2, x2 - frameW + 2, y2 + tiltY - 2);

  brush.set("rotring", PAL.inkDark, 0.55);
  brush.line(x1, y1, x2, y1 + tiltY * 0.3);
  brush.line(x2, y1 + tiltY * 0.3, x2, y2 + tiltY);
  brush.line(x2, y2 + tiltY, x1, y2);
  brush.line(x1, y2, x1, y1);

  // Wrought-iron strap hinges & shutter hardware
  for (let hy of [y1 + 38, y2 - 42]) {
    brush.set("rotring", PAL.inkDark, 0.9);
    brush.line(x1, hy, x1 + 24, hy + tiltY * 0.08);
    brush.circle(x1 + 20, hy + tiltY * 0.08, 2.2);
  }
}

