// ============================================================================
// 4. STRIPED BARBER-POLE MOORING POST (x = 206..284, y = 8..438)
// ============================================================================

function drawMooringPost() {
  let px1 = 206, px2 = 284;
  let pWidth = px2 - px1;
  let pCenter = (px1 + px2) * 0.5;
  let pyTop = 44;
  let pyBot = WATER_Y + 2;

  // --- 4A. Turned Wooden Finial Cap at the Top (y = 10..46) ---
  let capPts = [];
  for (let a = 180; a <= 360; a += 15) {
    let cx = pCenter + cos(a) * (pWidth * 0.48);
    let cy = 34 + sin(a) * 24;
    capPts.push([cx, cy]);
  }
  capPts.push([px2, pyTop + 4]);
  capPts.push([px1, pyTop + 4]);
  let capPoly = new brush.Polygon(capPts);
  capPoly.wash(PAL.poleCream, 240);

  // Shaded right side of wooden finial cap
  let capShadow = new brush.Polygon([
    [pCenter + 4, 11],
    [px2 - 4, 24],
    [px2, pyTop + 4],
    [pCenter + 6, pyTop + 4]
  ]);
  capShadow.wash(PAL.poleShadow, 175);

  // --- 4B. Cylindrical Diagonal Barber-Pole Stripes ---
  // We slice the cylinder vertically into narrow 3D longitudinal strips and spiral bands
  // so every red and white stripe curves naturally across the rounded timber post
  let numBands = 14;
  let bandH = 45; // each stripe is 45px tall (period = 90px)

  for (let b = -2; b < numBands; b++) {
    let isRed = ((b % 2) + 2) % 2 === 0;
    let yStartLeft = pyTop + b * bandH;

    // Subdivide across the cylinder width into 4 lighting zones:
    // 0: Left turning edge (u = -1..-0.65)
    // 1: Sunlit highlight face (u = -0.65..-0.05)
    // 2: Mid-tone face (u = -0.05..0.45)
    // 3: Core shadow & right reflected rim (u = 0.45..1.0)
    const zones = [
      { u1: -1.0, u2: -0.62, zoneIdx: 0 },
      { u1: -0.62, u2: -0.05, zoneIdx: 1 },
      { u1: -0.05, u2: 0.45, zoneIdx: 2 },
      { u1: 0.45, u2: 1.0, zoneIdx: 3 }
    ];

    for (let z of zones) {
      let polyPts = [];
      let steps = 4;

      // Top edge of this spiral band segment
      for (let s = 0; s <= steps; s++) {
        let u = lerp(z.u1, z.u2, s / steps);
        let x = pCenter + u * (pWidth * 0.5);
        let cylCurve = sqrt(max(0, 1 - u * u)) * 16;
        let y = yStartLeft - (x - px1) * 0.68 + cylCurve;
        polyPts.push([x, constrain(y, pyTop, pyBot)]);
      }
      // Bottom edge of this spiral band segment
      for (let s = steps; s >= 0; s--) {
        let u = lerp(z.u1, z.u2, s / steps);
        let x = pCenter + u * (pWidth * 0.5);
        let cylCurve = sqrt(max(0, 1 - u * u)) * 16;
        let y = yStartLeft + bandH - (x - px1) * 0.68 + cylCurve;
        polyPts.push([x, constrain(y, pyTop, pyBot)]);
      }

      // Check if band is within vertical range of the post
      let minY = 9999, maxY = -9999;
      for (let pt of polyPts) {
        if (pt[1] < minY) minY = pt[1];
        if (pt[1] > maxY) maxY = pt[1];
      }
      if (maxY - minY < 2) continue;

      let zCol;
      if (isRed) {
        if (z.zoneIdx === 0) zCol = PAL.venetianRed;
        else if (z.zoneIdx === 1) zCol = PAL.venetianBright;
        else if (z.zoneIdx === 2) zCol = PAL.venetianRed;
        else zCol = PAL.venetianDark;
      } else {
        if (z.zoneIdx === 0) zCol = PAL.poleCream;
        else if (z.zoneIdx === 1) zCol = PAL.poleWhite;
        else if (z.zoneIdx === 2) zCol = PAL.poleCream;
        else zCol = PAL.poleShadow;
      }

      let segPoly = new brush.Polygon(polyPts);
      segPoly.wash(zCol, 238);
    }

    // Crisp weathered boundary line between the red and white spiral stripes
    let stripeEdgePts = [];
    for (let s = 0; s <= 10; s++) {
      let u = lerp(-1, 1, s / 10);
      let x = pCenter + u * (pWidth * 0.5);
      let cylCurve = sqrt(max(0, 1 - u * u)) * 16;
      let y = yStartLeft - (x - px1) * 0.68 + cylCurve + (noise(s * 0.4, b * 2) - 0.5) * 2.2;
      if (y >= pyTop + 2 && y <= pyBot - 2) {
        stripeEdgePts.push([x, y, 0.65]);
      }
    }
    if (stripeEdgePts.length >= 3) {
      brush.set("rotring", isRed ? PAL.venetianDark : PAL.poleShadow, 0.42);
      brush.spline(stripeEdgePts, 0.35);

      // Peeling paint highlight lip along the stripe border
      brush.set("cpencil", PAL.poleWhite, 0.55);
      brush.spline(stripeEdgePts, 0.35);
    }
  }

  // --- 4C. Cylindrical Highlight Glaze, Wood Grain Fissures & Flaking Paint ---
  // Bright sunlit highlight strip down left-center of post (x ~ 224..236)
  brush.set("lifted_light", PAL.poleWhite, 0.9);
  brush.line(227, pyTop + 6, 227, pyBot - 28);

  // Reflected jade/ochre water rim light along the far right shadow edge (x ~ 280..283)
  brush.set("cpencil", PAL.jadeMid, 0.75);
  brush.line(px2 - 2.5, pyTop + 10, px2 - 2.5, pyBot - 15);

  // Deep vertical timber drying cracks splitting the painted wood
  const woodCracks = [
    { x: 222, y1: 68, y2: 195 },
    { x: 239, y1: 135, y2: 345 },
    { x: 256, y1: 48, y2: 245 },
    { x: 266, y1: 210, y2: 412 },
    { x: 215, y1: 260, y2: 395 }
  ];
  for (let cr of woodCracks) {
    let pts = [];
    let highlightPts = [];
    for (let y = cr.y1; y <= cr.y2; y += 16) {
      let wx = cr.x + (noise(cr.x, y * 0.03) - 0.5) * 3.2;
      let press = sin( map(y, cr.y1, cr.y2, 10, 170) );
      pts.push([wx, y, press * 0.85]);
      highlightPts.push([wx + 1.6, y, press * 0.7]);
    }
    brush.set("rotring", PAL.inkDark, 0.52);
    brush.spline(pts, 0.3);
    brush.set("cpencil", PAL.poleWhite, 0.45);
    brush.spline(highlightPts, 0.3);
  }

  // --- 4D. Rusted Wrought-Iron Mooring Collar & Ring at y ~ 278 ---
  let collarPts = [];
  for (let s = 0; s <= 8; s++) {
    let u = lerp(-1, 1, s / 8);
    let x = pCenter + u * (pWidth * 0.52);
    let y = 274 + sqrt(max(0, 1 - u * u)) * 7;
    collarPts.push([x, y]);
  }
  for (let s = 8; s >= 0; s--) {
    let u = lerp(-1, 1, s / 8);
    let x = pCenter + u * (pWidth * 0.52);
    let y = 283 + sqrt(max(0, 1 - u * u)) * 7;
    collarPts.push([x, y]);
  }
  let collarPoly = new brush.Polygon(collarPts);
  collarPoly.wash(PAL.inkDark, 235);

  // Hanging iron mooring ring on the front-left of the collar
  brush.set("rotring", PAL.inkDark, 1.35);
  brush.circle(232, 296, 13, 0.15);
  brush.set("cpencil", PAL.ochreLight, 0.5);
  brush.arc(232, 296, 13, 200, 320);

  // --- 4E. Wet Bottle-Green Moss & Tidal Stain at the Base of the Post (y = 398..438) ---
  let mossPts = [[px1, pyBot], [px2, pyBot]];
  for (let s = 8; s >= 0; s--) {
    let x = lerp(px1, px2, s / 8);
    let y = 404 + sin(s * 50) * 6 + noise(s * 0.8) * 10;
    mossPts.push([x, y]);
  }
  let mossPoly = new brush.Polygon(mossPts);
  mossPoly.wash(PAL.bottleDark, 215);
  mossPoly.fill(PAL.bottleGreen, 90, 0.18, 0.5);

  // Crisp outer contours of the mooring post
  brush.set("rotring", PAL.inkDark, 0.62);
  brush.line(px1, pyTop, px1, pyBot);
  brush.line(px2, pyTop, px2, pyBot);

  let capOutline = [];
  for (let a = 180; a <= 360; a += 15) {
    capOutline.push([pCenter + cos(a) * (pWidth * 0.48), 34 + sin(a) * 24, 0.7]);
  }
  brush.spline(capOutline, 0.45);
}

