function drawWaterlineFinishing() {
  // Crisp dark meniscus & lapping wavelets right along WATER_Y (436)
  for (let x = 5; x < 1195; x += random(28, 62)) {
    let xEnd = min(1196, x + random(24, 54));
    let pts = [];
    for (let sx = x; sx <= xEnd; sx += 8) {
      let wy = WATER_Y + sin(sx * 12) * 1.6 + (noise(sx * 0.04) - 0.5) * 2.5;
      pts.push([sx, wy, 0.8]);
    }
    if (pts.length >= 2) {
      brush.set("rotring", PAL.inkGreen, 0.48);
      brush.spline(pts, 0.45);
    }

    // Lifted bright meniscus highlight right beside the mooring post and stone base
    if (random() < 0.55 || (x > 190 && x < 300)) {
      let hPts = pts.map(p => [p[0], p[1] + 2.2, 0.7]);
      brush.set("cpencil", PAL.poleWhite, 0.65);
      brush.spline(hPts, 0.45);
    }
  }

  // Elliptical concentric ripple rings radiating gently around the base of the mooring post
  const ringRadii = [
    [48, 5.5],
    [68, 8.5],
    [94, 12.5],
    [126, 17.5]
  ];
  for (let r of ringRadii) {
    let rx = r[0], ry = r[1];
    let ringPts = [];
    for (let a = 8; a <= 172; a += 10) {
      let x = 245 + cos(a) * rx + sin(a * 5) * 2.2;
      let y = WATER_Y + 3 + sin(a) * ry + cos(a * 6) * 1.1;
      ringPts.push([x, y, sin(a) * 0.75 + 0.2]);
    }
    brush.set("rotring", PAL.inkDark, 0.34);
    brush.spline(ringPts, 0.5);

    // Lifted light glint on the front of the concentric post ripple
    let glintPts = ringPts.slice(4, 13).map(pt => [pt[0], pt[1] - 1.5, 0.7]);
    if (glintPts.length >= 3) {
      brush.set("lifted_light", PAL.poleWhite, 0.55);
      brush.spline(glintPts, 0.5);
    }
  }
}

