// ============================================================================
// GEOMETRY BUILDER: CANONICAL LOTUS ROOT SLICE (BILATERALLY SYMMETRIC)
// ============================================================================

function buildCanonicalSlice() {
  // 9 main chambers arranged symmetrically across the radial axis (theta = 0)
  const mainDefs = [
    { angle: 0,    rIn: 38, rOut: 115, wIn: 6.8, wOut: 11.8, dimple: 0.065 },
    { angle: 38.5, rIn: 38, rOut: 114, wIn: 6.6, wOut: 11.4, dimple: 0.060 },
    { angle: -38.5,rIn: 38, rOut: 114, wIn: 6.6, wOut: 11.4, dimple: 0.060 },
    { angle: 77.5, rIn: 37, rOut: 113, wIn: 6.5, wOut: 11.2, dimple: 0.058 },
    { angle: -77.5,rIn: 37, rOut: 113, wIn: 6.5, wOut: 11.2, dimple: 0.058 },
    { angle: 117.5,rIn: 36, rOut: 111, wIn: 6.5, wOut: 11.4, dimple: 0.060 },
    { angle: -117.5,rIn:36, rOut: 111, wIn: 6.5, wOut: 11.4, dimple: 0.060 },
    { angle: 159.0,rIn: 35, rOut: 109, wIn: 6.8, wOut: 11.8, dimple: 0.065 },
    { angle: -159.0,rIn:35, rOut: 109, wIn: 6.8, wOut: 11.8, dimple: 0.065 }
  ];

  // 9 interstitial node angles (septa between main chambers)
  const nodeAngles = [19.2, -19.2, 58.0, -58.0, 97.5, -97.5, 138.2, -138.2, 180.0];

  // 9 secondary peripheral chambers nestled in the outer septa
  const subDefs = nodeAngles.map((ang) => {
    const isBack = abs(ang) > 150;
    return {
      angle: ang,
      rIn: isBack ? 109 : 112,
      rOut: isBack ? 129 : 133,
      wIn: 2.3,
      wOut: 4.1,
      dimple: 0.03
    };
  });

  // 18 tiny peripheral vascular pores near the outer skin
  const tinyPores = [];
  for (let i = 0; i < mainDefs.length; i++) {
    const a = mainDefs[i].angle;
    for (let side of [-1, 1]) {
      const poreAng = a + side * 7.2;
      const poreR = (abs(a) > 130 ? 135 : 138);
      tinyPores.push(makeSmallPore(poreAng, poreR, 2.7, 14));
    }
  }
  // Additional 9 tiny inner-ring pores tucked between inner apices of main holes
  for (let i = 0; i < nodeAngles.length; i++) {
    const a = nodeAngles[i];
    tinyPores.push(makeSmallPore(a, 29.5, 2.2, 12));
  }

  // Outer contour function with realistic node indentations over the 9 septa
  function outerRadiusAt(theta, offset = 0) {
    let r = SLICE_R + offset;
    // Slight natural elliptical poise
    r += 1.6 * cos(theta) - 0.8 * cos(2 * theta);
    // Subtle indentations at the 9 vascular nodes
    for (let i = 0; i < nodeAngles.length; i++) {
      let d = angularDiff(theta, nodeAngles[i]);
      if (abs(d) < 14) {
        r -= 3.4 * pow(cos((d / 14) * 90), 2.2);
      }
    }
    // Gentle outward swell over each main chamber arch
    for (let i = 0; i < mainDefs.length; i++) {
      let d = angularDiff(theta, mainDefs[i].angle);
      if (abs(d) < 16) {
        r += 1.8 * pow(cos((d / 16) * 90), 1.8);
      }
    }
    // High-frequency symmetric epidermal micro-undulation
    r += 0.45 * cos(18 * theta) + 0.25 * cos(27 * theta);
    return r;
  }

  function makeOuterContour(numPts, offset = 0) {
    const pts = [];
    for (let i = 0; i < numPts; i++) {
      const th = (i / numPts) * 360;
      const r = outerRadiusAt(th, offset);
      pts.push([r * cos(th), r * sin(th)]);
    }
    return pts;
  }

  // Central chamber contour (scalloped 9-lobed central canal)
  function makeCenterChamber(numPts = 36, scaleR = 1.0) {
    const pts = [];
    for (let i = 0; i < numPts; i++) {
      const th = (i / numPts) * 360;
      let r = (17.2 + 0.95 * cos(9 * th) + 0.4 * cos(2 * th)) * scaleR;
      pts.push([r * cos(th), r * sin(th)]);
    }
    return {
      pts,
      cx: 0,
      cy: 0,
      angle: 0,
      isCenter: true,
      wallDepth: 0.20
    };
  }

  // Parametric lotus canal generator (teardrop-squircle with outer vascular dimple)
  function makeCanalChamber(def, numPts = 36, expandPx = 0) {
    const pts = [];
    const rIn = def.rIn - expandPx;
    const rOut = def.rOut + expandPx;
    const rMid = 0.5 * (rIn + rOut);
    const rHalf = 0.5 * (rOut - rIn);
    const expandDeg = (expandPx / rMid) * (180 / PI);
    const wIn = def.wIn + expandDeg;
    const wOut = def.wOut + expandDeg;

    let sumX = 0;
    let sumY = 0;

    for (let i = 0; i < numPts; i++) {
      const t = (i / numPts) * 360;
      const u = cos(t); // -1 at inner apex, +1 at outer arch
      const v = sin(t); // -1..+1 transverse across canal

      let uMod;
      if (u >= 0) {
        const dimpleFactor = 1.0 - def.dimple * pow(1.0 - v * v, 2.2);
        uMod = pow(u, 0.72) * dimpleFactor;
      } else {
        uMod = -pow(-u, 0.90);
      }

      const r = rMid + rHalf * uMod;
      const wHalf = lerp(wIn, wOut, 0.54 + 0.46 * u);
      const vExp = u >= 0 ? lerp(0.88, 0.72, u) : lerp(0.88, 0.95, -u);
      const vMod = (v >= 0 ? 1 : -1) * pow(abs(v), vExp);
      const th = def.angle + wHalf * vMod;

      const x = r * cos(th);
      const y = r * sin(th);
      pts.push([x, y]);
      sumX += x;
      sumY += y;
    }

    return {
      pts,
      cx: sumX / numPts,
      cy: sumY / numPts,
      angle: def.angle,
      rMid,
      def,
      isCenter: false,
      wallDepth: rHalf > 20 ? 0.19 : 0.24
    };
  }

  function makeSmallPore(angle, rCenter, radius, numPts = 14) {
    const pts = [];
    const cx = rCenter * cos(angle);
    const cy = rCenter * sin(angle);
    const ux = cos(angle);
    const uy = sin(angle);
    const vx = -sin(angle);
    const vy = cos(angle);
    for (let i = 0; i < numPts; i++) {
      const t = (i / numPts) * 360;
      const lr = radius * (0.92 + 0.12 * cos(2 * t));
      const x = cx + lr * (0.88 * cos(t) * ux + 1.08 * sin(t) * vx);
      const y = cy + lr * (0.88 * cos(t) * uy + 1.08 * sin(t) * vy);
      pts.push([x, y]);
    }
    return { pts, cx, cy, angle, radius, wallDepth: 0.30 };
  }

  const mainChambers = mainDefs.map((d) => makeCanalChamber(d, 38, 0));
  const mainChambersBevel = mainDefs.map((d) => makeCanalChamber(d, 34, 4.2));
  const subChambers = subDefs.map((d) => makeCanalChamber(d, 26, 0));
  const subChambersBevel = subDefs.map((d) => makeCanalChamber(d, 22, 3.0));
  const centerChamber = makeCenterChamber(36, 1.0);
  const centerChamberBevel = makeCenterChamber(32, 1.24);

  // Precompute watercolor glaze cushions (starchy flesh zones between holes)
  const septumPatches = [];
  for (let i = 0; i < nodeAngles.length; i++) {
    const ang = nodeAngles[i];
    septumPatches.push(makeRadialPatch(ang, 34, 110, 4.8, 7.5, 20));
  }

  const outerRimPatches = [];
  for (let i = 0; i < mainDefs.length; i++) {
    const ang = mainDefs[i].angle;
    outerRimPatches.push(makeRadialPatch(ang, 116, 152, 11.5, 13.5, 20));
  }

  const innerHeartPatches = [];
  for (let i = 0; i < mainDefs.length; i++) {
    const ang = mainDefs[i].angle + 20;
    innerHeartPatches.push(makeRadialPatch(ang, 19, 44, 14, 16, 16));
  }

  return {
    outerRadiusAt,
    makeOuterContour,
    outerContour: makeOuterContour(84, 0),
    innerSkinContour: makeOuterContour(84, -2.6),
    midFleshContour: makeOuterContour(72, -6.5),
    innerFleshContour: makeOuterContour(64, -22),
    coreFleshContour: makeOuterContour(48, -112),
    mainDefs,
    nodeAngles,
    mainChambers,
    mainChambersBevel,
    subChambers,
    subChambersBevel,
    centerChamber,
    centerChamberBevel,
    tinyPores,
    septumPatches,
    outerRimPatches,
    innerHeartPatches
  };
}

function makeRadialPatch(angle, rIn, rOut, wIn, wOut, numPts = 20) {
  const pts = [];
  const rMid = 0.5 * (rIn + rOut);
  const rHalf = 0.5 * (rOut - rIn);
  for (let i = 0; i < numPts; i++) {
    const t = (i / numPts) * 360;
    const u = cos(t);
    const v = sin(t);
    const r = rMid + rHalf * u;
    const w = lerp(wIn, wOut, 0.5 + 0.5 * u);
    const th = angle + w * v;
    pts.push([r * cos(th), r * sin(th)]);
  }
  return pts;
}

function angularDiff(a, b) {
  let d = (a - b) % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

// ============================================================================
// COORDINATE TRANSFORMS: LOCAL SLICE SPACE -> WORLD CANVAS SPACE
// ============================================================================

function getSliceTransform(s) {
  const phi = -90 + s * 72;
  const ux = cos(phi);
  const uy = sin(phi);
  const vx = -sin(phi);
  const vy = cos(phi);
  const sx = CX + SLICE_DIST * ux;
  const sy = CY + SLICE_DIST * uy;
  return { phi, ux, uy, vx, vy, sx, sy };
}

function localToWorld(tf, lx, ly, dxWorld = 0, dyWorld = 0) {
  return [
    tf.sx + lx * tf.ux + ly * tf.vx + dxWorld,
    tf.sy + lx * tf.uy + ly * tf.vy + dyWorld
  ];
}

function transformPts(s, pts, dxWorld = 0, dyWorld = 0, scale = 1.0) {
  const tf = getSliceTransform(s);
  const out = new Array(pts.length);
  for (let i = 0; i < pts.length; i++) {
    const lx = pts[i][0] * scale;
    const ly = pts[i][1] * scale;
    out[i] = [
      tf.sx + lx * tf.ux + ly * tf.vx + dxWorld,
      tf.sy + lx * tf.uy + ly * tf.vy + dyWorld
    ];
  }
  return out;
}

function drawPolyShape(pts, curvature = 0.2) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ============================================================================
// 1. GLOSSY BLACK LACQUER FIELD (ROIRO-URUSHI)
// ============================================================================

function drawLacquerField() {
  background("#07080d");

  brush.noStroke();
  brush.noFill();

  // Deep twilight obsidian platter vignette
  const platterRadii = [575, 535, 495, 440, 360];
  const platterColors = ["#0a0c14", "#0d101b", "#101422", "#121726", "#0d111c"];
  for (let i = 0; i < platterRadii.length; i++) {
    brush.wash(platterColors[i], 38);
    brush.circle(CX, CY, platterRadii[i], 0.02);
  }

  // Diagonal glossy specular reflection band across the black lacquer
  const sheenBands = [
    { offset: -220, w: 180, col: "#111624", op: 22 },
    { offset: -90,  w: 240, col: "#161d2e", op: 28 },
    { offset: -20,  w: 140, col: "#1d2538", op: 26 },
    { offset: 40,   w: 95,  col: "#232c42", op: 20 },
    { offset: 160,  w: 210, col: "#121726", op: 22 },
    { offset: 340,  w: 190, col: "#110c10", op: 25 }
  ];

  const cosA = cos(-38);
  const sinA = sin(-38);
  const nx = -sinA;
  const ny = cosA;

  for (let b of sheenBands) {
    const bx = CX + b.offset * nx;
    const by = CY + b.offset * ny;
    const L = 860;
    const W = b.w;
    const poly = [
      [bx - L * cosA - W * nx, by - L * sinA - W * ny],
      [bx + L * cosA - W * nx, by + L * sinA - W * ny],
      [bx + L * cosA + W * nx, by + L * sinA + W * ny],
      [bx - L * cosA + W * nx, by - L * sinA + W * ny]
    ];
    brush.wash(b.col, b.op);
    drawPolyShape(poly, 0.05);
  }

  // Fine hand-polished urushi grain lines along the glossy reflection
  brush.noWash();
  brush.noFill();
  for (let i = 0; i < 68; i++) {
    const off = random(-480, 480);
    const span = random(240, 680);
    const bx = CX + off * nx;
    const by = CY + off * ny;
    const isSpec = abs(off + 25) < 160;
    const col = isSpec ? "#263046" : "#131723";
    brush.set("lacquer_sheen", col, isSpec ? 0.55 : 0.35);
    brush.line(
      bx - span * cosA,
      by - span * sinA,
      bx + span * cosA,
      by + span * sinA
    );
  }
}

// ============================================================================
// 2. SUBMERGED MIRROR REFLECTIONS & CAST SHADOWS IN THE LACQUER
// ============================================================================

function drawLacquerReflectionsAndShadows() {
  brush.noStroke();
  brush.noFill();

  // Subtle submerged mirror reflection of the 5 pale slices in the dark lacquer
  brush.wash("#1b2230", 34);
  for (let s = 0; s < NUM_SLICES; s++) {
    const reflOuter = transformPts(s, canonicalSlice.outerContour, 9, 13, 1.01);
    drawPolyShape(reflOuter, 0.2);
  }

  brush.wash("#252e3f", 24);
  for (let s = 0; s < NUM_SLICES; s++) {
    const reflMid = transformPts(s, canonicalSlice.innerFleshContour, 10, 14, 0.98);
    drawPolyShape(reflMid, 0.2);
  }

  // Cut out the reflected holes in the mirror image
  brush.wash("#080a10", 52);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let ch of canonicalSlice.mainChambers) {
      drawPolyShape(transformPts(s, ch.pts, 9, 13, 1.0), 0.2);
    }
    drawPolyShape(transformPts(s, canonicalSlice.centerChamber.pts, 9, 13, 1.0), 0.2);
  }

  // Multi-step ambient occlusion drop shadow anchoring each slice to the lacquer
  const shadowPasses = [
    { dx: 5.5, dy: 7.5, scale: 1.022, col: "#020205", op: 110 },
    { dx: 3.2, dy: 4.5, scale: 1.012, col: "#010103", op: 165 },
    { dx: 1.4, dy: 2.0, scale: 1.005, col: "#000002", op: 210 }
  ];

  for (let p of shadowPasses) {
    brush.wash(p.col, p.op);
    for (let s = 0; s < NUM_SLICES; s++) {
      const shPts = transformPts(s, canonicalSlice.outerContour, p.dx, p.dy, p.scale);
      drawPolyShape(shPts, 0.2);
    }
  }
  brush.noWash();
}

// ============================================================================
// 3. 3D OUTER SKIN BEVEL OF EACH SLICE
// ============================================================================

function drawSlicesOuterBevel() {
  brush.noStroke();
  brush.noFill();

  // Deep umber-taupe outer epidermis visible along the 3D thickness edge
  brush.wash("#2a1f1e", 245);
  for (let s = 0; s < NUM_SLICES; s++) {
    const bevelOuter = transformPts(s, canonicalSlice.outerContour, 1.8, 2.6, 1.018);
    drawPolyShape(bevelOuter, 0.2);
  }

  // Warm oxidized bronze-taupe skin rim
  brush.wash("#4d3b36", 225);
  for (let s = 0; s < NUM_SLICES; s++) {
    const skinRim = transformPts(s, canonicalSlice.outerContour, 0.7, 1.0, 1.009);
    drawPolyShape(skinRim, 0.2);
  }

  brush.noWash();
}

// ============================================================================
// 4. OPAQUE STARCHY BASE UNDERPAINTING
// ============================================================================

function drawSlicesOpaqueBase() {
  brush.noStroke();
  brush.noFill();

  // Layer 4A: Outer translucent twilight celadon-taupe flesh edge
  brush.wash("#758380", 240);
  for (let s = 0; s < NUM_SLICES; s++) {
    drawPolyShape(transformPts(s, canonicalSlice.outerContour), 0.2);
  }

  // Layer 4B: Sub-epidermal pale celadon flesh
  brush.wash("#9eb0a8", 235);
  for (let s = 0; s < NUM_SLICES; s++) {
    drawPolyShape(transformPts(s, canonicalSlice.innerSkinContour), 0.2);
  }

  // Layer 4C: Main starchy celadon-ivory body
  brush.wash("#c4d1c9", 230);
  for (let s = 0; s < NUM_SLICES; s++) {
    drawPolyShape(transformPts(s, canonicalSlice.midFleshContour), 0.2);
  }

  // Layer 4D: Dense creamy pearl-ivory interior ring
  brush.wash("#dde3da", 215);
  for (let s = 0; s < NUM_SLICES; s++) {
    drawPolyShape(transformPts(s, canonicalSlice.innerFleshContour), 0.2);
  }

  // Layer 4E: Warm ivory starchy bridges along the septa and central ring
  brush.wash("#eae9dd", 195);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let patch of canonicalSlice.septumPatches) {
      drawPolyShape(transformPts(s, patch), 0.25);
    }
    for (let patch of canonicalSlice.innerHeartPatches) {
      drawPolyShape(transformPts(s, patch), 0.25);
    }
  }

  brush.noWash();
}

// ============================================================================
// 5. LAYERED TRANSPARENT WATERCOLOR GLAZES (BATCHED BY COLOR)
// ============================================================================

function drawSlicesWatercolorGlazes() {
  brush.noStroke();
  brush.noWash();

  // Batch 1: Pale celadon-jade watercolor wash across outer rim cushions
  brush.fill("#8fa89f", 58);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.35);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let k = 0; k < canonicalSlice.outerRimPatches.length; k += 2) {
      drawPolyShape(transformPts(s, canonicalSlice.outerRimPatches[k]), 0.25);
    }
  }

  // Batch 2: Dusky twilight slate-lavender shadow glaze in alternate outer arches
  brush.fill("#6f7387", 48);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.6, 0.4);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let k = 1; k < canonicalSlice.outerRimPatches.length; k += 2) {
      drawPolyShape(transformPts(s, canonicalSlice.outerRimPatches[k]), 0.25);
    }
  }

  // Batch 3: Translucent watery celadon subsurface scattering along septum bridges
  brush.fill("#748c89", 52);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.5, 0.3);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let k = 0; k < canonicalSlice.septumPatches.length; k += 2) {
      drawPolyShape(transformPts(s, canonicalSlice.septumPatches[k]), 0.25);
    }
  }

  // Batch 4: Warm oxidized lotus starch glaze (sepia-mauve twilight undertone)
  brush.fill("#9c8982", 44);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.55, 0.38);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let k = 1; k < canonicalSlice.septumPatches.length; k += 2) {
      drawPolyShape(transformPts(s, canonicalSlice.septumPatches[k]), 0.25);
    }
    drawPolyShape(transformPts(s, canonicalSlice.coreFleshContour), 0.25);
  }

  // Batch 5: Luminous bone-ivory starchy crown highlights around the heart
  brush.fill("#f6f4e8", 72);
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.45, 0.25);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let patch of canonicalSlice.innerHeartPatches) {
      drawPolyShape(transformPts(s, patch), 0.25);
    }
  }

  brush.noFill();
}

// ============================================================================
// 6. INTERNAL STARCHY FIBRES, RADIAL STRIATIONS & CELLULAR GRAIN
// ============================================================================

function drawSlicesStarchTexture() {
  brush.noFill();
  brush.noWash();

  for (let s = 0; s < NUM_SLICES; s++) {
    const tf = getSliceTransform(s);

    // A. Radial vascular striations along the 9 septum bridges
    for (let i = 0; i < canonicalSlice.nodeAngles.length; i++) {
      const baseAng = canonicalSlice.nodeAngles[i];
      for (let j = -2; j <= 2; j++) {
        const ang = baseAng + j * 1.45;
        const rStart = 21 + abs(j) * 2.5;
        const rEnd = 107 - abs(j) * 1.5;
        const rMid = 0.5 * (rStart + rEnd);
        const wobble = (j % 2 === 0 ? 0.8 : -0.8);

        const p1 = localToWorld(tf, rStart * cos(ang), rStart * sin(ang));
        const p2 = localToWorld(tf, rMid * cos(ang + wobble), rMid * sin(ang + wobble));
        const p3 = localToWorld(tf, rEnd * cos(ang), rEnd * sin(ang));

        const col = j === 0 ? "#8a9994" : (abs(j) === 1 ? "#f4f3e8" : "#9baba4");
        const wt = j === 0 ? 0.32 : 0.26;
        brush.set("2H", col, wt);
        brush.spline([
          [p1[0], p1[1], 0.4],
          [p2[0], p2[1], 0.9],
          [p3[0], p3[1], 0.4]
        ], 0.35);
      }
    }

    // B. Delicate concentric starchy grain arcs in the outer rim zone (r = 118..153)
    for (let i = 0; i < canonicalSlice.mainDefs.length; i++) {
      const mAng = canonicalSlice.mainDefs[i].angle;
      for (let ring = 0; ring < 5; ring++) {
        const r = 119 + ring * 6.8;
        const span = 12.5 - ring * 0.6;
        const pA = localToWorld(tf, r * cos(mAng - span), r * sin(mAng - span));
        const pB = localToWorld(tf, (r + 1.2) * cos(mAng), (r + 1.2) * sin(mAng));
        const pC = localToWorld(tf, r * cos(mAng + span), r * sin(mAng + span));

        const isLight = ring === 1 || ring === 2;
        brush.set("2H", isLight ? "#f2f1e6" : "#7e8e8a", isLight ? 0.32 : 0.25);
        brush.spline([
          [pA[0], pA[1], 0.3],
          [pB[0], pB[1], 0.85],
          [pC[0], pC[1], 0.3]
        ], 0.4);
      }
    }

    // C. Cellular starchy stipple & translucent pores
    brush.set("starch_grain", "#f7f6ec", 0.55);
    for (let i = 0; i < canonicalSlice.nodeAngles.length; i++) {
      const ang = canonicalSlice.nodeAngles[i];
      const pA = localToWorld(tf, 32 * cos(ang), 32 * sin(ang));
      const pB = localToWorld(tf, 102 * cos(ang), 102 * sin(ang));
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    brush.set("starch_grain", "#687877", 0.48);
    for (let i = 0; i < canonicalSlice.mainDefs.length; i++) {
      const ang = canonicalSlice.mainDefs[i].angle;
      const pA = localToWorld(tf, 122 * cos(ang - 9), 122 * sin(ang - 9));
      const pB = localToWorld(tf, 146 * cos(ang + 9), 146 * sin(ang + 9));
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }
}

// ============================================================================
// 7. HOLLOW CHAMBERS: RECESSED BEVELS, 3D INNER FLESH WALLS & LACQUER DEPTH
// ============================================================================

function buildChamberWallLayers(s, ch) {
  const tf = getSliceTransform(s);
  const wPts = transformPts(s, ch.pts);
  const cWorld = localToWorld(tf, ch.cx, ch.cy);

  // Light direction combines gallery top-left light (-0.65, -0.76) with radial crest balance
  const gLightX = -0.62 * 0.55 - tf.ux * 0.45;
  const gLightY = -0.78 * 0.55 - tf.uy * 0.45;
  const gLen = sqrt(gLightX * gLightX + gLightY * gLightY) || 1;
  const lxDir = gLightX / gLen;
  const lyDir = gLightY / gLen;

  const midWallPts = [];
  const deepWallPts = [];
  const lacquerPts = [];
  const innerShadowPts = [];

  for (let i = 0; i < wPts.length; i++) {
    const px = wPts[i][0];
    const py = wPts[i][1];
    const dx = px - cWorld[0];
    const dy = py - cWorld[1];
    const dist = sqrt(dx * dx + dy * dy) || 1;
    const ux = dx / dist;
    const uy = dy / dist;

    // Side of the hole closest to the light source reveals the 3D inner cylindrical wall
    const align = ux * lxDir + uy * lyDir;
    const wFactor = pow(max(0, 0.38 + 0.62 * align), 1.35);
    const fTotal = 0.045 + ch.wallDepth * wFactor;

    const fMid = 0.38 * fTotal;
    const fDeep = 0.76 * fTotal;
    const fBot = fTotal;
    const fShadow = min(0.85, fTotal + 0.065 + 0.05 * max(0, align));

    midWallPts.push([lerp(px, cWorld[0], fMid), lerp(py, cWorld[1], fMid)]);
    deepWallPts.push([lerp(px, cWorld[0], fDeep), lerp(py, cWorld[1], fDeep)]);
    lacquerPts.push([lerp(px, cWorld[0], fBot), lerp(py, cWorld[1], fBot)]);
    innerShadowPts.push([lerp(px, cWorld[0], fShadow), lerp(py, cWorld[1], fShadow)]);
  }

  return { wPts, cWorld, midWallPts, deepWallPts, lacquerPts, innerShadowPts, lxDir, lyDir };
}

function drawSlicesHollowChambers() {
  brush.noStroke();
  brush.noFill();

  // Pass 7A: Soft recessed moisture bevel around every chamber on the top surface
  brush.wash("#879995", 88);
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let chB of canonicalSlice.mainChambersBevel) {
      drawPolyShape(transformPts(s, chB.pts), 0.22);
    }
    for (let chB of canonicalSlice.subChambersBevel) {
      drawPolyShape(transformPts(s, chB.pts), 0.22);
    }
    drawPolyShape(transformPts(s, canonicalSlice.centerChamberBevel.pts), 0.22);
  }

  // Gather all chambers across the 5 slices and precalculate their 3D wall layers
  const allChamberLayers = [];
  for (let s = 0; s < NUM_SLICES; s++) {
    const chList = [
      canonicalSlice.centerChamber,
      ...canonicalSlice.mainChambers,
      ...canonicalSlice.subChambers
    ];
    for (let ch of chList) {
      allChamberLayers.push(buildChamberWallLayers(s, ch));
    }
  }

  // Pass 7B: Top-inner bevel lip of the cut flesh wall (oxidized celadon-taupe)
  brush.wash("#73817e", 248);
  for (let L of allChamberLayers) {
    drawPolyShape(L.wPts, 0.2);
  }

  // Pass 7C: Mid-depth cylindrical inner flesh wall (cool twilight slate-celadon)
  brush.wash("#536165", 245);
  for (let L of allChamberLayers) {
    drawPolyShape(L.midWallPts, 0.2);
  }

  // Pass 7D: Deep shadow at the base of the inner flesh wall
  brush.wash("#2e3640", 248);
  for (let L of allChamberLayers) {
    drawPolyShape(L.deepWallPts, 0.2);
  }

  // Pass 7E: Cast shadow on the black lacquer floor inside each hole
  brush.wash("#020306", 252);
  for (let L of allChamberLayers) {
    drawPolyShape(L.lacquerPts, 0.2);
  }

  // Pass 7F: Deep glossy black lacquer visible at the bottom center of each chamber
  brush.wash("#090b12", 245);
  for (let L of allChamberLayers) {
    drawPolyShape(L.innerShadowPts, 0.2);
  }

  // Pass 7G: Tiny vascular pores near the outer rim and inner ring
  const allPoreLayers = [];
  for (let s = 0; s < NUM_SLICES; s++) {
    for (let pore of canonicalSlice.tinyPores) {
      allPoreLayers.push(buildChamberWallLayers(s, pore));
    }
  }

  brush.wash("#5b5150", 230);
  for (let P of allPoreLayers) {
    drawPolyShape(P.wPts, 0.2);
  }
  brush.wash("#08090f", 248);
  for (let P of allPoreLayers) {
    drawPolyShape(P.lacquerPts, 0.2);
  }

  brush.noWash();

  // Pass 7H: Fine 3D depth-striations down the visible inner cylindrical walls
  for (let L of allChamberLayers) {
    const n = L.wPts.length;
    for (let i = 0; i < n; i += 2) {
      const pTop = L.wPts[i];
      const pBot = L.lacquerPts[i];
      const d = dist(pTop[0], pTop[1], pBot[0], pBot[1]);
      if (d > 2.4) {
        brush.set("2H", i % 4 === 0 ? "#8a9b97" : "#3a444d", 0.24);
        brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
      }
    }
  }
}

// ============================================================================
// 8. WET SHEEN & SPECULAR MENISCUS HIGHLIGHTS AROUND THE HOLLOW CHAMBERS
// ============================================================================

function drawSlicesWetSheen() {
  brush.noFill();
  brush.noWash();

  for (let s = 0; s < NUM_SLICES; s++) {
    const tf = getSliceTransform(s);
    const gLightX = -0.62 * 0.55 - tf.ux * 0.45;
    const gLightY = -0.78 * 0.55 - tf.uy * 0.45;
    const gLen = sqrt(gLightX * gLightX + gLightY * gLightY) || 1;
    const lxDir = gLightX / gLen;
    const lyDir = gLightY / gLen;

    const chList = [
      canonicalSlice.centerChamber,
      ...canonicalSlice.mainChambers,
      ...canonicalSlice.subChambers
    ];

    for (let ch of chList) {
      const wPts = transformPts(s, ch.pts);
      const cWorld = localToWorld(tf, ch.cx, ch.cy);
      const n = wPts.length;

      // Build wet meniscus points just outside the crisp chamber rim (pushed outward by 2.0px)
      const rimGlowPts = [];
      for (let i = 0; i < n; i++) {
        const px = wPts[i][0];
        const py = wPts[i][1];
        const dx = px - cWorld[0];
        const dy = py - cWorld[1];
        const len = sqrt(dx * dx + dy * dy) || 1;
        const ux = dx / len;
        const uy = dy / len;

        // Specular reflection peaks on the curved lip opposite the light AND grazing the upper lip
        const dotL = ux * lxDir + uy * lyDir;
        const primarySpec = pow(max(0, -dotL + 0.25), 1.8);
        const secondarySpec = 0.65 * pow(max(0, dotL - 0.15), 2.2);
        const specStrength = max(primarySpec, secondarySpec);

        const pushOut = ch.isCenter ? 1.8 : 2.3;
        rimGlowPts.push({
          x: px + ux * pushOut,
          y: py + uy * pushOut,
          xClose: px + ux * (pushOut * 0.52),
          yClose: py + uy * (pushOut * 0.52),
          spec: specStrength
        });
      }

      // Draw continuous wet sheen halo arcs and broken bright specular moisture glints
      let arcGlow = [];
      let arcBright = [];

      for (let i = 0; i <= n; i++) {
        const pt = rimGlowPts[i % n];
        if (pt.spec > 0.18) {
          arcGlow.push([pt.x, pt.y, constrain(pt.spec * 1.1, 0.3, 1.2)]);
        } else {
          if (arcGlow.length >= 3) {
            brush.set("wet_glint", "#dfeee9", 0.95);
            brush.spline(arcGlow, 0.35);
          }
          arcGlow = [];
        }

        if (pt.spec > 0.38) {
          arcBright.push([pt.xClose, pt.yClose, constrain(pt.spec * 1.3, 0.4, 1.35)]);
        } else {
          if (arcBright.length >= 3) {
            brush.set("wet_glint", "#ffffff", 0.52);
            brush.spline(arcBright, 0.35);
          }
          arcBright = [];
        }
      }

      if (arcGlow.length >= 3) {
        brush.set("wet_glint", "#dfeee9", 0.95);
        brush.spline(arcGlow, 0.35);
      }
      if (arcBright.length >= 3) {
        brush.set("wet_glint", "#ffffff", 0.52);
        brush.spline(arcBright, 0.35);
      }

      // Pinpoint glistening moisture beads along the wet chamber lip
      brush.set("wet_glint", "#ffffff", 0.68);
      for (let i = 0; i < n; i += 5) {
        const pt = rimGlowPts[i];
        const ptNext = rimGlowPts[(i + 1) % n];
        if (pt.spec > 0.46) {
          brush.line(pt.xClose, pt.yClose, ptNext.xClose, ptNext.yClose);
        }
      }
    }

    // Wet sheen glints around the tiny peripheral pores
    brush.set("wet_glint", "#f4fbf8", 0.38);
    for (let pore of canonicalSlice.tinyPores) {
      const pWorld = localToWorld(tf, pore.cx, pore.cy);
      const r = pore.radius + 1.1;
      brush.arc(pWorld[0], pWorld[1], r, -45, 75);
    }

    // Broad damp starchy sheen streaks across the septum bridges
    brush.set("wet_glint", "#f6fbf9", 0.45);
    for (let i = 0; i < canonicalSlice.nodeAngles.length; i++) {
      const ang = canonicalSlice.nodeAngles[i];
      const p1 = localToWorld(tf, 42 * cos(ang), 42 * sin(ang));
      const p2 = localToWorld(tf, 68 * cos(ang + 0.8), 68 * sin(ang + 0.8));
      const p3 = localToWorld(tf, 94 * cos(ang), 94 * sin(ang));
      brush.spline([
        [p1[0], p1[1], 0.2],
        [p2[0], p2[1], 0.95],
        [p3[0], p3[1], 0.2]
      ], 0.35);
    }
  }
}

// ============================================================================
// 9. CRISP FINE-PEN CONTOURS & FINE ROOT FIBRES AT THE RIMS
// ============================================================================

function drawClosedContourSpline(pts, brushName, col, weight, pressureVar = 0.15) {
  brush.set(brushName, col, weight);
  const sp = [];
  const n = pts.length;
  for (let i = 0; i <= n + 1; i++) {
    const p = pts[i % n];
    const pr = 0.9 + pressureVar * sin((i / n) * 720);
    sp.push([p[0], p[1], pr]);
  }
  brush.spline(sp, 0.3);
}

function drawSlicesContoursAndFibres() {
  brush.noFill();
  brush.noWash();

  for (let s = 0; s < NUM_SLICES; s++) {
    const tf = getSliceTransform(s);

    // A. Inner epidermis double-line contour (thin skin boundary of cut lotus root)
    const innerSkin = transformPts(s, canonicalSlice.innerSkinContour);
    drawClosedContourSpline(innerSkin, "fine_pen", "#57443e", 0.34, 0.12);

    // B. Heraldic crisp fine-pen outer contour holding the slice shape
    const outerRim = transformPts(s, canonicalSlice.outerContour);
    drawClosedContourSpline(outerRim, "fine_pen", "#1a1416", 0.56, 0.14);

    // C. Crisp fine-pen contours around all hollow chambers
    drawClosedContourSpline(
      transformPts(s, canonicalSlice.centerChamber.pts),
      "fine_pen",
      "#1e181b",
      0.50,
      0.12
    );

    for (let ch of canonicalSlice.mainChambers) {
      const L = buildChamberWallLayers(s, ch);
      // Inner floor contour where flesh wall meets black lacquer
      drawClosedContourSpline(L.lacquerPts, "fine_pen", "#0e1017", 0.34, 0.08);
      // Crisp top lip heraldic contour
      drawClosedContourSpline(L.wPts, "fine_pen", "#1e181b", 0.50, 0.14);
    }

    for (let ch of canonicalSlice.subChambers) {
      const L = buildChamberWallLayers(s, ch);
      drawClosedContourSpline(L.lacquerPts, "fine_pen", "#0e1017", 0.28, 0.08);
      drawClosedContourSpline(L.wPts, "fine_pen", "#221b1e", 0.40, 0.12);
    }

    for (let pore of canonicalSlice.tinyPores) {
      drawClosedContourSpline(
        transformPts(s, pore.pts),
        "fine_pen",
        "#2b2224",
        0.30,
        0.08
      );
    }

    // D. Fine Root Fibres at the Rims (clustered at the 9 vascular nodes + along the skin)
    // 1. Node rootlet tufts emerging from the 9 rim indentations
    for (let i = 0; i < canonicalSlice.nodeAngles.length; i++) {
      const nAng = canonicalSlice.nodeAngles[i];
      const rNode = canonicalSlice.outerRadiusAt(nAng, 0);

      // Tiny dark root node scar on the rim
      const scarPt = localToWorld(tf, (rNode - 0.8) * cos(nAng), (rNode - 0.8) * sin(nAng));
      brush.set("fine_pen", "#241917", 0.55);
      brush.circle(scarPt[0], scarPt[1], 1.4, 0.2);

      // Symmetrically paired wispy root fibres curling out from each node
      const fibreConfigs = [
        { dAng: -2.2, len: 11.5, curl: -5.5, col: "#3d2e2a", wt: 0.36 },
        { dAng:  2.2, len: 11.5, curl:  5.5, col: "#3d2e2a", wt: 0.36 },
        { dAng: -1.1, len: 16.0, curl: -9.0, col: "#6e584c", wt: 0.30 },
        { dAng:  1.1, len: 16.0, curl:  9.0, col: "#6e584c", wt: 0.30 },
        { dAng: -0.4, len: 13.0, curl:  3.8, col: "#b59f89", wt: 0.24 },
        { dAng:  0.4, len: 13.0, curl: -3.8, col: "#b59f89", wt: 0.24 },
        { dAng:  0.0, len:  8.5, curl:  1.5, col: "#d8c9b8", wt: 0.20 }
      ];

      for (let fc of fibreConfigs) {
        const a0 = nAng + fc.dAng;
        const r0 = canonicalSlice.outerRadiusAt(a0, -0.5);
        const r1 = r0 + fc.len * 0.48;
        const r2 = r0 + fc.len;
        const a1 = a0 + fc.curl * 0.45;
        const a2 = a0 + fc.curl;

        const p0 = localToWorld(tf, r0 * cos(a0), r0 * sin(a0));
        const p1 = localToWorld(tf, r1 * cos(a1), r1 * sin(a1));
        const p2 = localToWorld(tf, r2 * cos(a2), r2 * sin(a2));

        brush.set("fibre_hair", fc.col, fc.wt);
        brush.spline([
          [p0[0], p0[1], 1.1],
          [p1[0], p1[1], 0.65],
          [p2[0], p2[1], 0.1]
        ], 0.4);
      }
    }

    // 2. Fine epidermal hair fibres & peeled starchy skin fibrils along the outer rim arches
    const numRimHairs = 72;
    for (let k = 0; k < numRimHairs; k++) {
      const th = (k / numRimHairs) * 360;
      const r0 = canonicalSlice.outerRadiusAt(th, -0.4);
      const dirSign = (k % 2 === 0 ? 1 : -1);
      const hairLen = 4.5 + 3.5 * abs(sin(k * 37));
      const sweep = dirSign * (3.2 + 2.4 * abs(cos(k * 23)));

      const r1 = r0 + hairLen * 0.55;
      const r2 = r0 + hairLen;
      const th1 = th + sweep * 0.5;
      const th2 = th + sweep;

      const p0 = localToWorld(tf, r0 * cos(th), r0 * sin(th));
      const p1 = localToWorld(tf, r1 * cos(th1), r1 * sin(th1));
      const p2 = localToWorld(tf, r2 * cos(th2), r2 * sin(th2));

      const col = k % 3 === 0 ? "#8a7364" : (k % 3 === 1 ? "#4c3b36" : "#626675");
      brush.set("fibre_hair", col, 0.24);
      brush.spline([
        [p0[0], p0[1], 1.0],
        [p1[0], p1[1], 0.55],
        [p2[0], p2[1], 0.08]
      ], 0.35);
    }
  }
}

// ============================================================================
// 10. SINGLE THIN GOLD RING ENCLOSING THE ARRANGEMENT (MAKI-E GOLD)
// ============================================================================

function drawRingCircleSpline(cx, cy, radius, brushName, col, weight, startDeg = 0, endDeg = 360) {
  brush.set(brushName, col, weight);
  const steps = max(24, floor(((endDeg - startDeg) / 360) * 144));
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const a = lerp(startDeg, endDeg, i / steps);
    const pr = 0.92 + 0.08 * cos(5 * a);
    pts.push([cx + radius * cos(a), cy + radius * sin(a), pr]);
  }
  brush.spline(pts, 0.3);
}

function drawEnclosingGoldRing() {
  brush.noFill();
  brush.noWash();

  // 1. Subtle submerged golden reflection in the black lacquer beneath the ring
  drawRingCircleSpline(CX + 4, CY + 6, RING_R, "lacquer_sheen", "#332613", 1.15);

  // 2. Crisp dark drop shadow under the raised takamaki-e gold ring
  drawRingCircleSpline(CX + 2.2, CY + 3.0, RING_R, "fine_pen", "#010103", 1.35);

  // 3. Outer and inner bronze-gold bevel bases (ring total thickness ~5.6px)
  drawRingCircleSpline(CX, CY, RING_R - 2.2, "fine_pen", "#5c421e", 0.95);
  drawRingCircleSpline(CX, CY, RING_R + 2.2, "fine_pen", "#5c421e", 0.95);

  // 4. Warm antique kamon gold body
  drawRingCircleSpline(CX, CY, RING_R - 1.1, "fine_pen", "#8f6b32", 1.15);
  drawRingCircleSpline(CX, CY, RING_R + 1.1, "fine_pen", "#9c7638", 1.15);
  drawRingCircleSpline(CX, CY, RING_R, "fine_pen", "#c49e54", 1.35);

  // 5. Luminous metallic gold ridge
  drawRingCircleSpline(CX, CY, RING_R - 0.2, "fine_pen", "#dfc079", 0.85);

  // 6. Specular champagne-gold and white-gold luster arcs catching the twilight light
  const specArcs = [
    { s: -168, e: -78, col: "#f5de9e", wt: 0.72 },
    { s: -148, e: -102, col: "#fff6d6", wt: 0.48 },
    { s: 12,   e: 98,  col: "#f2d894", wt: 0.68 },
    { s: 32,   e: 76,  col: "#fff6d6", wt: 0.44 },
    { s: -42,  e: -12, col: "#e6c882", wt: 0.52 },
    { s: 138,  e: 168, col: "#e6c882", wt: 0.52 }
  ];

  for (let arcDef of specArcs) {
    drawRingCircleSpline(CX, CY, RING_R - 0.3, "wet_glint", arcDef.col, arcDef.wt, arcDef.s, arcDef.e);
  }

  // 7. Ultra-fine maki-e gold dust texture along the gold ring
  drawRingCircleSpline(CX, CY, RING_R, "starch_grain", "#ebd08e", 0.38);

  // 8. Razor-sharp heraldic inner and outer hairline contours holding the gold ring
  drawRingCircleSpline(CX, CY, RING_R - 2.8, "fine_pen", "#261a0b", 0.36);
  drawRingCircleSpline(CX, CY, RING_R + 2.8, "fine_pen", "#261a0b", 0.36);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88341);

  // Custom fine felt-tip marker for crisp print motif outlines
  brush.add("fine_marker", {
    type: "marker",
    weight: 1.1,
    scatter: 0.04,
    opacity: 165,
    spacing: 0.25,
    pressure: [0.85, 1.0, 0.8],
    rotate: "natural",
    markerTip: false,
    noise: 0.25
  });

  // Custom soft glaze brush for fold shading transitions
  brush.add("soft_glaze", {
