    rotate: "natural",
    noise: 0.4
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#eae5dd");

  // =========================================================================
  // 1. GEOMETRY, ANATOMY & 3D CLOTH DRAPE ENGINE
  // =========================================================================

  // Seam & Silhouette boundary curves
  function collarTopY(x) {
    let dx = (x - 600) / 185;
    return 140 + 26 * dx * dx + 3 * sin(dx * 180);
  }

  function collarBotY(x) {
    let dx = (x - 600) / 215;
    return 204 + 28 * dx * dx + 4 * cos(dx * 270);
  }

  function yokeSeamY(x) {
    let dx = (x - 600) / 410;
    return 334 + 14 * dx * dx - 7 * cos((x - 600) * 0.65) + 4 * sin((x - 250) * 0.45);
  }

  function shoulderSlopeY(x) {
    if (x < 600) {
      let t = constrain((415 - x) / 345, 0, 1);
      return 164 + t * 145 + 16 * sin(t * 180) + (t > 0.68 ? pow(t - 0.68, 2) * 420 : 0);
    } else {
      let t = constrain((x - 785) / 345, 0, 1);
      return 162 + t * 142 + 15 * sin(t * 180) + (t > 0.68 ? pow(t - 0.68, 2) * 420 : 0);
    }
  }

  function leftArmholeX(y) {
    if (y < 334) {
      let t = constrain((y - 292) / 42, 0, 1);
      return 172 + t * 24;
    }
    let t = constrain((y - 334) / 340, 0, 1);
    return 196 + 44 * sin(t * 145) + 8 * sin(t * 360);
  }

  function rightArmholeX(y) {
    if (y < 330) {
      let t = constrain((y - 288) / 42, 0, 1);
      return 1028 - t * 24;
    }
    let t = constrain((y - 330) / 340, 0, 1);
    return 1004 - 44 * sin(t * 145) - 8 * sin(t * 360);
  }

  function leftTorsoX(y) {
    let t = constrain((y - 620) / 590, 0, 1);
    return 226 + 22 * t - 11 * sin(t * 540) + 6 * cos(t * 900);
  }

  function rightTorsoX(y) {
    let t = constrain((y - 620) / 590, 0, 1);
    return 974 - 22 * t + 11 * sin(t * 520) - 6 * cos(t * 880);
  }

  // Signed distance fields (<= 0 means inside the pattern piece)
  function fieldCollar(p) {
    let x = p[0], y = p[1];
    let dx = abs(x - 600) - (195 + (y - 140) * 0.28);
    let dyTop = collarTopY(x) - y;
    let dyBot = y - collarBotY(x);
    return max(dx, max(dyTop, dyBot));
  }

  function fieldYoke(p) {
    let x = p[0], y = p[1];
    let topB = (x > 392 && x < 808) ? max(collarBotY(x) - 3, shoulderSlopeY(x)) : shoulderSlopeY(x);
    let dyTop = topB - y;
    let dyBot = y - yokeSeamY(x);
    let dxL = leftArmholeX(y) - x;
    let dxR = x - rightArmholeX(y);
    return max(max(dyTop, dyBot), max(dxL, dxR));
  }

  function fieldBack(p) {
    let x = p[0], y = p[1];
    let dyTop = yokeSeamY(x) - y;
    let dyBot = y - 1212;
    let leftB = y < 640 ? leftArmholeX(y) : leftTorsoX(y);
    let rightB = y < 635 ? rightArmholeX(y) : rightTorsoX(y);
    return max(max(dyTop, dyBot), max(leftB - x, x - rightB));
  }

  function fieldSleeveL(p) {
    let x = p[0], y = p[1];
    let rightB = leftArmholeX(y);
    let topB = shoulderSlopeY(x);
    let t = constrain((232 - x) / 162, 0, 1);
    let botB = 678 - t * 44 + 10 * sin(t * 180);
    let leftB = 66 + max(0, (540 - y) * 0.31);
    return max(max(topB - y, y - botB), max(leftB - x, x - rightB));
  }

  function fieldSleeveR(p) {
    let x = p[0], y = p[1];
    let leftB = rightArmholeX(y);
    let topB = shoulderSlopeY(x);
    let t = constrain((x - 968) / 162, 0, 1);
    let botB = 672 - t * 44 + 10 * sin(t * 180);
    let rightB = 1134 - max(0, (535 - y) * 0.31);
    return max(max(topB - y, y - botB), max(leftB - x, x - rightB));
  }

  // Sweat-soaked patch between the shoulder blades (<= 0 is soaked through)
  function sweatField(p) {
    let x = p[0], y = p[1];
    if (x < 340 || x > 860 || y < 220 || y > 870) return 1.0;

    // Anatomical moisture lobes along spine, yoke seam, and inner scapulae
    let lobes = [
      { cx: 600, cy: 345, rx: 118, ry: 55, w: 0.95 }, // Yoke pooling lobe
      { cx: 600, cy: 445, rx: 132, ry: 95, w: 1.15 }, // Upper inter-scapular core
      { cx: 525, cy: 430, rx: 85,  ry: 62, w: 0.55 }, // Left scapula inner wing
      { cx: 678, cy: 425, rx: 88,  ry: 65, w: 0.58 }, // Right scapula inner wing
      { cx: 602, cy: 555, rx: 96,  ry: 95, w: 1.00 }, // Mid thoracic spine channel
      { cx: 555, cy: 540, rx: 72,  ry: 48, w: 0.42 }, // Fold-wicking left lobe
      { cx: 652, cy: 575, rx: 68,  ry: 46, w: 0.42 }, // Fold-wicking right lobe
      { cx: 598, cy: 665, rx: 64,  ry: 82, w: 0.80 }, // Lower thoracic taper
      { cx: 595, cy: 752, rx: 38,  ry: 58, w: 0.52 }, // Lumbar drip tail
      { cx: 462, cy: 332, rx: 42,  ry: 22, w: 0.40 }, // Left yoke pleat damp spot
      { cx: 735, cy: 330, rx: 44,  ry: 22, w: 0.40 }  // Right yoke pleat damp spot
    ];

    let density = 0;
    for (let i = 0; i < lobes.length; i++) {
      let l = lobes[i];
      let dx = (x - l.cx) / l.rx;
      let dy = (y - l.cy) / l.ry;
      let d2 = dx * dx + dy * dy;
      if (d2 < 3.2) {
        density += l.w * exp(-d2 * 1.35);
      }
    }

    // Capillary wicking noise along rayon threads and fold troughs
    let n1 = noise(x * 0.014, y * 0.014) - 0.48;
    let n2 = noise(x * 0.042, y * 0.042) - 0.48;
    let n3 = noise(x * 0.11, y * 0.11) - 0.5;
    let foldWick = sin((x - 600) * 0.5 + (y - 450) * 1.1) * 0.06;

    return 0.62 - (density + n1 * 0.38 + n2 * 0.19 + n3 * 0.08 + foldWick);
  }

  function sweatHaloField(p) {
    return sweatField(p) - 0.16;
