  // Warps a point (u, v) from flat rayon pattern space into 3D draped screen space
  function warpFabricPoint(u, v, piece) {
    let x = u;
    let y = v;

    if (piece === "yoke") {
      // Yoke curves over the roundness of the upper trapezius and deltoids
      let dx = (x - 600) / 420;
      y += 14 * dx * dx - 6 * cos(dx * 180);
      x += sin((y - 220) * 0.8) * 3;
      return [x, y];
    }

    if (piece === "collar") {
      let dx = (x - 600) / 200;
      y += 24 * dx * dx;
      return [x, y];
    }

    if (piece === "sleeveL") {
      // Cylindrical wrap around left upper arm + diagonal fold kinks
      let cx = 158, cy = 490;
      let dArm = (x - cx) / 95;
      x += sin(dArm * 90) * 8;
      y += (1 - cos(dArm * 90)) * 12;
    } else if (piece === "sleeveR") {
      let cx = 1042, cy = 485;
      let dArm = (x - cx) / 95;
      x += sin(dArm * 90) * 8;
      y += (1 - cos(dArm * 90)) * 12;
    } else if (piece === "back") {
      // 1. Broad convex expansion over Left Scapula (420, 455) and Right Scapula (780, 450)
      let dxL = x - 420, dyL = y - 455;
      let r2L = (dxL * dxL + dyL * dyL) / (165 * 165);
      if (r2L < 2.2) {
        let push = exp(-r2L * 1.1) * 18;
        x += (dxL / 165) * push;
        y += (dyL / 165) * push * 0.85;
      }

      let dxR = x - 780, dyR = y - 450;
      let r2R = (dxR * dxR + dyR * dyR) / (165 * 165);
      if (r2R < 2.2) {
        let push = exp(-r2R * 1.1) * 18;
        x += (dxR / 165) * push;
        y += (dyR / 165) * push * 0.85;
      }

      // 2. Concave inward pull into the sweat-soaked spinal furrow (x ≈ 600)
      let dxSpine = (x - 600) / 95;
      let dySpine = (y - 510) / 240;
      if (abs(dxSpine) < 2.0 && abs(dySpine) < 1.4) {
        let pull = exp(-dxSpine * dxSpine * 1.2 - dySpine * dySpine * 1.1);
        x -= (x - 600) * 0.14 * pull;
        y += 11 * pull;
      }
    }

    // Apply crease ridge & fold trough displacements
    for (let i = 0; i < folds.length; i++) {
      let f = folds[i];
      let vx = f.x2 - f.x1;
      let vy = f.y2 - f.y1;
      let len2 = vx * vx + vy * vy;
      let t = constrain(((u - f.x1) * vx + (v - f.y1) * vy) / len2, 0, 1);
      // Catenary sag along the fold spine
      let sag = sin(t * 180) * 18;
      let fx = f.x1 + t * vx;
      let fy = f.y1 + t * vy + sag;
      let len = sqrt(len2);
      let nx = -vy / len;
      let ny = vx / len;
      let d = (u - fx) * nx + (v - fy) * ny;
      let dn = d / f.w;
      if (abs(dn) < 2.4) {
        let env = exp(-dn * dn * 1.15) * sin(t * 180);
        let kink = dn * exp(-dn * dn * 1.4) * sin(t * 180);
        x += f.pullU * env + nx * f.pinch * kink;
        y += f.pullV * env + ny * f.pinch * kink;
      }
    }

    return [x, y];
  }

  // Polygon subdivision & scalar-field clipping utilities
  function subdividePoly(pts, maxStep = 9) {
    let out = [];
    for (let i = 0; i < pts.length; i++) {
      let a = pts[i];
      let b = pts[(i + 1) % pts.length];
      let d = dist(a[0], a[1], b[0], b[1]);
      let steps = max(1, ceil(d / maxStep));
      for (let s = 0; s < steps; s++) {
        let t = s / steps;
        out.push([lerp(a[0], b[0], t), lerp(a[1], b[1], t)]);
      }
    }
    return out;
  }

  function clipPolyByField(poly, fieldFn) {
    if (!poly || poly.length < 3) return [];
    let out = [];
    let n = poly.length;
    for (let i = 0; i < n; i++) {
      let a = poly[i];
      let b = poly[(i + 1) % n];
      let fa = fieldFn(a);
      let fb = fieldFn(b);
      if (fa <= 0 && fb <= 0) {
        out.push(b);
      } else if (fa <= 0 && fb > 0) {
        let t = constrain(-fa / (fb - fa + 1e-6), 0, 1);
        out.push([lerp(a[0], b[0], t), lerp(a[1], b[1], t)]);
      } else if (fa > 0 && fb <= 0) {
        let t = constrain(-fa / (fb - fa + 1e-6), 0, 1);
        out.push([lerp(a[0], b[0], t), lerp(a[1], b[1], t)]);
        out.push(b);
      }
    }
    return cleanPoly(out);
  }

  function cleanPoly(pts) {
    if (!pts || pts.length < 3) return [];
    let res = [pts[0]];
    for (let i = 1; i < pts.length; i++) {
      let prev = res[res.length - 1];
      if (dist(pts[i][0], pts[i][1], prev[0], prev[1]) > 2.2) {
        res.push(pts[i]);
      }
    }
    if (res.length >= 3 && dist(res[0][0], res[0][1], res[res.length - 1][0], res[res.length - 1][1]) <= 2.2) {
      res.pop();
    }
    if (res.length < 3) return [];
    // Verify non-degenerate polygon area
    let area = 0;
    for (let i = 0; i < res.length; i++) {
      let p1 = res[i], p2 = res[(i + 1) % res.length];
      area += p1[0] * p2[1] - p2[0] * p1[1];
    }
    return abs(area) * 0.5 > 14 ? res : [];
  }

  function drawFilledPoly(pts, curvature = 0.12) {
    if (!pts || pts.length < 3) return;
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  }

  // Clips an open polyline against fieldFn(p) <= 0, returning array of sub-polylines
  function clipPolylineByField(pts, fieldFn) {
    let segments = [];
    let curr = [];
    for (let i = 0; i < pts.length; i++) {
      let p = pts[i];
      if (fieldFn(p) <= 0) {
        curr.push(p);
      } else {
        if (curr.length >= 2) segments.push(curr);
        curr = [];
      }
    }
    if (curr.length >= 2) segments.push(curr);
    return segments;
  }

