  // =========================================================================
  // 5. LAYER 4: THE ALOHA PRINT MOTIFS (HIBISCUS, MONSTERA & OUTRIGGER CANOES)
  // =========================================================================
  // Buckets for batched watercolor fills (dry pastel vs. sweat-darkened) and marker lines
  let buckets = {
    dryGreen: [], wetGreen: [],
    dryDarkGreen: [], wetDarkGreen: [],
    dryCoral: [], wetCoral: [],
    dryDeepCoral: [], wetDeepCoral: [],
    dryCream: [], wetCream: [],
    dryGold: [], wetGold: [],
