  };
  let markerStrokes = []; // { pts, colDry, colWet, w, pieceField }

  function registerMotifPoly(localPts, colorGroup, piece, pieceField) {
    let sub = subdividePoly(localPts, 8);
    let warped = sub.map(pt => warpFabricPoint(pt[0], pt[1], piece));
    let inPiece = clipPolyByField(warped, pieceField);
    if (inPiece.length < 3) return;

    // Split polygon cleanly across the sweat-soaked boundary!
    let dryPart = clipPolyByField(inPiece, dryShirtField);
    let wetPart = clipPolyByField(inPiece, sweatField);

    if (dryPart.length >= 3) buckets["dry" + colorGroup].push(dryPart);
    if (wetPart.length >= 3) buckets["wet" + colorGroup].push(wetPart);
  }

  function registerMotifStroke(localPts, colDry, colWet, weight, piece, pieceField, closed = false) {
    let pts = closed ? [...localPts, localPts[0]] : localPts;
    let sub = [];
    for (let i = 0; i < pts.length - 1; i++) {
      let a = pts[i], b = pts[i + 1];
      let d = dist(a[0], a[1], b[0], b[1]);
      let steps = max(1, ceil(d / 7));
      for (let s = 0; s < steps; s++) {
        let t = s / steps;
        sub.push(warpFabricPoint(lerp(a[0], b[0], t), lerp(a[1], b[1], t), piece));
      }
    }
    sub.push(warpFabricPoint(pts[pts.length - 1][0], pts[pts.length - 1][1], piece));

    let pieceSegs = clipPolylineByField(sub, pieceField);
    for (let seg of pieceSegs) {
      let drySegs = clipPolylineByField(seg, dryShirtField);
      for (let ds of drySegs) {
        markerStrokes.push({ pts: ds, col: colDry, w: weight });
      }
      let wetSegs = clipPolylineByField(seg, sweatField);
      for (let ws of wetSegs) {
        markerStrokes.push({ pts: ws, col: colWet, w: weight * 1.08 });
      }
    }
  }

  function xform(cx, cy, sc, angDeg, lx, ly) {
    let c = cos(angDeg), s = sin(angDeg);
    return [cx + (lx * c - ly * s) * sc, cy + (lx * s + ly * c) * sc];
  }

  // --- MOTIF GENERATOR 1: HAWAIIAN HIBISCUS BLOSSOM ---
  function addHibiscus(cx, cy, sc, rot, variant, piece, pieceField) {
    let mainColor = variant === "cream" ? "Cream" : "Coral";
    let centerColor = variant === "cream" ? "Coral" : "DeepCoral";

    // 2 notched tropical hibiscus leaves behind the flower
    for (let l = 0; l < 2; l++) {
      let lAng = rot + 35 + l * 155;
      let leafPts = [
        [0, 0], [18, -14], [42, -22], [54, -15], [72, -18],
        [88, 0], [72, 18], [54, 15], [42, 22], [18, 14]
      ].map(p => xform(cx, cy, sc * 0.95, lAng, p[0], p[1]));
      registerMotifPoly(leafPts, "DarkGreen", piece, pieceField);
      registerMotifStroke(leafPts, "#234236", "#162b23", 0.48, piece, pieceField, true);
      let midrib = [[8, 0], [45, 0], [80, 0]].map(p => xform(cx, cy, sc * 0.95, lAng, p[0], p[1]));
      registerMotifStroke(midrib, "#d9ebe0", "#8aa899", 0.4, piece, pieceField, false);
    }

    // 5 overlapping ruffled hibiscus petals
    for (let i = 0; i < 5; i++) {
      let pAng = rot + i * 72;
      let petalPts = [
        [0, 0],
        [14, -12], [32, -26], [52, -28], [66, -18],
        [72, -5], [69, 8], [62, 20], [46, 27],
        [28, 22], [12, 10]
      ].map(p => xform(cx, cy, sc, pAng, p[0], p[1]));
      registerMotifPoly(petalPts, mainColor, piece, pieceField);

      // Deep throat star at base of petal
      let throatPts = [
        [0, 0], [12, -8], [26, -10], [31, 0], [26, 10], [12, 8]
      ].map(p => xform(cx, cy, sc, pAng, p[0], p[1]));
      registerMotifPoly(throatPts, centerColor, piece, pieceField);

      // Crisp marker outline & delicate radiating petal veins
      registerMotifStroke(petalPts, "#33474a", "#1c2b2e", 0.52, piece, pieceField, true);
      for (let v = -1; v <= 1; v++) {
        let vein = [
          [16, v * 3], [38, v * 9], [58, v * 12]
        ].map(p => xform(cx, cy, sc, pAng, p[0], p[1]));
        let vColDry = variant === "cream" ? "#e5857e" : "#fae8dc";
        let vColWet = variant === "cream" ? "#9e4d49" : "#b89b94";
        registerMotifStroke(vein, vColDry, vColWet, 0.36, piece, pieceField, false);
      }
    }

    // Long curving hibiscus stamen & golden pollen tips
    let sAng = rot + 24;
    let stamenStem = [
      [0, 0], [22, -4], [46, -12], [72, -24], [86, -32]
    ].map(p => xform(cx, cy, sc, sAng, p[0], p[1]));
    registerMotifStroke(stamenStem, "#fbf4e2", "#bfa89e", 0.85, piece, pieceField, false);
    registerMotifStroke(stamenStem, "#4a332d", "#291c18", 0.38, piece, pieceField, false);

    let tipOffsets = [[82, -36], [88, -28], [91, -35], [76, -32], [84, -23]];
    for (let t of tipOffsets) {
      let tc = xform(cx, cy, sc, sAng, t[0], t[1]);
      let dot = [];
      for (let a = 0; a < 360; a += 60) {
        dot.push([tc[0] + cos(a) * 4.2 * sc, tc[1] + sin(a) * 4.2 * sc]);
      }
      registerMotifPoly(dot, "Gold", piece, pieceField);
    }
  }

  // --- MOTIF GENERATOR 2: SPLIT MONSTERA DELICIOSA LEAF ---
  function addMonstera(cx, cy, sc, rot, piece, pieceField) {
    // Iconic fenestrated left & right leaf lobes so gaps reveal the lagoon teal ground
    let lobes = [
      // Left 4 lobes
      [[0, -35], [-18, -42], [-42, -32], [-56, -14], [-46, -4], [-18, -14], [0, -16]],
      [[0, -10], [-24, -12], [-58, 2], [-66, 20], [-52, 30], [-22, 16], [0, 12]],
      [[0, 18], [-22, 22], [-52, 38], [-54, 54], [-38, 62], [-16, 44], [0, 38]],
      [[0, 42], [-15, 48], [-34, 66], [-28, 82], [-12, 86], [0, 92], [0, 62]],
      // Right 4 lobes
      [[0, -35], [18, -42], [42, -32], [56, -14], [46, -4], [18, -14], [0, -16]],
      [[0, -10], [24, -12], [58, 2], [66, 20], [52, 30], [22, 16], [0, 12]],
      [[0, 18], [22, 22], [52, 38], [54, 54], [38, 62], [16, 44], [0, 38]],
      [[0, 42], [15, 48], [34, 66], [28, 82], [12, 86], [0, 92], [0, 62]],
      // Central stem & midrib spine
      [[-4, -62], [4, -62], [5, -10], [3, 85], [-3, 85], [-5, -10]]
    ];

    for (let i = 0; i < lobes.length; i++) {
      let pts = lobes[i].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
      let colGroup = (i % 2 === 0) ? "Green" : "DarkGreen";
      registerMotifPoly(pts, colGroup, piece, pieceField);
      if (i < 8) {
        registerMotifStroke(pts, "#264738", "#162b22", 0.46, piece, pieceField, true);
      }
    }

    // Cream-green central vein highlight
    let mainVein = [[0, -60], [0, -15], [0, 35], [0, 88]].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
    registerMotifStroke(mainVein, "#e6f2e4", "#9ab09d", 0.55, piece, pieceField, false);
  }

  // --- MOTIF GENERATOR 3: HAWAIIAN OUTRIGGER CANOE (WA'A) & SURF ---
  function addOutriggerCanoe(cx, cy, sc, rot, hasSail, piece, pieceField) {
