    // 4. Long sleek canoe hull with curved bow & stern manu
    let hullPts = [
      [-78, -14], [-66, -4], [-42, 2], [42, 2], [68, -6], [82, -18],
      [74, 8], [48, 16], [-48, 16], [-72, 6]
    ].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
    registerMotifPoly(hullPts, "Coral", piece, pieceField);

    // Cream gunwale trim stripe
    let gunwale = [
      [-66, -3], [-40, 3], [40, 3], [68, -5], [64, 1], [-62, 2]
    ].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
    registerMotifPoly(gunwale, "Cream", piece, pieceField);
    registerMotifStroke(hullPts, "#2b3d40", "#182326", 0.55, piece, pieceField, true);

    // 5. Outrigger float (ama) & curved cross-booms ('iako)
    let boom1 = [[-26, 4], [-22, 14], [-18, 22]].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
    let boom2 = [[24, 4], [28, 14], [32, 22]].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
    registerMotifStroke(boom1, "#382a24", "#1f1714", 0.65, piece, pieceField, false);
    registerMotifStroke(boom2, "#382a24", "#1f1714", 0.65, piece, pieceField, false);

    let amaPts = [
      [-48, 18], [-34, 21], [42, 21], [56, 15], [46, 26], [-38, 26]
    ].map(p => xform(cx, cy, sc, rot, p[0], p[1]));
    registerMotifPoly(amaPts, "Gold", piece, pieceField);
    registerMotifStroke(amaPts, "#2b3d40", "#182326", 0.48, piece, pieceField, true);
