  // --- POPULATE PATTERN ACROSS ALL 5 SHIRT PIECES ---
  // 1. Main Back Panel Motifs (including clusters right across the sweat patch & shoulder blades!)
  let backMotifs = [
    // Monstera leaves (drawn first so flowers & canoes overlap naturally)
    { type: "monstera", x: 345, y: 420, sc: 0.92, rot: -32 },
