    { type: "canoe", x: 445, y: 375, sc: 0.92, rot: -8, sail: true },
    { type: "canoe", x: 645, y: 495, sc: 0.98, rot: 6, sail: false }, // Right across the soaked spine!
    { type: "canoe", x: 870, y: 535, sc: 0.88, rot: -12, sail: true },
    { type: "canoe", x: 355, y: 655, sc: 0.95, rot: 9, sail: false },
    { type: "canoe", x: 535, y: 685, sc: 0.92, rot: -7, sail: true }, // Straddles lower sweat edge!
    { type: "canoe", x: 785, y: 745, sc: 0.94, rot: 11, sail: false },
    { type: "canoe", x: 595, y: 885, sc: 0.98, rot: -5, sail: true },
    { type: "canoe", x: 335, y: 985, sc: 0.90, rot: 8, sail: false },
    { type: "canoe", x: 845, y: 995, sc: 0.92, rot: -9, sail: true },
    { type: "canoe", x: 685, y: 1145, sc: 0.94, rot: 6, sail: false },

    // Hibiscus Blossoms (Coral Red & Cream)
    { type: "hibiscus", x: 275, y: 370, sc: 0.86, rot: 15, v: "coral" },
    { type: "hibiscus", x: 515, y: 445, sc: 0.96, rot: 42, v: "cream" }, // Half wet, half dry!
    { type: "hibiscus", x: 675, y: 390, sc: 0.90, rot: -18, v: "coral" }, // Half wet, half dry!
    { type: "hibiscus", x: 915, y: 385, sc: 0.85, rot: 55, v: "cream" },
    { type: "hibiscus", x: 395, y: 525, sc: 0.92, rot: -28, v: "coral" },
    { type: "hibiscus", x: 595, y: 585, sc: 0.95, rot: 12, v: "coral" }, // Soaked center back!
    { type: "hibiscus", x: 755, y: 635, sc: 0.92, rot: 64, v: "cream" },
    { type: "hibiscus", x: 295, y: 815, sc: 0.88, rot: -40, v: "cream" },
    { type: "hibiscus", x: 485, y: 795, sc: 0.96, rot: 22, v: "coral" },
    { type: "hibiscus", x: 665, y: 815, sc: 0.88, rot: -15, v: "cream" },
    { type: "hibiscus", x: 905, y: 835, sc: 0.90, rot: 35, v: "coral" },
    { type: "hibiscus", x: 455, y: 1015, sc: 0.94, rot: -22, v: "cream" },
    { type: "hibiscus", x: 725, y: 1010, sc: 0.94, rot: 48, v: "coral" },
    { type: "hibiscus", x: 435, y: 1165, sc: 0.88, rot: 18, v: "coral" },
    { type: "hibiscus", x: 575, y: 1165, sc: 0.86, rot: -32, v: "cream" }
  ];

  for (let m of backMotifs) {
    if (m.type === "monstera") addMonstera(m.x, m.y, m.sc, m.rot, "back", fieldBack);
    else if (m.type === "canoe") addOutriggerCanoe(m.x, m.y, m.sc, m.rot, m.sail, "back", fieldBack);
    else if (m.type === "hibiscus") addHibiscus(m.x, m.y, m.sc, m.rot, m.v, "back", fieldBack);
