  // 2. Shoulder Yoke Motifs (separate cut pattern piece, so motifs cut off at the yoke seam!)
  let yokeMotifs = [
    { type: "monstera", x: 295, y: 265, sc: 0.85, rot: -65 },
    { type: "monstera", x: 535, y: 275, sc: 0.88, rot: 48 },
    { type: "monstera", x: 755, y: 255, sc: 0.86, rot: -42 },
    { type: "monstera", x: 935, y: 275, sc: 0.82, rot: 72 },
    { type: "canoe", x: 415, y: 255, sc: 0.85, rot: -12, sail: false },
    { type: "canoe", x: 845, y: 265, sc: 0.85, rot: 10, sail: true },
