    { type: "hibiscus", x: 485, y: 315, sc: 0.86, rot: -15, v: "coral" },
    { type: "hibiscus", x: 645, y: 275, sc: 0.90, rot: 35, v: "cream" }, // Clips into yoke sweat lobe!
    { type: "hibiscus", x: 735, y: 325, sc: 0.84, rot: -28, v: "coral" },
