  ];
  for (let m of yokeMotifs) {
    if (m.type === "monstera") addMonstera(m.x, m.y, m.sc, m.rot, "yoke", fieldYoke);
    else if (m.type === "canoe") addOutriggerCanoe(m.x, m.y, m.sc, m.rot, m.sail, "yoke", fieldYoke);
    else if (m.type === "hibiscus") addHibiscus(m.x, m.y, m.sc, m.rot, m.v, "yoke", fieldYoke);
  }

  // 3. Collar Motifs
  addMonstera(495, 175, 0.72, -55, "collar", fieldCollar);
  addMonstera(695, 175, 0.72, 65, "collar", fieldCollar);
  addHibiscus(585, 172, 0.74, 15, "coral", "collar", fieldCollar);
  addHibiscus(435, 168, 0.68, -22, "cream", "collar", fieldCollar);
  addHibiscus(755, 168, 0.68, 38, "cream", "collar", fieldCollar);

  // 4. Left & Right Sleeves (tilted bias cut angle following sleeve drape)
  addMonstera(165, 395, 0.84, -75, "sleeveL", fieldSleeveL);
  addMonstera(135, 575, 0.86, 35, "sleeveL", fieldSleeveL);
  addOutriggerCanoe(160, 495, 0.82, -28, false, "sleeveL", fieldSleeveL);
  addHibiscus(195, 355, 0.78, 12, "coral", "sleeveL", fieldSleeveL);
  addHibiscus(115, 465, 0.82, -35, "cream", "sleeveL", fieldSleeveL);
  addHibiscus(175, 615, 0.80, 28, "coral", "sleeveL", fieldSleeveL);

  addMonstera(1035, 390, 0.84, 75, "sleeveR", fieldSleeveR);
  addMonstera(1065, 570, 0.86, -35, "sleeveR", fieldSleeveR);
  addOutriggerCanoe(1040, 490, 0.82, 28, true, "sleeveR", fieldSleeveR);
  addHibiscus(1005, 350, 0.78, -12, "cream", "sleeveR", fieldSleeveR);
  addHibiscus(1085, 460, 0.82, 35, "coral", "sleeveR", fieldSleeveR);
  addHibiscus(1025, 610, 0.80, -28, "cream", "sleeveR", fieldSleeveR);

  // --- BATCH RENDER ALL MOTIF WATERCOLOR FILLS ---
  brush.noStroke();
  brush.fillBleed(0.11, "out");
  brush.fillTexture(0.42, 0.35);

  let batchRenderOrder = [
    { key: "dryDarkGreen", col: "#548a6b", op: 195 },
    { key: "wetDarkGreen", col: "#2e5442", op: 215 },
    { key: "dryGreen",     col: "#7ab08a", op: 190 },
    { key: "wetGreen",     col: "#416e55", op: 210 },
    { key: "dryCream",     col: "#faf3e3", op: 215 },
    { key: "wetCream",     col: "#bfa59d", op: 210 },
    { key: "dryCoral",     col: "#eb7870", op: 205 },
    { key: "wetCoral",     col: "#9e4648", op: 215 },
    { key: "dryDeepCoral", col: "#c44d49", op: 205 },
    { key: "wetDeepCoral", col: "#782b30", op: 220 },
    { key: "dryGold",      col: "#ebd47c", op: 210 },
    { key: "wetGold",      col: "#9e8047", op: 215 }
  ];

  for (let b of batchRenderOrder) {
    let list = buckets[b.key];
    if (!list || list.length === 0) continue;
    brush.fill(b.col, b.op);
    for (let i = 0; i < list.length; i++) {
      drawFilledPoly(list[i], 0.1);
    }
  }

  // =========================================================================
  // 6. LAYER 5: THIN MARKER OUTLINES CRISPING THE PRINT MOTIFS
  // =========================================================================
  brush.noFill();
  for (let i = 0; i < markerStrokes.length; i++) {
    let ms = markerStrokes[i];
    if (ms.pts.length < 2) continue;
    brush.set("fine_marker", ms.col, ms.w);
    if (ms.pts.length === 2) {
      brush.line(ms.pts[0][0], ms.pts[0][1], ms.pts[1][0], ms.pts[1][1]);
    } else {
      let splinePts = ms.pts.map(p => [p[0], p[1], 0.9]);
      brush.spline(splinePts, 0.25);
    }
  }

  // =========================================================================
  // 7. LAYER 6: POOLING WATERCOLOR FOLD SHADOWS, WET CLING & SEAM DETAILS
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.48, 0.28);

  // Soft watercolor shadow troughs pooling inside each fabric fold
  for (let i = 0; i < folds.length; i++) {
    let f = folds[i];
    let vx = f.x2 - f.x1, vy = f.y2 - f.y1;
    let len = sqrt(vx * vx + vy * vy);
    let nx = -vy / len, ny = vx / len;

    // Build pooling shadow ribbon on the lower/shaded side of the crease ridge
    let topEdge = [], botEdge = [];
    let steps = 14;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let sag = sin(t * 180) * 18;
      let bx = f.x1 + t * vx;
      let by = f.y1 + t * vy + sag;
      let wEnv = sin(t * 180) * f.w * 0.85;
      topEdge.push([bx - nx * wEnv * 0.15, by - ny * wEnv * 0.15]);
      botEdge.push([bx + nx * wEnv * 1.05, by + ny * wEnv * 1.05]);
    }
    let foldPoly = cleanPoly([...topEdge, ...botEdge.reverse()]);
    if (foldPoly.length >= 3) {
      let isWetFold = sweatField([(f.x1 + f.x2) * 0.5, (f.y1 + f.y2) * 0.5]) < 0.1;
      brush.fill(isWetFold ? "#1c363b" : "#2f575e", round(52 * f.shade));
      drawFilledPoly(foldPoly, 0.2);
    }

    // Crisp crease accent & sunlit upper ridge highlight
    let ridgePts = [];
    let lightPts = [];
    for (let s = 1; s < steps; s++) {
      let t = s / steps;
      let sag = sin(t * 180) * 18;
      let bx = f.x1 + t * vx;
      let by = f.y1 + t * vy + sag;
      ridgePts.push([bx, by, sin(t * 180) * 0.95]);
      lightPts.push([bx - nx * f.w * 0.42, by - ny * f.w * 0.42, sin(t * 180) * 0.9]);
