// ============================================================================
// ANATOMICAL SILHOUETTE, 3D HEIGHT MAP, AND SURFACE NORMALS
// ============================================================================

// Top contour of horse: withers (left) -> saddle bed / back (mid) -> loin / croup (right)
function getTopEdge(x) {
  let nx = x / W;
  // High withers on left, dipping into the back around nx=0.46, rising to croup at nx=0.92
  let withers = -78 * exp(-pow((nx - 0.08) / 0.16, 2));
  let backDip = 52 * exp(-pow((nx - 0.46) / 0.24, 2));
  let croupRise = -58 * exp(-pow((nx - 0.90) / 0.20, 2));
  return 138 + withers + backDip + croupRise;
}

// Bottom contour: forearm/elbow (left) -> girth notch -> barrel belly -> flank fold -> stifle (right)
function getBottomEdge(x) {
  let nx = x / W;
  // Forearm & point of elbow dropping low on the left
  let forearm = 155 * exp(-pow((nx - 0.09) / 0.11, 2));
  let elbowPoint = 68 * exp(-pow((nx - 0.19) / 0.045, 2));
  // Tuck behind elbow at girth line
  let girthNotch = -28 * exp(-pow((nx - 0.31) / 0.06, 2));
  // Deepest curve of barrel belly
  let bellySwell = 42 * exp(-pow((nx - 0.56) / 0.20, 2));
  // Upward arch of the flank fold (plica lateralis)
  let flankArch = -112 * exp(-pow((nx - 0.79) / 0.085, 2));
  // Descent of the stifle / thigh on the far right
  let stifleDrop = 165 * exp(-pow((nx - 0.98) / 0.11, 2));
  return 995 + forearm + elbowPoint + girthNotch + bellySwell + flankArch + stifleDrop;
}

function isInsideHorse(x, y, margin = 0) {
  if (x < -margin || x > W + margin) return false;
  let topY = getTopEdge(constrain(x, 0, W)) - margin;
  let botY = getBottomEdge(constrain(x, 0, W)) + margin;
  return y >= topY && y <= botY;
}

// Gaussian helper
function gauss2D(x, y, cx, cy, sx, sy, angleDeg = 0) {
  let dx = x - cx;
  let dy = y - cy;
  if (angleDeg !== 0) {
    let c = cos(angleDeg);
    let s = sin(angleDeg);
    let rx = dx * c + dy * s;
    let ry = -dx * s + dy * c;
    dx = rx;
    dy = ry;
  }
  return exp(-(dx * dx) / (2 * sx * sx) - (dy * dy) / (2 * sy * sy));
}

// Analytical 3D anatomical height map H(x, y) in canvas units
function getHorseHeight(x, y) {
  let topY = getTopEdge(constrain(x, 0, W));
  let botY = getBottomEdge(constrain(x, 0, W));
  let span = max(120, botY - topY);
  let v = constrain((y - topY) / span, 0, 1);

  // 1. Base cylindrical barrel curvature (fuller on upper-mid barrel)
  let barrelProfile = pow(sin(v * 180), 0.72);
  // Subtle dorsal fullness near the topline
  let H_val = 240 * barrelProfile;

  // 2. Shoulder & Scapula complex (left)
  // Spine of scapula ridge running from withers (170, 175) toward point of shoulder (30, 590)
  H_val += 56 * gauss2D(x, y, 135, 365, 62, 195, -28);
  // Muscular infraspinatus & deltoid / triceps mass
  H_val += 74 * gauss2D(x, y, 205, 555, 82, 135, -14);
  // Deep anatomical furrow / crease behind the triceps (from (295, 410) to elbow (268, 860))
  H_val -= 48 * gauss2D(x, y, 295, 615, 32, 175, 10);
  // Bony prominence of the olecranon (point of elbow)
  H_val += 42 * gauss2D(x, y, 222, 895, 42, 52, -10);
  // Deep hollow behind the elbow in the girth groove
  H_val -= 38 * gauss2D(x, y, 335, 845, 55, 85, 18);
  // High muscular crest of the withers
  H_val += 48 * gauss2D(x, y, 130, 210, 95, 68, -12);

  // 3. Ribcage / Barrel swell & subtle athletic intercostal rib ripples
  H_val += 64 * gauss2D(x, y, 575, 525, 195, 165, 6);
  // Latissimus dorsi upper shelf
  H_val += 34 * gauss2D(x, y, 515, 325, 180, 75, 8);

  // Subtle intercostal ribs (6 ribs visible under glossy summer skin)
  let ribEnv = gauss2D(x, y, 615, 585, 145, 135, -12);
  if (ribEnv > 0.05) {
    let ribPhase = (x - 0.34 * y) * 3.8; // in degrees
    H_val += 5.2 * ribEnv * sin(ribPhase);
  }

  // 4. Flank Hollow (Paralumbar Fossa) & Hindquarter / Stifle Complex (right)
  // Concave triangle of the flank hollow
  H_val -= 68 * gauss2D(x, y, 882, 455, 82, 105, -22);
  // Prominent Point of Hip (Tuber Coxae) catching overhead midday light
  H_val += 76 * gauss2D(x, y, 975, 292, 68, 52, -18);
  // Loin & Gluteus medius powerful upper croup swell
  H_val += 82 * gauss2D(x, y, 1085, 235, 145, 95, -14);
  // Tensor fasciae latae & quadriceps swell descending toward the stifle
  H_val += 88 * gauss2D(x, y, 1095, 645, 118, 220, 14);
  // Taut ridge of the flank fold (plica lateralis)
  H_val += 36 * gauss2D(x, y, 945, 805, 38, 125, 34);
  // Hollow just above the flank fold around the flank cowlick
  H_val -= 26 * gauss2D(x, y, 905, 675, 58, 65, 20);

  return H_val;
}

// Compute 3D unit surface normal [nx, ny, nz] via finite differences
function getSurfaceNormal(x, y) {
  let eps = 4.0;
  let hx1 = getHorseHeight(x + eps, y);
  let hx0 = getHorseHeight(x - eps, y);
  let hy1 = getHorseHeight(x, y + eps);
  let hy0 = getHorseHeight(x, y - eps);

  let dhdx = (hx1 - hx0) / (2 * eps);
  let dhdy = (hy1 - hy0) / (2 * eps);

  // Scale gradient for strong sculptural relief
  let sx = -dhdx * 1.15;
  let sy = -dhdy * 1.15;
  let sz = 1.0;
  let len = sqrt(sx * sx + sy * sy + sz * sz);
  return [sx / len, sy / len, sz / len];
}

// ============================================================================
// EQUINE HAIR GROWTH VECTOR FIELD (WHORLS, CONVERGENCE & DIVERGENCE)
// ============================================================================

function getCoatAngle(x, y) {
  let topY = getTopEdge(constrain(x, 0, W));
  let botY = getBottomEdge(constrain(x, 0, W));
  let v = constrain((y - topY) / max(120, botY - topY), 0, 1);

  // 1. Base anatomical flow across the body
  // Near topline (v ~ 0): flows nearly parallel to the spine (+12 to +24 deg)
  // Across mid-barrel (v ~ 0.45): sweeps down and back (+36 to +54 deg)
  // Near belly underline (v ~ 0.9): sweeps backward along belly (+8 to +18 deg)
  let spineAngle = (getTopEdge(constrain(x + 10, 0, W)) - getTopEdge(constrain(x - 10, 0, W))) * 2.5;
  let bellyAngle = (getBottomEdge(constrain(x + 10, 0, W)) - getBottomEdge(constrain(x - 10, 0, W))) * 1.8;

  let midBarrelAngle = 44 + 14 * sin((x / W) * 180);
  // Shoulder area flows steeper downward toward the forearm/elbow
  let shoulderSteep = 34 * gauss2D(x, y, 165, 580, 145, 240, -10);
  // Hindquarter / thigh sweeps steeper downward toward the stifle
  let thighSteep = 38 * gauss2D(x, y, 1110, 740, 130, 260, 12);

  let baseAngle =
    (1 - v) * (1 - v) * (spineAngle + 14) +
    2 * (1 - v) * v * (midBarrelAngle + shoulderSteep + thighSteep) +
    v * v * (bellyAngle + 12);

  let vx = cos(baseAngle);
  let vy = sin(baseAngle);

  // 2. Muscle divergence/convergence: hair deflects slightly across strong muscle gradients
  let n = getSurfaceNormal(x, y);
  vx += n[0] * 0.28;
  vy += n[1] * 0.16;

  // 3. Superpose Spiral Cowlick Whorls (Trichoglyphs)
  for (let i = 0; i < WHORLS.length; i++) {
    let w = WHORLS[i];
    let dx = x - w.x;
    let dy = y - w.y;
    let d = sqrt(dx * dx + dy * dy) + 0.001;
    if (d < w.r * 2.4) {
      // Radial angle from whorl center
      let phi = atan2(dy, dx);
      // Spiral tangent angle: phi + twist (converging/diverging spiral vortex)
      // Tighten spiral angle slightly as it approaches the core
      let coreTighten = 18 * exp(-d / 32) * w.chirality;
      let spiralAng = phi + w.twist + coreTighten;

      let weight = w.strength * exp(-pow(d / w.r, 1.65));
      vx = vx * (1 - min(0.92, weight * 0.72)) + cos(spiralAng) * weight;
      vy = vy * (1 - min(0.92, weight * 0.72)) + sin(spiralAng) * weight;
    }
  }

  // 4. Flank feathering ridge (linear convergence below the primary flank whorl into the stifle fold)
  let ridgeEnv = gauss2D(x, y, 938, 790, 42, 115, 26);
  if (ridgeEnv > 0.05) {
    // Hair from left sweeps down-right; hair from right (stifle) sweeps down-left to meet at the ridge
    let side = (x - (912 + (y - 668) * 0.24));
    let ridgeAng = side < 0 ? 58 : 112;
    vx += cos(ridgeAng) * ridgeEnv * 0.85;
    vy += sin(ridgeAng) * ridgeEnv * 0.85;
  }

  return atan2(vy, vx);
}

// Compute a flow-orthogonal phase value so neighboring strokes group into readable hair ribbons
function getStreamlineRibbonVal(x, y) {
  let ang = getCoatAngle(x, y);
  // Perpendicular coordinate to local flow
  let perpX = -sin(ang) * x + cos(ang) * y;
  let alongX = cos(ang) * x + sin(ang) * y;
  let n1 = noise(perpX * 0.028 + 100, alongX * 0.0035 + 200);
  let n2 = noise(x * 0.012 + 50, y * 0.012 + 50);
  return 0.65 * n1 + 0.35 * n2;
}

// ============================================================================
// ANISOTROPIC EQUINE COAT SHADER (PALETTE & LIGHTING)
// ============================================================================

// Returns { col, highlightType, lum } for a given point (x, y) and tangent angle
function sampleCoatColor(x, y, tangentAngle, jitter = 0) {
  let n = getSurfaceNormal(x, y);
  let nx = n[0], ny = n[1], nz = n[2];

  // Bright midday sun from above & slightly forward: L = normalize(0.06, -0.80, 0.59)
  let lx = 0.06, ly = -0.80, lz = 0.59;
  let ndotl = max(0, nx * lx + ny * ly + nz * lz);

  // Zenith sky reflection vector (overhead blue sky dome + viewer Half-vector)
  // H_vec = normalize(L + V) where V = (0, 0, 1) -> normalize(0.04, -0.50, 0.86)
  let hx = 0.04, hy = -0.52, hz = 0.85;
  let ndoth = max(0, nx * hx + ny * hy + nz * hz);

  // Kajiya-Kay anisotropic hair sheen: specular peaks when hair tangent T is perpendicular to H_vec
  let tx = cos(tangentAngle);
  let ty = sin(tangentAngle);
  let tdoth = tx * hx + ty * hy;
  let sinTH = sqrt(max(0, 1 - tdoth * tdoth));
  let anisoSpec = pow(sinTH, 14) * pow(ndoth, 5.2);

  // Secondary warm subsurface / Marschner TRT copper scattering lobe around specular rim
  let copperScatter = pow(sinTH, 6) * pow(ndotl, 1.85) * (1 - 0.5 * pow(ndoth, 9));

  // Downward-facing dusky twilight bounce light (when ny > 0.22, facing warm ground & twilight horizon)
  let twilightBounce = pow(constrain((ny - 0.15) / 0.72, 0, 1), 1.45) * (0.45 + 0.55 * nz);

  // Flow-aligned ribbon modulation for readable streamlines at a distance
  let ribbon = getStreamlineRibbonVal(x, y);
  let lightLevel = ndotl * 0.82 + anisoSpec * 0.65 + (ribbon - 0.5) * 0.22 + jitter;

  // Color stops
  // 1. Cool Reflected Sky-Blue Specular Sheen (highest zenith-facing gloss)
  if (anisoSpec > 0.44 && ny < -0.12 && lightLevel > 0.64) {
    let skyPalette = ["#537596", "#6b91b5", "#84accf", "#9ec4e4", "#bad9f2"];
    let idx = constrain(floor(map(anisoSpec + jitter * 0.5, 0.44, 0.92, 0, skyPalette.length)), 0, skyPalette.length - 1);
    return { col: skyPalette[idx], type: "sky", lum: 0.9 };
  }

  // 2. Fiery Coppery & Burnished Gold Highlights (bright midday sun on glossy bay hair)
  if (lightLevel > 0.56 || (copperScatter > 0.48 && ny < 0.15)) {
    let copperPalette = ["#a83e18", "#c2511e", "#d96826", "#eb8334", "#f5a24d", "#fad82a20"];
    let validCopper = ["#a83e18", "#c2511e", "#d96826", "#eb8334", "#f5a24d", "#f7be6d"];
    let idx = constrain(floor(map(lightLevel + copperScatter * 0.3, 0.54, 1.15, 0, validCopper.length)), 0, validCopper.length - 1);
    return { col: validCopper[idx], type: "copper", lum: 0.75 };
  }

  // 3. Dusky Twilight Bounce Light (underbelly, behind elbow, lower flank fold)
  if (twilightBounce > 0.32 && lightLevel < 0.42) {
    let twilightPalette = ["#2d1d2b", "#3d283b", "#4f354a", "#614252", "#755248", "#8c6747"];
    let idx = constrain(floor(map(twilightBounce + ribbon * 0.25, 0.32, 0.95, 0, twilightPalette.length)), 0, twilightPalette.length - 1);
    return { col: twilightPalette[idx], type: "twilight", lum: 0.32 };
  }

  // 4. Rich Mahogany & Bay Midtones
  if (lightLevel > 0.30) {
    let mahoganyPalette = ["#4f1a0e", "#632011", "#782815", "#8c3119", "#9e3b1d"];
    let idx = constrain(floor(map(lightLevel, 0.30, 0.58, 0, mahoganyPalette.length)), 0, mahoganyPalette.length - 1);
    return { col: mahoganyPalette[idx], type: "mahogany", lum: 0.48 };
  }

  // 5. Burnt Umber, Espresso & Deep Core Shadows
  let umberPalette = ["#140806", "#1f0c08", "#2b110a", "#38170d", "#451c10"];
  let idx = constrain(floor(map(lightLevel, 0.02, 0.32, 0, umberPalette.length)), 0, umberPalette.length - 1);
  return { col: umberPalette[idx], type: "umber", lum: 0.18 };
}

// ============================================================================
// LAYER 1: WARM OCHRE PAPER GROUND
// ============================================================================

function drawOchrePaperGround() {
  // Base warm ochre paper tone
  background("#d5ae72");

  brush.noField();
  brush.noStroke();

  // Broad warm tonal variations across the ochre paper using fast washes
  brush.wash("#cba060", 65);
  brush.rect(0, 0, W, H, "corner");

  brush.wash("#e3be84", 55);
  brush.circle(580, 420, 520, 0.2);

  brush.wash("#bf9152", 48);
  brush.rect(0, 880, W, 320, "corner");

  brush.noWash();

  // Subtle laid-paper grain & tooth with ultra-light 2H and spray
  brush.set("2H", "#c4985a", 0.7);
  for (let i = 0; i < 240; i++) {
    let y = random(H);
    let x1 = random(0, W * 0.4);
    let x2 = x1 + random(250, 750);
    brush.line(x1, y, min(W, x2), y + random(-3, 3));
  }

  brush.set("2H", "#e6c68e", 0.55);
  for (let i = 0; i < 160; i++) {
    let y = random(H);
    let x1 = random(0, W * 0.5);
    let x2 = x1 + random(200, 600);
    brush.line(x1, y, min(W, x2), y + random(-2, 2));
  }

  // Fine mineral paper flecks
  brush.set("spray", "#b5874a", 0.8);
