// ============================================================================
// LAYER 2: VECTOR FIELD STUDY MARKS ON THE OCHRE MARGIN
// ============================================================================

function drawMarginVectorFieldStudy() {
  // Delicate architectural vector-field streamlines & tangent ticks on the ochre ground
  // near the horse's topline and belly contour, tying the study to the vector-field concept
  brush.field("equineCoat");

  for (let i = 0; i < 180; i++) {
    let x = random(30, W - 30);
    let topEdge = getTopEdge(x);
    let botEdge = getBottomEdge(x);

    // Place in upper paper margin or lower paper margin near silhouette
    let isTop = random() < 0.48;
    let y = isTop ? random(18, topEdge + 35) : random(botEdge - 35, H - 18);

    let ang = getCoatAngle(x, y);
    let col = isTop ? (random() < 0.5 ? "#9c7444" : "#7d5b3b") : (random() < 0.5 ? "#876142" : "#664938");
    brush.set("2H", col, random(0.45, 0.8));
    brush.flowLine(x, y, random(45, 115), ang);
  }

  brush.noField();

  // Subtle contour construction splines along topline and underline
  let topPts = [];
  let botPts = [];
  for (let x = 0; x <= W; x += 60) {
    topPts.push([x, getTopEdge(x), 0.5]);
    botPts.push([x, getBottomEdge(x), 0.5]);
  }
  brush.set("2H", "#8c6239", 0.65);
  brush.spline(topPts, 0.5);
  brush.spline(botPts, 0.5);
}

// ============================================================================
// STREAMLINE TRACER HELPER (RK2 INTEGRATION THROUGH VECTOR FIELD)
// ============================================================================

function traceStreamline(startX, startY, stepLen, numSteps, margin = 2, dirSign = 1) {
  let pts = [];
  let x = startX;
  let y = startY;

  for (let s = 0; s < numSteps; s++) {
    if (!isInsideHorse(x, y, margin)) break;

    // Taper pressure softly at start and end of each coloured-pencil stroke
    let t = s / max(1, numSteps - 1);
    let pressure = 0.32 + 0.85 * sin(t * 180);
    pts.push([x, y, pressure]);

    // RK2 midpoint step
    let a1 = getCoatAngle(x, y);
    let mx = x + dirSign * cos(a1) * (stepLen * 0.5);
    let my = y + dirSign * sin(a1) * (stepLen * 0.5);
    let a2 = getCoatAngle(mx, my);

    x += dirSign * cos(a2) * stepLen;
    y += dirSign * sin(a2) * stepLen;
  }
  return pts;
}

// ============================================================================
// LAYER 3: UNDERPAINTING FLOW (BROAD COLOURED-PENCIL & CHARCOAL BASE)
// ============================================================================

function drawUnderpaintingFlow() {
  brush.noField();

  // Warm base under-wash inside key shadow masses so darks have rich depth while midtones breathe ochre paper
  let totalBaseStrokes = 850;
  for (let i = 0; i < totalBaseStrokes; i++) {
    let x = random(-10, W + 10);
    let y = random(65, H - 40);
    if (!isInsideHorse(x, y, -4)) continue;

    let pts = traceStreamline(x, y, 22, floor(random(6, 11)), -2, random() < 0.5 ? 1 : -1);
    if (pts.length < 3) continue;

    let midPt = pts[floor(pts.length / 2)];
    let ang = getCoatAngle(midPt[0], midPt[1]);
    let shade = sampleCoatColor(midPt[0], midPt[1], ang, random(-0.06, 0.06));

    // Leave warm ochre paper breathing in the warm transition zones
    if (shade.type === "mahogany" && random() < 0.22) continue;

    let bName = shade.lum < 0.28 ? "charcoal" : "cpencil";
    let w = random(1.15, 1.95);
    brush.set(bName, shade.col, w);
    brush.spline(pts, 0.5);
  }
}

// ============================================================================
// LAYER 4: PRIMARY COLOURED-PENCIL COAT STREAMLINES
// ============================================================================

function drawPrimaryCoatStreamlines() {
  brush.noField();

  // Pass 4A: Structured grid-jittered long streamlines so coverage is complete and flow is crystal-clear
  let stepX = 19;
  let stepY = 17;

  for (let gx = -15; gx <= W + 15; gx += stepX) {
    for (let gy = 70; gy <= H - 30; gy += stepY) {
      let x = gx + random(-7, 7);
      let y = gy + random(-6, 6);
      if (!isInsideHorse(x, y, 2)) continue;

      let ribbon = getStreamlineRibbonVal(x, y);
      // Modulate density slightly by ribbon phase so streamlines read as distinct flowing locks at a distance
      if (ribbon < 0.24 && random() < 0.45) continue;

      let numSteps = floor(random(8, 15));
      let stepLen = random(15, 20);
      let pts = traceStreamline(x, y, stepLen, numSteps, 3, 1);
      if (pts.length < 3) continue;

      let midPt = pts[floor(pts.length / 2)];
      let ang = getCoatAngle(midPt[0], midPt[1]);
      let shade = sampleCoatColor(midPt[0], midPt[1], ang, (ribbon - 0.5) * 0.14 + random(-0.04, 0.04));

      let brushChoice = "cpencil";
      let weight = random(0.68, 1.18);

      if (shade.type === "umber") {
        brushChoice = random() < 0.45 ? "2B" : "cpencil";
        weight = random(0.75, 1.25);
      } else if (shade.type === "sky" || shade.type === "copper") {
        brushChoice = random() < 0.65 ? "cpencil" : "HB";
        weight = random(0.62, 1.05);
      }

      brush.set(brushChoice, shade.col, weight);
      brush.spline(pts, 0.5);
    }
  }

  // Pass 4B: Extra-long sweeping Hero Streamlines (220-340 px long) emphasizing pure flow at a distance
  for (let i = 0; i < 620; i++) {
    let x = random(0, W);
    let y = random(85, H - 50);
    if (!isInsideHorse(x, y, 4)) continue;

    let ribbon = getStreamlineRibbonVal(x, y);
    if (ribbon < 0.42) continue; // Concentrate along the crest of each hair fascicle

    let pts = traceStreamline(x, y, 18, floor(random(11, 18)), 3, 1);
    if (pts.length < 4) continue;

    let midPt = pts[floor(pts.length / 2)];
    let ang = getCoatAngle(midPt[0], midPt[1]);
    let shade = sampleCoatColor(midPt[0], midPt[1], ang, 0.06);

    brush.set("cpencil", shade.col, random(0.65, 1.05));
    brush.spline(pts, 0.55);
  }
}

// ============================================================================
// LAYER 5: SPIRAL COWLICKS (WHORLS) & FEATHERING RIDGES
// ============================================================================

function drawCowlickVortices() {
  brush.noField();

  for (let wIdx = 0; wIdx < WHORLS.length; wIdx++) {
    let w = WHORLS[wIdx];

    // Seed dense radial-spiral streamlines converging into / diverging from each cowlick center
    let numSpiralStrokes = wIdx < 2 ? 240 : 130;
    for (let i = 0; i < numSpiralStrokes; i++) {
      let angleAround = (i / numSpiralStrokes) * 360 + random(-4, 4);
      let distFromCenter = random(6, w.r * 0.95);
      let sx = w.x + cos(angleAround) * distFromCenter;
      let sy = w.y + sin(angleAround) * distFromCenter;

      if (!isInsideHorse(sx, sy, 2)) continue;

      // Shorter, tighter step length near the vortex core so the spiral curvature is crisp
      let stepLen = map(distFromCenter, 5, w.r, 6.5, 14.5);
      let steps = floor(random(7, 13));
      let dir = distFromCenter < 45 ? -1 : (random() < 0.6 ? 1 : -1);
      let pts = traceStreamline(sx, sy, stepLen, steps, 2, dir);
      if (pts.length < 3) continue;

      let midPt = pts[floor(pts.length / 2)];
      let ang = getCoatAngle(midPt[0], midPt[1]);

      // Enhance sculptural contrast around the cowlick rim (coppery-blue upper rim, dark umber core)
      let dyCore = midPt[1] - w.y;
      let dCore = dist(midPt[0], midPt[1], w.x, w.y);
      let whorlBias = 0;
      if (dCore < 22) {
        whorlBias = -0.35; // Dark skin/hair vortex pinpoint
      } else if (dCore < 85 && dyCore < 0) {
        whorlBias = 0.22; // Sunlit upper spiral crest
      } else if (dCore < 85 && dyCore > 0) {
        whorlBias = -0.14; // Shaded lower spiral rim
      }

      let shade = sampleCoatColor(midPt[0], midPt[1], ang, whorlBias + random(-0.04, 0.04));
      let bType = dCore < 45 ? "fine_pencil" : "cpencil";
      let bWeight = dCore < 45 ? random(0.65, 1.0) : random(0.55, 0.9);

      brush.set(bType, shade.col, bWeight);
      brush.spline(pts, 0.55);
    }

    // Crisp pinpoint center of the cowlick vortex (tiny ochre-skin glint + dark umber parting)
    brush.set("fine_pencil", "#160705", 0.95);
    for (let k = 0; k < 18; k++) {
      let a = k * 20 + random(-5, 5);
      let r1 = random(1.5, 5);
      let r2 = r1 + random(10, 22);
      let a2 = a + w.twist * 0.45;
      brush.line(
        w.x + cos(a) * r1,
        w.y + sin(a) * r1,
        w.x + cos(a2) * r2,
        w.y + sin(a2) * r2
      );
    }
    // Tiny warm ochre/copper highlight flecks on the upper lip of the whorl
    brush.set("fine_pencil", "#e89a48", 0.75);
    for (let k = 0; k < 12; k++) {
      let a = random(-155, -25);
      let r1 = random(8, 28);
      let r2 = r1 + random(12, 24);
      let a2 = a + w.twist * 0.4;
      brush.line(
        w.x + cos(a) * r1,
        w.y + sin(a) * r1,
        w.x + cos(a2) * r2,
        w.y + sin(a2) * r2
      );
    }
  }

  // Emphasize the converging feathering ridge descending from the Flank Whorl into the stifle fold
  for (let i = 0; i < 95; i++) {
    let sy = random(670, 915);
    let ridgeX = 912 + (sy - 668) * 0.24 + random(-45, 45);
    if (!isInsideHorse(ridgeX, sy, 2)) continue;

    let pts = traceStreamline(ridgeX, sy, 9, 8, 2, 1);
    if (pts.length < 3) continue;

    let isLeft = ridgeX < 912 + (sy - 668) * 0.24;
    let col = isLeft ? (random() < 0.5 ? "#d96b27" : "#789ec2") : (random() < 0.5 ? "#2b1109" : "#5e2011");
    brush.set("fine_pencil", col, random(0.65, 0.95));
    brush.spline(pts, 0.5);
  }
}

// ============================================================================
// LAYER 6: HIGH-GLOSS SKY-BLUE & COPPERY SHEEN PASS
// ============================================================================

function drawGlossySheenPass() {
  brush.noField();

  // Target the sunlit zenith-facing zones (withers, shoulder spine, upper barrel, ribs, point of hip, croup)
  for (let i = 0; i < 680; i++) {
    let x = random(15, W - 15);
    // Bias y toward the upper 65% of the horse where overhead midday light hits strongest
    let topY = getTopEdge(x);
    let botY = getBottomEdge(x);
    let y = topY + pow(random(), 1.35) * (botY - topY) * 0.82;
    if (!isInsideHorse(x, y, 4)) continue;

    let ang = getCoatAngle(x, y);
    let shade = sampleCoatColor(x, y, ang, 0.08);
    if (shade.type !== "sky" && shade.type !== "copper") continue;

    let pts = traceStreamline(x, y, 14, floor(random(6, 11)), 4, 1);
    if (pts.length < 3) continue;

    if (shade.type === "sky") {
      // Cool reflected zenith sky-blue highlight hairs
      let skyCols = ["#6d94ba", "#8bb2d6", "#a8ccf0", "#c7e2fc"];
      let c = skyCols[floor(random(skyCols.length))];
      brush.set(random() < 0.6 ? "fine_pencil" : "2H", c, random(0.55, 0.95));
      brush.spline(pts, 0.5);
    } else {
      // Luminous coppery-gold & burnished orange highlight hairs
      let copCols = ["#d45d20", "#e8782c", "#f5963d", "#fabe64"];
      let c = copCols[floor(random(copCols.length))];
      brush.set(random() < 0.55 ? "cpencil" : "fine_pencil", c, random(0.55, 0.9));
      brush.spline(pts, 0.5);
    }
  }
}

// ============================================================================
// LAYER 7: SUBCUTANEOUS VEINS (3D RELIEF + OVER-ARCHING HAIRS)
// ============================================================================

function precomputeVeinSegments() {
  veinSegments = [];
  for (let v = 0; v < VEIN_PATHS.length; v++) {
    let path = VEIN_PATHS[v];
    let p = path.pts;
    let totalSegments = (p.length - 1) * 10;

    for (let i = 0; i < p.length - 1; i++) {
      let p0 = p[max(0, i - 1)];
      let p1 = p[i];
      let p2 = p[i + 1];
      let p3 = p[min(p.length - 1, i + 2)];

      for (let step = 0; step < 10; step++) {
        let t1 = step / 10;
        let t2 = (step + 1) / 10;
        let xy1 = catmullRomPoint(p0, p1, p2, p3, t1);
        let xy2 = catmullRomPoint(p0, p1, p2, p3, t2);

        // Organic micro-wobble along the vein
        let prog = (i * 10 + step) / totalSegments;
        let radius = path.w * (1 - 0.55 * prog);
        veinSegments.push({
          x1: xy1[0],
          y1: xy1[1],
          x2: xy2[0],
          y2: xy2[1],
          mx: (xy1[0] + xy2[0]) * 0.5,
          my: (xy1[1] + xy2[1]) * 0.5,
          r: radius
        });
      }
    }
  }
}

function catmullRomPoint(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * t +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
  return [x, y];
}

function drawSubcutaneousVeins() {
  brush.noField();

  for (let i = 0; i < veinSegments.length; i++) {
    let seg = veinSegments[i];
    if (!isInsideHorse(seg.mx, seg.my, 8)) continue;

    // Direction of vein segment & normal vector pointing downward/upward
    let vdx = seg.x2 - seg.x1;
    let vdy = seg.y2 - seg.y1;
    let vlen = max(0.001, sqrt(vdx * vdx + vdy * vdy));
    let nx = -vdy / vlen;
    let ny = vdx / vlen;
    // Ensure (nx, ny) points toward the upper/sunlit side (negative y)
    if (ny > 0) {
      nx = -nx;
      ny = -ny;
    }

    let r = seg.r;

    // 1. Underside shadow trough of the raised vein ridge (opposite overhead midday sun)
    brush.set("fine_pencil", "#170705", r * 0.34);
    brush.line(
      seg.x1 - nx * r * 0.85,
      seg.y1 - ny * r * 0.85,
      seg.x2 - nx * r * 0.85,
      seg.y2 - ny * r * 0.85
    );

    brush.set("cpencil", "#2e1109", r * 0.28);
    brush.line(
      seg.x1 - nx * r * 1.35,
      seg.y1 - ny * r * 1.35,
      seg.x2 - nx * r * 1.35,
      seg.y2 - ny * r * 1.35
    );

    // 2. Sunlit upper bevel of the vein ridge (catching copper or sky-blue sheen)
    let coatAng = getCoatAngle(seg.mx, seg.my);
    let localShade = sampleCoatColor(seg.mx, seg.my, coatAng, 0.24);
    let bevelCol =
      localShade.type === "sky"
        ? "#9ec4e6"
        : localShade.lum > 0.45
        ? "#f0933e"
        : "#b84b1e";

    brush.set("fine_pencil", bevelCol, r * 0.32);
    brush.line(
      seg.x1 + nx * r * 0.65,
      seg.y1 + ny * r * 0.65,
      seg.x2 + nx * r * 0.65,
      seg.y2 + ny * r * 0.65
    );

    // 3. Individual short coat hairs arching directly OVER the vein ridge in the local coat direction
    let hx = cos(coatAng);
    let hy = sin(coatAng);
    let hairLen = r * 2.4 + 4;

    // Upper sunlit half of the hair arching onto the vein crest
    brush.set("fine_pencil", bevelCol, random(0.45, 0.72));
    brush.line(
      seg.mx - hx * hairLen * 0.55 + nx * r * 0.3,
      seg.my - hy * hairLen * 0.55 + ny * r * 0.3,
      seg.mx + nx * r * 0.1,
      seg.my + ny * r * 0.1
    );

    // Lower shaded half of the hair descending off the vein ridge
    brush.set("fine_pencil", "#1e0a07", random(0.48, 0.75));
    brush.line(
      seg.mx - nx * r * 0.1,
      seg.my - ny * r * 0.1,
      seg.mx + hx * hairLen * 0.6 - nx * r * 0.4,
      seg.my + hy * hairLen * 0.6 - ny * r * 0.4
    );
  }
}

// ============================================================================
// LAYER 8: DRIED SWEAT LINE UNDER THE GIRTH AREA (PHOTOGRAPHIC DETAIL)
// ============================================================================

function getGirthCenterX(y) {
  // Runs from below the saddle flap edge (x ~ 410, y ~ 410) down into the girth notch behind the elbow (x ~ 358, y ~ 965)
  let t = constrain((y - 390) / (965 - 390), 0, 1);
  return 412 - 54 * pow(t, 0.85) + 12 * sin(t * 260);
}

function getGirthHalfWidth(y) {
  // Girth strap widens slightly across the middle barrel and narrows toward the buckle/elbow
  let t = constrain((y - 390) / (965 - 390), 0, 1);
  return 34 * sin(t * 150 + 18) + 12;
}

function drawDriedSweatGirthLine() {
  brush.noField();

  let yStart = 395;
  let yEnd = 962;

  // 1. Compressed, slightly darkened & matted hair inside the girth band where the cinch pressed
  for (let y = yStart; y <= yEnd; y += 4.5) {
    let cx = getGirthCenterX(y);
    let hw = getGirthHalfWidth(y);

    for (let k = 0; k < 4; k++) {
      let gx = cx + random(-hw * 0.92, hw * 0.92);
      let gy = y + random(-3, 3);
      if (!isInsideHorse(gx, gy, 3)) continue;

      // Matted hair clumps clump together at a slightly steeper downward angle than the surrounding glossy coat
      let baseAng = getCoatAngle(gx, gy) + random(6, 22);
      let clumpLen = random(14, 28);

      // Dark damp/matted bay hair spike
      let darkCol = random() < 0.5 ? "#1f0b07" : "#33140b";
      brush.set("fine_pencil", darkCol, random(0.65, 1.05));
      brush.line(
        gx,
        gy,
        gx + cos(baseAng) * clumpLen,
        gy + sin(baseAng) * clumpLen
      );

      // Tiny V-shaped matted tuft convergence at the tip of the clump
      let sideAng = baseAng - random(12, 24);
      brush.line(
        gx + random(-3, 3),
        gy + random(3, 6),
        gx + cos(baseAng) * clumpLen,
        gy + sin(baseAng) * clumpLen
      );
    }
  }

  // 2. The Crystalline White / Warm-Buff / Slate Dried Sweat Salt Crust along both edges of the girth mark
  //    (anterior edge behind the elbow + posterior edge on the barrel + upper saddle-pad corner)
  for (let y = yStart; y <= yEnd; y += 2.2) {
    let cx = getGirthCenterX(y);
    let hw = getGirthHalfWidth(y);
    let nJagged1 = (noise(y * 0.045, 10) - 0.5) * 18;
    let nJagged2 = (noise(y * 0.045, 90) - 0.5) * 18;

    let frontEdgeX = cx - hw + nJagged1;
    let backEdgeX = cx + hw + nJagged2;

    let edges = [frontEdgeX, backEdgeX];
    // At the top of the girth (around y = 395..430), connect the crust under the saddle-pad corner
    if (y < 428) {
      edges.push(lerp(frontEdgeX, backEdgeX, random()));
    }

    for (let e = 0; e < edges.length; e++) {
      let ex = edges[e] + random(-3.5, 3.5);
      let ey = y + random(-2, 2);
      if (!isInsideHorse(ex, ey, 4)) continue;

      let coatAng = getCoatAngle(ex, ey);

      // Dark matted shadow base right under the crust
      brush.set("fine_pencil", "#190906", random(0.7, 1.1));
      brush.line(
        ex + 1.5,
        ey + 2.2,
        ex + cos(coatAng) * random(8, 16) + 1.5,
        ey + sin(coatAng) * random(8, 16) + 2.2
      );

      // Crusty salt-stiffened hair spikes & chalky salt granules
      // In bright midday light, the dried salt crust catches warm ivory-ochre on top and cool sky-grey in shadow
      let isLowerShadow = ey > 780;
      let saltCols = isLowerShadow
        ? ["#9da7b2", "#b8b2a6", "#d1c7b4", "#e3dac8"]
        : ["#cbbca2", "#dfd4be", "#eee6d5", "#faf5ea", "#b3c2d1"];
      let sCol = saltCols[floor(random(saltCols.length))];

      brush.set("fine_pencil", sCol, random(0.45, 0.92));
      let spikeLen = random(5, 15);
      let spikeAng = coatAng + random(-14, 18);
      brush.line(
        ex,
        ey,
        ex + cos(spikeAng) * spikeLen,
        ey + sin(spikeAng) * spikeLen
      );

      // Tiny crystalline salt bead / fleck at the base or tip of the matted hair
      if (random() < 0.65) {
        let bx = ex + random(-4, 4);
        let by = ey + random(-3, 3);
        brush.set("rotring", "#f5efe2", random(0.35, 0.65));
        brush.line(bx, by, bx + random(1.2, 3.2), by + random(-1.5, 2.0));
      }
    }
  }

  // 3. Dried vertical sweat rivulets / tracks trickling down toward the underline behind the elbow
  let trickleXs = [348, 366, 384, 405, 424];
  for (let t = 0; t < trickleXs.length; t++) {
    let tx = trickleXs[t];
    let tyStart = random(640, 770);
    let tyEnd = min(getBottomEdge(tx) - 8, tyStart + random(110, 195));

    for (let y = tyStart; y < tyEnd; y += 3.5) {
      let wx = tx + (noise(y * 0.03, t * 20) - 0.5) * 14;
      if (!isInsideHorse(wx, y, 4)) continue;

      // Dark matted center of dried sweat rivulet
      brush.set("fine_pencil", "#1c0a07", 0.75);
      brush.line(wx, y, wx + random(-1.5, 1.5), y + 5.5);

      // Twin crusty white-buff salt rims flanking the dried trickle
      if (random() < 0.78) {
        brush.set("fine_pencil", "#e0d5c0", 0.52);
        brush.line(wx - 2.4, y, wx - 2.0, y + 3.5);
        brush.set("fine_pencil", "#c7bba6", 0.48);
        brush.line(wx + 2.4, y, wx + 2.0, y + 3.5);
      }
    }
  }
}

// ============================================================================
// LAYER 9: PHOTOGRAPHIC FLY PERCHED ON THE BARREL
// ============================================================================

function drawPerchedFly(fx, fy) {
  brush.noField();

  // The fly is oriented facing up-left (-128 deg), perched on the sunlit barrel near a vein branch
  let bodyAngle = -128; // degrees

  push();
  translate(fx, fy);
  rotate(bodyAngle);

  // Local coordinates: +X is head direction, -X is abdomen tip, Y is left/right lateral
  // Overhead midday sun is in direction (-18, +14) in world space -> cast shadow offset below the fly
  let shX = -4.5;
  let shY = 5.5;

  // 1. Crisp Cast Shadow of legs, body, and wings on the glossy bay coat
  brush.set("fine_pencil", "#0f0403", 1.15);
  // Body shadow
  for (let sy = -6; sy <= 6; sy += 1.4) {
    let halfLen = 14 * sqrt(max(0, 1 - pow(sy / 6.5, 2)));
    brush.line(shX - halfLen, shY + sy, shX + halfLen * 0.85, shY + sy);
  }

  // Define the 6 jointed legs: [mountX, mountY, kneeX, kneeY, ankleX, ankleY, clawX, clawY]
  let legs = [
    // Front pair
    [7, -4, 14, -12, 19, -16, 22, -18],
    [7, 4, 14, 12, 19, 16, 22, 18],
    // Middle pair
    [2, -5, 3, -15, 0, -22, -2, -25],
    [2, 5, 3, 15, 0, 22, -2, 25],
    // Hind pair
    [-4, -5, -11, -14, -19, -19, -24, -21],
    [-4, 5, -11, 14, -19, 19, -24, 21]
  ];

  // Cast shadow of the 6 jointed legs on the coat hairs
  brush.set("rotring", "#120504", 0.52);
  for (let i = 0; i < legs.length; i++) {
    let L = legs[i];
    // Shadow touches the coat at the claw tip and separates toward the body
    brush.line(L[0] + shX * 0.8, L[1] + shY * 0.8, L[2] + shX * 0.6, L[3] + shY * 0.6);
    brush.line(L[2] + shX * 0.6, L[3] + shY * 0.6, L[4] + shX * 0.25, L[5] + shY * 0.25);
    brush.line(L[4] + shX * 0.25, L[5] + shY * 0.25, L[6], L[7]);
  }

  // 2. Actual 6 Jointed Legs (Femur, Tibia, Tarsi) with tiny specular glints
  for (let i = 0; i < legs.length; i++) {
    let L = legs[i];
    // Dark chitin femur & tibia
    brush.set("rotring", "#1a0d09", 0.68);
    brush.line(L[0], L[1], L[2], L[3]);
    brush.set("rotring", "#2b160f", 0.52);
    brush.line(L[2], L[3], L[4], L[5]);
    brush.set("rotring", "#1a0d09", 0.38);
    brush.line(L[4], L[5], L[6], L[7]);

    // Tiny sunlit copper/sky specular glint along upper edge of femur/tibia
    brush.set("fine_pencil", "#b8cde0", 0.32);
    brush.line(L[0], L[1] - 0.5, L[2], L[3] - 0.5);
  }

  // 3. Segmented Abdomen (x from -16 to +1, width ~ 11)
  for (let ax = -16; ax <= 1; ax += 0.9) {
    let normX = (ax + 7.5) / 8.5;
    let hw = 6.2 * sqrt(max(0, 1 - normX * normX));
    // Tergite segmentation bands every 3.2 units
    let isBand = sin(ax * 58) > 0.35;
    let abCol = isBand ? "#1b0d08" : "#4a2513";
    brush.set("fine_pencil", abCol, 0.72);
    brush.line(ax, -hw, ax, hw);

    // Translucent amber-copper lateral spot on horsefly abdomen
    if (ax > -11 && ax < -2 && !isBand) {
      brush.set("fine_pencil", "#c46828", 0.55);
      brush.line(ax, -hw * 0.85, ax, -hw * 0.35);
      brush.line(ax, hw * 0.35, ax, hw * 0.85);
    }
  }

  // 4. Thorax (x from 0 to +9, width ~ 10) with characteristic dorsal longitudinal stripes
  for (let tx = -0.5; tx <= 8.5; tx += 0.8) {
    let normX = (tx - 4.0) / 4.8;
    let hw = 5.4 * sqrt(max(0, 1 - normX * normX));
    brush.set("fine_pencil", "#1e1614", 0.78);
    brush.line(tx, -hw, tx, hw);
  }
  // Pale grey-buff dorsal pruinose stripes on the horsefly thorax
  let stripeYs = [-2.6, 0, 2.6];
  for (let s = 0; s < stripeYs.length; s++) {
    brush.set("fine_pencil", "#9e9589", 0.45);
    brush.line(0.5, stripeYs[s], 7.5, stripeYs[s]);
  }
  // Bright zenith sky-blue & white specular highlight dot on the convex dome of the thorax
  brush.set("fine_pencil", "#cde4fa", 0.65);
  brush.line(3.2, -1.5, 5.8, -1.0);
  brush.set("rotring", "#ffffff", 0.42);
  brush.line(4.0, -1.2, 5.2, -0.9);

  // 5. Head & Iridescent Compound Eyes (x from +8.5 to +13)
  // Left compound eye
  brush.set("fine_pencil", "#142620", 0.9);
  brush.line(8.8, -4.2, 11.8, -1.2);
  brush.set("fine_pencil", "#3b8c6e", 0.58);
  brush.line(9.5, -3.6, 11.4, -1.6);
  brush.set("rotring", "#a8e6cf", 0.38);
  brush.line(10.2, -3.2, 11.2, -2.0);

  // Right compound eye
  brush.set("fine_pencil", "#142620", 0.9);
  brush.line(8.8, 4.2, 11.8, 1.2);
  brush.set("fine_pencil", "#3b8c6e", 0.58);
  brush.line(9.5, 3.6, 11.4, 1.6);
  brush.set("rotring", "#c95b2b", 0.38);
  brush.line(10.0, 2.8, 11.2, 1.8);

  // Short antennae / proboscis at the front of the head
  brush.set("rotring", "#160a07", 0.36);
  brush.line(11.8, -0.8, 14.2, -1.8);
  brush.line(11.8, 0.8, 14.2, 1.8);

  // 6. Translucent Scissored Wings (V-shaped over abdomen, catching iridescent sky & gold sheen)
  let wingSigns = [-1, 1];
  for (let w = 0; w < 2; w++) {
    let sgn = wingSigns[w];
    push();
    translate(4.5, sgn * 2.2);
    rotate(sgn * 19); // Scissored V-angle backward

    // Translucent smoky-sky membrane shimmer (fine parallel strokes)
    for (let wy = -3.8; wy <= 3.8; wy += 0.85) {
      let wLen = 23 * sqrt(max(0, 1 - pow(wy / 4.2, 2)));
      let memCol = abs(wy) < 1.6 ? "#bdd9f2" : "#dfd3c3";
      brush.set("fine_pencil", memCol, 0.38);
      brush.line(-wLen, wy, -2, wy * 0.4);
    }

    // Iridescent sunlit interference flash across the wing blade
    brush.set("fine_pencil", "#e8f4ff", 0.52);
    brush.line(-15, -1.2, -7, -0.4);
    brush.set("fine_pencil", "#f7d488", 0.42);
    brush.line(-18, 0.6, -10, 1.2);

    // Razor-sharp chitin wing veins (costa, subcosta, radial & medial veins)
    brush.set("rotring", "#2b170e", 0.38);
    // Leading costal edge
    brush.line(0, 0, -22, sgn * 2.4);
    // Trailing edge curve
    brush.set("rotring", "#4a2c1d", 0.26);
    brush.line(-22, sgn * 2.4, -18, -sgn * 2.6);
    brush.line(-18, -sgn * 2.6, -2, -sgn * 1.2);
    // Internal branching wing venation
    brush.set("rotring", "#331b11", 0.28);
    brush.line(-1, 0, -19, sgn * 0.9);
    brush.line(-4, 0, -17, -sgn * 0.6);
    brush.line(-7, 0, -15, -sgn * 1.9);
    // Cross-vein of the discal cell
    brush.line(-11, sgn * 0.5, -12, -sgn * 1.2);

    pop();
  }

  pop();
}

// ============================================================================
// LAYER 10: CONTOUR HAIR-EDGE DEFINITION & FINAL MICRO-HIGHLIGHTS
// ============================================================================

function drawContourFinish() {
  brush.noField();

  // Crisp hair-by-hair topline & underline silhouette transition against the warm ochre paper
  for (let x = 8; x < W - 8; x += 4.5) {
    // 1. Topline (Withers -> Back -> Croup): lit brightly from above by midday sun & blue sky
    let ty = getTopEdge(x);
    let tAng = getCoatAngle(x, ty + 4);
    let isSkyCrest = (x < 260 || x > 860) && random() < 0.55;
    let topCol = isSkyCrest
      ? (random() < 0.5 ? "#8cb4d9" : "#b5d6f5")
      : (random() < 0.6 ? "#e88231" : "#f5aa52");

    brush.set("fine_pencil", topCol, random(0.55, 0.95));
    brush.line(
      x,
      ty,
      x + cos(tAng) * random(18, 36),
      ty + sin(tAng) * random(18, 36)
    );

    // 2. Underline (Elbow -> Girth -> Belly -> Flank Fold -> Stifle): dusky twilight & burnt umber edge
    let by = getBottomEdge(x);
    let bAng = getCoatAngle(x, by - 4);
    let botCol = random() < 0.55 ? "#29120b" : (random() < 0.5 ? "#493245" : "#694a3c");

    brush.set("fine_pencil", botCol, random(0.6, 1.0));
    brush.line(
      x,
      by,
      x + cos(bAng) * random(16, 32),
      by + sin(bAng) * random(16, 32)
    );
  }
}

