// Material Constants
const MAT_EMPTY = 0;
const MAT_COUNTER = 1;
const MAT_PORCELAIN = 2;
const MAT_CREMA = 3;
const MAT_SUGAR = 4;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42);
  noiseSeed(42);

  // Register custom alcohol-marker chisel nib & ultra-clean fineliner
  brush.add("chisel_marker", {
    type: "marker",
    weight: 1.6,
    scatter: 0.03,
    opacity: 42,
