    type: "default",
    weight: 0.36,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 0.15,
    opacity: 155,
    spacing: 0.25,
    pressure: [0.95, 1.0, 0.95],
    noise: 0.04
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Deep Black Lacquer Studio Ground
  background("#0a0d13");
  brush.noStroke();
  brush.wash("#0b0f16", 255);
  brush.rect(0, 0, width, height, "corner");

  // Subtle horizontal lacquer sheen streaks in the dark background
  brush.set("chisel_marker", "#121822", 2.4);
  for (let i = 0; i < 48; i++) {
    let y = map(i, 0, 47, 40, height - 40);
    let x1 = random(0, 260);
    let x2 = width - random(0, 260);
    brush.line(x1, y, x2, y + random(-3, 3));
  }

  // 2. Projection Parameters: Low Three-Quarter Angle across Counter
  const theta = 33.0; // Three-quarter horizontal rotation (degrees)
  const alpha = 23.5; // Low camera elevation angle (degrees)
  const S = 11.4;     // Voxel grid scale in pixels
  const CX = 612;     // Screen X of world origin (0,0,0)
  const CY = 688;     // Screen Y of world origin (0,0,0)

  const cosT = cos(theta), sinT = sin(theta);
  const cosA = cos(alpha), sinA = sin(alpha);

  // Screen basis vectors for (+1,0,0), (0,+1,0), (0,0,+1)
  const ex_x = S * cosT,        ex_y = S * sinT * sinA;
  const ey_x = -S * sinT,       ey_y = S * cosT * sinA;
  const ez_x = 0.0,             ez_y = -S * cosA;

  // Exact 3D camera viewing ray direction (increasing toward viewer)
  const Vx = sinT * cosA;
  const Vy = cosT * cosA;
  const Vz = sinA;

  function project(x, y, z) {
    return [
      CX + x * ex_x + y * ey_x + z * ez_x,
      CY + x * ex_y + y * ey_y + z * ez_y
    ];
  }

  // 3. Build 3D Voxel Grid
  const X_MIN = -48, X_MAX = 50;
  const Y_MIN = -48, Y_MAX = 52;
  const Z_MIN = 0,   Z_MAX = 50;
  const NX = X_MAX - X_MIN + 1;
  const NY = Y_MAX - Y_MIN + 1;
  const NZ = Z_MAX - Z_MIN + 1;

  const gridMat = new Uint8Array(NX * NY * NZ);
  const gridId  = new Int16Array(NX * NY * NZ);
  const normX   = new Float32Array(NX * NY * NZ);
  const normY   = new Float32Array(NX * NY * NZ);
  const normZ   = new Float32Array(NX * NY * NZ);

  function idx(x, y, z) {
    return ((x - X_MIN) * NY + (y - Y_MIN)) * NZ + (z - Z_MIN);
  }

  function inBounds(x, y, z) {
    return x >= X_MIN && x <= X_MAX && y >= Y_MIN && y <= Y_MAX && z >= Z_MIN && z <= Z_MAX;
  }

  function getMat(x, y, z) {
    if (!inBounds(x, y, z)) return MAT_EMPTY;
    return gridMat[idx(x, y, z)];
  }

  function setVoxel(x, y, z, mat, id, nx, ny, nz) {
    if (!inBounds(x, y, z)) return;
    let i = idx(x, y, z);
    gridMat[i] = mat;
    gridId[i] = id;
    let len = Math.hypot(nx, ny, nz) || 1;
    normX[i] = nx / len;
    normY[i] = ny / len;
    normZ[i] = nz / len;
  }

  // --- Scene Element A: Demitasse Cup, Saucer, Handle & Espresso Crema ---
  const cupCX = -8.0, cupCY = -12.0;
  const phiH = -16.0;
  const uHx = cos(phiH), uHy = sin(phiH);
  const vHx = -sin(phiH), vHy = cos(phiH);

  // Precompute handle spine points for fast distance queries
  const handlePts = [];
  for (let i = 0; i <= 40; i++) {
    let t = i / 40.0;
    let ang = map(t, 0, 1, -78, 95);
    let u = 20.2 + 13.8 * Math.pow(cos(ang), 0.85);
    let z = 29.0 - 13.0 * sin(ang) + 1.8 * cos(ang * 0.5);
    handlePts.push({ u, z, t });
  }

  for (let x = -46; x <= 32; x++) {
    for (let y = -46; y <= 26; y++) {
      let dx = x - cupCX;
      let dy = y - cupCY;
      let r = Math.hypot(dx, dy);

      for (let z = 1; z <= 48; z++) {
        // 1) Saucer (z in 1..10, r <= 36.8)
        if (z <= 11 && r <= 36.8) {
          let isSaucer = false;
          let snx = dx, sny = dy, snz = 18.0;
          // Foot ring
          if (z <= 2 && r >= 13.2 && r <= 17.5) {
            isSaucer = true;
          }
          // Center well flat
          if (z >= 2 && z <= 3 && r <= 15.2) {
            isSaucer = true;
            snx = 0; sny = 0; snz = 1;
          }
          // Raised well ridge
          if (z >= 2 && z <= 4 && r >= 14.2 && r <= 16.6) {
            isSaucer = true;
            snx = (r - 15.4) * dx; sny = (r - 15.4) * dy; snz = 6.0;
          }
          // Flared saucer wing
          if (r >= 14.8 && r <= 36.8) {
            let tr = (r - 14.8) / 22.0;
            let zCenter = 2.8 + 6.0 * Math.pow(tr, 1.32);
            let halfThick = r > 34.5 ? 1.35 : 1.15;
            if (Math.abs(z - zCenter) <= halfThick) {
              isSaucer = true;
              if (z >= zCenter - 0.2) {
                // Upper concave surface normal points inward and up
                snx = -0.32 * dx; sny = -0.32 * dy; snz = r + 1.0;
              } else {
                // Underside normal points outward and down
                snx = 0.55 * dx; sny = 0.55 * dy; snz = -0.35 * r;
              }
            }
          }
          if (isSaucer) {
            setVoxel(x, y, z, MAT_PORCELAIN, 1, snx, sny, snz);
          }
        }

        // 2) Demitasse Cup Body (z in 3..47)
        if (z >= 3 && z <= 47 && r <= 25.0) {
          let t = (z - 3.0) / 44.0;
          let rOut = 13.2 + 10.8 * Math.pow(t, 0.88);
          if (z === 47) rOut -= 0.35; // Rounded top lip
          let rIn = z < 11 ? 0.0 : (rOut - 3.4) * Math.min(1.0, Math.pow((z - 10.0) / 6.0, 0.45));

          if (r <= rOut && r >= rIn) {
            let cnx = dx, cny = dy, cnz = -0.22 * r;
            if (z >= 46) {
              // Top rolled lip normal points upward
              let midR = (rOut + rIn) * 0.5;
              let dr = r - midR;
              cnx = dx * (dr / 2.0);
              cny = dy * (dr / 2.0);
              cnz = Math.max(2.0, r * 0.85);
            } else if (r < rIn + 1.5 && z >= 11) {
              // Inner porcelain wall normal points inward toward center
              cnx = -dx;
              cny = -dy;
              cnz = 0.25 * r;
            }
            setVoxel(x, y, z, MAT_PORCELAIN, 2, cnx, cny, cnz);
          } else if (z >= 35 && r < rIn) {
            // 3) Espresso Crema Meniscus inside the cup
            let normR = r / Math.max(1.0, rIn);
            let ripple = 0.25 * sin(x * 24 + y * 18);
            let zMeniscus = 39.8 + 2.35 * Math.pow(normR, 3.2) + ripple;
            if (z <= zMeniscus && z >= zMeniscus - 3.2) {
              // Concave meniscus normal tilts slightly inward near rim
              let mnx = -0.18 * dx * normR;
              let mny = -0.18 * dy * normR;
              let mnz = 1.0;
              setVoxel(x, y, z, MAT_CREMA, 3, mnx, mny, mnz);
            }
          }
        }

        // 4) Demitasse Ear Handle (z in 13..44)
        if (z >= 13 && z <= 44 && r >= 15.0 && r <= 37.5) {
          let u = dx * uHx + dy * uHy;
          let v = dx * vHx + dy * vHy;
          if (u >= 14.0 && Math.abs(v) <= 3.1) {
            let minD = 999.0;
            let bestPt = null;
            for (let k = 0; k < handlePts.length; k++) {
              let hp = handlePts[k];
              let du = u - hp.u;
              let dz = z - hp.z;
              let d = Math.hypot(du, dz * 0.92);
              if (d < minD) {
                minD = d;
                bestPt = hp;
              }
            }
            // Elliptical strap cross-section
            let strapDist = Math.hypot(minD / 2.35, v / 2.75);
            if (strapDist <= 1.0) {
              let hnx = (u - bestPt.u) * uHx + (v * 0.8) * vHx;
              let hny = (u - bestPt.u) * uHy + (v * 0.8) * vHy;
              let hnz = (z - bestPt.z);
              setVoxel(x, y, z, MAT_PORCELAIN, 4, hnx, hny, hnz);
            }
          }
        }
      }
    }
  }

  // --- Scene Element B: Tumbled Heap of 17 Sugar Cubes + Loose Crystals ---
  const sugarCubes = [
    // Layer 1: Base cubes on counter & leaning on saucer rim
    { id: 10, cx: 10.0,  cy: 16.0, cz: 5.0, hx: 5.6, hy: 5.6, hz: 5.0, yaw: 18,  pitch: 0,   roll: 0 },
    { id: 11, cx: -2.0,  cy: 20.5, cz: 5.0, hx: 5.6, hy: 5.5, hz: 5.0, yaw: -27, pitch: 0,   roll: 0 },
    { id: 12, cx: 21.5,  cy: 14.5, cz: 5.0, hx: 5.5, hy: 5.6, hz: 5.0, yaw: 41,  pitch: 0,   roll: 0 },
    { id: 13, cx: 14.0,  cy: 27.5, cz: 5.0, hx: 5.6, hy: 5.6, hz: 5.0, yaw: -14, pitch: 0,   roll: 0 },
    { id: 14, cx: 2.0,   cy: 31.5, cz: 5.0, hx: 5.5, hy: 5.6, hz: 5.0, yaw: 33,  pitch: 0,   roll: 0 },
    { id: 15, cx: -10.5, cy: 29.0, cz: 5.0, hx: 5.6, hy: 5.5, hz: 5.0, yaw: 12,  pitch: 0,   roll: 0 },
    { id: 16, cx: 26.5,  cy: 26.5, cz: 5.0, hx: 5.6, hy: 5.6, hz: 5.0, yaw: -36, pitch: 0,   roll: 0 },
    // Cube 17 propped up against the front-left porcelain saucer rim
    { id: 17, cx: 0.5,   cy: 9.2,  cz: 7.4, hx: 5.5, hy: 5.5, hz: 4.9, yaw: 24,  pitch: -28, roll: 14 },

    // Layer 2: Tumbled mid-tier cubes tilted at 3D angles
    { id: 18, cx: 8.5,   cy: 21.0, cz: 14.3, hx: 5.5, hy: 5.5, hz: 5.0, yaw: 36,  pitch: 18,  roll: -15 },
    { id: 19, cx: -3.5,  cy: 25.5, cz: 14.1, hx: 5.5, hy: 5.5, hz: 4.9, yaw: -25, pitch: -21, roll: 17 },
    { id: 20, cx: 19.2,  cy: 20.5, cz: 13.9, hx: 5.5, hy: 5.5, hz: 4.9, yaw: -19, pitch: 24,  roll: 14 },
    { id: 21, cx: 11.2,  cy: 31.2, cz: 13.7, hx: 5.4, hy: 5.5, hz: 4.9, yaw: 29,  pitch: -17, roll: -22 },
    { id: 22, cx: -9.5,  cy: 19.5, cz: 12.2, hx: 5.3, hy: 5.4, hz: 4.8, yaw: 44,  pitch: 26,  roll: -12 },

    // Layer 3: High crown cubes catching direct upper-left key light
    { id: 23, cx: 4.8,   cy: 23.0, cz: 22.8, hx: 5.4, hy: 5.4, hz: 4.9, yaw: -31, pitch: 27,  roll: 21 },
    { id: 24, cx: 14.2,  cy: 23.2, cz: 21.6, hx: 5.3, hy: 5.4, hz: 4.8, yaw: 17,  pitch: -23, roll: -18 },

    // Foreground & side tumbled outlier sugar cubes
    { id: 25, cx: 34.5,  cy: 18.5, cz: 5.0, hx: 5.5, hy: 5.5, hz: 5.0, yaw: 53,  pitch: 0,   roll: 0 },
    { id: 26, cx: 22.0,  cy: 38.5, cz: 5.0, hx: 5.5, hy: 5.5, hz: 4.9, yaw: -22, pitch: 0,   roll: 0 },
    { id: 27, cx: -17.5, cy: 18.0, cz: 5.0, hx: 5.4, hy: 5.4, hz: 4.9, yaw: 62,  pitch: 0,   roll: 0 }
  ];

  // Helper: 3D rotation matrix & inverse for each sugar cube
  function buildRotMatrix(yaw, pitch, roll) {
    let cy = cos(yaw), sy = sin(yaw);
    let cp = cos(pitch), sp = sin(pitch);
    let cr = cos(roll), sr = sin(roll);
    // R = Rz(yaw) * Ry(pitch) * Rx(roll)
    return [
      cy * cp, cy * sp * sr - sy * cr, cy * sp * cr + sy * sr,
      sy * cp, sy * sp * sr + cy * cr, sy * sp * cr - cy * sr,
      -sp,     cp * sr,                cp * cr
    ];
  }

  for (let c of sugarCubes) {
    let R = buildRotMatrix(c.yaw, c.pitch, c.roll);
    let bound = Math.ceil(Math.hypot(c.hx, c.hy, c.hz)) + 1;
    let x0 = Math.max(X_MIN, Math.floor(c.cx - bound));
    let x1 = Math.min(X_MAX, Math.ceil(c.cx + bound));
    let y0 = Math.max(Y_MIN, Math.floor(c.cy - bound));
    let y1 = Math.min(Y_MAX, Math.ceil(c.cy + bound));
    let z0 = Math.max(1,     Math.floor(c.cz - bound));
    let z1 = Math.min(Z_MAX, Math.ceil(c.cz + bound));

    for (let x = x0; x <= x1; x++) {
      for (let y = y0; y <= y1; y++) {
        for (let z = z0; z <= z1; z++) {
          if (getMat(x, y, z) !== MAT_EMPTY) continue;
          let dx = x - c.cx;
          let dy = y - c.cy;
          let dz = z - c.cz;
          // Transform by R^T into local sugar cube coordinates
          let lx = R[0] * dx + R[3] * dy + R[6] * dz;
          let ly = R[1] * dx + R[4] * dy + R[7] * dz;
          let lz = R[2] * dx + R[5] * dy + R[8] * dz;

          let ax = Math.abs(lx) / c.hx;
          let ay = Math.abs(ly) / c.hy;
          let az = Math.abs(lz) / c.hz;

          // Subtle crystalline edge chipping on extreme corners
          let cornerSum = Math.max(0, ax - 0.78) + Math.max(0, ay - 0.78) + Math.max(0, az - 0.78);
          let hash = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719 + c.id * 5.1) * 43758.5453;
          let frac = hash - Math.floor(hash);
          let maxA = Math.max(ax, ay, az);

          if (maxA <= 1.0 && !(cornerSum > 0.46 && frac > 0.45)) {
            // Determine dominant local macro-face normal of the rotated sugar cube
            let lnx = 0, lny = 0, lnz = 0;
            if (ax >= ay && ax >= az) lnx = lx >= 0 ? 1 : -1;
            else if (ay >= ax && ay >= az) lny = ly >= 0 ? 1 : -1;
            else lnz = lz >= 0 ? 1 : -1;

            // Blend slightly near bevels for natural edge catchlight
            lnx += 0.18 * (lx / c.hx);
            lny += 0.18 * (ly / c.hy);
            lnz += 0.18 * (lz / c.hz);

            // Rotate normal back to world coordinates: N = R * lN
            let wnx = R[0] * lnx + R[1] * lny + R[2] * lnz;
            let wny = R[3] * lnx + R[4] * lny + R[5] * lnz;
            let wnz = R[6] * lnx + R[7] * lny + R[8] * lnz;
            setVoxel(x, y, z, MAT_SUGAR, c.id, wnx, wny, wnz);
          }
        }
      }
    }
  }

  // Scattered loose sugar crystals (1x1x1 and 2x2x1 granules on the counter)
  const looseCrystals = [
    [30, 12, 1], [32, 14, 1], [28, 33, 1], [31, 30, 1], [25, 34, 1],
    [17, 36, 1], [14, 38, 1], [9, 37, 1],  [5, 39, 1],  [-2, 38, 1],
    [-8, 36, 1], [-14, 34, 1], [-19, 26, 1], [-13, 14, 1], [29, 23, 1],
    [38, 22, 1], [36, 16, 1], [27, 41, 1], [19, 42, 1], [12, 41, 1],
    [16, 10, 1], [25, 9, 1],  [-6, 14, 1], [33, 27, 1], [20, 34, 1]
  ];
  for (let i = 0; i < looseCrystals.length; i++) {
    let [cx, cy, sz] = looseCrystals[i];
    setVoxel(cx, cy, 1, MAT_SUGAR, 100 + i, -0.3, 0.5, 0.8);
    if (i % 3 === 0) {
      setVoxel(cx + 1, cy, 1, MAT_SUGAR, 100 + i, 0.4, 0.5, 0.8);
      setVoxel(cx, cy + 1, 1, MAT_SUGAR, 100 + i, -0.4, 0.6, 0.7);
    }
  }

  // 4. Lighting, Raytraced Staircase Shadows & Voxel Reflections
  // Hard Key Light from Upper Left: points toward (-x, +y, +z)
  const Lx = -0.509, Ly = 0.632, Lz = 0.584; // Normalized (-0.58, +0.72, +0.665)

  function isInCastShadow(x, y, z, selfId, allowSelfSkip) {
    let startT = allowSelfSkip ? 1.55 : 0.85;
    for (let t = startT; t < 68.0; t += 0.48) {
      let sx = Math.round(x + Lx * t);
      let sy = Math.round(y + Ly * t);
      let sz = Math.round(z + Lz * t);
      if (sz > Z_MAX || sx < X_MIN || sy > Y_MAX) return false;
      let m = getMat(sx, sy, sz);
      if (m !== MAT_EMPTY && m !== MAT_COUNTER) {
        if (allowSelfSkip && t < 3.3 && gridId[idx(sx, sy, sz)] === selfId) continue;
        return true;
      }
    }
    return false;
  }

  // Compute local crevice Ambient Occlusion and inter-cube contact seams
  function computeAO(x, y, z, selfId) {
    let occ = 0;
    let diffIdOcc = 0;
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        for (let dz = -1; dz <= 1; dz++) {
          if (dx === 0 && dy === 0 && dz === 0) continue;
          // Bias hemisphere toward camera/upward
          if (dx + dy + dz < -1) continue;
          let nx = x + dx, ny = y + dy, nz = z + dz;
          if (nz <= 0) {
            occ += 0.65;
            continue;
          }
          let m = getMat(nx, ny, nz);
          if (m !== MAT_EMPTY && m !== MAT_COUNTER) {
            occ += 1.0;
            if (gridId[idx(nx, ny, nz)] !== selfId) {
              diffIdOcc += 1.35;
            }
          }
        }
      }
    }
    return { ao: Math.min(1.0, occ / 15.0), seam: Math.min(1.0, diffIdOcc / 4.0) };
  }

  // Populate Black Lacquer Counter voxels (z = 0) with spotlight, staircase shadows & reflections
  // Reflection ray goes from (x, y, 0) along (-Vx, -Vy, +Vz) so reflections sit directly vertically below objects on screen!
  const counterReflLevel = new Int8Array(NX * NY);
  for (let x = X_MIN; x <= X_MAX; x++) {
    for (let y = Y_MIN; y <= Y_MAX; y++) {
      // Elliptical spotlight / studio table boundary
      let dxSpot = (x - 4.0) / 45.0;
      let dySpot = (y - 8.0) / 47.0;
      let rSpot = Math.hypot(dxSpot, dySpot);
      if (rSpot > 1.03) continue;

      // Skip counter tiles completely buried deep inside opaque objects
      if (
        getMat(x, y, 1) !== MAT_EMPTY &&
        getMat(x + 1, y, 1) !== MAT_EMPTY &&
        getMat(x, y + 1, 1) !== MAT_EMPTY
      ) {
        continue;
      }

      let inShadow = isInCastShadow(x, y, 0.4, -1, false);

      // Trace reflection ray into scene along (-Vx, -Vy, +Vz)
      let reflHitMat = MAT_EMPTY;
      let reflHitX = 0, reflHitY = 0, reflHitZ = 0;
      for (let t = 1.2; t < 44.0; t += 0.5) {
        let rx = Math.round(x - Vx * t);
        let ry = Math.round(y - Vy * t);
        let rz = Math.round(Vz * t);
        if (rz > Z_MAX) break;
        let m = getMat(rx, ry, rz);
        if (m !== MAT_EMPTY && m !== MAT_COUNTER) {
          reflHitMat = m;
          reflHitX = rx; reflHitY = ry; reflHitZ = rz;
          break;
        }
      }

      // Compute discrete lacquer swatch index (0..10)
      let level = 2;
      if (rSpot < 0.38) level = 5;
      else if (rSpot < 0.62) level = 4;
      else if (rSpot < 0.84) level = 3;
      else level = 2;

      if (inShadow) {
        // Crisp staircase cast shadow on the black lacquer counter
        level = rSpot < 0.55 ? 0 : 1;
      }

      // Add crisp voxel reflection of sugar cubes, saucer, and demitasse cup
      if (reflHitMat !== MAT_EMPTY) {
        let hitI = idx(reflHitX, reflHitY, reflHitZ);
        let hnx = normX[hitI], hny = normY[hitI], hnz = normZ[hitI];
        let ndotl = Math.max(0, hnx * Lx + hny * Ly + hnz * Lz);
        let hitShadow = isInCastShadow(reflHitX, reflHitY, reflHitZ, gridId[hitI], true);
        let falloff = Math.max(0.25, 1.0 - reflHitZ / 42.0);
        let reflBoost = 0;
        if (hitShadow) {
          reflBoost = 2;
        } else if (ndotl > 0.62) {
          reflBoost = 5;
        } else if (ndotl > 0.25) {
          reflBoost = 4;
        } else {
          reflBoost = 3;
        }
        reflBoost = Math.round(reflBoost * falloff);
        level = Math.min(10, Math.max(level, (inShadow ? 3 : 4) + reflBoost));
      }

      // Contact darkening right next to sugar cubes & saucer base
      let nearBase = false;
      for (let bx = -1; bx <= 1; bx++) {
        for (let by = -1; by <= 1; by++) {
          if (getMat(x + bx, y + by, 1) !== MAT_EMPTY) nearBase = true;
        }
      }
      if (nearBase && reflHitMat === MAT_EMPTY) {
        level = Math.max(0, level - 2);
      }

      setVoxel(x, y, 0, MAT_COUNTER, 0, 0, 0, 1);
      counterReflLevel[(x - X_MIN) * NY + (y - Y_MIN)] = level;
    }
  }

  // 5. Collect All Visible Voxels & Sort by Exact Camera Ray Depth
  const visibleVoxels = [];
  for (let x = X_MIN; x <= X_MAX; x++) {
    for (let y = Y_MIN; y <= Y_MAX; y++) {
      for (let z = Z_MIN; z <= Z_MAX; z++) {
        let m = getMat(x, y, z);
        if (m === MAT_EMPTY) continue;

        // A voxel is visible if at least one of its 3 front-facing neighbors (+X, +Y, +Z) is empty
        let expX = getMat(x + 1, y, z) === MAT_EMPTY;
        let expY = getMat(x, y + 1, z) === MAT_EMPTY;
        let expZ = getMat(x, y, z + 1) === MAT_EMPTY;
        if (!expX && !expY && !expZ) continue;

        let depth = x * Vx + y * Vy + z * Vz;
        visibleVoxels.push({ x, y, z, m, expX, expY, expZ, depth });
      }
    }
  }

  // Sort strictly back-to-front along camera viewing vector (Vx, Vy, Vz)
  visibleVoxels.sort((a, b) => a.depth - b.depth);

  // 6. Compute Alcohol-Marker Face Swatches for Each Visible Voxel
  function getCremaColors(x, y, z, inShadow, aoVal) {
    let dx = x - cupCX;
    let dy = y - cupCY;
    let r = Math.hypot(dx, dy);
    let ang = atan2(dy, dx);
    // Swirling tiger-stripe crema pattern
    let swirl = sin(ang * 3.0 + r * 28.0) + 0.65 * cos(ang * 5.0 - r * 22.0 + x * 14.0);
    let isOuterMeniscus = r > 16.5;
    let isTigerStripe = swirl > 0.55 || (isOuterMeniscus && swirl > -0.15);

    let shadowStep = inShadow ? 3 : 0;
    let aoStep = Math.round(aoVal * 2.0);

    if (isTigerStripe) {
      // Burnt umber block
      let tIdx = Math.min(6, Math.max(0, 1 + shadowStep + aoStep));
      let lIdx = Math.min(6, Math.max(0, 2 + shadowStep + aoStep));
      let rIdx = Math.min(6, Math.max(0, 3 + shadowStep + aoStep));
      return {
        top: CREMA_UMBER[tIdx],
        left: CREMA_UMBER[lIdx],
        right: CREMA_UMBER[rIdx],
        crevice: "#1c0a03",
        edge: CREMA_TAN[Math.min(7, 2 + shadowStep)]
      };
    } else {
      // Golden tan block with burnt umber side steps
      let heartHighlight = (r < 6.5 && !inShadow) ? -1 : 0;
      let tIdx = Math.min(7, Math.max(0, 1 + heartHighlight + shadowStep + aoStep));
      let lIdx = Math.min(7, Math.max(0, 3 + shadowStep + aoStep));
      let rIdx = Math.min(6, Math.max(0, 2 + shadowStep + aoStep));
      return {
        top: CREMA_TAN[tIdx],
        left: CREMA_TAN[lIdx],
        right: CREMA_UMBER[rIdx],
        crevice: "#240e04",
        edge: CREMA_TAN[Math.min(7, Math.max(0, tIdx - 1))]
      };
    }
  }

  function getVoxelColors(v) {
    let { x, y, z, m } = v;
    if (m === MAT_COUNTER) {
      let lvl = counterReflLevel[(x - X_MIN) * NY + (y - Y_MIN)];
      return {
        top: LACQUER_TOP[lvl],
        left: LACQUER_LEFT[lvl],
        right: LACQUER_RIGHT[lvl],
        crevice: "#05070a",
        edge: LACQUER_TOP[Math.min(10, lvl + 1)]
      };
    }

    let i = idx(x, y, z);
    let id = gridId[i];
    let nx = normX[i], ny = normY[i], nz = normZ[i];

    // Macro diffuse illumination from Upper-Left Key Light
    let ndotl = nx * Lx + ny * Ly + nz * Lz;
    let allowSelfSkip = ndotl > 0.12;
    let inShadow = isInCastShadow(x, y, z, id, allowSelfSkip);
    let { ao, seam } = computeAO(x, y, z, id);

    if (m === MAT_CREMA) {
      return getCremaColors(x, y, z, inShadow, ao);
    }

    // Porcelain & Sugar Cube lighting -> Bone White (Top), Warm Grey (Left), Cool Slate (Right)
    // Specular highlight for glazed porcelain vs crystalline translucency for sugar
    let Hx = Lx + Vx, Hy = Ly + Vy, Hz = Lz + Vz;
    let Hlen = Math.hypot(Hx, Hy, Hz) || 1;
    Hx /= Hlen; Hy /= Hlen; Hz /= Hlen;
    let ndoth = Math.max(0, nx * Hx + ny * Hy + nz * Hz);

    let isSpec = false;
    if (!inShadow && m === MAT_PORCELAIN && (ndoth > 0.91 || (z >= 46 && ndotl > 0.35))) {
      isSpec = true;
    }

    // Base marker step index (0 = brightest, 9 = darkest)
    let baseStep = 3.0 - ndotl * 2.6;
    if (m === MAT_SUGAR) {
      // Sugar cubes have bright crystalline top scattering and subtle facet sparkle
      baseStep -= 0.45;
      let crystalSparkle = ((x * 19 + y * 31 + z * 13) & 7) === 0 ? -0.45 : 0.0;
      if (!inShadow && ndotl > 0.25) baseStep += crystalSparkle;
    } else if (m === MAT_PORCELAIN) {
      // Smooth cylindrical contrast + cool rim reflection on right terminator
      let rimRight = (nx > 0.65 && ny < 0.1) ? -0.6 : 0.0;
      baseStep += rimRight;
    }

    if (inShadow) {
      baseStep = Math.max(baseStep + 3.6, 6.2);
    }

    baseStep += ao * 2.2 + seam * 1.6;
    if (isSpec) baseStep = 0.0;

    let topIdx   = Math.min(9, Math.max(0, Math.round(baseStep - 0.5)));
    let leftIdx  = Math.min(9, Math.max(0, Math.round(baseStep + (ny > 0.2 ? -0.3 : 0.4))));
    let rightIdx = Math.min(9, Math.max(0, Math.round(baseStep + (nx > 0.3 ? 0.5 : -0.2))));

    if (isSpec) {
      topIdx = 0;
      leftIdx = 0;
    }

    return {
      top: BONE_WHITE[topIdx],
      left: WARM_GREY[leftIdx],
      right: COOL_SLATE[rightIdx],
      crevice: inShadow ? "#141922" : "#262e3b",
      edge: BONE_WHITE[Math.max(0, topIdx - 1)]
    };
  }

  // 7. Render Voxel Scene in Painter's Order with Alcohol-Marker Strokes & Washes
  const chiselQueue = [];
  const edgeQueue = [];

  for (let idxV = 0; idxV < visibleVoxels.length; idxV++) {
    let v = visibleVoxels[idxV];
    let { x, y, z, m } = v;
    let cols = getVoxelColors(v);

    // First seal the full 1.02 unit footprint so zero background leaks between micro-stepped cubes
    if (m !== MAT_COUNTER) {
      let s0 = 1.02;
      let p_topBack   = project(x, y, z + s0);
      let p_topLeft   = project(x, y + s0, z + s0);
      let p_botLeft   = project(x, y + s0, z);
      let p_botFront  = project(x + s0, y + s0, z);
      let p_botRight  = project(x + s0, y, z);
      let p_topRight  = project(x + s0, y, z + s0);

      let hexPoly = new brush.Polygon([
        p_topBack, p_topLeft, p_botLeft, p_botFront, p_botRight, p_topRight
      ]);
      hexPoly.wash(cols.crevice, 255);
    }

    // Cube size s < 1.0 ensures EVERY cube displays all 3 of its flat faces (Top, Left-Front, Right-Front)
    // even along vertical stacks or horizontal runs!
    let s = m === MAT_COUNTER ? 0.94 : (m === MAT_SUGAR ? 0.91 : 0.925);

    let p001 = project(x,     y,     z + s); // Top-Back
    let p011 = project(x,     y + s, z + s); // Top-Left
    let p111 = project(x + s, y + s, z + s); // Center Y-vertex (Front-Top)
    let p101 = project(x + s, y,     z + s); // Top-Right
    let p010 = project(x,     y + s, z);     // Bottom-Left
    let p110 = project(x + s, y + s, z);     // Bottom-Front
    let p100 = project(x + s, y,     z);     // Bottom-Right

    // 1) Top Face (+Z): Bone White / Crema Tan / Lacquer Top
    let polyTop = new brush.Polygon([p001, p011, p111, p101]);
    polyTop.wash(cols.top, 255);

    // 2) Left-Front Face (+Y): Warm Grey / Crema Mid / Lacquer Left
    let polyLeft = new brush.Polygon([p011, p010, p110, p111]);
    polyLeft.wash(cols.left, 255);

    // 3) Right-Front Face (+X): Cool Slate / Crema Umber / Lacquer Right
    let polyRight = new brush.Polygon([p111, p110, p100, p101]);
    polyRight.wash(cols.right, 255);

    // Queue selective chisel-marker strokes & razor-clean Y-junction edges on exposed surface cubes
    if (m !== MAT_COUNTER) {
      if (v.expZ && ((x + y + z) & 1) === 0) {
        chiselQueue.push({
          col: cols.top,
          x1: (p001[0] + p011[0]) * 0.5,
          y1: (p001[1] + p011[1]) * 0.5,
          x2: (p101[0] + p111[0]) * 0.5,
          y2: (p101[1] + p111[1]) * 0.5
        });
      }
      if (v.expY && ((x * 3 + z) & 1) === 0) {
        chiselQueue.push({
          col: cols.left,
          x1: (p011[0] + p111[0]) * 0.5,
          y1: (p011[1] + p111[1]) * 0.5,
          x2: (p010[0] + p110[0]) * 0.5,
          y2: (p010[1] + p110[1]) * 0.5
        });
      }
      if (v.expX && ((y * 3 + z) & 1) === 0) {
        chiselQueue.push({
          col: cols.right,
          x1: (p111[0] + p101[0]) * 0.5,
          y1: (p111[1] + p101[1]) * 0.5,
          x2: (p110[0] + p100[0]) * 0.5,
          y2: (p110[1] + p100[1]) * 0.5
        });
      }

      // Crisp inner Y-ridge catchlight where the 3 flat faces of the cube meet
      if ((v.expX && v.expY) || (v.expZ && (v.expX || v.expY))) {
        edgeQueue.push({
          col: cols.edge,
          x1: p011[0], y1: p011[1],
          x2: p111[0], y2: p111[1]
        });
        edgeQueue.push({
          col: cols.edge,
          x1: p111[0], y1: p111[1],
          x2: p101[0], y2: p101[1]
        });
        edgeQueue.push({
          col: cols.left,
          x1: p111[0], y1: p111[1],
          x2: p110[0], y2: p110[1]
        });
      }
    }
  }

  // 8. Execute Batched Alcohol-Marker Chisel Strokes & Razor-Clean Cube Edges
  brush.noFill();
  brush.noWash();

  // Sort by color so brush.set() state changes are minimized
  chiselQueue.sort((a, b) => (a.col < b.col ? -1 : a.col > b.col ? 1 : 0));
  let curCol = "";
  for (let i = 0; i < chiselQueue.length; i++) {
    let st = chiselQueue[i];
    if (st.col !== curCol) {
      curCol = st.col;
      brush.set("chisel_marker", curCol, 0.85);
    }
    brush.line(st.x1, st.y1, st.x2, st.y2);
  }

  edgeQueue.sort((a, b) => (a.col < b.col ? -1 : a.col > b.col ? 1 : 0));
  curCol = "";
  for (let i = 0; i < edgeQueue.length; i++) {
    let ed = edgeQueue[i];
    if (ed.col !== curCol) {
      curCol = ed.col;
      brush.set("razor_pen", curCol, 0.42);
    }
    brush.line(ed.x1, ed.y1, ed.x2, ed.y2);
  }

  noLoop();
}

