// Plate geometry constants (Slightly elevated three-quarter view, cropped off right & bottom)
const PLATE = {
  cx: 790,
  cy: 695,
  tilt: -22,
  aspect: 0.71,
  rOuter: 745,
  rRimInner: 495,
  rWell: 410,
  wellShiftX: 16,
  wellShiftY: 22
};

// Map polar plate coords (radius r, angle deg, depth drop z) to canvas (x, y)
function platePt(r, deg, zDrop = 0) {
  let rad = deg * (Math.PI / 180);
  let tiltRad = PLATE.tilt * (Math.PI / 180);
  let lx = r * Math.cos(rad);
  let ly = r * Math.sin(rad) * PLATE.aspect;
  let rx = lx * Math.cos(tiltRad) - ly * Math.sin(tiltRad);
  let ry = lx * Math.sin(tiltRad) + ly * Math.cos(tiltRad);
  return [
    PLATE.cx + rx + zDrop * 0.45,
    PLATE.cy + ry + zDrop * 0.65
  ];
}

// Helper to draw a closed smooth shape from an array of [x, y] points
function drawShapePts(pts, curvature = 0.35, closeShape = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

// Generate an elliptical arc of points on the plate
function getPlateArc(r, degStart, degEnd, steps, zDrop = 0, jitter = 0) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let deg = lerp(degStart, degEnd, t);
    let rMod = r + (jitter ? random(-jitter, jitter) : 0);
    pts.push(platePt(rMod, deg, zDrop));
  }
  return pts;
}

// Generate a ribbon band on the plate between r1 and r2 from degStart to degEnd
function getPlateBand(r1, r2, degStart, degEnd, steps, zDrop1 = 0, zDrop2 = 0, jitter = 0) {
  let outer = getPlateArc(r2, degStart, degEnd, steps, zDrop2, jitter);
  let inner = getPlateArc(r1, degEnd, degStart, steps, zDrop1, jitter);
  return outer.concat(inner);
}

