function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.tableDark);

  // 1. STUDIO TABLETOP & PLATE CAST SHADOW
  renderStudioBackground();

  // 2. TIN-GLAZED MAJOLICA PLATE BASE & 3D FORM
  renderPlateBase();

  // 3. MAJOLICA PAINTED BORDERS, GLAZE POOLS, CRAWLS & PINHOLES
  renderMajolicaDecoration();

  // 4. DIFFUSE STUDIO LIGHT GLEAM ON PLATE CURVE
  renderPlateReflections();

  // 5. FROG CONTACT SHADOW & GLAZE REFLECTION UNDER BELLY
  renderFrogShadowsAndReflections();

  // 6. HYPERREAL LIVING GREEN FROG
  renderLivingFrog();

  noLoop();
}

// ============================================================================
// 1. STUDIO BACKGROUND & CAST SHADOW
// ============================================================================
function renderStudioBackground() {
  // Deep warm tabletop visible in top-left and bottom-left corners
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.4);

  brush.fill(PAL.tableWarm, 95);
  drawShapePts([[0, 0], [850, 0], [400, 600], [0, 950]], 0.2);

  brush.fill(PAL.tableMid, 120);
  drawShapePts([[0, 0], [620, 0], [220, 500], [0, 720]], 0.2);

  // Subtle wood/slate surface grain in the dark background corner
  brush.hatchStyle("charcoal", "#2f2326", 0.9);
  brush.hatch(9, -22, { rand: 0.12, gradient: 0.4 });
  brush.noFill();
  brush.noStroke();
  drawShapePts([[0, 0], [760, 0], [250, 620], [0, 880]], 0.1);
  brush.noHatch();

  // Deep cast shadow under the plate's raised outer rim
  brush.noStroke();
  brush.fillBleed(0.4, "out");
  brush.fill(PAL.castShadow, 190);
  let shadowRim = getPlateBand(PLATE.rOuter - 20, PLATE.rOuter + 48, 125, 295, 36, 18, 28);
  drawShapePts(shadowRim, 0.3);

  brush.fill("#070508", 220);
  let tightShadow = getPlateBand(PLATE.rOuter - 10, PLATE.rOuter + 22, 130, 290, 32, 10, 16);
  drawShapePts(tightShadow, 0.3);
}

// ============================================================================
// 2. TIN-GLAZED PLATE BASE (OPAQUE WHITE GROUND & 3D CAVETTO)
// ============================================================================
function renderPlateBase() {
  brush.noStroke();

  // Terracotta bisque outer edge (exposed unglazed clay hints at the very rim)
  brush.wash(PAL.bisque, 225);
  let outerEdge = getPlateArc(PLATE.rOuter + 5, 0, 360, 64, 0, 1.5);
  drawShapePts(outerEdge, 0.35);

  // Milky opaque tin-glaze ground (Bianco)
  brush.wash(PAL.tinWhite, 250);
  let mainPlate = getPlateArc(PLATE.rOuter, 0, 360, 64, 0, 1.2);
  drawShapePts(mainPlate, 0.35);

  // Subtle warm creamy variation across the broad rim
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.45, 0.3);
  brush.fill(PAL.tinCream, 110);
  let rimBand = getPlateBand(PLATE.rRimInner, PLATE.rOuter - 4, 140, 340, 40, 0, 0);
  drawShapePts(rimBand, 0.3);

  // 3D Cavetto Drop (the sloped wall between rim and sunken well)
  // Upper-left cavetto wall faces away from top-left light -> cool porcelain shadow
  brush.fillBleed(0.32, "out");
  brush.fill(PAL.tinCoolShadow, 155);
  let cavettoShadow = getPlateBand(PLATE.rWell, PLATE.rRimInner + 6, 155, 325, 36, 36, 0);
  drawShapePts(cavettoShadow, 0.35);

  brush.fill(PAL.tinDeepShadow, 125);
  let cavettoDeep = getPlateBand(PLATE.rWell + 8, PLATE.rRimInner - 10, 175, 295, 30, 36, 0);
  drawShapePts(cavettoDeep, 0.35);

  // Sunken central well base
  brush.wash(PAL.tinCream, 210);
  let wellPts = getPlateArc(PLATE.rWell, 0, 360, 50, 36, 0);
  drawShapePts(wellPts, 0.35);

  // Soft watercolor shading inside the well near the cavetto base
  brush.fillBleed(0.38, "out");
  brush.fill(PAL.tinCoolShadow, 95);
  let wellCrease = getPlateBand(PLATE.rWell - 45, PLATE.rWell + 6, 160, 315, 32, 36, 36);
  drawShapePts(wellCrease, 0.35);
}

// ============================================================================
// 3. MAJOLICA DECORATION (COBALT, ANTIMONY, COPPER, MANGANESE)
// ============================================================================
function renderMajolicaDecoration() {
  brush.noStroke();

  // --- A. CONCENTRIC PAINTED BANDS WITH WATERCOLOUR BLEED ---
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.72, 0.58);

  // 1. Outer Cobalt Blue Band (near rim edge, r = 685..732)
  for (let seg = 120; seg < 345; seg += 36) {
