    brush.fill(PAL.antimonyBright, random(180, 220));
    drawShapePts(getPlateBand(502, 528, seg, segEnd, 14, 0, 0, 2.5), 0.35);
  }
  // Warm orange-ochre antimony glaze pools
  for (let a of [152, 205, 248, 285, 322]) {
