  // 3. Cavetto Cobalt & Copper Green Gadroons / Petal Border (r = 412..488, sloping into well)
  for (let deg = 115; deg <= 355; deg += 9) {
    let isGreen = (Math.round(deg / 9) % 3 === 0);
    let p1 = platePt(488, deg - 3.5, 4);
    let p2 = platePt(488, deg + 3.5, 4);
    let p3 = platePt(445, deg + 4.2, 22);
    let pTip = platePt(416, deg, 35);
    let p4 = platePt(445, deg - 4.2, 22);

    brush.fill(isGreen ? PAL.copper : PAL.cobalt, random(140, 185));
    drawShapePts([p1, p2, p3, pTip, p4], 0.42);

    // Running glaze drip at tip of petal down into the well
    if (random() < 0.45) {
      let dripTip = platePt(396 - random(18), deg + random(-1.5, 1.5), 36);
      brush.fill(isGreen ? PAL.copperBright : PAL.cobaltWash, 105);
      drawShapePts([p3, pTip, dripTip, p4], 0.45);
    }
  }

  // --- B. RIM FRIEZE: RENAISSANCE SCROLLING GARLAND (r = 535..650) ---
  // Painted in Copper Green, Cobalt Blue, Antimony Yellow, and Manganese Purple
  for (let deg = 122; deg <= 346; deg += 14) {
    let idx = Math.round((deg - 122) / 14);
    let rMid = 592 + Math.sin(idx * 1.4) * 18;

    // Alternating Copper Green leaves and Cobalt Blue palmettes
    let leaf1Center = platePt(rMid + 24, deg + 3, 0);
    let leaf2Center = platePt(rMid - 24, deg + 7, 0);

    // Copper Green bleeding foliage
    brush.fill(PAL.copper, random(150, 195));
    let leaf1 = [
      platePt(rMid + 6, deg - 2, 0),
      platePt(rMid + 34, deg + 1, 0),
      platePt(rMid + 48, deg + 7, 0),
      platePt(rMid + 26, deg + 9, 0),
      platePt(rMid + 8, deg + 5, 0)
    ];
    drawShapePts(leaf1, 0.45);

    // Soft turquoise-green glaze crawl around copper leaf
    brush.fill(PAL.copperTurq, 85);
    let leafBleed = [
      platePt(rMid + 2, deg - 3, 0),
      platePt(rMid + 42, deg + 0, 0),
      platePt(rMid + 56, deg + 8, 0),
      platePt(rMid + 22, deg + 11, 0)
    ];
    drawShapePts(leafBleed, 0.5);

    // Cobalt Blue lower leaf / lobe
    brush.fill(PAL.cobaltBright, random(145, 185));
    let leaf2 = [
      platePt(rMid - 4, deg + 2, 0),
      platePt(rMid - 32, deg + 5, 0),
      platePt(rMid - 46, deg + 11, 0),
      platePt(rMid - 22, deg + 12, 0),
      platePt(rMid - 6, deg + 8, 0)
    ];
    drawShapePts(leaf2, 0.45);

    // Antimony Yellow & Manganese Purple berries/medallions
    if (idx % 2 === 0) {
      let medPt = platePt(rMid, deg + 10, 0);
      brush.fill(PAL.antimony, 195);
      brush.circle(medPt[0], medPt[1], random(13, 17), 0.25);

      brush.fill(PAL.manganese, 165);
      let berry1 = platePt(rMid + 28, deg + 12, 0);
      let berry2 = platePt(rMid - 25, deg + 1, 0);
      brush.circle(berry1[0], berry1[1], random(7, 10), 0.3);
      brush.circle(berry2[0], berry2[1], random(7, 10), 0.3);
    } else {
      let medPt = platePt(rMid + 4, deg + 11, 0);
      brush.fill(PAL.manganeseBright, 160);
