    drawShapePts(getPlateBand(342, 364, seg, segEnd, 12, 36, 36, 2), 0.35);
    brush.fill(PAL.copper, 155);
    drawShapePts(getPlateBand(295, 322, seg, segEnd, 12, 36, 36, 3), 0.35);
  }

  // Central Renaissance rosette petals inside the well (r = 80..285)
  for (let deg = 135; deg <= 345; deg += 18) {
    let isMing = (Math.round(deg / 18) % 2 === 0);
    let pBase1 = platePt(95, deg - 5, 36);
    let pBase2 = platePt(95, deg + 5, 36);
    let pMid1 = platePt(210, deg - 7, 36);
    let pOuter = platePt(282, deg, 36);
    let pMid2 = platePt(210, deg + 7, 36);

    brush.fill(isMing ? PAL.manganese : PAL.cobaltBright, 150);
    drawShapePts([pBase1, pMid1, pOuter, pMid2, pBase2], 0.42);

