    brush.circle(pCore[0], pCore[1], 14, 0.25);
  }

  // --- D. MANGANESE PURPLE & COBALT BRUSHWORK CONTOURS (SOFTENED IN GLAZE) ---
  brush.noFill();
  brush.noWash();

  // Concentric hand-painted Manganese Purple border lines
  let borderRadii = [
    { r: 733, z: 0, col: PAL.cobaltDeep, w: 1.4 },
    { r: 688, z: 0, col: PAL.manganese, w: 1.3 },
    { r: 655, z: 0, col: PAL.manganeseDeep, w: 1.5 },
    { r: 530, z: 0, col: PAL.manganeseDeep, w: 1.5 },
    { r: 500, z: 0, col: PAL.manganese, w: 1.3 },
    { r: 412, z: 35, col: PAL.cobaltDeep, w: 1.4 },
    { r: 366, z: 36, col: PAL.manganese, w: 1.2 },
    { r: 340, z: 36, col: PAL.manganeseDeep, w: 1.2 }
