    // Core hand-painted pigment line
    brush.set("cpencil", b.col, b.w);
    let linePts = getPlateArc(b.r, 118, 352, 48, b.z, 1.2);
    brush.spline(linePts, 0.4);
  }

  // Undulating Manganese Purple vine stem through the rim frieze
  let vinePts = [];
  for (let deg = 120; deg <= 350; deg += 4) {
    let rVine = 592 + Math.sin((deg - 120) * 0.1) * 20;
    vinePts.push(platePt(rVine, deg, 0));
  }
  brush.set("glaze_crawl", PAL.manganeseWash, 1.1);
  brush.spline(vinePts, 0.45);
  brush.set("cpencil", PAL.manganeseDeep, 1.3);
  brush.spline(vinePts, 0.45);

  // Delicate Manganese leaf veins and tendril curls on the rim
  for (let deg = 126; deg <= 342; deg += 14) {
    let idx = Math.round((deg - 122) / 14);
    let rMid = 592 + Math.sin(idx * 1.4) * 18;
    brush.set("micro_detail", PAL.manganeseDeep, 1.0);
    let v1 = platePt(rMid + 4, deg - 1, 0);
    let v2 = platePt(rMid + 26, deg + 4, 0);
    let v3 = platePt(rMid + 44, deg + 7, 0);
    brush.spline([v1, v2, v3], 0.4);

    let u1 = platePt(rMid - 4, deg + 2, 0);
    let u2 = platePt(rMid - 24, deg + 7, 0);
    let u3 = platePt(rMid - 40, deg + 11, 0);
    brush.spline([u1, u2, u3], 0.4);
  }

  // --- E. MAJOLICA GLAZE CRAWLS, PINHOLES & TERRACOTTA RIM WEAR ---
  // Where tin glaze crawled during firing, tiny circular pinholes expose warm terracotta bisque
  for (let i = 0; i < 240; i++) {
    let deg = random(118, 355);
    let r = random(180, 740);
    let z = r < PLATE.rRimInner ? map(r, PLATE.rWell, PLATE.rRimInner, 36, 0, true) : 0;
    let pt = platePt(r, deg, z);

    // Rim edge has larger glaze crawls
    let isEdge = r > 728 || (r > 488 && r < 504);
    if (isEdge && random() < 0.45) {
      brush.noStroke();
      brush.wash(PAL.bisque, random(160, 220));
      brush.circle(pt[0], pt[1], random(2.5, 6.5), 0.45);
      brush.set("micro_detail", PAL.bisqueDark, 0.7);
      brush.circle(pt[0], pt[1], random(1.5, 3.5), 0.4);
    } else {
      // Tiny ceramic pinhole with dark center and pale glaze rim
      brush.set("micro_detail", PAL.tinWhite, 0.9);
      brush.circle(pt[0] + 0.8, pt[1] + 0.8, random(1.2, 2.6), 0.3);
      brush.set("micro_detail", random() < 0.6 ? PAL.bisqueDark : "#5c4a42", 0.8);
      brush.circle(pt[0], pt[1], random(0.8, 1.8), 0.3);
    }
  }

  // Subtle glaze crazing (hairline crackle network in old tin glaze)
  brush.set("micro_detail", "#cfc6b4", 0.55);
  for (let i = 0; i < 28; i++) {
    let deg = random(135, 335);
    let rStart = random(280, 710);
    let cPts = [];
    let curR = rStart;
    let curDeg = deg;
    for (let s = 0; s < 5; s++) {
      let z = curR < PLATE.rRimInner ? map(curR, PLATE.rWell, PLATE.rRimInner, 36, 0, true) : 0;
      cPts.push(platePt(curR, curDeg, z));
      curR += random(-32, 32);
      curDeg += random(-4, 4);
    }
    brush.spline(cPts, 0.25);
  }
}

// ============================================================================
// 4. SOFT DIFFUSE STUDIO LIGHT GLEAM ON PLATE CURVE
// ============================================================================
function renderPlateReflections() {
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.25, 0.15);

  // Broad softbox reflection sweeping across the upper-left and lower-left curved rim
  brush.fill("#ffffff", 95);
  let gleam1 = getPlateBand(535, 715, 145, 192, 20, 0, 0);
  drawShapePts(gleam1, 0.4);

  brush.fill("#ffffff", 130);
  let gleamCore1 = getPlateBand(565, 685, 155, 182, 16, 0, 0);
  drawShapePts(gleamCore1, 0.4);

  // Secondary diffuse reflection on the lower-left / bottom rim curve
  brush.fill("#ffffff", 85);
  let gleam2 = getPlateBand(520, 700, 260, 305, 18, 0, 0);
  drawShapePts(gleam2, 0.4);

  // Sharp, Continuous Gleaming Highlight along the convex Cavetto Lip (r = 495)
  // This gives the ceramic plate its unmistakable glossy tin-glazed material quality
  for (let pass = 0; pass < 3; pass++) {
    let w = [3.4, 2.0, 1.0][pass];
    let col = pass === 2 ? "#ffffff" : PAL.specularCyan;
    brush.set("wet_sheen", col, w);
    let lipGleamA = getPlateArc(496 + pass * 1.2, 142, 208, 28, 1, 0.4);
    brush.spline(lipGleamA, 0.4);

    let lipGleamB = getPlateArc(496 + pass * 1.2, 245, 318, 28, 1, 0.4);
    brush.spline(lipGleamB, 0.4);
  }

  // Glossy outer rim highlight along the top-left turn of the plate
  brush.set("wet_sheen", "#ffffff", 2.4);
  let outerGleam = getPlateArc(738, 188, 258, 32, 0, 0.5);
  brush.spline(outerGleam, 0.4);
  brush.set("wet_sheen", "#ffffff", 1.2);
  let outerGleamSharp = getPlateArc(740, 198, 248, 24, 0, 0.3);
  brush.spline(outerGleamSharp, 0.4);
}

