// Hyperrealism: Giraffe Voronoi Coat & Glossy Savanna-Sky Eye
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

const W = 1200;
const H = 1200;

// Eye anatomical center and orientation
const EYE_X = 775;
const EYE_Y = 430;
const EYE_TILT = 15; // degrees downward toward muzzle (lower-right)

// Late-afternoon raking light direction (from upper-left grazing across hide)
const LIGHT_DIR = { x: -0.76, y: -0.46, z: 0.46 };

async function setup() {
