// ---------------------------------------------------------------------------
// 3D Anatomical Surface, Raking Light & Hair Flow Field
// ---------------------------------------------------------------------------

// Rotate point (x, y) into eye-local coordinates
function toEyeSpace(x, y) {
  let dx = x - EYE_X;
  let dy = y - EYE_Y;
  let c = cos(-EYE_TILT);
  let s = sin(-EYE_TILT);
  return {
    u: dx * c - dy * s,
    v: dx * s + dy * c
  };
}

// Transform eye-local coordinates (u, v) back to canvas coordinates
function fromEyeSpace(u, v) {
  let c = cos(EYE_TILT);
  let s = sin(EYE_TILT);
  return {
    x: EYE_X + u * c - v * s,
    y: EYE_Y + u * s + v * c
  };
}

// Compute 3D sculptural elevation and raking light intensity at (x, y)
function getSurfaceLight(x, y) {
  let es = toEyeSpace(x, y);
  let u = es.u;
  let v = es.v;
  let dEye = sqrt(u * u * 0.75 + v * v * 1.25);

  // Sweeping neck cylinder axis curving from lower-left (140, 1200) into head (780, 420)
  // Parameter along neck-to-head curve:
  let neckCurveX = 160 + 620 * pow(1 - constrain(y / 1200, 0, 1), 0.78);
  let distFromSpine = x - neckCurveX;

  // Base cylindrical normal across neck & head
  let nx = constrain((distFromSpine - 110) / 520, -0.92, 0.92);
  let ny = -0.25 + 0.35 * (y / 1200);

  // Jugular / cervical muscular furrow sweeping from (180, 1200) to (640, 600)
  let furrowX = 210 + (1 - y / 1200) * 520 + sin((y / 1200) * 180) * 45;
  let dFurrow = (x - furrowX) / 135;
  if (abs(dFurrow) < 1.8 && y > 480) {
    let fStrength = constrain((y - 480) / 500, 0, 1) * exp(-dFurrow * dFurrow * 1.4);
    nx += dFurrow * 0.48 * fStrength;
    ny += 0.22 * fStrength;
  }

  // Prominent supraorbital brow ridge arching above the eye
  let browV = -95 + 0.0012 * u * u;
  let dBrow = (v - browV) / 48;
  if (abs(u) < 230 && abs(dBrow) < 1.8) {
    let bAmp = exp(-(u * u) / (190 * 190)) * exp(-dBrow * dBrow * 1.3);
    ny += dBrow * 0.65 * bAmp;
    nx -= 0.25 * bAmp;
  }

  // Zygomatic / cheek prominence below the eye
  let cheekV = 135 - 0.0008 * u * u;
  let dCheek = (v - cheekV) / 65;
  if (abs(u + 20) < 260 && abs(dCheek) < 1.8) {
    let cAmp = exp(-((u + 20) * (u + 20)) / (220 * 220)) * exp(-dCheek * dCheek * 1.2);
    ny += dCheek * 0.45 * cAmp;
    nx -= 0.18 * cAmp;
  }

  // Deep orbital depression immediately around eyelids
  if (dEye > 85 && dEye < 185) {
    let t = map(dEye, 85, 185, 0, 180);
    let recess = sin(t) * 0.38;
    nx += (u / (dEye + 1)) * recess;
    ny += (v / (dEye + 1)) * recess;
  }

  let nLenSq = nx * nx + ny * ny;
  let nz = sqrt(max(0.08, 1 - nLenSq));
  let len = sqrt(nx * nx + ny * ny + nz * nz);
  nx /= len;
  ny /= len;
  nz /= len;

  // Dot product with late-afternoon raking light
  let dot = nx * LIGHT_DIR.x + ny * LIGHT_DIR.y + nz * LIGHT_DIR.z;
  let light = constrain(map(dot, -0.55, 0.85, 0.05, 1.0), 0, 1);

  // Grazing / raking rim factor (strong when surface turns toward upper-left sun)
  let raking = pow(constrain(map(nx * -0.82 + ny * -0.57, 0.05, 0.82, 0, 1), 0, 1), 1.45);

  return { nx, ny, nz, light, raking, dEye, u, v };
}

// Continuous anatomical hair direction (in degrees) across neck, cheek, brow, and orbital ring
function getHairAngle(x, y) {
  let es = toEyeSpace(x, y);
  let u = es.u;
  let v = es.v;
  let r = sqrt(u * u + v * v);

  // Global flow from upper-left neck arch sweeping down and curving into cheek/muzzle
  let baseAngle = 62 - 34 * (x / W) + 18 * (y / H);
  // Subtle muscular S-curve modulation along neck
  baseAngle += 14 * sin((x * 0.22 + y * 0.35) * 0.5) * constrain((y - 250) / 800, 0, 1);

  // Orbital flow around the huge eye
  if (r < 340) {
    // Tangent flow sweeping over the brow from left to right and under the lower lid
    let theta = atan2(v * 1.25, u * 0.85); // -180 to 180
    let orbitalDir;
    if (v < 0) {
      // Upper hemisphere: arch from left lateral corner over brow toward right medial corner
      orbitalDir = EYE_TILT + map(u, -240, 240, -38, 32);
    } else {
      // Lower hemisphere: sweep from left lateral corner under cheek toward lower-right snout
      orbitalDir = EYE_TILT + map(u, -240, 240, 48, 18);
    }
    let blend = pow(constrain(1 - (r - 95) / 245, 0, 1), 1.5);
    // Smooth angular interpolation
    let diff = ((orbitalDir - baseAngle + 540) % 360) - 180;
    baseAngle = baseAngle + diff * blend;
  }

  // Fine local organic curl
  let n = (noise(x * 0.0045, y * 0.0045) - 0.5) * 14;
  return baseAngle + n;
}

// Target Voronoi seed spacing as a function of anatomical region
function getTargetSpacing(x, y) {
  let es = toEyeSpace(x, y);
  let dEye = sqrt(es.u * es.u * 0.82 + es.v * es.v * 1.18);

  // Near the orbital ring: small compact polygonal spots
  if (dEye < 230) {
    return map(constrain(dEye, 130, 230), 130, 230, 34, 62);
  }

  // Distance along neck from head (upper-right) to lower-left neck base
  let dHead = dist(x, y, EYE_X + 60, EYE_Y - 30);
  let s = map(constrain(dHead, 200, 1150), 200, 1150, 62, 188);

  // Slightly tighter cells along the upper-left nuchal crest and right muzzle/cheek edge
  if (x < 260 && y < 480) {
    s *= map(x + y * 0.4, 0, 450, 0.62, 1.0);
  }
  if (x > 940) {
    s *= map(x, 940, 1200, 1.0, 0.68);
  }
  return constrain(s, 34, 192);
}

// ---------------------------------------------------------------------------
// Exact Half-Plane Voronoi Tessellation & Biological Boundary Generator
// ---------------------------------------------------------------------------

// Clip convex polygon against half-plane: (P - linePt) . lineNorm <= 0
function clipHalfPlane(poly, px, py, nx, ny) {
  let out = [];
  let n = poly.length;
  if (n === 0) return out;

  for (let i = 0; i < n; i++) {
    let cur = poly[i];
    let nxt = poly[(i + 1) % n];
    let dCur = (cur.x - px) * nx + (cur.y - py) * ny;
    let dNxt = (nxt.x - px) * nx + (nxt.y - py) * ny;

    if (dCur <= 0) {
      out.push(cur);
      if (dNxt > 0) {
        let t = dCur / (dCur - dNxt);
        out.push({
          x: cur.x + t * (nxt.x - cur.x),
          y: cur.y + t * (nxt.y - cur.y),
          nx,
          ny
        });
      }
    } else if (dNxt <= 0) {
      let t = dCur / (dCur - dNxt);
      out.push({
        x: cur.x + t * (nxt.x - cur.x),
        y: cur.y + t * (nxt.y - cur.y),
        nx,
        ny
      });
    }
  }
  return out;
}

function polygonCentroid(poly) {
  let cx = 0,
    cy = 0,
    area = 0;
  let n = poly.length;
  if (n < 3) return { x: 0, y: 0, area: 0 };
  for (let i = 0; i < n; i++) {
    let p0 = poly[i];
    let p1 = poly[(i + 1) % n];
    let cross = p0.x * p1.y - p1.x * p0.y;
    area += cross;
    cx += (p0.x + p1.x) * cross;
    cy += (p0.y + p1.y) * cross;
  }
  area *= 0.5;
  if (abs(area) < 1e-4) {
    for (let p of poly) {
      cx += p.x;
      cy += p.y;
    }
    return { x: cx / n, y: cy / n, area: 0 };
  }
  return { x: cx / (6 * area), y: cy / (6 * area), area: abs(area) };
}

function buildVoronoiTessellation() {
  let seeds = [];

  // 1. Place an inner anatomical guard ring of seeds inside the eye socket
  // so the peri-orbital Voronoi cells terminate cleanly around the eyelids!
  let ringCount = 16;
  for (let i = 0; i < ringCount; i++) {
    let ang = (i / ringCount) * 360;
    let p = fromEyeSpace(cos(ang) * 132, sin(ang) * 98);
    seeds.push({
      x: p.x,
      y: p.y,
      spacing: 34,
      isEyeCore: true,
      pinned: true
    });
  }

  // Second orbital ring (small transitional brow/cheek cells)
  let outerRingCount = 22;
  for (let i = 0; i < outerRingCount; i++) {
    let ang = (i / outerRingCount) * 360 + 8;
    let rx = 182 + random(-10, 10);
    let ry = 142 + random(-10, 10);
    let p = fromEyeSpace(cos(ang) * rx, sin(ang) * ry);
    seeds.push({
      x: p.x,
      y: p.y,
      spacing: 44,
      isEyeCore: false,
      pinned: true
    });
  }

  // 2. Variable-density Poisson-disc seed sampling over [-140, 1340]^2
  let attempts = 16000;
  for (let a = 0; a < attempts; a++) {
    let px = random(-130, W + 130);
    let py = random(-130, H + 130);

    // Exclude interior of eye opening
    let es = toEyeSpace(px, py);
    let eyeNorm = sqrt((es.u / 160) * (es.u / 160) + (es.v / 122) * (es.v / 122));
    if (eyeNorm < 1.02) continue;

    let sp = getTargetSpacing(px, py);
    let ok = true;
    for (let s of seeds) {
      let minDist = 0.76 * min(sp, s.spacing);
      let dx = px - s.x;
      let dy = py - s.y;
      if (dx * dx + dy * dy < minDist * minDist) {
        ok = false;
        break;
      }
    }
    if (ok) {
      seeds.push({
        x: px,
        y: py,
        spacing: sp,
        isEyeCore: false,
        pinned: false
      });
    }
  }

  // 3. Weighted Lloyd relaxation (3 iterations) for crisp, balanced Voronoi cells
  for (let iter = 0; iter < 3; iter++) {
    for (let i = 0; i < seeds.length; i++) {
      let s = seeds[i];
      if (s.pinned) continue;

      let R = s.spacing * 2.2;
      let poly = [
        { x: s.x - R, y: s.y - R },
        { x: s.x + R, y: s.y - R },
        { x: s.x + R, y: s.y + R },
        { x: s.x - R, y: s.y + R }
      ];

      for (let j = 0; j < seeds.length; j++) {
        if (i === j) continue;
        let o = seeds[j];
        let dx = o.x - s.x;
        let dy = o.y - s.y;
        let d2 = dx * dx + dy * dy;
        if (d2 > R * R * 4) continue;
        let d = sqrt(d2);
        let nx = dx / d;
        let ny = dy / d;
        // Anisotropic weighting slightly favors elongation along neck flow
        let weightRatio = s.spacing / (s.spacing + o.spacing);
        let mx = s.x + dx * weightRatio;
        let my = s.y + dy * weightRatio;
        poly = clipHalfPlane(poly, mx, my, nx, ny);
        if (poly.length < 3) break;
      }

      if (poly.length >= 3) {
        let c = polygonCentroid(poly);
        let nx = lerp(s.x, c.x, 0.52);
        let ny = lerp(s.y, c.y, 0.52);
        let es = toEyeSpace(nx, ny);
        if ((es.u / 158) * (es.u / 158) + (es.v / 120) * (es.v / 120) > 1.02) {
          s.x = nx;
          s.y = ny;
          s.spacing = getTargetSpacing(s.x, s.y);
        }
      }
    }
  }

  // 4. Compute final mathematical Voronoi polygon AND organic channel-inset polygon for each cell
  let cells = [];
  for (let i = 0; i < seeds.length; i++) {
    let s = seeds[i];
    if (s.isEyeCore) continue;

    // Skip cells completely outside the 1200x1200 canvas
    if (s.x < -110 || s.x > W + 110 || s.y < -110 || s.y > H + 110) continue;

    let R = s.spacing * 2.4;
    let mathPoly = [
      { x: s.x - R, y: s.y - R },
      { x: s.x + R, y: s.y - R },
      { x: s.x + R, y: s.y + R },
      { x: s.x - R, y: s.y + R }
    ];
    let insetPoly = [
      { x: s.x - R, y: s.y - R },
      { x: s.x + R, y: s.y - R },
      { x: s.x + R, y: s.y + R },
      { x: s.x - R, y: s.y + R }
    ];

    // Sort neighbors by distance
    let neighbors = [];
    for (let j = 0; j < seeds.length; j++) {
      if (i === j) continue;
      let o = seeds[j];
      let dx = o.x - s.x;
      let dy = o.y - s.y;
      let d2 = dx * dx + dy * dy;
      if (d2 < R * R * 4.2) {
        neighbors.push({ seed: o, d: sqrt(d2), dx, dy });
      }
    }
    neighbors.sort((a, b) => a.d - b.d);

    for (let nb of neighbors) {
      let o = nb.seed;
      let d = nb.d;
      let nx = nb.dx / d;
      let ny = nb.dy / d;
      let wRatio = s.spacing / (s.spacing + o.spacing);
      let mx = s.x + nb.dx * wRatio;
      let my = s.y + nb.dy * wRatio;

      // Exact mathematical Voronoi boundary
      mathPoly = clipHalfPlane(mathPoly, mx, my, nx, ny);

      // Cream channel half-width between cell i and neighbor o
      let avgSp = 0.5 * (s.spacing + o.spacing);
      let baseGap = map(constrain(avgSp, 34, 190), 34, 190, 3.8, 17.5);
      let noiseMod = 0.72 + 0.58 * noise(mx * 0.007 + 10, my * 0.007 + 10);
      let halfGap = baseGap * noiseMod * 0.52;

      insetPoly = clipHalfPlane(
        insetPoly,
        mx - nx * halfGap,
        my - ny * halfGap,
        nx,
        ny
      );
    }

    if (insetPoly.length < 3 || mathPoly.length < 3) continue;

    let cInfo = polygonCentroid(insetPoly);
    if (cInfo.area < 140) continue;

    // Check if visible on canvas
    if (
      cInfo.x < -90 ||
      cInfo.x > W + 90 ||
      cInfo.y < -90 ||
      cInfo.y > H + 90
    ) {
      continue;
    }

    // 5. Transform insetPoly into a biological Voronoi cell where:
    //    - Triple junctions (corners) round & widen the cream channel (Plateau's law)
    //    - Shared edges bow slightly outward & undulate so the cream channel thins and widens!
    let organicPoly = [];
    let innerCorePoly = [];
    let nv = insetPoly.length;
    let avgGap = map(constrain(s.spacing, 34, 190), 34, 190, 3.8, 17.5);

    for (let k = 0; k < nv; k++) {
      let pPrev = insetPoly[(k - 1 + nv) % nv];
      let pCur = insetPoly[k];
      let pNext = insetPoly[(k + 1) % nv];

      let edgeLen = dist(pCur.x, pCur.y, pNext.x, pNext.y);
      if (edgeLen < 4) continue;

      // Outward normal of edge (pCur -> pNext)
      let ex = (pNext.x - pCur.x) / edgeLen;
      let ey = (pNext.y - pCur.y) / edgeLen;
      let outNx = ey;
      let outNy = -ex;
      // Ensure normal points away from centroid
      if (
        outNx * (pCur.x - cInfo.x) + outNy * (pCur.y - cInfo.y) < 0
      ) {
        outNx = -outNx;
        outNy = -outNy;
      }

      // Corner rounding & inward pull at triple junction (widens channel at vertices)
      let tCorner = constrain(avgGap * 0.42 / edgeLen, 0.12, 0.26);
      let cPull = avgGap * (0.28 + 0.25 * noise(pCur.x * 0.02, pCur.y * 0.02));

      let p1x = lerp(pCur.x, pNext.x, tCorner);
      let p1y = lerp(pCur.y, pNext.y, tCorner);
      let v1x = cInfo.x - p1x;
      let v1y = cInfo.y - p1y;
      let v1Len = sqrt(v1x * v1x + v1y * v1y) + 1e-4;
      p1x += (v1x / v1Len) * cPull;
      p1y += (v1y / v1Len) * cPull;
      organicPoly.push({ x: p1x, y: p1y });

      // Mid-edge points: push slightly outward so channel thins along the middle of the edge,
      // modulated by biological indentation noise (serrated giraffe patch bays)
      let subSteps = edgeLen > 75 ? 3 : edgeLen > 35 ? 2 : 1;
      for (let m = 1; m <= subSteps; m++) {
        let t = map(m, 0, subSteps + 1, tCorner, 1 - tCorner);
        let mx = lerp(pCur.x, pNext.x, t);
        let my = lerp(pCur.y, pNext.y, t);

        let arch = sin(t * 180); // peaks at mid-edge (1.0)
        let nWave = noise(mx * 0.018 + i * 3.1, my * 0.018) - 0.44;
        // Channel thins at mid-edge (+outward), or pinches inward at a biological bay
        let swell = avgGap * (0.24 * arch + 0.34 * nWave);
        mx += outNx * swell;
        my += outNy * swell;
        organicPoly.push({ x: mx, y: my });
      }

      let p2x = lerp(pCur.x, pNext.x, 1 - tCorner);
      let p2y = lerp(pCur.y, pNext.y, 1 - tCorner);
      let v2x = cInfo.x - p2x;
      let v2y = cInfo.y - p2y;
      let v2Len = sqrt(v2x * v2x + v2y * v2y) + 1e-4;
      p2x += (v2x / v2Len) * cPull;
      p2y += (v2y / v2Len) * cPull;
      organicPoly.push({ x: p2x, y: p2y });
    }

    // Build inner pigment core polygon (for concentrated liver-brown / sienna center blooms)
    for (let pt of organicPoly) {
      let scale = 0.62 + 0.22 * noise(pt.x * 0.015 + i, pt.y * 0.015);
      innerCorePoly.push({
        x: lerp(cInfo.x, pt.x, scale),
        y: lerp(cInfo.y, pt.y, scale)
      });
    }

    // Determine cell color family & lighting from 3D surface model
    let surf = getSurfaceLight(cInfo.x, cInfo.y);
    let colorPick = noise(cInfo.x * 0.004, cInfo.y * 0.004, 7.7);

    // Assign to one of 9 batched watercolor buckets:
    // 0..2: Burnt Orange (sunlit & vibrant)
    // 3..5: Chestnut (classic rich giraffe reddish-brown)
    // 6..8: Liver Brown (deep dark espresso-mahogany)
    let bucket;
    let bias = colorPick + surf.light * 0.25 - (1 - surf.light) * 0.2;
    if (bias > 0.66) {
      bucket = floor(random(0, 3)); // Burnt Orange
    } else if (bias > 0.38) {
      bucket = floor(random(3, 6)); // Chestnut
    } else {
      bucket = floor(random(6, 9)); // Liver Brown
    }

    cells.push({
      id: i,
      seed: s,
      centroid: cInfo,
      mathPoly,
      organicPoly,
      innerCorePoly,
      spacing: s.spacing,
      surf,
      bucket
    });
  }

  return cells;
}

// Helper to draw a closed polygon with p5.brush beginShape/vertex/endShape
function drawBrushShape(pts, curvature = 0.32) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
}

// Point-in-polygon test (ray casting)
function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i].x,
      yi = poly[i].y;
    let xj = poly[j].x,
      yj = poly[j].y;
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-7) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

// ---------------------------------------------------------------------------
// Main Render Pipeline
// ---------------------------------------------------------------------------

function draw() {
  // Warm sunlit parchment-cream ground
  background("#f4e5c8");
  translate(-W / 2, -H / 2);

  // Build the mathematical + biological Voronoi tessellation
  let cells = buildVoronoiTessellation();

  // =========================================================================
  // PASS 1: 3D Sculptural Underpainting on the Cream Channels & Hide Ground
  // =========================================================================
  brush.noStroke();

  // 1A. Sunlit golden-apricot raking light washes along the upper-left neck arch & brow ridge
  let sunlitBlobs = [
    { x: 240, y: 340, rx: 320, ry: 420, col: "#fae8be", op: 75 },
    { x: 140, y: 680, rx: 280, ry: 440, col: "#f7d594", op: 68 },
    { x: 480, y: 180, rx: 340, ry: 230, col: "#f9dfaa", op: 72 },
    { x: 740, y: 290, rx: 240, ry: 130, col: "#f6ce84", op: 65 },
    { x: 690, y: 585, rx: 210, ry: 120, col: "#f2c479", op: 55 }
  ];
  for (let b of sunlitBlobs) {
    brush.fill(b.col, b.op);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.55, 0.35);
    let pts = [];
    for (let a = 0; a < 360; a += 24) {
      let rMod = 0.85 + 0.3 * noise(cos(a) + b.x * 0.01, sin(a) + b.y * 0.01);
      pts.push({
        x: b.x + cos(a) * b.rx * rMod,
        y: b.y + sin(a) * b.ry * rMod
      });
    }
    drawBrushShape(pts, 0.45);
  }

  // 1B. Sculptural shadow washes in the jugular furrow, lower-right throat, and orbital socket
  let shadowBlobs = [
    { x: 420, y: 880, rx: 190, ry: 340, col: "#cfa06e", op: 62 },
    { x: 880, y: 960, rx: 360, ry: 320, col: "#c28f5e", op: 68 },
    { x: 1060, y: 680, rx: 240, ry: 360, col: "#b58050", op: 64 },
    { x: 780, y: 435, rx: 235, ry: 180, col: "#b88254", op: 72 },
    { x: 775, y: 432, rx: 175, ry: 132, col: "#7a492e", op: 85 }
  ];
  for (let b of shadowBlobs) {
    brush.fill(b.col, b.op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.62, 0.45);
    let pts = [];
    for (let a = 0; a < 360; a += 24) {
      let rMod = 0.85 + 0.3 * noise(cos(a) * 1.3 + b.x, sin(a) * 1.3 + b.y);
      pts.push({
        x: b.x + cos(a) * b.rx * rMod,
        y: b.y + sin(a) * b.ry * rMod
      });
    }
    drawBrushShape(pts, 0.45);
  }
  brush.noFill();

  // =========================================================================
  // PASS 2: Mathematical Voronoi Diagram Skeleton in the Cream Channels
  // ("The pattern is both a mathematical diagram and a living animal")
  // =========================================================================
  // Delicate bisector lines, triple-junction vertex nodes, and seed centroids
  brush.set("2H", "#9c724c", 0.32);
  for (let c of cells) {
    let mp = c.mathPoly;
    for (let k = 0; k < mp.length; k++) {
      let p0 = mp[k];
      let p1 = mp[(k + 1) % mp.length];
      // Draw subtle mathematical bisector line along the center of the cream channel
      if (random() < 0.78) {
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }

  // Triple-junction mathematical vertices & subtle Delaunay/centroid ticks
  brush.set("rotring", "#875c39", 0.26);
  for (let c of cells) {
    // Small geometric ticks at select triple junctions
    for (let v of c.mathPoly) {
      if (v.x > 10 && v.x < W - 10 && v.y > 10 && v.y < H - 10 && random() < 0.28) {
        brush.circle(v.x, v.y, 2.2, 0.15);
      }
    }
    // Faint seed centroid crosshair + hair-vector tangent indicator
    if (c.spacing > 55 && random() < 0.55) {
      let cx = c.centroid.x;
      let cy = c.centroid.y;
      let ang = getHairAngle(cx, cy);
      brush.line(cx - 4, cy, cx + 4, cy);
      brush.line(cx, cy - 4, cx, cy + 4);
      brush.line(
        cx,
        cy,
        cx + cos(ang) * (c.spacing * 0.22),
        cy + sin(ang) * (c.spacing * 0.22)
      );
    }
  }

  // =========================================================================
  // PASS 3: Watercolor Voronoi Cells with Pooled Wet Edges (Batched by Color)
  // =========================================================================
  // 9 rich warm watercolor pigment buckets:
  // 0..2: Burnt Orange, 3..5: Chestnut, 6..8: Liver Brown
  const WATERCOLOR_BUCKETS = [
    { base: "#d45c20", core: "#9e3612", rim: "#7a240b", op: 155 }, // 0: Sunlit Burnt Orange
    { base: "#c24918", core: "#87290f", rim: "#631b09", op: 165 }, // 1: Deep Burnt Orange
    { base: "#df6e2b", core: "#ad4216", rim: "#822b0e", op: 150 }, // 2: Luminous Amber-Orange
    { base: "#99381c", core: "#5e1c0f", rim: "#471309", op: 170 }, // 3: Warm Chestnut
    { base: "#852d16", core: "#4f160c", rim: "#3b0f07", op: 178 }, // 4: Deep Red Chestnut
    { base: "#a84322", core: "#6b2212", rim: "#4d150a", op: 165 }, // 5: Bright Sienna-Chestnut
    { base: "#5c2116", core: "#36100b", rim: "#290b07", op: 185 }, // 6: Rich Liver Brown
    { base: "#4a1911", core: "#2b0c08", rim: "#1f0805", op: 192 }, // 7: Dark Espresso-Liver
    { base: "#6b281a", core: "#3f140d", rim: "#2e0d08", op: 178 }  // 8: Warm Claret-Liver
  ];

  // 3A. Base Watercolor Washes (batched by color bucket for high performance & edge pooling)
  // High borderIntensity (0.88) in fillTexture creates authentic capillary pigment pooling at cell edges!
  brush.noStroke();
  for (let b = 0; b < WATERCOLOR_BUCKETS.length; b++) {
    let spec = WATERCOLOR_BUCKETS[b];
    brush.fill(spec.base, spec.op);
    brush.fillBleed(0.15, "out");
    brush.fillTexture(0.72, 0.9);

    for (let c of cells) {
      if (c.bucket === b) {
        drawBrushShape(c.organicPoly, 0.34);
      }
    }
  }

  // 3B. Secondary Wet-in-Wet Inner Core Blooms (deeper liver/mahogany centers & sunlit blooms)
  for (let b = 0; b < WATERCOLOR_BUCKETS.length; b++) {
    let spec = WATERCOLOR_BUCKETS[b];
    brush.fill(spec.core, floor(spec.op * 0.72));
    brush.fillBleed(0.24, "in");
    brush.fillTexture(0.78, 0.85);

    for (let c of cells) {
      if (c.bucket === b && c.spacing > 42) {
        drawBrushShape(c.innerCorePoly, 0.38);
      }
    }
  }
  brush.noFill();

  // 3C. Explicit Pooled Wet Watercolor Edges around Every Voronoi Cell
  for (let b = 0; b < WATERCOLOR_BUCKETS.length; b++) {
    let spec = WATERCOLOR_BUCKETS[b];
    brush.set("wet_rim", spec.rim, 0.95);
    for (let c of cells) {
      if (c.bucket !== b) continue;
      let poly = c.organicPoly;
      let pts = [];
      for (let k = 0; k <= poly.length; k++) {
        let p = poly[k % poly.length];
        let pWeight = 0.65 + 0.75 * noise(p.x * 0.025, p.y * 0.025);
        pts.push([p.x, p.y, pWeight]);
      }
      if (pts.length >= 3) {
        brush.spline(pts, 0.35);
      }
    }
  }

  // =========================================================================
  // PASS 4: Coloured-Pencil Short Hair Direction & Late-Afternoon Raking Nap
  // =========================================================================

  // 4A. Per-Cell Directional Coloured-Pencil Hatching (bridges diagram & fur grain)
  brush.noStroke();
  brush.noFill();
  for (let c of cells) {
    let cx = c.centroid.x;
    let cy = c.centroid.y;
    let hairAng = getHairAngle(cx, cy);
    let spec = WATERCOLOR_BUCKETS[c.bucket];

    // Spacing scales with cell size but stays fine like short dense hairs
    let hDist = map(constrain(c.spacing, 34, 190), 34, 190, 3.2, 5.2);

    // Primary coloured-pencil hair grain
    let hatchCol = c.surf.light > 0.55 ? "#d96b27" : spec.core;
    brush.hatchStyle("cpencil", hatchCol, 0.42);
    brush.hatch(hDist, hairAng, { rand: 0.14, gradient: 0.22 });
    drawBrushShape(c.organicPoly, 0.25);

    // Secondary warm raking-light pencil grain on sunlit cells
    if (c.surf.light > 0.48) {
      let napCol = c.surf.raking > 0.35 ? "#f5a642" : "#c7551e";
      brush.hatchStyle("cpencil", napCol, 0.34);
      brush.hatch(hDist * 1.45, hairAng + 5, { rand: 0.18, gradient: 0.35 });
      drawBrushShape(c.organicPoly, 0.25);
    }
  }
  brush.noHatch();

  // 4B. Fine Individual Coloured-Pencil Fur Strokes in the Cream Channels
  //     (laying the short hair direction across the thinning & widening channels)
  const CHANNEL_PENCIL_COLORS = [
    "#fff6de", // Sunlit ivory-cream
    "#f7d794", // Warm golden-cream
    "#e6b873", // Honey buff
    "#c99255", // Mid-tone warm ochre
    "#9e6b3b"  // Shadowed channel umber
  ];

  // Sample points along the mathematical Voronoi edges (which lie in the middle of the cream channels!)
  for (let pass = 0; pass < CHANNEL_PENCIL_COLORS.length; pass++) {
    brush.set("cpencil", CHANNEL_PENCIL_COLORS[pass], 0.42);

    for (let c of cells) {
      let mp = c.mathPoly;
      let op = c.organicPoly;
      let n = mp.length;

      for (let k = 0; k < n; k++) {
        let a = mp[k];
        let b = mp[(k + 1) % n];
        let edgeLen = dist(a.x, a.y, b.x, b.y);
        let steps = floor(edgeLen / 5.5);

        for (let s = 0; s <= steps; s++) {
          let t = s / max(1, steps);
          let px = lerp(a.x, b.x, t) + random(-3.5, 3.5);
          let py = lerp(a.y, b.y, t) + random(-3.5, 3.5);
          if (px < -20 || px > W + 20 || py < -20 || py > H + 20) continue;

          let surf = getSurfaceLight(px, py);
          if (surf.dEye < 125) continue;

          // Choose pencil tone based on local 3D lighting and raking angle
          let targetPass;
          if (surf.raking > 0.48) targetPass = 0;
          else if (surf.light > 0.68) targetPass = 1;
          else if (surf.light > 0.48) targetPass = 2;
          else if (surf.light > 0.30) targetPass = 3;
          else targetPass = 4;

          if (targetPass !== pass && random() > 0.22) continue;

          let ang = getHairAngle(px, py) + random(-5, 5);
          let hLen = map(constrain(c.spacing, 34, 190), 34, 190, 7, 17) * random(0.8, 1.25);
          let x2 = px + cos(ang) * hLen;
          let y2 = py + sin(ang) * hLen;
          brush.line(px, py, x2, y2);
        }
      }
    }
  }

  // 4C. Layered Coloured-Pencil Fur Strokes Over Each Voronoi Cell & Interdigitating Edges
  const PATCH_PENCIL_PALETTE = [
    { col: "#260b06", w: 0.44 }, // 0: Deep espresso-black shadow hairs
    { col: "#4a170e", w: 0.42 }, // 1: Dark liver-brown guard hairs
    { col: "#7d2a14", w: 0.40 }, // 2: Rich chestnut coat hairs
    { col: "#b84618", w: 0.40 }, // 3: Burnt sienna / rust hairs
    { col: "#e67828", w: 0.38 }, // 4: Glowing tangerine raking-light hairs
    { col: "#f7be63", w: 0.35 }  // 5: Molten gold fur-nap highlights
  ];

  for (let pIdx = 0; pIdx < PATCH_PENCIL_PALETTE.length; pIdx++) {
    let pSpec = PATCH_PENCIL_PALETTE[pIdx];
    brush.set("fine_hair", pSpec.col, pSpec.w);

    for (let c of cells) {
      let cx = c.centroid.x;
      let cy = c.centroid.y;
      let surf = c.surf;
      let rad = sqrt(c.centroid.area / PI);

      // Determine how many hairs of this pigment tone belong in this cell
      let count = floor(constrain(c.centroid.area / 230, 8, 65));

      for (let h = 0; h < count; h++) {
        // Sample inside cell via convex combination of centroid and two adjacent polygon vertices
        let op = c.organicPoly;
        let idx = floor(random(op.length));
        let vA = op[idx];
        let vB = op[(idx + 1) % op.length];
        let u1 = random(0.1, 0.95);
        let u2 = random(0, 1);
        let edgePtX = lerp(vA.x, vB.x, u2);
        let edgePtY = lerp(vA.y, vB.y, u2);
        // Bias toward cell perimeter when drawing raking rim highlights or dark edge interdigitation
        let radialBias = pIdx === 5 || pIdx === 1 ? pow(u1, 0.45) : sqrt(u1);
        let hx = lerp(cx, edgePtX, radialBias);
        let hy = lerp(cy, edgePtY, radialBias);

        let localSurf = getSurfaceLight(hx, hy);

        // Select pigment layer based on cell bucket, 3D lighting, and raking nap
        let drawThis = false;
        if (pIdx === 0 && (c.bucket >= 6 || localSurf.light < 0.38) && random() < 0.65) {
          drawThis = true;
        } else if (pIdx === 1 && c.bucket >= 3 && random() < 0.72) {
          drawThis = true;
        } else if (pIdx === 2 && c.bucket <= 6 && random() < 0.75) {
          drawThis = true;
        } else if (pIdx === 3 && (c.bucket <= 4 || localSurf.light > 0.5) && random() < 0.68) {
          drawThis = true;
        } else if (pIdx === 4 && localSurf.light > 0.58 && random() < 0.52) {
          drawThis = true;
        } else if (
          pIdx === 5 &&
          (localSurf.raking > 0.32 || (radialBias > 0.78 && hx < cx && hy < cy)) &&
          localSurf.light > 0.55 &&
          random() < 0.48
        ) {
          drawThis = true;
        }

        if (!drawThis) continue;

        let ang = getHairAngle(hx, hy) + random(-4.5, 4.5);
        let hLen = map(constrain(c.spacing, 34, 190), 34, 190, 8, 19) * random(0.75, 1.25);
        brush.line(hx, hy, hx + cos(ang) * hLen, hy + sin(ang) * hLen);
      }
    }
  }

  // 4D. Intense Late-Afternoon Raking Light Catching the Fur's Nap
  //     Along the upper-left neck crest, brow ridge, cheekbone, and sun-facing cell rims
  brush.set("cpencil", "#ffe8a6", 0.38);
  for (let i = 0; i < 950; i++) {
    let rx = random(0, W * 0.85);
    let ry = random(0, H);
    let surf = getSurfaceLight(rx, ry);
    if (surf.dEye < 135) continue;

    if (surf.raking > 0.38 && random() < surf.raking * 0.95) {
      let ang = getHairAngle(rx, ry) + random(-6, 6);
      let len = random(9, 20);
      brush.line(rx, ry, rx + cos(ang) * len, ry + sin(ang) * len);
    }
  }

  // =========================================================================
  // PASS 5: Peri-Orbital Skin Folds, Huge Glossy Dark Sphere Eye & Eyelashes
  // =========================================================================
  renderGiraffeEye();

  noLoop();
}

// ---------------------------------------------------------------------------
// Hyperreal Giraffe Eye, Orbital Folds, Savanna Sky Reflection & Long Lashes
// ---------------------------------------------------------------------------

function renderGiraffeEye() {
  // 1. Peri-Orbital Soft Velvety Skin Transition & Concentric Eyelid Folds
  brush.noStroke();

  // Outer warm umber socket shadow
  let socketRings = [
    { rx: 168, ry: 128, offU: -4, offV: 4, col: "#6e3d25", op: 95 },
    { rx: 148, ry: 112, offU: -2, offV: 2, col: "#4f2818", op: 115 },
    { rx: 132, ry: 96, offU: 0, offV: 2, col: "#33180f", op: 140 },
    { rx: 118, ry: 82, offU: 2, offV: 3, col: "#1f0d08", op: 175 }
  ];

  for (let ring of socketRings) {
    brush.fill(ring.col, ring.op);
    brush.fillBleed(0.18, "out");
    brush.fillTexture(0.68, 0.72);
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      let u = ring.offU + cos(a) * ring.rx;
      let v = ring.offV + sin(a) * ring.ry;
      // Pinch slightly at lateral (left) and medial tear-duct (right) corners
      if (cos(a) > 0.65) {
        u += pow(cos(a) - 0.65, 1.4) * 42;
        v += pow(cos(a) - 0.65, 1.2) * 14;
      }
      if (cos(a) < -0.65) {
        u -= pow(-cos(a) - 0.65, 1.4) * 28;
      }
      pts.push(fromEyeSpace(u, v));
    }
    drawBrushShape(pts, 0.38);
  }
  brush.noFill();

  // Sculptural Upper Brow & Eyelid Creases (3 concentric arched folds above the eye)
  let upperCreases = [
    { vPeak: -102, uSpan: 158, arch: 58, shadowCol: "#29120b", lightCol: "#cfa06b" },
    { vPeak: -84, uSpan: 144, arch: 50, shadowCol: "#1e0c07", lightCol: "#b88252" },
    { vPeak: -67, uSpan: 132, arch: 42, shadowCol: "#140704", lightCol: "#99653c" }
  ];

  for (let cr of upperCreases) {
    // Sunlit ridge above crease
    brush.set("soft_glaze", cr.lightCol, 1.35);
    let lightPts = [];
    for (let t = -1; t <= 1; t += 0.1) {
      let u = t * cr.uSpan;
      let v = cr.vPeak - 6 + t * t * cr.arch;
      let p = fromEyeSpace(u, v);
      lightPts.push([p.x, p.y, 1 - 0.55 * t * t]);
    }
    brush.spline(lightPts, 0.4);

    // Deep crease shadow line
    brush.set("wet_rim", cr.shadowCol, 1.15);
    let darkPts = [];
    for (let t = -1; t <= 1; t += 0.1) {
      let u = t * cr.uSpan;
      let v = cr.vPeak + t * t * cr.arch;
      let p = fromEyeSpace(u, v);
      darkPts.push([p.x, p.y, 1.2 - 0.6 * t * t]);
    }
    brush.spline(darkPts, 0.4);
  }

  // Lower Eyelid Bag Folds (soft concentric wrinkles beneath the globe)
  let lowerCreases = [
    { vPeak: 72, uSpan: 122, arch: -34, shadowCol: "#1a0a06", lightCol: "#8f5c38" },
    { vPeak: 92, uSpan: 138, arch: -42, shadowCol: "#2b130c", lightCol: "#ab764b" },
    { vPeak: 112, uSpan: 148, arch: -46, shadowCol: "#452115", lightCol: "#c99565" }
  ];

  for (let cr of lowerCreases) {
    brush.set("soft_glaze", cr.lightCol, 1.1);
    let lightPts = [];
    for (let t = -1; t <= 1; t += 0.1) {
      let u = t * cr.uSpan;
      let v = cr.vPeak - 5 + t * t * cr.arch;
      let p = fromEyeSpace(u, v);
      lightPts.push([p.x, p.y, 1 - 0.5 * t * t]);
    }
    brush.spline(lightPts, 0.4);

    brush.set("wet_rim", cr.shadowCol, 0.95);
    let darkPts = [];
    for (let t = -1; t <= 1; t += 0.1) {
      let u = t * cr.uSpan;
      let v = cr.vPeak + t * t * cr.arch;
      let p = fromEyeSpace(u, v);
      darkPts.push([p.x, p.y, 1.1 - 0.5 * t * t]);
    }
    brush.spline(darkPts, 0.4);
  }

  // Fine velvety peri-orbital hairs along eyelids and brow
  const EYELID_FUR = [
    { col: "#261009", rMin: 78, rMax: 145, count: 420 },
    { col: "#592b18", rMin: 88, rMax: 165, count: 380 },
    { col: "#9e633a", rMin: 95, rMax: 175, count: 340 },
    { col: "#e3a664", rMin: 98, rMax: 178, count: 260 }
  ];
  for (let ef of EYELID_FUR) {
    brush.set("fine_hair", ef.col, 0.34);
    for (let i = 0; i < ef.count; i++) {
      let ang = random(0, 360);
      let r = random(ef.rMin, ef.rMax);
      let u = cos(ang) * r * 1.18;
      let v = sin(ang) * r * 0.86;
      let p = fromEyeSpace(u, v);
      let surf = getSurfaceLight(p.x, p.y);
      if (ef.col === "#e3a664" && surf.light < 0.48) continue;
      let hAng = getHairAngle(p.x, p.y) + random(-6, 6);
      let hLen = random(5, 11);
      brush.line(p.x, p.y, p.x + cos(hAng) * hLen, p.y + sin(hAng) * hLen);
    }
  }

  // =========================================================================
  // 2. The Glossy Dark Sphere (Cornea, Warm Mahogany Iris & Pupil)
  // =========================================================================

  // Helper function for upper and lower eyelid margin curves in eye-local (u, v) space
  // u in [-118, +126] (left lateral canthus to right medial tear-duct canthus)
  function upperLidV(u) {
    let t = map(u, -118, 126, -1, 1);
    // High, protective arch over the spherical globe, dipping toward the tear duct at right
    return -58 * (1 - t * t) + 8 * pow(max(0, t), 1.6);
  }

  function lowerLidV(u) {
    let t = map(u, -118, 126, -1, 1);
    // Deep, rounded lower curve cradling the sphere, narrowing into the tear duct at right
    return 56 * (1 - t * t) + 8 * pow(max(0, t), 1.4);
  }

  // Build exact palpebral opening polygon
  let eyeOpeningPoly = [];
  for (let u = -118; u <= 126; u += 10) {
    eyeOpeningPoly.push(fromEyeSpace(u, upperLidV(u)));
  }
  for (let u = 126; u >= -118; u -= 10) {
    eyeOpeningPoly.push(fromEyeSpace(u, lowerLidV(u)));
  }

  // Base obsidian-espresso eyeball fill
  brush.noStroke();
  brush.wash("#0d0504", 245);
  drawBrushShape(eyeOpeningPoly, 0.25);
  brush.noWash();

  // Spherical eyeball core (radius ~ 88 in u, ~ 56 in v visible)
  let globePoly = [];
  for (let a = 0; a < 360; a += 15) {
    let u = cos(a) * 92;
    let v = sin(a) * 55;
    v = constrain(v, upperLidV(u) + 1.5, lowerLidV(u) - 1.5);
    globePoly.push(fromEyeSpace(u, v));
  }
  brush.wash("#140806", 240);
  drawBrushShape(globePoly, 0.35);
  brush.noWash();

  // Warm Subsurface Amber / Mahogany Iris Crescent in the lower hemisphere
  // (where raking light refracts through the curved cornea into the bottom of the dark brown iris)
  let irisLayers = [
    { uOff: 6, vMin: 4, vMax: 50, uSpan: 78, col: "#4a1b0b", op: 165 },
    { uOff: 8, vMin: 12, vMax: 48, uSpan: 68, col: "#752e12", op: 155 },
    { uOff: 10, vMin: 20, vMax: 45, uSpan: 54, col: "#a34619", op: 145 },
    { uOff: 12, vMin: 26, vMax: 42, uSpan: 38, col: "#cc6424", op: 130 }
  ];

  for (let il of irisLayers) {
    brush.fill(il.col, il.op);
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.6, 0.4);
    let iPts = [];
    for (let t = -1; t <= 1; t += 0.16) {
      let u = il.uOff + t * il.uSpan;
      let vTop = il.vMin + t * t * (il.vMax - il.vMin) * 0.65;
      iPts.push(fromEyeSpace(u, min(vTop, lowerLidV(u) - 3)));
    }
    for (let t = 1; t >= -1; t -= 0.16) {
      let u = il.uOff + t * il.uSpan;
      let vBot = min(il.vMax * (1 - 0.35 * t * t), lowerLidV(u) - 3);
      iPts.push(fromEyeSpace(u, vBot));
    }
    drawBrushShape(iPts, 0.35);
  }
  brush.noFill();

  // Delicate radial iris stroma fibers in warm copper, mahogany, and espresso
  for (let a = 12; a < 168; a += 2.5) {
    let r1 = random(24, 34);
    let r2 = random(52, 76);
    let u1 = cos(a) * r1 * 1.1;
    let v1 = sin(a) * r1 * 0.62;
    let u2 = cos(a) * r2 * 1.12;
    let v2 = min(sin(a) * r2 * 0.66, lowerLidV(u2) - 4);
    let p1 = fromEyeSpace(u1, v1);
    let p2 = fromEyeSpace(u2, v2);
    let col = random() < 0.45 ? "#b8551e" : random() < 0.7 ? "#6e2910" : "#240c06";
    brush.set("fine_hair", col, 0.32);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Deep Horizontal-Oval Giraffe Pupil at center of globe
  brush.noStroke();
  let pupilPoly = [];
  for (let a = 0; a < 360; a += 18) {
    let u = cos(a) * 52;
    let v = -2 + sin(a) * 26;
    pupilPoly.push(fromEyeSpace(u, v));
  }
  brush.wash("#070202", 245);
  drawBrushShape(pupilPoly, 0.4);
  brush.noWash();

  // Medial Canthus (Tear Duct / Caruncle at right corner u = 105..126)
  let carunclePoly = [
    fromEyeSpace(96, -8),
    fromEyeSpace(114, -4),
    fromEyeSpace(125, 6),
    fromEyeSpace(112, 14),
    fromEyeSpace(94, 8)
  ];
  brush.fill("#592218", 190);
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.5, 0.6);
  drawBrushShape(carunclePoly, 0.35);
  brush.noFill();

  // =========================================================================
  // 3. The Savanna Sky Reflection on the Glossy Cornea Sphere
  // =========================================================================
  // Curved reflection window warped across the upper hemisphere of the eyeball
  let skyBands = [
    // Upper cerulean savanna sky dome
    { uSpan: 76, vTop: -44, vBot: -26, col: "#6da1bd", op: 155 },
    { uSpan: 80, vTop: -34, vBot: -18, col: "#97c8de", op: 175 },
    { uSpan: 82, vTop: -24, vBot: -10, col: "#c7e7f2", op: 190 },
    // Warm late-afternoon golden horizon clouds
    { uSpan: 80, vTop: -15, vBot: -3, col: "#fce3aa", op: 205 },
    { uSpan: 72, vTop: -9, vBot: 1, col: "#fff8e3", op: 220 }
  ];

  for (let sb of skyBands) {
    let bPts = [];
    for (let t = -1; t <= 1; t += 0.14) {
      let u = -6 + t * sb.uSpan;
      // Spherical corneal warp
      let warp = (1 - 0.55 * t * t);
      let v = sb.vTop * warp - 10 * (1 - warp);
      v = max(v, upperLidV(u) + 5);
      bPts.push(fromEyeSpace(u, v));
    }
    for (let t = 1; t >= -1; t -= 0.14) {
      let u = -6 + t * sb.uSpan;
      let warp = (1 - 0.55 * t * t);
      let v = sb.vBot * warp - 10 * (1 - warp);
      v = max(v, upperLidV(u) + 6);
      bPts.push(fromEyeSpace(u, v));
    }
    brush.noStroke();
    brush.wash(sb.col, sb.op);
    drawBrushShape(bPts, 0.38);
    brush.noWash();
  }

  // Crisp brilliant specular sun-glint on the upper-left curve of the cornea
  brush.set("soft_glaze", "#ffffff", 1.15);
  let glintPts = [];
  for (let t = -0.75; t <= 0.35; t += 0.12) {
    let u = -8 + t * 72;
    let v = -14 * (1 - 0.5 * t * t) - 6 * (1 - (1 - 0.5 * t * t));
    let p = fromEyeSpace(u, v);
    glintPts.push([p.x, p.y, 1.2 - abs(t + 0.2)]);
  }
  brush.spline(glintPts, 0.4);

  // Subtle Savanna Horizon Silhouette & Flat-Topped Acacia Trees reflected at the base of the sky band
  brush.set("fine_hair", "#26120c", 0.55);
  let hPts = [];
  for (let t = -0.92; t <= 0.92; t += 0.1) {
    let u = -6 + t * 76;
    let warp = 1 - 0.55 * t * t;
    let v = 2 * warp - 9 * (1 - warp);
    let p = fromEyeSpace(u, v);
    hPts.push([p.x, p.y, 0.9]);
  }
  brush.spline(hPts, 0.35);

  // Tiny flat-topped acacia canopy silhouettes inside the corneal reflection
  let acacias = [
    { u: -34, v: -4, w: 18, h: 7 },
    { u: 14, v: -3, w: 22, h: 8 },
    { u: 44, v: -6, w: 13, h: 5 }
  ];
  for (let ac of acacias) {
    let baseP = fromEyeSpace(ac.u, ac.v + 3);
    let topP = fromEyeSpace(ac.u - 1, ac.v - ac.h);
    brush.set("fine_hair", "#2a140d", 0.38);
    brush.line(baseP.x, baseP.y, topP.x, topP.y);
    let cLeft = fromEyeSpace(ac.u - ac.w * 0.5, ac.v - ac.h);
    let cRight = fromEyeSpace(ac.u + ac.w * 0.5, ac.v - ac.h);
    brush.set("wet_rim", "#2a140d", 0.55);
    brush.line(cLeft.x, cLeft.y, cRight.x, cRight.y);
  }

  // Reflected Eyelash Silhouettes cutting across the bright savanna sky reflection!
  brush.set("fine_hair", "#1a0b07", 0.44);
  for (let i = 0; i < 24; i++) {
    let t = map(i, 0, 23, -0.88, 0.85) + random(-0.02, 0.02);
    let uTop = -6 + t * 76;
    let vTop = upperLidV(uTop) + 4;
    let uMid = uTop - 6 + t * 8;
    let vMid = vTop + random(16, 28);
    let uBot = uMid - 8 + t * 12;
    let vBot = vMid + random(12, 22);
    let p0 = fromEyeSpace(uTop, vTop);
    let p1 = fromEyeSpace(uMid, vMid);
    let p2 = fromEyeSpace(uBot, vBot);
    brush.spline(
      [
        [p0.x, p0.y, 1.1],
        [p1.x, p1.y, 0.75],
        [p2.x, p2.y, 0.2]
      ],
      0.4
    );
  }

  // =========================================================================
  // 4. Wet Tear Film Meniscus & Eyelid Rim Modeling
  // =========================================================================

  // Heavy dark upper tarsal eyelid margin casting a soft shadow onto the top of the cornea
  brush.set("wet_rim", "#0b0403", 1.55);
  let upperRimPts = [];
  for (let u = -120; u <= 126; u += 12) {
    let p = fromEyeSpace(u, upperLidV(u));
    upperRimPts.push([p.x, p.y, 1.25]);
  }
  brush.spline(upperRimPts, 0.38);

  // Lower eyelid dark wet rim
  brush.set("wet_rim", "#170906", 1.25);
  let lowerRimPts = [];
  for (let u = -118; u <= 126; u += 12) {
    let p = fromEyeSpace(u, lowerLidV(u) + 2);
    lowerRimPts.push([p.x, p.y, 1.1]);
  }
  brush.spline(lowerRimPts, 0.38);

  // Glistening wet tear meniscus along the lower eyelid margin & caruncle
  brush.set("fine_hair", "#fff8eb", 0.52);
  for (let u = -88; u <= 108; u += 7) {
    if (random() < 0.82) {
      let p1 = fromEyeSpace(u, lowerLidV(u) - 1.2);
      let p2 = fromEyeSpace(u + random(4, 9), lowerLidV(u + 5) - 1.2);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }
  // Pinpoint wet highlights on medial tear duct
  let tearGlint1 = fromEyeSpace(108, 2);
  let tearGlint2 = fromEyeSpace(116, 6);
  brush.set("cpencil", "#ffffff", 0.65);
  brush.line(tearGlint1.x - 2, tearGlint1.y, tearGlint1.x + 3, tearGlint1.y + 1);
  brush.line(tearGlint2.x - 1, tearGlint2.y, tearGlint2.x + 2, tearGlint2.y + 1);

  // =========================================================================
  // 5. Huge, Sweeping Long Eyelashes Catching Late-Afternoon Raking Light
  // =========================================================================

  // Giraffe upper eyelashes grow in a dense, umbrella-like canopy from the upper lid margin,
  // sweeping outward and curving gracefully downward over the cornea and lateral/medial corners.
  let lashCount = 92;
  let lashes = [];

  for (let i = 0; i < lashCount; i++) {
    let t = map(i, 0, lashCount - 1, -0.96, 0.90) + random(-0.012, 0.012);
    let u0 = t * 116;
    let v0 = upperLidV(u0) - random(0, 4);

    // Clump factor: eyelashes naturally group into subtle star-like bundles at their tips
    let clumpCenter = round(t * 14) / 14;
    let clumpPull = (clumpCenter - t) * 28;

    // Lash length peaks across the central-lateral upper arch (up to 145px!)
    let archEnvelope = sin(map(constrain(t, -0.98, 0.95), -0.98, 0.95, 12, 168));
    let len = (48 + 98 * pow(archEnvelope, 0.85)) * random(0.84, 1.14);

    // 3D foreshortening & graceful downward droop + outward flare
    let flareU = t * 44 + clumpPull - 14;
    let u1 = u0 + flareU * 0.42;
    let v1 = v0 - len * 0.14 + len * 0.28 * (1 - archEnvelope * 0.5);

    let u2 = u0 + flareU * 0.88 + random(-4, 4);
    let v2 = v0 + len * (0.42 + 0.25 * abs(t));

    let u3 = u2 + flareU * 0.35 + random(-5, 5);
    let v3 = v2 + len * 0.32;

    lashes.push({
      t,
      p0: fromEyeSpace(u0, v0),
      p1: fromEyeSpace(u1, v1),
      p2: fromEyeSpace(u2, v2),
      p3: fromEyeSpace(u3, v3),
      sunlit: t < 0.55 ? map(t, -0.96, 0.55, 1.0, 0.25) : 0.15
    });
  }

  // Pass 5A: Deep espresso-black lash roots and underside shafts
  for (let l of lashes) {
    let col = random() < 0.6 ? "#0e0503" : "#1f0c07";
    brush.set("fine_hair", col, random(0.52, 0.78));
    brush.spline(
      [
        [l.p0.x, l.p0.y, 1.35],
        [l.p1.x, l.p1.y, 1.05],
        [l.p2.x, l.p2.y, 0.65],
        [l.p3.x, l.p3.y, 0.15]
      ],
      0.42
    );
  }

  // Pass 5B: Warm copper-chestnut mid-shafts where raking light filters through the lash canopy
  for (let l of lashes) {
    if (random() < 0.72) {
      let col = l.sunlit > 0.5 ? "#9e4416" : "#5e240d";
      brush.set("fine_hair", col, random(0.36, 0.52));
      brush.spline(
        [
          [l.p0.x, l.p0.y, 0.9],
          [l.p1.x, l.p1.y, 0.85],
          [l.p2.x, l.p2.y, 0.55],
          [l.p3.x, l.p3.y, 0.15]
        ],
        0.42
      );
    }
  }

  // Pass 5C: Glowing amber, gold, and sunlit cream on the upper curves and tips of the eyelashes!
  for (let l of lashes) {
    if (random() < l.sunlit * 0.92 + 0.15) {
      let tipCol =
        l.sunlit > 0.65 && random() < 0.55
          ? "#ffe49e"
          : l.sunlit > 0.4
          ? "#f2a441"
          : "#c96820";
      brush.set("fine_hair", tipCol, random(0.28, 0.44));
      brush.spline(
        [
          [l.p1.x, l.p1.y - 1, 0.55],
          [l.p2.x, l.p2.y - 1, 0.75],
          [l.p3.x, l.p3.y - 0.5, 0.18]
        ],
        0.42
      );
    }
  }

  // Lower Eyelashes (shorter, delicate, curving downward from the lower tarsal rim)
  let lowerLashCount = 46;
  for (let i = 0; i < lowerLashCount; i++) {
    let t = map(i, 0, lowerLashCount - 1, -0.90, 0.84) + random(-0.02, 0.02);
    let u0 = t * 112;
    let v0 = lowerLidV(u0) + 3;
    let len = random(22, 48) * sin(map(t, -0.95, 0.9, 15, 165));

    let u1 = u0 + t * 14 - 4;
    let v1 = v0 + len * 0.52;
    let u2 = u1 + t * 10 - 3 + random(-3, 3);
    let v2 = v1 + len * 0.52;

    let p0 = fromEyeSpace(u0, v0);
    let p1 = fromEyeSpace(u1, v1);
    let p2 = fromEyeSpace(u2, v2);

    brush.set("fine_hair", "#1a0a06", 0.44);
    brush.spline(
      [
        [p0.x, p0.y, 1.0],
        [p1.x, p1.y, 0.65],
        [p2.x, p2.y, 0.15]
      ],
      0.38
    );

    // Golden raking-light catch on lower lash tips
    if (t < 0.45 && random() < 0.65) {
      brush.set("fine_hair", "#e89b42", 0.28);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // Long Tactile Supraorbital Vibrissae (sensory brow whiskers arcing into the raking light)
  let vibrissae = [
    { u0: -92, v0: -92, du1: -55, dv1: -58, du2: -105, dv2: -32 },
    { u0: -68, v0: -102, du1: -42, dv1: -72, du2: -88, dv2: -54 },
    { u0: -38, v0: -108, du1: -18, dv1: -82, du2: -52, dv2: -74 },
    { u0: -10, v0: -110, du1: 12, dv1: -78, du2: -8, dv2: -84 },
    { u0: 24, v0: -106, du1: 38, dv1: -68, du2: 32, dv2: -76 }
  ];

  for (let vb of vibrissae) {
    let p0 = fromEyeSpace(vb.u0, vb.v0);
    let p1 = fromEyeSpace(vb.u0 + vb.du1, vb.v0 + vb.dv1);
    let p2 = fromEyeSpace(vb.u0 + vb.du2, vb.v0 + vb.dv2);

    brush.set("fine_hair", "#260f08", 0.46);
    brush.spline(
      [
        [p0.x, p0.y, 1.1],
        [p1.x, p1.y, 0.65],
        [p2.x, p2.y, 0.15]
      ],
      0.45
    );

    brush.set("fine_hair", "#ffe59e", 0.30);
    brush.spline(
      [
        [p0.x, p0.y - 0.8, 0.5],
        [p1.x, p1.y - 0.8, 0.7],
        [p2.x, p2.y - 0.5, 0.2]
      ],
      0.45
    );
  }
}

// Hyperrealist Deconstructivist Windshield After Impact
// p5.js 2.x + p5.brush (WEBGL)

const W = 1200;
const H = 1200;

// Primary impact point and secondary shear node
