// ---------------------------------------------------------------------------
// 2D Convex Polygon & Line Clipping Utilities
// ---------------------------------------------------------------------------

function signedArea(poly) {
  let a = 0;
  for (let i = 0, n = poly.length; i < n; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % n];
    a += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return a * 0.5;
}

function ensureCWScreen(poly) {
  if (poly.length < 3) return poly;
  if (signedArea(poly) < 0) poly.reverse();
  return poly;
}

function polyCentroid(poly) {
  let cx = 0, cy = 0;
  for (let i = 0; i < poly.length; i++) {
    cx += poly[i][0];
    cy += poly[i][1];
  }
  return [cx / poly.length, cy / poly.length];
}

function clipToHalfPlane(poly, x1, y1, x2, y2, keepPositive = true) {
  if (poly.length < 3) return [];
  let out = [];
  let dx = x2 - x1;
  let dy = y2 - y1;
  let sign = keepPositive ? 1 : -1;

  for (let i = 0, n = poly.length; i < n; i++) {
    let A = poly[i];
    let B = poly[(i + 1) % n];
    let sA = sign * (dx * (A[1] - y1) - dy * (A[0] - x1));
    let sB = sign * (dx * (B[1] - y1) - dy * (B[0] - x1));

    if (sA >= -1e-5) out.push(A);
    if ((sA > 1e-5 && sB < -1e-5) || (sA < -1e-5 && sB > 1e-5)) {
      let t = sA / (sA - sB);
      out.push([A[0] + t * (B[0] - A[0]), A[1] + t * (B[1] - A[1])]);
    }
  }
  return out.length >= 3 ? ensureCWScreen(out) : [];
}

function clipPolyToConvexPoly(subjectPoly, clipPoly) {
  let out = subjectPoly.slice();
  for (let i = 0, n = clipPoly.length; i < n; i++) {
    if (out.length < 3) return [];
    let p1 = clipPoly[i];
    let p2 = clipPoly[(i + 1) % n];
    out = clipToHalfPlane(out, p1[0], p1[1], p2[0], p2[1], true);
  }
  return out;
}

function clipLineToConvexPoly(x1, y1, x2, y2, clipPoly) {
  let t0 = 0.0;
  let t1 = 1.0;
  let vx = x2 - x1;
  let vy = y2 - y1;

  for (let i = 0, n = clipPoly.length; i < n; i++) {
    let e1 = clipPoly[i];
    let e2 = clipPoly[(i + 1) % n];
    let ex = e2[0] - e1[0];
    let ey = e2[1] - e1[1];
    // Interior is ex * (py - e1y) - ey * (px - e1x) >= 0
    let num = ex * (y1 - e1[1]) - ey * (x1 - e1[0]);
    let den = ex * vy - ey * vx;

    if (Math.abs(den) < 1e-9) {
      if (num < 0) return null;
    } else {
      let t = -num / den;
      if (den > 0) {
        if (t > t0) t0 = t;
      } else {
        if (t < t1) t1 = t;
      }
      if (t0 > t1) return null;
    }
  }
  if (t0 > t1 || t1 - t0 < 1e-4) return null;
  return [
    x1 + t0 * vx,
    y1 + t0 * vy,
    x1 + t1 * vx,
    y1 + t1 * vy
  ];
}

function transformPt(x, y, cx, cy, shiftX, shiftY, cosA, sinA, sc) {
  let dx = (x - cx) * sc;
  let dy = (y - cy) * sc;
  return [
    cx + shiftX + dx * cosA - dy * sinA,
    cy + shiftY + dx * sinA + dy * cosA
  ];
}

function drawBrushPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ---------------------------------------------------------------------------
// World Scene Geometry (Overpass Girders, Trusses, Wires, Dashboard, Sky)
// ---------------------------------------------------------------------------

let worldPolys = [];
let worldLines = [];

function buildWorldScene() {
  // 1. Massive Deconstructivist Overpass Steel Plate Girder #1 (Upper-left to lower-right)
  addSteelGirder(-250, 90, 1450, 820, 115, 22, true);

  // 2. Crossing Viaduct Concrete & Steel Box Beam #2 (Lower-left to upper-right)
  addSteelGirder(-180, 680, 1380, 120, 92, 18, false);

  // 3. Secondary High Overpass Soffit & Truss (Top-center to right edge)
  addTrussSpan(120, -140, 1360, 540, 84, 14);

  // 4. Vertical/Cantilevered Highway Pier & Luminaire Mast
  addSteelGirder(910, -150, 740, 1350, 56, 12, false);

  // 5. Overhead Catenary / High-Tension Power Cables
  let wireOffsets = [-45, -18, 12, 42, 78];
  for (let w = 0; w < wireOffsets.length; w++) {
    let off = wireOffsets[w];
    let segs = 14;
    for (let s = 0; s < segs; s++) {
      let t1 = s / segs;
      let t2 = (s + 1) / segs;
      let x1 = -150 + t1 * 1500;
      let x2 = -150 + t2 * 1500;
      let sag1 = Math.sin(t1 * Math.PI) * 95;
      let sag2 = Math.sin(t2 * Math.PI) * 95;
      let y1 = 180 + off + t1 * 290 + sag1;
      let y2 = 180 + off + t2 * 290 + sag2;
      worldLines.push({
        x1, y1, x2, y2,
        type: "wire",
        weight: w % 2 === 0 ? 0.42 : 0.28
      });
    }
  }

  // 6. Driver's Dashboard, Defroster Vents, Instrument Cowl & Wiper Truss (lower region)
  addDashboardReflections();

  // 7. Horizon Cloud Strata & Perspective Grid Lines
  for (let i = 0; i < 18; i++) {
    let y = -60 + i * 75;
    worldLines.push({
      x1: -200, y1: y,
      x2: 1400, y2: y + (i % 3 - 1) * 90,
      type: "construction",
      weight: 0.22
    });
  }
}

function addSteelGirder(x1, y1, x2, y2, depth, flangeH, withRivets) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  let ux = dx / len;
  let uy = dy / len;
  let nx = -uy;
  let ny = ux;

  // Main web polygon
  let webPoly = ensureCWScreen([
    [x1, y1],
    [x2, y2],
    [x2 + nx * depth, y2 + ny * depth],
    [x1 + nx * depth, y1 + ny * depth]
  ]);
  worldPolys.push({ poly: webPoly, kind: "girder_web", ux, uy, nx, ny });

  // Top & Bottom Flanges
  let topFlange = ensureCWScreen([
    [x1 - nx * flangeH, y1 - ny * flangeH],
    [x2 - nx * flangeH, y2 - ny * flangeH],
    [x2 + nx * (flangeH * 0.6), y2 + ny * (flangeH * 0.6)],
    [x1 + nx * (flangeH * 0.6), y1 + ny * (flangeH * 0.6)]
  ]);
  worldPolys.push({ poly: topFlange, kind: "girder_flange", ux, uy, nx, ny });

  let botFlange = ensureCWScreen([
    [x1 + nx * (depth - flangeH * 0.5), y1 + ny * (depth - flangeH * 0.5)],
    [x2 + nx * (depth - flangeH * 0.5), y2 + ny * (depth - flangeH * 0.5)],
    [x2 + nx * (depth + flangeH), y2 + ny * (depth + flangeH)],
    [x1 + nx * (depth + flangeH), y1 + ny * (depth + flangeH)]
  ]);
  worldPolys.push({ poly: botFlange, kind: "girder_flange", ux, uy, nx, ny });

  // Longitudinal flange & web ruling lines
  let offsets = [-flangeH, 0, flangeH * 0.6, depth * 0.35, depth * 0.7, depth - flangeH * 0.5, depth, depth + flangeH];
  for (let k = 0; k < offsets.length; k++) {
    let d = offsets[k];
    let isOuter = (k === 0 || k === offsets.length - 1 || k === 1 || k === offsets.length - 2);
    worldLines.push({
      x1: x1 + nx * d, y1: y1 + ny * d,
      x2: x2 + nx * d, y2: y2 + ny * d,
      type: isOuter ? "girder_edge" : "girder_seam",
      weight: isOuter ? 0.52 : 0.28
    });
  }

  // Transverse stiffener plates & cross-bracing
  let numBays = Math.floor(len / 95);
  for (let b = 0; b <= numBays; b++) {
    let dist = b * 95;
    let bx = x1 + ux * dist;
    let by = y1 + uy * dist;
    // Stiffener rib
    worldLines.push({
      x1: bx - nx * flangeH, y1: by - ny * flangeH,
      x2: bx + nx * (depth + flangeH), y2: by + ny * (depth + flangeH),
      type: "girder_edge",
      weight: 0.44
    });
    worldLines.push({
      x1: bx + ux * 6 - nx * flangeH, y1: by + uy * 6 - ny * flangeH,
      x2: bx + ux * 6 + nx * (depth + flangeH), y2: by + uy * 6 + ny * (depth + flangeH),
      type: "girder_seam",
      weight: 0.26
    });

    // Diagonal truss X-bracing inside bay
    if (b < numBays) {
      let nbx = x1 + ux * (dist + 95);
      let nby = y1 + uy * (dist + 95);
      worldLines.push({
        x1: bx, y1: by,
        x2: nbx + nx * depth, y2: nby + ny * depth,
        type: "girder_seam",
        weight: 0.32
      });
      if (withRivets && b % 2 === 0) {
        worldLines.push({
          x1: bx + nx * depth, y1: by + ny * depth,
          x2: nbx, y2: nby,
          type: "girder_seam",
          weight: 0.28
        });
      }
    }

    // Rivet tick marks along top and bottom flanges
    if (withRivets && b < numBays) {
      for (let r = 1; r <= 5; r++) {
        let rx = bx + ux * (r * 16);
        let ry = by + uy * (r * 16);
        worldLines.push({
          x1: rx - nx * (flangeH * 0.4), y1: ry - ny * (flangeH * 0.4),
          x2: rx + nx * (flangeH * 0.2), y2: ry + ny * (flangeH * 0.2),
          type: "rivet",
          weight: 0.45
        });
        worldLines.push({
          x1: rx + nx * (depth + flangeH * 0.2), y1: ry + ny * (depth + flangeH * 0.2),
          x2: rx + nx * (depth + flangeH * 0.7), y2: ry + ny * (depth + flangeH * 0.7),
          type: "rivet",
          weight: 0.45
        });
      }
    }
  }
}

function addTrussSpan(x1, y1, x2, y2, depth, chordW) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  let ux = dx / len;
  let uy = dy / len;
  let nx = -uy;
  let ny = ux;

  // Chords
  for (let d of [0, chordW, depth, depth + chordW]) {
    worldLines.push({
      x1: x1 + nx * d, y1: y1 + ny * d,
      x2: x2 + nx * d, y2: y2 + ny * d,
      type: "girder_edge",
      weight: 0.4
    });
  }

  // Warren truss zig-zags
  let step = 72;
  let nSteps = Math.floor(len / step);
  for (let i = 0; i < nSteps; i++) {
    let ax = x1 + ux * (i * step);
    let ay = y1 + uy * (i * step);
    let bx = x1 + ux * ((i + 0.5) * step) + nx * depth;
    let by = y1 + uy * ((i + 0.5) * step) + ny * depth;
    let cx = x1 + ux * ((i + 1) * step);
    let cy = y1 + uy * ((i + 1) * step);

    worldLines.push({ x1: ax, y1: ay, x2: bx, y2: by, type: "girder_edge", weight: 0.36 });
    worldLines.push({ x1: bx, y1: by, x2: cx, y2: cy, type: "girder_edge", weight: 0.36 });
    // Parallel thickness member
    worldLines.push({
      x1: ax + ux * 7, y1: ay + uy * 7,
      x2: bx + ux * 7, y2: by + uy * 7,
      type: "girder_seam", weight: 0.24
    });
  }
}

function addDashboardReflections() {
  // Dashboard defroster louver grilles (bottom center-left and right)
  for (let bank = 0; bank < 2; bank++) {
    let startX = bank === 0 ? 120 : 620;
    let startY = bank === 0 ? 920 : 880;
    let tilt = bank === 0 ? -0.18 : 0.14;
    for (let i = 0; i < 24; i++) {
      let lx = startX + i * 16;
      let ly = startY + i * 16 * tilt;
      worldLines.push({
        x1: lx, y1: ly,
        x2: lx - 28, y2: ly + 68,
        type: "dash_louver",
        weight: 0.42
      });
      worldLines.push({
        x1: lx + 4, y1: ly + 1,
        x2: lx - 24, y2: ly + 69,
        type: "girder_seam",
        weight: 0.24
      });
    }
    // Outer bezel frame of defroster vent
    let endX = startX + 23 * 16;
    let endY = startY + 23 * 16 * tilt;
    worldLines.push({ x1: startX, y1: startY, x2: endX, y2: endY, type: "girder_edge", weight: 0.5 });
    worldLines.push({ x1: startX - 28, y1: startY + 68, x2: endX - 28, y2: endY + 68, type: "girder_edge", weight: 0.5 });
  }

  // Instrument cluster binnacle hood & speedometer radial ticks (lower left-center)
  let cx = 370, cy = 1040, rad = 210;
  let arcSteps = 28;
  for (let i = 0; i < arcSteps; i++) {
    let a1 = Math.PI * (1.08 + (i / arcSteps) * 0.84);
    let a2 = Math.PI * (1.08 + ((i + 1) / arcSteps) * 0.84);
    worldLines.push({
      x1: cx + Math.cos(a1) * rad, y1: cy + Math.sin(a1) * rad,
      x2: cx + Math.cos(a2) * rad, y2: cy + Math.sin(a2) * rad,
      type: "girder_edge",
      weight: 0.55
    });
    worldLines.push({
      x1: cx + Math.cos(a1) * (rad - 14), y1: cy + Math.sin(a1) * (rad - 14),
      x2: cx + Math.cos(a2) * (rad - 14), y2: cy + Math.sin(a2) * (rad - 14),
      type: "girder_seam",
      weight: 0.3
    });
    // Gauge dial ticks
    if (i % 2 === 0) {
      let tickLen = (i % 4 === 0) ? 26 : 14;
      worldLines.push({
        x1: cx + Math.cos(a1) * (rad - 20), y1: cy + Math.sin(a1) * (rad - 20),
        x2: cx + Math.cos(a1) * (rad - 20 - tickLen), y2: cy + Math.sin(a1) * (rad - 20 - tickLen),
        type: "dash_louver",
        weight: (i % 4 === 0) ? 0.48 : 0.28
      });
    }
  }

  // Windshield wiper blade & articulated pantograph arm sweeping across lower middle
  addTrussSpan(60, 1080, 980, 790, 26, 5);
}

// ---------------------------------------------------------------------------
// Spiderweb & Deconstructivist Shard Mesh Generation
// ---------------------------------------------------------------------------

function generateShards() {
  let canvasPoly = ensureCWScreen([[0, 0], [W, 0], [W, H], [0, H]]);
  let basePolys = [];

  // 1. Generate radial rays from IMPACT
  const NUM_RAYS = 32;
  const RING_RADII = [0, 18, 34, 54, 80, 112, 152, 202, 265, 345, 445, 575, 735, 930, 1200, 1550];
  const NUM_RINGS = RING_RADII.length - 1;

  // Base angles with irregular spacing for tension
  let baseAngles = [];
  let accum = 0;
  for (let i = 0; i < NUM_RAYS; i++) {
    accum += 0.6 + random(0.85);
    baseAngles.push(accum);
  }
  let totalAccum = baseAngles[NUM_RAYS - 1];
  for (let i = 0; i < NUM_RAYS; i++) {
    baseAngles[i] = (baseAngles[i] / totalAccum) * Math.PI * 2;
  }

  // Build vertex grid [ray][ring] with slight angular kink per ring
  let grid = [];
  for (let i = 0; i < NUM_RAYS; i++) {
    let rayPts = [];
    let curAngle = baseAngles[i];
    for (let j = 0; j <= NUM_RINGS; j++) {
      let r = RING_RADII[j];
      if (j === 0) {
        rayPts.push([IMPACT.x, IMPACT.y]);
      } else {
        // Slight angular deflection as crack propagates outward
        curAngle += random(-0.022, 0.022);
        // Step radius variation per sector/ring
        let rVar = r * (1 + random(-0.08, 0.08));
        rayPts.push([
          IMPACT.x + Math.cos(curAngle) * rVar,
          IMPACT.y + Math.sin(curAngle) * rVar
        ]);
      }
    }
    grid.push(rayPts);
  }

  // Extract cells from radial grid
  for (let i = 0; i < NUM_RAYS; i++) {
    let ni = (i + 1) % NUM_RAYS;
    for (let j = 0; j < NUM_RINGS; j++) {
      if (j === 0) {
        let tri = ensureCWScreen([
          grid[i][0],
          grid[i][1],
          grid[ni][1]
        ]);
        let clipped = clipPolyToConvexPoly(tri, canvasPoly);
        if (clipped.length >= 3) basePolys.push({ poly: clipped, ring: j, sector: i });
      } else {
        let A = grid[i][j];
        let B = grid[i][j + 1];
        let C = grid[ni][j + 1];
        let D = grid[ni][j];

        // Split some quads diagonally into sharp splinters, keep others as convex quads
        let splitMode = random();
        if (splitMode < 0.38 || j >= NUM_RINGS - 3) {
          // Split into two triangles
          let diag = random() < 0.5;
          let t1 = ensureCWScreen(diag ? [A, B, C] : [A, B, D]);
          let t2 = ensureCWScreen(diag ? [A, C, D] : [B, C, D]);
          let c1 = clipPolyToConvexPoly(t1, canvasPoly);
          let c2 = clipPolyToConvexPoly(t2, canvasPoly);
          if (c1.length >= 3) basePolys.push({ poly: c1, ring: j, sector: i });
          if (c2.length >= 3) basePolys.push({ poly: c2, ring: j, sector: i });
        } else {
          // Ensure convexity by testing both diagonals
          let quad = ensureCWScreen([A, B, C, D]);
          let cQuad = clipPolyToConvexPoly(quad, canvasPoly);
          if (cQuad.length >= 3) basePolys.push({ poly: cQuad, ring: j, sector: i });
        }
      }
    }
  }

  // 2. Slice the mesh with long edge-to-edge deconstructivist fault lines running off every edge
  const FAULT_LINES = [
    [0, 195, W, 885],                        // Long primary shear through impact zone
    [160, 0, 960, H],                        // Steep diagonal from top-left to bottom-right
    [0, 740, W, 240],                        // Counter-diagonal running off left & right edges
    [540, 0, 110, H],                        // Steep slash cutting left half
    [0, 1080, 1090, 0],                      // Full-canvas diagonal slash
    [790, 0, W, 940],                        // Right-side tension fault
    [0, 460, W, 680],                        // Horizontal-ish shear through impact
    [320, H, W, 390]                         // Secondary shear through lower-right node
  ];

  let currentPolys = basePolys;
  for (let f = 0; f < FAULT_LINES.length; f++) {
    let [fx1, fy1, fx2, fy2] = FAULT_LINES[f];
    let nextPolys = [];
    for (let k = 0; k < currentPolys.length; k++) {
      let item = currentPolys[k];
      // Keep tiny core shards intact near impact center for spiderweb density
      if (item.ring <= 2 && f > 1) {
        nextPolys.push(item);
        continue;
      }
      let pPos = clipToHalfPlane(item.poly, fx1, fy1, fx2, fy2, true);
      let pNeg = clipToHalfPlane(item.poly, fx1, fy1, fx2, fy2, false);
      if (pPos.length >= 3 && Math.abs(signedArea(pPos)) > 25) {
        nextPolys.push({ poly: pPos, ring: item.ring, sector: item.sector });
      }
      if (pNeg.length >= 3 && Math.abs(signedArea(pNeg)) > 25) {
        nextPolys.push({ poly: pNeg, ring: item.ring, sector: item.sector });
      }
    }
    currentPolys = nextPolys;
  }

  // 3. Assign visual & perspective properties to each shard
  let shards = [];
  for (let i = 0; i < currentPolys.length; i++) {
    let poly = currentPolys[i].poly;
    let area = Math.abs(signedArea(poly));
    if (area < 18) continue;

    let [cx, cy] = polyCentroid(poly);
    let distImpact = Math.hypot(cx - IMPACT.x, cy - IMPACT.y);
    let distShear = Math.hypot(cx - SHEAR_NODE.x, cy - SHEAR_NODE.y);
    let angleFromImpact = Math.atan2(cy - IMPACT.y, cx - IMPACT.x);

    // Determine surface fill category
    let style = "raw";
    let fillCol = null;
    let fillOpacity = 0;
    let isMilky = false;

    if (distImpact < 72 || (distImpact < 145 && random() < 0.42) || (distShear < 68 && random() < 0.45)) {
      style = "milky";
      isMilky = true;
      fillCol = random() < 0.65 ? PALETTE.milkyWhite : PALETTE.milkyIce;
      fillOpacity = random(165, 235);
    } else {
      let rVal = random();
      // Bias upper-right & upper-left shards slightly toward cerulean sky, lower/mid toward sodium & raw paper
      let skyBias = cy < 620 ? 0.12 : -0.05;
      if (rVal < 0.34) {
        style = "raw";
      } else if (rVal < 0.61 + skyBias) {
        style = "cerulean";
        let pick = random();
        fillCol = pick < 0.33 ? PALETTE.ceruleanDeep : (pick < 0.72 ? PALETTE.ceruleanMid : PALETTE.ceruleanPale);
        fillOpacity = random(55, 115);
      } else if (rVal < 0.82) {
        style = "sodium";
        let pick = random();
        fillCol = pick < 0.3 ? PALETTE.sodiumDeep : (pick < 0.7 ? PALETTE.sodiumMid : PALETTE.sodiumPale);
        fillOpacity = random(60, 120);
      } else {
        style = "pastel";
        let pick = random();
        fillCol = pick < 0.36 ? PALETTE.pastelRose : (pick < 0.7 ? PALETTE.pastelCeladon : PALETTE.pastelLavender);
        fillOpacity = random(50, 95);
      }
    }

    // Perspective disagreement transform: each shard tilts and shifts the world reflections
    let tiltMag = map(constrain(distImpact, 20, 900), 20, 900, 0.48, 0.18);
    let dRot = random(-tiltMag, tiltMag) + (currentPolys[i].sector % 3 - 1) * 0.11;
    let shiftSpread = map(constrain(distImpact, 20, 900), 20, 900, 95, 38);
    let shiftX = random(-shiftSpread, shiftSpread);
    let shiftY = random(-shiftSpread, shiftSpread);
    let sc = random(0.78, 1.28);

    shards.push({
      poly,
      area,
      cx,
      cy,
      distImpact,
      distShear,
      angleFromImpact,
      ring: currentPolys[i].ring,
      sector: currentPolys[i].sector,
      style,
      fillCol,
      fillOpacity,
      isMilky,
      dRot,
      cosA: Math.cos(dRot),
      sinA: Math.sin(dRot),
      shiftX,
      shiftY,
      sc
    });
  }

  return { shards, faultLines: FAULT_LINES };
}

// ---------------------------------------------------------------------------
// Foreground Air-Freshener Tree (Crisp Hyperreal Illustration)
// ---------------------------------------------------------------------------

function drawCrispAirFreshener() {
  // Hangs in the upper-right foreground from rear-view mirror cord
  const anchorX = 838;
  const anchorY = -10;
  const holeX = 846;
  const holeY = 196;
  const tiltDeg = -3.2;

  push();
  // 1. Elastic hanging string from top edge to tree apex hole
  brush.noFill();
  brush.noHatch();
  // Subtle dark edge of cord
  brush.set("rotring", "#2A3038", 0.38);
  brush.line(anchorX - 1.2, anchorY, holeX - 0.8, holeY);
  brush.line(anchorX + 1.2, anchorY, holeX + 0.8, holeY);
  // Crisp white cord core
  brush.set("cpencil", "#FFFFFF", 0.65);
  brush.line(anchorX, anchorY, holeX, holeY);

  // Translate to tree apex and rotate slightly
  translate(holeX, holeY);
  rotate(tiltDeg);

  // Define classic stepped pine tree geometry (local coords relative to hole at (0, 0))
  // Total height ~ 162px, max width ~ 96px
  const treeRight = [
    [0, -10],
    [6, -7],
    [28, 28],
    [13, 28],
    [39, 68],
    [20, 68],
    [48, 112],
    [27, 112],
    [34, 134],
    [13, 134],
    [13, 152],
    [0, 152]
  ];

  let treePoly = [];
  for (let i = 0; i < treeRight.length; i++) {
    treePoly.push([treeRight[i][0], treeRight[i][1]]);
  }
  for (let i = treeRight.length - 2; i >= 1; i--) {
    treePoly.push([-treeRight[i][0], treeRight[i][1]]);
  }
  treePoly = ensureCWScreen(treePoly);

  // 2. Cardboard 3D bevel edge (left/bottom thickness offset by (-3.2, 2.2))
  let bevelPoly = treePoly.map(p => [p[0] - 3.2, p[1] + 2.2]);
  brush.noStroke();
  brush.wash("#D5CFC1", 245);
  drawBrushPoly(bevelPoly, 0);

  // 3. Opaque cardboard base coat so background cracks are completely blocked
  brush.wash("#F5F2E9", 255);
  drawBrushPoly(treePoly, 0);

  // 4. Soft pastel pine-green body wash + subtle vertical gradient hatching
  brush.wash("#8AB399", 215);
  drawBrushPoly(treePoly, 0);

  // Inner inset border (classic white/cream die-cut margin)
  let innerScale = 0.88;
  let innerPoly = treePoly.map(p => [p[0] * innerScale, (p[1] - 72) * innerScale + 72]);
  brush.wash("#6E997F", 190);
  drawBrushPoly(innerPoly, 0);

  // Fine cardboard grain & hyperreal tonal shading across the tree face
  brush.hatchStyle("2H", "#4E755E", 0.26);
  brush.hatch(3.5, 25, { rand: 0.02 });
  drawBrushPoly(innerPoly, 0);
  brush.noHatch();

  // Light pastel mint highlight on upper-left foliage planes
  let highlightPoly = ensureCWScreen([
    [0, -4],
    [22, 26],
    [9, 26],
    [32, 64],
    [-32, 64],
    [-9, 26],
    [-22, 26]
  ]);
  brush.wash("#A6CBB3", 125);
  drawBrushPoly(highlightPoly, 0);

  // 5. Crisp cream & coral-pastel graphic banner across the lower middle tier
  let bannerPoly = ensureCWScreen([
    [-31, 78],
    [31, 78],
    [39, 98],
    [-39, 98]
  ]);
  brush.wash("#FAF6EC", 250);
  drawBrushPoly(bannerPoly, 0);

  // Thin pastel sodium-gold & rose trim lines on banner
  brush.set("rotring", "#D47A6A", 0.35);
  brush.line(-30, 81, 30, 81);
  brush.line(-37, 95, 37, 95);

  // Tiny crisp ruled lettering simulation inside banner ("ROYAL PINE")
  brush.set("rotring", "#1E242B", 0.36);
  const letterX = [-22, -15, -8, -1, 6, 14, 20];
  for (let lx of letterX) {
    brush.line(lx, 85, lx, 91);
    brush.line(lx, 85, lx + 3.5, 85);
    brush.line(lx, 88, lx + 3, 88);
  }

  // Trunk base graphic detail
  let trunkPoly = ensureCWScreen([
    [-11, 134],
    [11, 134],
    [11, 150],
    [-11, 150]
  ]);
  brush.wash("#D8B88A", 210);
  drawBrushPoly(trunkPoly, 0);

  // 6. Razor-sharp Rotring ink outlines of cardboard bevel and front silhouette
  brush.noFill();
  brush.noWash();
  brush.set("rotring", "#5A554C", 0.32);
  for (let i = 0; i < bevelPoly.length; i++) {
    let p1 = bevelPoly[i];
    let p2 = bevelPoly[(i + 1) % bevelPoly.length];
    if (p1[0] <= 2 && p2[0] <= 2) {
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // White inner border line
  brush.set("cpencil", "#FAF8F2", 0.45);
  for (let i = 0; i < innerPoly.length; i++) {
    let p1 = innerPoly[i];
    let p2 = innerPoly[(i + 1) % innerPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Outer crisp ink contour of the air-freshener tree
  brush.set("rotring", PALETTE.inkDark, 0.52);
  for (let i = 0; i < treePoly.length; i++) {
    let p1 = treePoly[i];
    let p2 = treePoly[(i + 1) % treePoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Banner crisp border
  brush.set("rotring", PALETTE.inkDark, 0.34);
  for (let i = 0; i < bannerPoly.length; i++) {
    let p1 = bannerPoly[i];
    let p2 = bannerPoly[(i + 1) % bannerPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 7. Die-cut punch hole at apex & string loop knot
  brush.noStroke();
  brush.wash("#8EBBD9", 230);
  brush.circle(0, 3, 3.8, 0.05);
  brush.set("rotring", PALETTE.inkDark, 0.4);
  brush.circle(0, 3, 3.8, 0.05);

  // String loop passing through hole
  brush.set("cpencil", "#FFFFFF", 0.65);
  brush.line(-1, -10, -0.5, 3);
  brush.line(1, -10, 0.5, 3);
  brush.set("rotring", "#2A3038", 0.3);
  brush.line(-1.8, -10, -1.2, 3);
  brush.line(1.8, -10, 1.2, 3);

  pop();
}

// ---------------------------------------------------------------------------
// Main Setup & Draw
// ---------------------------------------------------------------------------

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paper);
  brush.noField();

  // Build world scene & fractured windshield mesh
  buildWorldScene();
  const { shards, faultLines } = generateShards();

  // -------------------------------------------------------------------------
  // PASS 1: Batched Watercolor Fills & Opaque Laminate Washes
  // -------------------------------------------------------------------------
  const colorBatches = {};
  const milkyShards = [];

  for (let i = 0; i < shards.length; i++) {
    let s = shards[i];
    if (s.style === "raw") continue;
    if (s.isMilky) {
      milkyShards.push(s);
      continue;
    }
    if (!colorBatches[s.fillCol]) colorBatches[s.fillCol] = [];
    colorBatches[s.fillCol].push(s);
  }

  // Render watercolor fills grouped by color for optimal caching
  brush.noStroke();
  const colorKeys = Object.keys(colorBatches);
  for (let c = 0; c < colorKeys.length; c++) {
    let col = colorKeys[c];
    let group = colorBatches[col];

    for (let i = 0; i < group.length; i++) {
      let s = group[i];
      // Use full watercolor bleed on medium/large planes, fast wash on tiny splinters
      if (s.area > 1650 && i % 2 === 0) {
        brush.noWash();
        brush.fillBleed(0.14, "out");
        brush.fillTexture(0.42, 0.32);
        brush.fill(col, s.fillOpacity);
        drawBrushPoly(s.poly, 0);
        brush.noFill();
      } else {
        brush.noFill();
        brush.wash(col, s.fillOpacity * 0.85);
        drawBrushPoly(s.poly, 0);
        brush.noWash();
      }
    }
  }

  // Render milky PVB laminate refraction shards near impact point
  brush.noFill();
  for (let i = 0; i < milkyShards.length; i++) {
    let s = milkyShards[i];
    brush.wash(s.fillCol, s.fillOpacity);
    drawBrushPoly(s.poly, 0);
  }
  brush.noWash();

  // -------------------------------------------------------------------------
  // PASS 2: Displaced Architectural Reflections Inside Each Shard
  // -------------------------------------------------------------------------
  // 2A. Clipped Girder Web & Flange Tonal Hatching per Shard
  for (let i = 0; i < shards.length; i++) {
    let s = shards[i];
    if (s.area < 85) continue;

    // Subtle sky/atmosphere graphite hatching in some shards
    if (s.style !== "raw" && s.area > 900 && (i % 3 === 0)) {
      let hatchAngle = (s.dRot * 180 / Math.PI) + (s.sector * 19);
      let hatchSpacing = map(constrain(s.distImpact, 50, 800), 50, 800, 5.5, 11);
      brush.hatchStyle("2H", PALETTE.graphite2H, 0.25);
      brush.hatch(hatchSpacing, hatchAngle, { rand: 0.03 });
      brush.noStroke();
      drawBrushPoly(s.poly, 0);
      brush.noHatch();
    }

    // Transform world girder polygons into this shard's tilted perspective
    for (let wp = 0; wp < worldPolys.length; wp++) {
      let item = worldPolys[wp];
      let tPoly = [];
      for (let v = 0; v < item.poly.length; v++) {
        tPoly.push(transformPt(
          item.poly[v][0], item.poly[v][1],
          s.cx, s.cy, s.shiftX, s.shiftY, s.cosA, s.sinA, s.sc
        ));
      }
      tPoly = ensureCWScreen(tPoly);
      let clipped = clipPolyToConvexPoly(tPoly, s.poly);
      if (clipped.length >= 3 && Math.abs(signedArea(clipped)) > 35) {
        let baseAngle = Math.atan2(item.uy, item.ux) * (180 / Math.PI) + (s.dRot * 180 / Math.PI);
        if (item.kind === "girder_flange") {
          // Dense dark graphite cross-hatching on steel flanges
          brush.noStroke();
          brush.wash("#D9DDE2", 75);
          drawBrushPoly(clipped, 0);
          brush.noWash();

          brush.hatchStyle("HB", PALETTE.graphite2B, 0.32);
          brush.hatch(4.2, baseAngle + 90, { rand: 0.02 });
          drawBrushPoly(clipped, 0);
          brush.noHatch();
        } else {
          // Lighter longitudinal graphite shading on steel girder web
          brush.hatchStyle("2H", PALETTE.graphiteHB, 0.26);
          brush.hatch(6.5, baseAngle + 35, { rand: 0.03 });
          brush.noStroke();
          drawBrushPoly(clipped, 0);
          brush.noHatch();
        }
      }
    }
  }

  // 2B. Clipped World Lines (Girder Edges, Rivets, Wires, Louvers, Construction)
  // Collect clipped segments by brush style so we minimize brush.set() state switches
  const segBuckets = {
    girder_edge: [],
    girder_seam: [],
    rivet: [],
    wire: [],
    dash_louver: [],
    construction: []
  };

  for (let i = 0; i < shards.length; i++) {
    let s = shards[i];
    if (s.area < 30) continue;

    for (let wl = 0; wl < worldLines.length; wl++) {
      let ln = worldLines[wl];
      let p1 = transformPt(ln.x1, ln.y1, s.cx, s.cy, s.shiftX, s.shiftY, s.cosA, s.sinA, s.sc);
      let p2 = transformPt(ln.x2, ln.y2, s.cx, s.cy, s.shiftX, s.shiftY, s.cosA, s.sinA, s.sc);
      let cSeg = clipLineToConvexPoly(p1[0], p1[1], p2[0], p2[1], s.poly);
      if (cSeg) {
        segBuckets[ln.type].push(cSeg);
      }
    }
  }

  // Draw deconstructivist perspective construction lines (extending slightly past shards)
  brush.set("2H", PALETTE.graphite2H, 0.24);
  for (let i = 0; i < segBuckets.construction.length; i++) {
    let [x1, y1, x2, y2] = segBuckets.construction[i];
    // Extend ghosted projection lines slightly beyond shard edge on raw paper
    let dx = x2 - x1, dy = y2 - y1;
    let ext = (i % 4 === 0) ? 0.18 : 0.0;
    brush.line(x1 - dx * ext, y1 - dy * ext, x2 + dx * ext, y2 + dy * ext);
  }

  // Draw girder seams & internal web lines in sharp HB graphite
  brush.set("HB", PALETTE.graphiteHB, 0.3);
  for (let i = 0; i < segBuckets.girder_seam.length; i++) {
    let [x1, y1, x2, y2] = segBuckets.girder_seam[i];
    brush.line(x1, y1, x2, y2);
  }

  // Draw main steel girder edges in crisp 2B graphite + rotring
  brush.set("rotring", PALETTE.graphite2B, 0.42);
  for (let i = 0; i < segBuckets.girder_edge.length; i++) {
    let [x1, y1, x2, y2] = segBuckets.girder_edge[i];
    brush.line(x1, y1, x2, y2);
  }

  // Draw rivets & bolt heads
  brush.set("rotring", PALETTE.inkDark, 0.48);
  for (let i = 0; i < segBuckets.rivet.length; i++) {
    let [x1, y1, x2, y2] = segBuckets.rivet[i];
    brush.line(x1, y1, x2, y2);
  }

  // Draw overhead wires & catenary cables
  brush.set("rotring", "#2A313A", 0.34);
  for (let i = 0; i < segBuckets.wire.length; i++) {
    let [x1, y1, x2, y2] = segBuckets.wire[i];
    brush.line(x1, y1, x2, y2);
  }

  // Draw dashboard louvers & speedometer ticks
  brush.set("2B", "#2D343E", 0.4);
  for (let i = 0; i < segBuckets.dash_louver.length; i++) {
    let [x1, y1, x2, y2] = segBuckets.dash_louver[i];
    brush.line(x1, y1, x2, y2);
  }

  // -------------------------------------------------------------------------
  // PASS 3: Laminated Glass Double-Edge Refraction & Ruled Ink Shard Cracks
  // -------------------------------------------------------------------------
  // Deduplicate shard edges so each crack is drawn cleanly with controlled thickness
  const edgeMap = new Map();
  function quantKey(x1, y1, x2, y2) {
    let ax = Math.round(x1 * 2), ay = Math.round(y1 * 2);
    let bx = Math.round(x2 * 2), by = Math.round(y2 * 2);
    return (ax < bx || (ax === bx && ay < by))
      ? `${ax},${ay}_${bx},${by}`
      : `${bx},${by}_${ax},${ay}`;
  }

  for (let i = 0; i < shards.length; i++) {
    let s = shards[i];
    let n = s.poly.length;
    for (let j = 0; j < n; j++) {
      let p1 = s.poly[j];
      let p2 = s.poly[(j + 1) % n];
      // Skip outer canvas border edges
      if ((p1[0] <= 1 && p2[0] <= 1) || (p1[0] >= W - 1 && p2[0] >= W - 1) ||
          (p1[1] <= 1 && p2[1] <= 1) || (p1[1] >= H - 1 && p2[1] >= H - 1)) {
        continue;
      }
      let k = quantKey(p1[0], p1[1], p2[0], p2[1]);
      if (!edgeMap.has(k)) {
        let mx = (p1[0] + p2[0]) * 0.5;
        let my = (p1[1] + p2[1]) * 0.5;
        let dImp = Math.hypot(mx - IMPACT.x, my - IMPACT.y);
        edgeMap.set(k, { x1: p1[0], y1: p1[1], x2: p2[0], y2: p2[1], dImp });
      }
    }
  }

  const uniqueEdges = Array.from(edgeMap.values());

  // 3A. Secondary glass thickness edge (offset refraction in laminated safety glass)
  brush.set("2H", PALETTE.refractEdge, 0.32);
  for (let i = 0; i < uniqueEdges.length; i++) {
    let e = uniqueEdges[i];
    // Offset vector perpendicular to impact center
    let offX = e.x1 > IMPACT.x ? 2.8 : -2.8;
    let offY = e.y1 > IMPACT.y ? 2.6 : -2.6;
    brush.line(e.x1 + offX, e.y1 + offY, e.x2 + offX, e.y2 + offY);

    // Short transverse thickness ticks at crack vertices (glass edge facets)
    if (i % 4 === 0 && e.dImp < 580) {
      brush.line(e.x1, e.y1, e.x1 + offX, e.y1 + offY);
    }
  }

  // 3B. Milky white internal reflection highlights along cracks
  brush.set("cpencil", "#FFFFFF", 0.52);
  for (let i = 0; i < uniqueEdges.length; i++) {
    let e = uniqueEdges[i];
    if (e.dImp < 260 || i % 2 === 0) {
      brush.line(e.x1 + 1.2, e.y1 + 1.2, e.x2 + 1.2, e.y2 + 1.2);
    }
  }

  // 3C. Crisp ruled Rotring ink shard edges
  brush.set("rotring", PALETTE.inkDark, 0.36);
  for (let i = 0; i < uniqueEdges.length; i++) {
    let e = uniqueEdges[i];
    if (e.dImp >= 190) {
      brush.line(e.x1, e.y1, e.x2, e.y2);
    }
  }

  // Heavier ink emphasis near the impact spiderweb & stress ridges
  brush.set("rotring", PALETTE.inkDark, 0.55);
  for (let i = 0; i < uniqueEdges.length; i++) {
    let e = uniqueEdges[i];
    if (e.dImp < 190) {
      brush.line(e.x1, e.y1, e.x2, e.y2);
    }
  }

  // 3D. Long edge-to-edge deconstructivist fault lines running off every edge
  brush.set("rotring", PALETTE.inkDark, 0.68);
  for (let f = 0; f < faultLines.length; f++) {
    let [fx1, fy1, fx2, fy2] = faultLines[f];
    brush.line(fx1, fy1, fx2, fy2);
  }
  // Bright white specular bevel alongside every primary fault line
  brush.set("cpencil", "#FFFFFF", 0.75);
  for (let f = 0; f < faultLines.length; f++) {
    let [fx1, fy1, fx2, fy2] = faultLines[f];
    brush.line(fx1 + 2.2, fy1 - 1.8, fx2 + 2.2, fy2 - 1.8);
  }

  // -------------------------------------------------------------------------
  // PASS 4: Milky Laminate Crazing & Pulverized Glass at Impact Point
  // -------------------------------------------------------------------------
  // Dense concentric & radial milky white refraction rings at IMPACT (435, 485)
  brush.set("cpencil", "#FFFFFF", 0.78);
  for (let r = 8; r < 145; r += 5.5) {
    let numArcs = Math.floor(map(r, 8, 145, 5, 16));
    for (let a = 0; a < numArcs; a++) {
      let a1 = random(360);
      let a2 = a1 + random(14, 38);
      let rad = r + random(-2, 2);
      let x1 = IMPACT.x + cos(a1) * rad;
      let y1 = IMPACT.y + sin(a1) * rad;
      let x2 = IMPACT.x + cos(a2) * rad;
      let y2 = IMPACT.y + sin(a2) * rad;
      brush.line(x1, y1, x2, y2);
    }
  }

  // Secondary micro-crazing around SHEAR_NODE (845, 735)
  for (let r = 10; r < 78; r += 7) {
    for (let a = 0; a < 7; a++) {
      let a1 = random(360);
      let a2 = a1 + random(18, 42);
      let x1 = SHEAR_NODE.x + cos(a1) * r;
      let y1 = SHEAR_NODE.y + sin(a1) * r;
      let x2 = SHEAR_NODE.x + cos(a2) * r;
      let y2 = SHEAR_NODE.y + sin(a2) * r;
      brush.line(x1, y1, x2, y2);
    }
  }

  // Sharp micro-splinters and pulverized dark/white glass crumbs at impact center
  brush.set("rotring", PALETTE.inkDark, 0.34);
  for (let i = 0; i < 95; i++) {
    let ang = random(360);
    let d = random(4, 115) * random(0.3, 1.0);
    let len = random(4, 16);
    let x1 = IMPACT.x + cos(ang) * d;
    let y1 = IMPACT.y + sin(ang) * d;
    let crackAng = ang + random(-65, 65);
    brush.line(x1, y1, x1 + cos(crackAng) * len, y1 + sin(crackAng) * len);
  }

  // Fine stress-hackle feathers along the main radial rays
  brush.set("2H", PALETTE.graphite2B, 0.25);
  for (let i = 0; i < 140; i++) {
    let e = uniqueEdges[Math.floor(random(uniqueEdges.length))];
    if (e.dImp < 420) {
      let t = random(0.15, 0.85);
      let px = lerp(e.x1, e.x2, t);
      let py = lerp(e.y1, e.y2, t);
      let ang = atan2(e.y2 - e.y1, e.x2 - e.x1) + (random() < 0.5 ? 68 : -68);
      let hLen = random(5, 15);
      brush.line(px, py, px + cos(ang) * hLen, py + sin(ang) * hLen);
    }
  }

  // -------------------------------------------------------------------------
  // PASS 5: Foreground Crisp Air-Freshener Tree
  // -------------------------------------------------------------------------
  drawCrispAirFreshener();

  noLoop();
}

