// ============================================================================
// CORE GEOMETRY & RENDERING HELPERS
// ============================================================================

function wcPlane(pts, col, opacity = 200, bleed = 0.035, tex = 0.45, border = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "in");
  brush.fillTexture(tex, border);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function solidPlane(pts, col, opacity = 240) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function hatchPlane(pts, brushName, col, weight, dist, angle, rand = 0.02) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, { rand: rand });
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function penLine(x1, y1, x2, y2, col = PAL.STEEL_ABYSS, weight = 0.55, bName = "rotring") {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function penPoly(pts, col = PAL.STEEL_ABYSS, weight = 0.55, close = true, bName = "rotring") {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
  if (close && pts.length > 2) {
    brush.line(pts[pts.length - 1][0], pts[pts.length - 1][1], pts[0][0], pts[0][1]);
  }
}

function rectPts(x, y, w, h) {
  return [
    [x, y],
    [x + w, y],
    [x + w, y + h],
    [x, y + h]
  ];
}

// Cylindrical perspective curve at height y0 and radius R
function cylY(u, y0, R = TUN_R) {
  let clamped = constrain(u, -1, 1);
  let sag = (y0 - EYE_Y) * 0.088 * (R / 330);
  return y0 + sag * sqrt(max(0, 1 - clamped * clamped));
}

function cylPt(u, y0, R = TUN_R) {
  return [TUN_CX + u * R, cylY(u, y0, R)];
}

function cylBandPts(u1, u2, yTop, yBot, rTop = TUN_R, rBot = TUN_R, steps = 5) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let u = lerp(u1, u2, i / steps);
    pts.push(cylPt(u, yTop, rTop));
  }
  for (let i = steps; i >= 0; i--) {
    let u = lerp(u1, u2, i / steps);
    pts.push(cylPt(u, yBot, rBot));
  }
  return pts;
}

