function drawCopperMashTun() {
  let yStackTop = -15;
  let yCollar = 195;
  let yMidCone = 325;
  let yShoulder = 450;
  let yUpperBelt = 640;
  let yLowerBelt = 865;
  let yBase = 1085;

  let rStack = 96;
  let rMidCone = 216;
  let rMain = TUN_R; // 330

  // --- 3A. HEAVY GUNMETAL STEEL BASE PLINTH / SKIRT (y = 1085..1200) ---
  let skirtBands = [
    [-1.00, -0.82, PAL.STEEL_DARK],
    [-0.82, -0.58, PAL.STEEL_MID],
    [-0.58, -0.36, PAL.STEEL_LIGHT],
    [-0.36, -0.22, PAL.STEEL_GLEAM],
    [-0.22, -0.05, PAL.STEEL_SLATE],
    [-0.05,  0.25, PAL.STEEL_DARK],
    [ 0.25,  0.65, PAL.STEEL_DEEP],
    [ 0.65,  0.84, PAL.STEEL_SLATE],
    [ 0.84,  1.00, PAL.STEEL_ABYSS]
  ];
  for (let b of skirtBands) {
    let pts = [];
    for (let i = 0; i <= 4; i++) {
      let u = lerp(b[0], b[1], i / 4);
      pts.push(cylPt(u, yBase, rMain));
    }
    pts.push([TUN_CX + b[1] * rMain, 1205]);
    pts.push([TUN_CX + b[0] * rMain, 1205]);
    solidPlane(pts, b[2], 245);
    penPoly(pts, PAL.STEEL_ABYSS, 0.45);
  }

  // Vertical stiffening ribs on plinth skirt
  let ribUs = [-0.85, -0.52, -0.15, 0.25, 0.62, 0.90];
  for (let ru of ribUs) {
    let pTop = cylPt(ru, yBase, rMain);
    solidPlane(rectPts(pTop[0] - 5, pTop[1], 10, 1205 - pTop[1]), PAL.STEEL_DEEP, 245);
    solidPlane(rectPts(pTop[0] - 5, pTop[1], 3, 1205 - pTop[1]), PAL.STEEL_LIGHT, 230);
    penPoly(rectPts(pTop[0] - 5, pTop[1], 10, 1205 - pTop[1]), PAL.STEEL_ABYSS, 0.55);
  }

  // --- 3B. MAIN COPPER CYLINDER (y = 450..1085) ---
  // Precisionist reflection sequence across normalized cylinder width [-1, 1]
  // Combines rich burnt sienna, gleaming polished copper, white-gold speculars, and cool steel cross-reflections
  let cylSpec = [
    { u1: -1.00, u2: -0.92, cTop: PAL.SIENNA_DARK,   cMid: PAL.SIENNA_BURNT,  cBot: PAL.SIENNA_DEEP },
    { u1: -0.92, u2: -0.83, cTop: PAL.REF_COOL_COPPER, cMid: PAL.STEEL_MID,   cBot: PAL.REF_WARM_SLATE }, // reflected left steel standpipe
    { u1: -0.83, u2: -0.73, cTop: PAL.COPPER_POLISH, cMid: PAL.SIENNA_LIGHT,  cBot: PAL.SIENNA_BURNT },
    { u1: -0.73, u2: -0.61, cTop: PAL.COPPER_BRIGHT, cMid: PAL.COPPER_POLISH, cBot: PAL.SIENNA_LIGHT },
    { u1: -0.61, u2: -0.50, cTop: PAL.COPPER_GLEAM,  cMid: PAL.COPPER_BRIGHT, cBot: PAL.COPPER_POLISH },
    // Primary Clerestory Specular Highlight Zone
    { u1: -0.50, u2: -0.41, cTop: PAL.COPPER_GOLD,   cMid: PAL.COPPER_GLEAM,  cBot: PAL.COPPER_BRIGHT },
    { u1: -0.41, u2: -0.33, cTop: PAL.COPPER_SPEC,   cMid: PAL.COPPER_GOLD,   cBot: PAL.COPPER_GLEAM },
    { u1: -0.33, u2: -0.28, cTop: PAL.SKY_SPEC,      cMid: PAL.COPPER_SPEC,   cBot: PAL.COPPER_GOLD },
    // Foreground vertical pipe at x=535 (u = -0.45) casts shadow & reflection near u = -0.28..-0.16
    { u1: -0.28, u2: -0.21, cTop: PAL.SIENNA_BURNT,  cMid: PAL.SIENNA_DARK,   cBot: PAL.SIENNA_DEEP },
    { u1: -0.21, u2: -0.14, cTop: PAL.COPPER_GOLD,   cMid: PAL.COPPER_GLEAM,  cBot: PAL.COPPER_POLISH },
    { u1: -0.14, u2: -0.03, cTop: PAL.COPPER_BRIGHT, cMid: PAL.COPPER_POLISH, cBot: PAL.SIENNA_BURNT },
    { u1: -0.03, u2:  0.08, cTop: PAL.SIENNA_LIGHT,  cMid: PAL.SIENNA_BURNT,  cBot: PAL.SIENNA_DARK },
    { u1:  0.08, u2:  0.17, cTop: PAL.COPPER_GLEAM,  cMid: PAL.COPPER_BRIGHT, cBot: PAL.SIENNA_LIGHT },
    { u1:  0.17, u2:  0.24, cTop: PAL.REF_COOL_COPPER, cMid: PAL.REF_WARM_SLATE, cBot: PAL.SIENNA_DARK },
    { u1:  0.24, u2:  0.37, cTop: PAL.SIENNA_BURNT,  cMid: PAL.SIENNA_DARK,   cBot: PAL.SIENNA_DEEP },
    // Deep Core Shadow Zone on Cylinder Right-Center
    { u1:  0.37, u2:  0.51, cTop: PAL.SIENNA_DARK,   cMid: PAL.SIENNA_DEEP,   cBot: PAL.SIENNA_ABYSS },
    { u1:  0.51, u2:  0.57, cTop: PAL.SIENNA_DEEP,   cMid: PAL.SIENNA_ABYSS,  cBot: PAL.SIENNA_ABYSS },
    // Right pipe reflection & secondary warm copper bounce
    { u1:  0.57, u2:  0.66, cTop: PAL.COPPER_POLISH, cMid: PAL.SIENNA_LIGHT,  cBot: PAL.SIENNA_DARK },
    { u1:  0.66, u2:  0.74, cTop: PAL.COPPER_GLEAM,  cMid: PAL.COPPER_BRIGHT, cBot: PAL.COPPER_POLISH },
    { u1:  0.74, u2:  0.82, cTop: PAL.REF_COOL_COPPER, cMid: PAL.STEEL_SLATE, cBot: PAL.SIENNA_DARK },
    { u1:  0.82, u2:  0.92, cTop: PAL.SIENNA_BURNT,  cMid: PAL.SIENNA_DARK,   cBot: PAL.SIENNA_DEEP },
