    { u1: -0.46, u2: -0.32, y1: 450, y2: 760, col: PAL.SKY_SPEC },
    { u1: -0.83, u2: -0.61, y1: 520, y2: 590, col: PAL.COPPER_GLEAM },
    { u1:  0.08, u2:  0.22, y1: 470, y2: 610, col: PAL.COPPER_GOLD },
    { u1:  0.64, u2:  0.74, y1: 510, y2: 720, col: PAL.COPPER_GOLD },
    { u1: -0.61, u2: -0.14, y1: 790, y2: 865, col: PAL.SIENNA_BURNT },
