  }

  // --- 3C. CONICAL COPPER DOME / HOOD (y = 195..450) ---
  // Notice how conical reflections shift slightly relative to cylinder reflections for authentic optical kink!
  for (let i = 0; i < cylSpec.length; i++) {
    let b = cylSpec[i];
    // Upper cone (yCollar to yMidCone)
    let ptsConeTop = cylBandPts(b.u1, b.u2, yCollar, yMidCone, rStack, rMidCone, 2);
    // Lower cone (yMidCone to yShoulder)
    let ptsConeBot = cylBandPts(b.u1, b.u2, yMidCone, yShoulder, rMidCone, rMain, 2);

    wcPlane(ptsConeTop, b.cTop, 230, 0.03, 0.45, 0.35);
