  for (let b of cylSpec) {
    let ptsStack = cylBandPts(b.u1, b.u2, yStackTop, yCollar, rStack, rStack, 2);
    solidPlane(ptsStack, b.cTop, 235);
  }
  solidPlane(cylBandPts(-0.46, -0.24, yStackTop, yCollar, rStack, rStack, 2), PAL.SKY_SPEC, 230);
  solidPlane(cylBandPts(0.35, 0.62, yStackTop, yCollar, rStack, rStack, 2), PAL.SIENNA_ABYSS, 235);

  // --- 3E. FINE BRUSHED / SPUN COPPER CIRCUMFERENTIAL GRAIN & RAZOR FACET LINES ---
  // Razor vertical & radial division lines along major reflection boundaries
  let majorDivs = [-1.0, -0.83, -0.61, -0.41, -0.33, -0.28, -0.14, 0.08, 0.24, 0.37, 0.57, 0.74, 0.92, 1.0];
  for (let u of majorDivs) {
    let p0 = cylPt(u, yStackTop, rStack);
    let p1 = cylPt(u, yCollar, rStack);
    let p2 = cylPt(u, yMidCone, rMidCone);
    let p3 = cylPt(u, yShoulder, rMain);
    let p4 = cylPt(u, yBase, rMain);
    let lineCol = (u > -0.55 && u < -0.15) ? PAL.SIENNA_LIGHT : PAL.SIENNA_ABYSS;
    penLine(p0[0], p0[1], p1[0], p1[1], lineCol, 0.35, "rotring");
    penLine(p1[0], p1[1], p2[0], p2[1], lineCol, 0.38, "rotring");
    penLine(p2[0], p2[1], p3[0], p3[1], lineCol, 0.38, "rotring");
    penLine(p3[0], p3[1], p4[0], p4[1], lineCol, 0.42, "rotring");
  }

  // Spun-copper circumferential micro-grain arcs across cylinder & cone
  for (let y = yShoulder + 14; y < yBase; y += 16) {
    drawCopperGrainArc(y, rMain, -0.96, -0.15, PAL.COPPER_SPEC, 0.28);
    drawCopperGrainArc(y + 6, rMain, -0.15, 0.96, PAL.SIENNA_ABYSS, 0.3);
  }
  for (let t = 0.08; t < 0.95; t += 0.065) {
    let yc = lerp(yCollar, yShoulder, t);
    let rc = lerp(rStack, rMain, t);
    drawCopperGrainArc(yc, rc, -0.95, -0.1, PAL.COPPER_SPEC, 0.28);
    drawCopperGrainArc(yc + 4, rc, -0.1, 0.95, PAL.SIENNA_ABYSS, 0.3);
  }

  // Cast shadow of the foreground vertical pipe (x = 535, u = -0.45) onto the copper mash tun!
  // Because north light is from upper-left, the pipe at x=535 casts a shadow at u = -0.35..-0.24
  let pipeShadowPts = cylBandPts(-0.34, -0.25, 390, yBase, rMain, rMain, 3);
  wcPlane(pipeShadowPts, PAL.SIENNA_ABYSS, 155, 0.02, 0.3, 0.3);
  // And the right foreground vertical pipe (x = 855, u = 0.51) casts a shadow at u = 0.58..0.66
  let rightShadowPts = cylBandPts(0.58, 0.65, 535, yBase, rMain, rMain, 3);
  wcPlane(rightShadowPts, PAL.SIENNA_ABYSS, 165, 0.02, 0.3, 0.3);

  // --- 3F. VERTICAL & RADIAL RIVETED LAP-SEAM STRAPS ---
  let vertSeamUs = [-0.70, -0.06, 0.42, 0.84];
  for (let su of vertSeamUs) {
    drawVerticalRivetedSeam(su, yCollar, yShoulder, yBase, rStack, rMain);
  }

  // --- 3G. HORIZONTAL RIVETED COPPER BELT STRAPS ---
  drawHorizontalRivetedStrap(yCollar, rStack, 16, 18);
  drawHorizontalRivetedStrap(yMidCone, rMidCone, 18, 28);
  drawHorizontalRivetedStrap(yShoulder, rMain, 24, 40);
  drawHorizontalRivetedStrap(yUpperBelt, rMain, 20, 38);
  drawHorizontalRivetedStrap(yLowerBelt, rMain, 20, 38);
  drawHorizontalRivetedStrap(yBase, rMain, 24, 40);

  // Outer silhouette razor contour of the entire Copper Mash Tun
  let leftCone = [cylPt(-1, yStackTop, rStack), cylPt(-1, yCollar, rStack), cylPt(-1, yShoulder, rMain), cylPt(-1, yBase, rMain)];
  let rightCone = [cylPt(1, yStackTop, rStack), cylPt(1, yCollar, rStack), cylPt(1, yShoulder, rMain), cylPt(1, yBase, rMain)];
  penPoly(leftCone, PAL.SIENNA_ABYSS, 0.9, false);
  penPoly(rightCone, PAL.SIENNA_ABYSS, 0.9, false);

  // --- 3H. PRESSURIZED BRONZE & COPPER MANWAY HATCH / SIGHT GLASS (cx = 628, cy = 572) ---
  drawMashTunManway(628, 572);

  // --- 3I. SECONDARY POLISHED COPPER CIP PIPE & GRANT (Echoing Copper Accent) ---
  drawCopperPipe(758, 255, 945, 195, 15);
  drawCopperPipe(945, 195, 945, 815, 15);
  drawPipeFlange(758, 255, 0.3, -0.95, 16, true);
  drawPipeFlange(945, 195, -0.7, -0.7, 16, true);
  drawPipeFlange(945, 460, -1, 0, 16, true);
}

function drawCopperGrainArc(y0, R, uStart, uEnd, col, weight) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("2H", col, weight);
  let steps = 14;
  for (let i = 0; i < steps; i++) {
    if (i % 3 === 2) continue; // interrupted realistic lathe grain
    let uA = lerp(uStart, uEnd, i / steps);
    let uB = lerp(uStart, uEnd, (i + 1) / steps);
    let pA = cylPt(uA, y0, R);
    let pB = cylPt(uB, y0, R);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }
}

function drawHorizontalRivetedStrap(y0, R, strapH, numRivets) {
  let yTop = y0 - strapH * 0.5;
  let yBot = y0 + strapH * 0.5;

  // Draw strap segments matching the copper cylinder lighting
  let segs = 24;
  for (let i = 0; i < segs; i++) {
    let u1 = lerp(-1, 1, i / segs);
    let u2 = lerp(-1, 1, (i + 1) / segs);
    let uMid = (u1 + u2) * 0.5;

    let col = PAL.COPPER_POLISH;
    if (uMid < -0.65) col = PAL.SIENNA_BURNT;
    else if (uMid < -0.45) col = PAL.COPPER_BRIGHT;
    else if (uMid < -0.28) col = PAL.COPPER_SPEC;
    else if (uMid < -0.15) col = PAL.COPPER_GOLD;
    else if (uMid < 0.10) col = PAL.COPPER_POLISH;
    else if (uMid < 0.28) col = PAL.SIENNA_LIGHT;
    else if (uMid < 0.58) col = PAL.SIENNA_DEEP;
    else if (uMid < 0.76) col = PAL.COPPER_BRIGHT;
    else col = PAL.SIENNA_DARK;

    let pts = cylBandPts(u1, u2, yTop, yBot, R, R, 1);
    solidPlane(pts, col, 240);
  }

  // Top bevel highlight & bottom cast shadow of lap strap
  for (let i = 0; i < segs; i++) {
    let u1 = lerp(-1, 1, i / segs);
    let u2 = lerp(-1, 1, (i + 1) / segs);
    let pT1 = cylPt(u1, yTop, R);
    let pT2 = cylPt(u2, yTop, R);
    let pB1 = cylPt(u1, yBot, R);
    let pB2 = cylPt(u2, yBot, R);

    // Upper bevel catch-light
    let hiCol = (u1 > -0.6 && u1 < 0.1) ? PAL.COPPER_SPEC : PAL.COPPER_GLEAM;
    penLine(pT1[0], pT1[1] + 1.5, pT2[0], pT2[1] + 1.5, hiCol, 0.65, "cpencil");
    // Lower shadow under strap lip
    penLine(pB1[0], pB1[1] + 2, pB2[0], pB2[1] + 2, PAL.SIENNA_ABYSS, 0.9, "rotring");
    // Razor pen edges
    penLine(pT1[0], pT1[1], pT2[0], pT2[1], PAL.SIENNA_ABYSS, 0.55, "rotring");
    penLine(pB1[0], pB1[1], pB2[0], pB2[1], PAL.SIENNA_ABYSS, 0.65, "rotring");
  }

  // Double staggered row of photographic copper rivets
  let rRad = constrain(strapH * 0.19, 2.8, 4.5);
  for (let i = 1; i < numRivets; i++) {
    // Cosine spacing near edges for true cylindrical foreshortening!
    let theta = map(i, 0, numRivets, -84, 84);
    let u = sin(theta);
    let foreshorten = cos(theta);
    if (foreshorten < 0.18) continue;

    let pUpper = cylPt(u, y0 - strapH * 0.23, R);
    let pLower = cylPt(u, y0 + strapH * 0.23, R);
    let isLit = (u > -0.65 && u < 0.15) || (u > 0.60 && u < 0.78);
    drawCopperRivet(pUpper[0], pUpper[1], rRad * sqrt(foreshorten), rRad, isLit);
    drawCopperRivet(pLower[0], pLower[1], rRad * sqrt(foreshorten), rRad, isLit);
  }
}

function drawVerticalRivetedSeam(u, yCollar, yShoulder, yBase, rStack, rMain) {
  let du = 0.022;
  // Cone radial seam
  let pC1 = cylPt(u - du, yCollar, rStack);
  let pC2 = cylPt(u + du, yCollar, rStack);
  let pS1 = cylPt(u - du, yShoulder, rMain);
  let pS2 = cylPt(u + du, yShoulder, rMain);
  let seamCol = (u < 0) ? PAL.COPPER_BRIGHT : PAL.SIENNA_DARK;
  solidPlane([pC1, pC2, pS2, pS1], seamCol, 225);
  penLine(pC1[0], pC1[1], pS1[0], pS1[1], PAL.COPPER_SPEC, 0.5);
  penLine(pC2[0], pC2[1], pS2[0], pS2[1], PAL.SIENNA_ABYSS, 0.65);

  // Cylinder vertical seam
  let pB1 = cylPt(u - du, yBase, rMain);
  let pB2 = cylPt(u + du, yBase, rMain);
  solidPlane([pS1, pS2, pB2, pB1], seamCol, 225);
  penLine(pS1[0], pS1[1], pB1[0], pB1[1], PAL.COPPER_SPEC, 0.5);
  penLine(pS2[0], pS2[1], pB2[0], pB2[1], PAL.SIENNA_ABYSS, 0.65);

  // Rivets along radial cone seam
  let isLit = u < 0.15;
  for (let t = 0.08; t < 0.94; t += 0.075) {
    let rx = lerp((pC1[0] + pC2[0]) * 0.5, (pS1[0] + pS2[0]) * 0.5, t);
    let ry = lerp((pC1[1] + pC2[1]) * 0.5, (pS1[1] + pS2[1]) * 0.5, t);
    drawCopperRivet(rx, ry, 3.2, 3.4, isLit);
  }
  // Rivets along vertical cylinder seam
  for (let y = yShoulder + 22; y < yBase - 18; y += 22) {
    let pt = cylPt(u, y, rMain);
    drawCopperRivet(pt[0], pt[1], 3.4, 3.6, isLit);
  }
}

function drawCopperRivet(x, y, rx, ry, isLit = true) {
  // 1. Cast shadow crescent below-right
  let shPts = ellipsePts(x + rx * 0.35, y + ry * 0.42, rx * 0.95, ry * 0.95, 8);
  solidPlane(shPts, PAL.SIENNA_ABYSS, 240);

  // 2. Domed copper rivet body
  let bodyCol = isLit ? PAL.COPPER_BRIGHT : PAL.SIENNA_BURNT;
  let domePts = ellipsePts(x, y, rx, ry, 10);
  solidPlane(domePts, bodyCol, 245);

  // 3. Upper-left north-light specular dot
  let hiCol = isLit ? PAL.SKY_SPEC : PAL.COPPER_GLEAM;
  let hiPts = ellipsePts(x - rx * 0.32, y - ry * 0.32, rx * 0.45, ry * 0.45, 6);
  solidPlane(hiPts, hiCol, 250);

  // 4. Razor rim contour
  penPoly(domePts, PAL.SIENNA_ABYSS, 0.38, true);
}

function drawMicroRivet(x, y, r, isCopper = false) {
  let shCol = isCopper ? PAL.SIENNA_ABYSS : PAL.STEEL_ABYSS;
  let midCol = isCopper ? PAL.COPPER_POLISH : PAL.STEEL_SLATE;
  let hiCol = isCopper ? PAL.COPPER_SPEC : PAL.STEEL_SPEC;
  solidPlane(ellipsePts(x + r * 0.3, y + r * 0.35, r, r, 8), shCol, 235);
  solidPlane(ellipsePts(x, y, r, r, 8), midCol, 245);
  solidPlane(ellipsePts(x - r * 0.3, y - r * 0.3, r * 0.45, r * 0.45, 6), hiCol, 250);
  penPoly(ellipsePts(x, y, r, r, 8), shCol, 0.35, true);
}

function ellipsePts(cx, cy, rx, ry, n = 20, aStart = 0, aEnd = 360) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = lerp(aStart, aEnd, i / n);
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  return pts;
}

function ringSectorPts(cx, cy, rxOut, ryOut, rxIn, ryIn, a1, a2, steps = 8) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(a1, a2, i / steps);
    pts.push([cx + cos(a) * rxOut, cy + sin(a) * ryOut]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(a1, a2, i / steps);
    pts.push([cx + cos(a) * rxIn, cy + sin(a) * ryIn]);
  }
  return pts;
}

function drawMashTunManway(cx, cy) {
  let rx = 98, ry = 76;

  // Heavy cast shadow of protruding manway assembly on copper wall
  solidPlane(ellipsePts(cx + 12, cy + 14, rx + 6, ry + 6, 28), PAL.SIENNA_ABYSS, 215);

  // Outer bolted bronze flange ring with faceted metallic reflections
  let sectors = [
    [0, 45, PAL.SIENNA_DARK],
    [45, 110, PAL.SIENNA_DEEP],
    [110, 175, PAL.COPPER_POLISH],
    [175, 225, PAL.COPPER_GLEAM],
    [225, 265, PAL.COPPER_SPEC],
    [265, 315, PAL.COPPER_BRIGHT],
    [315, 360, PAL.SIENNA_BURNT]
  ];
  for (let s of sectors) {
    solidPlane(ringSectorPts(cx, cy, rx, ry, rx * 0.78, ry * 0.78, s[0], s[1], 6), s[2], 245);
  }
  penPoly(ellipsePts(cx, cy, rx, ry, 32), PAL.SIENNA_ABYSS, 0.75);
  penPoly(ellipsePts(cx, cy, rx * 0.78, ry * 0.78, 28), PAL.SIENNA_ABYSS, 0.65);

  // Recessed dished copper hatch door
  let dishSectors = [
    [0, 70, PAL.COPPER_GLEAM],
    [70, 150, PAL.COPPER_POLISH],
    [150, 240, PAL.SIENNA_DEEP],
    [240, 315, PAL.SIENNA_BURNT],
    [315, 360, PAL.COPPER_GOLD]
  ];
  for (let s of dishSectors) {
    solidPlane(ringSectorPts(cx, cy, rx * 0.76, ry * 0.76, rx * 0.36, ry * 0.36, s[0], s[1], 6), s[2], 240);
  }
  penPoly(ellipsePts(cx, cy, rx * 0.76, ry * 0.76, 28), PAL.SIENNA_ABYSS, 0.55);

  // Central Circular Sight-Glass Porthole (r = 34)
  let gx = cx, gy = cy;
  solidPlane(ellipsePts(gx, gy, 38, 32, 24), PAL.STEEL_DARK, 245);
  solidPlane(ellipsePts(gx, gy, 31, 26, 24), PAL.SIENNA_ABYSS, 250);
  // Warm amber wort glow in lower sight glass
  solidPlane(ringSectorPts(gx, gy, 29, 24, 0, 0, 20, 160, 10), PAL.SIENNA_BURNT, 210);
  // Crisp geometric diagonal clerestory reflection slash across the dark sight glass
  solidPlane([
    [gx - 22, gy - 12],
    [gx - 6, gy - 22],
    [gx + 22, gy + 10],
    [gx + 8, gy + 20]
  ], PAL.SKY_ICE, 215);
  solidPlane([
    [gx - 15, gy - 17],
    [gx - 8, gy - 21],
    [gx + 19, gy + 12],
    [gx + 13, gy + 17]
  ], PAL.SKY_SPEC, 235);
  penPoly(ellipsePts(gx, gy, 38, 32, 24), PAL.STEEL_ABYSS, 0.65);
  penPoly(ellipsePts(gx, gy, 31, 26, 24), PAL.STEEL_ABYSS, 0.65);

  // Horizontal heavy cast-bronze hinge bar & screw wheel across the manway
  solidPlane(rectPts(cx - rx - 14, cy - 9, rx * 2 + 22, 18), PAL.SIENNA_DARK, 245);
  solidPlane(rectPts(cx - rx - 14, cy - 9, rx * 2 + 22, 5), PAL.COPPER_GOLD, 240);
  solidPlane(rectPts(cx - rx - 14, cy + 4, rx * 2 + 22, 5), PAL.SIENNA_ABYSS, 245);
  penPoly(rectPts(cx - rx - 14, cy - 9, rx * 2 + 22, 18), PAL.SIENNA_ABYSS, 0.65);

  // 8 radial dog-clamp bolts around the manway perimeter
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + 22.5;
    let bx = cx + cos(a) * (rx * 0.88);
    let by = cy + sin(a) * (ry * 0.88);
    solidPlane(rectPts(bx - 5, by - 5, 10, 10), PAL.STEEL_LIGHT, 245);
    solidPlane(rectPts(bx - 5, by - 5, 4, 10), PAL.STEEL_SPEC, 245);
    penPoly(rectPts(bx - 5, by - 5, 10, 10), PAL.STEEL_ABYSS, 0.5);
  }
}

// ============================================================================
// 4. STAINLESS STEEL PIPE CATHEDRAL (PIPES, ELBOWS & BOLTED FLANGES)
// ============================================================================

function drawStainlessPipe(x1, y1, x2, y2, r, nearCopper = false, isBack = false) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  let ux = dx / len;
  let uy = dy / len;

  // Normal vector oriented toward upper-left north light (-0.707, -0.707)
  let nx = -uy;
  let ny = ux;
  if (nx * -0.707 + ny * -0.707 < 0) {
    nx = -nx;
    ny = -ny;
  }

  // 9 Precisionist cylindrical reflection bands across pipe width s in [-1 (shadow), +1 (lit)]
  let bounceCol = nearCopper ? PAL.REF_COPPER_STEEL : PAL.STEEL_MID;
  let bounceWarm = nearCopper ? PAL.COPPER_POLISH : PAL.STEEL_SLATE;

  let bands = [
    { s1:  0.84, s2:  1.00, col: PAL.STEEL_SLATE },
    { s1:  0.60, s2:  0.84, col: PAL.STEEL_GLEAM },
    { s1:  0.38, s2:  0.60, col: PAL.STEEL_SPEC },     // Primary razor north-light specular band
    { s1:  0.22, s2:  0.38, col: PAL.STEEL_MID },      // Crisp internal reflection step
    { s1:  0.06, s2:  0.22, col: PAL.STEEL_LIGHT },    // Secondary bright stainless band
    { s1: -0.22, s2:  0.06, col: PAL.STEEL_SLATE },    // Mid cylinder gunmetal
    { s1: -0.56, s2: -0.22, col: PAL.STEEL_DEEP },     // Core shadow band
    { s1: -0.82, s2: -0.56, col: bounceCol },          // Reflected copper/ambient bounce band
    { s1: -1.00, s2: -0.82, col: PAL.STEEL_ABYSS }     // Dark shadow edge
  ];

  // Base watercolor wash for the whole pipe body to give subtle pigment grain
  let pipeOutline = [
    [x1 + nx * r, y1 + ny * r],
    [x2 + nx * r, y2 + ny * r],
    [x2 - nx * r, y2 - ny * r],
    [x1 - nx * r, y1 - ny * r]
  ];
  wcPlane(pipeOutline, PAL.STEEL_MID, isBack ? 190 : 215, 0.02, 0.4, 0.3);

  // Crisp ruled reflection bands
  for (let b of bands) {
    let pts = [
      [x1 + nx * (r * b.s1), y1 + ny * (r * b.s1)],
      [x2 + nx * (r * b.s1), y2 + ny * (r * b.s1)],
      [x2 + nx * (r * b.s2), y2 + ny * (r * b.s2)],
      [x1 + nx * (r * b.s2), y1 + ny * (r * b.s2)]
    ];
    solidPlane(pts, b.col, isBack ? 215 : 238);
  }

  // Optional warm copper glint strip on pipes right next to the mash tun
  if (nearCopper) {
    let cPts = [
      [x1 + nx * (r * -0.74), y1 + ny * (r * -0.74)],
      [x2 + nx * (r * -0.74), y2 + ny * (r * -0.74)],
      [x2 + nx * (r * -0.62), y2 + ny * (r * -0.62)],
      [x1 + nx * (r * -0.62), y1 + ny * (r * -0.62)]
    ];
    solidPlane(cPts, bounceWarm, 185);
  }

  // Brushed-steel circumferential & longitudinal micro-grain
  let grainStep = isBack ? 9 : 6;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  for (let d = 8; d < len - 8; d += grainStep) {
    let px = x1 + ux * d;
    let py = y1 + uy * d;
    // Circumferential brushed lathe lines
    brush.set("2H", PAL.STEEL_ABYSS, 0.26);
    brush.line(px + nx * r * 0.9, py + ny * r * 0.9, px - nx * r * 0.2, py - ny * r * 0.2);
    brush.set("2H", PAL.STEEL_SPEC, 0.28);
    brush.line(px + nx * r * 0.75, py + ny * r * 0.75, px + nx * r * 0.1, py + ny * r * 0.1);
  }

  // Razor pen internal reflection division lines & outer silhouette edges
  let divS = [0.60, 0.38, 0.06, -0.22, -0.56];
  for (let s of divS) {
    penLine(
      x1 + nx * r * s, y1 + ny * r * s,
      x2 + nx * r * s, y2 + ny * r * s,
      PAL.STEEL_DARK, 0.32, "rotring"
    );
  }
  penLine(x1 + nx * r, y1 + ny * r, x2 + nx * r, y2 + ny * r, PAL.STEEL_ABYSS, 0.7, "rotring");
  penLine(x1 - nx * r, y1 - ny * r, x2 - nx * r, y2 - ny * r, PAL.STEEL_ABYSS, 0.75, "rotring");
}

function drawCopperPipe(x1, y1, x2, y2, r) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  let ux = dx / len;
  let uy = dy / len;
  let nx = -uy;
  let ny = ux;
  if (nx * -0.707 + ny * -0.707 < 0) {
    nx = -nx;
    ny = -ny;
  }

  let bands = [
    { s1:  0.80, s2:  1.00, col: PAL.SIENNA_BURNT },
    { s1:  0.55, s2:  0.80, col: PAL.COPPER_GLEAM },
    { s1:  0.32, s2:  0.55, col: PAL.COPPER_SPEC },
    { s1:  0.10, s2:  0.32, col: PAL.COPPER_BRIGHT },
    { s1: -0.25, s2:  0.10, col: PAL.COPPER_POLISH },
    { s1: -0.62, s2: -0.25, col: PAL.SIENNA_DEEP },
    { s1: -0.85, s2: -0.62, col: PAL.REF_COOL_COPPER },
    { s1: -1.00, s2: -0.85, col: PAL.SIENNA_ABYSS }
  ];

  for (let b of bands) {
    let pts = [
      [x1 + nx * (r * b.s1), y1 + ny * (r * b.s1)],
      [x2 + nx * (r * b.s1), y2 + ny * (r * b.s1)],
      [x2 + nx * (r * b.s2), y2 + ny * (r * b.s2)],
      [x1 + nx * (r * b.s2), y1 + ny * (r * b.s2)]
    ];
    solidPlane(pts, b.col, 240);
  }
  penLine(x1 + nx * r, y1 + ny * r, x2 + nx * r, y2 + ny * r, PAL.SIENNA_ABYSS, 0.65);
  penLine(x1 - nx * r, y1 - ny * r, x2 - nx * r, y2 - ny * r, PAL.SIENNA_ABYSS, 0.65);
}

// Draws a segmented miter/mandrel pipe elbow between two directions
function drawPipeElbow(cx, cy, r, ang1, ang2, nearCopper = false) {
  let steps = 4;
  let radBend = r * 1.15;
  // Center of curvature
  let midAng = (ang1 + ang2) * 0.5;
  for (let i = 0; i < steps; i++) {
    let aA = lerp(ang1, ang2, i / steps);
    let aB = lerp(ang1, ang2, (i + 1) / steps);
    let xA = cx + cos(aA) * radBend * 0.35;
    let yA = cy + sin(aA) * radBend * 0.35;
    let xB = cx + cos(aB) * radBend * 0.35;
    let yB = cy + sin(aB) * radBend * 0.35;
    drawStainlessPipe(xA, yA, xB, yB, r, nearCopper, false);
  }
}

// Draws a heavy bolted industrial tri-clamp / flange joint perpendicular to (ux, uy)
function drawPipeFlange(cx, cy, nx, ny, pipeR, isCopper = false) {
  // (nx, ny) is the normal across the pipe width; axis along pipe is (-ny, nx)
  let nLen = sqrt(nx * nx + ny * ny);
  if (nLen < 0.001) return;
  nx /= nLen;
  ny /= nLen;
  let ax = -ny;
  let ay = nx;

  // Ensure (nx, ny) points toward upper-left light
  if (nx * -0.707 + ny * -0.707 < 0) {
    nx = -nx;
    ny = -ny;
  }

  let flR = pipeR * 1.34 + 5;
  let flThick = max(13, pipeR * 0.44);
  let halfT = flThick * 0.5;

  // Cast shadow of flange onto pipe
  let shPts = [
    [cx - ax * (halfT + 4) + nx * pipeR, cy - ay * (halfT + 4) + ny * pipeR],
    [cx + ax * (halfT + 6) + nx * pipeR, cy + ay * (halfT + 6) + ny * pipeR],
    [cx + ax * (halfT + 6) - nx * pipeR, cy + ay * (halfT + 6) - ny * pipeR],
    [cx - ax * (halfT + 4) - nx * pipeR, cy - ay * (halfT + 4) - ny * pipeR]
  ];
  solidPlane(shPts, isCopper ? PAL.SIENNA_ABYSS : PAL.STEEL_ABYSS, 210);

  let bands = isCopper
    ? [
        { s1:  0.65, s2:  1.00, col: PAL.COPPER_GLEAM },
        { s1:  0.30, s2:  0.65, col: PAL.COPPER_SPEC },
        { s1: -0.15, s2:  0.30, col: PAL.COPPER_POLISH },
        { s1: -0.60, s2: -0.15, col: PAL.SIENNA_DEEP },
        { s1: -1.00, s2: -0.60, col: PAL.SIENNA_BURNT }
      ]
    : [
        { s1:  0.68, s2:  1.00, col: PAL.STEEL_LIGHT },
        { s1:  0.32, s2:  0.68, col: PAL.STEEL_SPEC },
        { s1: -0.10, s2:  0.32, col: PAL.STEEL_MID },
        { s1: -0.58, s2: -0.10, col: PAL.STEEL_DEEP },
        { s1: -0.82, s2: -0.58, col: PAL.STEEL_SLATE },
        { s1: -1.00, s2: -0.82, col: PAL.STEEL_ABYSS }
      ];

  for (let b of bands) {
    let p1 = [cx - ax * halfT + nx * flR * b.s1, cy - ay * halfT + ny * flR * b.s1];
    let p2 = [cx + ax * halfT + nx * flR * b.s1, cy + ay * halfT + ny * flR * b.s1];
    let p3 = [cx + ax * halfT + nx * flR * b.s2, cy + ay * halfT + ny * flR * b.s2];
    let p4 = [cx - ax * halfT + nx * flR * b.s2, cy - ay * halfT + ny * flR * b.s2];
    solidPlane([p1, p2, p3, p4], b.col, 248);
  }

  // Central dark gasket seam line splitting the two bolted flange plates
  penLine(cx + nx * flR, cy + ny * flR, cx - nx * flR, cy - ny * flR, PAL.STEEL_ABYSS, 0.75);

  // Outer flange perimeter outline
  let outline = [
    [cx - ax * halfT + nx * flR, cy - ay * halfT + ny * flR],
    [cx + ax * halfT + nx * flR, cy + ay * halfT + ny * flR],
    [cx + ax * halfT - nx * flR, cy + ay * halfT - ny * flR],
    [cx - ax * halfT - nx * flR, cy - ay * halfT - ny * flR]
  ];
  penPoly(outline, PAL.STEEL_ABYSS, 0.65);

  // Machined hex bolts protruding through the flange rim
  let boltPositions = [-0.82, -0.42, 0.0, 0.42, 0.82];
  let bSize = constrain(pipeR * 0.14, 3, 5.5);
  for (let bs of boltPositions) {
    let bx = cx + nx * flR * bs;
    let by = cy + ny * flR * bs;
    let bPts1 = [
      [bx - ax * (halfT + bSize) + nx * bSize, by - ay * (halfT + bSize) + ny * bSize],
      [bx - ax * halfT + nx * bSize, by - ay * halfT + ny * bSize],
      [bx - ax * halfT - nx * bSize, by - ay * halfT - ny * bSize],
      [bx - ax * (halfT + bSize) - nx * bSize, by - ay * (halfT + bSize) - ny * bSize]
    ];
    let bPts2 = [
      [bx + ax * halfT + nx * bSize, by + ay * halfT + ny * bSize],
      [bx + ax * (halfT + bSize) + nx * bSize, by + ay * (halfT + bSize) + ny * bSize],
      [bx + ax * (halfT + bSize) - nx * bSize, by + ay * (halfT + bSize) - ny * bSize],
      [bx + ax * halfT - nx * bSize, by + ay * halfT - ny * bSize]
    ];
    solidPlane(bPts1, bs > 0 ? PAL.STEEL_SPEC : PAL.STEEL_DARK, 245);
    solidPlane(bPts2, bs > 0 ? PAL.STEEL_LIGHT : PAL.STEEL_DEEP, 245);
    penPoly(bPts1, PAL.STEEL_ABYSS, 0.45);
    penPoly(bPts2, PAL.STEEL_ABYSS, 0.45);
  }
}

