function drawFrontHandwheelValve(cx, cy, r, isCopperAccent = true) {
  // Cast shadow of handwheel onto pipe behind it
  solidPlane(ellipsePts(cx + 9, cy + 11, r + 3, r + 3, 28), PAL.STEEL_ABYSS, 205);

  let rimOuter = r;
  let rimInner = r * 0.78;
  let hubR = r * 0.26;

  // 6 radial cast spokes with highlight & shadow bevels
  for (let i = 0; i < 6; i++) {
    let a = i * 60 + 15;
    let ca = cos(a), sa = sin(a);
    let nx = -sa, ny = ca;
    let w = r * 0.085;
    let p1 = [cx + ca * hubR + nx * w, cy + sa * hubR + ny * w];
    let p2 = [cx + ca * rimInner + nx * w * 0.75, cy + sa * rimInner + ny * w * 0.75];
    let p3 = [cx + ca * rimInner - nx * w * 0.75, cy + sa * rimInner - ny * w * 0.75];
    let p4 = [cx + ca * hubR - nx * w, cy + sa * hubR - ny * w];
    let spokeCol = isCopperAccent ? PAL.SIENNA_BURNT : PAL.STEEL_DARK;
    let spokeHi = isCopperAccent ? PAL.COPPER_GLEAM : PAL.STEEL_LIGHT;
    solidPlane([p1, p2, p3, p4], spokeCol, 245);
    penLine(p1[0], p1[1], p2[0], p2[1], spokeHi, 0.65);
    penPoly([p1, p2, p3, p4], PAL.STEEL_ABYSS, 0.5);
  }

  // Faceted outer wheel rim
  let sectors = isCopperAccent
    ? [
        [0, 60, PAL.SIENNA_BURNT],
        [60, 130, PAL.SIENNA_DEEP],
        [130, 195, PAL.COPPER_POLISH],
        [195, 245, PAL.COPPER_SPEC],
        [245, 290, PAL.COPPER_GLEAM],
        [290, 360, PAL.COPPER_BRIGHT]
      ]
    : [
        [0, 60, PAL.STEEL_SLATE],
        [60, 130, PAL.STEEL_DEEP],
        [130, 195, PAL.STEEL_MID],
        [195, 245, PAL.STEEL_SPEC],
        [245, 290, PAL.STEEL_GLEAM],
        [290, 360, PAL.STEEL_LIGHT]
      ];

  for (let s of sectors) {
    solidPlane(ringSectorPts(cx, cy, rimOuter, rimOuter, rimInner, rimInner, s[0], s[1], 6), s[2], 248);
  }

  // Machined specular outer edge bevel
  penPoly(ellipsePts(cx, cy, rimOuter, rimOuter, 32), PAL.STEEL_ABYSS, 0.75);
  penPoly(ellipsePts(cx, cy, rimInner, rimInner, 28), PAL.STEEL_ABYSS, 0.65);
  penPoly(ellipsePts(cx, cy, (rimOuter + rimInner) * 0.5, (rimOuter + rimInner) * 0.5, 28),
    isCopperAccent ? PAL.COPPER_GOLD : PAL.STEEL_SPEC, 0.45);

  // Central machined gunmetal & brass hub with hex nut
  solidPlane(ellipsePts(cx, cy, hubR, hubR, 18), PAL.STEEL_DARK, 250);
  solidPlane(ellipsePts(cx - 2, cy - 2, hubR * 0.7, hubR * 0.7, 6), PAL.COPPER_GLEAM, 250);
  solidPlane(ellipsePts(cx, cy, hubR * 0.35, hubR * 0.35, 10), PAL.STEEL_SPEC, 250);
  penPoly(ellipsePts(cx, cy, hubR, hubR, 18), PAL.STEEL_ABYSS, 0.65);
  penPoly(ellipsePts(cx, cy, hubR * 0.7, hubR * 0.7, 6), PAL.STEEL_ABYSS, 0.55);
}

function drawProfileValve(px, py, dx, dy, wheelR, isCopper = true) {
  // (dx, dy) is direction stem projects out from pipe center (px, py)
  let nx = -dy;
  let ny = dx;

  // Cast valve bonnet & packing nut on pipe
  let bLen = 36;
  let bW = 14;
  let bonnetPts = [
    [px + nx * bW, py + ny * bW],
    [px + dx * bLen + nx * bW * 0.7, py + dy * bLen + ny * bW * 0.7],
    [px + dx * bLen - nx * bW * 0.7, py + dy * bLen - ny * bW * 0.7],
    [px - nx * bW, py - ny * bW]
  ];
  solidPlane(bonnetPts, PAL.STEEL_SLATE, 245);
  penPoly(bonnetPts, PAL.STEEL_ABYSS, 0.6);

  // Threaded brass rising stem
  let sLen = 64;
  let sW = 5.5;
  let stemPts = [
    [px + dx * bLen + nx * sW, py + dy * bLen + ny * sW],
    [px + dx * sLen + nx * sW, py + dy * sLen + ny * sW],
    [px + dx * sLen - nx * sW, py + dy * sLen - ny * sW],
    [px + dx * bLen - nx * sW, py + dy * bLen - ny * sW]
  ];
  solidPlane(stemPts, PAL.COPPER_GOLD, 248);
  penPoly(stemPts, PAL.SIENNA_ABYSS, 0.5);

  // Foreshortened handwheel ellipse at end of stem
  let wx = px + dx * (sLen - 8);
  let wy = py + dy * (sLen - 8);
  let thick = 11;
  let wPts = [
    [wx - dx * thick * 0.5 + nx * wheelR, wy - dy * thick * 0.5 + ny * wheelR],
    [wx + dx * thick * 0.5 + nx * wheelR, wy + dy * thick * 0.5 + ny * wheelR],
    [wx + dx * thick * 0.5 - nx * wheelR, wy + dy * thick * 0.5 - ny * wheelR],
    [wx - dx * thick * 0.5 - nx * wheelR, wy - dy * thick * 0.5 - ny * wheelR]
  ];
  solidPlane(wPts, isCopper ? PAL.SIENNA_BURNT : PAL.STEEL_DARK, 248);

  // Highlight band on upper half of profile wheel
  let wHi = [
    [wx - dx * thick * 0.5 + nx * wheelR, wy - dy * thick * 0.5 + ny * wheelR],
    [wx + dx * thick * 0.5 + nx * wheelR, wy + dy * thick * 0.5 + ny * wheelR],
    [wx + dx * thick * 0.5 + nx * wheelR * 0.2, wy + dy * thick * 0.5 + ny * wheelR * 0.2],
    [wx - dx * thick * 0.5 + nx * wheelR * 0.2, wy - dy * thick * 0.5 + ny * wheelR * 0.2]
  ];
  solidPlane(wHi, isCopper ? PAL.COPPER_GLEAM : PAL.STEEL_GLEAM, 245);
  penPoly(wPts, PAL.STEEL_ABYSS, 0.65);
}

function drawPressureGauge(cx, cy, r, mountX, mountY, needleAngle, labelText) {
  // 1. Brass siphon stem & hex union connecting gauge to pipe at (mountX, mountY)
  penLine(cx, cy, mountX, mountY, PAL.STEEL_ABYSS, 6.5, "rotring");
  penLine(cx, cy, mountX, mountY, PAL.COPPER_GOLD, 4.2, "cpencil");
  solidPlane(rectPts((cx + mountX) * 0.5 - 7, (cy + mountY) * 0.5 - 7, 14, 14), PAL.COPPER_BRIGHT, 245);
  penPoly(rectPts((cx + mountX) * 0.5 - 7, (cy + mountY) * 0.5 - 7, 14, 14), PAL.SIENNA_ABYSS, 0.55);

  // 2. Crisp 3D cylindrical casing & cast shadow (shifted down-right)
  solidPlane(ellipsePts(cx + 8, cy + 10, r + 3, r + 3, 28), PAL.STEEL_ABYSS, 215);
  solidPlane(ellipsePts(cx + 4, cy + 5, r + 1, r + 1, 28), PAL.STEEL_DEEP, 248);
  penPoly(ellipsePts(cx + 4, cy + 5, r + 1, r + 1, 28), PAL.STEEL_ABYSS, 0.65);

  // 3. Brushed Stainless Stepped Bezel (8 geometric reflection sectors)
  let rOuter = r;
  let rInner = r * 0.80;
  let bezelSectors = [
    [0, 45, PAL.STEEL_SLATE],
    [45, 105, PAL.STEEL_DEEP],
    [105, 165, PAL.STEEL_MID],
    [165, 205, PAL.STEEL_GLEAM],
    [205, 245, PAL.STEEL_SPEC],
    [245, 285, PAL.STEEL_LIGHT],
    [285, 325, PAL.REF_COPPER_STEEL],
    [325, 360, PAL.STEEL_DARK]
  ];
  for (let s of bezelSectors) {
    solidPlane(ringSectorPts(cx, cy, rOuter, rOuter, rInner, rInner, s[0], s[1], 5), s[2], 250);
  }
  penPoly(ellipsePts(cx, cy, rOuter, rOuter, 32), PAL.STEEL_ABYSS, 0.8);
  penPoly(ellipsePts(cx, cy, (rOuter + rInner) * 0.5, (rOuter + rInner) * 0.5, 28), PAL.STEEL_DARK, 0.35);

  // 4. Inner Recessed Brass Rim & Clean Ivory Dial Face
  solidPlane(ellipsePts(cx, cy, rInner, rInner, 28), PAL.COPPER_POLISH, 245);
  let rFace = r * 0.75;
  solidPlane(ellipsePts(cx, cy, rFace, rFace, 28), PAL.IVORY_LIT, 252);

  // Crescent inner shadow at top-left of dial face cast by deep bezel
  let innerSh = [];
  for (let a = 135; a <= 315; a += 15) {
    innerSh.push([cx + cos(a) * rFace, cy + sin(a) * rFace]);
  }
  for (let a = 315; a >= 135; a -= 15) {
    innerSh.push([cx + cos(a) * (rFace * 0.84) + 3, cy + sin(a) * (rFace * 0.84) + 3]);
  }
  solidPlane(innerSh, PAL.IVORY_COOL, 225);

  // 5. High-Pressure Burnt Sienna Warning Arc (from +15° to +135°)
  solidPlane(ringSectorPts(cx, cy, rFace * 0.84, rFace * 0.84, rFace * 0.72, rFace * 0.72, -15, 55, 6), PAL.SIENNA_LIGHT, 235);

  // 6. Razor-Sharp Radial Calibration Ticks around 270° scale (from 135° to 405°)
  let numTicks = 24;
  for (let i = 0; i <= numTicks; i++) {
    let a = lerp(135, 405, i / numTicks);
    let isMajor = (i % 4 === 0);
    let rT1 = rFace * 0.86;
    let rT2 = rFace * (isMajor ? 0.64 : 0.74);
    penLine(
      cx + cos(a) * rT1, cy + sin(a) * rT1,
      cx + cos(a) * rT2, cy + sin(a) * rT2,
      PAL.STEEL_ABYSS, isMajor ? 0.65 : 0.35, "rotring"
    );
  }

  // Tiny industrial sub-dial & typography blocks on dial face
  penLine(cx - rFace * 0.22, cy + rFace * 0.38, cx + rFace * 0.22, cy + rFace * 0.38, PAL.STEEL_ABYSS, 0.55);
  penLine(cx - rFace * 0.15, cy + rFace * 0.48, cx + rFace * 0.15, cy + rFace * 0.48, PAL.SIENNA_BURNT, 0.45);

  // 7. Tapered Precision Black Indicator Needle & Counterweight Tail
  let na = needleAngle;
  let ca = cos(na), sa = sin(na);
  let nx = -sa, ny = ca;
  let needlePts = [
    [cx + ca * (rFace * 0.78), cy + sa * (rFace * 0.78)],
    [cx - ca * (rFace * 0.26) + nx * 2.6, cy - sa * (rFace * 0.26) + ny * 2.6],
    [cx - ca * (rFace * 0.32), cy - sa * (rFace * 0.32)],
    [cx - ca * (rFace * 0.26) - nx * 2.6, cy - sa * (rFace * 0.26) - ny * 2.6]
  ];
  // Subtle needle shadow on ivory face
  let needleSh = needlePts.map(p => [p[0] + 1.8, p[1] + 2.2]);
  solidPlane(needleSh, PAL.IVORY_COOL, 210);
  solidPlane(needlePts, PAL.STEEL_ABYSS, 252);
  penPoly(needlePts, PAL.STEEL_ABYSS, 0.45);

  // Central brass pivot pin
  solidPlane(ellipsePts(cx, cy, 4.5, 4.5, 10), PAL.COPPER_GOLD, 250);
  penPoly(ellipsePts(cx, cy, 4.5, 4.5, 10), PAL.STEEL_ABYSS, 0.5);

  // 8. Crisp Geometric Diagonal Glass Reflection Slash across Gauge Lens
  let gSlash1 = [
    [cx - rFace * 0.65, cy - rFace * 0.20],
    [cx - rFace * 0.20, cy - rFace * 0.65],
    [cx + rFace * 0.55, cy + rFace * 0.10],
    [cx + rFace * 0.10, cy + rFace * 0.55]
  ];
  let gSlash2 = [
    [cx - rFace * 0.42, cy - rFace * 0.45],
    [cx - rFace * 0.26, cy - rFace * 0.61],
    [cx + rFace * 0.48, cy + rFace * 0.13],
    [cx + rFace * 0.32, cy + rFace * 0.29]
  ];
  solidPlane(gSlash1, PAL.SKY_ICE, 115);
  solidPlane(gSlash2, PAL.SKY_SPEC, 185);

  penPoly(ellipsePts(cx, cy, rInner, rInner, 28), PAL.STEEL_ABYSS, 0.65);
  penPoly(ellipsePts(cx, cy, rFace, rFace, 28), PAL.STEEL_ABYSS, 0.55);
}

