function populatePipeCondensation(xMin, xMax, yMin, yMax, count, isCopper = false) {
  for (let i = 0; i < count; i++) {
    let bx = random(xMin, xMax);
    let by = random(yMin, yMax);
    let br = random(1.8, 4.4);

    // Occasional vertical condensation trickle trail above larger droplets
    if (br > 3.4 && random() < 0.45) {
      let trailLen = random(14, 38);
      let trCol = isCopper ? PAL.COPPER_GLEAM : PAL.STEEL_GLEAM;
      let shCol = isCopper ? PAL.SIENNA_DARK : PAL.STEEL_DARK;
      penLine(bx - 0.6, by - trailLen, bx - 0.6, by, trCol, 0.4, "cpencil");
      penLine(bx + 0.6, by - trailLen, bx + 0.6, by, shCol, 0.35, "2H");
    }

    drawCondensationBead(bx, by, br, isCopper);
  }
}

function drawCondensationBead(x, y, r, isCopper = false) {
  // 1. Tiny dark cast shadow immediately below the droplet
  let shCol = isCopper ? PAL.SIENNA_ABYSS : PAL.STEEL_ABYSS;
  let refractCol = isCopper ? PAL.SIENNA_DARK : PAL.STEEL_DEEP;
  let bellyCol = isCopper ? PAL.COPPER_GOLD : PAL.SKY_ICE;

  solidPlane(ellipsePts(x + r * 0.22, y + r * 0.72, r * 0.85, r * 0.65, 6), shCol, 225);

  // 2. Dark upper refraction hemisphere
  solidPlane(ellipsePts(x, y, r, r * 1.12, 8), refractCol, 240);

  // 3. Luminous lower-right internal lens reflection crescent
  solidPlane(ellipsePts(x + r * 0.18, y + r * 0.25, r * 0.68, r * 0.68, 6), bellyCol, 245);

  // 4. Pinpoint pure white north-light specular dot on upper-left
  solidPlane(ellipsePts(x - r * 0.32, y - r * 0.35, max(1.1, r * 0.36), max(1.1, r * 0.36), 5), PAL.SKY_SPEC, 255);

  // 5. Micro contour
  penPoly(ellipsePts(x, y, r, r * 1.12, 8), shCol, 0.28, true);
}

