async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);

  // Custom square watercolor-dab brush for mosaic tesserae
  brush.add("tessera", {
    type: "custom",
    weight: 3.2,
    scatter: 0.08,
    opacity: 165,
    spacing: 0.9,
    pressure: [0.95, 1.0, 0.95],
    tip: (_m) => {
      _m.rect(-1.8, -1.8, 3.6, 3.6);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.2
  });

  // Ultra-fine needle/bristle brush for photographic stubble, pores, and eye rims
  brush.add("micro_hair", {
    type: "default",
    weight: 0.28,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.85,
    opacity: 210,
    spacing: 0.35,
    pressure: [0.4, 1.0, 0.15],
    rotate: "natural",
    noise: 0.15
  });

  // Board-form rough charcoal plank brush
  brush.add("board_grain", {
    type: "default",
    weight: 1.6,
    scatter: 0.65,
    sharpness: 0.35,
    grain: 0.92,
    opacity: 95,
    spacing: 0.5,
    pressure: [0.7, 1.1, 0.7],
    rotate: "natural",
    noise: 0.7
  });

  // Subtle horizontal steppe wind vector field
  brush.addField("steppe_wind", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.08;
        let ny = row * 0.08;
        field[col][row] = -4 + (noise(nx, ny) - 0.5) * 18;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // 1. Overcast Steppe Sky & Distant Horizon
  drawSteppeSkyAndRoad();

  // 2. Brutalist Cantilevered Bus Shelter Base & Structure
  drawShelterBaseStructure();

  // 3. The Vast Cosmonaut Mosaic (Watercolor Under-washes + Tesserae + Grout + Chips)
  drawCosmonautMosaic();

  // 4. Cantilevered Swooping Canopy, Board-Form Concrete Grain & Rebar Rust Bleeds
  drawCantileverCanopyAndRust();

  // 5. Brutalist Concrete Bench & Platform Details
  drawConcreteBench();

  // 6. The Elderly Man in Quilted Coat (Off-Centre Right, Hyperrealistic Focal Point)
  drawElderlyMan();

  // 7. Final Cold Chalky Atmospheric Grain & Foreground Steppe Weeds
  drawForegroundDetails();

  noLoop();
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

function polyShape(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

// Check if a point (x,y) is occluded by the seated old man on the right
// (used to skip mosaic tesserae directly behind his torso/head for speed & clean layering)
function isBehindManCore(x, y) {
  // Head core
  if (x > 780 && x < 852 && y > 548 && y < 665) return true;
  // Torso core
  if (x > 715 && x < 915 && y >= 665 && y < 860) return true;
  return false;
}

