function drawBoardFormConcrete(x1, y1, x2, y2, planks, isRightPier) {
  let h = y2 - y1;
  let plankH = h / planks;

  for (let i = 0; i < planks; i++) {
    let py = y1 + i * plankH;
    // Slight perspective tilt
    let tilt = isRightPier ? -12 : -6;

    // Plank seam line
    brush.set("2B", PAL.charcoalDark, 0.65);
    brush.line(x1, py, x2, py + tilt);

    // Wood grain lines inside each shuttering board
    brush.set("board_grain", i % 2 === 0 ? PAL.charcoalMid : PAL.concreteDark, 0.55);
    for (let g = 2; g < plankH - 1; g += 3.5) {
      let lx1 = x1 + random(0, 12);
      let lx2 = x2 - random(0, 12);
      brush.line(lx1, py + g, lx2, py + g + tilt);
    }

    // Occasional tie-rod form holes in the concrete
    if (i % 5 === 2) {
      let hx = lerp(x1, x2, 0.35);
      let hy = py + plankH * 0.5 + tilt * 0.35;
      brush.set("charcoal", PAL.soot, 0.9);
      brush.circle(hx, hy, 2.5, 0.3);
      // Rust or damp drip below tie-rod hole
      brush.set("2B", PAL.rustDark, 0.5);
      brush.line(hx, hy + 2, hx + random(-2, 2), hy + random(18, 42));
    }
  }
}

// =============================================================================
// 3. THE VAST COSMONAUT MOSAIC (3-STAGE RENDER: WASHES -> TESSERAE -> GROUT/CHIPS)
// =============================================================================

// Helper to determine the mosaic's designed color & tile angle at any wall coordinate (x, y)
function sampleCosmonautMosaic(x, y) {
  // Wall bounds: x in [290, 1038], y in [310, 835]
  // Check if this coordinate falls in a "chipped / fallen tesserae" damage zone
  let nChip = noise(x * 0.018, y * 0.018);
  let nFine = noise(x * 0.06, y * 0.06);

  // Diagonal structural crack from (505, 315) to (615, 830)
  let crackX = map(y, 315, 830, 505, 615) + (noise(y * 0.03) - 0.5) * 35;
  if (abs(x - crackX) < 12 + nFine * 18) {
    return { chipped: true, mortarDark: abs(x - crackX) < 6 };
  }

  // Secondary crack on right side above bench from (865, 300) to (820, 620)
  let crackX2 = map(y, 300, 620, 865, 820) + (noise(y * 0.04, 9) - 0.5) * 25;
  if (y < 620 && abs(x - crackX2) < 7 + nFine * 10) {
    return { chipped: true, mortarDark: abs(x - crackX2) < 3.5 };
  }

  // Heavy lower-wall water/frost spalling near the bench and corners
  if (y > 755 && nChip + (y - 755) * 0.006 > 0.62) {
    return { chipped: true, mortarDark: nFine > 0.55 };
  }
  // Upper-left weather erosion
  if (x < 375 && y < 440 && nChip + (375 - x) * 0.004 > 0.64) {
    return { chipped: true, mortarDark: nFine > 0.5 };
  }
  // Random small missing tile pockets across the wall
  if (nChip > 0.76 && nFine > 0.58) {
    return { chipped: true, mortarDark: false };
  }

  // --- COSMONAUT & COSMIC MOTIF GEOMETRY ---
  // Key focal points:
  // 1) Radiant Sputnik/Star held aloft at (395, 455)
  let sx = 395, sy = 455;
  let dStar = dist(x, y, sx, sy);
  let angStar = atan2(y - sy, x - sx);

  // 2) Cosmonaut Helmet centered at (615, 470), radius 106
  let hx = 615, hy = 470;
  let dHelm = dist(x, y, hx, hy);
  let angHelm = atan2(y - hy, x - hx);

  // 3) Ringed Planet / Saturn motif on upper right at (925, 420)
  let px = 925, py = 420;
  let dPlanet = dist(x, y, px, py);

  // Check 8-pointed Soviet Star / Sputnik at (395, 455)
  let starRay = abs(((angStar + 360) % 45) - 22.5);
  let starRadius = map(starRay, 0, 22.5, 16, 62);
  if (dStar < starRadius) {
    return {
      chipped: false,
      col: dStar < 22 ? PAL.chalkWarm : (nFine > 0.4 ? PAL.ochreLight : PAL.ochreMid),
      angle: angStar
    };
  }
  // Sputnik trailing antennas going down-left from star
  if (x < sx && y > sy && abs((y - sy) - (sx - x) * 0.85) < 14 && dStar < 145) {
    return { chipped: false, col: PAL.ochreLight, angle: -40 };
  }

  // Check Cosmonaut Visor (facing slightly left, inside helmet)
  let vx = (x - 585) / 68;
  let vy = (y - 472) / 46;
  if (vx * vx + vy * vy < 1.0 && x < 642) {
    // Diagonal solar glint across visor
    let glint = abs((x - 575) + (y - 465) * 0.7);
    if (glint < 13) {
      return { chipped: false, col: PAL.ochreLight, angle: -35 };
    } else if (glint < 24) {
      return { chipped: false, col: PAL.smaltChalk, angle: -35 };
    }
    return {
      chipped: false,
      col: vy < -0.2 ? PAL.smaltDeep : (vx < -0.2 ? PAL.smaltMid : PAL.smaltDeep),
      angle: angHelm + 90
    };
  }

  // Check Cosmonaut Helmet Dome
  if (dHelm < 106) {
    // Red "CCCP" / headband stripe near brow
    if (dHelm > 68 && dHelm < 88 && y < 448 && x > 535 && x < 675) {
      // Break into blocky letter-like segments
      let seg = floor((x - 535) / 16);
      let isLetter = seg % 2 === 0;
      return {
        chipped: false,
        col: isLetter ? PAL.brickMid : PAL.chalkWarm,
        angle: angHelm + 90
      };
    }
    // Helmet rim collar at bottom
    if (y > 542 && dHelm > 75) {
      return { chipped: false, col: PAL.brickMid, angle: 12 };
    }
    // Helmet shading planes (chalk white on left/top, warm ochre/slate on right)
    let helmCol = PAL.chalkWarm;
    if (x > 650) helmCol = dHelm > 82 ? PAL.concreteMid : PAL.ochreLight;
    else if (dHelm > 92) helmCol = PAL.concreteLight;
    return { chipped: false, col: helmCol, angle: angHelm + 90 };
  }

  // Helmet Halo / Acoustic Ring (radius 106..126)
  if (dHelm >= 106 && dHelm < 126) {
    return {
      chipped: false,
      col: (floor(angHelm / 12) % 2 === 0) ? PAL.ochreMid : PAL.brickLight,
      angle: angHelm
    };
  }

  // Raised Right Arm reaching from shoulder (530, 620) toward Star (415, 495)
  let armT = constrain(((x - 530) * (415 - 530) + (y - 620) * (495 - 620)) / (115 * 115 + 125 * 125), 0, 1);
  let armProjX = 530 + armT * (415 - 530);
  let armProjY = 620 + armT * (495 - 620);
  let dArm = dist(x, y, armProjX, armProjY);
  if (dArm < 38 && armT > 0.05 && armT < 0.95) {
    // Ribbed spacesuit sleeve segments
    let rib = floor(armT * 10) % 2 === 0;
    return {
      chipped: false,
      col: dArm > 24 ? PAL.brickDeep : (rib ? PAL.brickMid : PAL.ochreMid),
      angle: -42
    };
  }

  // Cosmonaut Heroic Torso & Shoulders (trapezoid/arch from y = 560 to 835, x = 455 to 790)
  if (y >= 555 && y <= 835) {
    let halfW = map(y, 555, 835, 130, 195);
    let centerX = 625;
    if (abs(x - centerX) < halfW) {
      // Geometric chest emblem / control pack in center (560..675, 620..745)
      if (x > 565 && x < 675 && y > 625 && y < 745) {
        let inBorder = x < 580 || x > 660 || y < 640 || y > 730;
        return {
          chipped: false,
          col: inBorder ? PAL.ochreMid : ( (x + y) % 28 < 14 ? PAL.smaltMid : PAL.chalkWarm ),
          angle: 0
        };
      }
      // Diagonal Soviet sash/ribbing across suit
      let suitDiag = (x - centerX) + (y - 650) * 0.45;
      if (abs(suitDiag) < 35) {
        return { chipped: false, col: PAL.chalkWarm, angle: 65 };
      }
      // Left lit shoulder vs right shadowed shoulder
      if (x < centerX) {
        return {
          chipped: false,
          col: (y % 36 < 10) ? PAL.ochreMid : PAL.brickLight,
          angle: 25
        };
      } else {
        return {
          chipped: false,
          col: (y % 36 < 10) ? PAL.brickDeep : PAL.brickMid,
          angle: -25
        };
      }
    }
  }

  // Saturn / Ringed Planet on upper right (925, 420)
  // Tilted ring check
  let rx = (x - px) * cos(28) + (y - py) * sin(28);
  let ry = -(x - px) * sin(28) + (y - py) * cos(28);
  let ringEll = (rx * rx) / (82 * 82) + (ry * ry) / (20 * 20);
  if (ringEll > 0.55 && ringEll < 1.05) {
    return { chipped: false, col: PAL.ochreLight, angle: -28 };
  }
  if (dPlanet < 38) {
    return {
      chipped: false,
      col: rx < 0 ? PAL.brickLight : PAL.brickDeep,
      angle: atan2(y - py, x - px) + 90
    };
  }

  // Sweeping Parabolic Cosmic Orbits & Red Banner Waves across the background
  // Orbit 1: diagonal band sweeping from (310, 740) through (880, 320)
  let orb1 = (y - 740) - ((320 - 740) / (880 - 310)) * (x - 310) + sin(x * 0.4) * 22;
  if (abs(orb1) < 28) {
    return { chipped: false, col: PAL.chalkWarm, angle: -36 };
  }
  if (orb1 >= 28 && orb1 < 72 && x > 720) {
    // Heroic red banner streaming behind the cosmonaut on the right
    return {
      chipped: false,
      col: orb1 < 50 ? PAL.brickMid : PAL.brickDeep,
      angle: -32
    };
  }

  // Concentric solar rays & cosmic arcs radiating from the Sputnik star (395, 455)
  let raySector = floor(((angStar + 360) % 360) / 18);
  if (dStar < 360 && raySector % 3 === 0) {
    return {
      chipped: false,
      col: dStar < 210 ? PAL.ochreMid : PAL.smaltLight,
      angle: angStar
    };
  }

  // Default Deep Smalt Blue Cosmic Field (varied smalt tesserae tones)
  let smaltBand = floor(dStar / 42) % 3;
  let smaltCol = smaltBand === 0 ? PAL.smaltDeep : (smaltBand === 1 ? PAL.smaltMid : PAL.smaltLight);
  if (nFine > 0.68) smaltCol = PAL.smaltChalk;
  return {
    chipped: false,
    col: smaltCol,
    angle: angStar + 90
  };
}

function drawCosmonautMosaic() {
  // -------------------------------------------------------------------------
  // STAGE A: Batched Watercolor Under-Washes (creates soft pigment bleed)
  // -------------------------------------------------------------------------
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.65, 0.4);

  // Batch 1: Smalt Blue cosmic background zones
  brush.fill(PAL.smaltDeep, 130);
  polyShape([[292, 325], [780, 305], [520, 620], [292, 590]], 0);
  polyShape([[740, 305], [1038, 292], [1038, 690], [760, 650]], 0);

  brush.fill(PAL.smaltMid, 115);
  polyShape([[295, 480], [620, 320], [920, 560], [295, 760]], 0);
  // Visor wash
  polyShape([[540, 440], [640, 435], [640, 510], [540, 505]], 0.3);

  // Batch 2: Brick Red suit, banner, and planet washes
  brush.fill(PAL.brickMid, 135);
  // Cosmonaut suit torso
  polyShape([[480, 565], [765, 565], [805, 830], [445, 830]], 0);
  // Streaming banner on right
  polyShape([[730, 450], [1035, 315], [1035, 460], [750, 560]], 0);
  // Raised arm
  polyShape([[405, 485], [445, 460], [560, 590], [510, 625]], 0);

  // Batch 3: Ochre solar rays, halo, and star
  brush.fill(PAL.ochreMid, 130);
  brush.circle(395, 455, 58, 0.2);
  brush.circle(615, 470, 122, 0.15);
  brush.circle(925, 420, 44, 0.2);

  // Batch 4: Chalk white helmet dome & orbital arc
  brush.fill(PAL.chalkWarm, 150);
  brush.circle(615, 470, 98, 0.15);

  brush.noFill();

  // -------------------------------------------------------------------------
  // STAGE B: Individual Square Watercolour Tesserae Dabs + Chipped Plaster
  // -------------------------------------------------------------------------
  let stepX = 10.5;
  let stepY = 10.5;

  for (let y = 302; y <= 832; y += stepY) {
    // Respect perspective top and bottom edges of the mosaic wall
    let topEdge = map(y, 302, 832, 322, 294);
    for (let x = 294; x <= 1035; x += stepX) {
      let wallTopY = map(x, 294, 1035, 324, 294);
      let wallBotY = map(x, 294, 1035, 825, 842);
      if (y < wallTopY || y > wallBotY) continue;

      // Skip tiles completely hidden behind the core of the seated man
      if (isBehindManCore(x, y)) continue;

      let jx = x + random(-1.2, 1.2);
      let jy = y + random(-1.2, 1.2);
      let sample = sampleCosmonautMosaic(jx, jy);

      if (sample.chipped) {
        // Exposed raw concrete/mortar bed with diamond scratch-coat marks
        if (sample.mortarDark && random() < 0.65) {
          brush.set("charcoal", PAL.charcoalDark, 0.55);
          brush.line(jx - 3, jy - 2, jx + 3, jy + 2);
        } else if (random() < 0.45) {
          brush.set("2B", PAL.concreteDark, 0.45);
          brush.line(jx - 3, jy + 3, jx + 3, jy - 3);
        }
      } else {
        // Draw square watercolour tessera dab
        let wMult = random(0.82, 1.08);
        brush.set("tessera", sample.col, wMult);
        // Short 2px stroke creates a square dab with slight handmade irregularity
        let a = sample.angle;
        brush.line(jx - 0.8, jy - 0.4, jx + 0.8, jy + 0.4);

        // Occasional chipped corner or bright glaze reflection on smalt/ochre tesserae
        let r = random();
        if (r < 0.08) {
          brush.set("2H", PAL.chalk, 0.45);
          brush.line(jx - 2, jy - 2, jx + 1, jy - 2);
        } else if (r > 0.93) {
          brush.set("2B", PAL.charcoalMid, 0.4);
          brush.line(jx - 2, jy + 2, jx + 2, jy + 2);
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // STAGE C: Grey Grout Lines, Structural Cracks & Chipped Edge Shadows
  // -------------------------------------------------------------------------
  // Horizontal grey grout lines
  brush.set("2H", PAL.concreteLight, 0.35);
  for (let y = 305; y <= 832; y += stepY) {
    let xStart = 294;
    for (let x = 294; x <= 1030; x += 32) {
      let wallTopY = map(x, 294, 1035, 324, 294);
      let wallBotY = map(x, 294, 1035, 825, 842);
      if (y > wallTopY && y < wallBotY && !isBehindManCore(x, y)) {
        brush.line(x, y, x + 26, y + random(-0.6, 0.6));
      }
    }
  }

  // Vertical grey grout lines
  for (let x = 294; x <= 1035; x += stepX) {
    let wallTopY = map(x, 294, 1035, 324, 294);
    let wallBotY = map(x, 294, 1035, 825, 842);
    for (let y = wallTopY; y < wallBotY - 25; y += 34) {
      if (!isBehindManCore(x, y)) {
        brush.line(x + random(-0.5, 0.5), y, x, y + 26);
      }
    }
  }

  // Deep structural crack line & lime efflorescence drips
  brush.set("charcoal", PAL.soot, 0.7);
  let prevCX = 505, prevCY = 318;
  for (let y = 335; y <= 825; y += 22) {
    let cx = map(y, 315, 830, 505, 615) + (noise(y * 0.03) - 0.5) * 35;
    brush.line(prevCX, prevCY, cx, y);
    // White chalky efflorescence bleed alongside the crack
    brush.set("2H", PAL.chalk, 0.55);
    brush.line(cx + 4, prevCY + 4, cx + 3, y + 6);
    brush.set("charcoal", PAL.soot, 0.7);
    prevCX = cx;
    prevCY = y;
  }
}

// =============================================================================
// 4. SWOOPING CANTILEVERED CANOPY, SOFFIT COFFERS & REBAR RUST BLEEDS
// =============================================================================

function drawCantileverCanopyAndRust() {
  // Define the swooping curves of the brutalist cantilevered roof
  // Top roof edge: from left prow (105, 165) sweeping up to right pier (1145, 72)
  // Bottom fascia edge: from left prow (122, 242) sweeping to right pier (1135, 185)
  // Back soffit junction with mosaic wall: from (285, 324) to (1045, 292)

  let topPts = [];
  let botFasciaPts = [];
  let soffitBackPts = [];
  let steps = 24;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Parabolic swoop for dramatic Soviet modernist profile
    let swoop = sin(t * 180) * 28 - pow(1 - t, 2.2) * 18;
    let tx = lerp(105, 1145, t);
    let ty = lerp(162, 72, t) - swoop;
    topPts.push([tx, ty]);

    let bx = lerp(124, 1135, t);
    let by = lerp(244, 182, t) - swoop * 0.65;
    botFasciaPts.push([bx, by]);
  }

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sx = lerp(260, 1045, t);
    let sy = lerp(322, 292, t);
    soffitBackPts.push([sx, sy]);
  }

  // 1. Wash & Fill for the Under-Canopy Soffit (in deep overcast shade)
  brush.noStroke();
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.7, 0.45);

  let soffitPoly = [...botFasciaPts, ...soffitBackPts.slice().reverse()];
  brush.fill(PAL.concreteDark, 185);
  polyShape(soffitPoly, 0);

  // Deeper shadow band where soffit meets the mosaic wall
  brush.fill(PAL.charcoalDark, 145);
  polyShape([
    botFasciaPts[4],
    botFasciaPts[20],
    [1045, 292],
    [260, 322]
  ], 0);

  // 2. Wash & Fill for the Front Swooping Fascia Beam
  let fasciaPoly = [...topPts, ...botFasciaPts.slice().reverse()];
  brush.fill(PAL.concreteLight, 175);
  polyShape(fasciaPoly, 0);

  // Weathering darker stain along upper lip and left cantilevered prow
  brush.fill(PAL.concreteMid, 125);
  polyShape([
    topPts[0], topPts[8], botFasciaPts[6], botFasciaPts[0]
  ], 0);

  // 3. Rebar Rust Bleeds (watercolour bleeds dripping from exposed rebar pockets)
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.75, 0.3);
  let rustSites = [
    { x: 185, y: 215, w: 18, h: 32 },
    { x: 355, y: 185, w: 24, h: 48 },
    { x: 590, y: 158, w: 20, h: 52 },
    { x: 845, y: 142, w: 28, h: 58 },
    { x: 1055, y: 210, w: 22, h: 85 },
    { x: 272, y: 420, w: 16, h: 95 },
    { x: 1068, y: 490, w: 20, h: 110 }
  ];

  // Batch rust washes
  brush.fill(PAL.rustWash, 115);
  for (let r of rustSites) {
    polyShape([
      [r.x - r.w * 0.4, r.y],
      [r.x + r.w * 0.4, r.y],
      [r.x + r.w * 0.7, r.y + r.h],
      [r.x - r.w * 0.5, r.y + r.h * 0.9]
    ], 0.2);
  }
  brush.fill(PAL.rustMid, 130);
  for (let r of rustSites) {
    polyShape([
      [r.x - r.w * 0.2, r.y],
      [r.x + r.w * 0.2, r.y],
      [r.x + r.w * 0.3, r.y + r.h * 0.65],
      [r.x - r.w * 0.25, r.y + r.h * 0.6]
    ], 0.2);
  }
  brush.noFill();

  // 4. Layered Charcoal Hatching & Board-Form Shuttering on the Fascia & Soffit
  // Coffer ribs under the soffit
  for (let i = 0; i <= steps; i++) {
    let pFront = botFasciaPts[i];
    let pBack = soffitBackPts[i];

    // Heavy concrete coffer rib every 2 steps
    if (i % 2 === 0) {
      brush.set("charcoal", PAL.charcoalDark, 1.1);
      brush.line(pFront[0], pFront[1], pBack[0], pBack[1]);
      brush.set("2H", PAL.concreteLight, 0.5);
      brush.line(pFront[0] + 3, pFront[1], pBack[0] + 3, pBack[1]);
    }

    // Board-form planks spanning between soffit ribs
    if (i < steps) {
      let nextFront = botFasciaPts[i + 1];
      let nextBack = soffitBackPts[i + 1];
      brush.set("board_grain", PAL.charcoalDark, 0.65);
      for (let s = 0.12; s < 0.95; s += 0.14) {
        let a = lerpPt(pFront, pBack, s);
        let b = lerpPt(nextFront, nextBack, s);
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }
  }

  // Sweeping board-form timber lines along the main cantilevered fascia
  for (let s = 0; s <= 1.0; s += 0.09) {
    let isSeam = abs((s * 100) % 27) < 9;
    brush.set(isSeam ? "2B" : "board_grain", isSeam ? PAL.charcoalDark : PAL.concreteDark, isSeam ? 0.65 : 0.55);
    for (let i = 0; i < steps; i++) {
      let a = lerpPt(topPts[i], botFasciaPts[i], s);
      let b = lerpPt(topPts[i + 1], botFasciaPts[i + 1], s);
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }

  // Crisp brutalist top & bottom contour lines of the canopy
  brush.set("charcoal", PAL.charcoalDark, 0.95);
  brush.spline(topPts, 0.3);
  brush.spline(botFasciaPts, 0.3);

  // 5. Exposed Corroded Rebar Rods & Spalled Concrete Pockets
  for (let r of rustSites) {
    // Dark spalled concrete cavity
    brush.set("charcoal", PAL.soot, 1.1);
    brush.line(r.x - 9, r.y + 2, r.x + 9, r.y - 1);
    brush.line(r.x - 6, r.y + 5, r.x + 7, r.y + 4);

    // Exposed rusted steel rebar rod & vertical rust streaks
    brush.set("rotring", PAL.rustDark, 0.9);
    brush.line(r.x - 11, r.y + 2, r.x + 11, r.y);
    brush.line(r.x - 2, r.y - 4, r.x - 2, r.y + 12);

    // Fine rust bleed streaks running down into the concrete grain
    brush.set("2H", PAL.rustMid, 0.45);
    for (let k = -4; k <= 4; k += 2) {
      brush.line(r.x + k, r.y + 4, r.x + k + random(-3, 3), r.y + r.h * random(0.6, 1.15));
    }
  }
}

