  brush.line(310, 890, 1020, 914);
  brush.line(328, 814, 1005, 834);
  brush.line(328, 830, 1005, 850);

  // Timber/concrete slat joints along the bench seat
  brush.set("board_grain", PAL.charcoalMid, 0.55);
  for (let s = 0.25; s < 0.9; s += 0.25) {
    let yL = lerp(858, 872, s);
    let yR = lerp(878, 894, s);
    brush.line(315, yL, 1018, yR);
  }

  // Concrete leg outlines and shadow hatching under bench
  brush.hatchStyle("charcoal", PAL.soot, 0.65);
