  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.68, 0.45);

  // Main coat silhouette (padded hunched shoulders, sleeves converging to lap)
  brush.fill(PAL.charcoalMid, 215);
  polyShape([
    [762, 635], [868, 635], // upturned collar
    [912, 668], [932, 745], [922, 838], [898, 895], // right shoulder & sleeve
    [815, 912], [728, 892], // lower hem over lap
    [704, 832], [698, 742], [718, 665]  // left shoulder & sleeve
  ], 0.15);

  // Lit top planes of hunched shoulders and upper sleeves (flat overcast sky light from above)
  brush.fill(PAL.concreteMid, 130);
  polyShape([[718, 665], [770, 645], [765, 725], [702, 735]], 0.2);
  polyShape([[860, 645], [912, 668], [928, 738], [862, 725]], 0.2);

  // Deep shadow inside collar, under arms, and beneath overlapping coat front
  brush.fill(PAL.soot, 175);
  polyShape([[768, 640], [862, 640], [848, 715], [782, 715]], 0.15);
  polyShape([[748, 745], [775, 835], [742, 855], [735, 755]], 0.15);
  polyShape([[882, 745], [892, 850], [855, 835], [868, 750]], 0.15);
  brush.noFill();

  // Render the hyper-realistic DIAMOND & RIBBED QUILTING across the torso and sleeves
  drawQuiltedCoatTexture();

  // -------------------------------------------------------------------------
  // C. CLASPED WEATHERED HANDS IN LAP (x = 772..858, y = 835..892)
  // -------------------------------------------------------------------------
  drawClaspedHands();

  // -------------------------------------------------------------------------
  // D. THE PORTRAIT HEAD: USHANKA, WATERY EYES & STUBBLE (x = 770..860, y = 538..668)
  // -------------------------------------------------------------------------
  drawHyperrealHead();
}

function drawQuiltedCoatTexture() {
  // High padded collar around neck
  brush.set("charcoal", PAL.soot, 0.85);
  brush.spline([[758, 636], [768, 692], [812, 725], [862, 690], [870, 636]], 0.3);

  // Collar vertical quilting ribs
  for (let x = 762; x <= 866; x += 9) {
    if (x > 780 && x < 848) continue; // neck opening
    brush.set("2B", PAL.charcoalDark, 0.55);
    brush.line(x, 638, x + (x < 815 ? 4 : -4), 688);
    brush.set("2H", PAL.concreteLight, 0.45);
    brush.line(x + 3, 640, x + 3 + (x < 815 ? 4 : -4), 685);
  }

  // Wool scarf tucked inside collar
  brush.set("charcoal", PAL.concreteDark, 0.7);
  for (let y = 665; y <= 715; y += 5) {
    brush.line(784, y, 844, y + 4);
  }

  // Torso diamond/vertical quilting grid (left breast panel & right breast panel overlapping)
  // Center coat placket seam with worn buttons
  brush.set("charcoal", PAL.soot, 0.9);
  brush.spline([[812, 718], [808, 780], [806, 840]], 0.2);
  brush.set("2H", PAL.concreteLight, 0.55);
  brush.spline([[815, 718], [811, 780], [809, 840]], 0.2);

  // Coat buttons along placket
  let btnYs = [738, 776, 814];
  for (let by of btnYs) {
    brush.set("rotring", PAL.soot, 0.85);
    brush.circle(818, by, 4.5, 0.15);
    brush.set("2H", PAL.chalk, 0.45);
    brush.arc(818, by, 4.2, -140, 20);
    // Two buttonholes thread mark
    brush.set("rotring", PAL.concreteLight, 0.5);
    brush.line(816, by - 1, 820, by + 1);
  }

  // Quilted cells on torso panels (x = 740..885, y = 680..845)
  let rowH = 16;
  let colW = 15;
  for (let y = 678; y <= 838; y += rowH) {
    for (let x = 742; x <= 882; x += colW) {
      // Skip neck opening
      if (y < 712 && x > 776 && x < 852) continue;

      let cx = x + ((floor(y / rowH) % 2) * (colW * 0.5));
      let cy = y;

      // Diamond stitch seam lines (dark recessed thread trough)
      brush.set("HB", PAL.soot, 0.55);
      brush.line(cx, cy - rowH * 0.5, cx + colW * 0.5, cy);
      brush.line(cx + colW * 0.5, cy, cx, cy + rowH * 0.5);
      brush.line(cx, cy + rowH * 0.5, cx - colW * 0.5, cy);
      brush.line(cx - colW * 0.5, cy, cx, cy - rowH * 0.5);

      // Puffy highlight in upper half of each quilted diamond cell
      brush.set("2H", PAL.concreteLight, 0.5);
      brush.line(cx - 3, cy - 3, cx + 3, cy - 2);
      brush.line(cx - 2, cy - 5, cx + 2, cy - 4);

      // Lower crescent shadow inside each puffy diamond
      brush.set("2B", PAL.charcoalDark, 0.5);
      brush.line(cx - 3, cy + 3, cx + 3, cy + 3);
    }
  }

  // Left Sleeve & Right Sleeve curved quilting & heavy elbow folds
  // Left sleeve path: from shoulder (720, 675) down to elbow (708, 795) to cuff (775, 862)
  // Right sleeve path: from shoulder (908, 678) down to elbow (920, 798) to cuff (852, 864)
  for (let side = -1; side <= 1; side += 2) {
    let isLeft = side === -1;
    let shX = isLeft ? 726 : 902;
    let elbX = isLeft ? 712 : 916;
    let cuffX = isLeft ? 772 : 856;

    // Outer & inner sleeve contours
    brush.set("charcoal", PAL.soot, 0.9);
    if (isLeft) {
      brush.spline([[758, 650], [712, 672], [698, 755], [706, 838], [768, 882]], 0.35);
      brush.spline([[748, 735], [742, 815], [782, 845]], 0.35);
    } else {
      brush.spline([[870, 650], [916, 675], [930, 758], [922, 840], [860, 884]], 0.35);
      brush.spline([[880, 735], [886, 815], [846, 845]], 0.35);
    }

    // Transverse quilted rings & compression folds along sleeve
    for (let t = 0.08; t <= 0.94; t += 0.085) {
      let sx, sy;
      if (t < 0.55) {
        let u = t / 0.55;
        sx = lerp(shX, elbX, u);
        sy = lerp(675, 798, u);
      } else {
        let u = (t - 0.55) / 0.45;
        sx = lerp(elbX, cuffX, u);
        sy = lerp(798, 862, u);
      }
      let w = map(abs(t - 0.5), 0, 0.5, 26, 20);
      let ang = t < 0.55 ? (isLeft ? 12 : -12) : (isLeft ? -38 : 38);
      let dx = cos(ang) * w;
      let dy = sin(ang) * w;

      // Stitch trough / fold shadow
      brush.set("2B", PAL.soot, 0.7);
      brush.spline([
        [sx - dx, sy - dy],
        [sx, sy + 5],
        [sx + dx, sy + dy]
      ], 0.4);

      // Padded ridge highlight just above the trough
      brush.set("2H", PAL.concreteLight, 0.55);
      brush.spline([
        [sx - dx * 0.85, sy - dy - 4],
        [sx, sy + 1],
        [sx + dx * 0.85, sy + dy - 4]
      ], 0.4);
    }
  }
}

function drawClaspedHands() {
  // Positioned at x = 772..858, y = 838..892 between the cuffs
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.45, 0.3);

  // Base skin wash for the two clasped, weathered hands
  brush.fill(PAL.skinMid, 210);
  polyShape([
    [774, 845], [814, 838], [854, 846],
    [858, 878], [815, 892], [772, 878]
  ], 0.25);

  // Cold reddish knuckle warmth & deep shadow between interlaced fingers
  brush.fill(PAL.skinColdRed, 115);
  polyShape([[785, 848], [845, 848], [842, 872], [788, 872]], 0.2);

  brush.fill(PAL.skinDeep, 165);
  polyShape([[776, 870], [852, 870], [835, 892], [792, 892]], 0.2);
  brush.noFill();

  // Dark padded cuffs framing the wrists
  brush.set("charcoal", PAL.soot, 1.0);
  brush.spline([[766, 842], [782, 858], [770, 882]], 0.3);
  brush.spline([[862, 842], [846, 858], [858, 882]], 0.3);

  // Interlaced gnarled fingers, knuckles, tendons, and fingernails
  let fingerYs = [849, 860, 871, 881];
  for (let i = 0; i < fingerYs.length; i++) {
    let fy = fingerYs[i];
    let xL = 784 + i * 2;
    let xR = 844 - i * 2;

    // Upper lit edge of each finger
    brush.set("2H", PAL.skinPale, 0.65);
    brush.spline([[xL, fy - 2], [814, fy - 4], [xR, fy - 1]], 0.35);

    // Swollen arthritic knuckle highlight
    brush.set("2H", PAL.chalkWarm, 0.55);
    brush.circle(798 + (i % 2) * 6, fy - 1, 3.2, 0.2);
    brush.circle(830 - (i % 2) * 6, fy - 1, 3.2, 0.2);

    // Deep crease between fingers
    brush.set("rotring", PAL.skinDeep, 0.55);
    brush.spline([[xL - 2, fy + 3], [814, fy + 2], [xR + 2, fy + 4]], 0.35);

    // Pale fingernail on tips
    let nx = i % 2 === 0 ? xR - 4 : xL + 4;
    brush.set("micro_hair", PAL.chalk, 0.7);
    brush.line(nx - 2, fy - 1, nx + 2, fy - 1);
    brush.set("micro_hair", PAL.skinDeep, 0.65);
    brush.line(nx - 2, fy + 1, nx + 2, fy + 1);
  }

  // Prominent veins and wrinkled skin creases on back of hands
  brush.set("micro_hair", PAL.skinShadow, 0.75);
  brush.line(780, 852, 798, 848);
  brush.line(778, 862, 796, 858);
  brush.line(848, 854, 830, 849);
  brush.line(850, 864, 832, 860);
}

// =============================================================================
// HYPERREALISTIC PORTRAIT HEAD (USHANKA, WATERY EYES, PORES & STUBBLE)
// =============================================================================

function drawHyperrealHead() {
  // Head center: x = 814, Eye line: y = 609, Nose tip: y = 629, Mouth: y = 646, Chin: y = 664
  // Ushanka hat: y = 536..592, x = 768..860

  // -------------------------------------------------------------------------
  // 1. WORN SOVIET USHANKA (FUR/FLEECE WINTER HAT)
  // -------------------------------------------------------------------------
  brush.noStroke();
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.7, 0.45);

  // Hat crown & tied side ear-flaps
  brush.fill(PAL.charcoalDark, 225);
  polyShape([
    [776, 542], [814, 535], [852, 542],
    [864, 568], [860, 608], [848, 602],
    [844, 582], [784, 582],
    [780, 602], [768, 608], [764, 568]
  ], 0.2);

  // Front turned-up faux-fur / sheep-fleece visor band (x = 774..854, y = 552..584)
  brush.fill(PAL.charcoalMid, 230);
  polyShape([
    [774, 554], [814, 550], [854, 554],
    [852, 584], [814, 581], [776, 584]
  ], 0.15);
  brush.noFill();

  // Dense matted fleece curls on the ushanka visor and side flaps
  for (let i = 0; i < 220; i++) {
    let fx = random(772, 856);
    let fy = random(550, 585);
    let isHighlight = fy < 564 || random() < 0.28;
    brush.set("micro_hair", isHighlight ? PAL.concreteLight : PAL.soot, random(0.65, 1.1));
    brush.arc(fx, fy, random(1.8, 3.8), random(0, 180), random(190, 350));
  }
  // Side ear-flap fur texture
  for (let i = 0; i < 85; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let fx = side === -1 ? random(765, 780) : random(848, 863);
    let fy = random(562, 608);
    brush.set("micro_hair", random() < 0.35 ? PAL.concreteMid : PAL.soot, 0.8);
    brush.line(fx, fy, fx + side * random(2, 5), fy + random(-2, 3));
  }

  // Faint indentation / ghost scar on fur where a Soviet cockade pin once sat
  brush.set("micro_hair", PAL.soot, 0.8);
  brush.circle(814, 566, 4.5, 0.2);

  // -------------------------------------------------------------------------
  // 2. CRANIAL & FACIAL SKIN WASHES (SCULPTING THE BONE STRUCTURE)
  // -------------------------------------------------------------------------
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.5, 0.3);

  // Base weathered skin tone
  brush.fill(PAL.skinMid, 225);
  polyShape([
    [778, 582], [850, 582],
    [852, 615], [845, 646], [828, 665],
    [814, 668], [800, 665],
    [783, 646], [776, 615]
  ], 0.2);

  // Pale chalky highlights on forehead brow, cheekbones, and nose bridge
  brush.fill(PAL.skinPale, 165);
  polyShape([[784, 584], [844, 584], [840, 598], [788, 598]], 0.2);
  polyShape([[780, 616], [798, 618], [795, 632], [780, 628]], 0.2);
  polyShape([[830, 618], [848, 616], [848, 628], [833, 632]], 0.2);
  polyShape([[810, 604], [818, 604], [819, 628], [809, 628]], 0.1);

  // Cold steppe wind redness on bulbous nose tip, lower eyelids, and cheekbones
  brush.fill(PAL.skinColdRed, 130);
  brush.circle(814, 627, 9, 0.2);
  brush.circle(792, 622, 8, 0.25);
  brush.circle(836, 622, 8, 0.25);

  // Deep eye sockets, hollow gaunt cheeks, and under-chin shadow
  brush.fill(PAL.skinShadow, 175);
  // Eye sockets
  polyShape([[782, 600], [807, 602], [806, 617], [782, 615]], 0.2);
  polyShape([[821, 602], [846, 600], [846, 615], [822, 617]], 0.2);
  // Gaunt lower cheeks & jawline shadow
  polyShape([[778, 628], [796, 634], [802, 662], [783, 648]], 0.2);
  polyShape([[832, 634], [850, 628], [845, 648], [826, 662]], 0.2);
  // Neck & under-chin shadow
  brush.fill(PAL.skinDeep, 210);
  polyShape([[785, 652], [814, 667], [843, 652], [846, 678], [782, 678]], 0.15);

  brush.noFill();

  // Weathered ears peeking beneath the ushanka flaps
  for (let side = -1; side <= 1; side += 2) {
    let ex = side === -1 ? 775 : 853;
    brush.set("2B", PAL.skinShadow, 0.55);
    brush.spline([[ex, 608], [ex + side * 5, 616], [ex + side * 4, 630], [ex, 635]], 0.4);
    brush.set("micro_hair", PAL.skinDeep, 0.7);
    brush.spline([[ex + side * 2, 613], [ex + side * 3, 622], [ex + side * 1, 628]], 0.4);
    brush.set("micro_hair", PAL.skinPale, 0.65);
    brush.line(ex + side * 3.5, 612, ex + side * 3.5, 626);
  }

  // -------------------------------------------------------------------------
  // 3. FOREHEAD WRINKLES, GLABELLAR FURROWS & BUSHY GREY EYEBROWS
  // -------------------------------------------------------------------------
  // Deeply etched horizontal forehead creases
  let foreheadYs = [587, 591.5, 596];
  for (let fy of foreheadYs) {
    // Shadow trough of wrinkle
    brush.set("micro_hair", PAL.skinDeep, 0.85);
    brush.spline([
      [784, fy + 1], [798, fy - 0.8], [814, fy + 0.8], [830, fy - 0.8], [844, fy + 1]
    ], 0.4);
    // Catchlight ridge immediately below the wrinkle trough
    brush.set("micro_hair", PAL.chalkWarm, 0.7);
    brush.spline([
      [785, fy + 2], [798, fy + 0.3], [814, fy + 1.8], [830, fy + 0.3], [843, fy + 2]
    ], 0.4);
  }

  // Vertical glabellar "eleven" frown lines between eyebrows
  brush.set("micro_hair", PAL.skinDeep, 0.9);
  brush.line(810.5, 594, 811, 604);
  brush.line(817.5, 594, 817, 604);
  brush.set("micro_hair", PAL.skinPale, 0.7);
  brush.line(812, 594, 812.5, 604);
  brush.line(816, 594, 815.5, 604);

  // Unkempt, wiry grey & white eyebrows
  for (let side = -1; side <= 1; side += 2) {
    let bxStart = side === -1 ? 807 : 821;
    let bxEnd = side === -1 ? 781 : 847;
    for (let i = 0; i < 42; i++) {
      let t = i / 41;
      let bx = lerp(bxStart, bxEnd, t) + random(-1, 1);
      let by = 601 - sin(t * 150) * 2.8 + random(-1.2, 1.2);
      let isWhite = random() < 0.55;
      brush.set("micro_hair", isWhite ? PAL.chalk : PAL.charcoalDark, isWhite ? 0.75 : 0.85);
      let len = random(4, 7.5);
      let ang = side === -1 ? random(195, 245) : random(-65, -15);
      brush.line(bx, by, bx + cos(ang) * len, by + sin(ang) * len);
    }
  }

  // -------------------------------------------------------------------------
  // 4. WATERY EYES WITH UNCOMFORTABLE PHOTOGRAPHIC PRECISION
  // -------------------------------------------------------------------------
  // Left eye center: (795.5, 609.5), Right eye center: (832.5, 609.5)
  let eyes = [
    { cx: 795.5, cy: 609.5, side: -1 },
    { cx: 832.5, cy: 609.5, side: 1 }
  ];

  for (let e of eyes) {
    let cx = e.cx, cy = e.cy, s = e.side;

    // A. Heavy hooded upper eyelid fold (epicanthic / aged skin overhang)
    brush.set("micro_hair", PAL.soot, 0.95);
    brush.spline([
      [cx - s * 10, cy - 1.5],
      [cx - s * 3, cy - 5.5],
      [cx + s * 4, cy - 4.8],
      [cx + s * 11.5, cy + 1.5]
    ], 0.4);
    // Lit skin fold above the upper lid crease
    brush.set("micro_hair", PAL.skinPale, 0.75);
    brush.spline([
      [cx - s * 9, cy - 2.8],
      [cx, cy - 6.5],
      [cx + s * 10, cy - 0.5]
    ], 0.4);

    // B. Sclera (slightly reddened/watery off-white eyeball)
    brush.noStroke();
    brush.fillBleed(0.02, "in");
    brush.fill(PAL.chalkWarm, 235);
    polyShape([
      [cx - 8.5, cy + 0.5],
      [cx - 3.5, cy - 3.2],
      [cx + 3.5, cy - 3.2],
      [cx + 8.5, cy + 0.5],
      [cx + 3.5, cy + 3.2],
      [cx - 3.5, cy + 3.2]
    ], 0.3);

    // Reddened inner canthus (tear caruncle) & wet lower lid rim
    brush.fill(PAL.eyeRim, 210);
    brush.circle(cx - s * 7.2, cy + 0.8, 1.8, 0.1);

    // C. Milky-blue/slate aged Iris with Arcus Senilis (pale ring of old age)
    brush.fill(PAL.irisDark, 235);
    brush.circle(cx, cy - 0.2, 4.1, 0.05);
    brush.fill(PAL.irisBlue, 225);
    brush.circle(cx, cy - 0.2, 3.3, 0.05);
    brush.noFill();

    // Radial iris stroma fibers & pale cloudy arcus senilis ring
    brush.set("micro_hair", PAL.chalk, 0.55);
    brush.arc(cx, cy - 0.2, 3.6, -160, 160);
    for (let a = 0; a < 360; a += 36) {
      brush.set("micro_hair", a % 72 === 0 ? PAL.tearWhite : PAL.irisDark, 0.45);
      brush.line(cx + cos(a) * 1.2, cy - 0.2 + sin(a) * 1.2, cx + cos(a) * 3.4, cy - 0.2 + sin(a) * 3.4);
    }

    // D. Pinpoint Pupil (constricted in bright overcast daylight)
    brush.set("rotring", PAL.soot, 1.1);
    brush.circle(cx, cy - 0.3, 1.35, 0.02);
    brush.line(cx - 0.6, cy - 0.3, cx + 0.6, cy - 0.3);

    // E. Upper eyelid lash line casting dark shadow across top of cornea
    brush.set("micro_hair", PAL.soot, 1.05);
    brush.spline([
      [cx - 8.8, cy + 0.6],
      [cx - 3.5, cy - 3.3],
      [cx + 3.5, cy - 3.2],
      [cx + 8.8, cy + 0.8]
    ], 0.4);

    // F. Reddened, everted watery lower eyelid margin & tear bags
    brush.set("micro_hair", PAL.eyeRim, 0.95);
    brush.spline([
      [cx - 8.2, cy + 1.0],
      [cx, cy + 3.6],
      [cx + 8.2, cy + 1.1]
    ], 0.4);

    // Tiny bloodshot micro-capillaries in sclera corners
    brush.set("micro_hair", PAL.brickMid, 0.45);
    brush.line(cx - 7.5, cy + 0.5, cx - 4.2, cy + 0.2);
    brush.line(cx + 7.5, cy + 0.6, cx + 4.4, cy + 0.1);

    // G. THE WATERY TEAR MENISCUS & CORNEAL SKY CATCHLIGHTS
    // 1) Bright rectangular overcast sky window reflection on upper-left of iris/pupil
    brush.set("micro_hair", PAL.tearWhite, 1.15);
    brush.line(cx - 2.0, cy - 1.9, cx - 0.4, cy - 1.9);
    brush.line(cx - 1.8, cy - 1.2, cx - 0.6, cy - 1.2);

    // 2) Glistening liquid tear meniscus pooling along the entire lower eyelid rim
    brush.set("micro_hair", PAL.tearWhite, 1.05);
    brush.spline([
      [cx - 6.2, cy + 1.6],
      [cx - 1.5, cy + 3.2],
      [cx + 2.5, cy + 3.1],
      [cx + 6.0, cy + 1.7]
    ], 0.4);

    // 3) Wet tear bead glistening at the inner corner and outer canthus, plus a damp track
    brush.set("micro_hair", PAL.tearWhite, 1.25);
    brush.line(cx - s * 6.8, cy + 1.2, cx - s * 5.8, cy + 1.6);
    brush.line(cx + s * 7.2, cy + 1.4, cx + s * 7.8, cy + 2.4);
    // Faint glistening tear track on the upper cheek skin below the eye bag
    brush.set("micro_hair", PAL.tearWhite, 0.6);
    brush.line(cx - s * 4.5, cy + 4.2, cx - s * 5.2, cy + 11.5);
    brush.line(cx + s * 6.5, cy + 3.2, cx + s * 7.5, cy + 9.5);

    // H. Puffy lower eye bags (orbicularis folds) & deep crow's feet wrinkles
    brush.set("micro_hair", PAL.skinDeep, 0.8);
    brush.spline([
      [cx - 8.5, cy + 3.5],
      [cx, cy + 7.2],
      [cx + 9.0, cy + 4.2]
    ], 0.4);
    brush.set("micro_hair", PAL.skinShadow, 0.7);
    brush.spline([
      [cx - 7.5, cy + 6.5],
      [cx + s * 1.5, cy + 10.5],
      [cx + 9.5, cy + 7.5]
    ], 0.4);
    // Puffy highlight on tear bag
    brush.set("micro_hair", PAL.skinPale, 0.75);
    brush.spline([
      [cx - 6.0, cy + 4.8],
      [cx, cy + 5.8],
      [cx + 6.0, cy + 4.8]
    ], 0.4);

    // Crow's feet radiating from outer eye corners into temple
    brush.set("micro_hair", PAL.skinDeep, 0.75);
    for (let c = -2; c <= 2; c++) {
      let startX = cx + s * 9.0;
      let startY = cy + 0.5 + c * 1.2;
      let endX = startX + s * random(6, 10);
      let endY = startY + c * 2.4 + random(-0.8, 0.8);
      brush.line(startX, startY, endX, endY);
      brush.set("micro_hair", PAL.skinPale, 0.55);
      brush.line(startX, startY + 0.8, endX, endY + 0.8);
      brush.set("micro_hair", PAL.skinDeep, 0.75);
    }

    // Sparse pale lower eyelashes catching the tear film
    brush.set("micro_hair", PAL.chalk, 0.55);
