// ============================================================================
// BATHYMETRIC & GEOLOGICAL ELEVATION FIELD + MARCHING SQUARES
// ============================================================================

function gaussian2D(x, y, cx, cy, rx, ry, angleDeg = 0) {
  let rad = (angleDeg * Math.PI) / 180;
  let dx = x - cx;
  let dy = y - cy;
  let u = dx * Math.cos(rad) + dy * Math.sin(rad);
  let v = -dx * Math.sin(rad) + dy * Math.cos(rad);
  return Math.exp(-(u * u) / (2 * rx * rx) - (v * v) / (2 * ry * ry));
}

function getElevation(x, y) {
  // Base dry rock elevation
  let z = 0.42;

  // Main diagonal rock basin
  z -= 0.92 * gaussian2D(x, y, 565, 595, 245, 195, 32);
  // Deep southeast kelp trench
  z -= 0.58 * gaussian2D(x, y, 690, 715, 135, 115, -20);
  // Northwest anemone cove
  z -= 0.48 * gaussian2D(x, y, 395, 435, 125, 100, 15);
  // Southwest shallow sandy hermit-crab shelf
  z -= 0.36 * gaussian2D(x, y, 445, 665, 140, 110, -15);
  // Northeast gem-anemone embayment
  z -= 0.42 * gaussian2D(x, y, 765, 515, 110, 95, 40);
  // Narrow southern tidal channel
  z -= 0.32 * gaussian2D(x, y, 560, 825, 95, 80, 10);

  // Submerged & awash danger-rock pinnacle inside the pool!
  z += 0.64 * gaussian2D(x, y, 575, 435, 52, 42, -25);
  // Secondary submerged rock ridge
  z += 0.28 * gaussian2D(x, y, 555, 585, 45, 35, 20);

  // Broad flat stone plateau in upper-right for the etched compass rose
  let compassDist = gaussian2D(x, y, 955, 230, 165, 155, 0);
  z = z * (1 - 0.65 * compassDist) + 0.36 * compassDist;

  // Multi-octave geological rock roughness (suppressed slightly on compass slab)
  let n1 = noise(x * 0.0045, y * 0.0045) - 0.5;
  let n2 = noise(x * 0.014 + 50, y * 0.014 + 50) - 0.5;
  let n3 = noise(x * 0.038 + 120, y * 0.038 + 120) - 0.5;
  let roughScale = 1 - 0.72 * compassDist;
  z += roughScale * (0.24 * n1 + 0.09 * n2 + 0.032 * n3);

  // Ensure outer margin stays strictly above water (z >= 0.36) for closed contours
  let edgeDist = Math.min(x, W - x, y, H - y);
  if (edgeDist < 145) {
    let t = Math.pow((145 - edgeDist) / 145, 1.7);
    z = Math.max(z, z + 0.55 * t);
  }

  return z;
}

function buildElevationGrid() {
  elevGrid = new Array(GRID_N + 1);
  for (let ix = 0; ix <= GRID_N; ix++) {
    elevGrid[ix] = new Float32Array(GRID_N + 1);
    for (let iy = 0; iy <= GRID_N; iy++) {
      elevGrid[ix][iy] = getElevation(ix * GRID_STEP, iy * GRID_STEP);
    }
  }
}

function getElevationGrad(x, y) {
  let eps = 4.0;
  let gx = (getElevation(x + eps, y) - getElevation(x - eps, y)) / (2 * eps);
  let gy = (getElevation(x, y + eps) - getElevation(x, y - eps)) / (2 * eps);
  return { gx, gy, mag: Math.hypot(gx, gy) };
}

// Topological Marching Squares using exact integer edge IDs
function extractContours(level) {
  const stride = GRID_N + 1;
  const vOffset = stride * stride;
  let nextEdge = new Map();
  let edgePos = new Map();

  function hEdgeId(ix, iy) {
    return iy * stride + ix;
  }
  function vEdgeId(ix, iy) {
    return vOffset + iy * stride + ix;
  }

  function interpH(ix, iy, vA, vB) {
    let id = hEdgeId(ix, iy);
    if (!edgePos.has(id)) {
      let t = Math.max(0.001, Math.min(0.999, (level - vA) / (vB - vA || 1e-6)));
      edgePos.set(id, [(ix + t) * GRID_STEP, iy * GRID_STEP]);
    }
    return id;
  }

  function interpV(ix, iy, vA, vB) {
    let id = vEdgeId(ix, iy);
    if (!edgePos.has(id)) {
      let t = Math.max(0.001, Math.min(0.999, (level - vA) / (vB - vA || 1e-6)));
      edgePos.set(id, [ix * GRID_STEP, (iy + t) * GRID_STEP]);
    }
    return id;
  }

  for (let ix = 0; ix < GRID_N; ix++) {
    for (let iy = 0; iy < GRID_N; iy++) {
      let v0 = elevGrid[ix][iy];
      let v1 = elevGrid[ix + 1][iy];
      let v2 = elevGrid[ix + 1][iy + 1];
      let v3 = elevGrid[ix][iy + 1];

      let mask =
        (v0 < level ? 1 : 0) |
        (v1 < level ? 2 : 0) |
        (v2 < level ? 4 : 0) |
        (v3 < level ? 8 : 0);

      if (mask === 0 || mask === 15) continue;

      let eTop = (mask & 1) !== (mask & 2) >> 1 ? interpH(ix, iy, v0, v1) : -1;
      let eRight = (mask & 2) >> 1 !== (mask & 4) >> 2 ? interpV(ix + 1, iy, v1, v2) : -1;
      let eBottom = (mask & 8) >> 3 !== (mask & 4) >> 2 ? interpH(ix, iy + 1, v3, v2) : -1;
      let eLeft = (mask & 1) !== (mask & 8) >> 3 ? interpV(ix, iy, v0, v3) : -1;

      let vc = 0.25 * (v0 + v1 + v2 + v3);

      switch (mask) {
        case 1: nextEdge.set(eLeft, eTop); break;
        case 2: nextEdge.set(eTop, eRight); break;
        case 3: nextEdge.set(eLeft, eRight); break;
        case 4: nextEdge.set(eRight, eBottom); break;
        case 5:
          if (vc < level) {
            nextEdge.set(eLeft, eBottom);
            nextEdge.set(eRight, eTop);
          } else {
            nextEdge.set(eLeft, eTop);
            nextEdge.set(eRight, eBottom);
          }
          break;
        case 6: nextEdge.set(eTop, eBottom); break;
        case 7: nextEdge.set(eLeft, eBottom); break;
        case 8: nextEdge.set(eBottom, eLeft); break;
        case 9: nextEdge.set(eBottom, eTop); break;
        case 10:
          if (vc < level) {
            nextEdge.set(eTop, eLeft);
            nextEdge.set(eBottom, eRight);
          } else {
            nextEdge.set(eTop, eRight);
            nextEdge.set(eBottom, eLeft);
          }
          break;
        case 11: nextEdge.set(eBottom, eRight); break;
        case 12: nextEdge.set(eRight, eLeft); break;
        case 13: nextEdge.set(eRight, eTop); break;
        case 14: nextEdge.set(eTop, eLeft); break;
      }
    }
  }

  let visited = new Set();
  let loops = [];

  // First trace any open chains starting at edges that have no incoming edge
  let hasIncoming = new Set(nextEdge.values());
  for (let startId of nextEdge.keys()) {
    if (!hasIncoming.has(startId) && !visited.has(startId)) {
      let chain = [];
      let curr = startId;
      while (curr !== undefined && !visited.has(curr)) {
        visited.add(curr);
        chain.push(edgePos.get(curr));
        curr = nextEdge.get(curr);
      }
      if (curr !== undefined && edgePos.has(curr)) chain.push(edgePos.get(curr));
      if (chain.length >= 4) loops.push({ pts: chain, closed: false, area: 0 });
    }
  }

  // Trace all closed cycles
  for (let startId of nextEdge.keys()) {
    if (visited.has(startId)) continue;
    let chain = [];
    let curr = startId;
    while (curr !== undefined && !visited.has(curr)) {
      visited.add(curr);
      chain.push(edgePos.get(curr));
      curr = nextEdge.get(curr);
    }
    if (chain.length >= 6) {
      let area = computeSignedArea(chain);
      loops.push({ pts: chain, closed: true, area });
    }
  }

  return loops;
}

function computeSignedArea(pts) {
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    a += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return 0.5 * a;
}

function subsampleLoop(pts, minDist = 24, closed = true) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = out[out.length - 1];
    let d = Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]);
    if (d >= minDist) {
      out.push(pts[i]);
    }
  }
  if (closed && out.length >= 3) {
    let first = out[0];
    let last = out[out.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < minDist * 0.55) {
      out.pop();
    }
  }
  return out;
}

function drawSmoothShape(pts, curvature = 0.35, close = true) {
  let clean = subsampleLoop(pts, 14, close);
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(close);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 1.8) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

