  for (let i = 0; i < 18; i++) {
    let x1 = random(60, 1140);
    let y1 = random(60, 1140);
    let ang = random(360);
    brush.line(x1, y1, x1 + cos(ang) * 180, y1 + sin(ang) * 180);
  }

  // Faint cartographic rhumb lines radiating from the compass rose at (955, 230)
  let cx = 955, cy = 230;
  brush.set("etch_needle", PAL.sepiaFaint, 0.45);
  for (let i = 0; i < 16; i++) {
    let ang = i * 22.5 - 8;
    let rStart = 148;
    let rEnd = 1450;
    let x1 = cx + cos(ang) * rStart;
    let y1 = cy + sin(ang) * rStart;
    let x2 = cx + cos(ang) * rEnd;
    let y2 = cy + sin(ang) * rEnd;
    // Clip to neatline [48, 1152]
    let clipped = clipLineToRect(x1, y1, x2, y2, 48, 48, 1152, 1152);
    if (clipped) {
      brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);
    }
  }

  // Secondary auxiliary rhumb node at bottom-left (195, 965)
  brush.set("etch_needle", PAL.sepiaFaint, 0.32);
  for (let i = 0; i < 8; i++) {
    let ang = i * 45 + 14;
    let clipped = clipLineToRect(
      195 + cos(ang) * 28,
      965 + sin(ang) * 28,
      195 + cos(ang) * 900,
      965 + sin(ang) * 900,
      48, 48, 1152, 1152
    );
    if (clipped) {
      brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);
    }
  }
}

function clipLineToRect(x0, y0, x1, y1, xmin, ymin, xmax, ymax) {
  let t0 = 0, t1 = 1;
  let dx = x1 - x0, dy = y1 - y0;
  let p = [-dx, dx, -dy, dy];
  let q = [x0 - xmin, xmax - x0, y0 - ymin, ymax - y0];
  for (let i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-6) {
      if (q[i] < 0) return null;
    } else {
      let t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return null;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return null;
        if (t < t1) t1 = t;
      }
    }
  }
  return [x0 + t0 * dx, y0 + t0 * dy, x0 + t1 * dx, y0 + t1 * dy];
}

