    { x: 1010, y: 620, rx: 165, ry: 230, ang: -12, col: PAL.rockBuff2, op: 50 },
    { x: 920, y: 960, rx: 230, ry: 165, ang: 25, col: PAL.rockOchre, op: 45 },
