    for (let a = 0; a < 360; a += 18) {
      let rMod = 1 + 0.18 * (noise(p.x * 0.01 + cos(a), p.y * 0.01 + sin(a)) - 0.5);
      let ux = cos(a) * p.rx * rMod;
      let uy = sin(a) * p.ry * rMod;
      let rx = p.x + ux * cos(p.ang) - uy * sin(p.ang);
      let ry = p.y + ux * sin(p.ang) + uy * cos(p.ang);
      pts.push([constrain(rx, 55, 1145), constrain(ry, 55, 1145)]);
