  // Damp intertidal rock halo right around the tide pool rim (z = 0.09)
  let dampLoops = extractContours(0.09);
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.55, 0.48);
  for (let loop of dampLoops) {
    if (loop.closed && loop.area > 8000) {
      brush.fill(PAL.rockOchre, 42);
      drawSmoothShape(loop.pts, 0.35, true);
    }
  }
  brush.noFill();

  // Subtle sedimentary rock striations & mineral hatching on dry stone
  brush.field("tidal_current");
  brush.set("2H", PAL.rockDusk, 0.42);
  for (let i = 0; i < 160; i++) {
    let rx = random(65, 1135);
    let ry = random(65, 1135);
    let z = getElevation(rx, ry);
    if (z > 0.04) {
      brush.flowLine(rx, ry, random(28, 75), -28 + random(-12, 12));
    }
  }
  brush.noField();

  // Geological rock crevices & fault joints on the dry rock platforms
  const fissures = [
    [[85, 290], [185, 325], [275, 365], [345, 405]],
    [[210, 110], [265, 205], [320, 285], [385, 345]],
    [[640, 85], [610, 175], [585, 255], [555, 315]],
    [[1110, 480], [1015, 505], [935, 525], [855, 535]],
    [[1085, 790], [975, 765], [885, 745], [805, 735]],
    [[795, 1110], [755, 1010], [720, 925], [680, 855]],
    [[335, 1110], [375, 1005], [405, 920], [435, 845]],
    [[75, 745], [165, 710], [245, 685], [315, 665]],
    // Branching micro-fissures
    [[185, 325], [215, 265], [255, 235]],
    [[975, 765], [945, 835], [910, 885]],
    [[375, 1005], [310, 965], [250, 945]]
  ];

  for (let f of fissures) {
    // Subdivide with rugged rock jitter
    let pts = [];
    let hiPts = [];
    for (let s = 0; s < f.length - 1; s++) {
      let p0 = f[s], p1 = f[s + 1];
      let steps = 6;
      for (let k = 0; k < steps; k++) {
        let t = k / steps;
        let x = lerp(p0[0], p1[0], t);
        let y = lerp(p0[1], p1[1], t);
        let jx = (noise(x * 0.03, y * 0.03) - 0.5) * 14;
        let jy = (noise(y * 0.03, x * 0.03) - 0.5) * 14;
        let pressure = 1.2 - 0.7 * ((s + t) / (f.length - 1));
        pts.push([x + jx, y + jy, pressure]);
        hiPts.push([x + jx + 2.2, y + jy + 2.2, pressure * 0.8]);
      }
    }
    let last = f[f.length - 1];
    pts.push([last[0], last[1], 0.3]);
    hiPts.push([last[0] + 2.2, last[1] + 2.2, 0.25]);

    // Soft crevice shadow glaze
    brush.set("water_glaze", PAL.rockShadow, 0.7);
    safeSpline(pts, 0.35);
    // Sharp dark fault line
    brush.set("fine_quill", PAL.rockCrevice, 1.1);
    safeSpline(pts, 0.35);
