    { x: 1060, y: 930, r: 12, col: "#dfd9cc" },
    { x: 165, y: 990, r: 20, col: "#9ca693" },
    { x: 195, y: 1015, r: 14, col: "#dfd9cc" }
  ];
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.75, 0.65);
  for (let lc of lichens) {
    brush.fill(lc.col, 85);
    brush.circle(lc.x, lc.y, lc.r, 0.45);
  }
  brush.noFill();
}

// ============================================================================
// 3. ETCHED COMPASS ROSE ON UPPER-RIGHT STONE SLAB
// ============================================================================

function drawEtchedCompassRose(cx, cy, R) {
  push();
  translate(cx, cy);
  rotate(-8); // Slight hydrographic chart magnetic alignment

  // Helper for etched stone line (dark chiseled groove + pale southeast stone catch-light)
  function etchedLine(x1, y1, x2, y2, w = 0.55) {
    brush.set("chalk_highlight", PAL.rockHighlight, w * 0.75);
    brush.line(x1 + 1.1, y1 + 1.1, x2 + 1.1, y2 + 1.1);
    brush.set("etch_needle", PAL.sepiaMid, w);
    brush.line(x1, y1, x2, y2);
  }

  function etchedCircle(r, w = 0.55) {
    brush.set("chalk_highlight", PAL.rockHighlight, w * 0.7);
    brush.circle(1.1, 1.1, r, 0.04);
    brush.set("etch_needle", PAL.sepiaMid, w);
    brush.circle(0, 0, r, 0.04);
  }

  // Concentric compass rings etched into the stone
  etchedCircle(R, 0.65);
  etchedCircle(R * 0.91, 0.5);
  etchedCircle(R * 0.76, 0.42);
  etchedCircle(R * 0.22, 0.45);

  // Degree tick marks around outer ring
  for (let deg = 0; deg < 360; deg += 2) {
    let rOuter = R;
    let rInner = deg % 30 === 0 ? R * 0.87 : deg % 10 === 0 ? R * 0.91 : R * 0.95;
    let w = deg % 30 === 0 ? 0.6 : deg % 10 === 0 ? 0.45 : 0.3;
    etchedLine(
      cos(deg) * rInner,
      sin(deg) * rInner,
      cos(deg) * rOuter,
      sin(deg) * rOuter,
      w
    );
  }

  // Inner quarter-wind tick marks
  for (let i = 0; i < 32; i++) {
    let a = i * 11.25;
    etchedLine(
      cos(a) * R * 0.72,
      sin(a) * R * 0.72,
      cos(a) * R * 0.76,
      sin(a) * R * 0.76,
      0.38
    );
  }

  // 16-point mariner's star (8 half-winds, 4 ordinals, 4 cardinals)
  const tiers = [
    { count: 8, offset: 22.5, step: 45, len: R * 0.56, base: R * 0.09 },
    { count: 4, offset: 45, step: 90, len: R * 0.71, base: R * 0.13 },
    { count: 4, offset: 0, step: 90, len: R * 0.86, base: R * 0.17 }
  ];

  for (let tier of tiers) {
    for (let i = 0; i < tier.count; i++) {
      let a = tier.offset + i * tier.step;
      let tipX = cos(a) * tier.len;
      let tipY = sin(a) * tier.len;
      let leftX = cos(a - 22.5) * tier.base;
      let leftY = sin(a - 22.5) * tier.base;
      let rightX = cos(a + 22.5) * tier.base;
      let rightY = sin(a + 22.5) * tier.base;

      // Shaded half of needle (faint dusky sepia wash + fine etching hatch)
      brush.noStroke();
      brush.fillBleed(0.02, "in");
      brush.fill(PAL.rockShadow, 42);
      brush.beginShape(0);
      brush.vertex(0, 0);
      brush.vertex(tipX, tipY);
      brush.vertex(rightX, rightY);
      brush.endShape(true);
      brush.noFill();

      // Sunlit half of needle (pale stone catch-light)
      brush.noStroke();
      brush.fill(PAL.rockHighlight, 36);
      brush.beginShape(0);
      brush.vertex(0, 0);
      brush.vertex(tipX, tipY);
      brush.vertex(leftX, leftY);
      brush.endShape(true);
      brush.noFill();

      // Chiseled needle outlines
      etchedLine(0, 0, tipX, tipY, 0.52);
      etchedLine(tipX, tipY, leftX, leftY, 0.52);
      etchedLine(tipX, tipY, rightX, rightY, 0.58);
    }
  }

  // Ornate Fleur-de-lis North Pointer at angle -90 (top of compass)
  let ny = -R * 0.91;
  etchedLine(0, ny + 8, 0, ny - 28, 0.7);
  brush.set("etch_needle", PAL.sepiaDark, 0.65);
  safeSpline([[0, ny - 28], [-7, ny - 14], [-3, ny - 3], [0, ny + 4]], 0.5);
  safeSpline([[0, ny - 28], [7, ny - 14], [3, ny - 3], [0, ny + 4]], 0.5);
  safeSpline([[-3, ny - 6], [-12, ny - 13], [-14, ny - 5], [-6, ny - 1]], 0.5);
  safeSpline([[3, ny - 6], [12, ny - 13], [14, ny - 5], [6, ny - 1]], 0.5);
  etchedLine(-9, ny - 2, 9, ny - 2, 0.6);

  // Center brass/stone boss ring
  etchedCircle(6, 0.6);

  pop();
}

