function drawBathymetricWaterWashes() {
  const depthLayers = [
    { level: 0.0, col: PAL.waterFilm, op: 48, bleed: 0.16, tex: 0.45 },
    { level: -0.09, col: PAL.waterShallow1, op: 52, bleed: 0.16, tex: 0.48 },
    { level: -0.19, col: PAL.waterShallow2, op: 56, bleed: 0.15, tex: 0.52 },
    { level: -0.30, col: PAL.waterMid1, op: 60, bleed: 0.14, tex: 0.55 },
    { level: -0.42, col: PAL.waterMid2, op: 65, bleed: 0.13, tex: 0.58 },
    { level: -0.55, col: PAL.waterDeep1, op: 70, bleed: 0.12, tex: 0.6 },
    { level: -0.68, col: PAL.waterDeep2, op: 76, bleed: 0.11, tex: 0.62 },
    { level: -0.81, col: PAL.waterAbyss, op: 82, bleed: 0.1, tex: 0.65 }
  ];

  brush.noStroke();

  for (let layer of depthLayers) {
    let loops = extractContours(layer.level);
    brush.fillBleed(layer.bleed, "out");
    brush.fillTexture(layer.tex, 0.38);
    brush.fill(layer.col, layer.op);

    for (let loop of loops) {
      // Only fill outer basin loops (area > 0), skipping interior rock shoal holes
      if (loop.closed && loop.area > 1200) {
        drawSmoothShape(loop.pts, 0.38, true);
      }
    }
  }

  // Now restore the awash danger-rock shoal pinnacle at (575, 435) where z > -0.12
  let shoalLoops = extractContours(-0.14);
  for (let loop of shoalLoops) {
    if (loop.closed && loop.area < -400) {
      // Negative area means an interior rock island rising out of the basin!
      brush.fillBleed(0.14, "out");
      brush.fillTexture(0.58, 0.45);
      brush.fill(PAL.rockBuff2, 72);
      drawSmoothShape(loop.pts, 0.38, true);
    }
  }

  let shoalCrown = extractContours(-0.02);
  for (let loop of shoalCrown) {
    if (loop.closed && loop.area < -150) {
      brush.fillBleed(0.1, "out");
      brush.fill(PAL.rockBuff1, 82);
      drawSmoothShape(loop.pts, 0.38, true);
    }
  }

  brush.noFill();
}

