function drawSubmergedPebble(x, y, rx, ry, ang, col) {
  push();
  translate(x, y);
  rotate(ang);

  // Drop shadow on pool floor
  brush.set("water_glaze", PAL.waterAbyss, 0.55);
  brush.line(-rx * 0.5 + 3, 3, rx * 0.5 + 3, 3);

  // Pebble body wash
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(col, 130);
  let pts = [];
  for (let a = 0; a < 360; a += 30) {
    pts.push([cos(a) * rx, sin(a) * ry]);
  }
  drawSmoothShape(pts, 0.4, true);
  brush.noFill();

  // Outline & top wet highlight
  brush.set("fine_quill", PAL.sepiaDark, 0.45);
  brush.arc(0, 0, (rx + ry) * 0.5, 15, 195);
  brush.set("chalk_highlight", PAL.causticBright, 0.45);
  brush.arc(-rx * 0.15, -ry * 0.15, (rx + ry) * 0.35, 200, 330);

  pop();
}

