function buildKelpPolygon(spine, maxW, offX = 0, offY = 0) {
  let samples = sampleSplinePoints(spine, 26);
  let leftPts = [];
  let rightPts = [];

  for (let i = 0; i < samples.length; i++) {
    let t = i / (samples.length - 1);
    let p = samples[i];
    // Width profile: narrow stipe -> broad blade -> tapering tip
    let wProfile = Math.sin(Math.pow(t, 0.72) * Math.PI) * maxW;
    // Ruffled undulating edge modulation
    let ruffleL = 1 + 0.28 * Math.sin(t * 950 + p[0] * 0.5);
    let ruffleR = 1 + 0.28 * Math.cos(t * 950 + p[1] * 0.5);

    let nx = -p[3], ny = p[2]; // normal to tangent (dx, dy)
    leftPts.push([p[0] + offX + nx * wProfile * ruffleL, p[1] + offY + ny * wProfile * ruffleL]);
    rightPts.push([p[0] + offX - nx * wProfile * ruffleR, p[1] + offY - ny * wProfile * ruffleR]);
  }

  rightPts.reverse();
  return leftPts.concat(rightPts);
}

function sampleSplinePoints(ctrlPts, numSamples) {
  let out = [];
  let n = ctrlPts.length - 1;
  for (let i = 0; i <= numSamples; i++) {
    let u = (i / numSamples) * n;
    let idx = Math.min(n - 1, Math.floor(u));
    let f = u - idx;
    let p0 = ctrlPts[Math.max(0, idx - 1)];
    let p1 = ctrlPts[idx];
    let p2 = ctrlPts[idx + 1];
    let p3 = ctrlPts[Math.min(n, idx + 2)];

    // Catmull-Rom interpolation
    let f2 = f * f, f3 = f2 * f;
    let x =
      0.5 *
      (2 * p1[0] +
        (-p0[0] + p2[0]) * f +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3);
    let y =
      0.5 *
      (2 * p1[1] +
        (-p0[1] + p2[1]) * f +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3);

    out.push([x, y, 0, 0]);
  }

  for (let i = 0; i < out.length; i++) {
    let prev = out[Math.max(0, i - 1)];
    let next = out[Math.min(out.length - 1, i + 1)];
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    let len = Math.hypot(dx, dy) || 1;
    out[i][2] = dx / len;
    out[i][3] = dy / len;
  }
  return out;
}

function drawLaminariaFrond(spine, maxW, colBase, colRim) {
  let poly = buildKelpPolygon(spine, maxW, 0, 0);
  let innerPoly = buildKelpPolygon(spine, maxW * 0.52, 0, 0);

  // Translucent olive-bronze blade wash
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.65, 0.55);
  brush.fill(colBase, 125);
  drawSmoothShape(poly, 0.35, true);

  // Warm amber inner blade glow catching the high light
  brush.fill(colRim, 85);
  drawSmoothShape(innerPoly, 0.35, true);
  brush.noFill();

  // Ruffled blade margins & cross-ribbed cellular striations
  let samples = sampleSplinePoints(spine, 28);
  let leftEdge = [];
  let rightEdge = [];
  let midrib = [];

  for (let i = 0; i < samples.length; i++) {
    let t = i / (samples.length - 1);
    let p = samples[i];
    let w = Math.sin(Math.pow(t, 0.72) * Math.PI) * maxW;
    let rL = 1 + 0.28 * Math.sin(t * 950 + p[0] * 0.5);
    let rR = 1 + 0.28 * Math.cos(t * 950 + p[1] * 0.5);
    let nx = -p[3], ny = p[2];

    let lx = p[0] + nx * w * rL;
    let ly = p[1] + ny * w * rL;
    let rx = p[0] - nx * w * rR;
    let ry = p[1] - ny * w * rR;

    leftEdge.push([lx, ly, 0.85]);
    rightEdge.push([rx, ry, 0.85]);
    midrib.push([p[0], p[1], 1.2 - 0.7 * t]);

    // Delicate lateral wrinkles across the kelp blade
    if (i > 2 && i < samples.length - 2) {
      brush.set("etch_needle", PAL.kelpDark, 0.38);
      safeSpline(
        [
          [p[0], p[1]],
          [lerp(p[0], lx, 0.55) + p[2] * 5, lerp(p[1], ly, 0.55) + p[3] * 5],
          [lx, ly]
        ],
        0.4
      );
      safeSpline(
        [
          [p[0], p[1]],
          [lerp(p[0], rx, 0.55) + p[2] * 5, lerp(p[1], ry, 0.55) + p[3] * 5],
          [rx, ry]
        ],
        0.4
      );
    }
  }

  // Central stipe & midrib
  brush.set("fine_quill", PAL.kelpDark, 1.05);
  safeSpline(midrib, 0.45);
  brush.set("chalk_highlight", PAL.kelpHighlight, 0.55);
  safeSpline(midrib.map((p) => [p[0] + 1.2, p[1] - 1.2, p[2] * 0.7]), 0.45);

  // Crisp ruffled margin outlines & luminous rim catch-light
  brush.set("fine_quill", PAL.sepiaDark, 0.62);
  safeSpline(leftEdge, 0.45);
  safeSpline(rightEdge, 0.45);

  brush.set("chalk_highlight", PAL.kelpHighlight, 0.48);
  safeSpline(leftEdge.slice(3, -3), 0.45);
}

function drawBladderWrack(x, y, baseDir, len) {
  function branch(bx, by, dir, l, depth) {
    if (depth <= 0 || l < 16) return;
    let ex = bx + cos(dir) * l;
    let ey = by + sin(dir) * l;
    let mx = (bx + ex) * 0.5 + cos(dir + 90) * (random(-5, 5));
    let my = (by + ey) * 0.5 + sin(dir + 90) * (random(-5, 5));

    // Thallus rib
    brush.set("water_glaze", PAL.kelpMid, 0.85);
    safeSpline([[bx, by], [mx, my], [ex, ey]], 0.4);
    brush.set("fine_quill", PAL.kelpDark, 0.65);
    safeSpline([[bx, by], [mx, my], [ex, ey]], 0.4);

    // Paired oval pneumatocysts (air bladders) along the thallus
    let nx = -sin(dir), ny = cos(dir);
    for (let side of [-1, 1]) {
      let px = mx + nx * side * 6.5;
      let py = my + ny * side * 6.5;
      brush.noStroke();
      brush.fillBleed(0.04, "in");
      brush.fill(PAL.kelpAmber, 155);
      brush.circle(px, py, 4.5, 0.2);
      brush.noFill();

      brush.set("fine_quill", PAL.kelpDark, 0.45);
      brush.circle(px, py, 4.5, 0.15);
      // Specular highlight dot on each air bladder
      brush.set("chalk_highlight", PAL.causticBright, 0.55);
      brush.line(px - 1.2, py - 1.2, px + 0.5, py - 1.5);
    }

    branch(ex, ey, dir - 22 + random(-6, 6), l * 0.68, depth - 1);
    branch(ex, ey, dir + 22 + random(-6, 6), l * 0.68, depth - 1);
  }

  branch(x, y, baseDir, len * 0.42, 3);
}

function drawRedAlgaeTuft(x, y, dir, radius) {
  for (let i = 0; i < 14; i++) {
    let a = dir + map(i, 0, 13, -65, 65) + random(-6, 6);
    let r = radius * random(0.65, 1.1);
    let x1 = x + cos(a) * r * 0.45;
    let y1 = y + sin(a) * r * 0.45;
    let x2 = x + cos(a + random(-15, 15)) * r;
    let y2 = y + sin(a + random(-15, 15)) * r;

    brush.set("water_glaze", PAL.redAlgaeMid, 0.75);
    safeSpline([[x, y], [x1, y1], [x2, y2]], 0.5);
    brush.set("fine_quill", PAL.redAlgaeDark, 0.55);
    safeSpline([[x, y], [x1, y1], [x2, y2]], 0.5);

    // Iridescent rose-violet tips underwater
    brush.set("chalk_highlight", PAL.redAlgaeTip, 0.55);
    brush.line(x2, y2, x2 + cos(a) * 3.5, y2 + sin(a) * 3.5);
  }
}

