function drawBathymetricContoursAndSoundings() {
  const contourLevels = [
    { z: 0.24, index: false, style: "rock" },
    { z: 0.14, index: true, style: "rock" },
    { z: 0.05, index: false, style: "rock" },
    { z: 0.0, index: true, style: "shoreline" },
    { z: -0.06, index: false, style: "lowwater" },
    { z: -0.14, index: false, style: "water" },
    { z: -0.22, index: true, style: "water" },
    { z: -0.31, index: false, style: "water" },
    { z: -0.40, index: false, style: "water" },
    { z: -0.50, index: true, style: "water" },
    { z: -0.60, index: false, style: "water" },
    { z: -0.70, index: false, style: "water" },
    { z: -0.80, index: true, style: "water" }
  ];

  // Sounding locations where we leave a tiny clean gap in the contour lines
  const soundings = [
    { x: 355, y: 400, val: "2", sub: "4" },
    { x: 435, y: 365, val: "3", sub: "2" },
    { x: 520, y: 390, val: "1", sub: "5" },
    { x: 645, y: 410, val: "4", sub: "" },
    { x: 755, y: 465, val: "3", sub: "6" },
    { x: 825, y: 535, val: "2", sub: "1" },
    { x: 395, y: 585, val: "2", sub: "8" },
    { x: 515, y: 615, val: "4", sub: "5" },
    { x: 605, y: 535, val: "6", sub: "2" },
    { x: 665, y: 585, val: "9", sub: "4" },
    { x: 585, y: 675, val: "11", sub: "" },
    { x: 685, y: 675, val: "15", sub: "2" },
    { x: 710, y: 735, val: "18", sub: "" },
    { x: 635, y: 765, val: "12", sub: "5" },
    { x: 555, y: 815, val: "5", sub: "3" },
    { x: 455, y: 745, val: "3", sub: "1" }
  ];

  for (let cl of contourLevels) {
    let loops = extractContours(cl.z);
    let col = cl.index ? PAL.sepiaDark : PAL.sepiaMid;
    let weight = cl.index ? 0.78 : 0.44;
    if (cl.style === "shoreline") weight = 0.92;

    for (let loop of loops) {
      let pts = loop.pts;
      if (pts.length < 5) continue;

      if (cl.style === "lowwater") {
        // Dotted-dashed low-water drying line (Admiralty chart convention)
        brush.set("fine_quill", PAL.sepiaMid, 0.5);
        for (let i = 0; i < pts.length - 1; i += 2) {
          let p0 = pts[i], p1 = pts[i + 1];
          brush.line(p0[0], p0[1], lerp(p0[0], p1[0], 0.55), lerp(p0[1], p1[1], 0.55));
        }
      } else {
        // Draw smooth sepia contour segments, breaking cleanly around sounding numerals
        brush.set("fine_quill", col, weight);
        let seg = [];
        let total = loop.closed ? pts.length + 1 : pts.length;
        for (let i = 0; i < total; i++) {
          let pt = pts[i % pts.length];
          let nearSounding = false;
          for (let s of soundings) {
            if (Math.hypot(pt[0] - s.x, pt[1] - s.y) < 16) {
              nearSounding = true;
              break;
            }
          }
          if (nearSounding) {
            if (seg.length >= 2) safeSpline(seg, 0.4);
            seg = [];
          } else {
            seg.push(pt);
          }
        }
        if (seg.length >= 2) safeSpline(seg, 0.4);
      }

      // Draw authentic Admiralty slope hachures along shoreline & index contours
      if (cl.style === "shoreline" || cl.z === 0.05 || cl.z === -0.22 || cl.z === -0.50) {
        let stepH = cl.style === "shoreline" ? 3 : 6;
        brush.set("etch_needle", PAL.sepiaMid, 0.38);
        for (let i = 0; i < pts.length; i += stepH) {
          let p = pts[i];
          let g = getElevationGrad(p[0], p[1]);
          if (g.mag > 0.0018) {
            // Point down-slope (into deeper water)
            let dx = -g.gx / g.mag;
            let dy = -g.gy / g.mag;
            let hLen = constrain(g.mag * 2400, 4.5, 13.5);
            if (cl.style !== "shoreline") hLen *= 0.65;
            brush.line(p[0], p[1], p[0] + dx * hLen, p[1] + dy * hLen);
          }
        }
      }
    }
  }

  // Render crisp sepia sounding numerals (e.g. 15₂) across the tide pool
  for (let s of soundings) {
    drawCartographicSounding(s.x, s.y, s.val, s.sub);
  }
}

// Vector stroke font for authentic engraved sepia chart digits
const DIGIT_STROKES = {
  "0": [[[0.2, 0], [0.8, 0], [1, 0.3], [1, 0.7], [0.8, 1], [0.2, 1], [0, 0.7], [0, 0.3], [0.2, 0]]],
  "1": [[[0.2, 0.22], [0.55, 0], [0.55, 1]], [[0.2, 1], [0.9, 1]]],
  "2": [[[0.05, 0.25], [0.3, 0], [0.8, 0], [0.95, 0.25], [0.8, 0.52], [0.05, 1], [0.98, 1]]],
  "3": [[[0.1, 0.18], [0.35, 0], [0.8, 0], [0.95, 0.22], [0.55, 0.46], [0.98, 0.72], [0.75, 1], [0.25, 1], [0.05, 0.82]]],
  "4": [[[0.72, 1], [0.72, 0], [0, 0.68], [1, 0.68]]],
  "5": [[[0.92, 0], [0.15, 0], [0.1, 0.45], [0.65, 0.4], [0.95, 0.65], [0.75, 1], [0.2, 1], [0.05, 0.82]]],
  "6": [[[0.88, 0.12], [0.55, 0], [0.18, 0.18], [0.05, 0.62], [0.25, 1], [0.78, 1], [0.95, 0.7], [0.72, 0.45], [0.12, 0.55]]],
  "7": [[[0.05, 0], [0.98, 0], [0.38, 1]]],
  "8": [[[0.5, 0.46], [0.15, 0.25], [0.3, 0], [0.7, 0], [0.85, 0.25], [0.5, 0.46], [0.1, 0.72], [0.25, 1], [0.75, 1], [0.9, 0.72], [0.5, 0.46]]],
  "9": [[[0.88, 0.45], [0.35, 0.55], [0.08, 0.3], [0.25, 0], [0.75, 0], [0.92, 0.35], [0.82, 0.78], [0.45, 1], [0.15, 0.92]]]
};

function drawDigit(ch, x, y, w, h, slant = 0.16, strokeW = 0.52) {
  let paths = DIGIT_STROKES[ch];
  if (!paths) return;
  brush.set("fine_quill", PAL.sepiaDark, strokeW);
  for (let path of paths) {
    let pts = path.map((p) => [x + p[0] * w + (0.5 - p[1]) * h * slant, y + p[1] * h]);
    safeSpline(pts, 0.25);
  }
}

function drawCartographicSounding(cx, cy, mainStr, subStr) {
  let w = 6.5, h = 10.5;
  let totalW = mainStr.length * (w + 2.2) + (subStr ? 5.5 : 0);
  let startX = cx - totalW * 0.5;
  let startY = cy - h * 0.5;

  for (let i = 0; i < mainStr.length; i++) {
    drawDigit(mainStr[i], startX + i * (w + 2.2), startY, w, h, 0.18, 0.56);
  }
  if (subStr && subStr.length > 0) {
    let sx = startX + mainStr.length * (w + 2.2) + 0.5;
    let sy = startY + h * 0.48;
    drawDigit(subStr[0], sx, sy, w * 0.68, h * 0.68, 0.18, 0.44);
  }
}

