function drawOpenAnemone(cx, cy, radius, cfg) {
  // 1. Cast shadow on rock ledge beneath the anemone
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.35);
  brush.fill(PAL.waterAbyss, 95);
  brush.circle(cx + 6, cy + 7, radius * 0.92, 0.32);

  // 2. Basal column & oral disc wash
  brush.fillBleed(0.08, "in");
  brush.fill(cfg.baseCol, 185);
  brush.circle(cx, cy, radius * 0.56, 0.25);

  brush.fill(cfg.discCol, 195);
  brush.circle(cx, cy, radius * 0.42, 0.2);
  brush.noFill();

  // 3. Radial mesentery striations across the oral disc
  brush.set("etch_needle", cfg.baseCol, 0.48);
  for (let i = 0; i < 24; i++) {
    let a = i * 15 + random(-3, 3);
    brush.line(
      cx + cos(a) * radius * 0.1,
      cy + sin(a) * radius * 0.1,
      cx + cos(a) * radius * 0.4,
      cy + sin(a) * radius * 0.4
    );
  }

  // Ring of bright turquoise acrorhagi beads under the outer tentacle crown
  for (let i = 0; i < 18; i++) {
    let a = i * 20 + random(-4, 4);
    let bx = cx + cos(a) * radius * 0.52;
    let by = cy + sin(a) * radius * 0.52;
    brush.set("chalk_highlight", cfg.beadCol, 0.75);
    brush.line(bx - 1, by - 1, bx + 1, by + 1);
  }

  // 4. Three concentric rings of hyperreal tapering tentacles (outer -> middle -> inner)
  const rings = [
    { count: 38, rStart: 0.44, rLen: 0.58, col: cfg.tentDark, w: 0.95 },
    { count: 32, rStart: 0.34, rLen: 0.48, col: cfg.tentMid, w: 0.85 },
    { count: 24, rStart: 0.24, rLen: 0.36, col: cfg.tentLight, w: 0.75 }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let ring = rings[rIdx];
    for (let i = 0; i < ring.count; i++) {
      let baseAng = (i / ring.count) * 360 + rIdx * 7 + random(-4, 4);
      let sx = cx + cos(baseAng) * radius * ring.rStart;
      let sy = cy + sin(baseAng) * radius * ring.rStart;

      let len = radius * ring.rLen * random(0.82, 1.16);
      // Gentle water current sway + natural S-curve curl
      let sway1 = sin(baseAng - cfg.currentAng) * 14 + random(-10, 10);
      let sway2 = sin(baseAng - cfg.currentAng) * 24 + random(-16, 16);

      let mx = sx + cos(baseAng + sway1) * (len * 0.52);
      let my = sy + sin(baseAng + sway1) * (len * 0.52);
      let ex = sx + cos(baseAng + sway2) * len;
      let ey = sy + sin(baseAng + sway2) * len;

      // Tentacle shadow underside
      brush.set("tentacle_brush", cfg.baseCol, ring.w * 1.05);
      safeSpline([[sx + 1.5, sy + 2], [mx + 1.5, my + 2], [ex + 1.5, ey + 2]], 0.45);

      // Tentacle translucent body
      brush.set("tentacle_brush", ring.col, ring.w);
      safeSpline([[sx, sy, 1.3], [mx, my, 0.85], [ex, ey, 0.22]], 0.45);

      // Upper glowing edge
      if (rIdx >= 1 || i % 2 === 0) {
        brush.set("etch_needle", cfg.tentLight, 0.42);
        safeSpline([[sx - 0.6, sy - 0.6], [mx - 0.6, my - 0.6], [ex, ey]], 0.45);
      }

      // Banded rings for Dahlia/Gem anemone
      if (cfg.striped) {
        for (let b = 0.35; b <= 0.75; b += 0.35) {
          let bx = lerp(sx, ex, b);
          let by = lerp(sy, ey, b);
          let nx = -sin(baseAng), ny = cos(baseAng);
          brush.set("chalk_highlight", cfg.tipCol, 0.48);
          brush.line(bx - nx * 2.2, by - ny * 2.2, bx + nx * 2.2, by + ny * 2.2);
        }
      }

      // Luminous tentacle tip
      brush.set("chalk_highlight", cfg.tipCol, 0.62);
      brush.line(ex, ey, ex + cos(baseAng + sway2) * 2.6, ey + sin(baseAng + sway2) * 2.6);
    }
  }

  // 5. Central slit mouth (actinopharynx) with folded lips
  brush.set("water_glaze", cfg.baseCol, 0.65);
  brush.line(cx - radius * 0.11, cy - 3, cx + radius * 0.11, cy + 3);
  brush.set("fine_quill", "#26070d", 0.85);
  brush.line(cx - radius * 0.1, cy - 2.5, cx + radius * 0.1, cy + 2.5);
  brush.set("chalk_highlight", cfg.tipCol, 0.45);
  brush.arc(cx, cy, radius * 0.12, 195, 345);
}

function drawClosedAnemone(cx, cy, r) {
  // Drop shadow on damp rock
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fill(PAL.rockCrevice, 95);
  brush.circle(cx + 4, cy + 5, r * 0.98, 0.25);

  // Glossy crimson-berry dome
  brush.fillBleed(0.06, "in");
  brush.fill(PAL.anemoneBase, 210);
  brush.circle(cx, cy, r, 0.2);
  brush.fill(PAL.anemoneTentDark, 175);
  brush.circle(cx - 2, cy - 2, r * 0.72, 0.18);
  brush.noFill();

  // Puckered apical sphincter dimple
  brush.set("fine_quill", "#24060b", 0.7);
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    brush.line(cx + cos(a) * 2, cy + sin(a) * 2, cx + cos(a) * (r * 0.45), cy + sin(a) * (r * 0.45));
  }

  // Wet specular reflection arcs on the gelatinous dome
  brush.set("chalk_highlight", PAL.specularWhite, 0.75);
  brush.arc(cx - 1, cy - 1, r * 0.62, 205, 295);
  brush.line(cx - r * 0.35, cy + r * 0.2, cx - r * 0.25, cy + r * 0.3);
}

// ============================================================================
// 9. HYPERREAL HERMIT CRAB (PAGURUS BERNHARDUS) ON SHALLOW SHELF
// ============================================================================

function drawHermitCrab(cx, cy) {
  push();
  translate(cx, cy);
  rotate(-12);

  // 1. Cast shadow of shell, claws & walking legs on the sandy shelf
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.3);
  brush.fill(PAL.waterAbyss, 88);
  let shadowPts = [
    [-68, -14], [-35, -34], [18, -32], [58, -16],
    [66, 22], [32, 46], [-18, 42], [-56, 18]
  ];
  drawSmoothShape(shadowPts, 0.4, true);
  brush.noFill();

  // 2. Jointed Walking Legs (2 pairs) & Asymmetrical Chelipeds (Claws)
  // Left walking legs (extending toward top-right)
  drawCrabLeg([[10, -14], [28, -42], [52, -48], [68, -38]], [7.5, 5.8, 4.0], -1);
  drawCrabLeg([[2, -16], [14, -48], [36, -60], [54, -56]], [6.8, 5.2, 3.6], -1);

  // Right walking legs (extending toward bottom-right)
  drawCrabLeg([[8, 16], [28, 44], [54, 46], [72, 34]], [8.0, 6.2, 4.2], 1);
  drawCrabLeg([[-2, 18], [14, 50], [38, 58], [56, 50]], [7.2, 5.4, 3.8], 1);

  // Left Cheliped (smaller claw)
  drawCrabLeg([[16, -8], [38, -24], [56, -18]], [8.5, 7.5], -1);
  drawCrabChela(56, -18, 22, 11, -18, false);

  // Right Cheliped (large dominant armored crusher claw)
  drawCrabLeg([[16, 10], [42, 22], [62, 12]], [10.5, 9.5], 1);
  drawCrabChela(62, 12, 32, 16, 14, true);

  // 3. Cephalothorax front, Stalked Compound Eyes & Sweeping Antennae
  // Rostrum / shield
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.crabOrange, 190);
  brush.circle(16, 0, 12, 0.2);
  brush.noFill();

  // Stalked eyes
  for (let s of [-1, 1]) {
    let ex = 31, ey = s * 6.5;
    brush.set("fine_quill", PAL.crabOrange, 1.3);
    brush.line(18, s * 3.5, ex, ey);
    brush.set("fine_quill", "#222e24", 1.5);
    brush.line(ex - 1, ey, ex + 1.5, ey);
    brush.set("chalk_highlight", "#dce8c8", 0.55);
    brush.line(ex, ey - 0.8, ex + 1, ey - 0.8);
  }

  // Long sweeping antennae + faint refraction shadow on pool floor
  const antL = [[22, -4], [48, -14], [78, -32], [108, -58]];
  const antR = [[22, 4], [52, 10], [84, 24], [116, 46]];
  brush.set("etch_needle", PAL.waterAbyss, 0.45);
  safeSpline(antL.map((p) => [p[0] + 4, p[1] + 6]), 0.5);
  safeSpline(antR.map((p) => [p[0] + 4, p[1] + 6]), 0.5);

  brush.set("fine_quill", PAL.crabRed, 0.65);
  safeSpline(antL.map((p, i) => [p[0], p[1], 1.1 - i * 0.25]), 0.5);
  safeSpline(antR.map((p, i) => [p[0], p[1], 1.1 - i * 0.25]), 0.5);

  // Short antennules
  brush.set("etch_needle", PAL.crabOrange, 0.55);
  safeSpline([[24, -2], [38, -4], [46, -8]], 0.4);
  safeSpline([[24, 2], [38, 4], [46, 8]], 0.4);

  // 4. Turbinate Whelk Shell (5 convex spiral whorls tapering to apex at (-68, -6))
  const whorls = [
    { x: -64, y: -6, rx: 6, ry: 5, ang: -10 },
    { x: -53, y: -5, rx: 11, ry: 9.5, ang: -8 },
    { x: -38, y: -4, rx: 17, ry: 15, ang: -6 },
    { x: -19, y: -2, rx: 24, ry: 22, ang: -4 },
    { x: 2, y: 0, rx: 30, ry: 29, ang: 0 }
  ];

  for (let wIdx = 0; wIdx < whorls.length; wIdx++) {
    let w = whorls[wIdx];
    let pts = [];
    for (let a = 0; a < 360; a += 20) {
      pts.push([w.x + cos(a) * w.rx, w.y + sin(a) * w.ry]);
    }

    // Base warm ochre-terracotta whorl wash
    brush.noStroke();
    brush.fillBleed(0.06, "in");
    brush.fillTexture(0.6, 0.45);
    brush.fill(wIdx % 2 === 0 ? PAL.shellLight : PAL.shellOchre, 185);
    drawSmoothShape(pts, 0.4, true);

    // Underside shadow glaze on each whorl
    let shPts = [];
    for (let a = 15; a <= 175; a += 20) {
      shPts.push([w.x + cos(a) * w.rx, w.y + sin(a) * w.ry]);
    }
    shPts.push([w.x - w.rx * 0.7, w.y + w.ry * 0.15]);
    shPts.push([w.x + w.rx * 0.7, w.y + w.ry * 0.15]);
    brush.fill(PAL.shellBand, 115);
    drawSmoothShape(shPts, 0.35, true);
    brush.noFill();

    // Spiral colour bands & ridges along the whorl
    for (let b = -0.65; b <= 0.65; b += 0.32) {
      let bandPts = [];
      for (let t = -0.75; t <= 0.75; t += 0.25) {
        let bx = w.x + t * w.rx * 0.85;
        let by = w.y + b * w.ry * Math.sqrt(Math.max(0.1, 1 - t * t * 0.6));
        bandPts.push([bx, by]);
      }
      brush.set("fine_quill", Math.abs(b) < 0.2 ? PAL.shellBand : PAL.shellSienna, 0.58);
      safeSpline(bandPts, 0.4);
    }

    // 3D cross-contour axial growth ribs across the whorl
    brush.set("etch_needle", PAL.shellDark, 0.42);
    for (let r = -0.7; r <= 0.7; r += 0.22) {
      let rx = w.x + r * w.rx * 0.85;
      let h = w.ry * Math.sqrt(Math.max(0.15, 1 - r * r * 0.75));
      safeSpline([[rx - 2, w.y - h], [rx + 3.5, w.y], [rx - 2, w.y + h]], 0.45);
    }

    // Deep suture line between whorls
    brush.set("fine_quill", PAL.shellDark, 0.82);
    brush.arc(w.x, w.y, (w.rx + w.ry) * 0.5, 95, 265);

    // Wet specular highlight along top-left dome of whorl
    brush.set("chalk_highlight", PAL.shellLight, 0.68);
    brush.arc(w.x - 2, w.y - 3, (w.rx + w.ry) * 0.36, 215, 315);
  }

  // Shell aperture lip (nacreous pale inner rim + dark shadow cavity)
  brush.set("water_glaze", PAL.shellDark, 0.9);
  brush.arc(10, 0, 24, -65, 65);
  brush.set("chalk_highlight", PAL.crabCream, 0.85);
  brush.arc(14, 0, 26, -60, 60);

  // Tiny epibiont: white calcareous spirorbid worm tube & miniature barnacle on the shell!
  brush.set("chalk_highlight", PAL.specularWhite, 0.65);
  brush.arc(-14, -10, 3.2, 0, 310);
  drawSingleBarnacle(-6, 8, 5.5);

  pop();
}

function drawCrabLeg(joints, widths, sideSign) {
  for (let i = 0; i < joints.length - 1; i++) {
    let p0 = joints[i];
    let p1 = joints[i + 1];
    let w = widths[i] || 4.0;
    let dx = p1[0] - p0[0], dy = p1[1] - p0[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len, ny = dx / len;

    let segPoly = [
      [p0[0] + nx * w * 0.45, p0[1] + ny * w * 0.45],
      [lerp(p0[0], p1[0], 0.5) + nx * w * 0.58, lerp(p0[1], p1[1], 0.5) + ny * w * 0.58],
      [p1[0] + nx * w * 0.35, p1[1] + ny * w * 0.35],
      [p1[0] - nx * w * 0.35, p1[1] - ny * w * 0.35],
      [lerp(p0[0], p1[0], 0.5) - nx * w * 0.58, lerp(p0[1], p1[1], 0.5) - ny * w * 0.58],
      [p0[0] - nx * w * 0.45, p0[1] - ny * w * 0.45]
    ];

    brush.noStroke();
    brush.fillBleed(0.03, "in");
    brush.fill(i === joints.length - 2 ? PAL.crabRed : PAL.crabOrange, 200);
    drawSmoothShape(segPoly, 0.35, true);
    brush.noFill();

    // Exoskeleton contour, calcified tubercles & sensory setae (bristles)
    brush.set("fine_quill", PAL.crabDark, 0.62);
    drawSmoothShape(segPoly, 0.35, true);

    // Cream calcified dots & top highlight ridge
    brush.set("chalk_highlight", PAL.crabCream, 0.58);
    brush.line(
      lerp(p0[0], p1[0], 0.25),
      lerp(p0[1], p1[1], 0.25),
      lerp(p0[0], p1[0], 0.75),
      lerp(p0[1], p1[1], 0.75)
    );

    // Tiny sensory bristles along outer margin
    brush.set("etch_needle", PAL.crabDark, 0.38);
    for (let t = 0.2; t <= 0.85; t += 0.25) {
      let bx = lerp(p0[0], p1[0], t) + nx * sideSign * w * 0.5;
      let by = lerp(p0[1], p1[1], t) + ny * sideSign * w * 0.5;
      brush.line(bx, by, bx + (dx / len) * 2.5 + nx * sideSign * 3.2, by + (dy / len) * 2.5 + ny * sideSign * 3.2);
    }
  }
}

function drawCrabChela(x, y, len, w, ang, isMajor) {
  push();
  translate(x, y);
  rotate(ang);

  // Propodus (palm + fixed finger)
  let palmPts = [
    [0, -w * 0.42],
    [len * 0.48, -w * 0.55],
    [len, -w * 0.12],
    [len * 0.55, 0],
    [len * 0.95, w * 0.22],
    [len * 0.45, w * 0.52],
    [0, w * 0.38]
  ];

  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fill(PAL.crabOrange, 210);
  drawSmoothShape(palmPts, 0.32, true);
  brush.fill(PAL.crabRed, 145);
  brush.circle(len * 0.32, 0, w * 0.42, 0.25);
  brush.noFill();

  // Outline & dactylus (movable pincer cleft)
  brush.set("fine_quill", PAL.crabDark, 0.72);
  drawSmoothShape(palmPts, 0.32, true);
  safeSpline([[len * 0.48, -w * 0.05], [len * 0.75, 0.5], [len * 0.98, -w * 0.08]], 0.3);

  // Calcified white-cream granules/tubercles on the claw surface
  brush.set("chalk_highlight", PAL.crabCream, 0.68);
  let numTub = isMajor ? 10 : 6;
  for (let i = 0; i < numTub; i++) {
    let tx = random(len * 0.15, len * 0.75);
    let ty = random(-w * 0.28, w * 0.25);
    brush.line(tx - 0.8, ty - 0.8, tx + 0.8, ty + 0.8);
  }

  pop();
}

// ============================================================================
// 10. LIMPETS, ACORN BARNACLES & CARTOGRAPHIC DANGER-ROCK SYMBOLS
// ============================================================================

function drawLimpetsBarnaclesAndDangerSymbols() {
  // 1. Conical ribbed Limpets (Patella vulgata) on intertidal & shallow rock
  const limpets = [
    { x: 265, y: 555, rx: 28, ry: 23, ang: 22 },
    { x: 302, y: 608, rx: 19, ry: 16, ang: -35 },
    { x: 608, y: 328, rx: 25, ry: 21, ang: 12 },
    { x: 848, y: 405, rx: 27, ry: 22, ang: -18 },
    { x: 878, y: 445, rx: 18, ry: 15, ang: 42 },
    { x: 742, y: 868, rx: 24, ry: 20, ang: -28 },
    { x: 568, y: 428, rx: 17, ry: 14, ang: 15 } // On the awash shoal!
  ];

  for (let lp of limpets) {
    drawLimpet(lp.x, lp.y, lp.rx, lp.ry, lp.ang);
  }

  // 2. Clusters of Acorn Barnacles (Semibalanus balanoides)
  const barnacleClusters = [
    { cx: 585, cy: 442, count: 16, spread: 28 }, // On awash danger-rock shoal
    { cx: 342, cy: 348, count: 14, spread: 26 }, // NW rock ledge
    { cx: 818, cy: 452, count: 12, spread: 24 }, // East rock shelf
    { cx: 512, cy: 848, count: 13, spread: 25 }, // South intertidal rim
    { cx: 285, cy: 485, count: 10, spread: 20 }  // West ledge
  ];

  for (let bc of barnacleClusters) {
    for (let i = 0; i < bc.count; i++) {
      let a = i * 137.5; // Phyllotaxis packing for natural non-overlapping cluster
      let r = Math.sqrt(i / bc.count) * bc.spread + random(-2.5, 2.5);
      let bx = bc.cx + cos(a) * r;
      let by = bc.cy + sin(a) * r;
      let br = map(i, 0, bc.count, 7.5, 4.2) * random(0.85, 1.15);
      drawSingleBarnacle(bx, by, br);
    }
  }

  // 3. Authentic Nautical Chart Danger-Rock Symbols right beside actual barnacles!
  const dangerSymbols = [
    { x: 552, y: 412, r: 16, type: "awash", label: "Rk" },
    { x: 612, y: 452, r: 13, type: "star", label: "" },
    { x: 355, y: 472, r: 14, type: "awash", label: "" },
    { x: 805, y: 432, r: 14, type: "star", label: "Rk" },
    { x: 538, y: 832, r: 13, type: "awash", label: "" },
    { x: 555, y: 585, r: 15, type: "submerged", label: "+" }
  ];

  for (let ds of dangerSymbols) {
    drawDangerRockSymbol(ds.x, ds.y, ds.r, ds.type, ds.label);
  }
}

function drawLimpet(cx, cy, rx, ry, ang) {
  push();
  translate(cx, cy);
  rotate(ang);

  // Strong directional drop shadow on the rock
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fill(PAL.rockCrevice, 105);
  let shPts = [];
  for (let a = 0; a < 360; a += 24) {
    shPts.push([4.5 + cos(a) * rx * 1.02, 5.5 + sin(a) * ry * 1.02]);
  }
  drawSmoothShape(shPts, 0.38, true);

  // Scalloped conical shell base wash
  let shellPts = [];
  let numRibs = 24;
  for (let i = 0; i < numRibs; i++) {
    let a = (i / numRibs) * 360;
    let ribMod = i % 2 === 0 ? 1.04 : 0.96;
    shellPts.push([cos(a) * rx * ribMod, sin(a) * ry * ribMod]);
  }

  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.65, 0.5);
  brush.fill(PAL.rockBuff1, 195);
  drawSmoothShape(shellPts, 0.35, true);

  // Shaded SE slope of the cone
  let shadePts = [[-rx * 0.15, -ry * 0.1]];
  for (let a = -25; a <= 165; a += 18) {
    shadePts.push([cos(a) * rx, sin(a) * ry]);
  }
  brush.fill(PAL.rockShadow, 115);
  drawSmoothShape(shadePts, 0.35, true);
  brush.noFill();

  // Concentric growth rings
  for (let f of [0.38, 0.68, 0.88]) {
    brush.set("etch_needle", PAL.sepiaMid, 0.42);
    let ringPts = [];
    for (let a = 0; a <= 360; a += 24) {
      ringPts.push([
        lerp(-rx * 0.14, 0, f) + cos(a) * rx * f,
        lerp(-ry * 0.1, 0, f) + sin(a) * ry * f
      ]);
    }
    safeSpline(ringPts, 0.4);
  }

  // Rugged radial calcified ribs radiating from eccentric apex (-rx*0.14, -ry*0.1)
  let ax = -rx * 0.14, ay = -ry * 0.1;
  for (let i = 0; i < numRibs; i++) {
    let a = (i / numRibs) * 360;
    let ex = cos(a) * rx * (i % 2 === 0 ? 1.04 : 0.96);
    let ey = sin(a) * ry * (i % 2 === 0 ? 1.04 : 0.96);

    brush.set("fine_quill", i % 2 === 0 ? PAL.sepiaDark : PAL.rockDusk, 0.55);
    brush.line(ax, ay, ex, ey);

    // Sunlit NW rib highlights
    if (a > 165 && a < 340 && i % 2 === 0) {
      brush.set("chalk_highlight", PAL.rockHighlight, 0.58);
      brush.line(lerp(ax, ex, 0.2), lerp(ay, ey, 0.2), lerp(ax, ex, 0.9), lerp(ay, ey, 0.9));
    }
  }

  // Weathered apex crown
  brush.set("chalk_highlight", PAL.rockHighlight, 0.8);
  brush.circle(ax, ay, 3.2, 0.2);
  brush.set("fine_quill", PAL.sepiaDark, 0.65);
  drawSmoothShape(shellPts, 0.35, true);

  pop();
}

function drawSingleBarnacle(x, y, r) {
  // Drop shadow
  brush.noStroke();
  brush.fillBleed(0.06, "out");
  brush.fill(PAL.rockCrevice, 90);
  brush.circle(x + 1.8, y + 2.2, r, 0.25);

  // Pale chalky-buff calcified cone (6 parietal plates)
  brush.fillBleed(0.03, "in");
  brush.fill("#e8e0d2", 215);
  brush.circle(x, y, r, 0.25);
  brush.noFill();

  // 6 plate sutures & radial ribs
  brush.set("etch_needle", PAL.rockShadow, 0.42);
  for (let i = 0; i < 6; i++) {
    let a = i * 60 + 15;
    brush.line(x + cos(a) * r * 0.38, y + sin(a) * r * 0.38, x + cos(a) * r, y + sin(a) * r);
  }
  brush.set("fine_quill", PAL.sepiaMid, 0.45);
  brush.circle(x, y, r, 0.22);

  // Dark diamond opercular aperture (tergum & scutum valves)
  let or = r * 0.44;
  brush.noStroke();
  brush.fill(PAL.rockCrevice, 220);
  brush.beginShape(0.1);
  brush.vertex(x - or, y);
  brush.vertex(x, y - or * 0.78);
  brush.vertex(x + or, y);
  brush.vertex(x, y + or * 0.78);
  brush.endShape(true);
  brush.noFill();

  // Central valve seam & rim catch-light
  brush.set("chalk_highlight", PAL.specularWhite, 0.48);
  brush.line(x - or * 0.75, y, x + or * 0.75, y);
  brush.arc(x - 0.5, y - 0.5, r * 0.62, 195, 315);
}

function drawDangerRockSymbol(cx, cy, r, type, label) {
  // Subtle hydrographic chart danger tint inside the dotted circle
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.dangerTint, 55);
  brush.circle(cx, cy, r, 0.1);
  brush.noFill();

  // Ring of crisp sepia dots around the danger perimeter
  let numDots = 16;
  brush.set("fine_quill", PAL.sepiaDark, 0.72);
  for (let i = 0; i < numDots; i++) {
    let a = (i / numDots) * 360;
    let dx = cx + cos(a) * r;
    let dy = cy + sin(a) * r;
    brush.line(dx - 0.6, dy - 0.6, dx + 0.6, dy + 0.6);
  }

  if (type === "awash" || type === "submerged") {
    // Cross (+) symbol with 4 dots in quadrants (Admiralty Rock Awash symbol)
    let cr = r * 0.62;
    brush.set("fine_quill", PAL.sepiaDark, 0.68);
    brush.line(cx - cr, cy, cx + cr, cy);
    brush.line(cx, cy - cr, cx, cy + cr);

    if (type === "awash") {
      for (let q = 45; q < 360; q += 90) {
        let qx = cx + cos(q) * (r * 0.42);
        let qy = cy + sin(q) * (r * 0.42);
        brush.line(qx - 0.6, qy - 0.6, qx + 0.6, qy + 0.6);
      }
    }
  } else if (type === "star") {
    // 6-rayed asterisk (*) rock symbol
    let cr = r * 0.62;
    brush.set("fine_quill", PAL.sepiaDark, 0.65);
    for (let a = 0; a < 180; a += 60) {
      brush.line(cx - cos(a) * cr, cy - sin(a) * cr, cx + cos(a) * cr, cy + sin(a) * cr);
    }
  }

  // Optional tiny etched "Rk" notation beside the symbol
  if (label === "Rk") {
    let lx = cx + r + 5;
    let ly = cy - 4;
    brush.set("etch_needle", PAL.sepiaDark, 0.52);
    // 'R'
    brush.line(lx, ly + 8, lx + 1.5, ly);
    safeSpline([[lx + 1.5, ly], [lx + 6, ly + 0.5], [lx + 5.5, ly + 4], [lx + 1, ly + 4.2]], 0.3);
    brush.line(lx + 3.2, ly + 4.2, lx + 5.8, ly + 8);
    // 'k'
    brush.line(lx + 8, ly + 8, lx + 9.2, ly);
    brush.line(lx + 12.5, ly + 2.8, lx + 8.6, ly + 5.2);
    brush.line(lx + 9.5, ly + 4.8, lx + 12.5, ly + 8);
  }
}

// ============================================================================
// 11. CAUSTIC LIGHT NETWORKS & SLIGHTLY RIPPLED WATER SURFACE
// ============================================================================

function drawCausticLightNetwork() {
  // Generate jittered grid nodes for a cellular Voronoï caustic mesh over the pool
  const cols = 15;
  const rows = 15;
  const minX = 240, maxX = 920;
  const minY = 270, maxY = 930;
  const cellW = (maxX - minX) / cols;
  const cellH = (maxY - minY) / rows;

  let nodes = [];
  for (let gx = 0; gx <= cols; gx++) {
    nodes[gx] = [];
    for (let gy = 0; gy <= rows; gy++) {
      let x = minX + gx * cellW + random(-cellW * 0.36, cellW * 0.36);
      let y = minY + gy * cellH + random(-cellH * 0.36, cellH * 0.36);
      nodes[gx][gy] = [x, y];
    }
  }

  // Extract dual Voronoï-like cell vertices (triangle circumcenters / centroids)
  // and connect adjacent cell centers with inward-curved catenary caustic filaments
  let edges = [];
  let cusps = [];

  for (let gx = 0; gx < cols; gx++) {
    for (let gy = 0; gy < rows; gy++) {
      let p00 = nodes[gx][gy];
      let p10 = nodes[gx + 1][gy];
      let p01 = nodes[gx][gy + 1];
      let p11 = nodes[gx + 1][gy + 1];

      // Two triangle centers per quad cell
      let cA = [(p00[0] + p10[0] + p01[0]) / 3, (p00[1] + p10[1] + p01[1]) / 3];
      let cB = [(p11[0] + p10[0] + p01[0]) / 3, (p11[1] + p10[1] + p01[1]) / 3];

      edges.push([cA, cB]);
      cusps.push(cA, cB);

      if (gx < cols - 1) {
        let p20 = nodes[gx + 2][gy];
        let p21 = nodes[gx + 2][gy + 1];
        let cRight = [(p10[0] + p20[0] + p11[0]) / 3, (p10[1] + p20[1] + p11[1]) / 3];
        edges.push([cB, cRight]);
      }
      if (gy < rows - 1) {
        let p02 = nodes[gx][gy + 2];
        let p12 = nodes[gx + 1][gy + 2];
        let cDown = [(p01[0] + p11[0] + p02[0]) / 3, (p01[1] + p11[1] + p02[1]) / 3];
        edges.push([cB, cDown]);
      }
    }
  }

  // Draw caustic network where submerged (z < -0.03)
  for (let e of edges) {
    let pA = e[0], pB = e[1];
    let mx = (pA[0] + pB[0]) * 0.5;
    let my = (pA[1] + pB[1]) * 0.5;
    let z = getElevation(mx, my);

    // Only underwater (and skip the emerged crown of the awash shoal)
    if (z >= -0.03) continue;

    // Modulate intensity: brightest on shallow/mid shelves, softer in deep trench
    let depthFactor = constrain(map(z, -0.85, -0.08, 0.28, 1.0), 0.25, 1.0);

    // Slight refraction curvature based on depth gradient
    let g = getElevationGrad(mx, my);
    let dx = pB[0] - pA[0], dy = pB[1] - pA[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len, ny = dx / len;
    let bend = (noise(mx * 0.02, my * 0.02) - 0.5) * 10 + g.gx * 120;

    let ctrl = [mx + nx * bend, my + ny * bend];

    // 1. Subtle dark teal chromatic-refraction shadow filament on floor
    if (depthFactor > 0.45) {
      brush.set("etch_needle", PAL.waterDeep2, 0.32 * depthFactor);
      safeSpline(
        [
          [pA[0] + 2.5, pA[1] + 3.5],
          [ctrl[0] + 2.5, ctrl[1] + 3.5],
          [pB[0] + 2.5, pB[1] + 3.5]
        ],
        0.45
      );
    }

    // 2. Soft aqua-cream caustic glow
    brush.set("water_glaze", PAL.causticGlow, 0.34 * depthFactor);
    safeSpline([pA, ctrl, pB], 0.45);

    // 3. Crisp shimmering caustic filament (flared at ends, thin in middle)
    brush.set("caustic_filament", PAL.causticBright, 0.62 * depthFactor);
    safeSpline(
      [
        [pA[0], pA[1], 1.25],
        [ctrl[0], ctrl[1], 0.42],
        [pB[0], pB[1], 1.25]
      ],
      0.45
    );
  }

  // Bright astroid-like cusp nodes at 3-way caustic junctions in the shallows
  for (let c of cusps) {
    let z = getElevation(c[0], c[1]);
    if (z < -0.05 && z > -0.58 && random() < 0.65) {
      let w = map(z, -0.58, -0.05, 0.35, 0.85);
      brush.set("chalk_highlight", PAL.specularWhite, w);
      brush.line(c[0] - 2.2, c[1] - 0.8, c[0] + 2.2, c[1] + 0.8);
      brush.line(c[0] - 0.8, c[1] - 2.2, c[0] + 0.8, c[1] + 2.2);
    }
  }
}

function drawWaterRipplesAndMeniscus() {
  // Subtle concentric surface ripples around the awash rock shoal & hermit crab
  const rippleCenters = [
    { x: 578, y: 438, radii: [34, 48, 66, 86] },
    { x: 485, y: 635, radii: [42, 64, 92] },
    { x: 375, y: 435, radii: [52, 76] },
    { x: 775, y: 515, radii: [46, 70] }
  ];

  for (let rc of rippleCenters) {
    for (let r of rc.radii) {
      let numArcs = 3;
      let baseA = random(360);
      for (let k = 0; k < numArcs; k++) {
        let aStart = baseA + k * 120 + random(-15, 15);
        let aEnd = aStart + random(35, 68);

        // Dark refraction twin just below the surface ripple
        brush.set("etch_needle", PAL.waterDeep1, 0.42);
        brush.arc(rc.x + 1.5, rc.y + 2.2, r, aStart, aEnd);

        // Crisp high-light surface ripple reflection
        brush.set("chalk_highlight", PAL.specularWhite, 0.58);
        brush.arc(rc.x, rc.y, r, aStart, aEnd);
      }
    }
  }

  // Meniscus catch-lights along the water's shoreline (z = 0)
  let shoreLoops = extractContours(0.0);
  brush.set("chalk_highlight", PAL.specularWhite, 0.65);
  for (let loop of shoreLoops) {
    let pts = loop.pts;
    for (let i = 0; i < pts.length - 4; i += 9) {
      if (random() < 0.55) {
        safeSpline([pts[i], pts[i + 1], pts[i + 2], pts[i + 3]], 0.4);
      }
    }
  }
}

