function drawChartBorderAndAnnotations() {
  const mOut = 34;
  const mMid = 44;
  const mIn = 49;

  // Outer heavy sepia neatline
  brush.set("fine_quill", PAL.sepiaDark, 1.05);
  brush.line(mOut, mOut, W - mOut, mOut);
  brush.line(W - mOut, mOut, W - mOut, H - mOut);
  brush.line(W - mOut, H - mOut, mOut, H - mOut);
  brush.line(mOut, H - mOut, mOut, mOut);

  // Inner double neatlines
  brush.set("fine_quill", PAL.sepiaMid, 0.58);
  brush.line(mMid, mMid, W - mMid, mMid);
  brush.line(W - mMid, mMid, W - mMid, H - mMid);
  brush.line(W - mMid, H - mMid, mMid, H - mMid);
  brush.line(mMid, H - mMid, mMid, mMid);

  brush.set("etch_needle", PAL.sepiaMid, 0.42);
  brush.line(mIn, mIn, W - mIn, mIn);
  brush.line(W - mIn, mIn, W - mIn, H - mIn);
  brush.line(W - mIn, H - mIn, mIn, H - mIn);
  brush.line(mIn, H - mIn, mIn, mIn);

  // Alternating hatched degree/minute subdivisions along all four borders
  let segLen = (W - 2 * mMid) / 24;
  brush.set("etch_needle", PAL.sepiaDark, 0.42);
  for (let i = 0; i < 24; i++) {
    let p0 = mMid + i * segLen;
    let p1 = p0 + segLen;

    // Tick marks
    brush.line(p0, mOut, p0, mIn);
    brush.line(p0, H - mOut, p0, H - mIn);
    brush.line(mOut, p0, mIn, p0);
    brush.line(W - mOut, p0, W - mIn, p0);

    // Shade alternating minute bars with fine triple rules
    if (i % 2 === 0) {
      for (let o = 2.5; o <= 7.5; o += 2.5) {
        brush.line(p0, mOut + o, p1, mOut + o);
        brush.line(p0, H - mOut - o, p1, H - mOut - o);
        brush.line(mOut + o, p0, mOut + o, p1);
        brush.line(W - mOut - o, p0, W - mOut - o, p1);
      }
    }
  }

  // Corner cartographic rosette crosshairs
  const corners = [
    [39, 39],
    [W - 39, 39],
    [W - 39, H - 39],
    [39, H - 39]
  ];
  for (let c of corners) {
    brush.set("fine_quill", PAL.sepiaDark, 0.55);
    brush.circle(c[0], c[1], 3.5, 0.1);
    brush.line(c[0] - 5, c[1], c[0] + 5, c[1]);
    brush.line(c[0], c[1] - 5, c[0], c[1] + 5);
  }

  // Engraved Survey Scale Bar at bottom-left (x: 85..325, y: 1122)
  let sx = 88, sy = 1120, unitW = 42;
  brush.set("fine_quill", PAL.sepiaDark, 0.58);
  brush.line(sx, sy, sx + unitW * 5, sy);
  brush.line(sx, sy + 5, sx + unitW * 5, sy + 5);

  for (let u = 0; u <= 5; u++) {
    let ux = sx + u * unitW;
    brush.line(ux, sy - 3, ux, sy + 8);
    drawDigit(String(u), ux - 3, sy - 16, 5.5, 8.5, 0.12, 0.48);
    if (u < 5 && u % 2 === 0) {
      brush.line(ux, sy + 2.5, ux + unitW, sy + 2.5);
    }
  }
  // Subdivided first unit (tenths)
  for (let sub = 1; sub < 5; sub++) {
    let subX = sx + sub * (unitW / 5);
    brush.line(subX, sy, subX, sy + 5);
  }
}

