function draw() {
  translate(-width / 2, -height / 2);
  background("#221006");

  brush.noField();

  // Base wood ground wash across the entire panel
  brush.noStroke();
  brush.wash(PAL.walnutDark, 255);
  brush.rect(0, 0, width, height, "corner");

  // ---------------------------------------------------------------------------
  // 1. BUILD ANATOMICAL CONTOURS (Heart Disc, Medial Ridge, Beak, Eyes)
  // ---------------------------------------------------------------------------
  const heartCtrlR = [
    [600, 236], // P0: Top medial V-notch
    [672, 198], // P1: Inner upper brow slope
    [786, 186], // P2: Peak of upper brow dome
    [906, 232], // P3: Upper temple curve
    [982, 342], // P4: Upper cheek curve
    [996, 474], // P5: Widest cheek point
    [956, 606], // P6: Lower cheek curve
    [868, 722], // P7: Jawline curve
    [742, 814], // P8: Lower chin taper
    [600, 862]  // P9: Bottom chin apex
  ];

  const N_HEART_HALF = 36;
  const rightHeartRim = [];
  const leftHeartRim = [];
  for (let i = 0; i <= N_HEART_HALF; i++) {
    let t = i / N_HEART_HALF;
    let p = evalCatmullRomChain(heartCtrlR, t);
    rightHeartRim.push([p[0], p[1]]);
    leftHeartRim.push([1200 - p[0], p[1]]);
  }

  // Full closed heart loop (72 segments around the facial disc)
  const fullHeartLoop = [];
  for (let i = 0; i < N_HEART_HALF; i++) fullHeartLoop.push(rightHeartRim[i]);
  for (let i = N_HEART_HALF; i > 0; i--) fullHeartLoop.push(leftHeartRim[i]);

  // Eye focal centers
  const EL = { x: 442, y: 478 };
  const ER = { x: 758, y: 478 };

  // Medial spine half-width profile from y = 236 to y = 862
  function medialHalfWidth(y) {
    if (y < 236) return 18;
    if (y < 430) {
      // Forehead bridge
      let u = (y - 236) / (430 - 236);
      return 18 + 6 * sin(u * 180);
    }
    if (y < 530) {
      // Between the eyes down to cere
      let u = (y - 430) / (530 - 430);
      return 18 + u * 16;
    }
    if (y < 605) {
      // Loral bristle flare around upper beak
      let u = (y - 530) / (605 - 530);
      return 34 + 11 * sin(u * 90);
    }
    if (y < 752) {
      // Tapering hooked beak down to tip at y = 752
      let u = (y - 605) / (752 - 605);
      return 45 * pow(1 - u, 1.38);
    }
    // Lower chin seam below beak tip
    let u = constrain((y - 752) / (862 - 752), 0, 1);
    return 10 * sin(u * 180);
  }

  // Build closed boundary loops for Right and Left Facial Discs
  const rightDiscLoop = [];
  for (let i = 0; i <= N_HEART_HALF; i++) {
    let pt = rightHeartRim[i];
    if (i === 0) {
      rightDiscLoop.push([600 + medialHalfWidth(pt[1]), pt[1]]);
    } else if (i === N_HEART_HALF) {
      rightDiscLoop.push([600 + medialHalfWidth(pt[1]), pt[1]]);
    } else {
      rightDiscLoop.push([pt[0], pt[1]]);
    }
  }
  const N_MEDIAL_STEPS = 28;
  for (let i = N_MEDIAL_STEPS - 1; i >= 1; i--) {
    let y = lerp(236, 862, i / N_MEDIAL_STEPS);
    rightDiscLoop.push([600 + medialHalfWidth(y), y]);
  }

  const leftDiscLoop = rightDiscLoop.map(p => [1200 - p[0], p[1]]);

  // ---------------------------------------------------------------------------
  // 2. DRAW OUTER PLUMAGE (Crown, Mantle, Wing Coverts & Speckled Breast)
  // ---------------------------------------------------------------------------
  drawOuterPlumage(fullHeartLoop);

  // ---------------------------------------------------------------------------
  // 3. DRAW THE 3-RING BRAIDED HEART RUFF
  // ---------------------------------------------------------------------------
  drawHeartRuff(fullHeartLoop);

  // ---------------------------------------------------------------------------
  // 4. DRAW RADIATING FACIAL DISC MARQUETRY (Left & Right Concave Bowls)
  // ---------------------------------------------------------------------------
  drawFacialDiscSide(EL, leftDiscLoop, -1);
  drawFacialDiscSide(ER, rightDiscLoop, +1);

  // ---------------------------------------------------------------------------
  // 5. DRAW MEDIAL FOREHEAD RIDGE, LORAL BRISTLES, BEAK & CHIN KEYSTONE
  // ---------------------------------------------------------------------------
  drawMedialSpineAndBeak(medialHalfWidth);

  // ---------------------------------------------------------------------------
  // 6. MACRO 3D CHIAROSCURO GLAZES (Hot-Sand Scorch Volume Modelling)
  // ---------------------------------------------------------------------------
  drawMacroScorchGlazes(EL, ER, rightHeartRim, leftHeartRim);

  // ---------------------------------------------------------------------------
  // 7. DRAW THE EYES (Obsidian Ebony, Glowing Carnelian Accent & Catchlights)
  // ---------------------------------------------------------------------------
  drawOwlEye(EL.x, EL.y, -1);
  drawOwlEye(ER.x, ER.y, +1);

  // ---------------------------------------------------------------------------
  // 8. DRAW OUTER MARQUETRY PANEL BORDER & INLAID STRINGING
  // ---------------------------------------------------------------------------
  drawPanelBorder();

  noLoop();
}

// =============================================================================
// OUTER PLUMAGE: Crown, Mantle & Speckled Breast (Staggered Scallop Joinery)
// =============================================================================
function drawOuterPlumage(fullHeartLoop) {
  const PANEL_MIN = 28;
  const PANEL_MAX = 1172;
  const cx = 600, cy = 505;

  // Resample the heart loop into N_ANG evenly spaced angular rays around (600, 505)
  const N_ANG = 48;
  const baseRing = [];
  for (let i = 0; i < N_ANG; i++) {
    let ang = -90 + (i / N_ANG) * 360;
    let dx = cos(ang), dy = sin(ang);
    let hit = rayLoopIntersection(cx, cy, dx, dy, fullHeartLoop);
    baseRing.push({
      ang: ang,
      x: hit[0],
      y: hit[1],
      r: dist(cx, cy, hit[0], hit[1])
    });
  }

  // Helper to get point at radial expansion `d` outside the heart rim
  // Smoothly rounds out the top notch as `d` increases into the crown dome
  function outerPlumagePoint(angDeg, d) {
    // Interpolate base heart radius at arbitrary angle angDeg
    let normA = ((angDeg + 90) % 360 + 360) % 360;
    let fIdx = (normA / 360) * N_ANG;
    let i0 = floor(fIdx) % N_ANG;
    let i1 = (i0 + 1) % N_ANG;
    let frac = fIdx - floor(fIdx);
    let rHeart = lerp(baseRing[i0].r, baseRing[i1].r, frac);

    // Top notch smoothing: near -90 deg, fill in the V-notch as d grows
    let topDiff = abs(((angDeg + 90 + 180) % 360) - 180);
    let notchFill = topDiff < 32 ? map(topDiff, 0, 32, 1, 0) * min(d * 0.42, 48) : 0;

    // Breast & corner expansion so rings comfortably reach the 1200x1200 corners
    let radScale = 1.0 + 0.18 * pow( abs(sin(angDeg * 2)), 1.5 );
    if (sin(angDeg) > 0) {
      // Lower breast stretches downward
      radScale += 0.22 * pow(sin(angDeg), 1.4);
    }

    let rTotal = rHeart + notchFill + d * radScale;
    return [cx + cos(angDeg) * rTotal, cy + sin(angDeg) * rTotal];
  }

  // Ring distances starting from the outer edge of the Heart Ruff (d = 84)
  const ringDists = [84, 146, 218, 300, 392, 496, 615, 745];

  // Draw from outermost ring inward so overlapping feather tips layer naturally
  for (let rIdx = ringDists.length - 2; rIdx >= 0; rIdx--) {
    let d0 = ringDists[rIdx];
    let d1 = ringDists[rIdx + 1];
    let dMid = lerp(d0, d1, 0.55);
    let dTip = d1 + (d1 - d0) * 0.24;
    let stagger = (rIdx % 2 === 1) ? 0.5 : 0.0;

    for (let i = 0; i < N_ANG; i++) {
      let stepDeg = 360 / N_ANG;
      let aCenter = -90 + (i + stagger) * stepDeg;
      let aLeft   = aCenter - stepDeg * 0.52;
      let aRight  = aCenter + stepDeg * 0.52;

      // 6-vertex interlocking scalloped shield tile
      let pBaseC = outerPlumagePoint(aCenter, max(82, d0 - (d1 - d0) * 0.14));
      let pBaseL = outerPlumagePoint(aLeft, d0 + (d1 - d0) * 0.08);
      let pSideL = outerPlumagePoint(aLeft, dMid);
      let pTip   = outerPlumagePoint(aCenter, dTip);
      let pSideR = outerPlumagePoint(aRight, dMid);
      let pBaseR = outerPlumagePoint(aRight, d0 + (d1 - d0) * 0.08);

      let rawPoly = [pBaseC, pBaseL, pSideL, pTip, pSideR, pBaseR];
      let clipped = clipPolygonToRect(rawPoly, PANEL_MIN, PANEL_MIN, PANEL_MAX, PANEL_MAX);
      if (clipped.length < 3 || polyArea(clipped) < 45) continue;

      let cent = polyCentroid(clipped);
      let isCrown = cent[1] < 380;
      let isBreast = cent[1] > 690;
      let distFromCenterX = abs(cent[0] - 600);
      let nVal = noise(cent[0] * 0.008, cent[1] * 0.008, rIdx * 0.7);

      let baseCol, grainCol, scorchCol = PAL.rosewoodDeep;
      let scorchStr = 0.35;
      let hasSpeckle = false;
      let speckleType = "none";

      if (isBreast) {
        // Speckled Breast: creamy sycamore in center, honey satinwood on flanks
        let flankFactor = constrain(map(distFromCenterX, 120, 540, 0, 1) + (rIdx * 0.06), 0, 1);
        let breastPick = flankFactor * 0.68 + nVal * 0.32;
        if (breastPick < 0.26) {
          baseCol = PAL.sycamoreBright;
          grainCol = PAL.satinLight;
          scorchCol = PAL.walnutLight;
          scorchStr = 0.25;
        } else if (breastPick < 0.52) {
          baseCol = PAL.sycamoreCream;
          grainCol = PAL.satinGold;
          scorchCol = PAL.walnutWarm;
          scorchStr = 0.30;
        } else if (breastPick < 0.75) {
          baseCol = PAL.sycamoreWarm;
          grainCol = PAL.satinHoney;
          scorchCol = PAL.walnutDeep;
          scorchStr = 0.38;
        } else if (breastPick < 0.90) {
          baseCol = PAL.satinLight;
          grainCol = PAL.walnutLight;
          scorchCol = PAL.walnutDark;
          scorchStr = 0.44;
        } else {
          baseCol = PAL.satinGold;
          grainCol = PAL.walnutWarm;
          scorchCol = PAL.rosewoodLight;
          scorchStr = 0.50;
        }
        // Barn owl breast speckles: sparse dark ebony arrow-dots
        if ((i * 7 + rIdx * 13) % 3 !== 0 && cent[1] > 730) {
          hasSpeckle = true;
          speckleType = "breastFlecks";
        }
      } else if (isCrown) {
        // Crown & Forehead Dome: rich honey satinwood, toasted walnut & rosewood
        let crownPick = nVal * 0.65 + (rIdx / 7) * 0.35;
        if (crownPick < 0.25) {
          baseCol = PAL.satinLight;
          grainCol = PAL.walnutWarm;
          scorchStr = 0.42;
        } else if (crownPick < 0.50) {
          baseCol = PAL.satinHoney;
          grainCol = PAL.walnutDeep;
          scorchStr = 0.48;
        } else if (crownPick < 0.76) {
          baseCol = PAL.walnutLight;
          grainCol = PAL.rosewoodLight;
          scorchStr = 0.55;
        } else {
          baseCol = PAL.walnutDeep;
          grainCol = PAL.rosewoodDeep;
          scorchStr = 0.62;
        }
        if ((i + rIdx) % 2 === 0) {
          hasSpeckle = true;
          speckleType = "crownTwinDot";
        }
      } else {
        // Lateral Neck & Wing Mantle Coverts
        let sidePick = nVal * 0.6 + (distFromCenterX / 580) * 0.4;
        if (sidePick < 0.28) {
          baseCol = PAL.sycamoreBuff;
          grainCol = PAL.satinHoney;
          scorchStr = 0.38;
        } else if (sidePick < 0.55) {
          baseCol = PAL.satinGold;
          grainCol = PAL.walnutWarm;
          scorchStr = 0.46;
        } else if (sidePick < 0.80) {
          baseCol = PAL.walnutLight;
          grainCol = PAL.walnutDark;
          scorchStr = 0.54;
        } else {
          baseCol = PAL.walnutWarm;
          grainCol = PAL.rosewoodDeep;
          scorchStr = 0.62;
        }
        if ((i * 3 + rIdx) % 3 === 0) {
          hasSpeckle = true;
          speckleType = "crownTwinDot";
        }
      }

      // Grain runs deliberately along the feather axis with subtle marquetry variation
      let grainAngle = aCenter + random(-9, 9);
      // Hot-sand scorching darkens the base of the feather (where it tucks under the inner ring)
      let scorchAngle = aCenter + 180 + random(-12, 12);

      drawVeneerPiece(clipped, {
        baseCol: baseCol,
        grainCol: grainCol,
        grainAngle: grainAngle,
        grainDist: isBreast ? 5.8 : 5.2,
        scorchCol: scorchCol,
        scorchAngle: scorchAngle,
        scorchStrength: scorchStr,
        seamWeight: 0.44,
        speckleType: hasSpeckle ? speckleType : "none",
        featherAxis: aCenter,
        tipPt: pTip,
        basePt: pBaseC
      });
    }
  }
}

// =============================================================================
// THE 3-RING BRAIDED HEART RUFF (Framing the Facial Disc)
// =============================================================================
function drawHeartRuff(fullHeartLoop) {
  const N = fullHeartLoop.length; // 72 segments
  const cx = 600, cy = 505;

  function ruffRingPoint(idx, dOut) {
    let normIdx = ((idx % N) + N) % N;
    let i0 = floor(normIdx);
    let i1 = (i0 + 1) % N;
    let frac = normIdx - i0;
    let hx = lerp(fullHeartLoop[i0][0], fullHeartLoop[i1][0], frac);
    let hy = lerp(fullHeartLoop[i0][1], fullHeartLoop[i1][1], frac);

    let ang = atan2(hy - cy, hx - cx);
    // Smooth the top V-notch slightly across the ruff thickness
    let topDiff = abs(((ang + 90 + 180) % 360) - 180);
    let notchLift = topDiff < 25 ? map(topDiff, 0, 25, 1, 0) * dOut * 0.25 : 0;

    return [
      hx + cos(ang) * dOut,
      hy + sin(ang) * dOut - notchLift
    ];
  }

  // Draw from Outer Ruff Ring (Ring 2) inward to Inner Ruff Ring (Ring 0)
  const ruffBounds = [
    { dIn: 0,  dOut: 22, step: 1, stagger: 0.0 }, // Ring 0: Inner sawtooth rim
    { dIn: 22, dOut: 54, step: 1, stagger: 0.5 }, // Ring 1: Main braided dark ruff
    { dIn: 54, dOut: 86, step: 1, stagger: 0.0 }  // Ring 2: Outer golden-walnut collar
  ];

  for (let r = 2; r >= 0; r--) {
    let cfg = ruffBounds[r];
    for (let i = 0; i < N; i++) {
      let s0 = i + cfg.stagger;
      let s1 = i + 1 + cfg.stagger;
      let sMid = (s0 + s1) * 0.5;

      let pInL  = ruffRingPoint(s0, cfg.dIn);
      let pInR  = ruffRingPoint(s1, cfg.dIn);
      let pOutR = ruffRingPoint(s1, cfg.dOut);
      let pOutM = ruffRingPoint(sMid, cfg.dOut + (r === 1 ? 6 : 4));
      let pOutL = ruffRingPoint(s0, cfg.dOut);

      let pts = [pInL, pInR, pOutR, pOutM, pOutL];
      let cent = polyCentroid(pts);
      let radialAng = atan2(cent[1] - cy, cent[0] - cx);

      let baseCol, grainCol, scorchCol = PAL.ebony;
      let scorchStr = 0.65;

      if (r === 0) {
        // Inner sawtooth ring: high-contrast alternating dark rosewood & bright satinwood
        if (i % 2 === 0) {
          baseCol = PAL.rosewoodDeep;
          grainCol = PAL.ebony;
          scorchStr = 0.72;
        } else if (i % 4 === 1) {
          baseCol = PAL.satinLight;
          grainCol = PAL.walnutDeep;
          scorchCol = PAL.rosewoodDeep;
          scorchStr = 0.55;
        } else {
          baseCol = PAL.walnutWarm;
          grainCol = PAL.rosewoodDark;
          scorchStr = 0.62;
        }
      } else if (r === 1) {
        // Middle braided ring: rich dark walnut, ebony, rosewood & warm carnelian accents
        let mod = (i + floor(cent[1] * 0.05)) % 5;
        if (mod === 0) {
          baseCol = PAL.ebony;
          grainCol = PAL.walnutWarm;
          scorchStr = 0.75;
        } else if (mod === 1) {
          baseCol = PAL.satinGold;
          grainCol = PAL.walnutDark;
          scorchCol = PAL.rosewoodDark;
          scorchStr = 0.62;
        } else if (mod === 2) {
          baseCol = PAL.rosewoodDeep;
          grainCol = PAL.ebonyAbyss;
          scorchStr = 0.70;
        } else if (mod === 3) {
          // Subtle warm carnelian-rosewood heartwood tile in the ruff braid
          baseCol = (i % 3 === 0) ? PAL.accentDark : PAL.walnutDeep;
          grainCol = PAL.rosewoodDark;
          scorchStr = 0.68;
        } else {
          baseCol = PAL.walnutLight;
          grainCol = PAL.rosewoodDeep;
          scorchStr = 0.60;
        }
      } else {
        // Outer collar ring: golden honey satinwood, sycamore & toasted walnut
        let mod = i % 3;
        if (mod === 0) {
          baseCol = PAL.satinLight;
          grainCol = PAL.walnutWarm;
          scorchCol = PAL.walnutDark;
          scorchStr = 0.48;
        } else if (mod === 1) {
          baseCol = PAL.walnutLight;
          grainCol = PAL.rosewoodLight;
          scorchCol = PAL.rosewoodDeep;
          scorchStr = 0.54;
        } else {
          baseCol = PAL.sycamoreBuff;
          grainCol = PAL.satinDeep;
          scorchCol = PAL.walnutDeep;
          scorchStr = 0.45;
        }
      }

      // Chevron braided grain orientation
      let chevronTilt = ((i % 2 === 0) ? 32 : -32);
      drawVeneerPiece(pts, {
        baseCol: baseCol,
        grainCol: grainCol,
        grainAngle: radialAng + chevronTilt,
        grainDist: 3.8,
        scorchCol: scorchCol,
        scorchAngle: radialAng + 180,
        scorchStrength: scorchStr,
        seamWeight: 0.48,
        noCathedral: true
      });
    }
  }
}

// =============================================================================
// RADIATING FACIAL DISC BOWLS (Concave Radial Veneer Flutes)
// =============================================================================
function drawFacialDiscSide(eyeCenter, discOuterLoop, sideSign) {
  // sideSign: -1 for Left Disc, +1 for Right Disc
  const N_RAYS = 32;
  const rInner = 43; // Starts just inside the eyelid caruncle ring

  // Precompute curved radial rays from eyeCenter out to discOuterLoop
  const rays = [];
  for (let i = 0; i <= N_RAYS; i++) {
    let ang = (i / N_RAYS) * 360;
    let dx = cos(ang), dy = sin(ang);
    let outerHit = rayLoopIntersection(eyeCenter.x, eyeCenter.y, dx, dy, discOuterLoop);
    let totalR = dist(eyeCenter.x, eyeCenter.y, outerHit[0], outerHit[1]);

    // Natural radial feather S-bow perpendicular to the ray (vanishes at s=0 and s=1)
    let perpX = -dy * sideSign;
    let perpY = dx * sideSign;
    let bowAmp = sin((ang - 90) * 1.2) * 10;

    rays.push({
      ang: ang,
      totalR: totalR,
      pointAt: function(s) {
        let r = lerp(rInner, totalR, s);
        let bow = sin(s * 180) * bowAmp * s;
        return [
          eyeCenter.x + dx * r + perpX * bow,
          eyeCenter.y + dy * r + perpY * bow
        ];
      }
    });
  }

  // Radial ring subdivisions from eye socket (s=0) to heart ruff / medial bridge (s=1)
  // Ring 0: Eyelid caruncle beads [0.00 .. 0.08]
  // Ring 1: Orbital mask [0.08 .. 0.24]
  // Ring 2: Inner concave disc [0.24 .. 0.50]
  // Ring 3: Mid concave cheek bowl [0.50 .. 0.77]
  // Ring 4: Outer disc flute rim [0.77 .. 1.00]
  const sRings = [0.00, 0.085, 0.24, 0.50, 0.77, 1.00];

  // Draw from outer ring (Ring 4) inward to Ring 0 so inner rings sit cleanly inside
  for (let rIdx = sRings.length - 2; rIdx >= 0; rIdx--) {
    let s0 = sRings[rIdx];
    let s1 = sRings[rIdx + 1];
    let sMid = (s0 + s1) * 0.5;

    for (let i = 0; i < N_RAYS; i++) {
      let rayA = rays[i];
      let rayB = rays[i + 1];

      // 6-vertex curved radial quad
      let p0 = rayA.pointAt(s0);
      let p1 = rayA.pointAt(sMid);
      let p2 = rayA.pointAt(s1);
      let p3 = rayB.pointAt(s1);
      let p4 = rayB.pointAt(sMid);
      let p5 = rayB.pointAt(s0);

      let pts = [p0, p1, p2, p3, p4, p5];
      let cent = polyCentroid(pts);
      let midAng = rayA.ang + (360 / N_RAYS) * 0.5;

      // Determine anatomical position relative to the medial tear-duct (anterior canthus)
      // For right eye (+1), medial direction is ~172 deg (west-southwest toward beak).
      // For left eye (-1), medial direction is ~8 deg (east-southeast toward beak).
      let medialTargetAng = (sideSign > 0) ? 166 : 14;
      let angToMedial = abs(((midAng - medialTargetAng + 180) % 360 + 360) % 360 - 180);
      let isTearPatch = angToMedial < 52;

      let baseCol, grainCol, scorchCol = PAL.walnutDeep;
      let scorchStr = 0.28;
      let scorchAng = midAng + 180;

      if (rIdx === 0) {
        // Ring 0: Eyelid caruncle rim — tiny dark rosewood, walnut & carnelian veneers
        if (i % 3 === 0) {
          baseCol = PAL.rosewoodDark;
          grainCol = PAL.ebony;
        } else if (isTearPatch && i % 2 === 1) {
          baseCol = PAL.accentDark;
          grainCol = PAL.rosewoodDark;
        } else {
          baseCol = PAL.walnutDark;
          grainCol = PAL.rosewoodDeep;
        }
        scorchCol = PAL.ebony;
        scorchStr = 0.65;
      } else if (rIdx === 1) {
        // Ring 1: Orbital ring — dark russet-rosewood tear-patch anteriorly, toasted satinwood laterally
        if (angToMedial < 36) {
          baseCol = (i % 2 === 0) ? PAL.rosewoodLight : PAL.walnutDark;
          grainCol = PAL.rosewoodDark;
          scorchCol = PAL.ebony;
          scorchStr = 0.68;
        } else if (angToMedial < 68) {
          baseCol = (i % 2 === 0) ? PAL.walnutWarm : PAL.satinDeep;
          grainCol = PAL.walnutDark;
          scorchCol = PAL.rosewoodDeep;
          scorchStr = 0.52;
        } else {
          baseCol = (i % 2 === 0) ? PAL.satinLight : PAL.sycamoreBuff;
          grainCol = PAL.walnutLight;
          scorchCol = PAL.walnutDeep;
          scorchStr = 0.42;
        }
      } else if (rIdx === 2) {
        // Ring 2: Inner disc — transitions from warm honey-russet near nose bridge to creamy sycamore
        if (angToMedial < 32) {
          baseCol = (i % 2 === 0) ? PAL.walnutLight : PAL.satinDeep;
          grainCol = PAL.walnutDark;
          scorchCol = PAL.rosewoodLight;
          scorchStr = 0.48;
        } else if (angToMedial < 58) {
          baseCol = (i % 2 === 0) ? PAL.satinLight : PAL.sycamoreWarm;
          grainCol = PAL.satinDeep;
          scorchCol = PAL.walnutWarm;
          scorchStr = 0.34;
        } else {
          baseCol = (i % 3 === 0) ? PAL.sycamoreBright : PAL.sycamoreCream;
          grainCol = PAL.satinGold;
          scorchCol = PAL.satinDeep;
          scorchStr = 0.24;
        }
      } else if (rIdx === 3) {
        // Ring 3: Main concave cheek dish — luminous sycamore cream with subtle 3D light modulation
        // Upper-left brow slope is slightly shaded; lower-outer bowl catches bright light
        let lightCatch = cos(midAng - 45);
        if (lightCatch > 0.25) {
          baseCol = (i % 2 === 0) ? PAL.sycamoreBright : PAL.sycamoreCream;
          grainCol = PAL.satinLight;
          scorchCol = PAL.satinHoney;
          scorchStr = 0.20;
        } else if (angToMedial < 30) {
          baseCol = PAL.sycamoreBuff;
          grainCol = PAL.satinHoney;
          scorchCol = PAL.walnutWarm;
          scorchStr = 0.35;
        } else {
          baseCol = (i % 2 === 0) ? PAL.sycamoreCream : PAL.sycamoreWarm;
          grainCol = PAL.satinGold;
          scorchCol = PAL.walnutLight;
          scorchStr = 0.26;
        }
      } else {
        // Ring 4: Outer disc rim — sycamore cream warming to honey satinwood & scorched at outer ruff edge
        let hitsMedial = (sideSign > 0 && cent[0] < 660) || (sideSign < 0 && cent[0] > 540);
        if (hitsMedial) {
          baseCol = (i % 2 === 0) ? PAL.sycamoreWarm : PAL.satinLight;
          grainCol = PAL.walnutLight;
          scorchCol = PAL.walnutDeep;
          scorchStr = 0.38;
          scorchAng = midAng; // Scorch toward the medial ridge seam
        } else {
          let outerPick = (i + rIdx) % 3;
          if (outerPick === 0) {
            baseCol = PAL.satinLight;
            grainCol = PAL.walnutLight;
          } else if (outerPick === 1) {
            baseCol = PAL.sycamoreBuff;
            grainCol = PAL.satinDeep;
          } else {
            baseCol = PAL.satinGold;
            grainCol = PAL.walnutWarm;
          }
          scorchCol = PAL.rosewoodLight;
          scorchStr = 0.56;
          scorchAng = midAng; // Heavy hot-sand scorch along the outer heart rim!
        }
      }

      drawVeneerPiece(pts, {
        baseCol: baseCol,
        grainCol: grainCol,
        grainAngle: midAng + random(-3, 3), // Strictly radial pencil wood grain!
        grainDist: rIdx === 0 ? 3.2 : (rIdx <= 2 ? 4.2 : 4.8),
        scorchCol: scorchCol,
        scorchAngle: scorchAng,
        scorchStrength: scorchStr,
        seamWeight: rIdx === 0 ? 0.36 : 0.42,
        noCathedral: rIdx <= 1
      });
    }
  }
}

// =============================================================================
// MEDIAL FOREHEAD RIDGE, LORAL BRISTLES, HOOKED BEAK & CHIN KEYSTONE
// =============================================================================
function drawMedialSpineAndBeak(medialHalfWidth) {
  // 1. BOOK-MATCHED FOREHEAD & NOSE-BRIDGE CHEVRONS (y = 236 .. 535)
  const N_BRIDGE = 12;
  for (let i = 0; i < N_BRIDGE; i++) {
    let y0 = lerp(236, 535, i / N_BRIDGE);
    let y1 = lerp(236, 535, (i + 1) / N_BRIDGE);
    let w0 = medialHalfWidth(y0);
    let w1 = medialHalfWidth(y1);
    let chevDip = 12;

    // Left chevron veneer
    let leftPts = [
      [600 - w0, y0],
      [600, y0 + chevDip],
      [600, y1 + chevDip],
      [600 - w1, y1]
    ];
    // Right book-matched chevron veneer
    let rightPts = [
      [600, y0 + chevDip],
      [600 + w0, y0],
      [600 + w1, y1],
      [600, y1 + chevDip]
    ];

    let isLight = (i % 2 === 0);
    let lCol = isLight ? PAL.satinLight : PAL.walnutLight;
    let rCol = isLight ? PAL.satinGold  : PAL.walnutWarm;
    let gCol = isLight ? PAL.walnutWarm : PAL.rosewoodLight;

    drawVeneerPiece(leftPts, {
      baseCol: lCol,
      grainCol: gCol,
      grainAngle: -52,
      grainDist: 3.8,
      scorchCol: PAL.rosewoodDeep,
      scorchAngle: 180,
      scorchStrength: 0.48,
      seamWeight: 0.44,
      noCathedral: true
    });

    drawVeneerPiece(rightPts, {
      baseCol: rCol,
      grainCol: gCol,
      grainAngle: 52,
      grainDist: 3.8,
      scorchCol: PAL.rosewoodDeep,
      scorchAngle: 0,
      scorchStrength: 0.48,
      seamWeight: 0.44,
      noCathedral: true
    });
  }

  // 2. LOWER CHIN KEYSTONE CHEVRONS BELOW BEAK (y = 748 .. 862)
  const N_CHIN = 4;
  for (let i = 0; i < N_CHIN; i++) {
    let y0 = lerp(748, 862, i / N_CHIN);
    let y1 = lerp(748, 862, (i + 1) / N_CHIN);
    let w0 = max(3, medialHalfWidth(y0));
    let w1 = max(2, medialHalfWidth(y1));

    let leftChin = [
      [600 - w0, y0],
      [600, y0 + 5],
      [600, y1],
      [600 - w1, y1]
    ];
    let rightChin = [
      [600, y0 + 5],
      [600 + w0, y0],
      [600 + w1, y1],
      [600, y1]
    ];

    let chinCol = (i === 0) ? PAL.rosewoodDeep : ((i % 2 === 1) ? PAL.sycamoreWarm : PAL.satinLight);
    let chinGrain = (i === 0) ? PAL.ebony : PAL.walnutWarm;

    drawVeneerPiece(leftChin, {
      baseCol: chinCol,
      grainCol: chinGrain,
      grainAngle: -65,
      grainDist: 3.6,
      scorchCol: PAL.rosewoodDark,
      scorchAngle: -90,
      scorchStrength: i === 0 ? 0.8 : 0.45,
      seamWeight: 0.42,
      noCathedral: true
    });
    drawVeneerPiece(rightChin, {
      baseCol: chinCol,
      grainCol: chinGrain,
      grainAngle: 65,
      grainDist: 3.6,
      scorchCol: PAL.rosewoodDark,
      scorchAngle: -90,
      scorchStrength: i === 0 ? 0.8 : 0.45,
      seamWeight: 0.42,
      noCathedral: true
    });
  }

  // 3. LORAL WHISKER PLUMES & SCULPTURAL HOOKED BEAK (y = 528 .. 756)
  // Upper loral feather splinters framing the cere
  const loralPairs = [
    { yTop: 528, yBot: 585, xInTop: 0,  xInBot: 11, xOutTop: 31, xOutBot: 42, col: PAL.sycamoreCream, ang: 68 },
    { yTop: 575, yBot: 632, xInTop: 11, xInBot: 14, xOutTop: 42, xOutBot: 41, col: PAL.sycamoreWarm,  ang: 74 },
    { yTop: 622, yBot: 678, xInTop: 14, xInBot: 12, xOutTop: 41, xOutBot: 28, col: PAL.sycamoreBuff,  ang: 80 }
  ];

  for (let lp of loralPairs) {
    let lPoly = [
      [600 - lp.xInTop,  lp.yTop],
      [600 - lp.xOutTop, lp.yTop + 6],
      [600 - lp.xOutBot, lp.yBot],
      [600 - lp.xInBot,  lp.yBot + 8]
    ];
    let rPoly = lPoly.map(p => [1200 - p[0], p[1]]);

    drawVeneerPiece(lPoly, {
      baseCol: lp.col,
      grainCol: PAL.satinDeep,
      grainAngle: 180 - lp.ang,
      grainDist: 3.6,
      scorchCol: PAL.walnutDeep,
      scorchAngle: 180,
      scorchStrength: 0.42,
      seamWeight: 0.44,
      noCathedral: true
    });
    drawVeneerPiece(rPoly, {
      baseCol: lp.col,
      grainCol: PAL.satinDeep,
      grainAngle: lp.ang,
      grainDist: 3.6,
      scorchCol: PAL.walnutDeep,
      scorchAngle: 0,
      scorchStrength: 0.42,
      seamWeight: 0.44,
      noCathedral: true
    });
  }

  // Lateral mandible plates of the beak (warm boxwood / honey satinwood)
  const leftMandible = [
    [589, 578],
    [586, 632],
    [572, 678],
    [585, 724],
    [600, 754],
    [594, 665]
  ];
  const rightMandible = leftMandible.map(p => [1200 - p[0], p[1]]);

  drawVeneerPiece(leftMandible, {
    baseCol: PAL.satinLight,
    grainCol: PAL.walnutWarm,
    grainAngle: 82,
    grainDist: 3.5,
    scorchCol: PAL.rosewoodDeep,
    scorchAngle: 165,
    scorchStrength: 0.62,
    seamWeight: 0.48,
    noCathedral: true
  });
  drawVeneerPiece(rightMandible, {
    baseCol: PAL.satinGold,
    grainCol: PAL.walnutDeep,
    grainAngle: 98,
    grainDist: 3.5,
    scorchCol: PAL.rosewoodDeep,
    scorchAngle: 15,
    scorchStrength: 0.65,
    seamWeight: 0.48,
    noCathedral: true
  });

  // Central dorsal culmen ridge of the beak (polished ivory-sycamore highlight)
  const culmenUpper = [
    [600, 556],
    [589, 580],
    [593, 665],
    [600, 682],
    [607, 665],
    [611, 580]
  ];
  drawVeneerPiece(culmenUpper, {
    baseCol: PAL.sycamoreBright,
    grainCol: PAL.satinLight,
    grainAngle: 90,
    grainDist: 3.4,
    scorchCol: PAL.walnutLight,
    scorchAngle: -90,
    scorchStrength: 0.25,
    seamWeight: 0.48,
    noCathedral: true
  });

  const culmenTip = [
    [593, 665],
    [600, 682],
    [607, 665],
    [604, 725],
    [600, 756],
    [596, 725]
  ];
  drawVeneerPiece(culmenTip, {
    baseCol: PAL.sycamoreCream,
    grainCol: PAL.walnutLight,
    grainAngle: 90,
    grainDist: 3.2,
    scorchCol: PAL.rosewoodDeep,
    scorchAngle: 90,
    scorchStrength: 0.55,
    seamWeight: 0.50,
    noCathedral: true
  });
}

// =============================================================================
// MACRO 3D CHIAROSCURO GLAZES (Batched Watercolor/Scorch Shading)
// =============================================================================
function drawMacroScorchGlazes(EL, ER, rightHeartRim, leftHeartRim) {
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.82);

  // Batch 1: Warm caramelized honey glaze along upper brow overhang & medial hollow
  brush.fill(PAL.walnutWarm, 36);
  for (let side of [-1, 1]) {
    let ex = side < 0 ? EL.x : ER.x;
    // Upper brow hollow glaze inside the top lobes of the heart disc
    brush.beginShape(0.45);
    brush.vertex(600 + side * 22, 245);
    brush.vertex(600 + side * 185, 200);
    brush.vertex(600 + side * 330, 275);
    brush.vertex(ex + side * 65, 390);
    brush.vertex(600 + side * 24, 425);
    brush.endShape(true);

    // Lower cheek-to-ruff cup glaze
    brush.beginShape(0.45);
    brush.vertex(600 + side * 370, 490);
    brush.vertex(600 + side * 320, 650);
    brush.vertex(600 + side * 165, 790);
    brush.vertex(600 + side * 120, 735);
    brush.vertex(600 + side * 280, 585);
    brush.endShape(true);
  }

  // Batch 2: Deep scorched rosewood shadow glaze around anterior eye sockets & under beak
  brush.fill(PAL.rosewoodDark, 48);
  for (let side of [-1, 1]) {
    let ex = side < 0 ? EL.x : ER.x;
    let ey = EL.y;
    // Tear-duct / anterior orbital hollow between eye and nose bridge
    brush.beginShape(0.45);
    brush.vertex(ex - side * 25, ey - 58);
    brush.vertex(600 + side * 22, ey - 42);
    brush.vertex(600 + side * 38, ey + 95);
    brush.vertex(ex - side * 10, ey + 78);
    brush.vertex(ex + side * 52, ey + 25);
    brush.vertex(ex + side * 48, ey - 38);
    brush.endShape(true);
  }

  // Deep shadow pocket directly beneath the hooked beak tip
  brush.beginShape(0.35);
  brush.vertex(572, 718);
  brush.vertex(600, 754);
  brush.vertex(628, 718);
  brush.vertex(616, 795);
  brush.vertex(600, 825);
  brush.vertex(584, 795);
  brush.endShape(true);

  // Batch 3: Subtle warm carnelian-amber glow around the inner tear-duct canthus
  brush.fill(PAL.accentMid, 28);
  for (let side of [-1, 1]) {
    let ex = side < 0 ? EL.x : ER.x;
    let ey = EL.y;
    brush.circle(ex - side * 42, ey + 22, 42, 0.25);
  }

  brush.noFill();
}

// =============================================================================
// HYPERREALIST MARQUETRY EYES (Obsidian Ebony, Carnelian Accent & Catchlights)
// =============================================================================
function drawOwlEye(ex, ey, sideSign) {
  // Slight anatomical almond tilt inward toward the beak
  const tilt = sideSign * -11;
  const rx = 43;
  const ry = 40;

  function eyePt(angDeg, radScaleX, radScaleY) {
    let lx = cos(angDeg) * rx * radScaleX;
    let ly = sin(angDeg) * ry * radScaleY;
    // Slight almond pinch at inner and outer canthus (0 and 180 deg)
    let rotX = lx * cos(tilt) - ly * sin(tilt);
    let rotY = lx * sin(tilt) + ly * cos(tilt);
    return [ex + rotX, ey + rotY];
  }

  // 1. Recessed Eyelid Rim Shadow Ring
  const rimPts = [];
  for (let a = 0; a < 360; a += 15) {
    rimPts.push(eyePt(a, 1.06, 1.06));
  }
  drawVeneerPiece(rimPts, {
    baseCol: PAL.rosewoodDark,
    grainCol: PAL.ebonyAbyss,
    grainAngle: tilt,
    grainDist: 3.0,
    scorchCol: PAL.ebonyAbyss,
    scorchAngle: -90,
    scorchStrength: 0.85,
    seamWeight: 0.55,
    noCathedral: true
  });

  // 2. Main Cornea & Pupil Abyss (Macassar Ebony core)
  const corePts = [];
  for (let a = 0; a < 360; a += 15) {
    corePts.push(eyePt(a, 0.95, 0.95));
  }
  drawVeneerPiece(corePts, {
    baseCol: PAL.ebony,
    grainCol: PAL.rosewoodLight,
    grainAngle: 68 * sideSign,
    grainDist: 3.2,
    scorchCol: PAL.ebonyAbyss,
    scorchAngle: -90,
    scorchStrength: 0.75,
    seamWeight: 0.52,
    noCathedral: true
  });

  // 3. THE ACCENT: Glowing Carnelian / Fiery Amber-Garnet Lower-Inner Iris Crescent
  // Positioned along the lower-medial curve where warm light refracts inside the dark eye
  const accentStart = (sideSign < 0) ? 10 : 55;
  const accentEnd   = (sideSign < 0) ? 125 : 170;
  const crescentOuter = [];
  const crescentInner = [];
  for (let a = accentStart; a <= accentEnd; a += 12) {
    crescentOuter.push(eyePt(a, 0.91, 0.91));
    crescentInner.unshift(eyePt(a, 0.56, 0.56));
  }
  const accentCrescentPts = crescentOuter.concat(crescentInner);
  drawVeneerPiece(accentCrescentPts, {
    baseCol: PAL.accentMid,
    grainCol: PAL.accentGlow,
    grainAngle: 45 * sideSign,
    grainDist: 2.6,
    scorchCol: PAL.accentDark,
    scorchAngle: 90,
    scorchStrength: 0.55,
    seamWeight: 0.42,
    noCathedral: true
  });

  // Inner bright fiery amber-gold sliver inside the carnelian crescent
  const glowCrescent = [];
  for (let a = accentStart + 18; a <= accentEnd - 18; a += 12) {
    glowCrescent.push(eyePt(a, 0.82, 0.82));
  }
  for (let a = accentEnd - 18; a >= accentStart + 18; a -= 12) {
    glowCrescent.push(eyePt(a, 0.66, 0.66));
  }
  drawVeneerPiece(glowCrescent, {
    baseCol: PAL.accentGlow,
    grainCol: PAL.sycamoreBright,
    grainAngle: -35 * sideSign,
    grainDist: 2.4,
    scorchCol: PAL.accentMid,
    scorchAngle: 90,
    scorchStrength: 0.35,
    seamWeight: 0.36,
    noCathedral: true
  });

  // 4. Deep Bog-Oak Pupil Center & Upper Eyelid Shadow Overhang
  const pupilPts = [];
  for (let a = 0; a < 360; a += 18) {
    pupilPts.push(eyePt(a, 0.56, 0.56));
  }
  drawVeneerPiece(pupilPts, {
    baseCol: PAL.ebonyAbyss,
    grainCol: PAL.rosewoodDark,
    grainAngle: -75 * sideSign,
    grainDist: 3.0,
    scorchCol: PAL.ebonyAbyss,
    scorchAngle: -90,
    scorchStrength: 0.80,
    seamWeight: 0.40,
    noCathedral: true
  });

  // Upper eyelid cast-shadow crescent across the top of the eyeball
  const lidShadowPts = [];
  for (let a = -165; a <= -15; a += 15) {
    lidShadowPts.push(eyePt(a, 0.94, 0.94));
  }
  for (let a = -15; a >= -165; a -= 15) {
    lidShadowPts.push(eyePt(a, 0.68, 0.52));
  }
  drawVeneerPiece(lidShadowPts, {
    baseCol: PAL.ebonyAbyss,
    grainCol: PAL.rosewoodDark,
    grainAngle: 0,
    grainDist: 3.2,
    scorchCol: PAL.ebonyAbyss,
    scorchAngle: -90,
    scorchStrength: 0.90,
    seamWeight: 0.42,
    noCathedral: true
  });

  // 5. INLAID SPECULAR CATCHLIGHTS (Window-Split Bleached Holly & Sycamore)
  // Upper-left skylight reflection split by a delicate marquetry mullion seam
  const catch1A = [
    eyePt(-142, 0.80, 0.80),
    eyePt(-116, 0.82, 0.82),
    eyePt(-114, 0.50, 0.50),
    eyePt(-140, 0.48, 0.48)
  ];
  const catch1B = [
    eyePt(-111, 0.82, 0.82),
    eyePt(-92,  0.78, 0.78),
    eyePt(-94,  0.52, 0.52),
    eyePt(-110, 0.50, 0.50)
  ];
  drawVeneerPiece(catch1A, {
    baseCol: PAL.sycamoreBright,
    grainCol: PAL.satinLight,
    grainAngle: -45,
    grainDist: 2.5,
    scorchStrength: 0.0,
    seamWeight: 0.36,
    noCathedral: true
  });
  drawVeneerPiece(catch1B, {
    baseCol: PAL.sycamoreCream,
    grainCol: PAL.satinGold,
    grainAngle: -45,
    grainDist: 2.5,
    scorchStrength: 0.0,
    seamWeight: 0.36,
    noCathedral: true
  });

  // Secondary pinpoint diamond catchlight on lower-right rim
  const catch2 = [
    eyePt(35, 0.74, 0.74),
    eyePt(46, 0.80, 0.80),
    eyePt(55, 0.72, 0.72),
    eyePt(44, 0.64, 0.64)
  ];
  drawVeneerPiece(catch2, {
    baseCol: PAL.sycamoreWarm,
    grainCol: PAL.satinGold,
    grainAngle: 45,
    grainDist: 2.5,
    scorchStrength: 0.0,
    seamWeight: 0.32,
    noCathedral: true
  });

  // Wet lower-lid rim highlight glint
  brush.set("2H", PAL.sycamoreWarm, 0.38);
  const wetRim = [];
  for (let a = 35; a <= 145; a += 15) {
    let p = eyePt(a, 0.97, 0.97);
    wetRim.push([p[0], p[1], 0.8]);
  }
  brush.spline(wetRim, 0.4);
}

// =============================================================================
// MARQUETRY PANEL BORDER (Mitered Rosewood Frame & Boxwood/Ebony Stringing)
// =============================================================================
function drawPanelBorder() {
  const W = 1200, H = 1200;
  const B1 = 20; // Outer mitered rosewood frame width
  const B2 = 28; // Inner stringing boundary

  // 4 Mitered Outer Rosewood Frame Strips
  const frameStrips = [
    { pts: [[0, 0], [W, 0], [W - B1, B1], [B1, B1]], ang: 0,   scorchAng: 90 },   // Top
    { pts: [[W, 0], [W, H], [W - B1, H - B1], [W - B1, B1]], ang: 90,  scorchAng: 180 }, // Right
    { pts: [[W, H], [0, H], [B1, H - B1], [W - B1, H - B1]], ang: 0,   scorchAng: -90 }, // Bottom
    { pts: [[0, H], [0, 0], [B1, B1], [B1, H - B1]], ang: 90,  scorchAng: 0 }    // Left
  ];

  for (let fs of frameStrips) {
    drawVeneerPiece(fs.pts, {
      baseCol: PAL.rosewoodDeep,
      grainCol: PAL.ebony,
      grainAngle: fs.ang,
      grainDist: 4.2,
      scorchCol: PAL.ebonyAbyss,
      scorchAngle: fs.scorchAng,
      scorchStrength: 0.65,
      seamWeight: 0.55,
      noCathedral: true
    });
  }

  // Alternating Sycamore & Ebony Geometric Stringing Inlay (between B1=20 and B2=28)
  const N_STR = 38;
  for (let side = 0; side < 4; side++) {
    for (let i = 0; i < N_STR; i++) {
      let t0 = i / N_STR;
      let t1 = (i + 1) / N_STR;
      let s0 = lerp(B1, W - B1, t0);
      let s1 = lerp(B1, W - B1, t1);
      let pts;
      let ang = (side % 2 === 0) ? 0 : 90;

      if (side === 0)      pts = [[s0, B1], [s1, B1], [s1, B2], [s0, B2]];
      else if (side === 1) pts = [[W - B1, s0], [W - B1, s1], [W - B2, s1], [W - B2, s0]];
      else if (side === 2) pts = [[s1, H - B1], [s0, H - B1], [s0, H - B2], [s1, H - B2]];
      else                 pts = [[B1, s1], [B1, s0], [B2, s0], [B2, s1]];

      let isLight = (i % 2 === 0);
      drawVeneerPiece(pts, {
        baseCol: isLight ? PAL.satinLight : PAL.ebony,
        grainCol: isLight ? PAL.walnutWarm : PAL.rosewoodDark,
        grainAngle: ang,
        grainDist: 3.0,
        scorchStrength: 0.0,
        seamWeight: 0.42,
        noCathedral: true,
        skipSecondGrain: true
      });
    }
  }
}

// =============================================================================
// CORE VENEER PIECE RENDERER (Wash + Wood Grain + Hot-Sand Scorch + Knife Seam)
// =============================================================================
function drawVeneerPiece(pts, opts) {
  if (!pts || pts.length < 3) return;
  let area = polyArea(pts);
  if (area < 10) return;

  let poly = new brush.Polygon(pts);
  let cent = polyCentroid(pts);

  // 1. Base Veneer Pigment Wash
  poly.wash(opts.baseCol, opts.washAlpha || 246);

  // 2. Primary Pencil-Hatched Wood Grain
  let gDist = opts.grainDist || 4.8;
  let gAng  = opts.grainAngle || 0;
  brush.hatchStyle("2H", opts.grainCol || PAL.walnutWarm, 0.34);
  poly.hatch(gDist, gAng, {
    rand: 0.05,
    gradient: 0.16
  });

  // 3. Secondary Wood Pore / Figure Grain on medium-to-large pieces
  if (area > 420 && !opts.skipSecondGrain) {
    brush.hatchStyle("HB", opts.scorchCol || PAL.walnutDark, 0.30);
    poly.hatch(gDist * 2.5, gAng + 2.5, {
      rand: 0.11,
      gradient: 0.38
    });
  }

  // 4. Directional Hot-Sand Scorch Gradient Hatching
  let scorchStr = opts.scorchStrength !== undefined ? opts.scorchStrength : 0.35;
  if (scorchStr > 0.08 && area > 180) {
    let sDist = map(constrain(scorchStr, 0.1, 0.9), 0.1, 0.9, 6.2, 3.0);
    brush.hatchStyle("2B", opts.scorchCol || PAL.rosewoodDeep, 0.35 * scorchStr + 0.12);
    poly.hatch(sDist, opts.scorchAngle || 180, {
      rand: 0.08,
      gradient: 0.78
    });
  }

  // 5. Soft Smoky Hot-Sand Scorch Edge Shading (inset inside shadow edges)
  if (scorchStr > 0.15 && area > 140) {
    let insetDist = min(4.2, sqrt(area) * 0.13);
    let sDirX = cos(opts.scorchAngle || 180);
    let sDirY = sin(opts.scorchAngle || 180);

    brush.set("scorch", opts.scorchCol || PAL.rosewoodDeep, 0.65 + scorchStr * 0.65);
    for (let i = 0; i < pts.length; i++) {
      let pA = pts[i];
      let pB = pts[(i + 1) % pts.length];
      let mx = (pA[0] + pB[0]) * 0.5;
      let my = (pA[1] + pB[1]) * 0.5;
      let ex = mx - cent[0];
      let ey = my - cent[1];
      let elen = sqrt(ex * ex + ey * ey) || 1;
      // Check if this edge lies on the scorched side of the veneer piece
      let align = (ex / elen) * sDirX + (ey / elen) * sDirY;
      if (align > -0.15 && dist(pA[0], pA[1], pB[0], pB[1]) > 7) {
        let ia = insetPoint(pA, cent, insetDist);
        let ib = insetPoint(pB, cent, insetDist);
        brush.line(ia[0], ia[1], ib[0], ib[1]);
      }
    }
  }

  // 6. Cathedral Heartwood Grain Arches on larger veneer tiles
  if (area > 950 && !opts.noCathedral) {
    drawCathedralGrainLines(pts, cent, gAng, opts.grainCol || PAL.walnutWarm);
  }

  // 7. Inlaid Feather Speckles (Crown Twin-Dots & Breast Arrow-Flecks)
  if (opts.speckleType && opts.speckleType !== "none" && area > 550) {
    drawInlaidSpeckle(pts, cent, opts);
  }

  // 8. Fine Bevel Highlight Glint along Upper/Lit Edges
  brush.set("2H", PAL.sycamoreBright, 0.28);
  for (let i = 0; i < pts.length; i++) {
    let pA = pts[i];
    let pB = pts[(i + 1) % pts.length];
    let segLen = dist(pA[0], pA[1], pB[0], pB[1]);
    if (segLen < 8) continue;
    let mx = (pA[0] + pB[0]) * 0.5;
    let my = (pA[1] + pB[1]) * 0.5;
    // Lit from upper-left (-0.45, -0.88)
    let nx = mx - cent[0];
    let ny = my - cent[1];
    let nlen = sqrt(nx * nx + ny * ny) || 1;
    if ((nx / nlen) * -0.45 + (ny / nlen) * -0.88 > 0.28) {
      let ia = insetPoint(pA, cent, 1.3);
      let ib = insetPoint(pB, cent, 1.3);
      brush.line(ia[0], ia[1], ib[0], ib[1]);
    }
  }

  // 9. Thin Knife-Cut Joinery Seam around the Polygon Perimeter
  let sw = opts.seamWeight || 0.44;
  poly.draw("rotring", PAL.ebony, sw);
}

// =============================================================================
// CATHEDRAL WOOD FIGURE ARCHES & INLAID FEATHER SPECKLES
// =============================================================================
function drawCathedralGrainLines(pts, cent, grainAngle, col) {
  let ux = cos(grainAngle), uy = sin(grainAngle);
  let px = -uy, py = ux;

  // Estimate span of polygon along and perpendicular to grain
  let maxAlong = 0, maxPerp = 0;
  for (let p of pts) {
    let dx = p[0] - cent[0], dy = p[1] - cent[1];
    maxAlong = max(maxAlong, abs(dx * ux + dy * uy));
    maxPerp  = max(maxPerp,  abs(dx * px + dy * py));
  }

  let L = maxAlong * 0.62;
  let W = maxPerp * 0.42;
  if (L < 8 || W < 4) return;

  brush.set("2H", col, 0.30);
  for (let k of [-0.55, 0.55]) {
    let s1 = [cent[0] - ux * L + px * W * k, cent[1] - uy * L + py * W * k, 0.4];
    let s2 = [cent[0] + ux * L * 0.25 + px * W * k * 0.18, cent[1] + uy * L * 0.25 + py * W * k * 0.18, 0.85];
    let s3 = [cent[0] - ux * L * 0.65 - px * W * k * 0.35, cent[1] - uy * L * 0.65 - py * W * k * 0.35, 0.4];
    brush.spline([s1, s2, s3], 0.55);
  }
}

function drawInlaidSpeckle(pts, cent, opts) {
  let ang = opts.featherAxis !== undefined ? opts.featherAxis : opts.grainAngle;
  let ux = cos(ang), uy = sin(ang);
  let px = -uy, py = ux;

  if (opts.speckleType === "breastFlecks") {
    // Tiny inlaid Macassar ebony arrowhead / diamond fleck on breast veneer
    let fx = cent[0] + ux * 6;
    let fy = cent[1] + uy * 6;
    let fleck = [
      [fx + ux * 7, fy + uy * 7],
      [fx - ux * 2 + px * 4.2, fy - uy * 2 + py * 4.2],
      [fx - ux * 6, fy - uy * 6],
      [fx - ux * 2 - px * 4.2, fy - uy * 2 - py * 4.2]
    ];
    let fPoly = new brush.Polygon(fleck);
    fPoly.wash(PAL.ebony, 245);
    fPoly.draw("rotring", PAL.ebonyAbyss, 0.35);
  } else if (opts.speckleType === "crownTwinDot") {
    // Classic Barn Owl crown/mantle inlay: pale sycamore shaft + dark ebony tip + cream pearl dot
    let sx0 = cent[0] - ux * 10, sy0 = cent[1] - uy * 10;
    let sx1 = cent[0] + ux * 10, sy1 = cent[1] + uy * 10;
    brush.set("2H", PAL.sycamoreBright, 0.36);
    brush.line(sx0, sy0, sx1, sy1);

    // Sub-terminal dark ebony diamond inlay
    let dx = cent[0] + ux * 7, dy = cent[1] + uy * 7;
    let darkDiamond = [
      [dx + ux * 6, dy + uy * 6],
      [dx + px * 4.5, dy + py * 4.5],
      [dx - ux * 5, dy - uy * 5],
      [dx - px * 4.5, dy - py * 4.5]
    ];
    let dPoly = new brush.Polygon(darkDiamond);
    dPoly.wash(PAL.ebony, 245);
    dPoly.draw("rotring", PAL.ebonyAbyss, 0.34);

    // Tiny bleached sycamore diamond inlay just behind the dark tip
    let wx = cent[0] - ux * 2, wy = cent[1] - uy * 2;
    let lightDiamond = [
      [wx + ux * 4.5, wy + uy * 4.5],
      [wx + px * 3.2, wy + py * 3.2],
      [wx - ux * 4.5, wy - uy * 4.5],
      [wx - px * 3.2, wy - py * 3.2]
    ];
    let lPoly = new brush.Polygon(lightDiamond);
    lPoly.wash(PAL.sycamoreBright, 250);
    lPoly.draw("rotring", PAL.walnutDark, 0.32);
  }
}

// =============================================================================
// GEOMETRY & SPLINE UTILITIES
// =============================================================================
function evalCatmullRomChain(pts, t) {
  let n = pts.length - 1;
  let scaled = constrain(t, 0, 1) * n;
  let idx = min(floor(scaled), n - 1);
  let u = scaled - idx;

  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[min(n, idx + 1)];
  let p3 = pts[min(n, idx + 2)];

  let u2 = u * u;
  let u3 = u2 * u;

  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * u +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * u +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3
  );
  return [x, y];
}

function rayLoopIntersection(ox, oy, dx, dy, loopPts) {
  let bestT = Infinity;
  let bestPt = [ox + dx * 200, oy + dy * 200];
  let n = loopPts.length;

  for (let i = 0; i < n; i++) {
    let x1 = loopPts[i][0], y1 = loopPts[i][1];
    let x2 = loopPts[(i + 1) % n][0], y2 = loopPts[(i + 1) % n][1];
    let sx = x2 - x1, sy = y2 - y1;

    let denom = dx * sy - dy * sx;
    if (abs(denom) < 1e-7) continue;

    let rx = x1 - ox, ry = y1 - oy;
    let t = (rx * sy - ry * sx) / denom;
    let u = (rx * dy - ry * dx) / denom;

    if (t > 0.1 && u >= -1e-5 && u <= 1.00001) {
      if (t < bestT) {
        bestT = t;
        bestPt = [ox + dx * t, oy + dy * t];
      }
    }
  }
  return bestPt;
}

function clipPolygonToRect(poly, xmin, ymin, xmax, ymax) {
  function clipEdge(pts, insideFn, intersectFn) {
    let out = [];
    if (pts.length === 0) return out;
    for (let i = 0; i < pts.length; i++) {
      let cur = pts[i];
      let prev = pts[(i + pts.length - 1) % pts.length];
      let curIn = insideFn(cur);
      let prevIn = insideFn(prev);
      if (curIn) {
        if (!prevIn) out.push(intersectFn(prev, cur));
        out.push(cur);
      } else if (prevIn) {
        out.push(intersectFn(prev, cur));
      }
    }
    return out;
  }

  let res = poly;
  res = clipEdge(res, p => p[0] >= xmin, (a, b) => [
    xmin, a[1] + (b[1] - a[1]) * (xmin - a[0]) / ((b[0] - a[0]) || 1e-7)
  ]);
  res = clipEdge(res, p => p[0] <= xmax, (a, b) => [
    xmax, a[1] + (b[1] - a[1]) * (xmax - a[0]) / ((b[0] - a[0]) || 1e-7)
  ]);
  res = clipEdge(res, p => p[1] >= ymin, (a, b) => [
    a[0] + (b[0] - a[0]) * (ymin - a[1]) / ((b[1] - a[1]) || 1e-7), ymin
  ]);
  res = clipEdge(res, p => p[1] <= ymax, (a, b) => [
    a[0] + (b[0] - a[0]) * (ymax - a[1]) / ((b[1] - a[1]) || 1e-7), ymax
  ]);
  return res;
}

function polyArea(pts) {
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    let j = (i + 1) % pts.length;
    a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
  }
  return abs(a) * 0.5;
}

function polyCentroid(pts) {
  let cx = 0, cy = 0;
  for (let p of pts) {
    cx += p[0];
    cy += p[1];
  }
  return [cx / pts.length, cy / pts.length];
}

function insetPoint(pt, cent, distPx) {
  let dx = cent[0] - pt[0];
  let dy = cent[1] - pt[1];
  let d = sqrt(dx * dx + dy * dy) || 1;
  let step = min(distPx, d * 0.45);
  return [pt[0] + (dx / d) * step, pt[1] + (dy / d) * step];
}

// ============================================================================
// HYPERREALISM IN P5.BRUSH: THE HIGH-WIRE STEP
// A tightrope walker's worn leather slipper gripping a frayed steel cable,
// set inside the bold graphics of a vintage circus poster.
// ============================================================================

const PAL = {
  paperBase: "#e6d7bc",
  paperWarm: "#d8c4a0",
  paperDark: "#bfa57c",
  chalkPure: "#fffdf8",
  chalkWarm: "#f5ecda",
  chalkMid: "#dfd1b5",

  // Vintage circus poster triad (muted earth tones)
  crimson: "#8e2c22",
  crimsonLight: "#aa3e30",
  crimsonDark: "#5c1a13",
  mustard: "#c89136",
  mustardLight: "#dca94e",
  mustardDark: "#96671e",
  royal: "#213a56",
  royalLight: "#315175",
  royalDark: "#132235",
  skyDeep: "#0e1826",
  inkDark: "#1c1510",
  inkSepia: "#332419",

  // Worn leather slipper & foot (lit from harsh spotlight below)
  leatherGlare: "#f7eed8",
  leatherHighlight: "#e5ca9e",
  leatherLight: "#cca26e",
  leatherMid: "#a67748",
  leatherWarm: "#8c5d34",
  leatherShadow: "#5c3a20",
  leatherDeep: "#382112",
  leatherCore: "#211209",
  suedeBuff: "#bfa07a",
  suedeRaw: "#6e4c30",
  stitchLinen: "#eee3cc",
  stitchRed: "#7d2b22",

  // Steel cable
  steelDark: "#16181c",
  steelShadow: "#2b2e34",
  steelMid: "#56554f",
  steelWarm: "#7d7668",
  steelLight: "#b5ada0",
  steelGlare: "#ebe4d5"
};

// Cable geometry constants
const CABLE_X1 = 115;
const CABLE_Y1 = 975;
const CABLE_XM = 665;
const CABLE_YM = 589;
const CABLE_X2 = 1085;
const CABLE_Y2 = 250;
const CABLE_R = 17.5;

function getCableY(x) {
  // Piecewise linear with smooth quadratic inflection under the foot's load
  const slopeL = (CABLE_YM - CABLE_Y1) / (CABLE_XM - CABLE_X1); // -0.7018
  const slopeR = (CABLE_Y2 - CABLE_YM) / (CABLE_X2 - CABLE_XM); // -0.8071
  const blendHalf = 75;

  if (x <= CABLE_XM - blendHalf) {
    return CABLE_Y1 + slopeL * (x - CABLE_X1);
  } else if (x >= CABLE_XM + blendHalf) {
    return CABLE_YM + slopeR * (x - CABLE_XM);
  } else {
    const t = (x - (CABLE_XM - blendHalf)) / (2 * blendHalf);
    const x0 = CABLE_XM - blendHalf;
    const y0 = CABLE_Y1 + slopeL * (x0 - CABLE_X1);
    const x2 = CABLE_XM + blendHalf;
    const y2 = CABLE_YM + slopeR * (x2 - CABLE_XM);
    return (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * CABLE_YM + t * t * y2;
  }
}

function getCableAngle(x) {
  const dx = 2;
  const dy = getCableY(x + dx) - getCableY(x - dx);
  return atan2(dy, 2 * dx);
}

function getCableNormal(x) {
  const ang = getCableAngle(x);
  // Downward-right normal (pointing toward the spotlight below)
  return { nx: -sin(ang), ny: cos(ang), ux: cos(ang), uy: sin(ang), ang };
}

function drawClosedShape(pts, curvature = 0.2) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7482);
  noiseSeed(7482);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paperBase);

  // 1. Aged vintage poster paper ground
  drawPaperGround();

  // 2. Loud vintage circus poster graphics: radiating sunburst + coarse spray halftone
  drawCircusSunburstAndHalftone();

  // 3. Deep sky drop beneath the wire + upward theatrical spotlight beam
  drawDeepSkyDrop();

  // 4. Star-studded circus border & inner theatrical drop frame
  drawStarStuddedBorder();

  // 5. The frayed steel cable (main structure, helical bundles, broken wires)
  drawSteelCable();

  // 6. The tightrope walker's ankle & worn leather slipper (obsessive hyperrealism)
  drawFootAndSlipper();

  // 7. Foreground cable strands, frayed wire whiskers & chalk dust clouds in glare
  drawForegroundCableAndChalk();

  // 8. Final distressed poster edge aging & registration marks
  drawPosterAgingDetails();

  noLoop();
}

// ============================================================================
// 1. AGED VINTAGE PAPER GROUND
// ============================================================================
function drawPaperGround() {
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.25);

  brush.fill(PAL.paperWarm, 55);
  brush.rect(40, 40, 1120, 1120);

  // Corner & edge age toning
  const stains = [
    [60, 60, 360, 260],
    [820, 50, 330, 280],
    [50, 860, 360, 290],
    [830, 850, 320, 300]
  ];
  brush.fill(PAL.paperDark, 42);
  for (let s of stains) {
    brush.rect(s[0], s[1], s[2], s[3]);
  }
  brush.noFill();

  // Subtle paper fiber weave
  brush.set("2H", PAL.paperDark, 0.28);
  for (let i = 0; i < 90; i++) {
    const y = random(20, 1180);
    brush.line(random(15, 180), y, random(1020, 1185), y + random(-8, 8));
  }
}

// ============================================================================
// 2. RADIATING SUNBURST BANDS & COARSE SPRAY HALFTONE
// ============================================================================
function drawCircusSunburstAndHalftone() {
  brush.clip([115, 115, 1085, 1085]);

  const cx = 645;
  const cy = 595;
  const numRays = 24;
  const rayRadius = 1150;

  // Sunburst color cycle: Crimson, Cream, Mustard, Cream, Royal Blue, Cream
  const cycle = [
    PAL.crimson,
    PAL.paperBase,
    PAL.mustard,
    PAL.paperBase,
    PAL.royal,
    PAL.paperBase
  ];

  // Batch washes by color for performance and flat marker appearance
  for (let cIdx = 0; cIdx < cycle.length; cIdx++) {
    const col = cycle[cIdx];
    if (col === PAL.paperBase) continue;

    for (let i = cIdx; i < numRays; i += cycle.length) {
      const a1 = i * (360 / numRays) - 8;
      const a2 = (i + 1) * (360 / numRays) - 8;
      const aMid = (a1 + a2) * 0.5;

      // Only draw rays that appear above or near the wire
      const pts = [
        [cx, cy],
        [cx + cos(a1) * rayRadius, cy + sin(a1) * rayRadius],
        [cx + cos(aMid) * rayRadius, cy + sin(aMid) * rayRadius],
        [cx + cos(a2) * rayRadius, cy + sin(a2) * rayRadius]
      ];

      brush.noStroke();
      brush.wash(col, 215);
      drawClosedShape(pts, 0.02);
      brush.noWash();

      // Flat marker radial fill strokes for authentic marker streak texture
      brush.set("marker", col, 1.8);
      const subRays = 6;
      for (let r = 1; r < subRays; r++) {
        const ang = lerp(a1, a2, r / subRays);
        brush.line(
          cx + cos(ang) * 70,
          cy + sin(ang) * 70,
          cx + cos(ang) * 820,
          cy + sin(ang) * 820
        );
      }
    }
  }

  // Crisp woodblock/litho ink rules along ray dividers
  brush.set("rotring", PAL.inkSepia, 0.45);
  for (let i = 0; i < numRays; i++) {
    const a = i * (360 / numRays) - 8;
    brush.line(
      cx + cos(a) * 90,
      cy + sin(a) * 90,
      cx + cos(a) * 780,
      cy + sin(a) * 780
    );
  }

  // Coarse spray halftone fading the sunburst bands toward the outer edges
  // Pass 1: Spray brush grain concentrated toward the outer perimeter
  const edgeColors = [PAL.paperBase, PAL.paperWarm, PAL.paperDark];
  for (let pass = 0; pass < 3; pass++) {
    brush.set("spray", edgeColors[pass], 1.6 + pass * 0.4);
    for (let i = 0; i < 65; i++) {
      const ang = random(-195, 25); // Upper hemisphere above wire
      const dist = random(380, 680);
      const px = cx + cos(ang) * dist;
      const py = cy + sin(ang) * dist;
      if (px > 105 && px < 1095 && py > 105 && py < getCableY(px) + 15) {
        const segLen = random(45, 110);
        brush.line(
          px,
          py,
          px + cos(ang + 90) * segLen,
          py + sin(ang + 90) * segLen
        );
      }
    }
  }

  // Pass 2: Explicit vintage coarse halftone dot grid near the edges
  const gridStep = 19;
  for (let gx = 128; gx <= 1072; gx += gridStep) {
    for (let gy = 128; gy <= 960; gy += gridStep) {
      const wireY = getCableY(gx);
      if (gy > wireY - 8) continue;

      const dCenter = dist(gx, gy, cx, cy);
      const dEdge = min(
        min(gx - 115, 1085 - gx),
        min(gy - 115, wireY - gy)
      );

      // Fade bands toward outer frame edges with paper-colored halftone dots,
      // and scatter colored halftone dots inward
      if (dCenter > 330 || dEdge < 140) {
        const fadeFactor = constrain(
          map(dCenter, 320, 620, 0.15, 0.95) + map(dEdge, 140, 0, 0, 0.55),
          0.1,
          1.0
        );
        if (random() < fadeFactor) {
          const jitterX = gx + ((gy / gridStep) % 2) * (gridStep * 0.5);
          const dotR = map(fadeFactor, 0.1, 1.0, 2.2, 6.8);
          brush.set("marker", PAL.paperBase, dotR * 0.36);
          brush.line(jitterX - 1, gy, jitterX + 1, gy);
        }
      }
    }
  }

  // Pass 3: Dark sepia & crimson halftone stipple near corners for vintage print grit
  brush.set("spray", PAL.inkSepia, 1.1);
  for (let i = 0; i < 45; i++) {
    const cornerX = i % 2 === 0 ? random(115, 360) : random(820, 1085);
    const cornerY = random(115, 340);
    brush.line(cornerX, cornerY, cornerX + random(-35, 35), cornerY + random(-25, 25));
  }

  brush.noClip();
}

// ============================================================================
// 3. DEEP SKY DROP BENEATH THE WIRE & HARSH UPWARD SPOTLIGHT
// ============================================================================
function drawDeepSkyDrop() {
  brush.clip([115, 115, 1085, 1085]);

  // Build polygon for the region beneath the diagonal cable
  const skyPoly = [];
  for (let x = 115; x <= 1085; x += 25) {
    skyPoly.push([x, getCableY(x) + 4]);
  }
  skyPoly.push([1085, 1085]);
  skyPoly.push([115, 1085]);

  // Solid deep nocturnal Prussian sky base wash
  brush.noStroke();
  brush.wash(PAL.royalDark, 245);
  drawClosedShape(skyPoly, 0.02);
  brush.noWash();

  // Deep sky watercolor & marker tonal variation
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.3);
  brush.fill(PAL.skyDeep, 170);
  drawClosedShape(
    [
      [115, 995],
      [480, 740],
      [420, 1085],
      [115, 1085]
    ],
    0.05
  );
  drawClosedShape(
    [
      [830, 470],
      [1085, 260],
      [1085, 1085],
      [890, 1085]
    ],
    0.05
  );
  brush.noFill();

  // Vertical painted canvas sky-drop texture strokes in dark indigo & slate
  brush.set("marker", PAL.royal, 1.4);
  for (let x = 130; x <= 1070; x += 18) {
    const topY = getCableY(x) + 18;
    if (topY < 1065) {
      brush.line(x, topY, x, min(1075, topY + random(140, 480)));
    }
  }

  // Coarse halftone spray along the bottom & side edges of the sky drop
  brush.set("spray", PAL.skyDeep, 1.8);
  for (let i = 0; i < 55; i++) {
    const sx = random(120, 1080);
    const sy = random(max(getCableY(sx) + 40, 750), 1080);
    brush.line(sx, sy, sx + random(-50, 50), sy + random(-20, 20));
  }

  // ---- HARSH THEATRICAL SPOTLIGHT CONE FROM BELOW ----
  // Spotlight originates at (690, 1140) and blasts upward onto the slipper & wire
  const spotX = 695;
  const spotY = 1150;

  // Outer warm ochre glow cone
  const coneOuter = [
    [spotX - 150, 1085],
    [355, getCableY(355) + 4],
    [855, getCableY(855) + 4],
    [spotX + 160, 1085]
  ];
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.15);
  brush.fill(PAL.mustard, 68);
  drawClosedShape(coneOuter, 0.05);

  // Mid spotlight beam
  const coneMid = [
    [spotX - 95, 1085],
    [435, getCableY(435) + 4],
    [810, getCableY(810) + 4],
    [spotX + 105, 1085]
  ];
  brush.fill(PAL.leatherHighlight, 88);
  drawClosedShape(coneMid, 0.05);

  // Intense core theatrical glare directly beneath the arch & gripping ball
  const coneCore = [
    [spotX - 45, 1085],
    [510, getCableY(510) + 4],
    [765, getCableY(765) + 4],
    [spotX + 55, 1085]
  ];
  brush.fill(PAL.chalkWarm, 110);
  drawClosedShape(coneCore, 0.05);
  brush.noFill();

  // Radiant light rays shooting up from the spotlight
  for (let i = 0; i < 68; i++) {
    const t = i / 67;
    const targetX = lerp(365, 845, t);
    const targetY = getCableY(targetX) + 6;
    const startX = lerp(spotX - 110, spotX + 110, t);
    const startY = 1080;

    const distFromCore = abs(t - 0.54);
    const col =
      distFromCore < 0.22
        ? PAL.chalkPure
        : distFromCore < 0.38
        ? PAL.leatherHighlight
        : PAL.mustardLight;
    const w = map(distFromCore, 0, 0.55, 0.75, 0.25);

    brush.set("2H", col, w);
    brush.line(
      lerp(startX, targetX, random(0.05, 0.35)),
      lerp(startY, targetY, random(0.05, 0.35)),
      targetX,
      targetY
    );
  }

  // Distant celestial stars & vintage poster constellations in the dark sky drop
  const skyStars = [
    [210, 995, 11],
    [295, 920, 8],
    [350, 1015, 9],
    [890, 620, 12],
    [975, 510, 10],
    [1015, 680, 14],
    [920, 795, 9],
    [1010, 875, 11],
    [885, 965, 13],
    [995, 1010, 9],
    [1035, 395, 10]
  ];
  for (let st of skyStars) {
    drawFourPointStar(st[0], st[1], st[2], PAL.mustardLight, PAL.chalkWarm);
  }

  // Tiny background stardust dots in the dark sky drop
  brush.set("rotring", PAL.paperWarm, 0.55);
  for (let i = 0; i < 85; i++) {
    const sx = random() < 0.35 ? random(145, 430) : random(835, 1060);
    const minY = getCableY(sx) + 45;
    if (minY < 1055) {
      const sy = random(minY, 1060);
      brush.line(sx - 1, sy, sx + 1, sy);
    }
  }

  // Inner ornamental gold-ochre scalloped frame along the deep sky drop perimeter
  const inset = 142;
  brush.set("rotring", PAL.mustardLight, 0.75);
  brush.line(inset, getCableY(inset) + 28, inset, 1058);
  brush.line(inset, 1058, 1058, 1058);
  brush.line(1058, getCableY(1058) + 28, 1058, 1058);

  brush.set("rotring", PAL.crimsonLight, 0.55);
  brush.line(inset + 6, getCableY(inset + 6) + 32, inset + 6, 1052);
  brush.line(inset + 6, 1052, 1052, 1052);
  brush.line(1052, getCableY(1052) + 32, 1052, 1052);

  brush.noClip();
}

function drawFourPointStar(x, y, r, colOuter, colInner) {
  brush.set("rotring", colOuter, 0.55);
  brush.line(x - r, y, x + r, y);
  brush.line(x, y - r, x, y + r);
  const d = r * 0.45;
  brush.line(x - d, y - d, x + d, y + d);
  brush.line(x - d, y + d, x + d, y - d);
  brush.set("marker", colInner, 0.6);
  brush.line(x - 1, y, x + 1, y);
}

// ============================================================================
// 4. STAR-STUDDED VINTAGE CIRCUS BORDER
// ============================================================================
function drawStarStuddedBorder() {
  const outer = 55;
  const inner = 115;

  // Four dark indigo-espresso border strips framing the poster
  brush.noStroke();
  brush.wash(PAL.royalDark, 245);
  brush.rect(outer, outer, 1200 - 2 * outer, inner - outer); // Top
  brush.rect(outer, 1200 - inner, 1200 - 2 * outer, inner - outer); // Bottom
  brush.rect(outer, inner, inner - outer, 1200 - 2 * inner); // Left
  brush.rect(1200 - inner, inner, inner - outer, 1200 - 2 * inner); // Right
  brush.noWash();

  // Crimson inner & outer trim bands
  brush.set("marker", PAL.crimson, 2.2);
  brush.rect(outer + 4, outer + 4, 1200 - 2 * (outer + 4), 1200 - 2 * (outer + 4));
  brush.rect(inner - 4, inner - 4, 1200 - 2 * (inner - 4), 1200 - 2 * (inner - 4));

  // Mustard ochre pinstripe rules
  brush.set("rotring", PAL.mustardLight, 0.85);
  brush.rect(outer + 9, outer + 9, 1200 - 2 * (outer + 9), 1200 - 2 * (outer + 9));
  brush.rect(inner - 9, inner - 9, 1200 - 2 * (inner - 9), 1200 - 2 * (inner - 9));

  // Heavy dark ink outer & inner structural borders
  brush.set("rotring", PAL.inkDark, 1.3);
  brush.rect(outer, outer, 1200 - 2 * outer, 1200 - 2 * outer);
  brush.rect(inner, inner, 1200 - 2 * inner, 1200 - 2 * inner);

  // Star-studded perimeter: 5-pointed circus stars along all four bands
  const bandMid = (outer + inner) * 0.5; // 85
  const starCount = 11;
  for (let i = 1; i < starCount; i++) {
    const pos = lerp(85, 1115, i / starCount);
    const col = i % 2 === 0 ? PAL.paperBase : PAL.mustardLight;
    drawFivePointStar(pos, bandMid, 16, 7, col, -90); // Top
    drawFivePointStar(pos, 1200 - bandMid, 16, 7, col, -90); // Bottom
    drawFivePointStar(bandMid, pos, 16, 7, col, -90); // Left
    drawFivePointStar(1200 - bandMid, pos, 16, 7, col, -90); // Right

    // Small diamond studs between stars
    if (i < starCount) {
      const midPos = lerp(85, 1115, (i + 0.5) / starCount);
      brush.set("marker", PAL.crimsonLight, 0.8);
      brush.line(midPos - 2, bandMid, midPos + 2, bandMid);
      brush.line(midPos - 2, 1200 - bandMid, midPos + 2, 1200 - bandMid);
      brush.line(bandMid, midPos - 2, bandMid, midPos + 2);
      brush.line(1200 - bandMid, midPos - 2, 1200 - bandMid, midPos + 2);
    }
  }

  // Four Corner Circus Rosettes
  const corners = [
    [bandMid, bandMid],
    [1200 - bandMid, bandMid],
    [1200 - bandMid, 1200 - bandMid],
    [bandMid, 1200 - bandMid]
  ];
  for (let c of corners) {
    brush.noStroke();
    brush.wash(PAL.crimson, 240);
    brush.circle(c[0], c[1], 24);
    brush.noWash();

    brush.set("rotring", PAL.mustardLight, 0.8);
    brush.circle(c[0], c[1], 24);
    brush.circle(c[0], c[1], 19);
    drawFivePointStar(c[0], c[1], 17, 7, PAL.paperBase, -90);
  }
}

function drawFivePointStar(cx, cy, rOut, rIn, fillCol, rotDeg = -90) {
  const pts = [];
  for (let i = 0; i < 10; i++) {
    const r = i % 2 === 0 ? rOut : rIn;
    const a = rotDeg + i * 36;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  brush.noStroke();
  brush.wash(fillCol, 235);
  drawClosedShape(pts, 0.01);
  brush.noWash();

  // Crisp ink bevel lines for vintage lithograph star look
  brush.set("rotring", PAL.inkDark, 0.45);
  drawClosedShape(pts, 0.01);
  for (let i = 0; i < 5; i++) {
    const a = rotDeg + i * 72;
    brush.line(cx, cy, cx + cos(a) * rOut, cy + sin(a) * rOut);
  }
}

// ============================================================================
// 5. HYPERREALISTIC FRAYED STEEL CABLE
// ============================================================================
function drawSteelCable() {
  brush.clip([115, 115, 1085, 1085]);

  // 1. Base cylindrical body of the cable
  const upperEdge = [];
  const lowerEdge = [];
  const midLine = [];
  for (let x = 110; x <= 1090; x += 20) {
    const cy = getCableY(x);
    const n = getCableNormal(x);
    upperEdge.push([x - n.nx * CABLE_R, cy - n.ny * CABLE_R]);
    lowerEdge.unshift([x + n.nx * CABLE_R, cy + n.ny * CABLE_R]);
    midLine.push([x + n.nx * 2, cy + n.ny * 2]);
  }

  // Dark steel shadow base
  brush.noStroke();
  brush.wash(PAL.steelShadow, 250);
  drawClosedShape(upperEdge.concat(lowerEdge), 0.05);

  // Lit lower half of the cylinder (catching the harsh spotlight from below)
  const lowerLitPoly = midLine.concat(lowerEdge);
  brush.wash(PAL.steelWarm, 210);
  drawClosedShape(lowerLitPoly, 0.05);
  brush.noWash();

  // 2. Helical twisted wire bundles (7x19 wire rope lay)
  // Step along the cable in laying intervals to render individual twisted rope strands
  const strandPitch = 22; // Distance between helical rope bundles
  const layShift = 30; // Horizontal advance of each S-twist across the cable diameter

  for (let xBase = 95; xBase <= 1095; xBase += strandPitch) {
    const xStart = xBase - layShift * 0.5;
    const xEnd = xBase + layShift * 0.5;

    // Proximity to the spotlight & foot grip zone (intensifies glare and chalk dust)
    const inSpotlight = xBase > 350 && xBase < 870;
    const underGrip = xBase > 560 && xBase < 825;

    // Each bundle has 9 individual steel wires twisted together
    const numWires = 9;
    for (let w = 0; w < numWires; w++) {
      const wireOffset = map(w, 0, numWires - 1, -7.5, 7.5);
      const pts = [];
      const steps = 6;

      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const x = lerp(xStart, xEnd, t) + wireOffset * 0.65;
        const cy = getCableY(x);
        const n = getCableNormal(x);

        // S-curve across the cylinder radius (-CABLE_R to +CABLE_R)
        const radPos = -cos(t * 180) * (CABLE_R - 1.5);
        // Subtle 3D bulge of the individual strand
        const strandCrown = sin(t * 180) * (1 - abs(wireOffset) / 9) * 2.2;
        const offsetN = radPos + strandCrown;

        pts.push([x + n.nx * offsetN, cy + n.ny * offsetN]);
      }

      // Shadow segment (top half of cable)
      const topPts = pts.slice(0, 4);
      const topCol =
        w === 0
          ? PAL.steelDark
          : w < 3
          ? PAL.steelShadow
          : PAL.steelMid;
      brush.set("rotring", topCol, w === 0 ? 0.65 : 0.42);
      brush.spline(topPts, 0.35);

      // Mid-to-Lower segment (lit by upward spotlight)
      const botPts = pts.slice(3);
      let botCol = PAL.steelLight;
      if (w === 0 || w === numWires - 1) {
        botCol = PAL.steelDark; // Deep groove between bundles
      } else if (w >= 4 && w <= 7) {
        botCol = inSpotlight ? PAL.chalkPure : PAL.steelGlare;
      } else if (w >= 2) {
        botCol = inSpotlight ? PAL.steelGlare : PAL.steelLight;
      }

      brush.set(
        w >= 4 && w <= 6 ? "rotring" : "2H",
        botCol,
        w >= 4 && w <= 6 ? 0.58 : 0.45
      );
      brush.spline(botPts, 0.35);
    }

    // Deep V-notch shadow along the top & bottom scallop of each twisted bundle
    const cTopY = getCableY(xStart);
    const nTop = getCableNormal(xStart);
    brush.set("rotring", PAL.steelDark, 0.75);
    brush.line(
      xStart - nTop.nx * CABLE_R,
      cTopY - nTop.ny * CABLE_R,
      xStart - nTop.nx * (CABLE_R - 6),
      cTopY - nTop.ny * (CABLE_R - 6)
    );

    // Bright specular crescent along the bottom bulge of each bundle
    const xBot = xEnd - 4;
    const cBotY = getCableY(xBot);
    const nBot = getCableNormal(xBot);
    const specCol = inSpotlight ? PAL.chalkPure : PAL.steelGlare;
    brush.set("rotring", specCol, inSpotlight ? 0.85 : 0.55);
    brush.line(
      xBot + nBot.nx * (CABLE_R - 1.5) - nBot.ux * 6,
      cBotY + nBot.ny * (CABLE_R - 1.5) - nBot.uy * 6,
      xBot + nBot.nx * (CABLE_R - 0.5) + nBot.ux * 5,
      cBotY + nBot.ny * (CABLE_R - 0.5) + nBot.uy * 5
    );

    // Chalk & rosin packed into the strand valleys near the foot
    if (underGrip || (xBase > 420 && xBase < 860 && random() < 0.75)) {
      const cMidY = getCableY(xBase);
      const nMid = getCableNormal(xBase);
      brush.set("cpencil", PAL.chalkWarm, 0.55);
      brush.line(
        xBase - nMid.nx * 6,
        cMidY - nMid.ny * 6,
        xBase + nMid.nx * 12,
        cMidY + nMid.ny * 12
      );
    }
  }

  // 3. Background frayed & snapped wire filaments springing off the cable
  drawCableFrays(false);

  brush.noClip();
}

function drawCableFrays(foregroundOnly) {
  // Deterministic list of broken wire locations along the cable
  const frayZones = [
    { x: 285, side: -1, len: 34, curl: -0.7, fg: false },
    { x: 340, side: 1, len: 42, curl: 0.9, fg: false },
    { x: 425, side: -1, len: 52, curl: -1.2, fg: false },
    { x: 465, side: 1, len: 64, curl: 1.4, fg: true },
    { x: 505, side: -1, len: 48, curl: -0.9, fg: true },
    { x: 538, side: 1, len: 58, curl: 1.1, fg: true },
    { x: 575, side: 1, len: 72, curl: 1.6, fg: true },
    { x: 590, side: -1, len: 45, curl: -1.3, fg: false },
    { x: 630, side: 1, len: 55, curl: 1.2, fg: true },
    { x: 678, side: 1, len: 68, curl: -1.5, fg: true },
    { x: 715, side: 1, len: 52, curl: 1.3, fg: true },
    { x: 758, side: 1, len: 48, curl: 0.8, fg: true },
    { x: 818, side: -1, len: 62, curl: -1.4, fg: true },
    { x: 838, side: 1, len: 56, curl: 1.1, fg: true },
    { x: 875, side: -1, len: 44, curl: -0.8, fg: false },
    { x: 920, side: 1, len: 38, curl: 0.9, fg: false },
    { x: 980, side: -1, len: 32, curl: -0.6, fg: false }
  ];

  for (let f of frayZones) {
    if (f.fg !== foregroundOnly) continue;

    // Draw 2 to 4 individual broken steel filaments at each fray site
    const count = f.x > 440 && f.x < 850 ? 4 : 2;
    for (let k = 0; k < count; k++) {
      const x0 = f.x + (k - 1.5) * 6;
      const y0 = getCableY(x0);
      const n = getCableNormal(x0);

      const startOff = f.side * (CABLE_R - 4 - k * 2);
      let px = x0 + n.nx * startOff;
      let py = y0 + n.ny * startOff;

      const pts = [[px, py]];
      const shadowPts = [[px + 1, py + 1.5]];
      let dir = n.ang + (f.side > 0 ? 28 + k * 14 : -32 - k * 12);
      const segs = 5;
      const segLen = (f.len * (0.75 + k * 0.15)) / segs;

      for (let s = 1; s <= segs; s++) {
        // Sharp metallic kink + helical curl of sprung high-carbon steel wire
        dir += f.curl * (14 + s * 8) + (s % 2 === 0 ? 12 : -8);
        px += cos(dir) * segLen;
        py += sin(dir) * segLen;
        pts.push([px, py]);
        shadowPts.push([px + 1.2, py + 1.5]);
      }

      // Dark backing wire shadow
      brush.set("rotring", PAL.steelDark, 0.55);
      brush.spline(shadowPts, 0.25);

      //Razor-sharp spotlight highlight on the sprung wire filament
      const inGlare = f.x > 400 && f.x < 860;
      const wireCol =
        inGlare && (f.side > 0 || k % 2 === 0) ? PAL.chalkPure : PAL.steelGlare;
      brush.set("rotring", wireCol, 0.42);
      brush.spline(pts, 0.25);
    }
  }
}

