function drawStitchedSeam(curvePts, numStitches, threadCol) {
  // Sunken seam groove
  brush.set("rotring", PAL.leatherCore, 0.65);
  brush.spline(curvePts, 0.3);

  // Individual wax-linen lockstitches along the seam
  for (let i = 0; i < numStitches; i++) {
    const t1 = i / numStitches;
    const t2 = (i + 0.68) / numStitches;
    const p1 = samplePolyline(curvePts, t1);
    const p2 = samplePolyline(curvePts, t2);

    // Dark needle hole
    brush.set("rotring", PAL.inkDark, 0.65);
    brush.line(p1[0] - 1, p1[1], p1[0] + 1, p1[1]);

    // Raised bright thread segment
    brush.set("rotring", threadCol, 0.62);
    brush.line(p1[0], p1[1] - 1, p2[0], p2[1] - 1);
  }
}

function drawWhipStitches(curvePts, numStitches, stitchLen, threadCol) {
  for (let i = 0; i <= numStitches; i++) {
    const t = i / numStitches;
    const p = samplePolyline(curvePts, t);
    const pNext = samplePolyline(curvePts, min(1, t + 0.04));
    const ang = atan2(pNext[1] - p[1], pNext[0] - p[0]) + 75;
    const dx = cos(ang) * stitchLen;
    const dy = sin(ang) * stitchLen;

    // Shadow under thread
    brush.set("rotring", PAL.leatherCore, 0.5);
    brush.line(p[0] - dx * 0.4 + 1, p[1] - dy * 0.4 + 1, p[0] + dx * 0.6 + 1, p[1] + dy * 0.6 + 1);

    // Lit thread
    brush.set("rotring", threadCol, 0.52);
    brush.line(p[0] - dx * 0.4, p[1] - dy * 0.4, p[0] + dx * 0.6, p[1] + dy * 0.6);
  }
}

function drawDarnedPatch(cx, cy, w, h, angleDeg, colWarp, colWeft) {
  push();
  translate(cx, cy);
  rotate(angleDeg);

  // Dark ragged tear beneath the darned threads
  brush.set("charcoal", PAL.leatherCore, 0.85);
  brush.line(-w * 0.42, 0, w * 0.42, 0);
  brush.set("cpencil", PAL.suedeRaw, 0.7);
  brush.rect(0, 0, w * 0.85, h * 0.75, "center");

  // Warp threads (longitudinal darning pass)
  const warpCount = 13;
  for (let i = 0; i < warpCount; i++) {
    const y = map(i, 0, warpCount - 1, -h * 0.45, h * 0.45);
    const halfLen = (w * 0.5) * (1 - sq(y / (h * 0.55)) * 0.35);

    // Needle holes at ends
    brush.set("rotring", PAL.leatherCore, 0.55);
    brush.line(-halfLen - 1, y, -halfLen + 1, y);
    brush.line(halfLen - 1, y, halfLen + 1, y);

    // Darned thread
    brush.set("rotring", i % 3 === 0 ? colWeft : colWarp, 0.48);
    brush.line(-halfLen, y, halfLen, y);
  }

  // Weft threads (perpendicular woven pass)
  const weftCount = 17;
  for (let j = 0; j < weftCount; j++) {
    const x = map(j, 0, weftCount - 1, -w * 0.42, w * 0.42);
    const halfH = (h * 0.5) * (1 - sq(x / (w * 0.52)) * 0.35);

    brush.set("rotring", PAL.leatherCore, 0.5);
    brush.line(x + 0.8, -halfH, x + 0.8, halfH);

    // Alternating bright linen and faded crimson repair threads
    brush.set("rotring", j % 4 === 0 ? colWeft : PAL.chalkPure, 0.5);
    brush.line(x, -halfH, x, halfH);
  }

  pop();
}

function drawLeatherScuffsAndCracks() {
  // 1. Abraded raw suede patches on ball of foot, heel curve & big toe dome
  const scuffZones = [
    { x: 372, y: 702, rx: 28, ry: 14, ang: 25 },
    { x: 605, y: 585, rx: 38, ry: 18, ang: -32 },
    { x: 678, y: 542, rx: 34, ry: 16, ang: -36 },
    { x: 758, y: 474, rx: 26, ry: 14, ang: -42 },
    { x: 545, y: 515, rx: 32, ry: 14, ang: -24 }
  ];

  for (let sz of scuffZones) {
    push();
    translate(sz.x, sz.y);
    rotate(sz.ang);

    // Rough directional suede nap scratches
    for (let i = 0; i < 28; i++) {
      const sx = random(-sz.rx, sz.rx);
      const sy = random(-sz.ry, sz.ry);
      if (sq(sx / sz.rx) + sq(sy / sz.ry) <= 1) {
        const len = random(6, 18);
        const col =
          sy > 0
            ? random() < 0.6
              ? PAL.chalkWarm
              : PAL.suedeBuff
            : PAL.suedeRaw;
        brush.set("rotring", col, 0.38);
        brush.line(sx - len * 0.5, sy, sx + len * 0.5, sy + random(-3, 3));
      }
    }
    pop();
  }

  // 2. Fine network of aged leather craze-cracks across mid-vamp and heel
  brush.set("rotring", PAL.leatherCore, 0.34);
  for (let i = 0; i < 55; i++) {
    const t = random(0.12, 0.88);
    const cx = lerp(365, 745, t) + random(-25, 25);
    const cy = lerp(665, 465, t) + random(-28, 32);
    const a1 = random(-180, 180);
    const l1 = random(8, 22);
    const x2 = cx + cos(a1) * l1;
    const y2 = cy + sin(a1) * l1;
    brush.line(cx, cy, x2, y2);
    // Branching micro-crack
    const a2 = a1 + random(35, 75) * (random() < 0.5 ? 1 : -1);
    brush.line(x2, y2, x2 + cos(a2) * (l1 * 0.6), y2 + sin(a2) * (l1 * 0.6));
  }
}

function samplePolyline(pts, t) {
  const scaled = constrain(t, 0, 0.9999) * (pts.length - 1);
  const idx = floor(scaled);
  const frac = scaled - idx;
  return [
    lerp(pts[idx][0], pts[idx + 1][0], frac),
    lerp(pts[idx][1], pts[idx + 1][1], frac)
  ];
}

