    type: "default",
    weight: 0.42,
    scatter: 0.008,
    sharpness: 0.96,
    grain: 0.06,
    opacity: 215,
    spacing: 0.11,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.06
  });

  brush.add("burin_uniform", {
    type: "default",
    weight: 0.48,
    scatter: 0.008,
    sharpness: 0.95,
    grain: 0.07,
    opacity: 225,
    spacing: 0.11,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.06
  });

  brush.add("burin_swell", {
    type: "default",
    weight: 0.82,
    scatter: 0.012,
    sharpness: 0.94,
    grain: 0.09,
    opacity: 242,
    spacing: 0.10,
    pressure: [0.14, 1.05, 0.14],
    noise: 0.08
  });

  brush.add("burin_heavy", {
    type: "default",
    weight: 1.26,
    scatter: 0.015,
    sharpness: 0.92,
    grain: 0.11,
    opacity: 252,
    spacing: 0.09,
    pressure: [0.12, 1.1, 0.12],
    noise: 0.08
  });

  brush.add("burin_lozenge", {
    type: "default",
    weight: 0.92,
    scatter: 0.01,
    sharpness: 0.95,
    grain: 0.08,
    opacity: 245,
    spacing: 0.09,
    pressure: [0.1, 1.25, 0.1],
    noise: 0.05
  });

  initGeometry();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paperBase);
  brush.noField();

  // 1. Archival cream laid paper texture, chain/wire lines & plate impression
  drawLaidPaperGround();

  // 2. Faint geometric rose-engine lathe border (unclosed at upper-left, broken by lemon & knife)
  drawGuillocheBorder();

  // 3. Engraved vignette sky & surface shadow plane beneath the knife
  drawVignetteBackgroundLines();

  // 4. Old carbon-steel knife (bolster, handle, spine, patinated blade flat, bevel, maker's mark)
  drawCarbonSteelKnife();

  // 5. The halved lemon: pitted outer rind in dot-and-lozenge stipple + form crosshatching
  drawLemonRind();

  // 6. The halved lemon: cut face (flavedo rim, scalloped pith, columella, septa, 10 segments & juice sacs)
  drawLemonCutFace();

  // 7. Foreground hyperreal focal incidents: wet seed caught on blade edge & drop about to fall
  drawCaughtSeed();
  drawHangingDrop();

  // 8. Final crisp intaglio accent hairlines & engraver's plate signature ticks
  drawFinalAccents();

  noLoop();
}

// ============================================================================
// GEOMETRY INITIALIZATION & SILHOUETTE / OCCLUSION SOLVERS
// ============================================================================

function initGeometry() {
  // 1. Precompute 95 3D cross-sectional rings of the lemon dome from cut-face (s=0) to nipple (s=1)
  const N_RINGS = 95;
  for (let i = 0; i <= N_RINGS; i++) {
    let s = i / N_RINGS;
    let prof = lemonDomeProfile(s);
    // Dome axis curves slightly upward then toward the mamilla apex
    let cx = lerp(LCX, APEX_X, Math.pow(s, 0.92));
    let cy = lerp(LCY, APEX_Y, Math.pow(s, 0.88)) - 26 * Math.sin(Math.PI * s);
    let rx = Math.max(1.5, L_RX * prof);
    let ry = Math.max(1.5, L_RY * prof * (1.0 + 0.06 * s));
    let rot = L_ROT * (1.0 - 0.35 * s) - 0.08 * s;
    domeRings.push({ s, cx, cy, rx, ry, rot, prof });
  }

  // 2. Generate ~460 oil-gland dimples (pits) on the lemon rind via golden-angle spiral
  const N_PITS = 460;
  for (let i = 0; i < N_PITS; i++) {
    let s = 0.03 + 0.93 * Math.pow((i + 0.5) / N_PITS, 0.72);
    let theta = ((i * 2.3999632297) % TWO_PI) - Math.PI;
    // Slight organic jitter
    s += random(-0.008, 0.008);
    theta += random(-0.03, 0.03);
    let rad = map(s, 0, 1, 4.8, 2.4) * random(0.82, 1.18);
    rindPits.push({ s, theta, rad, depth: random(0.75, 1.15) });
  }

  // 3. Define the 10 radial septa angles of the cut lemon
  const baseStep = TWO_PI / 10;
  const offsets = [0.00, 0.03, -0.02, 0.04, -0.01, -0.03, 0.02, -0.02, 0.03, -0.01];
  for (let k = 0; k <= 10; k++) {
    sepAngles.push(-Math.PI + k * baseStep + (offsets[k % 10] || 0));
  }

  // 4. Generate packed teardrop juice vesicles inside each of the 10 segments
  for (let k = 0; k < 10; k++) {
    let a0 = sepAngles[k];
    let a1 = sepAngles[k + 1];
    let aMid = 0.5 * (a0 + a1);
    let aSpan = a1 - a0;

    // 3 radial tiers of vesicles per segment
    const tiers = [
      { rMin: 0.17, rMax: 0.39, count: 2 },
      { rMin: 0.36, rMax: 0.60, count: 3 },
      { rMin: 0.56, rMax: 0.81, count: 4 }
    ];

    for (let tIdx = 0; tIdx < tiers.length; tIdx++) {
      let tier = tiers[tIdx];
      for (let j = 0; j < tier.count; j++) {
        let uFrac = (j + 0.5) / tier.count;
        let pad = 0.14 + (1.0 - tier.rMin) * 0.08;
        let thetaC = lerp(a0 + aSpan * pad, a1 - aSpan * pad, uFrac) + random(-0.018, 0.018);
        let rC = lerp(tier.rMin, tier.rMax, 0.52) + random(-0.022, 0.022);
        let rHalf = (tier.rMax - tier.rMin) * 0.52 * random(0.92, 1.08);
        let tHalf = ((aSpan * (1.0 - 2 * pad)) / tier.count) * 0.54 * random(0.92, 1.08);

        // Herringbone tilt: vesicles angle slightly from outer septum toward core
        let sideSign = uFrac < 0.5 ? -1 : 1;
        let tilt = sideSign * random(0.10, 0.24);

        // Specular highlight offset inside the vesicle
        let specS = random(-0.28, 0.08);
        let specT = random(-0.32, -0.04);

        vesicles.push({
          seg: k,
          tier: tIdx,
          rC,
          thetaC,
          rHalf,
          tHalf,
          tilt,
          specS,
          specT,
          seedType: 0 // 0 = normal juice sac, 1 = whole seed, 2 = sliced seed
        });
      }
    }
  }
}

function lemonDomeProfile(s) {
  if (s <= 0) return 1.0;
  if (s >= 1) return 0.0;
  let body = Math.pow(Math.max(0, 1.0 - Math.pow(s, 1.72)), 0.51);
  // Characteristic collar dip before the lemon nipple (mamilla)
  let neckDip = -0.072 * Math.exp(-Math.pow((s - 0.81) / 0.065, 2));
  let nipple = 0.052 * Math.exp(-Math.pow((s - 0.905) / 0.055, 2)) * (1.0 - s) * 6.2;
  let tipTaper = s > 0.93 ? Math.cos(((s - 0.93) / 0.07) * (Math.PI / 2)) : 1.0;
  return Math.max(0, (body + neckDip + nipple) * tipTaper);
}

function cutRimMod(theta) {
  return 1.0
    + 0.012 * Math.cos(3 * theta - 0.4)
    - 0.009 * Math.sin(2 * theta + 0.7)
    + 0.005 * Math.cos(10 * theta);
}

function toLemonLocal(x, y) {
  let dx = x - LCX, dy = y - LCY;
  let c = Math.cos(-L_ROT), s = Math.sin(-L_ROT);
  return { u: dx * c - dy * s, v: dx * s + dy * c };
}

function fromLemonLocal(u, v) {
  let c = Math.cos(L_ROT), s = Math.sin(L_ROT);
  return { x: LCX + u * c - v * s, y: LCY + u * s + v * c };
}

function pointInRing(x, y, ring) {
  let dx = x - ring.cx, dy = y - ring.cy;
  let c = Math.cos(-ring.rot), s = Math.sin(-ring.rot);
  let u = dx * c - dy * s;
  let v = dx * s + dy * c;
  let theta = Math.atan2(v / ring.ry, u / ring.rx);
  let mod = cutRimMod(theta);
  let nr = Math.hypot(u / (ring.rx * mod), v / (ring.ry * mod));
  return nr <= 1.0;
}

function inLemonCutFace(x, y) {
  return pointInRing(x, y, domeRings[0]);
}

function inLemonRind(x, y) {
  if (inLemonCutFace(x, y)) return false;
  for (let i = 1; i < domeRings.length; i++) {
    if (pointInRing(x, y, domeRings[i])) return true;
  }
  return false;
}

function inLemon(x, y) {
  for (let i = 0; i < domeRings.length; i++) {
    if (pointInRing(x, y, domeRings[i])) return true;
  }
  return false;
}

// Check if a point on ring[ringIdx] is visible (not occluded by any closer ring 0..ringIdx-1)
function isRindPointVisible(x, y, ringIdx) {
  for (let j = 0; j < ringIdx; j++) {
    if (pointInRing(x, y, domeRings[j])) return false;
  }
  return true;
}

// Knife coordinate transforms
function toBladeLocal(x, y) {
  let dx = x - BLADE_X0, dy = y - BLADE_Y0;
  let c = Math.cos(-BLADE_ANG), s = Math.sin(-BLADE_ANG);
  return { s: dx * c - dy * s, t: dx * s + dy * c };
}

function fromBladeLocal(s, t) {
  let c = Math.cos(BLADE_ANG), sn = Math.sin(BLADE_ANG);
  return { x: BLADE_X0 + s * c - t * sn, y: BLADE_Y0 + s * sn + t * c };
}

// Width of the carbon-steel knife blade flat at distance s along spine
function bladeWidthAt(s) {
  if (s < 0 || s > BLADE_LEN) return 0;
  let u = s / BLADE_LEN;
  // Wide chef/butcher profile with graceful belly sweep up to a sharp clip/drop point
  let heel = 120 * (1.0 - 0.08 * Math.exp(-Math.pow(u / 0.06, 2)));
  let belly = heel * Math.pow(Math.max(0, 1.0 - Math.pow(Math.max(0, (u - 0.18) / 0.82), 1.85)), 0.56);
  return belly;
}

// Spine thickness (seen in 3/4 top perspective along t < 0)
function spineThicknessAt(s) {
  if (s < -15 || s > BLADE_LEN) return 0;
  let u = constrain(s / BLADE_LEN, 0, 1);
  return 13.5 * Math.pow(1.0 - u, 0.65) + 1.2;
}

function inKnifeBlade(x, y) {
  let b = toBladeLocal(x, y);
  if (b.s < 0 || b.s > BLADE_LEN) return false;
  let w = bladeWidthAt(b.s);
  let sp = spineThicknessAt(b.s);
  return b.t >= -sp && b.t <= w;
}

function inKnifeHandle(x, y) {
  let b = toBladeLocal(x, y);
  if (b.s > 4 || b.s < -195) return false;
  // Sculpted forged bolster (s in [-28, 4]) + octagonal handle (s in [-195, -28])
  let u = -b.s; // 0 to 195
  let topT = -spineThicknessAt(0) + 4 * Math.sin(constrain(u / 35, 0, 1) * Math.PI);
  let botT = 68 - 22 * Math.exp(-Math.pow((u - 26) / 18, 2)) + 8 * (u / 190);
  if (u < 16) {
    // Forged heel drop transición
    botT = lerp(bladeWidthAt(0), 54, u / 16);
  }
  return b.t >= topT && b.t <= botT;
}

function inKnife(x, y) {
  return inKnifeBlade(x, y) || inKnifeHandle(x, y);
}

// Caught seed silhouette on the blade edge
function toSeedLocal(x, y) {
  let dx = x - SEED_CX, dy = y - SEED_CY;
  let c = Math.cos(-SEED_ANG), s = Math.sin(-SEED_ANG);
  return { u: dx * c - dy * s, v: dx * s + dy * c };
}

function fromSeedLocal(u, v) {
  let c = Math.cos(SEED_ANG), s = Math.sin(SEED_ANG);
  return { x: SEED_CX + u * c - v * s, y: SEED_CY + u * s + v * c };
}

function seedHalfWidthAt(uNorm) {
  // uNorm in [-1, 1]; pointed beak at uNorm -> +1, rounded chalaza at uNorm -> -1
  if (Math.abs(uNorm) > 1) return 0;
  let base = Math.sqrt(Math.max(0, 1.0 - uNorm * uNorm));
  let asym = 1.0 - 0.28 * uNorm - 0.12 * uNorm * uNorm;
  let beak = uNorm > 0.65 ? 0.16 * Math.sin(((1.0 - uNorm) / 0.35) * Math.PI) : 0;
  return SEED_RY * (base * asym + beak);
}

function inCaughtSeed(x, y) {
  let loc = toSeedLocal(x, y);
  let uNorm = loc.u / SEED_RX;
  if (Math.abs(uNorm) > 1.0) return false;
  return Math.abs(loc.v) <= seedHalfWidthAt(uNorm);
}

// Hanging drop silhouette below the cutting edge
function dropHalfWidthAt(y) {
  if (y < DROP_Y_TOP || y > DROP_Y_BOT) return 0;
  let t = (y - DROP_Y_TOP) / (DROP_Y_BOT - DROP_Y_TOP); // 0 at blade edge, 1 at bottom tip
  // Meniscus flare at t=0 -> capillary neck at t=0.27 -> plump spherical belly at t=0.72 -> rounded bottom at t=1
  let meniscus = 15.5 * Math.exp(-Math.pow(t / 0.16, 1.6));
  let neck = 5.4 * (1.0 - 0.4 * Math.pow(t - 0.26, 2));
  let belly = 19.2 * Math.pow(Math.max(0, Math.sin(Math.pow(t, 0.85) * Math.PI)), 0.72) * (t > 0.12 ? 1.0 : t / 0.12);
  return meniscus + (1.0 - Math.exp(-t * 10)) * Math.max(neck * (1.0 - t), belly);
}

function dropCenterXAt(y) {
  let t = constrain((y - DROP_Y_TOP) / (DROP_Y_BOT - DROP_Y_TOP), 0, 1);
  // Subtle gravity curve from the tilted blade edge into vertical fall
  return DROP_X + 2.2 * Math.sin(t * Math.PI * 0.8);
}

function inHangingDrop(x, y) {
  if (y < DROP_Y_TOP || y > DROP_Y_BOT) return false;
  let cx = dropCenterXAt(y);
  let hw = dropHalfWidthAt(y);
  return Math.abs(x - cx) <= hw;
}

// ============================================================================
// CORE BURIN SWELLING & TAPERING ENGINE
// ============================================================================

// Renders a path of {x, y, tone} points where line weight swells & tapers
// purely according to local tone (0 = pure paper highlight, 1 = deepest shadow)
function drawSwellingBurinPath(pts, curvature = 0.3) {
  if (pts.length < 2) return;

  // Pass 1: Continuous hairline groove where tone >= 0.045
  let runs1 = extractToneRuns(pts, 0.045);
  for (let run of runs1) {
    drawRunPoints(run, "burin_uniform", PALETTE.inkLight, 0.44, curvature, false);
  }

  // Pass 2: Mid-tone burin swell where tone >= 0.25
  let runs2 = extractToneRuns(pts, 0.25);
  for (let run of runs2) {
    drawRunPoints(run, "burin_swell", PALETTE.inkMid, 0.76, curvature, true);
  }

  // Pass 3: Dark burin swell where tone >= 0.48
  let runs3 = extractToneRuns(pts, 0.48);
  for (let run of runs3) {
    drawRunPoints(run, "burin_heavy", PALETTE.inkDark, 1.05, curvature, true);
  }

  // Pass 4: Deep intaglio groove widening where tone >= 0.72
  let runs4 = extractToneRuns(pts, 0.72);
  for (let run of runs4) {
    let flankA = offsetRunPerpendicular(run, 0.48);
    let flankB = offsetRunPerpendicular(run, -0.48);
    drawRunPoints(flankA, "burin_swell", PALETTE.inkDeep, 0.78, curvature, true);
    drawRunPoints(flankB, "burin_swell", PALETTE.inkDeep, 0.78, curvature, true);
  }
}

function extractToneRuns(pts, threshold) {
  let runs = [];
  let cur = [];
  for (let i = 0; i < pts.length; i++) {
    if (pts[i].tone >= threshold) {
      cur.push(pts[i]);
    } else {
      if (cur.length >= 2) runs.push(cur);
      cur = [];
    }
  }
  if (cur.length >= 2) runs.push(cur);
  return runs;
}

function offsetRunPerpendicular(run, offsetDist) {
  let out = [];
  for (let i = 0; i < run.length; i++) {
    let pPrev = run[Math.max(0, i - 1)];
    let pNext = run[Math.min(run.length - 1, i + 1)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    // Taper the offset at both ends of the run so the widened groove merges seamlessly
    let u = run.length > 2 ? Math.sin((i / (run.length - 1)) * Math.PI) : 0.7;
    out.push({
      x: run[i].x + nx * offsetDist * u,
      y: run[i].y + ny * offsetDist * u,
      tone: run[i].tone
    });
  }
  return out;
}

function drawRunPoints(run, brushName, col, weightMult, curvature, modulatePressure) {
  if (run.length < 2) return;
  brush.set(brushName, col, weightMult);
  if (run.length === 2) {
    brush.line(run[0].x, run[0].y, run[1].x, run[1].y);
    return;
  }
  let splinePts = [];
  for (let i = 0; i < run.length; i++) {
    let p = run[i];
    if (modulatePressure) {
      let endTaper = Math.sin(((i + 0.3) / (run.length - 0.4)) * Math.PI);
      let pr = constrain(0.25 + p.tone * 1.15, 0.2, 1.55) * (0.35 + 0.65 * endTaper);
      splinePts.push([p.x, p.y, pr]);
    } else {
      splinePts.push([p.x, p.y, 0.85]);
    }
  }
  brush.spline(splinePts, curvature);
}

// ============================================================================
// 1. ARCHIVAL CREAM LAID PAPER & INTAGLIO PLATE MARK
// ============================================================================

function drawLaidPaperGround() {
  // Subtle plate-tone wash in the center of the sheet
  brush.noStroke();
  brush.wash(PALETTE.paperWash, 18);
  brush.rect(85, 85, 1030, 1030, "corner");
  brush.noWash();

  // Horizontal laid paper wire lines (every 6.5px across the sheet)
  for (let y = 24; y < height - 24; y += 6.5) {
    let col = (Math.floor(y / 6.5) % 2 === 0) ? PALETTE.paperWire : PALETTE.paperChain;
    brush.set("paper_laid", col, random(0.45, 0.72));
    let yJit = y + random(-0.4, 0.4);
    brush.line(24, yJit, width - 24, yJit + random(-0.6, 0.6));
  }

  // Vertical laid paper chain lines (every 96px)
  for (let x = 78; x < width - 50; x += 96) {
    brush.set("paper_laid", PALETTE.paperChain, 0.78);
    brush.line(x, 24, x + random(-1, 1), height - 24);
  }

  // Subtle debossed intaglio copper/steel plate-mark border at sheet margin
  const pmX = 72, pmY = 72, pmW = 1056, pmH = 1056;
  brush.set("burin_hair", PALETTE.paperChain, 0.85);
  brush.line(pmX, pmY, pmX + pmW, pmY);
  brush.line(pmX, pmY, pmX, pmY + pmH);
  brush.set("burin_hair", "#fbfcf8", 0.9);
  brush.line(pmX + pmW, pmY, pmX + pmW, pmY + pmH);
  brush.line(pmX, pmY + pmH, pmX + pmW, pmY + pmH);
}

// ============================================================================
// 2. GEOMETRIC ROSE-ENGINE LATHE BORDER (GUILLOCHE)
// ============================================================================

function isOccludedBySubject(x, y) {
  if (inLemon(x, y)) return true;
  if (inKnife(x, y)) return true;
  if (inCaughtSeed(x, y)) return true;
  if (inHangingDrop(x, y)) return true;
  return false;
}

function drawGuillocheBorder() {
  const RX_BASE = 342;
  const RY_BASE = 356;
  const GAP_CENTER = -2.26; // Upper-left (~ 230 deg) where the border never quite closes
  const GAP_HALF = 0.27;    // ~31 degrees open gap

  // 18 harmonic phase-shifted rose-engine wave ribbons
  const N_RIBBONS = 18;
  const STEPS = 520;

  for (let rIdx = 0; rIdx < N_RIBBONS; rIdx++) {
    let phase = (rIdx / N_RIBBONS) * TWO_PI;
    let col = (rIdx % 3 === 0) ? PALETTE.inkLight : (rIdx % 2 === 0 ? PALETTE.inkFaint : PALETTE.inkWhisper);
    let wt = (rIdx % 4 === 0) ? 0.46 : 0.34;

    let currentSegment = [];

    for (let s = 0; s <= STEPS; s++) {
      let u = s / STEPS; // 0 to 1 spanning the non-gap arc
      let angSpan = TWO_PI - 2 * GAP_HALF;
      let phi = (GAP_CENTER + GAP_HALF) + u * angSpan;

      // Envelope taper near the two unclosed ends so the lathe ribbons unwind gracefully
      let distToStart = u * angSpan;
      let distToEnd = (1.0 - u) * angSpan;
      let minEndDist = Math.min(distToStart, distToEnd);
      let endTaper = minEndDist < 0.38 ? Math.pow(minEndDist / 0.38, 1.35) : 1.0;

      // Cycloidal rose-engine harmonic perturbation
      let wave1 = 31.0 * Math.sin(24 * phi + phase) * (0.22 + 0.78 * endTaper);
      let wave2 = 9.5 * Math.cos(72 * phi - 2 * phase) * endTaper;
      let angMod = 0.015 * Math.cos(24 * phi + phase) * endTaper;

      // Slight outward scroll flare at the very tip of the unclosed gap
      let scrollFlare = minEndDist < 0.16 ? 14.0 * Math.sin(((0.16 - minEndDist) / 0.16) * Math.PI) * ((rIdx % 2 === 0) ? 1 : -1) : 0;

      let rx = RX_BASE + wave1 + wave2 + scrollFlare;
      let ry = RY_BASE + wave1 + wave2 + scrollFlare;
      let x = FCX + rx * Math.cos(phi + angMod);
      let y = FCY + ry * Math.sin(phi + angMod);

      if (isOccludedBySubject(x, y)) {
        if (currentSegment.length >= 2) {
          drawGuillocheSegment(currentSegment, col, wt);
        }
        currentSegment = [];
      } else {
        // Check if the overhanging lemon nipple on the upper-right casts a shadow on the frame
        let inFrameShadow = isFrameUnderLemonShadow(x, y);
        currentSegment.push({ x, y, shadow: inFrameShadow });
      }
    }
    if (currentSegment.length >= 2) {
      drawGuillocheSegment(currentSegment, col, wt);
    }
  }

  // Inner and outer scalloped hairline guard rings of the lathe border (also unclosed at gap)
  const guardRings = [
    { dr: -43, amp: 3.5, freq: 96, col: PALETTE.inkFaint, wt: 0.42 },
    { dr: -38, amp: 1.5, freq: 48, col: PALETTE.inkLight, wt: 0.52 },
    { dr:  38, amp: 1.5, freq: 48, col: PALETTE.inkLight, wt: 0.52 },
    { dr:  43, amp: 3.5, freq: 96, col: PALETTE.inkFaint, wt: 0.42 }
  ];

  for (let gr of guardRings) {
    let seg = [];
    let angSpan = TWO_PI - 2 * GAP_HALF;
    for (let s = 0; s <= 420; s++) {
      let u = s / 420;
      let minEnd = Math.min(u, 1.0 - u) * angSpan;
      if (minEnd < 0.18) continue;
      let taper = minEnd < 0.42 ? (minEnd - 0.18) / 0.24 : 1.0;
      let phi = (GAP_CENTER + GAP_HALF) + u * angSpan;
      let rOff = gr.dr * (0.4 + 0.6 * taper) + gr.amp * Math.sin(gr.freq * phi) * taper;
      let x = FCX + (RX_BASE + rOff) * Math.cos(phi);
      let y = FCY + (RY_BASE + rOff) * Math.sin(phi);
      if (isOccludedBySubject(x, y)) {
        if (seg.length >= 2) drawGuillocheSegment(seg, gr.col, gr.wt);
        seg = [];
      } else {
        seg.push({ x, y, shadow: isFrameUnderLemonShadow(x, y) });
      }
    }
    if (seg.length >= 2) drawGuillocheSegment(seg, gr.col, gr.wt);
  }
}

function isFrameUnderLemonShadow(x, y) {
  // Beneath the protruding right-side lemon dome & nipple (x: 780..950, y: 350..540)
  if (x < 770 || x > 955 || y < 345 || y > 545) return false;
  return inLemon(x - 16, y - 24) || inLemon(x - 9, y - 14);
}

function drawGuillocheSegment(seg, col, wt) {
  brush.set("guilloche", col, wt);
  let pts = [];
  for (let i = 0; i < seg.length; i++) {
    let p = seg[i];
    pts.push([p.x, p.y, p.shadow ? 1.55 : 0.9]);
  }
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, 0.25);
  }
}

// ============================================================================
// 3. ENGRAVED VIGNETTE SKY & TABLE SURFACE SHADOW PLANE
// ============================================================================

function drawVignetteBackgroundLines() {
  // A. Upper vignette ruled sky behind the lit upper rim of the lemon (makes the lemon glow)
  for (let y = 225; y <= 555; y += 4.2) {
    let pts = [];
    for (let x = 250; x <= 895; x += 7) {
      if (isOccludedBySubject(x, y)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.15);
        pts = [];
        continue;
      }
      // Elliptical distance from upper-center of subject
      let dx = (x - 595) / 265;
      let dy = (y - 385) / 175;
      let d = Math.hypot(dx, dy);
      if (d < 1.0) {
        // Stronger right near the bright upper contour of the lemon for classical vignette contrast
        let nearLemon = inLemon(x + 14, y + 18) || inLemon(x - 14, y + 18) ? 0.12 : 0;
        let tone = Math.pow(1.0 - d, 1.85) * 0.28 + nearLemon;
        pts.push({ x, y, tone });
      } else {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.15);
        pts = [];
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.15);
  }

  // B. Horizontal ruled shadow plane beneath the raised carbon-steel knife blade
  // Creates the physical space into which the hanging drop is about to fall
  for (let y = 620; y <= 835; y += 3.2) {
    let pts = [];
    for (let x = 165; x <= 1020; x += 6) {
      if (isOccludedBySubject(x, y)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.15);
        pts = [];
        continue;
      }
      let b = toBladeLocal(x, y);
      let w = bladeWidthAt(constrain(b.s, 0, BLADE_LEN));
      let distBelowEdge = b.t - w;

      if (distBelowEdge > 0 && distBelowEdge < 145 && b.s > -140 && b.s < BLADE_LEN - 20) {
        // Cast shadow of knife + lemon onto the surface below
        let uAlong = (b.s + 100) / (BLADE_LEN + 80);
        let horizEnv = Math.sin(constrain(uAlong, 0, 1) * Math.PI);
        let vertEnv = Math.exp(-Math.pow((distBelowEdge - 28) / 48, 2));
        // Deepest shadow under the lemon & bolster
        let lemonShadowBoost = Math.exp(-Math.pow((x - 585) / 155, 2)) * 0.35;
        let bolsterBoost = Math.exp(-Math.pow((x - 255) / 95, 2)) * 0.28;

        // Luminous caustic ring on the table directly under the hanging drop (x=606, y=792)
        let dropRingD = Math.hypot((x - 606) / 34, (y - 792) / 11);
        let dropRipple = dropRingD < 1.3 ? 0.18 * Math.cos(dropRingD * TWO_PI) : 0;

        let tone = (0.24 + lemonShadowBoost + bolsterBoost) * vertEnv * horizEnv + dropRipple;
        pts.push({ x, y, tone: constrain(tone, 0, 0.82) });
      } else {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.15);
        pts = [];
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.15);
  }

  // Oblique cross-hatch pass in the deep shadow directly under the knife bolster & lemon overhang
  for (let k = -80; k <= 140; k++) {
    let xStart = 210 + k * 5.2;
    let yStart = 665;
    let pts = [];
    for (let step = 0; step <= 42; step++) {
      let x = xStart + step * 3.2;
      let y = yStart + step * 2.4;
      if (isOccludedBySubject(x, y)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
        pts = [];
        continue;
      }
      let b = toBladeLocal(x, y);
      let w = bladeWidthAt(constrain(b.s, 0, BLADE_LEN));
      let distBelow = b.t - w;
      if (distBelow > 2 && distBelow < 68 && b.s > -90 && b.s < 640) {
        let underLemon = Math.exp(-Math.pow((x - 575) / 135, 2));
        let underBolster = Math.exp(-Math.pow((x - 265) / 75, 2));
        let vFade = 1.0 - distBelow / 68;
        let tone = (0.38 * underLemon + 0.34 * underBolster) * vFade;
        if (tone > 0.08) {
          pts.push({ x, y, tone });
          continue;
        }
      }
      if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
      pts = [];
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
  }
}

// ============================================================================
// 4. THE OLD CARBON-STEEL KNIFE (BLADE FLAT, PATINA, SPINE, BOLSTER & HANDLE)
// ============================================================================

function getBladePatinaAndShadowTone(s, t, w, x, y) {
  let v = constrain(t / Math.max(1, w), 0, 1); // 0 at spine ridge, 1 at cutting edge
  let u = constrain(s / BLADE_LEN, 0, 1);

  // 1. Cylindrical metallic sheen of hollow-ground carbon steel
  // Bright longitudinal band around v = 0.28, darker near spine (v < 0.1) and lower grind (v ~ 0.72)
  let baseSheen = 0.18
    + 0.22 * Math.exp(-Math.pow((v - 0.04) / 0.09, 2))
    - 0.14 * Math.exp(-Math.pow((v - 0.28) / 0.14, 2))
    + 0.20 * Math.exp(-Math.pow((v - 0.72) / 0.22, 2));

  // 2. Old carbon-steel oxidation patina & dark acid-etch halos where lemon juice wet the steel
  let n1 = noise(s * 0.012 + 10, t * 0.022 + 20);
  let n2 = noise(s * 0.045 + 50, t * 0.055 + 70);
  let patinaCloud = Math.pow(constrain(n1 * 0.75 + n2 * 0.35 - 0.32, 0, 1), 1.4) * 0.42;

  // Acid stain ring around the lemon's contact area on the steel
  let dAcid = Math.hypot((s - 315) / 175, (t - 78) / 48);
  let acidRing = dAcid < 1.35 ? 0.24 * Math.exp(-Math.pow((dAcid - 0.92) / 0.18, 2)) : 0;
  let acidPool = dAcid < 0.92 ? 0.18 * (0.5 + 0.5 * Math.sin(s * 0.09 + t * 0.11)) : 0;

  // Water-spot tarnish rings toward the tip and heel
  let spot1 = Math.hypot((s - 565) / 32, (t - 45) / 22);
  let spotRing1 = Math.abs(spot1 - 1.0) < 0.22 ? 0.22 : (spot1 < 1.0 ? 0.08 : 0);
  let spot2 = Math.hypot((s - 125) / 42, (t - 62) / 28);
  let spotRing2 = Math.abs(spot2 - 1.0) < 0.18 ? 0.19 : (spot2 < 1.0 ? 0.07 : 0);

  // 3. Cast shadow and contact occlusion of the halved lemon resting on the blade
  // Light comes from crisp frontal-upper-left, so shadow falls beneath and slightly right of the lemon
  let dContact = Math.hypot((x - 568) / 188, (y - 595) / 72);
  let contactShadow = dContact < 1.15 ? 0.68 * Math.pow(1.0 - dContact / 1.15, 1.35) : 0;

  let dCast = Math.hypot((x - 635) / 195, (y - 615) / 68);
  let castShadow = dCast < 1.1 ? 0.46 * Math.pow(1.0 - dCast / 1.1, 1.5) : 0;

  // 4. Specular reflection of the bright lemon pith & segments ghosted on the steel flat
  let reflDist = Math.hypot((x - 555) / 145, (y - 642) / 26);
  let lemonRefl = (reflDist < 1.0 && v > 0.55) ? -0.22 * (1.0 - reflDist) * (0.6 + 0.4 * Math.cos((x - 555) * 0.09)) : 0;

  // 5. Wet juice film running from under the lemon to the seed and hanging drop
  let inJuiceTrail1 = Math.abs(x - 520 - (y - 645) * 0.2) < 12 && y > 630;
  let inJuiceTrail2 = Math.abs(x - 604) < 16 && y > 632;
  let wetGlint = (inJuiceTrail1 || inJuiceTrail2) ? -0.18 * Math.cos((x - 560) * 0.45) : 0;

  // Taper brightness near the sharp honed cutting bevel (v > 0.94)
  let bevelEdge = v > 0.93 ? -0.25 * ((v - 0.93) / 0.07) : 0;

  // Darken slightly near bolster (u < 0.06)
  let bolsterShade = u < 0.07 ? 0.28 * (1.0 - u / 0.07) : 0;

  return constrain(
    baseSheen + patinaCloud + acidRing + acidPool + spotRing1 + spotRing2 +
    contactShadow + castShadow + lemonRefl + wetGlint + bevelEdge + bolsterShade,
    0.02, 0.96
  );
}

function drawCarbonSteelKnife() {
  // 1. Primary steel grind lines across the blade flat (running from spine t=0 to edge t=w)
  // Spaced every 3.0px along the 815px blade length
  for (let s = 2; s <= BLADE_LEN - 4; s += 3.0) {
    let w = bladeWidthAt(s);
    if (w < 3) continue;

    let pts = [];
    let steps = Math.max(6, Math.floor(w / 3.2));
    for (let i = 0; i <= steps; i++) {
      let t = (i / steps) * (w - 2.5);
      // Slight curved grind sweep characteristic of hand-forged blades
      let sCurved = s + 4.5 * Math.sin((t / 120) * Math.PI * 0.65);
      let pos = fromBladeLocal(sCurved, t);

      if (inLemon(pos.x, pos.y) || inCaughtSeed(pos.x, pos.y) || inHangingDrop(pos.x, pos.y)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
        pts = [];
        continue;
      }

      let tone = getBladePatinaAndShadowTone(sCurved, t, w, pos.x, pos.y);
      pts.push({ x: pos.x, y: pos.y, tone });
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
  }

  // 2. Oblique lozenge cross-hatching over the dark patina stains & lemon cast shadow on the blade
  // Pass A: +26 deg relative to grind lines
  for (let s0 = -40; s0 <= BLADE_LEN - 30; s0 += 3.4) {
    let pts = [];
    for (let t = 2; t <= 122; t += 3.5) {
      let s = s0 + t * 0.52;
      if (s < 2 || s > BLADE_LEN - 6) continue;
      let w = bladeWidthAt(s);
      if (t >= w - 3) continue;
      let pos = fromBladeLocal(s, t);
      if (inLemon(pos.x, pos.y) || inCaughtSeed(pos.x, pos.y) || inHangingDrop(pos.x, pos.y)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
        pts = [];
        continue;
      }
      let rawTone = getBladePatinaAndShadowTone(s, t, w, pos.x, pos.y);
      // Crosshatch activates only in medium-dark patina and shadow zones
      let chTone = rawTone > 0.36 ? (rawTone - 0.32) * 1.15 : 0;
      if (chTone > 0.05) {
        pts.push({ x: pos.x, y: pos.y, tone: constrain(chTone, 0, 0.92) });
      } else {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
        pts = [];
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
  }

  // Pass B: -31 deg relative to grind lines (carving deepest contact shadow under the lemon)
  for (let s0 = 140; s0 <= 680; s0 += 3.2) {
    let pts = [];
    for (let t = 2; t <= 122; t += 3.5) {
      let s = s0 - t * 0.62;
      if (s < 2 || s > BLADE_LEN - 6) continue;
      let w = bladeWidthAt(s);
      if (t >= w - 3) continue;
      let pos = fromBladeLocal(s, t);
      if (inLemon(pos.x, pos.y) || inCaughtSeed(pos.x, pos.y) || inHangingDrop(pos.x, pos.y)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
        pts = [];
        continue;
      }
      let rawTone = getBladePatinaAndShadowTone(s, t, w, pos.x, pos.y);
      let chTone = rawTone > 0.54 ? (rawTone - 0.50) * 1.35 : 0;
      if (chTone > 0.05) {
        pts.push({ x: pos.x, y: pos.y, tone: constrain(chTone, 0, 0.95) });
      } else {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
        pts = [];
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.2);
  }

  // 3. Carbon-steel oxidation pitting & longitudinal sharpening scratches
  for (let i = 0; i < 420; i++) {
    let s = random(12, BLADE_LEN - 25);
    let w = bladeWidthAt(s);
    let t = random(4, w - 5);
    let pos = fromBladeLocal(s, t);
    if (inLemon(pos.x, pos.y) || inCaughtSeed(pos.x, pos.y) || inHangingDrop(pos.x, pos.y)) continue;
    let tone = getBladePatinaAndShadowTone(s, t, w, pos.x, pos.y);
    if (random() < tone * 0.85) {
      brush.set("burin_lozenge", PALETTE.inkDark, random(0.45, 0.95));
      let len = random(1.2, 3.2);
      let ang = BLADE_ANG + random(-0.25, 0.25);
      brush.line(pos.x, pos.y, pos.x + Math.cos(ang) * len, pos.y + Math.sin(ang) * len);
    }
  }

  // Longitudinal use scratches along the steel flat
  for (let k = 0; k < 28; k++) {
    let sStart = random(20, BLADE_LEN - 140);
    let sLen = random(35, 110);
    let tFrac = random(0.15, 0.88);
    let pts = [];
    for (let s = sStart; s <= sStart + sLen; s += 6) {
      let w = bladeWidthAt(s);
      let t = w * tFrac + 2.0 * Math.sin(s * 0.04);
      let pos = fromBladeLocal(s, t);
      if (inLemon(pos.x, pos.y) || inCaughtSeed(pos.x, pos.y) || inHangingDrop(pos.x, pos.y)) {
        if (pts.length >= 2) drawRunPoints(pts, "burin_hair", PALETTE.inkMid, 0.42, 0.2, true);
        pts = [];
        continue;
      }
      pts.push({ x: pos.x, y: pos.y, tone: 0.35 });
    }
    if (pts.length >= 2) drawRunPoints(pts, "burin_hair", PALETTE.inkMid, 0.42, 0.2, true);
  }

  // 4. Stamped antique maker's mark on the flat near the ricasso (s: 55..115, t: 28..42)
  drawStampedMakersMark();

  // 5. The thick forged spine (t in [-sp, 0])
  for (let s = 0; s <= BLADE_LEN - 2; s += 2.6) {
    let sp = spineThicknessAt(s);
    let pTop = fromBladeLocal(s, -sp);
    let pBot = fromBladeLocal(s, 0);
    if (inLemon(pTop.x, pTop.y) || inLemon(pBot.x, pBot.y)) continue;
    let u = s / BLADE_LEN;
    let tone = 0.35 + 0.35 * Math.sin(u * Math.PI * 3.2) * 0.3 + (u < 0.15 ? 0.25 : 0);
    drawSwellingBurinPath([
      { x: pTop.x, y: pTop.y, tone: tone + 0.22 },
      { x: (pTop.x + pBot.x) * 0.5, y: (pTop.y + pBot.y) * 0.5, tone: tone * 0.55 },
      { x: pBot.x, y: pBot.y, tone: tone + 0.15 }
    ], 0.1);
  }

  // Spine outer contour & ridge contour
  let spineTopPts = [], spineRidgePts = [];
  for (let s = 0; s <= BLADE_LEN; s += 5) {
    let sp = spineThicknessAt(s);
    let pTop = fromBladeLocal(s, -sp);
    let pRidge = fromBladeLocal(s, 0);
    if (!inLemon(pTop.x, pTop.y)) {
      spineTopPts.push({ x: pTop.x, y: pTop.y, tone: 0.62 });
    } else {
      if (spineTopPts.length >= 2) drawSwellingBurinPath(spineTopPts, 0.25);
      spineTopPts = [];
    }
    if (!inLemon(pRidge.x, pRidge.y)) {
      spineRidgePts.push({ x: pRidge.x, y: pRidge.y, tone: 0.28 });
    } else {
      if (spineRidgePts.length >= 2) drawSwellingBurinPath(spineRidgePts, 0.25);
      spineRidgePts = [];
    }
  }
  if (spineTopPts.length >= 2) drawSwellingBurinPath(spineTopPts, 0.25);
  if (spineRidgePts.length >= 2) drawSwellingBurinPath(spineRidgePts, 0.25);

  // 6. The razor-sharp honed cutting edge (secondary bevel along t = w - 3.5 .. w)
  // A double-engraved border leaving a gleaming bare-paper highlight wire, interrupted by micro-nicks, seed & drop
  let edgeUpperPts = [], edgeLowerPts = [];
  for (let s = 0; s <= BLADE_LEN; s += 3.5) {
    let w = bladeWidthAt(s);
    let pUp = fromBladeLocal(s, w - 3.2);
    let pLo = fromBladeLocal(s, w);

    // Subtle micro-nick in the aged cutting edge at s=215 and s=435
    let nick = (Math.abs(s - 215) < 3.5 || Math.abs(s - 438) < 3.0) ? -1.8 : 0;
    if (nick !== 0) {
      pLo = fromBladeLocal(s, w + nick);
    }

    let occUp = inLemon(pUp.x, pUp.y) || inCaughtSeed(pUp.x, pUp.y) || inHangingDrop(pUp.x, pUp.y);
    let occLo = inLemon(pLo.x, pLo.y) || inCaughtSeed(pLo.x, pLo.y) || inHangingDrop(pLo.x, pLo.y);

    if (!occUp) {
      let shadowBoost = (s > 240 && s < 480) ? 0.25 : 0;
      edgeUpperPts.push({ x: pUp.x, y: pUp.y, tone: 0.42 + shadowBoost });
    } else {
      if (edgeUpperPts.length >= 2) drawSwellingBurinPath(edgeUpperPts, 0.25);
      edgeUpperPts = [];
    }

    if (!occLo) {
      let shadowBoost = (s > 240 && s < 510) ? 0.35 : 0;
      edgeLowerPts.push({ x: pLo.x, y: pLo.y, tone: 0.68 + shadowBoost });
    } else {
      if (edgeLowerPts.length >= 2) drawSwellingBurinPath(edgeLowerPts, 0.25);
      edgeLowerPts = [];
    }
  }
  if (edgeUpperPts.length >= 2) drawSwellingBurinPath(edgeUpperPts, 0.25);
  if (edgeLowerPts.length >= 2) drawSwellingBurinPath(edgeLowerPts, 0.25);

  // 7. Forged integral steel bolster & dark horn/ebony handle on the left (s in [-195, 2])
  drawKnifeBolsterAndHandle();
}

function drawStampedMakersMark() {
  // Small worn intaglio stamp on the left ricasso flat: crown motif + "ACIER"
  let cPos = fromBladeLocal(82, 34);
  brush.set("burin_hair", PALETTE.inkDark, 0.55);
  // Tiny crown emblem
  brush.line(cPos.x - 9, cPos.y - 3, cPos.x + 9, cPos.y - 3);
  brush.line(cPos.x - 9, cPos.y - 3, cPos.x - 11, cPos.y - 9);
  brush.line(cPos.x - 11, cPos.y - 9, cPos.x - 4, cPos.y - 6);
  brush.line(cPos.x - 4, cPos.y - 6, cPos.x, cPos.y - 11);
  brush.line(cPos.x, cPos.y - 11, cPos.x + 4, cPos.y - 6);
  brush.line(cPos.x + 4, cPos.y - 6, cPos.x + 11, cPos.y - 9);
  brush.line(cPos.x + 11, cPos.y - 9, cPos.x + 9, cPos.y - 3);

  // Tiny stamped serif letters along blade angle
  for (let i = -3; i <= 3; i++) {
    let p1 = fromBladeLocal(84 + i * 5.2, 41);
    let p2 = fromBladeLocal(84 + i * 5.2, 46);
    brush.set("burin_hair", PALETTE.inkDark, 0.52);
    brush.line(p1.x, p1.y, p2.x, p2.y);
    if (i % 2 === 0) {
      let p3 = fromBladeLocal(84 + i * 5.2 + 2.5, 43.5);
      brush.line(p1.x, p1.y, p3.x, p3.y);
    }
  }
}

function drawKnifeBolsterAndHandle() {
  // Transverse contour rings modeling the sculpted forged bolster & dark octagonal handle
  for (let s = 2; s >= -192; s -= 2.4) {
    let u = -s;
    let topT = -spineThicknessAt(0) + 4 * Math.sin(constrain(u / 35, 0, 1) * Math.PI);
    let botT = u < 16
      ? lerp(bladeWidthAt(0), 54, u / 16)
      : 68 - 22 * Math.exp(-Math.pow((u - 26) / 18, 2)) + 8 * (u / 190);

    let isBolster = u < 36;
    let pts = [];
    let steps = 16;
    for (let i = 0; i <= steps; i++) {
      let v = i / steps;
      let t = lerp(topT, botT, v);
      // Curved 3D cross-contour of the round bolster / faceted handle
      let sBulge = s - (isBolster ? 4.5 : 2.8) * Math.sin(v * Math.PI);
      let pos = fromBladeLocal(sBulge, t);

      let cylLight = Math.sin(v * Math.PI);
      let highlight = Math.exp(-Math.pow((v - 0.28) / 0.14, 2));
      let tone = isBolster
        ? 0.52 - 0.42 * highlight + 0.32 * Math.pow(v, 1.4)
        : 0.78 - 0.30 * highlight + 0.18 * Math.sin(u * 0.25);

      // Taper handle lines off into vignette at far left (u > 155)
      if (u > 155) {
        tone *= Math.max(0, 1.0 - (u - 155) / 38);
      }
      pts.push({ x: pos.x, y: pos.y, tone: constrain(tone, 0, 0.95) });
    }
    drawSwellingBurinPath(pts, 0.28);
  }

  // Longitudinal wood-grain / horn-grain burin lines along the dark handle (s in [-185, -36])
  for (let v = 0.06; v <= 0.95; v += 0.045) {
    let pts = [];
    for (let s = -36; s >= -185; s -= 5) {
      let u = -s;
      let topT = -spineThicknessAt(0) + 4 * Math.sin(constrain(u / 35, 0, 1) * Math.PI);
      let botT = 68 - 22 * Math.exp(-Math.pow((u - 26) / 18, 2)) + 8 * (u / 190);
      let t = lerp(topT, botT, v);
      let pos = fromBladeLocal(s, t);
      let fade = u > 150 ? Math.max(0, 1.0 - (u - 150) / 36) : 1.0;
      let highlight = Math.exp(-Math.pow((v - 0.26) / 0.12, 2));
      let tone = (0.68 - 0.42 * highlight + 0.22 * v) * fade;
      pts.push({ x: pos.x, y: pos.y, tone: constrain(tone, 0, 0.92) });
    }
    drawSwellingBurinPath(pts, 0.2);
  }

  // Two flush metal rivets on the handle at s = -78 and s = -138
  const rivets = [-78, -136];
  for (let rs of rivets) {
    let rPos = fromBladeLocal(rs, 26);
    for (let ring = 2.2; ring <= 6.8; ring += 1.6) {
      let rPts = [];
      for (let a = 0; a <= TWO_PI + 0.2; a += 0.35) {
        let rx = rPos.x + Math.cos(a) * ring;
        let ry = rPos.y + Math.sin(a) * ring * 0.85;
        let rt = 0.35 + 0.45 * Math.sin(a + 0.8);
        rPts.push({ x: rx, y: ry, tone: constrain(rt, 0.05, 0.9) });
      }
      drawSwellingBurinPath(rPts, 0.35);
    }
  }
}

// ============================================================================
// 5. THE HALVED LEMON: PITTED RIND IN DOT-AND-LOZENGE STIPPLE + CROSSHATCH
// ============================================================================

function getRindTone(s, theta, x, y) {
  // 3D normal lighting on the lemon dome under crisp frontal-upper-left light
  // theta = -1.35 rad faces the light; theta = +0.75 rad turns into deep core shadow;
  // theta = +1.35 rad (bottom underside) catches cool reflected light off the steel knife blade
  let angDiff = Math.atan2(Math.sin(theta + 1.32), Math.cos(theta + 1.32));
  let directLight = Math.pow(constrain(Math.cos(angDiff * 0.78), 0, 1), 1.35);

  // Specular dome highlight around s in [0.22, 0.58], theta around -1.25
  let dSpec = Math.hypot((s - 0.38) / 0.26, angDiff / 0.42);
  let specGlow = dSpec < 1.0 ? 0.24 * Math.pow(1.0 - dSpec, 1.6) : 0;

  // Core shadow band along the lower-right turn of form (theta ~ 0.55 .. 1.15)
  let coreDiff = Math.atan2(Math.sin(theta - 0.78), Math.cos(theta - 0.78));
  let coreShadow = Math.exp(-Math.pow(coreDiff / 0.52, 2)) * 0.46;

  // Reflected steel light along the bottom edge (theta > 1.05)
  let reflDiff = Math.atan2(Math.sin(theta - 1.38), Math.cos(theta - 1.38));
  let bladeRefl = Math.exp(-Math.pow(reflDiff / 0.32, 2)) * 0.22;

  // Collar fold & mamilla (nipple) sculptural modeling around s = 0.80 .. 0.98
  let collarShade = 0.22 * Math.exp(-Math.pow((s - 0.81) / 0.055, 2));
  let nippleTipShade = s > 0.91 ? 0.28 * ((s - 0.91) / 0.09) : 0;

  let baseTone = (1.0 - directLight) * 0.62 - specGlow + coreShadow - bladeRefl + collarShade + nippleTipShade;

  // Modulate by nearby concave oil-gland dimples (pits)
  let pitMod = 0;
  for (let i = 0; i < rindPits.length; i++) {
    let p = rindPits[i];
    if (Math.abs(s - p.s) > 0.045) continue;
    let dTh = Math.atan2(Math.sin(theta - p.theta), Math.cos(theta - p.theta));
    if (Math.abs(dTh) > 0.12) continue;
    let ds = (s - p.s) / 0.024;
    let dt = dTh / 0.055;
    let d2 = ds * ds + dt * dt;
    if (d2 < 1.0) {
      // Concave pit: upper-left inside wall is shaded (+tone), lower-right rim catches crisp light (-tone)
      let rimDir = -0.65 * ds + 0.75 * dt;
      pitMod += (1.0 - d2) * p.depth * (0.22 - 0.34 * rimDir);
    }
  }

  return constrain(baseTone + pitMod, 0.02, 0.96);
}

function drawLemonRind() {
  // 1. Geodesic rows of Dot-and-Lozenge Stipple across all visible rings of the lemon dome
  for (let rIdx = 1; rIdx < domeRings.length; rIdx++) {
    let ring = domeRings[rIdx];
    let s = ring.s;
    let circumference = Math.PI * (ring.rx + ring.ry);
    let nSteps = Math.max(24, Math.floor(circumference / 5.4));

    // Stagger odd/even rings by half a step to create authentic diamond/lozenge brickwork
    let phaseShift = (rIdx % 2 === 1) ? (TWO_PI / nSteps) * 0.5 : 0;

    for (let j = 0; j < nSteps; j++) {
      let theta = -Math.PI + (j / nSteps) * TWO_PI + phaseShift;
      let mod = cutRimMod(theta);
      let u = ring.rx * mod * Math.cos(theta);
      let v = ring.ry * mod * Math.sin(theta);

      let c = Math.cos(ring.rot), sn = Math.sin(ring.rot);
      let x = ring.cx + u * c - v * sn;
      let y = ring.cy + u * sn + v * c;

      if (!isRindPointVisible(x, y, rIdx)) continue;

      let tone = getRindTone(s, theta, x, y);
      if (tone < 0.06) continue;

      // Tangent direction along the ring for the lozenge dash
      let tx = -ring.rx * Math.sin(theta) * c - ring.ry * Math.cos(theta) * sn;
      let ty = -ring.rx * Math.sin(theta) * sn + ring.ry * Math.cos(theta) * c;
      let tLen = Math.hypot(tx, ty) || 1;
      tx /= tLen;
      ty /= tLen;

      // 1a. Draw the diamond-lozenge dash (swollen in the center, tapered at ends)
      let lozHalfLen = map(constrain(tone, 0.06, 0.9), 0.06, 0.9, 0.7, 2.55);
      let wt = map(constrain(tone, 0.06, 0.9), 0.06, 0.9, 0.36, 1.15);
      let col = tone > 0.58 ? PALETTE.inkDeep : (tone > 0.30 ? PALETTE.inkDark : PALETTE.inkMid);

      brush.set("burin_lozenge", col, wt);
      brush.line(x - tx * lozHalfLen, y - ty * lozHalfLen, x + tx * lozHalfLen, y + ty * lozHalfLen);

      // 1b. "Dot-and-lozenge": place a fine burin stipple dot in the interstice between lozenges
      if (tone > 0.14) {
        let thetaDot = theta + (TWO_PI / nSteps) * 0.5;
        let uD = ring.rx * mod * Math.cos(thetaDot);
        let vD = ring.ry * mod * Math.sin(thetaDot);
        let xD = ring.cx + uD * c - vD * sn;
        let yD = ring.cy + uD * sn + vD * c;
        if (isRindPointVisible(xD, yD, rIdx)) {
          let dotWt = map(constrain(tone, 0.14, 0.9), 0.14, 0.9, 0.32, 0.85);
          brush.set("burin_hair", col, dotWt);
          brush.line(xD - ty * 0.45, yD + tx * 0.45, xD + ty * 0.45, yD - tx * 0.45);
        }
      }
    }
  }

  // 2. Concave Oil-Gland Pit Micro-Crescents (giving hyperrealistic pitted citrus peel texture)
  for (let i = 0; i < rindPits.length; i++) {
    let p = rindPits[i];
    let rIdx = constrain(Math.round(p.s * (domeRings.length - 1)), 1, domeRings.length - 1);
    let ring = domeRings[rIdx];
    let mod = cutRimMod(p.theta);
    let u = ring.rx * mod * Math.cos(p.theta);
    let v = ring.ry * mod * Math.sin(p.theta);
    let c = Math.cos(ring.rot), sn = Math.sin(ring.rot);
    let px = ring.cx + u * c - v * sn;
    let py = ring.cy + u * sn + v * c;

    if (!isRindPointVisible(px, py, rIdx)) continue;

    let baseTone = getRindTone(p.s, p.theta, px, py);
    let rPit = p.rad * (0.55 + 0.45 * ring.prof);
    if (rPit < 1.1) continue;

    // Shaded upper-left inner crescent of the dimple
    let arcPts = [];
    for (let a = 1.65; a <= 4.35; a += 0.45) {
      let ax = px + Math.cos(a) * rPit * 0.85;
      let ay = py + Math.sin(a) * rPit * 0.72;
      arcPts.push({ x: ax, y: ay, tone: constrain(baseTone + 0.28, 0.18, 0.92) });
    }
    drawRunPoints(arcPts, "burin_swell", PALETTE.inkDark, 0.55 + baseTone * 0.45, 0.4, true);

    // Center stipple dot inside the oil gland
    if (baseTone > 0.12) {
      brush.set("burin_lozenge", PALETTE.inkDark, 0.48 + baseTone * 0.4);
      brush.line(px - 0.5, py - 0.4, px + 0.5, py + 0.4);
    }
  }

  // 3. Longitudinal & Oblique Form-Shadow Crosshatching across the lower-right rind & mamilla
  // Carves the heavy 3D turn of the lemon half & the neck of the nipple
  const N_LONG = 96;
  for (let k = 0; k < N_LONG; k++) {
    let theta0 = -0.35 + (k / N_LONG) * 2.15; // Sweeps through the shadow side & underside
    let pts = [];
    for (let rIdx = 1; rIdx < domeRings.length; rIdx += 2) {
      let ring = domeRings[rIdx];
      // Slight spiral twist for lozenge crosshatch over the latitude rows
      let theta = theta0 + ring.s * 0.28;
      let mod = cutRimMod(theta);
      let u = ring.rx * mod * Math.cos(theta);
      let v = ring.ry * mod * Math.sin(theta);
      let c = Math.cos(ring.rot), sn = Math.sin(ring.rot);
      let x = ring.cx + u * c - v * sn;
      let y = ring.cy + u * sn + v * c;

      if (!isRindPointVisible(x, y, rIdx)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.3);
        pts = [];
        continue;
      }

      let rawTone = getRindTone(ring.s, theta, x, y);
      let shadowTone = rawTone > 0.34 ? (rawTone - 0.30) * 1.18 : 0;
      if (shadowTone > 0.05) {
        pts.push({ x, y, tone: constrain(shadowTone, 0, 0.92) });
      } else {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.3);
        pts = [];
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.3);
  }

  // Secondary counter-spiral crosshatch in the deepest core shadow of the rind
  for (let k = 0; k < 64; k++) {
    let theta0 = 0.05 + (k / 64) * 1.45;
    let pts = [];
    for (let rIdx = 1; rIdx < domeRings.length; rIdx += 2) {
      let ring = domeRings[rIdx];
      let theta = theta0 - ring.s * 0.38;
      let mod = cutRimMod(theta);
      let u = ring.rx * mod * Math.cos(theta);
      let v = ring.ry * mod * Math.sin(theta);
      let c = Math.cos(ring.rot), sn = Math.sin(ring.rot);
      let x = ring.cx + u * c - v * sn;
      let y = ring.cy + u * sn + v * c;

      if (!isRindPointVisible(x, y, rIdx)) {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.3);
        pts = [];
        continue;
      }

      let rawTone = getRindTone(ring.s, theta, x, y);
      let shadowTone = rawTone > 0.52 ? (rawTone - 0.48) * 1.32 : 0;
      if (shadowTone > 0.05) {
        pts.push({ x, y, tone: constrain(shadowTone, 0, 0.94) });
      } else {
        if (pts.length >= 2) drawSwellingBurinPath(pts, 0.3);
        pts = [];
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.3);
  }

  // Crisp silhouette contour line along the outer horizon of the lemon dome & nipple
  drawRindSilhouetteContour();
}

function drawRindSilhouetteContour() {
  for (let side of [-1, 1]) {
    let pts = [];
    for (let rIdx = 1; rIdx < domeRings.length; rIdx++) {
      let ring = domeRings[rIdx];
      // Horizon angles where the dome silhouettes against the background (~ -1.82 and +1.28)
      let theta = side < 0 ? -1.82 + 0.22 * ring.s : 1.28 - 0.18 * ring.s;
      let mod = cutRimMod(theta);
      let u = ring.rx * mod * Math.cos(theta);
      let v = ring.ry * mod * Math.sin(theta);
      let c = Math.cos(ring.rot), sn = Math.sin(ring.rot);
      let x = ring.cx + u * c - v * sn;
      let y = ring.cy + u * sn + v * c;
      if (isRindPointVisible(x, y, rIdx)) {
        let tone = side < 0 ? 0.22 + 0.25 * ring.s : 0.72;
        pts.push({ x, y, tone });
      }
    }
    if (pts.length >= 2) drawSwellingBurinPath(pts, 0.35);
  }
}

// ============================================================================
// 6. THE HALVED LEMON: CUT FACE (PITH, COLUMELLA, SEPTA, 10 SEGMENTS & SACS)
// ============================================================================

// Inner boundary of the white pith (albedo), scalloping inward at each of the 10 septa
function pithInnerRadiusAt(theta) {
  let minSepDist = Math.PI;
  for (let k = 0; k <= 10; k++) {
    let d = Math.abs(Math.atan2(Math.sin(theta - sepAngles[k]), Math.cos(theta - sepAngles[k])));
    if (d < minSepDist) minSepDist = d;
  }
  // Scallops inward to r=0.735 at each septum attachment, arches out to r=0.835 over segment middle
  let scallop = 0.105 * Math.exp(-Math.pow(minSepDist / 0.085, 1.6));
  let organic = 0.012 * Math.sin(3 * theta + 0.5) - 0.008 * Math.cos(5 * theta);
  return 0.838 - scallop + organic;
}

// Outer star-shaped boundary of the central spongy core (columella)
function coreRadiusAt(theta) {
  let minSepDist = Math.PI;
  for (let k = 0; k <= 10; k++) {
    let d = Math.abs(Math.atan2(Math.sin(theta - sepAngles[k]), Math.cos(theta - sepAngles[k])));
    if (d < minSepDist) minSepDist = d;
  }
  let starPoint = 0.042 * Math.exp(-Math.pow(minSepDist / 0.12, 1.5));
  return 0.128 + starPoint + 0.008 * Math.cos(2 * theta - 0.3);
}

function drawLemonCutFace() {
  // A. Outer Flavedo Bevel & Scalloped White Pith (Albedo) modeled with swelling parallel rings
  const N_PITH_RINGS = 24;
  for (let i = 0; i <= N_PITH_RINGS; i++) {
    let frac = i / N_PITH_RINGS; // 0 = inner segment boundary, 1 = outer cut rim (r=1.0)
    let pts = [];
    const STEPS = 220;

    for (let s = 0; s <= STEPS; s++) {
      let theta = -Math.PI + (s / STEPS) * TWO_PI;
      let rIn = pithInnerRadiusAt(theta);
      let rOut = 0.996;
      let rNorm = lerp(rIn, rOut, frac);

      let mod = cutRimMod(theta);
      let u = L_RX * mod * rNorm * Math.cos(theta);
      let v = L_RY * mod * rNorm * Math.sin(theta);
      let pos = fromLemonLocal(u, v);

      // Lighting across the pillowed cross-section of the pith:
      // Crisp frontal light makes the middle of the pith ring (frac ~ 0.45..0.68) very bright,
      // while the outer flavedo bevel (frac > 0.84) and inner wet pulp rim (frac < 0.18) swell in tone,
      // and the lower-right side of the cut face (theta in [0.1, 1.6]) shades softly.
      let shadowSide = Math.pow(constrain(0.5 + 0.5 * Math.sin(theta - 0.35), 0, 1), 1.6) * 0.28;
      let outerBevel = frac > 0.80 ? Math.pow((frac - 0.80) / 0.20, 1.3) * 0.58 : 0;
      let innerCleft = frac < 0.22 ? Math.pow((0.22 - frac) / 0.22, 1.4) * 0.52 : 0;
      let pillowHighlight = Math.exp(-Math.pow((frac - 0.54) / 0.22, 2)) * 0.16;

      // Subtle fibrous grain undulation in the albedo
      let fiber = 0.04 * Math.sin(theta * 36 + i * 0.9);

      let tone = constrain(0.06 + shadowSide + outerBevel + innerCleft - pillowHighlight + fiber, 0.02, 0.92);
      pts.push({ x: pos.x, y: pos.y, tone });
    }
    drawSwellingBurinPath(pts, 0.3);
  }

  // Fine radial pith cross-fibers near the outer flavedo bevel and lower shadow rim
  for (let s = 0; s < 180; s++) {
    let theta = -Math.PI + (s / 180) * TWO_PI;
    let rIn = pithInnerRadiusAt(theta);
    let mod = cutRimMod(theta);
    let p1 = fromLemonLocal(L_RX * mod * (rIn + 0.01) * Math.cos(theta), L_RY * mod * (rIn + 0.01) * Math.sin(theta));
    let p2 = fromLemonLocal(L_RX * mod * 0.995 * Math.cos(theta), L_RY * mod * 0.995 * Math.sin(theta));
    let pMid = fromLemonLocal(L_RX * mod * 0.92 * Math.cos(theta), L_RY * mod * 0.92 * Math.sin(theta));

    let sideShade = Math.pow(constrain(0.5 + 0.5 * Math.sin(theta - 0.35), 0, 1), 1.5);
    drawSwellingBurinPath([
      { x: p1.x, y: p1.y, tone: 0.28 + 0.25 * sideShade },
      { x: pMid.x, y: pMid.y, tone: 0.03 + 0.18 * sideShade },
      { x: p2.x, y: p2.y, tone: 0.52 + 0.28 * sideShade }
    ], 0.15);
  }

  // B. The 10 Radial Septa (Membranes separating the pulp segments)
  // Modeled by 5 parallel radial lines per septum that flare at the pith and columella
  for (let k = 0; k < 10; k++) {
    let thetaSep = sepAngles[k];
    for (let lane = -2; lane <= 2; lane++) {
      let pts = [];
      for (let r = 0.11; r <= 0.84; r += 0.025) {
        // Flare at inner core (r < 0.20) and outer pith attachment (r > 0.68)
        let flare = 1.0
          + 1.6 * Math.exp(-Math.pow((r - 0.11) / 0.06, 2))
          + 2.1 * Math.exp(-Math.pow((r - 0.82) / 0.08, 2));
        let angOffset = (lane * 0.0055 * flare) / Math.max(0.22, r);
        let th = thetaSep + angOffset;
        let mod = cutRimMod(th);
        let pos = fromLemonLocal(L_RX * mod * r * Math.cos(th), L_RY * mod * r * Math.sin(th));

        // Outer lanes (|lane| == 2) form the dark tucked edge where moist pulp meets the white septum;
        // Center lanes (lane == 0) catch the crisp frontal highlight!
        let edgeFactor = Math.abs(lane) === 2 ? 0.48 : (Math.abs(lane) === 1 ? 0.18 : 0.05);
        let sideShade = 0.16 * (0.5 + 0.5 * Math.sin(thetaSep - 0.3));
        let tone = constrain(edgeFactor + sideShade * (Math.abs(lane) / 2), 0.03, 0.88);
        pts.push({ x: pos.x, y: pos.y, tone });
      }
      drawSwellingBurinPath(pts, 0.25);
    }
  }

  // C. The Central Spongy Core (Columella) & Central Vascular Dimple
  for (let i = 1; i <= 11; i++) {
    let frac = i / 11;
    let pts = [];
    for (let s = 0; s <= 90; s++) {
      let theta = -Math.PI + (s / 90) * TWO_PI;
      let rCore = coreRadiusAt(theta) * frac;
      let mod = cutRimMod(theta);
      // Slight organic offset (-3, +2) for natural asymmetry
      let u = -3 + L_RX * mod * rCore * Math.cos(theta);
      let v = 2 + L_RY * mod * rCore * Math.sin(theta);
      let pos = fromLemonLocal(u, v);

      // Deep central hollow at frac < 0.36; bright spongy ring at frac in [0.48, 0.78]; dark crease at frac > 0.88
      let hollow = frac < 0.38 ? (0.38 - frac) * 1.95 : 0;
      let outerRim = frac > 0.84 ? (frac - 0.84) * 2.4 : 0;
      let directional = 0.18 * (0.5 + 0.5 * Math.cos(theta + 2.2));
      let tone = constrain(0.05 + hollow + outerRim + directional, 0.03, 0.92);
      pts.push({ x: pos.x, y: pos.y, tone });
    }
    drawSwellingBurinPath(pts, 0.35);
  }

  // D. The 10 Pulp Segments & Every Glistening Juice Sac (Vesicle) + 2 Embedded Seeds
  drawPulpSegmentsAndJuiceSacs();
}

function drawPulpSegmentsAndJuiceSacs() {
  // First: Dark recessed segment bed cross-hatching in the deep corners of each locule
  // so the bright curved juice sacs pop forward in 3D relief
  for (let k = 0; k < 10; k++) {
    let a0 = sepAngles[k] + 0.025;
    let a1 = sepAngles[k + 1] - 0.025;
    for (let r = 0.165; r <= 0.815; r += 0.018) {
      let pts = [];
      let steps = 22;
      for (let j = 0; j <= steps; j++) {
        let u = j / steps;
        let th = lerp(a0, a1, u);
        let rIn = coreRadiusAt(th) + 0.018;
        let rOut = pithInnerRadiusAt(th) - 0.012;
        if (r < rIn || r > rOut) continue;

        let mod = cutRimMod(th);
        let pos = fromLemonLocal(L_RX * mod * r * Math.cos(th), L_RY * mod * r * Math.sin(th));

        // Tucked shadow right under the outer pith wall, inner core, and septum walls
        let dSeptum = Math.min(u, 1.0 - u);
        let dRadial = Math.min((r - rIn) / 0.12, (rOut - r) / 0.12);
        let borderShade = Math.max(
          dSeptum < 0.18 ? (0.18 - dSeptum) * 3.2 : 0,
          dRadial < 1.0 ? (1.0 - dRadial) * 0.58 : 0
        );
        let tone = constrain(0.18 + borderShade, 0.12, 0.88);
        pts.push({ x: pos.x, y: pos.y, tone });
      }
      if (pts.length >= 2) drawSwellingBurinPath(pts, 0.25);
    }
  }

  // Mark two special vesicles as embedded seeds in the cut face:
  // 1) Segment 5, tier 0 -> Whole plump seed exposed in the pulp
  // 2) Segment 1, tier 0 -> Sliced-in-half seed showing pale cotyledon interior
  let wholeSeedVes = null;
  let slicedSeedVes = null;

  for (let v of vesicles) {
    if (v.seg === 5 && v.tier === 0 && !wholeSeedVes) {
      v.seedType = 1;
      wholeSeedVes = v;
    } else if (v.seg === 1 && v.tier === 0 && !slicedSeedVes) {
      v.seedType = 2;
      slicedSeedVes = v;
    }
  }

  // Render every individual glistening juice sac with swelling & tapering parallel lines
  for (let idx = 0; idx < vesicles.length; idx++) {
    let sac = vesicles[idx];
    if (sac.seedType === 1) {
      drawEmbeddedCutFaceSeed(sac, false);
    } else if (sac.seedType === 2) {
      drawEmbeddedCutFaceSeed(sac, true);
    } else {
      drawSingleJuiceSac(sac);
    }
  }
}

function drawSingleJuiceSac(sac) {
  // Each juice vesicle is a plump teardrop/fusiform sac in (r, theta) space.
  // We engrave 9 curved parallel lines across the sac that:
  // - Part / taper to zero inside the crisp frontal specular highlight window
  // - Swell boldly through the dark refractive translucent belly immediately around the highlight
  // - Taper slightly across the lower-right caustic glow before a crisp membrane crease!

  const N_LINES = 9;
  const STEPS = 14;

  for (let i = 0; i < N_LINES; i++) {
    let vNorm = -0.92 + (i / (N_LINES - 1)) * 1.84; // Transverse across the sac (-1 to +1)
    let maxU = Math.sqrt(Math.max(0.04, 1.0 - vNorm * vNorm * 0.92));

    let pts = [];
    for (let j = 0; j <= STEPS; j++) {
      let uNorm = lerp(-maxU, maxU, j / STEPS); // Longitudinal along the sac (-maxU to +maxU)

      // Teardrop asymmetry: slightly narrower toward inner core (uNorm < 0), plumper toward outer pith
      let tearMod = 1.0 + 0.22 * uNorm - 0.12 * uNorm * uNorm;
      let vCurved = vNorm * tearMod;

      // Apply herringbone tilt & 3D cross-contour arch over the plump belly of the sac
      let bellyArch = 0.14 * (1.0 - uNorm * uNorm) * (1.0 - vNorm * vNorm);
      let dr = (uNorm * sac.rHalf) + (vCurved * sac.rHalf * sac.tilt);
      let dTh = (vCurved * sac.tHalf) - ((uNorm - bellyArch) * sac.tHalf * sac.tilt);

      let r = sac.rC + dr;
      let th = sac.thetaC + dTh;

      // Clamp gracefully to segment cavity boundaries
      let rIn = coreRadiusAt(th) + 0.015;
      let rOut = pithInnerRadiusAt(th) - 0.010;
      r = constrain(r, rIn, rOut);

      let mod = cutRimMod(th);
      let pos = fromLemonLocal(L_RX * mod * r * Math.cos(th), L_RY * mod * r * Math.sin(th));

      // Compute refractive optics inside this glistening juice sac:
      // 1. Distance to the sac's crisp frontal specular highlight window
      let dsSpec = (uNorm - sac.specS) / 0.42;
      let dtSpec = (vNorm - sac.specT) / 0.38;
      let dSpec = Math.hypot(dsSpec, dtSpec);

      let tone;
      if (dSpec < 0.78) {
        // Pure gleaming cream-paper specular highlight window!
        tone = 0.01;
      } else if (dSpec < 1.38) {
        // Dark refractive halo immediately framing the wet specular highlight (swells boldly!)
        let halo = Math.sin(((dSpec - 0.78) / 0.60) * Math.PI);
        tone = 0.56 + 0.36 * halo;
      } else {
        // Translucent juicy belly + luminous secondary caustic crescent on lower-right (uNorm > 0.2, vNorm > 0.2)
        let dCaustic = Math.hypot((uNorm - 0.38) / 0.45, (vNorm - 0.38) / 0.45);
        let causticGlow = dCaustic < 1.0 ? 0.34 * (1.0 - dCaustic) : 0;
        let edgeCrease = Math.pow(Math.hypot(uNorm, vNorm), 2.2) * 0.38;
        tone = 0.48 - causticGlow + edgeCrease;
      }

      // Global cut-face shading (slightly deeper on lower-right segments & tucked under pith)
      let segShade = 0.14 * (0.5 + 0.5 * Math.sin(sac.thetaC - 0.35));
      let pithShadow = r > rOut - 0.06 ? 0.22 * (1.0 - (rOut - r) / 0.06) : 0;

      pts.push({
        x: pos.x,
        y: pos.y,
        tone: dSpec < 0.78 ? 0.01 : constrain(tone + segShade + pithShadow, 0.03, 0.95)
      });
    }
    drawSwellingBurinPath(pts, 0.35);
  }

  // Crisp tucked membrane crease around the perimeter of the juice sac
  let rimPts = [];
  for (let a = 0; a <= TWO_PI + 0.2; a += 0.32) {
    let uNorm = Math.cos(a);
    let vNorm = Math.sin(a) * (1.0 + 0.22 * uNorm);
    let r = constrain(sac.rC + uNorm * sac.rHalf, coreRadiusAt(sac.thetaC) + 0.015, pithInnerRadiusAt(sac.thetaC) - 0.010);
    let th = sac.thetaC + vNorm * sac.tHalf;
    let mod = cutRimMod(th);
    let pos = fromLemonLocal(L_RX * mod * r * Math.cos(th), L_RY * mod * r * Math.sin(th));
    // Leave tiny highlight breaks on the upper-left rim of the sac
    let rimLight = Math.cos(a + 2.2);
    let tone = rimLight > 0.65 ? 0.08 : 0.58 + 0.25 * Math.max(0, -rimLight);
    rimPts.push({ x: pos.x, y: pos.y, tone });
  }
  drawSwellingBurinPath(rimPts, 0.35);
}

function drawEmbeddedCutFaceSeed(sac, isSliced) {
  // Renders a seed nestled inside the lemon pulp at (sac.rC, sac.thetaC)
  let mod = cutRimMod(sac.thetaC);
  let cLocal = {
    u: L_RX * mod * sac.rC * Math.cos(sac.thetaC),
    v: L_RY * mod * sac.rC * Math.sin(sac.thetaC)
  };
  let center = fromLemonLocal(cLocal.u, cLocal.v);
  let ang = sac.thetaC + L_ROT;
  let rx = 18.5, ry = 9.5;

  // Dark recessed pocket around the seed in the pulp
  for (let ring = 1.05; ring <= 1.28; ring += 0.11) {
    let pocketPts = [];
    for (let a = 0; a <= TWO_PI + 0.2; a += 0.3) {
      let u = Math.cos(a) * rx * ring;
      let v = Math.sin(a) * ry * ring * (1.0 - 0.22 * Math.cos(a));
      let px = center.x + u * Math.cos(ang) - v * Math.sin(ang);
      let py = center.y + u * Math.sin(ang) + v * Math.cos(ang);
      pocketPts.push({ x: px, y: py, tone: 0.78 });
    }
    drawSwellingBurinPath(pocketPts, 0.35);
  }

  // Longitudinal seed lines
  for (let i = -6; i <= 6; i++) {
    let vFrac = i / 6;
    let maxU = Math.sqrt(Math.max(0.05, 1.0 - vFrac * vFrac));
    let pts = [];
    for (let s = 0; s <= 12; s++) {
      let uFrac = lerp(-maxU, maxU, s / 12);
      let u = uFrac * rx;
      let v = vFrac * ry * (1.0 - 0.24 * uFrac) * Math.sqrt(Math.max(0, 1.0 - uFrac * uFrac * 0.5));
      let px = center.x + u * Math.cos(ang) - v * Math.sin(ang);
      let py = center.y + u * Math.sin(ang) + v * Math.cos(ang);

      let tone;
      if (isSliced) {
        // Sliced seed: dark outer seed coat (|vFrac| > 0.78) framing a pale flat cotyledon interior with central cleft
        let isCoat = Math.abs(vFrac) > 0.76 || Math.abs(uFrac) > 0.84;
        let isCleft = Math.abs(vFrac) < 0.08 && Math.abs(uFrac) < 0.65;
        tone = isCoat ? 0.68 : (isCleft ? 0.42 : 0.07 + 0.08 * uFrac);
      } else {
        // Whole plump wet seed: bright specular ridge at vFrac ~ -0.35, swelling dark turn at vFrac > 0.2
        let dSpec = Math.hypot((uFrac + 0.1) / 0.55, (vFrac + 0.35) / 0.28);
        tone = dSpec < 0.85 ? 0.02 : constrain(0.32 + 0.48 * (vFrac + 0.3) + 0.15 * Math.sin(i * 1.4), 0.06, 0.88);
      }
      pts.push({ x: px, y: py, tone });
    }
    drawSwellingBurinPath(pts, 0.3);
  }
}

// ============================================================================
// 7. FOREGROUND FOCAL INCIDENTS: SEED CAUGHT ON EDGE & DROP ABOUT TO FALL
// ============================================================================

function drawCaughtSeed() {
  // 1. Cast shadow & wet meniscus ring of the seed on the carbon-steel cutting edge
  for (let ring = 1.04; ring <= 1.42; ring += 0.09) {
    let shPts = [];
    for (let a = -0.3; a <= Math.PI + 0.6; a += 0.22) {
      let uNorm = Math.cos(a);
      let vBase = seedHalfWidthAt(uNorm);
      let u = uNorm * SEED_RX * ring + (ring - 1.0) * 6.5;
      let v = Math.sin(a) * vBase * ring + (ring - 1.0) * 8.5;
      let pos = fromSeedLocal(u, v);
      let tone = ring < 1.15 ? 0.88 : 0.62 * (1.48 - ring) / 0.35;
      shPts.push({ x: pos.x, y: pos.y, tone: constrain(tone, 0.1, 0.92) });
    }
    drawSwellingBurinPath(shPts, 0.35);
  }

  // Wet meniscus highlight wire hugging the upper-left contact of the seed
  let menPts = [];
  for (let a = Math.PI + 0.3; a <= TWO_PI - 0.2; a += 0.22) {
    let uNorm = Math.cos(a);
    let vBase = seedHalfWidthAt(uNorm);
    let pos = fromSeedLocal(uNorm * SEED_RX * 1.14, Math.sin(a) * vBase * 1.18);
    menPts.push({ x: pos.x, y: pos.y, tone: 0.45 + 0.25 * Math.sin(a * 3) });
  }
  drawSwellingBurinPath(menPts, 0.35);

  // 2. Longitudinal swelling & tapering burin lines across the plump 3D seed body
  const N_SEED_LINES = 15;
  for (let i = 0; i < N_SEED_LINES; i++) {
    let vFrac = -0.96 + (i / (N_SEED_LINES - 1)) * 1.92;
    let pts = [];
    for (let s = 0; s <= 18; s++) {
      let uNorm = -0.98 + (s / 18) * 1.96;
      let hw = seedHalfWidthAt(uNorm);
      if (hw < 0.4) continue;

      // 3D convexity arch across the seed
      let v = vFrac * hw;
      let archShift = -1.6 * (1.0 - vFrac * vFrac) * (1.0 - uNorm * uNorm);
      let pos = fromSeedLocal(uNorm * SEED_RX, v + archShift);

      // Crisp frontal wet highlight along vFrac in [-0.52, -0.18], uNorm in [-0.55, 0.35]
      let dSpec = Math.hypot((uNorm + 0.10) / 0.48, (vFrac + 0.36) / 0.24);
      let tone;
      if (dSpec < 0.85) {
        tone = 0.01; // Gleaming wet paper highlight
      } else {
        // Swells across the lower shaded turn of form (vFrac in [0.15, 0.78]),
        // then tapers slightly at the very bottom edge (vFrac > 0.82) for steel reflected light!
        let formTurn = Math.exp(-Math.pow((vFrac - 0.46) / 0.36, 2)) * 0.68;
        let ridge = 0.08 * Math.cos(i * 1.8); // Characteristic longitudinal citrus seed ridges
        let tipShade = uNorm > 0.55 ? (uNorm - 0.55) * 0.55 : 0;
        tone = 0.16 + formTurn + ridge + tipShade;
      }
      pts.push({ x: pos.x, y: pos.y, tone: dSpec < 0.85 ? 0.01 : constrain(tone, 0.04, 0.94) });
    }
    drawSwellingBurinPath(pts, 0.3);
  }

  // Transverse cross-contour shadow lines on the shaded lower belly of the caught seed
  for (let uNorm = -0.75; uNorm <= 0.78; uNorm += 0.14) {
    let hw = seedHalfWidthAt(uNorm);
    let pts = [];
    for (let vFrac = 0.05; vFrac <= 0.96; vFrac += 0.15) {
      let pos = fromSeedLocal(uNorm * SEED_RX, vFrac * hw);
      let tone = 0.42 * Math.sin(((vFrac - 0.05) / 0.91) * Math.PI);
      pts.push({ x: pos.x, y: pos.y, tone });
    }
    drawSwellingBurinPath(pts, 0.3);
  }

  // Crisp outer contour of the caught seed
  let seedContour = [];
  for (let a = 0; a <= TWO_PI + 0.15; a += 0.2) {
    let uNorm = Math.cos(a);
    let hw = seedHalfWidthAt(uNorm);
    let pos = fromSeedLocal(uNorm * SEED_RX, Math.sin(a) * hw);
    let isLitEdge = a > 3.5 && a < 5.6;
    seedContour.push({ x: pos.x, y: pos.y, tone: isLitEdge ? 0.18 : 0.82 });
  }
  drawSwellingBurinPath(seedContour, 0.35);
}

function drawHangingDrop() {
  // Refractive optics of a transparent pendant drop about to fall:
  // - Dark upper meniscus & capillary neck (refracting the dark underside of the steel blade)
  // - Brilliant frontal specular window on the upper-left belly (pure untouched cream paper)
  // - Rich dark refractive core in the upper-center & left flank
  // - Luminous secondary caustic crescent along the lower-right belly
  // - Crisp dark outer refractive rim

  function getDropRefractiveTone(uNorm, tNorm) {
    // uNorm in [-1, 1] horizontally across drop; tNorm in [0, 1] vertically from blade edge to bottom tip
    // 1. Primary frontal specular window at tNorm in [0.46, 0.70], uNorm in [-0.62, -0.14]
    let dSpec1 = Math.hypot((uNorm + 0.38) / 0.26, (tNorm - 0.57) / 0.13);
    if (dSpec1 < 0.92) return 0.01;

    // Tiny secondary pin-point glint in the capillary neck (tNorm ~ 0.22, uNorm ~ -0.35)
    let dSpec2 = Math.hypot((uNorm + 0.34) / 0.18, (tNorm - 0.22) / 0.06);
    if (dSpec2 < 0.88) return 0.01;

    // 2. Luminous lower-right caustic glow (focused light exiting the bottom-right of the lens-like drop)
    let dCaustic = Math.hypot((uNorm - 0.32) / 0.38, (tNorm - 0.78) / 0.15);
    let causticGlow = dCaustic < 1.0 ? 0.56 * Math.pow(1.0 - dCaustic, 1.4) : 0;

    // 3. Dark upper meniscus & neck refraction (tNorm < 0.38)
    let neckDark = tNorm < 0.42 ? 0.44 * (1.0 - tNorm / 0.42) : 0;

    // 4. Dark refractive core around the primary specular window & Fresnel rim darkening
    let dHalo = Math.hypot((uNorm + 0.15) / 0.55, (tNorm - 0.55) / 0.26);
    let coreDark = dHalo < 1.2 ? 0.38 * (1.0 - dHalo / 1.2) : 0;
    let fresnelRim = Math.pow(Math.abs(uNorm), 2.4) * 0.48 + (tNorm > 0.90 ? (tNorm - 0.90) * 4.5 : 0);

    return constrain(0.36 + neckDark + coreDark + fresnelRim - causticGlow, 0.03, 0.96);
  }

  // 1. Vertical meridian burin lines flowing from the blade meniscus through the taut neck into the drop
  const N_MERIDIANS = 17;
  for (let i = 0; i < N_MERIDIANS; i++) {
    let uNorm = -0.95 + (i / (N_MERIDIANS - 1)) * 1.90;
    let pts = [];
    for (let y = DROP_Y_TOP; y <= DROP_Y_BOT; y += 2.2) {
      let tNorm = (y - DROP_Y_TOP) / (DROP_Y_BOT - DROP_Y_TOP);
      let hw = dropHalfWidthAt(y);
      if (hw < 0.8) continue;
      let cx = dropCenterXAt(y);
      let x = cx + uNorm * hw;
      let tone = getDropRefractiveTone(uNorm, tNorm);
      pts.push({ x, y, tone });
    }
    drawSwellingBurinPath(pts, 0.3);
  }

  // 2. Horizontal / elliptical cross-contour latitude curves wrapping the 3D sphere of the drop
  for (let y = DROP_Y_TOP + 3; y <= DROP_Y_BOT - 2; y += 2.8) {
    let tNorm = (y - DROP_Y_TOP) / (DROP_Y_BOT - DROP_Y_TOP);
    let hw = dropHalfWidthAt(y);
    if (hw < 1.5) continue;
    let cx = dropCenterXAt(y);
    let pts = [];
    let steps = 16;
    for (let j = 0; j <= steps; j++) {
      let uNorm = -0.96 + (j / steps) * 1.92;
      let x = cx + uNorm * hw;
      // Spherical downward curvature of each latitude ring
      let yArch = y + hw * 0.28 * Math.sqrt(Math.max(0, 1.0 - uNorm * uNorm)) * (tNorm - 0.15);
      let tone = getDropRefractiveTone(uNorm, tNorm);
      // Latitude pass emphasizes mid-to-dark refractive zones while keeping the caustic & highlight clean
      let latTone = tone < 0.18 ? 0.01 : tone * 0.88;
      pts.push({ x, y: yArch, tone: latTone });
    }
    drawSwellingBurinPath(pts, 0.35);
  }

  // 3. Crisp outer refractive silhouette contour of the hanging drop
  for (let side of [-1, 1]) {
    let rimPts = [];
    for (let y = DROP_Y_TOP; y <= DROP_Y_BOT; y += 2.2) {
      let tNorm = (y - DROP_Y_TOP) / (DROP_Y_BOT - DROP_Y_TOP);
      let hw = dropHalfWidthAt(y);
      let cx = dropCenterXAt(y);
      let x = cx + side * hw;
      let tone = (side < 0 && tNorm > 0.42 && tNorm < 0.68) ? 0.28 : 0.85;
      rimPts.push({ x, y, tone });
    }
    drawSwellingBurinPath(rimPts, 0.35);
  }

  // 4. Tiny satellite micro-bead of lemon juice on the steel bevel just to the right of the drop (x=642, y=652)
  const bx = 642, by = 651, br = 3.8;
  for (let dy = -br; dy <= br; dy += 1.2) {
    let hw = Math.sqrt(Math.max(0, br * br - dy * dy));
    let uSpec = dy < 0 ? 0.02 : 0.72;
    drawSwellingBurinPath([
      { x: bx - hw, y: by + dy, tone: 0.65 },
      { x: bx, y: by + dy + 0.6, tone: uSpec },
      { x: bx + hw, y: by + dy, tone: 0.85 }
    ], 0.3);
  }
}

// ============================================================================
// 8. FINAL INTAGLIO ACCENTS & ENGRAVER'S MICRO-DETAILS
// ============================================================================

function drawFinalAccents() {
  // 1. Crisp cut-face rim accent line separating the cut lemon face from the domed rind & steel shadow
  let rimPts = [];
  for (let s = 0; s <= 240; s++) {
    let theta = -Math.PI + (s / 240) * TWO_PI;
    let mod = cutRimMod(theta);
    let pos = fromLemonLocal(L_RX * mod * Math.cos(theta), L_RY * mod * Math.sin(theta));
    // Hairline on upper-left lit rim, bold dark occlusion line along bottom rim resting on the knife
    let isBottomContact = theta > 0.25 && theta < 2.35;
    let isUpperLit = theta < -0.85 && theta > -2.55;
    let tone = isBottomContact ? 0.92 : (isUpperLit ? 0.14 : 0.54);
    rimPts.push({ x: pos.x, y: pos.y, tone });
  }
  drawSwellingBurinPath(rimPts, 0.3);

  // 2. Wet juice meniscus line where the bottom of the lemon rests on the flat of the carbon-steel blade
  let contactPts = [];
  for (let theta = 0.42; theta <= 2.18; theta += 0.03) {
    let mod = cutRimMod(theta);
    let pos = fromLemonLocal(L_RX * mod * 1.015 * Math.cos(theta), L_RY * mod * 1.02 * Math.sin(theta) + 2.2);
    if (!inCaughtSeed(pos.x, pos.y) && !inHangingDrop(pos.x, pos.y)) {
      let glint = Math.sin(theta * 18) > 0.55 ? 0.12 : 0.88;
      contactPts.push({ x: pos.x, y: pos.y, tone: glint });
    }
  }
  drawSwellingBurinPath(contactPts, 0.3);

  // 3. Faint banknote engraver's registration hairlines & plate number in the lower margin
  brush.set("guilloche", PALETTE.inkWhisper, 0.38);
  // Top and bottom center registration ticks inside plate mark
  brush.line(FCX - 14, 92, FCX + 14, 92);
  brush.line(FCX, 84, FCX, 100);
  brush.line(FCX - 14, 1108, FCX + 14, 1108);
  brush.line(FCX, 1100, FCX, 1116);
}
